pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: tiny unusable gaps are the worst outcome.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    } else if post_residual >= 10 && post_residual < 20 {
        score += 25.0;
    } else if post_residual == 0 {
        // Perfect fit: strong reward.
        score -= 80.0;
    } else {
        // Larger usable leftovers are mildly good, scaled by usefulness.
        score -= (post_residual as f64).ln() * 6.0;
    }

    // Reward bins whose leftover can still host the lookahead item (k=2).
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 12.0;
    } else if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        // Leftover too small for the next item: dead space risk.
        score += 10.0;
    }

    // Last-chance bin: strongly favor using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 30.0;
    }

    // Open-bin pressure: with many open bins, discourage spreading to new bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += (open_bins_count as f64).powf(1.3) * 0.5 * (1.0 - progress);

    // Prefer bins tighter than average (consolidation of residuals).
    score += (mean_residual - bin_residual as f64) * 0.4;

    // New-bin candidate: only attractive if item is huge and no good fit exists.
    if bin_residual == bin_capacity {
        if item_size >= 70 && fitting_bins_count == 0 {
            score -= 20.0;
        } else {
            score += 15.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals too small for any realistic item (1..=100)
    // are worthless; penalize small unusable gaps super-linearly.
    if post_residual > 0 {
        let dead = 100.0f64.min(post_residual as f64);
        // unusable gap: nothing smaller than ~post_residual can ever use it
        let unusable = (post_residual as f64) < 10.0; // min item size floor
        if unusable {
            score += (10.0 - post_residual as f64) * 40.0; // heavy penalty for near-full bins
        } else {
            // value of residual decays as it shrinks toward the smallest useful size
            let usefulness = ((post_residual as f64) - 10.0) / 90.0;
            score -= usefulness * 20.0;
            // quadratic dead-space term for mid-range gaps
            score += (1.0 - usefulness) * (1.0 - usefulness) * 15.0;
        }
        let _ = dead;
    }

    // Perfect fit bonus
    if post_residual == 0 {
        score -= 60.0;
    }

    // Lookahead coupling: if next item fits exactly in the post residual, reward strongly
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 50.0;
        } else if next_item_size < post_residual {
            // residual left after next item would fit too
            let r2 = post_residual - next_item_size;
            if r2 >= 1 {
                score -= 10.0 + (r2 as f64).sqrt() * 3.0;
            }
        } else {
            // next item won't fit here: slight penalty for blocking
            score += 5.0;
        }
    }

    // Last-chance bin: if this is the only bin that fits, strongly favor using it
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 35.0;
    }

    // Open-bin pressure: prefer spreading into fewer bins when many are open
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += (open_bins_count as f64).ln().max(0.0) * (8.0 + 10.0 * progress);

    // Mean residual coupling: when average residual is tight, reward conserving space (tight fits)
    if mean_residual > 0.0 {
        let tight = 1.0 - ((post_residual as f64) / mean_residual).min(2.0) / 2.0;
        score += (1.0 - tight) * 12.0;
    }

    // New-bin candidate: make empty bins attractive only when open bins are crowded
    if bin_residual == bin_capacity {
        let crowd = (open_bins_count as f64) * 3.0 + mean_residual * 0.15;
        score = 95.0 - crowd.min(70.0);
        if next_item_size > 0 && next_item_size >= bin_residual {
            score -= 10.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the resulting residual: classify dead space into
    // capacity-fraction buckets. Residuals in the "small" class (< 25% of
    // capacity) are nearly unusable dead space -> penalize heavily.
    let quarter = bin_capacity / 4;
    let half = bin_capacity / 2;
    let post = post_residual;

    if post == 0 {
        // Perfect fit: strongly reward.
        score -= 100.0;
    } else if post < quarter {
        // Dead-space class: residual too small for typical items.
        score += 30.0;
        // Extra penalty if the next item cannot use it anyway.
        if next_item_size > post {
            score += 20.0;
        }
    } else if post < half {
        // Middle class: usable but imperfect.
        score += 5.0;
    } else {
        // Large residual class: good leftover.
        score -= 10.0;
    }

    // Integer-division threshold: residual divisible into likely item classes
    // (multiples of 10 / 20 in classic streams) is more valuable.
    if post % 10 == 0 && post > 0 {
        score -= 8.0;
    }
    if post % 20 == 0 && post > 0 {
        score -= 4.0;
    }

    // Lookahead coupling: reward if the next item fits the post residual
    // snugly (harmonic pair), penalize if next item is much larger.
    if next_item_size > 0 {
        if next_item_size <= post {
            let slack = post - next_item_size;
            if slack < quarter {
                score -= 15.0; // chains nicely
            } else {
                score -= 3.0;
            }
        } else {
            score += 10.0; // next item won't fit here
        }
    }

    // Last-chance bonus: if this is the only fitting bin, avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 25.0;
    }

    // New-bin candidate: neutral-to-slightly-positive baseline so it is only
    // chosen when open bins have bad residual classes. Scale with mean residual.
    if bin_residual == bin_capacity {
        score += 5.0 + 0.3 * mean_residual;
        // Early in the stream, opening bins is cheaper (more future items to fill).
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 1.0 };
        score -= 20.0 * (1.0 - progress);
        if next_item_size > 0 && next_item_size <= bin_capacity {
            score -= 5.0;
        }
    }

    // Mild penalty for accumulating many open bins with poor mean residual.
    if mean_residual > (bin_capacity as f64) * 0.6 && open_bins_count > 3 {
        score += 3.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Penalize "dead" residual: small unusable gaps (< 10) are worst.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    } else if post_residual < 25 {
        score += 12.0; // risky small gap
    } else if post_residual > 50 {
        score += 4.0; // large residual is somewhat wasted potential too
    }

    // Perfect fit bonus
    if post_residual == 0 {
        score -= 50.0;
    }

    // Last-chance pressure: if this is the only fitting bin, strongly favor using it
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // Open-bin pressure: with many open bins, prefer filling existing ones
    score += (open_bins_count as f64) * 2.0 * (1.0 - post_residual as f64 / bin_capacity as f64);

    // Lookahead: if next item fits exactly in the post residual, reward this placement
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= (next_item_size as f64) * 0.5;
    }
    // Penalize if next item cannot use the leftover gap (creates dead space)
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 8.0;
    }

    // Progression: early in stream, be slightly more willing to open new bins (score new bin better)
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity {
        score -= 15.0 * (1.0 - progress);
    }

    // Deviation from mean residual: prefer bins whose residual is near mean (balanced packing)
    score += (post_residual as f64 - mean_residual).abs() * 0.3;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals that are too small to ever
    // hold a future item (min size 1, but practically tiny gaps) are waste.
    if post_residual > 0 {
        // Penalize unusable small gaps super-linearly.
        if post_residual < 10 {
            score += (10 - post_residual) as f64 * 12.0;
        } else if post_residual < 25 {
            score += (25 - post_residual) as f64 * 4.0;
        }
    } else {
        // Perfect fit: strong reward.
        score -= 40.0;
    }

    // Reward tight fits (small waste relative to item size).
    let tightness = item_size as f64 / bin_residual.max(1) as f64;
    score -= tightness * 15.0;

    // Last-chance bin: if this is the only bin that fits, strongly prefer it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // Lookahead: if next item fits exactly in the post-residual, reward.
    if next_item_size > 0 && post_residual >= next_item_size {
        let next_fit_quality = (post_residual - next_item_size) as f64;
        score -= 10.0 - next_fit_quality.min(10.0) * 0.5;
    }
    // If next item cannot fit in post-residual, the gap becomes dead space.
    if next_item_size > 0 && post_residual < next_item_size && post_residual > 0 {
        score += 8.0;
    }

    // Open-bin pressure: many open bins -> prefer consolidating into
    // existing bins rather than opening new ones.
    score += open_bins_count as f64 * 0.8;

    // New-bin candidate handling: a fresh empty bin should only win when
    // fits elsewhere are poor. Give it a moderate baseline so tight fits
    // and last-chance bonuses beat it.
    if bin_residual == bin_capacity {
        score = 55.0 + post_residual as f64 * 0.1;
        // Late in stream with few bins, opening may be fine; slightly cheaper.
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score -= progress * 5.0;
    }

    // Prefer bins below mean residual (filling emptier bins first keeps
    // tight bins available for future tight items)? Inverse: fill tighter
    // bins first to close them out; slight nudge.
    score += (mean_residual - bin_residual as f64) * 0.15;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward perfect or near-perfect fits strongly.
    if post_residual == 0 {
        score -= 1000.0;
    } else if post_residual <= 5 {
        score -= 300.0;
    }

    // 2-step lookahead: reward bins whose post_residual matches next_item_size.
    if next_item_size > 0 {
        let diff = (post_residual as i64 - next_item_size as i64).abs() as f64;
        score -= 250.0 / (1.0 + diff);
        if post_residual == next_item_size {
            score -= 400.0;
        }
        // Penalize leaving a dead space smaller than the smallest plausible item
        if post_residual < next_item_size && post_residual < 10 {
            score += 200.0;
        }
        // If next item won't fit here either way, mild penalty for wasting this bin
        if next_item_size > bin_residual {
            score += 20.0;
        }
    }

    // Relative-to-mean coupling: bins tighter than mean are more valuable to fill now.
    score -= 0.5 * (mean_residual - bin_residual as f64);

    // Last-chance bonus: if this is the only bin that fits, strongly prefer it.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 150.0;
    }

    // Penalize opening new bins when open bins fit comfortably.
    if bin_residual == bin_capacity {
        score += 120.0 + 3.0 * open_bins_count as f64;
    } else {
        score += 10.0 * open_bins_count as f64;
    }

    // Early in stream: be less picky, fill bins greedily; late: conserve quality.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 50.0 * progress;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals too small for any item are worthless.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    }
    // Penalize gaps that can't fit the known next item (k=2 lookahead).
    if next_item_size > 0 && post_residual < next_item_size {
        score += 8.0 * (next_item_size as f64 - post_residual as f64).sqrt();
    }
    // Reward near-perfect fits.
    score -= 12.0 * (1.0 - post_residual as f64 / bin_capacity as f64);

    // Last-chance bonus: if this is the only fitting bin, avoid opening a new bin
    // unless the fit would be terrible.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0 + 0.05 * post_residual as f64;
    }

    // Open-bin pressure: discourage spreading across many bins unless fit is good.
    score += 0.15 * open_bins_count as f64 * (post_residual as f64 / bin_capacity as f64);

    // New-bin candidate: only attractive when all fits would leave large dead space
    // or no open bins exist.
    if bin_residual == bin_capacity {
        let dead_space_pressure = if post_residual > 0 { 0.0 } else { 0.0 };
        let _ = dead_space_pressure;
        let worst_case_gap = if next_item_size > 0 && post_residual < next_item_size { 1.0 } else { 0.0 };
        let fit_quality = post_residual as f64 / bin_capacity as f64;
        score = 40.0 + 55.0 * fit_quality + 20.0 * worst_case_gap - 10.0 * (open_bins_count as f64).ln().max(0.0);
        if open_bins_count == 0 {
            score = -100.0;
        }
    }

    // Slight late-stream tightening: waste matters more as stream progresses.
    score *= 1.0 + 0.3 * (step_index as f64 / total_items.max(1) as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Exact fit: overwhelmingly favored.
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Dead-space avoidance: small leftover gaps are unusable for typical items.
    if post_residual > 0 && post_residual < 10 {
        score += (10 - post_residual) as f64 * 15.0; // tight-but-wasted gap penalty
    }

    // Penalize large residual waste relative to capacity (poor density).
    let fill_ratio = item_size as f64 / bin_capacity as f64;
    score -= fill_ratio * 20.0; // reward placing into bins where item fills a big chunk

    // If the leftover gap could still fit the next item, mild reward.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 8.0;
        // Extra reward if next item would then fit almost exactly (chained fit).
        let chain_gap = post_residual - next_item_size;
        if chain_gap < 10 {
            score -= 12.0;
        }
    } else if next_item_size > 0 {
        // leftover cannot host next item: penalize proportionally to gap smallness
        if post_residual > 0 && post_residual < next_item_size as f64 * 0.5 {
            score += 10.0;
        }
    }

    // Last-chance bin: if this is the only bin that fits, strongly prefer using it.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate handling: opening a new bin is only attractive when
    // open-bin pressure is high or the fit into existing bins is poor.
    if bin_residual == bin_capacity {
        // Base hesitation: prefer existing bins slightly.
        score += 5.0;
        // More open bins -> more willing to open a fresh one (spread load).
        score -= (open_bins_count as f64).ln().max(0.0) * 4.0;
        // Late in the stream, opening new bins is safer than fragmenting.
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score -= progress * 10.0;
        // If mean residual across open bins is small (all bins tight), new bin is good.
        if mean_residual < item_size as f64 {
            score -= 20.0;
        }
    } else {
        // Existing bin: penalize if its residual deviates badly from mean (fragmentation).
        let dev = (bin_residual as f64 - mean_residual).abs();
        score += dev * 0.3;
        // Prefer bins with tighter residuals (best-fit flavor) beyond raw post_residual.
        score += (bin_residual as f64) * 0.1;
    }

    // Mild pressure: many open bins -> prefer consolidation into existing bins.
    score += open_bins_count as f64 * 0.5;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: penalize small unusable gaps hard.
    if post_residual > 0 {
        // A gap is "unusable" if it's smaller than the smallest plausible item (~1..15).
        // Penalize gaps in [1, 15] quadratically; they are almost certainly wasted.
        if post_residual < 15 {
            score += (16.0 - post_residual as f64) * (16.0 - post_residual as f64) * 4.0;
        }
        // Penalize gaps that can't fit the known next item (lookahead-aware dead space).
        if next_item_size > 0 && post_residual < next_item_size {
            score += (next_item_size - post_residual) as f64 * 3.0;
        }
    } else {
        // Perfect fit: strong reward.
        score -= 50.0;
    }

    // Reward tight fits: how well the item fills the bin relative to residual.
    let fill_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= fill_ratio * 20.0;

    // Open bins pressure: more open bins -> prefer filling existing bins over opening new ones.
    score += open_bins_count as f64 * 2.0;

    // Last-chance bonus: if this is the only bin that can fit the item, strongly prefer it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate handling: only attractive when no open bin fits well.
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin, modulated by stream progression.
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score += 35.0 + 20.0 * (1.0 - progress);
        // If open bins have plenty of slack on average, discourage a new bin less mildly.
        if mean_residual > item_size as f64 * 1.5 {
            score += 15.0;
        }
        // If the next item is large and this item is small, a fresh bin preserves flexibility.
        if next_item_size > 60 && item_size < 40 {
            score -= 10.0;
        }
    }

    // Slight preference for bins whose residual deviates from the mean
    // (consolidate slack into fewer bins).
    score += (bin_residual as f64 - mean_residual).abs() * 0.3;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap_f = bin_capacity as f64;
    let progress = step_index as f64 / total_items.max(1) as f64;
    let mut score = post_residual as f64;

    // Perfect fit: dominant reward.
    if post_residual == 0 {
        score -= 900.0;
    } else if post_residual <= 3 {
        score -= 320.0;
    } else if post_residual <= 12 {
        score -= 60.0;
    } else if post_residual < 20 {
        score += 12.0;
    } else if post_residual < 30 {
        score += 12.0 + (30 - post_residual) as f64 * 0.5;
    }

    // Lookahead chaining: reward leaving exactly room for next item.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 600.0;
        } else if next_item_size < post_residual {
            let post2 = post_residual - next_item_size;
            score -= 90.0 - post2 as f64 * 1.5;
            if post2 == 0 { score -= 80.0; }
            if post2 > 0 && post2 < 5 { score -= 20.0; }
            if post2 > 0 && post2 <= next_item_size / 2 { score -= 8.0; }
            if post_residual % next_item_size == 0 { score -= 12.0; }
        } else {
            // Next item cannot fit here: penalize dead space proportionally.
            let gap = (next_item_size - post_residual) as f64;
            score += gap * 0.8;
            if post_residual > 0 && gap <= 5.0 { score += 18.0; }
            if post_residual > 0 && post_residual < 15 { score += 25.0; }
        }
    }

    // Dead-space avoidance: residuals too small for plausible future items.
    if post_residual > 0 && (post_residual as f64) < 12.0 {
        score += (12.0 - post_residual as f64) * 5.0;
    }
    if post_residual > 0 && (post_residual as f64) < mean_residual * 0.25 {
        score -= 10.0;
    }

    // Tightness reward for near-full bins.
    if post_residual > 0 {
        let tightness = 1.0 - (post_residual as f64) / cap_f;
        score -= tightness * tightness * 12.0;
        let dead_ratio = post_residual as f64 / cap_f;
        if dead_ratio < 0.03 { score -= 25.0; }
        else if dead_ratio < 0.08 { score -= 10.0; }
        else if dead_ratio > 0.30 { score += 18.0; }
        if item_size == bin_residual { score -= 30.0; }
    }

    // Last-chance bonus: only fitting open bin.
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 22.0;
    }

    // Open-bin pressure: mild reuse preference.
    score += open_bins_count as f64 * 0.4;

    // ---- New-bin candidate logic ----
    if bin_residual == bin_capacity {
        let leftover = bin_capacity - item_size;
        let newbin_waste = leftover as f64;
        let avg_fill = 1.0 - mean_residual / cap_f;
        score += 200.0 - avg_fill * 260.0 - progress * 55.0;

        if fitting_bins_count > 0 {
            score += (fitting_bins_count as f64).min(5.0) * 8.0;
            let snug = item_size as f64 / bin_residual.max(1) as f64;
            if snug > 0.9 { score += 30.0; }
            if snug > 0.95 { score += 20.0; }
            // Compare new-bin waste vs best alternative waste.
            let best_alt = if item_size as f64 <= mean_residual { mean_residual - item_size as f64 } else { mean_residual };
            if newbin_waste > best_alt + cap_f * 0.08 { score += 18.0; }
