    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // Many open bins: discourage spreading; slight penalty scaled smoothly
    let ob = open_bins_count as f64;
    score += ob * (1.0 + late) * 0.5;

    // New-bin candidate: only attractive when nothing fits well
    if bin_residual == bin_capacity {
        let scarcity = 1.0 / (fitting_bins_count as f64 + 1.0);
        score = cap * (1.0 - scarcity * 0.9) + late * 20.0;
    }

    score
}

