            score -= 60.0;                       // multiple of 10: highly reusable
        } else if post_residual % 25 == 0 {
            score -= 45.0;                       // multiple of 25
        } else if post_residual % 5 == 0 {
            score -= 25.0;                       // multiple of 5
        } else {
            score += 30.0;                       // awkward non-harmonic leftover
        }
    }

    // Integer-division threshold classes on post_residual (dead-space bands)
    let band = post_residual / 15;               // 0..6 bands
    score += band as f64 * 12.0;                 // larger bands = more waste, mild penalty

    // Lookahead coupling: if the next item exactly fills the post residual, huge reward.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 800.0;
        } else if next_item_size <= post_residual {
            // next item fits: reward proportional to how much would then remain
            let post2 = post_residual - next_item_size;
            score -= 120.0 - (post2 as f64) * 2.0;
        } else {
            // next item cannot use this leftover: penalize harmonic-friendly leftovers less
            score += 20.0;
            if post_residual % 10 == 0 { score -= 15.0; }
        }
    }

    // Last-chance bin: strong preference to use it rather than open a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 150.0;
    }

    // New-bin candidate: penalize opening a new bin unless current bins are nearly full.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let avg_fill = 1.0 - (mean_residual / cap_f);
        // open a new bin only if existing bins are heavily filled or stream is early
        score += 250.0 - avg_fill * 300.0 - progress * 50.0;
        if post_residual % 10 == 0 { score -= 20.0; }
    } else {
        // Prefer bins whose residual is close to the item (tight fit)
        let tightness = 1.0 - (item_size as f64 / bin_residual.max(1) as f64);
        score += tightness * 80.0;

        // Prefer bins deviating favorably from mean residual (below-mean = well packed)
        score += (mean_residual - bin_residual as f64) * 1.5;
    }

    // Mild pressure to consolidate when many bins are open
    score += open_bins_count as f64 * 0.5;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit: strong reward.
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Dead-space avoidance: penalize small unusable gaps.
    // A gap is "dead" if it is smaller than the smallest conceivable item (1)
    // or smaller than the lookahead item that could otherwise use it.
    let gap = post_residual as f64;
    if next_item_size > 0 {
        if (next_item_size as f64) > gap {
            // gap cannot host the next item: dead space
            let deadness = (gap / bin_capacity as f64).powi(2);
            score += 120.0 * deadness;
            // extra penalty when the gap is tiny but nonzero
            if gap < 10.0 {
                score += 80.0;
            }
        } else {
            // gap can host next item: reward proportional to snugness
            let snug = 1.0 - (gap - next_item_size as f64) / bin_capacity as f64;
            score -= 40.0 * snug;
        }
    }

    // Reward tight fits relative to bin residual.
    let tightness = 1.0 - (item_size as f64 / bin_residual.max(1) as f64);
    score += 60.0 * tightness;

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 150.0;
    }

    // Open-bin pressure: discourage proliferation of open bins,
    // stronger late in the stream.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score += open_bins_count as f64 * (4.0 + 8.0 * progress);

    // Favor bins whose residual is already below mean (consolidate large gaps).
    if (bin_residual as f64) < mean_residual {
        score -= 15.0;
    } else {
        score += 10.0;
    }

    // New-bin candidate: mildly penalize so it only wins when open bins fit badly.
    if bin_residual == bin_capacity {
        score += 90.0 + 20.0 * progress;
        // but if no open bin fits well, new bin becomes attractive
        if fitting_bins_count == 0 {
            score -= 500.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong reward when the lookahead item exactly fills this bin afterwards (2-step perfect chain).
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 200.0;
        } else if post_residual >= next_item_size {
            // Reward proportionally to how tightly the next item fits into the remaining space.
            let slack = (post_residual - next_item_size) as f64;
            score -= 60.0 * (1.0 - slack / bin_capacity as f64);
        } else {
            // Penalize leaving a residual too small for the known next item (likely dead space).
            let waste = (next_item_size - post_residual) as f64;
            score += 1.5 * waste;
        }
    } else {
        // Last item: prefer the tightest fit possible.
        score += 10.0;
    }

    // Compare against the average state of open bins: bins below mean residual are "tighter"
    // and better candidates for consuming now.
    let residual_f = post_residual as f64;
    let dev = residual_f - mean_residual;
    score += 0.5 * dev;

    // Last-chance bonus: if this is the only bin that fits, strongly prefer using it.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 80.0;
    }

    // Penalize opening new bins when plenty of open bins exist (encourage bin consolidation),
    // but allow it early in the stream.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let pressure = open_bins_count as f64;
        score += 40.0 + 15.0 * pressure * (0.3 + 0.7 * progress);
        // Still allow a new bin if the current item is large and would leave tiny fragmentation elsewhere.
        if item_size > bin_capacity / 2 {
            score -= 20.0;
        }
    }

    // Slight preference for tighter fits overall (small post residual relative to capacity).
    score += 0.2 * (residual_f / bin_capacity as f64) * 10.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits (small post_residual) with a non-linear bonus.
    let tightness = 1.0 - (post_residual as f64) / (bin_capacity as f64);
    score -= 45.0 * tightness * tightness * tightness;

    // Penalize dead space that is too small to be useful later
    // (items are >= 1, but small slivers are hard to fill exactly).
    if post_residual > 0 && post_residual < 12 {
        score += 25.0;
    }

    // Perfect fit: overwhelming reward.
    if post_residual == 0 {
        score -= 200.0;
    }

    // Lookahead coupling: if the next item fits exactly into the
    // resulting residual, strongly favor this bin.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 120.0;
        } else if next_item_size <= post_residual {
            let slack = (post_residual - next_item_size) as f64;
            score -= 40.0 * (1.0 - slack / (bin_capacity as f64));
        } else {
            // Next item won't fit here: mild penalty proportional to gap.
            score += 8.0;
        }
    }

    // Last-chance bin: if this is the only bin that fits the item,
    // strongly prefer using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 90.0;
    }

    // New-bin candidate handling: opening a bin is only attractive when
    // the item is large relative to capacity or the stream is early and
    // many items remain to fill fresh space.
    if bin_residual == bin_capacity {
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        let item_frac = item_size as f64 / bin_capacity as f64;
        // Large items justify fresh bins; small items should reuse space.
        score += 60.0 - 70.0 * item_frac + 40.0 * progress;
        // If existing bins fit well, discourage opening a new one.
        if fitting_bins_count > 0 {
            score += 15.0 * (fitting_bins_count as f64).min(5.0);
        }
    }

    // Global pressure: when many open bins exist with large mean residual,
    // prefer filling existing bins (consolidation) over spreading.
    if open_bins_count > 2 {
        let pressure = (open_bins_count as f64).ln() * (mean_residual / bin_capacity as f64);
        score += 10.0 * pressure;
    }

    // Late in the stream: minimize leftover space aggressively.
    let horizon = step_index as f64 / (total_items.max(1) as f64);
    score -= 30.0 * horizon * (1.0 - post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;
    let size_f = item_size as f64;
    let norm_size = size_f / cap;

    // Base: post-residual waste, with smooth non-linear polynomial coupling
    // to stream progress. Early on, waste is cheaper; late, it is costly.
    let progress_coupling = 1.0 + 2.0 * progress * progress;
    let mut score = pr * progress_coupling;

    // Super-linear penalty on large dead space (quartic growth of normalized waste)
    score += 40.0 * norm_pr * norm_pr * norm_pr * norm_pr * cap;

    // Reward near-perfect fits smoothly (gaussian-like bump around small post_residual)
    let tightness = (-norm_pr * norm_pr / 0.02).exp();
    score -= 25.0 * tightness * cap * (0.5 + progress);

    // Lookahead coupling: penalize if post_residual cannot smoothly accommodate next item
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        let gap = pr - nxt;
        if gap < 0.0 {
            // next item won't fit here: dead space relative to lookahead need
            score += 0.5 * (-gap) * (1.0 + progress);
        } else {
            // reward leaving just enough room for the next item (smooth kernel)
            let fit_bonus = (-(gap / cap) * (-(gap / cap)) / 0.01).exp();
            score -= 12.0 * fit_bonus;
        }
    }

    // Last-chance bin: strongly favor using the only bin that fits
    if fitting_bins_count == 1 {
        score -= 30.0;
    }

    // Mild penalty when many bins are open (encourage consolidation)
    score += 0.3 * open_bins_count as f64 * norm_pr;

    // Nudge toward fuller bins relative to the fleet mean residual
    score += 0.2 * (mean_residual - bin_residual as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Exact fit: perfect placement, strongly reward.
    if post_residual == 0 {
        score -= 1000.0;
        return score;
    }

    // Harmonic class of post_residual: bins whose leftover belongs to a
    // "usable" harmonic class (small, or divisible into common item sizes)
    // are more valuable than bins with awkward dead space.
    let pr = post_residual;
    let cap = bin_capacity as f64;

    // Class 1: tiny dead space (pr <= 10) -> nearly perfect, big reward.
    if pr <= 10 {
        score -= 60.0;
    }
    // Class 2: post residual divisible by common item granularities
    // (10/20/25/50) -> future items can tile it exactly.
    else if pr % 10 == 0 || pr % 25 == 0 {
        score -= 25.0;
    }
    // Class 3: awkward residual in (10, 30) -> classic dead-space trap,
    // penalize heavily since few items (>=10) can use it.
    else if pr < 30 {
        score += 40.0;
    }

    // Integer-division threshold: how many "generic" items of the
    // smallest plausible size (10) fit in the leftover.
    let tileable = pr / 10;
    score -= 8.0 * tileable as f64;

    // Lookahead coupling (k=2): if the next item fits exactly into
    // post_residual, this bin is a two-item perfect chain -> reward.
    if next_item_size > 0 {
        if next_item_size == pr {
            score -= 120.0;
        } else if next_item_size <= pr {
            let chain_post = pr - next_item_size;
            if chain_post <= 10 || chain_post % 10 == 0 {
                score -= 45.0; // chain lands in a good harmonic class
            } else if chain_post < 30 {
                score += 20.0; // chain creates awkward residue
            }
        } else {
            // next item cannot use this bin's residue: residue is a
            // terminal dead zone unless another bin takes next item.
            score += 10.0;
        }
    }

    // Last-chance bin: if this is the only bin that fits, avoid opening
    // a new bin unless the fit is truly awful.
    if fitting_bins_count == 1 {
        score -= 50.0;
        // but if the fit wastes most of the bin, soften the bonus
        let waste_frac = post_residual as f64 / cap;
        if waste_frac > 0.7 {
            score += 55.0;
        }
    }

    // New-bin candidate: opening a fresh bin should only win when no
    // open bin offers a decent fit. Penalize the empty-bin call.
    if bin_residual == bin_capacity {
        score += 70.0;
        // early in the stream, seeding bins is cheaper; late in the
        // stream, prefer consolidation into open bins.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 40.0 * (1.0 - progress);
    }

    // Prefer placing into bins whose residual is far below the open-bin
    // mean (tight bins first keeps flexible space available).
    score -= 0.5 * (mean_residual - post_residual as f64);

    // Mild pressure against proliferating bins.
    score += 2.0 * open_bins_count as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps are heavily penalized.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    } else if post_residual >= 10 && post_residual < 20 {
        score += 18.0;
    } else if post_residual == 0 {
        score -= 40.0; // perfect fit reward
    }

    // Penalize wasted large residual that could still host a big item
    if post_residual > 60 {
        score += 12.0;
    }

    // Pressure from number of open bins: prefer compacting when many bins open
    score += open_bins_count as f64 * 0.8;

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // Lookahead: if next item fits into post_residual, reward this placement
    if next_item_size > 0 && (post_residual as u32) >= next_item_size {
        score -= 15.0;
    } else if next_item_size > 0 && next_item_size > post_residual && next_item_size > bin_residual {
        // next item won't fit anywhere: leave big residual if possible
        score += 5.0;
    }

    // Mild preference for tighter fits via relative fill ratio
    score -= (item_size as f64 / bin_capacity as f64) * 10.0;

    // Early in stream: slightly favor opening bins to build diversity
    let progress = step_index as f64 / total_items.max(1) as f64;
    if progress < 0.1 {
        score += 3.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Aggressive 2-step lookahead: perfect match with next item is heavily rewarded.
    if next_item_size > 0 {
        let diff = (post_residual as i64 - next_item_size as i64).abs();
        if post_residual >= next_item_size {
            // Reward closeness to next item size (perfect fit = big discount).
            score -= 30.0 * (1.0 - diff as f64 / bin_capacity as f64);
            if diff == 0 {
                score -= 50.0; // exact 2-step fit: place here almost surely
            }
        } else {
            // post_residual too small for next item: penalize dead space more
            // the smaller (more unusable) the residual is.
            let waste = post_residual as f64 / bin_capacity as f64;
            score += 15.0 * waste;
            if post_residual < 10 {
                score += 25.0; // tiny dead space, bin effectively closed
            }
        }
    } else {
        // Last item: just minimize waste.
        score += 10.0 * (post_residual as f64 / bin_capacity as f64);
    }

    // Compare post_residual against mean residual across open bins:
    // leaving more than average slack is wasteful; below-average slack is tight packing.
    if post_residual as f64 > mean_residual {
        score += 0.5 * (post_residual as f64 - mean_residual);
    } else {
        score -= 0.25 * (mean_residual - post_residual as f64);
    }

    // Last-chance bin: if this is the only bin that fits, strongly prefer using it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // Penalize opening a new bin when good open bins exist, unless current fit is bad.
    if bin_residual == bin_capacity {
        // New-bin candidate: baseline cost of a fresh bin.
        score = bin_capacity as f64 * 0.9;
        if fitting_bins_count == 0 {
            score -= 100.0; // must open a new bin
        } else if next_item_size > 0 && post_residual >= next_item_size && post_residual as f64 <= mean_residual {
            // Only open a new bin if it promises a better 2-step future than open bins.
            score -= 30.0;
        }
        // Large item with poor existing fit: opening a fresh bin can be attractive.
        if item_size as f64 > mean_residual + 10.0 && fitting_bins_count > 0 {
            score -= 15.0;
        }
    }

    // Early in the stream, allow more bins to keep flexibility; late, pack tightly.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 5.0 * (1.0 - progress);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer tight fits (small post_residual), with a non-linear squash.
    score = score.powf(1.25);

    // Lookahead: if the next item fits into the resulting post-residual, reward this bin.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= (next_item_size as f64) * 0.6;
        } else {
            // Dead space relative to the lookahead item: penalize unusable remainder.
            score += (next_item_size as f64 - post_residual as f64).powf(1.5) * 0.35;
        }
    }

    // Last-chance pressure: if this is the only bin that fits, strongly prefer using it.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    } else if fitting_bins_count > 1 {
        // Many options: slightly deprioritize to keep flexibility.
        score += (fitting_bins_count as f64 - 1.0).ln().max(0.0) * 4.0;
    }

    // New-bin candidate handling: empty bin is a fallback; make it attractive only
    // when the item is large (would leave little waste anyway) or fits are scarce.
    if bin_residual == bin_capacity {
        let large_item_bonus = (item_size as f64 / bin_capacity as f64).powf(2.0) * 30.0;
        score -= large_item_bonus;
        if fitting_bins_count == 0 {
            score -= 40.0; // must open a new bin anyway
        }
    }

    // Global state coupling: when mean residual is high, prefer filling bins with
    // large residuals (reduce fragmentation); when low, tight fits matter more.
    let progress = (step_index as f64) / (total_items.max(1) as f64);
    score -= (mean_residual - post_residual as f64).abs() * (0.15 + 0.35 * progress);

    // Late in the stream, waste matters more; penalize post_residual extra.
    score += post_residual as f64 * 0.2 * progress;

    // Encourage keeping open bin count from exploding early.
    if open_bins_count > 0 {
        score += (open_bins_count as f64).ln() * 1.5 * (1.0 - progress);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let norm_pr = pr / cap;
    let mut score = pr as f64;
    // non-linear polynomial coupling of post_residual with stream progress
    let poly = norm_pr * norm_pr * (1.0 - progress) - norm_pr * progress;
    score += 40.0 * poly;
    // reward tight fits more strongly as stream progresses
    let tightness = 1.0 - norm_pr;
    score -= tightness * tightness * (1.0 + progress) * 10.0;
    // penalize opening bins when many bins fit, reward last-chance usage
    if fitting_bins_count == 1 {
        score -= 15.0 + 10.0 * progress;
    } else {
        score += 2.0 * (fitting_bins_count as f64).ln().max(0.0);
    }
    // dead space penalty relative to mean residual, scaled by progress
    score += progress * (pr - mean_residual).abs() * 0.3;
    // lookahead: favor bins leaving room for next item
    if next_item_size > 0 {
        let ni = next_item_size as f64;
        if pr >= ni && pr - ni <= 10.0 {
            score -= 8.0;
        } else if pr < ni && pr > 0.0 {
            score += 5.0 * (1.0 - pr / ni);
        }
    }
    // new-bin candidate: prefer it early or when post_residual would be large
    if bin_residual == bin_capacity {
        score -= 20.0 * (1.0 - progress) + 25.0 * norm_pr;
    }
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: bins whose leftover falls into
    // "small residue" classes are rewarded (space is nearly fully used).
    let pr = post_residual;
    if pr == 0 {
        score -= 60.0; // perfect closure
    } else if pr <= 10 {
        score -= 30.0;
    } else if pr <= 20 {
        score -= 12.0;
    }

    // Modulo-10 harmonic class: residues that are multiples of common item
    // sizes (10/20/25/50) are more reusable than awkward residues.
    let awkward = pr % 10 != 0 && pr % 20 != 0 && pr % 25 != 0 && pr % 50 != 0;
    if awkward {
        score += (pr as f64) * 0.35;
    } else {
        score -= (pr as f64) * 0.15;
    }

    // Lookahead coupling: reward if the next item fits the post residual
    // exactly or nearly (harmonic pairing), penalize near-miss dead space.
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        if (post_residual as f64) >= nx {
            let gap = post_residual as f64 - nx;
            if gap == 0.0 {
                score -= 40.0;
            } else if gap <= 10.0 {
                score -= 15.0;
            } else {
                score += gap * 0.10;
            }
        } else if (post_residual as f64) > 0.0 {
            // next item cannot use leftover: leftover is likely dead space
            score += (post_residual as f64) * 0.25;
        }
    }

    // Last-chance bin: strongly favor using the only fitting bin to avoid
    // opening a new bin.
    if fitting_bins_count == 1 {
        score -= 25.0;
    }

    // Fraction-of-capacity thresholds on the fill ratio (integer-division
    // style thresholds at 3/4 and 9/10 of capacity used).
    let used = cap - (bin_residual as f64);
    let fill = used / cap;
    if fill >= 0.9 {
        score -= 20.0;
    } else if fill >= 0.75 {
        score -= 8.0;
    }

    // Prefer bins with below-mean residual (tighter bins) mildly.
    score -= (mean_residual - post_residual as f64) * 0.2;

    // Early in the stream, allow opening bins more freely; later, consolidate.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity {
        // New-bin candidate: base cost, cheaper early, expensive late.
        score = cap * 0.8 + progress * cap * 0.6;
        if fitting_bins_count == 0 {
            score -= cap; // no alternative: must open
        }
        if next_item_size > 0 && (next_item_size as f64) <= cap * 0.9 {
            score -= 20.0;
        }
    } else if progress < 0.3 {
        score += 5.0; // discourage hoarding many bins early
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals that are too small for any
    // future item (min item size = 1, but practically small gaps) are waste.
    // Penalize small-but-nonzero post_residual heavily.
    if post_residual > 0 {
        // Dead-space curve: gap of 1..15 is nearly unusable -> big penalty.
        let dead_zone = if post_residual <= 15 {
            60.0 * (1.0 - post_residual as f64 / 15.0)
        } else {
            0.0
        };
        score += dead_zone;
    } else {
        // Perfect fit: strong reward.
        score -= 40.0;
    }

    // Reward tight fits generally: small post_residual relative to item size.
    let tightness = post_residual as f64 / (item_size as f64 + 1.0);
    score += 8.0 * tightness;

    // If this bin can also fit the next item exactly, bonus.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 25.0;
    }
    // If next item fits in the residual left behind, mild bonus.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 6.0;
    }
    // Penalize leaving a gap just below next_item_size (dead space for lookahead).
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 12.0 * (1.0 - post_residual as f64 / next_item_size as f64);
    }

    // Last-chance bin: if this is the only fitting bin, prefer using it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // Open-bin pressure: when many bins are open, discourage opening new ones.
    if bin_residual == bin_capacity {
        // New-bin candidate: base cost plus pressure from open bins.
        score += 15.0 + 4.0 * open_bins_count as f64;
        // Early in stream, new bins are cheaper; late, avoid spreading.
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score += 10.0 * progress;
        // If mean residual is large, we should reuse existing bins instead.
        score += 0.3 * mean_residual;
    } else {
        // Reward using existing bins, more so when many are open.
        score -= 2.0 * (open_bins_count as f64).sqrt();
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong preference for exact/tight fits: reward small post_residual non-linearly.
    if post_residual == 0 {
        score -= 60.0;
    } else {
        let pr = post_residual as f64;
        // Dead-space penalty grows super-linearly for residuals below ~half capacity.
        if pr < bin_capacity as f64 * 0.5 {
            score += 0.6 * (bin_capacity as f64 * 0.5 - pr);
        }
    }

    // 2-step lookahead: if the next item fits exactly into post_residual, big reward.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        let pr = post_residual as f64;
        if nxt == pr {
            score -= 45.0;
        } else if nxt < pr {
            // Next item fits: reward proportionally to how tight the two-step fill is.
            score -= 25.0 * (1.0 - (pr - nxt) / bin_capacity as f64);
            // Extra reward if the pair nearly exhausts the bin.
            if pr - nxt <= 5.0 {
                score -= 20.0;
            }
        } else {
            // Next item won't fit here: penalize bins that become too small to be useful.
            let gap = nxt - pr;
            if gap <= 10.0 {
                score += 8.0 + gap as f64; // near-miss: mildly bad
            }
            // Small post_residual that can't host next item is dead space.
            if pr < 10.0 {
                score += 12.0;
            }
        }
    }

    // Compare against mean residual across open bins: prefer bins whose residual
    // deviates favorably (larger residual = more room to burn on this item).
    let res = bin_residual as f64;
    score -= 0.35 * (res - mean_residual);

    // Last-chance bonus: if this is the only bin that fits, strongly prefer using it
    // over opening a new bin (unless post_residual is tiny and next item needs it).
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
        if next_item_size > 0 && (next_item_size as f64) <= post_residual as f64 {
            score -= 15.0;
        }
    }

    // New-bin candidate handling: only prefer a fresh bin when all fitting bins are bad.
    if bin_residual == bin_capacity {
        // Base handicap so open bins with decent fits win.
        score += 55.0;
        // But if item is large relative to capacity and current bins are crowded/low,
        // opening fresh is attractive: reduce the handicap.
        let fill_ratio = item_size as f64 / bin_capacity as f64;
        score -= 40.0 * fill_ratio * fill_ratio;
        if mean_residual < 25.0 {
            score -= 25.0;
        }
        if open_bins_count == 0 {
            score -= 100.0;
        }
        // If next item is large, a fresh bin gives it room.
        if next_item_size > 0 && (next_item_size as f64) / bin_capacity as f64 > 0.6 {
            score -= 15.0;
        }
    }

    // Mild late-stream conservatism: consolidate more as stream progresses.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 5.0 * progress * (post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tightness: reward small post_residual nonlinearly.
    let tightness = post_residual as f64 / bin_capacity as f64;
    score += 40.0 * tightness * tightness;

    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 1000.0;
    } else if post_residual < 10 {
        score -= 200.0; // near-perfect fit, unusable sliver
    }

    // Lookahead coupling: penalize residuals that can't host the next item,
    // reward residuals that can.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 30.0 * (1.0 - (post_residual as f64 / bin_capacity as f64));
        } else {
            score += 25.0;
        }
    }

    // Last-chance bin: strongly favor using the only fitting bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 150.0;
    }

    // Penalize opening a new bin when good alternatives exist.
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let waste = bin_capacity as f64 - item_size as f64;
        score += 120.0 + 0.5 * open_bins_count as f64 + 0.3 * waste;
        // late in the stream, consolidate more aggressively
        score += 80.0 * progress;
        // if mean residual is large, opening new bins is wasteful
        score += mean_residual * 0.4;
    } else {
        // reward using bins whose residual is below mean (consolidation)
        let res = bin_residual as f64;
        if res < mean_residual {
            score -= (mean_residual - res) * 0.2;
        }
    }

    // Mild preference for keeping fewer open bins early on.
    score += 0.05 * open_bins_count as f64 * (1.0 - step_index as f64 / total_items.max(1) as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
