    score += 0.05 * open_bins_count as f64 * norm_pr;
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the resulting residual: classify dead space into
    // capacity-fraction buckets. Residuals in the "small" class (< 25% of
    // capacity) are nearly unusable dead space -> penalize heavily.
    let quarter = bin_capacity / 4;
    let half = bin_capacity / 2;
    let post = post_residual;

    if post == 0 {
        // Perfect fit: strongly reward.
        score -= 100.0;
    } else if post < quarter {
        // Dead-space class: residual too small for typical items.
        score += 30.0;
        // Extra penalty if the next item cannot use it anyway.
        if next_item_size > post {
            score += 20.0;
        }
    } else if post < half {
        // Middle class: usable but imperfect.
        score += 5.0;
    } else {
        // Large residual class: good leftover.
        score -= 10.0;
    }

    // Integer-division threshold: residual divisible into likely item classes
    // (multiples of 10 / 20 in classic streams) is more valuable.
    if post % 10 == 0 && post > 0 {
        score -= 8.0;
    }
    if post % 20 == 0 && post > 0 {
        score -= 4.0;
    }

    // Lookahead coupling: reward if the next item fits the post residual
    // snugly (harmonic pair), penalize if next item is much larger.
    if next_item_size > 0 {
        if next_item_size <= post {
            let slack = post - next_item_size;
            if slack < quarter {
                score -= 15.0; // chains nicely
            } else {
                score -= 3.0;
            }
        } else {
            score += 10.0; // next item won't fit here
