    // chosen when open bins have bad residual classes. Scale with mean residual.
    if bin_residual == bin_capacity {
        score += 5.0 + 0.3 * mean_residual;
        // Early in the stream, opening bins is cheaper (more future items to fill).
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 1.0 };
        score -= 20.0 * (1.0 - progress);
        if next_item_size > 0 && next_item_size <= bin_capacity {
            score -= 5.0;
        }
    }

    // Mild penalty for accumulating many open bins with poor mean residual.
    if mean_residual > (bin_capacity as f64) * 0.6 && open_bins_count > 3 {
        score += 3.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
