pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap_f = bin_capacity as f64;
    let mut score = post_residual as f64;

    let quarter = bin_capacity / 4;
    let half = bin_capacity / 2;
    let post = post_residual;

    if post == 0 {
        // Perfect fit: strongly reward.
        score -= 500.0;
    } else if post <= 3 {
        // Nearly dead space.
        score -= 120.0;
    } else if post < quarter {
        score += 30.0;
        if next_item_size > post {
            score += 20.0;
        }
    } else if post < half {
        score += 5.0;
    } else {
        score -= 10.0;
    }

    // Dead-space ratio view: residuals below ~8% of capacity are wasted.
    let dead_ratio = post as f64 / cap_f;
    if post > 0 {
        if dead_ratio < 0.03 {
            score -= 35.0;
        } else if dead_ratio < 0.08 {
            score -= 12.0;
        } else if dead_ratio > 0.35 {
            score += 22.0;
        }
    }

    if post % 10 == 0 && post > 0 {
        score -= 8.0;
    }
    if post % 20 == 0 && post > 0 {
        score -= 4.0;
    }

    // Lookahead coupling with graded snugness.
    if next_item_size > 0 {
        if next_item_size == post {
            score -= 250.0; // exact pair
        } else if next_item_size <= post {
            let slack = post - next_item_size;
            if slack < quarter {
                score -= 15.0 - (slack as f64) * 0.5;
            } else {
                score -= 3.0;
            }
            if slack % 10 == 0 && slack > 0 {
                score -= 10.0;
            }
        } else {
            score += 10.0;
            let gap = next_item_size - post;
            if gap <= 3 {
                score += 20.0; // next item just barely misses: bad leftover
            }
        }
    }

    // Last-chance bonus: only fitting bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate: baseline scaled by mean residual and progress.
    if bin_residual == bin_capacity {
        let progress = if total_items > 0 { step_index as f64 / total_items.max(1) as f64 } else { 1.0 };
        let avg_fill = 1.0 - (mean_residual / cap_f);
        score += 80.0 + avg_fill * 120.0 - progress * 40.0;
        if fitting_bins_count > 0 {
            // Opening a new bin while open bins fit is only good if the item
            // is large (would leave a poor residual in an open bin anyway).
            let snug = item_size as f64 / bin_residual.max(1) as f64;
            score += 30.0;
            if snug > 0.9 {
                score -= 35.0;
            }
            if snug > 0.95 {
                score -= 20.0;
            }
        } else {
            score -= 40.0; // no open bin fits: must open
        }
        if item_size as f64 > mean_residual {
            score -= 25.0;
        }
        if next_item_size > 0 && next_item_size >= bin_capacity / 2 {
            score -= 20.0;
        }
        if item_size >= bin_capacity * 3 / 4 {
            score -= 30.0;
        }
    } else {
        // Tightness coupling: prefer filling fuller bins.
        let tightness = 1.0 - (item_size as f64 / bin_residual.max(1) as f64);
        score += tightness * 60.0;
        score += (mean_residual - bin_residual as f64) * 1.5;
        if item_size == bin_residual {
            score -= 40.0;
        }
        if bin_residual as f64 > cap_f * 0.6 {
            score -= 12.0;
        }
        if post > 0 && (post as f64) < mean_residual * 0.25 {
            score -= 15.0;
        }
    }

    // Mild penalty for many open bins with poor mean residual.
    if mean_residual > cap_f * 0.6 && open_bins_count > 3 {
        score += 3.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let score = post_residual as f64 / bin_capacity.max(1) as f64;
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap_f = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Dead-space bands on post_residual
    if post_residual == 0 {
        score -= 1150.0;
    } else if post_residual <= 3 {
        score -= 480.0;
    } else if post_residual <= 8 {
        score -= 235.0;
    } else if post_residual <= 12 {
        score -= 95.0;
    } else if post_residual < 20 {
        score += 18.0;
    } else if post_residual < 30 {
        score += 30.0;
    }

    // Harmonic leftovers remain reusable
    if post_residual > 0 {
        if post_residual % 10 == 0 {
            score -= 55.0;
        } else if post_residual % 25 == 0 {
            score -= 40.0;
        } else if post_residual % 5 == 0 {
            score -= 22.0;
        } else {
            score += 28.0;
        }
    }

    // Lookahead coupling with next item
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 880.0;
        } else if next_item_size <= post_residual {
            let post2 = post_residual - next_item_size;
            score -= 130.0 - (post2 as f64) * 2.0;
            if post2 % 10 == 0 && post2 > 0 {
                score -= 28.0;
            }
            if post2 == 0 {
                score -= 105.0;
            }
            if post2 >= 20 && post2 % 5 == 0 {
                score -= 12.0;
            }
            if post2 > 0 && post2 < 5 {
                score -= 25.0;
            }
        } else {
            score += 20.0;
            if post_residual % 10 == 0 {
                score -= 15.0;
            }
            if post_residual > 0 && post_residual < 15 {
                score += 45.0;
            }
            if post_residual > 0 && (next_item_size - post_residual) <= 3 {
                score += 35.0;
            }
            let gap = next_item_size as f64 - post_residual as f64;
            if gap > 0.0 && gap <= 8.0 {
                score += 12.0;
            }
            if post_residual > 0 && gap as f64 > mean_residual * 0.5 {
                score += 14.0;
            }
        }
    }

    // Last-chance bin: prefer using it over opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 150.0;
    }

    // New-bin candidate decision
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let avg_fill = 1.0 - (mean_residual / cap_f);
        score += 250.0 - avg_fill * 320.0 - progress * 60.0;
        // Fresh bin attractive when item is large relative to remaining slack
        if item_size as f64 > mean_residual {
            score -= 45.0;
        }
        // Penalize new bins when many open bins can still fit the item
        if fitting_bins_count > 0 {
            score += (fitting_bins_count as f64).min(5.0) * 9.0;
            score += 20.0;
            let snug = item_size as f64 / bin_residual.max(1) as f64;
            if snug > 0.9 {
                score += 40.0;
            }
            if snug > 0.95 {
                score += 25.0;
            }
        }
        if next_item_size > 0 && next_item_size >= bin_capacity / 2 {
            score -= 30.0;
        }
        if item_size >= bin_capacity * 3 / 4 {
            score -= 55.0;
        }
        if next_item_size > 0 && next_item_size <= bin_capacity - item_size {
            score -= 25.0;
        }
        // Open fresh bin when item nearly fills it and open bins are slack
        if item_size as f64 / cap_f > 0.85 && mean_residual > cap_f * 0.35 {
            score -= 40.0;
        }
        // Avoid new bins when existing bins fit comfortably
        if fitting_bins_count > 3 && item_size as f64 / cap_f < 0.5 {
            score += 30.0;
        }
    } else {
        // Tightness preference: fill bins snugly
        let tightness = 1.0 - (item_size as f64 / bin_residual.max(1) as f64);
        score += tightness * 85.0;

        // Below-mean residual bins are well packed
        score += (mean_residual - bin_residual as f64) * 1.5;

        if post_residual >= next_item_size as u32 && next_item_size > 0 {
            score -= 18.0;
        }
        let dead_ratio = post_residual as f64 / cap_f;
        if dead_ratio < 0.03 {
            score -= 35.0;
        } else if dead_ratio < 0.08 {
            score -= 12.0;
        } else if dead_ratio > 0.35 {
            score += 22.0;
        }
        if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size as u32 {
            let wasted = next_item_size as f64 - post_residual as f64;
            score += wasted * 0.6;
        }
        if post_residual > 0 && post_residual < 6 {
            score -= 20.0;
        }
        if post_residual > 0 && (post_residual as f64) < mean_residual * 0.25 {
            score -= 15.0;
        }
        if item_size == bin_residual {
            score -= 40.0;
        }
        // Penalize residuals no plausible future item can fill
        if post_residual > 0 && next_item_size > 0 && post_residual < next_item_size as u32 && post_residual < bin_capacity / 10 {
            score += 18.0;
        }
        // Reward residuals that pair with common sizes
        if post_residual > 0 && post_residual % 10 == 0 {
            score -= 10.0;
        }
        // Prefer filling large open bins
        if bin_residual as f64 > cap_f * 0.6 {
            score -= 12.0;
        }
    }

    // Consolidation pressure when many bins are open
    score += open_bins_count as f64 * 0.5;

