        let tightness = 1.0 - (item_size as f64 / bin_residual.max(1) as f64);
        score += tightness * 85.0;

        // Below-mean residual bins are well packed
        score += (mean_residual - bin_residual as f64) * 1.5;

        if post_residual >= next_item_size as u32 && next_item_size > 0 {
            score -= 18.0;
        }
        let dead_ratio = post_residual as f64 / cap_f;
        if dead_ratio < 0.03 {
            score -= 35.0;
        } else if dead_ratio < 0.08 {
            score -= 12.0;
        } else if dead_ratio > 0.35 {
            score += 22.0;
        }
        if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size as u32 {
            let wasted = next_item_size as f64 - post_residual as f64;
            score += wasted * 0.6;
        }
        if post_residual > 0 && post_residual < 6 {
            score -= 20.0;
        }
        if post_residual > 0 && (post_residual as f64) < mean_residual * 0.25 {
            score -= 15.0;
        }
        if item_size == bin_residual {
            score -= 40.0;
        }
        // Penalize residuals no plausible future item can fill
        if post_residual > 0 && next_item_size > 0 && post_residual < next_item_size as u32 && post_residual < bin_capacity / 10 {
            score += 18.0;
        }
        // Reward residuals that pair with common sizes
        if post_residual > 0 && post_residual % 10 == 0 {
            score -= 10.0;
        }
        // Prefer filling large open bins
        if bin_residual as f64 > cap_f * 0.6 {
            score -= 12.0;
        }
        // New mutation: leave residuals that two next-size items could still fill
        if post_residual > 0 && next_item_size > 0 && post_residual >= item_size + next_item_size {
            score -= 22.0;
        }
