        if post_residual > 0 && (post_residual as f64) > mean_residual * 2.5 && fitting_bins_count > 2 {
            score += 14.0;
        }
        // Reward near-exact double fits
        if next_item_size > 0 && post_residual > next_item_size && post_residual - next_item_size <= 2 {
            score -= 30.0;
        }
    }

    // Consolidation pressure when many bins are open
    score += open_bins_count as f64 * 0.5;

