            }
            if post_residual % next_item_size == 0 {
                score -= 18.0;
            }
            // gen12: stronger chain bonus — residual divisible into multiple next-item slots
            if post2 > 0 && post2 * 2 == post_residual {
                score -= 12.0;
            }
            if post2 > 0 && post2 % 2 == 0 && post2 / 2 >= next_item_size {
                score -= 10.0;
            }
            let chain = post_residual / next_item_size;
            if chain >= 2 {
                score -= (chain.min(4)) as f64 * 8.0;
            }
        } else {
            score += 20.0;
            if post_residual % 10 == 0 {
                score -= 15.0;
            }
            if post_residual > 0 && post_residual < 15 {
                score += 45.0;
            }
            if post_residual > 0 && (next_item_size - post_residual) <= 3 {
                score += 35.0;
            }
            let gap = next_item_size as f64 - post_residual as f64;
            if gap > 0.0 && gap <= 8.0 {
                score += 12.0;
            }
            if post_residual > 0 && gap > mean_residual * 0.5 {
                score += 14.0;
            }
            if next_item_size - post_residual <= 5 {
                score += (6 - (next_item_size - post_residual)) as f64 * 4.0;
            }
        }
    }

    // Last-chance bin: prefer using it over opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 155.0;
    }

    // New-bin candidate decision
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let avg_fill = 1.0 - (mean_residual / cap_f);
        score += 250.0 - avg_fill * 330.0 - progress * 65.0;
        if item_size as f64 > mean_residual {
            score -= 45.0;
        }
        if fitting_bins_count > 0 {
            score += (fitting_bins_count as f64).min(5.0) * 9.0;
            score += 20.0;
            let snug = item_size as f64 / bin_residual.max(1) as f64;
            if snug > 0.9 {
                score += 40.0;
            }
            if snug > 0.95 {
                score += 28.0;
            }
        }
        if next_item_size > 0 && next_item_size >= bin_capacity / 2 {
            score -= 32.0;
        }
        if item_size >= bin_capacity * 3 / 4 {
            score -= 55.0;
        }
        if next_item_size > 0 && next_item_size <= bin_capacity - item_size {
            score -= 25.0;
        }
        if item_size as f64 / cap_f > 0.85 && mean_residual > cap_f * 0.35 {
            score -= 40.0;
        }
        if fitting_bins_count > 3 && item_size as f64 / cap_f < 0.5 {
            score += 30.0;
        }
        if bin_capacity - item_size <= 4 {
            score -= 70.0;
        }
        if item_size as f64 / cap_f > 0.7 && fitting_bins_count as f64 > 4.0 {
            score += 15.0;
        }
        // fresh-bin leftover should be a pairable remainder for the next item
        if next_item_size > 0 {
