            }
        }
        let dead_ratio = post_residual as f64 / cap_f;
        if dead_ratio < 0.03 {
            score -= 38.0;
        } else if dead_ratio < 0.08 {
            score -= 14.0;
        } else if dead_ratio > 0.35 {
            score += 24.0;
        }
        if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size as u32 {
