        if post_residual > 0 && post_residual < 6 {
            score -= 22.0;
        }
        if post_residual > 0 && (post_residual as f64) < mean_residual * 0.25 {
            score -= 15.0;
        }
        if item_size == bin_residual {
            score -= 45.0;
        }
        if post_residual > 0 && next_item_size > 0 && post_residual < next_item_size as u32 && post_residual < bin_capacity / 10 {
            score += 18.0;
        }
        if post_residual > 0 && post_residual % 10 == 0 {
            score -= 10.0;
        }
        if post_residual > 0 && post_residual % 5 == 0 && post_residual <= 30 {
            score -= 8.0;
        }
        if bin_residual as f64 > cap_f * 0.6 {
            score -= 12.0;
        }
        if post_residual > 0 && post_residual < 25 && next_item_size > post_residual {
            score += (25 - post_residual) as f64 * 1.2;
        }
        if post_residual > 0 && next_item_size > 0 && post_residual > next_item_size * 3 && post_residual < bin_capacity / 3 {
            score += 12.0;
        }
        // early-stream waste is costlier than late-stream waste
        let progress = step_index as f64 / total_items.max(1) as f64;
        if post_residual > 0 && next_item_size > 0 && post_residual < next_item_size as u32 {
            score += (1.0 - progress) * 14.0;
        }
        // residual at least twice the item keeps room for a similar pair
        if post_residual > 0 && next_item_size > 0 && post_residual < next_item_size as u32 && post_residual >= item_size * 2 {
            score += 10.0;
        }
        // near-exact residual usage strongly preferred
        if post_residual > 0 && (post_residual as f64) < cap_f * 0.015 {
            score -= 18.0;
        }
        if post_residual > 0 && next_item_size > 0 && post_residual > next_item_size as u32 && post_residual < next_item_size as u32 * 2 && post_residual < 20 {
            score += 8.0;
        }
        // gen12: chainable residuals strongly preferred
        if post_residual > 0 && next_item_size > 0 && post_residual >= next_item_size as u32 {
