                score -= 16.0;
            }
            if post_residual >= next_item_size * 2 && post_residual - next_item_size * 2 <= 4 {
                score -= 20.0;
            }
        } else {
            score += 18.0;
            let gap = next_item_size - post_residual;
            if post_residual > 0 && gap <= 3 {
                score += 32.0;
            }
            if post_residual > 0 && (gap as f64) > mean_residual * 0.5 {
                score += 12.0;
            }
