        score += (mean_residual - bin_residual as f64) * 1.5;

        if next_item_size > 0 && post_residual >= next_item_size {
            score -= 18.0;
            if post_residual <= next_item_size + 4 {
                score -= 22.0;
            }
        }
        let dead_ratio = post_residual as f64 / cap_f;
        if dead_ratio < 0.03 {
            score -= 38.0;
        } else if dead_ratio < 0.08 {
            score -= 14.0;
        } else if dead_ratio > 0.35 {
            score += 24.0;
        }
        if post_residual > 0 && next_item_size > 0 && post_residual < next_item_size {
            let wasted = (next_item_size - post_residual) as f64;
            score += wasted * 0.6 + (1.0 - progress_f(step_index, total_items)) * 14.0;
        }
        if item_size == bin_residual {
            score -= 45.0;
        }
        if post_residual > 0 && post_residual % 10 == 0 {
            score -= 10.0;
        }
        if post_residual > 0 && post_residual % 5 == 0 && post_residual <= 30 {
            score -= 8.0;
        }
        if next_item_size > 0 && post_residual >= next_item_size {
