        }
        if bin_residual as f64 > cap_f * 0.6 {
            score -= 12.0;
        }
    }

    // Pressure from open bins: compact when many bins are open
    score += open_bins_count as f64 * 0.8;

    // Last-chance bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    score
}

