    // Lookahead couplings (discrete, borrowed + extended)
    if nxt > 0 {
        if nxt == post_residual {
            score -= 900.0;
        } else if nxt <= post_residual {
            let post2 = post_residual - nxt;
            score -= 135.0 - post2 as f64 * 2.0;
            if post2 == 0 { score -= 110.0; }
            if post2 > 0 && post2 < 5 { score -= 28.0; }
            if post2 >= 20 && post2 % 5 == 0 { score -= 12.0; }
            if post_residual % nxt == 0 { score -= 18.0; }
            if post_residual >= nxt * 2 && post_residual - nxt * 2 <= 4 { score -= 20.0; }
        } else {
            let gap = pr - nxt as f64;
            score += 20.0;
            if post_residual > 0 && post_residual < 15 { score += 45.0; }
            if nxt - post_residual <= 3 { score += 35.0; }
            if gap > 0.0 && gap <= 8.0 { score += 12.0; }
            if nxt - post_residual <= 5 { score += (6 - (nxt - post_residual)) as f64 * 4.0; }
            if post_residual > 0 && gap > mean_residual * 0.5 { score += 14.0; }
        }
        if post_residual > nxt && post_residual % 2 == 0 && post_residual / 2 >= nxt {
            score -= 10.0;
        }
    }

    // New-bin candidate logic (bin_residual == bin_capacity)
    if bin_residual == bin_capacity {
        let avg_fill = 1.0 - (mean_residual / cap);
        score += 250.0 - avg_fill * 330.0 - progress * 65.0;
        if size_f > mean_residual { score -= 45.0; }
        if fitting_bins_count > 0 {
            score += fitting_bins_count.min(5) as f64 * 9.0 + 20.0;
            let snug = size_f / bin_residual.max(1) as f64;
            if snug > 0.9 { score += 40.0; }
            if snug > 0.95 { score += 28.0; }
        }
        if nxt > 0 && nxt >= bin_capacity / 2 { score -= 32.0; }
        if item_size >= bin_capacity * 3 / 4 { score -= 55.0; }
        if nxt > 0 && nxt <= bin_capacity - item_size { score -= 25.0; }
        if bin_capacity - item_size <= 4 { score -= 70.0; }
        let leftover = bin_capacity - item_size;
        if nxt > 0 {
            if leftover >= nxt && leftover % nxt <= 4 { score -= 16.0; }
            if leftover < nxt && leftover < 10 { score += 18.0; }
            if leftover >= nxt && leftover - nxt <= 6 { score -= 38.0; }
        }
        let newbin_waste = leftover as f64;
        if newbin_waste > 0.0 && newbin_waste < mean_residual * 0.6 { score -= 30.0; }
    } else {
        // Open-bin refinements
        let tight = 1.0 - size_f / bin_residual.max(1) as f64;
        score += tight * 85.0;
        score += (mean_residual - bin_residual as f64) * 1.5;
        if item_size == bin_residual { score -= 45.0; }
        let dead_ratio = norm_pr;
        if dead_ratio < 0.03 { score -= 38.0; }
        else if dead_ratio < 0.08 { score -= 14.0; }
        else if dead_ratio > 0.35 { score += 24.0; }
        if nxt > 0 && post_residual > 0 && post_residual < nxt {
            score += (nxt - post_residual) as f64 * 0.6;
        }
        if post_residual > 0 && post_residual < 6 { score -= 22.0; }
        if post_residual > 0 && pr < mean_residual * 0.25 { score -= 15.0; }
        if post_residual > 0 && post_residual < 25 && nxt > post_residual {
            score += (25 - post_residual) as f64 * 1.2;
        }
        if post_residual > 0 && post_residual % 5 == 0 && post_residual <= 30 { score -= 8.0; }
        if nxt > 0 && post_residual >= nxt {
            let chain = post_residual / nxt;
            if chain >= 2 { score -= chain.min(4) as f64 * 6.0; }
        }
        if post_residual > 0 && pr > mean_residual * 1.6 && fitting_bins_count > 2 { score += 10.0; }
    }

    // Last-chance bin
    if fitting_bins_count == 1 { score -= 30.0; }

    // Consolidation pressure
    score += 0.3 * open_bins_count as f64 * norm_pr;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals too small for the minimum item
    // are unusable dead space -> heavy penalty.
    if post_residual > 0 && post_residual < 10 {
        score += 40.0 + (10 - post_residual) as f64 * 6.0;
    }
    if post_residual == 0 {
        score -= 15.0; // perfect fit
    }

    // Last-chance bonus: if this is the only fitting bin, strongly prefer it
    // to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // Open-bin pressure: more open bins -> prefer consolidating into existing
    // bins rather than opening new ones.
    score += open_bins_count as f64 * 0.8;

    // New-bin candidate: only attractive when the item fits poorly everywhere
    // else (post_residual here is huge = capacity). Make it mildly unattractive
    // by default; dead-space penalties above will override for bad fits.
    if bin_residual == bin_capacity {
        score += 10.0 + mean_residual * 0.3;
        // If next item is large and current residual would be wasted anyway,
        // opening a fresh bin becomes more attractive.
        if next_item_size > 0 && post_residual < next_item_size as f64 * 1.2 {
            score -= 20.0;
        }
    }

    // Lookahead: penalize leaving a residual that exactly blocks the next item
    // if a slightly larger gap would still be useful.
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size as u32 {
        score += 8.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong reward if the next item fits exactly into the post residual.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 200.0;
        } else if next_item_size <= post_residual {
            // Reward closeness of the fit for the next item.
            let slack = (post_residual - next_item_size) as f64;
            score -= 60.0 * (1.0 - slack / bin_capacity as f64);
        } else {
            // Next item won't fit here: penalize leaving dead space relative to mean residual.
            let dead = (post_residual as f64 - mean_residual).max(0.0);
            score += 0.5 * dead;
        }
    }

    // Last-chance bin bonus: if this is the only bin that fits, strongly prefer using it.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 80.0;
    }

    // Penalize opening a new bin unless the item fits poorly everywhere else.
    if bin_residual == bin_capacity {
        let poor_fit = next_item_size > 0 && next_item_size > post_residual;
        let many_fitting = fitting_bins_count > 2;
        score += if poor_fit || many_fitting { 0.0 } else { 150.0 };
        // A new bin is attractive if it leaves a residual matching the next item.
        if next_item_size > 0 && next_item_size == post_residual {
            score -= 250.0;
        }
    }

    // Mild preference for tighter bins overall (smaller residual before placement).
    score += 0.05 * (bin_residual as f64 - mean_residual);

    // Slight late-stream tightening: avoid spreading across many bins early.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += 10.0 * progress * (open_bins_count as f64 / (total_items.max(1) as f64));

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let score = (post_residual as f64) * 0.94;
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits nonlinearly: small post-residuals are much better.
    let frag = (post_residual as f64) / (bin_capacity as f64);
    score += frag * frag * 60.0;

    // Perfect or near-perfect fill gets a strong bonus.
    if post_residual == 0 {
        score -= 40.0;
    } else if post_residual < 10 {
        score -= 25.0;
    }

    // Lookahead: penalize leaving a residual that fits next_item_size badly.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if post_residual as f64 >= nxt && (post_residual as u32) >= next_item_size {
            // residual still usable for next item: mild reward, scaled by snugness
            let snug = 1.0 - ((post_residual - next_item_size) as f64) / (bin_capacity as f64);
            score -= 10.0 * snug;
        } else if post_residual > 0 && (post_residual as u32) < next_item_size {
            // dead space relative to the known next item
            score += 12.0;
        }
    }

    // Last-chance bin: strongly favor using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate: penalize opening a new bin, more so late in the stream
    // or when many bins are already open; relax if this bin's fit is very poor.
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let mut penalty = 25.0 + 20.0 * progress + 0.5 * open_bins_count as f64;
        // If item is large relative to capacity, new bin is more acceptable.
        let size_frac = item_size as f64 / bin_capacity as f64;
        penalty -= 15.0 * size_frac;
        // If mean residual across open bins is small, opening a bin is justified.
        if mean_residual < item_size as f64 {
            penalty -= 10.0;
        }
        score += penalty.max(0.0);
    } else {
        // Existing bin: slight preference for bins with below-average residual
        // (keeps large residuals available for large future items).
        if (bin_residual as f64) < mean_residual {
            score -= 5.0;
        } else {
            score += 3.0;
        }
        // Early in stream, consolidate into emptier bins to keep flexibility.
        let progress = step_index as f64 / (total_items.max(1) as f64);
        if progress < 0.3 {
            score += 0.05 * bin_residual as f64;
        }
    }

    // Mild penalty on very large leftovers that few items can use.
    if post_residual > 0 && post_residual < 10 {
        score += 5.0; // tiny unusable slivers
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap_f = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Dead-space bands on post_residual
    if post_residual == 0 {
        score -= 1180.0;
    } else if post_residual <= 3 {
        score -= 500.0;
    } else if post_residual <= 8 {
        score -= 240.0;
    } else if post_residual <= 12 {
        score -= 98.0;
    } else if post_residual < 20 {
        score += 18.0;
    } else if post_residual < 30 {
        score += 30.0;
    }

    // Harmonic leftovers remain reusable
    if post_residual > 0 {
        if post_residual % 10 == 0 {
            score -= 55.0;
        } else if post_residual % 25 == 0 {
            score -= 40.0;
        } else if post_residual % 5 == 0 {
            score -= 22.0;
        } else {
            score += 28.0;
        }
        if post_residual < 25 && next_item_size > post_residual {
            score += (25 - post_residual) as f64 * 1.2;
        }
    }

    // Lookahead coupling with next item
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 900.0;
        } else if next_item_size <= post_residual {
            let post2 = post_residual - next_item_size;
            score -= 135.0 - (post2 as f64) * 2.0;
            if post2 % 10 == 0 && post2 > 0 {
                score -= 28.0;
            }
            if post2 == 0 {
                score -= 110.0;
            }
            if post2 >= 20 && post2 % 5 == 0 {
                score -= 12.0;
            }
            if post2 > 0 && post2 <= 2 {
                score -= 14.0;
            }
            if post_residual >= next_item_size * 2 && post_residual - next_item_size * 2 <= 4 {
                score -= 20.0;
            }
            if post_residual % next_item_size == 0 {
                score -= 18.0;
            }
            // residual that can host next item twice stays valuable
            if post2 > 0 && post2 * 2 == post_residual {
                score -= 12.0;
            }
            if post2 > 0 && post2 % 2 == 0 && post2 / 2 >= next_item_size {
                score -= 10.0;
            }
        } else {
            score += 20.0;
            if post_residual % 10 == 0 {
                score -= 15.0;
            }
            if post_residual > 0 && post_residual < 15 {
                score += 45.0;
            }
            if post_residual > 0 && (next_item_size - post_residual) <= 3 {
                score += 35.0;
            }
            let gap = next_item_size as f64 - post_residual as f64;
            if gap > 0.0 && gap <= 8.0 {
                score += 12.0;
            }
            if post_residual > 0 && gap > mean_residual * 0.5 {
                score += 14.0;
            }
            if next_item_size - post_residual <= 5 {
                score += (6 - (next_item_size - post_residual)) as f64 * 4.0;
            }
        }
        if post_residual > 0 && post_residual % 2 == 0 && post_residual / 2 >= next_item_size {
            score -= 10.0;
        }
    }

    // Last-chance bin: prefer using it over opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 155.0;
    }

    // New-bin candidate decision
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let avg_fill = 1.0 - (mean_residual / cap_f);
        score += 250.0 - avg_fill * 330.0 - progress * 65.0;
        if item_size as f64 > mean_residual {
            score -= 45.0;
        }
        if fitting_bins_count > 0 {
            score += (fitting_bins_count as f64).min(5.0) * 9.0;
            score += 20.0;
            let snug = item_size as f64 / bin_residual.max(1) as f64;
            if snug > 0.9 {
                score += 40.0;
            }
            if snug > 0.95 {
                score += 28.0;
            }
        }
        if next_item_size > 0 && next_item_size >= bin_capacity / 2 {
            score -= 32.0;
        }
        if item_size >= bin_capacity * 3 / 4 {
            score -= 55.0;
        }
        if next_item_size > 0 && next_item_size <= bin_capacity - item_size {
            score -= 25.0;
        }
        if item_size as f64 / cap_f > 0.85 && mean_residual > cap_f * 0.35 {
            score -= 40.0;
        }
        if fitting_bins_count > 3 && item_size as f64 / cap_f < 0.5 {
            score += 30.0;
        }
        if bin_capacity - item_size <= 4 {
            score -= 70.0;
        }
        if item_size as f64 / cap_f > 0.7 && fitting_bins_count as f64 > 4.0 {
            score += 15.0;
        }
        // fresh-bin leftover should be a pairable remainder for the next item
        if next_item_size > 0 {
            let leftover = bin_capacity - item_size;
            if leftover >= next_item_size {
                let tail = leftover % next_item_size;
                if tail <= 4 {
                    score -= 16.0;
                }
            }
            if leftover < next_item_size && leftover < 10 {
                score += 18.0;
            }
            if next_item_size <= bin_capacity - item_size && (bin_capacity - item_size) - next_item_size <= 6 {
                score -= 38.0;
            }
            // new-bin leftover close to mean residual keeps future fits easy
            let ldiff = (leftover as f64 - mean_residual).abs();
            if ldiff < cap_f * 0.05 {
                score -= 12.0;
            }
            // prefer leftovers that can host next item twice
            if leftover >= next_item_size * 2 {
                score -= 10.0;
            }
        }
        // discourage new bins when a perfect fit already exists
        if fitting_bins_count > 0 && item_size == bin_residual {
            score += 120.0;
        }
        // compare waste against best alternative fit in open bins
        let newbin_waste = (bin_capacity - item_size) as f64;
        if newbin_waste > 0.0 && newbin_waste < mean_residual * 0.6 {
            score -= 30.0;
        }
        if fitting_bins_count > 0 {
            let best_alt = if item_size <= mean_residual as u32 { mean_residual - item_size as f64 } else { mean_residual };
            if newbin_waste > best_alt + cap_f * 0.08 {
                score += 22.0;
            }
        }
    } else {
        // Tightness preference: fill bins snugly
        let tightness = 1.0 - (item_size as f64 / bin_residual.max(1) as f64);
        score += tightness * 85.0;

        score += (mean_residual - bin_residual as f64) * 1.5;

        if post_residual >= next_item_size as u32 && next_item_size > 0 {
            score -= 18.0;
            if post_residual <= next_item_size as u32 + 4 {
                score -= 22.0;
            }
            // chain bonus: residual divisible into multiple future fits
            let chain = post_residual / next_item_size;
            if chain >= 2 {
                score -= (chain.min(4)) as f64 * 6.0;
            }
        }
        let dead_ratio = post_residual as f64 / cap_f;
        if dead_ratio < 0.03 {
            score -= 38.0;
        } else if dead_ratio < 0.08 {
            score -= 14.0;
        } else if dead_ratio > 0.35 {
            score += 24.0;
        }
        if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size as u32 {
            let wasted = next_item_size as f64 - post_residual as f64;
            score += wasted * 0.6;
        }
        if post_residual > 0 && post_residual < 6 {
            score -= 22.0;
        }
        if post_residual > 0 && (post_residual as f64) < mean_residual * 0.25 {
            score -= 15.0;
        }
        if item_size == bin_residual {
            score -= 45.0;
        }
        if post_residual > 0 && next_item_size > 0 && post_residual < next_item_size as u32 && post_residual < bin_capacity / 10 {
            score += 18.0;
        }
        if post_residual > 0 && post_residual % 10 == 0 {
            score -= 10.0;
        }
        if post_residual > 0 && post_residual % 5 == 0 && post_residual <= 30 {
            score -= 8.0;
        }
        if bin_residual as f64 > cap_f * 0.6 {
            score -= 12.0;
        }
        if post_residual > 0 && post_residual < 25 && next_item_size > post_residual {
            score += (25 - post_residual) as f64 * 1.2;
        }
        // penalize mid-range dead space no near-future item can use
        if post_residual > 0 && next_item_size > 0 && post_residual > next_item_size * 3 && post_residual < bin_capacity / 3 {
            score += 12.0;
        }
        // early-stream waste is costlier than late-stream waste
        let progress = step_index as f64 / total_items.max(1) as f64;
        if post_residual > 0 && next_item_size > 0 && post_residual < next_item_size as u32 {
            score += (1.0 - progress) * 14.0;
        }
        // residual at least twice the item keeps room for a similar pair
        if post_residual > 0 && next_item_size > 0 && post_residual < next_item_size as u32 && post_residual >= item_size * 2 {
            score += 10.0;
        }
        // near-exact residual usage strongly preferred
        if post_residual > 0 && (post_residual as f64) < cap_f * 0.015 {
            score -= 18.0;
        }
        // stronger penalty on dead space exceeding next item but below a reusable band
        if post_residual > 0 && next_item_size > 0 && post_residual > next_item_size as u32 && post_residual < next_item_size as u32 * 2 && post_residual < 20 {
            score += 8.0;
        }
        // favor bins whose remaining residual stays divisible into future pairs
        if post_residual > 0 && next_item_size > 0 && post_residual >= next_item_size as u32 && post_residual % next_item_size == 0 {
            score -= 14.0;
        }
        // fractional usability band: residual just under one next-item fit
        let usable_frac = post_residual as f64 / next_item_size.max(1) as f64;
        if next_item_size > 0 && post_residual > 0 && usable_frac < 1.0 && usable_frac > 0.55 {
            score += 12.0;
        }
        // large residual that next item cannot use: mild penalty
        if post_residual > 0 && (post_residual as f64) > mean_residual * 1.3 && next_item_size as f64 > post_residual as f64 {
            score += 8.0;
        }
        // very large residual with many open bins: keep it in reserve
        if post_residual > 0 && (post_residual as f64) > mean_residual * 1.6 && fitting_bins_count > 2 {
            score += 10.0;
        }
    }

    score += open_bins_count as f64 * 0.5;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
