pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap_f = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Exact-fit / tiny-dead-space reward (sharpened bands)
    if post_residual == 0 {
        score -= 1180.0;
    } else if post_residual <= 3 {
        score -= 500.0;
    } else if post_residual <= 10 {
        score -= 200.0;
    } else if post_residual <= 12 {
        score -= 98.0;
    } else if post_residual < 20 {
        score += 18.0;
    } else if post_residual < 30 {
        score += 30.0;
    }

    // Harmonic leftover rewards
    if post_residual > 0 {
        if post_residual % 10 == 0 {
            score -= 60.0;
        } else if post_residual % 25 == 0 {
            score -= 45.0;
        } else if post_residual % 5 == 0 && post_residual <= 30 {
            score -= 25.0;
        } else {
            score += 30.0;
        }
    }

    let band = post_residual / 15;
    score += band as f64 * 12.0;

    // Lookahead coupling (enriched from best lineage)
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 900.0;
        } else if next_item_size <= post_residual {
            let post2 = post_residual - next_item_size;
            score -= 135.0 - (post2 as f64) * 2.0;
            if post2 == 0 { score -= 110.0; }
            if post2 > 0 && post2 % 10 == 0 { score -= 28.0; }
            if post2 > 0 && post2 < 5 { score -= 28.0; }
            if post2 > 0 && post2 <= 2 { score -= 14.0; }
            if post_residual % next_item_size == 0 { score -= 18.0; }
            let chain = post_residual / next_item_size;
            if chain >= 2 { score -= (chain.min(4)) as f64 * 6.0; }
        } else {
            score += 20.0;
            if post_residual % 10 == 0 { score -= 15.0; }
            if post_residual > 0 && post_residual < 15 { score += 45.0; }
            let gap = next_item_size - post_residual;
            if gap <= 5 { score += (6 - gap) as f64 * 4.0; }
            if post_residual > 0 && (post_residual as f64) < mean_residual * 0.25 { score -= 15.0; }
        }
        if post_residual > next_item_size && post_residual % 2 == 0 && post_residual / 2 >= next_item_size {
            score -= 10.0;
        }
    }

    // Last-chance bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 150.0;
    }

    if bin_residual == bin_capacity {
        // New-bin candidate decision
        let progress = step_index as f64 / total_items.max(1) as f64;
        let avg_fill = 1.0 - (mean_residual / cap_f);
        score += 250.0 - avg_fill * 330.0 - progress * 65.0;

        if item_size as f64 > mean_residual { score -= 45.0; }
        if fitting_bins_count > 0 {
            score += (fitting_bins_count as f64).min(5.0) * 9.0;
            let snug = item_size as f64 / (bin_residual.max(1) as f64);
            if snug > 0.9 { score += 40.0; }
            if snug > 0.95 { score += 28.0; }
        }
        if item_size >= bin_capacity * 3 / 4 { score -= 55.0; }
        if bin_capacity - item_size <= 4 { score -= 70.0; }
        if next_item_size > 0 && next_item_size <= bin_capacity - item_size { score -= 25.0; }

        let leftover = bin_capacity - item_size;
        let newbin_waste = leftover as f64;
        if next_item_size > 0 {
            if leftover >= next_item_size {
                let tail = leftover % next_item_size;
                if tail <= 4 { score -= 16.0; }
