    let mut score = post_residual as f64;

    // Dead-space avoidance (mutated from parent: stronger, tiered)
    if post_residual == 0 {
        score -= 300.0; // perfect fit
    } else if post_residual <= 3 {
        score -= 120.0;
    } else if post_residual < 10 {
        score += 60.0;
    } else if post_residual < 20 {
        score += 18.0;
    } else if post_residual < 30 {
        score += 10.0;
    }

    // Lookahead: exact and near-exact fits for the next item
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 220.0;
        } else if next_item_size <= post_residual {
            let post2 = post_residual - next_item_size;
            score -= 30.0 - (post2 as f64) * 1.2;
            if post2 == 0 { score -= 80.0; }
            if post2 > 0 && post2 < 5 { score -= 25.0; }
            if post2 % 10 == 0 && post2 > 0 { score -= 15.0; }
            if post_residual >= next_item_size * 2 && post_residual - next_item_size * 2 <= 4 {
                score -= 18.0;
            }
            // chain fits: residual can host next item multiple times
            let chain = post_residual / next_item_size;
            if chain >= 2 { score -= (chain.min(4)) as f64 * 5.0; }
        } else {
            // next item won't fit here: penalize leaving a nearly-fitting gap
            let gap = next_item_size - post_residual;
            if post_residual > 0 {
                if gap <= 3 { score += 35.0; }
                else if gap <= 8 { score += 12.0; }
                if (gap as f64) > mean_residual * 0.5 { score += 10.0; }
            }
        }
    }

    // Compaction pressure scaled by open bins
    score += open_bins_count as f64 * 0.8;

    // Last-chance bin: strongly favor using it
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 45.0;
    }

    // Tightness via relative fill
    score -= (item_size as f64 / bin_residual.max(1) as f64) * 30.0;

    // NEW-BIN CANDIDATE handling: usually avoid opening a bin, but allow it
    // when the item is huge and would leave a tiny, unusable gap elsewhere.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let newbin_waste = (bin_capacity - item_size) as f64;
        score += 180.0 - progress * 60.0;
        // big items deserve a fresh bin when few alternatives fit well
        if item_size as f64 / cap_f > 0.75 { score -= 55.0; }
        if item_size as f64 > mean_residual { score -= 25.0; }
        if newbin_waste < mean_residual * 0.5 { score -= 30.0; }
        if next_item_size > 0 && (bin_capacity - item_size) >= next_item_size
            && (bin_capacity - item_size) - next_item_size <= 6 {
            score -= 35.0; // fresh bin pairs perfectly with next item
        }
        if fitting_bins_count > 3 { score += (fitting_bins_count.min(6) as f64) * 6.0; }
        // early stream: allow diversity
        if progress < 0.1 { score -= 5.0; }
    }

    // Mild progress-based diversity nudge for open bins
    let progress = step_index as f64 / total_items.max(1) as f64;
    if progress < 0.1 { score += 3.0; }

    // Prefer bins whose residual is below average (consolidating slack)
    if bin_residual < bin_capacity {
        score += (mean_residual - bin_residual as f64) * 0.8;
    }

    score
}

