pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    let progress = if total_items > 1 { step_index as f64 / total_items as f64 } else { 0.0 };

    // Normalized post-residual and fit quality
    let pr = post_residual as f64 / cap;
    let fit = item_size as f64 / bin_residual.max(1) as f64;

    // Non-linear polynomial coupling of post_residual with stream progress:
    // early on, waste is tolerable; later, tight fits are heavily rewarded.
    let tightness = 1.0 - pr * pr; // peaks when post_residual small
    let progress_gain = progress * progress * (3.0 - 2.0 * progress); // smoothstep
    score -= 60.0 * tightness * progress_gain;

    // Penalize large dead space non-linearly, amplified late in the stream
    score += 40.0 * pr * pr * pr * (0.5 + progress);

    // Reward high fill ratio smoothly
    score -= 25.0 * fit * fit;

    // Last-chance bin: strongly favor using it
    if fitting_bins_count == 1 {
        score -= 30.0 + 20.0 * progress;
    }

    // Lookahead: if next item fits exactly into post_residual, big reward
    if next_item_size > 0 && next_item_size <= post_residual {
        let gap = (post_residual - next_item_size) as f64 / cap;
        score -= 35.0 * (1.0 - gap * gap);
    } else if next_item_size > post_residual && next_item_size > 0 {
        // next item won't fit here anyway; slight penalty for wasting space
        score += 8.0 * pr;
    }

    // Mean residual coupling: prefer bins near the mean (balanced packing)
    let dev = (post_residual as f64 - mean_residual).abs();
    score += 5.0 * (dev / cap) * (dev / cap) * 10.0;

    // New-bin candidate: penalize opening a new bin unless current bins are fragmented
    if bin_residual == bin_capacity {
        score += 15.0 + 10.0 * (1.0 - progress);
        if fitting_bins_count > 0 {
            score += 12.0;
        }
    }

    score
}

