                if tail == 0 { score -= 12.0; }
            }
            if leftover < next_item_size && leftover < 10 { score += 18.0; }
        }
        if fitting_bins_count > 3 { score += (fitting_bins_count.min(6) as f64) * 8.0; }
        if fitting_bins_count > 0 { score += 20.0; }
        // early stream: allow diversity
        if progress < 0.1 { score -= 5.0; }
    } else {
        // Prefer bins whose residual is below average (consolidating slack)
        score += (mean_residual - bin_residual as f64) * 1.2;
        if bin_residual as f64 > cap_f * 0.6 { score -= 12.0; }
        if post_residual > 0 && (post_residual as f64) < mean_residual * 0.25 { score -= 15.0; }
        if fitting_bins_count <= 2 && post_residual > 0 { score -= 8.0; }
    }

    // Mild progress-based diversity nudge for open bins
    let progress = step_index as f64 / total_items.max(1) as f64;
    if progress < 0.1 { score += 3.0; }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: buckets of width 10.
    // Residuals that are small (near-perfect fit) are heavily rewarded.
    let post_class = post_residual / 10;
    score -= match post_class {
        0 => 30.0,                 // residual < 10: essentially perfect
        1 => 20.0,
        2 => 12.0,
        3 => 6.0,
        4 => 0.0,
        _ => -2.0,                 // large residual: mild penalty via base
    };

    // Dead-space penalty: residuals that no future item (min size 1..=100,
    // typical small) can use well. Quadratic in wasted capacity fraction.
    let waste_frac = post_residual as f64 / bin_capacity as f64;
    score += 15.0 * waste_frac * waste_frac;

    // Lookahead coupling: if the next item fits exactly into post_residual,
    // strongly favor this bin (chained fit).
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 25.0;
        } else if next_item_size <= post_residual {
            // next fits but leaves another residual: grade by resulting class
            let chain = post_residual - next_item_size;
            score -= match chain / 10 {
                0 => 12.0,
                1 => 7.0,
                2 => 3.0,
                _ => 0.0,
            };
        } else {
            // next item cannot use this bin's residual: penalize small leftovers
            score += (post_residual < next_item_size) as i32 as f64 * 4.0;
        }
    }

    // Last-chance logic: if this is the only fitting bin, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 18.0;
    }

    // New-bin candidate: neutral-ish but slightly penalized so we prefer
    // filling open bins unless the fit is terrible. Scale with stream progress.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 10.0 + 8.0 * (1.0 - progress);
        // If item leaves a nicely classed residual in a fresh bin, ease penalty
        if post_class <= 1 { score -= 14.0; }
    }

    // Mild pressure toward compacting many open bins.
    score += 0.05 * open_bins_count as f64;

    // Mean-residual anchor: prefer bins below mean residual (tighter bins).
    score += 0.3 * (mean_residual - bin_residual as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Dead-space penalty: residuals too small to hold the smallest item (1..10) are wasted.
    if post_residual < 10 && post_residual > 0 {
        score += 60.0 * (1.0 - post_residual as f64 / 10.0);
    }

    // Reward very tight fits (post_residual near zero is perfect packing).
    if post_residual == 0 {
        score -= 80.0;
    }

    // Lookahead: if the next item fits exactly in post_residual, strongly favor this bin.
    if next_item_size > 0 && next_item_size <= post_residual {
        let slack = (post_residual - next_item_size) as f64;
        score -= 40.0 * (1.0 - slack / bin_capacity as f64);
    }

    // Penalize leaving a gap that neither fits the next item nor is useful.
    if next_item_size > post_residual && post_residual > 0 {
        score += 15.0;
    }

    // Last-chance bonus: if this is the only fitting bin, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 50.0;
    }

    // Open-bin pressure: with many open bins, prefer consolidating into existing bins
    // rather than spreading; make the new-bin candidate less attractive.
    if bin_residual == bin_capacity {
        score += 25.0 + 8.0 * open_bins_count as f64;
    }

    // Mean-residual coupling: if this bin is far below average residual (already tight),
    // prefer filling it further; if far above average, slight penalty for wasting space.
    score += 0.3 * (mean_residual - bin_residual as f64);

    // Mild stream-progression term: late in the stream, be more conservative
    // about opening new bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity {
        score += 20.0 * progress;
    }

    score
}

