    let cap_f = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of the resulting residual.
    let quarter = bin_capacity / 4;
    let half = bin_capacity / 2;
    let post = post_residual;

    if post == 0 {
        // Perfect fit: strongly reward.
        score -= 500.0;
    } else if post <= 3 {
        // Near-perfect dead space (unusable but tiny waste).
        score -= 120.0;
    } else if post < quarter {
        // Dead-space class: residual too small for typical items.
        score += 30.0;
        if next_item_size > post {
            score += 20.0;
        }
        // Tiny residuals are cheap waste; don't over-penalize.
        if post < 8 {
            score -= 45.0;
        }
    } else if post < half {
        // Middle class: usable but imperfect.
        score += 5.0;
    } else {
        // Large residual class: good leftover.
        score -= 10.0;
    }

    // Integer-division threshold: divisible residuals are more valuable.
    if post % 10 == 0 && post > 0 {
        score -= 10.0;
    }
    if post % 20 == 0 && post > 0 {
        score -= 5.0;
    }

    // Lookahead coupling: reward if the next item fits the post residual snugly.
    if next_item_size > 0 {
        if next_item_size == post {
            score -= 300.0; // exact harmonic pair
        } else if next_item_size <= post {
            let slack = post - next_item_size;
            if slack < quarter {
                score -= 25.0; // chains nicely
            } else {
                score -= 5.0;
            }
            // Chain potential: residual divisible by next item.
            if post % next_item_size == 0 {
                score -= 15.0;
            }
        } else {
            score += 10.0; // next item won't fit here
            let gap = next_item_size - post;
            if gap <= 4 {
                score += 20.0; // near-miss is painful dead space
            }
        }
    }

    // Last-chance bonus: if this is the only fitting bin, avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 60.0;
    }

    // New-bin candidate handling.
    if bin_residual == bin_capacity {
