        let dead_ratio = post as f64 / cap_f;
        if dead_ratio < 0.03 {
            score -= 30.0;
        } else if dead_ratio > 0.35 {
            score += 20.0;
        }
        // Exact fit of residual by item.
        if item_size == bin_residual {
            score -= 80.0;
        }
        // Usable fraction of next item's demand.
        if next_item_size > 0 && post > 0 {
            let frac = post as f64 / next_item_size.max(1) as f64;
            if frac < 1.0 && frac > 0.55 {
                score += 10.0;
            }
        }
        // Few fitting bins: keep this option attractive.
        if fitting_bins_count <= 2 && post > 0 {
            score -= 10.0;
        }
    }

    // Mild penalty for accumulating many open bins with poor mean residual.
    if mean_residual > cap_f * 0.6 && open_bins_count > 3 {
        score += 4.0;
    }

    score
}

