pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong reward for perfect fit (zero dead space).
    if post_residual == 0 {
        score -= 1000.0;
    }

    // 2-step lookahead: reward residuals that exactly match the next item size.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 500.0;
        } else if post_residual > next_item_size {
            // Next item can also fit here: mild reward proportional to tightness.
            let slack = (post_residual - next_item_size) as f64;
            score -= 50.0 * (1.0 - slack / bin_capacity as f64);
        } else {
            // Next item cannot fit here; penalize dead space below next item size.
            let dead = (next_item_size - post_residual) as f64;
            score += 2.0 * dead;
        }
    }

    // Penalize unusable dead space (< 10) that is not a perfect fit.
    if post_residual > 0 && post_residual < 10 {
        score += 300.0;
    }

    // Reward tight fits relative to mean residual across open bins.
    if (post_residual as f64) < mean_residual {
        score -= 0.5 * (mean_residual - post_residual as f64);
    } else {
        score += 0.25 * ((post_residual as f64) - mean_residual);
    }

    // Last-chance bonus: if this is the only bin that can fit the item,
    // strongly prefer using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 200.0;
    }

    // New-bin candidate: penalize opening a new bin, more so early in the stream
    // and when existing bins could accommodate the item.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 150.0 + 100.0 * (1.0 - progress);
        if fitting_bins_count > 0 {
            score += 100.0;
        }
    }

    // Slight preference for bins with smaller residuals (tighter bins first).
    score += 0.1 * (bin_residual as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strongly prefer perfect fits.
    if post_residual == 0 {
        score -= 1000.0;
    } else {
        // Penalize dead space, weighted by how unusable it is.
        let dead = post_residual as f64;
        let usable = if next_item_size > 0 {
            (dead >= next_item_size as f64) as f64
        } else {
            1.0
        };
        score += dead * dead / bin_capacity as f64 * (1.5 - usable);
    }

    // Lookahead coupling: reward bins whose post-residual exactly fits the next item.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 400.0;
    }
    // Reward if next item could also fit here afterwards.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 60.0;
    } else if next_item_size > 0 {
        score += 40.0; // blocks the lookahead item
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 300.0;
    }

    // Tightness: favor bins where the item fills a large fraction of residual.
    let fill_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= fill_ratio * 120.0;

    // Global state: many open bins -> consolidate; few open bins -> allow spreading.
    let pressure = open_bins_count as f64 / (1.0 + mean_residual / bin_capacity as f64);
    score += pressure * 8.0;
    score -= mean_residual * 0.3;

    // Time horizon: early in the stream, be more selective (higher base score
    // for mediocre fits); late in the stream, pack greedily.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += (1.0 - progress) * 50.0 * (post_residual as f64 / bin_capacity as f64);

    // New-bin candidate: only attractive when nothing fits well.
    if bin_residual == bin_capacity && item_size > 0 {
        score += 150.0 + 2.0 * open_bins_count as f64;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let isz = item_size as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    // Base: prefer tight fits (small post_residual), with non-linear shaping
    let mut score = pr + 0.35 * (pr * pr) / cap;

    // Smooth polynomial coupling of post_residual with stream progress:
    // early on, waste is cheap; later, residual waste is increasingly penalized.
    let prog_sq = progress * progress;
    score *= 1.0 + 0.8 * prog_sq * (pr / cap);

    // Reward near-perfect fits (post_residual small relative to item size)
    let fill_ratio = isz / bin_residual as f64;
    score -= 12.0 * fill_ratio * fill_ratio;

    // Penalize creating residual that is small but unusable-ish relative to min item size
    let min_item = 1.0f64;
    let unusable = ((min_item - pr).max(0.0) / min_item).min(1.0);
    score += 6.0 * unusable * unusable;

    // Lookahead: strongly favor bins whose post_residual accommodates the next item
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if pr as f64 >= nxt {
            score -= 8.0 * (1.0 - (pr - nxt) / cap);
        } else {
            // post_residual can't fit next item: penalize proportionally to how close it is
            score += 5.0 * (1.0 - pr / nxt.max(1.0));
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 10.0;
    }

    // New-bin candidate handling: make empty bins less attractive unless the fit
    // is poor in all existing bins. Empty bin has bin_residual == bin_capacity.
    if bin_residual == bin_capacity {
        // Neutral base for a fresh bin; add slight penalty that fades as stream matures
        // and as the number of open bins grows (consolidation preference).
        score += 4.0 + 0.5 * (open_bins_count as f64).ln().max(0.0) - 3.0 * progress;
        // If no other bin fits except this one, fitting_bins_count counts only this one;
        // soften the penalty so a new bin can win when necessary.
        if fitting_bins_count == 1 {
            score -= 6.0;
        }
    }

    // Mild preference for bins below mean residual (keep residuals balanced),
    // non-linearly damped.
    let dev = (bin_residual as f64 - mean_residual) / cap;
    score += 2.0 * dev * dev.abs();

    // Small nudge toward using more open bins early (fewer wasted fresh bins later)
    score -= 1.5 * (1.0 - progress) * (1.0 - pr / cap);

    score
}

