    let mut score = post_residual as f64;

    // Perfect fit is unbeatable
    if post_residual == 0 {
        return -1000.0;
    }

    // Harmonic class of the leftover space: residual capacity fractions
    let cap = bin_capacity as f64;
    let frac = post_residual as f64 / cap; // fraction of capacity wasted if bin dies here

    // Dead-space penalty is convex in leftover: small leftovers are cheap, mid-size leftovers (30..60)
