            // next item fits: leftover after that placement, quantized harmonically
            let next_post = post_residual - next_item_size;
            let nclass = (next_post / 10) as f64;
            score -= 40.0 + 6.0 * (10.0 - nclass.min(10.0));
        } else {
            // next item cannot use this bin's leftover: penalize proportionally
            score += 15.0 + frac * 20.0;
        }
    }

    // Last-chance bin: strongly prefer using it over opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 120.0;
    }

    // New-bin candidate handling: empty bin gets a baseline that competes only
    // when open bins have bad fits.
    if bin_residual == bin_capacity {
        // opening a new bin is fine early / with many bins, costly when few bins and stream late
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score = 90.0 + 60.0 * (1.0 - progress) - 3.0 * open_bins_count as f64;
        if next_item_size > 0 && next_item_size >= item_size {
            score -= 30.0; // big item followed by big item: fresh bin is attractive
        }
        return score;
    }

    // Prefer bins whose residual is already tight (below mean): compacting small bins
    if (post_residual as f64) < mean_residual {
        score -= 10.0;
    }

    // Modulo-10 harmonic bonus: leftovers divisible by 10 align with common item classes
    if post_residual % 10 == 0 {
        score -= 12.0;
    }
    // class of item size: large items (>=50) prefer large-residual bins
    if item_size >= 50 && bin_residual >= 70 {
        score -= 8.0;
    }
    if item_size < 30 && post_residual > 70 {
        score += 10.0; // don't waste a big empty bin on a tiny item
    }

    score
