                score += 40.0 + (15 - post_residual) as f64 * 1.5;
            }
            let gap = next_item_size - post_residual;
            if gap <= 5 {
                score += (6 - gap) as f64 * 4.0;
            }
            if post_residual as f64 > mean_residual * 1.4 {
                score -= 12.0;
            }
        }
    }

    // Penalize wasted large residual that could still host a big item
    if post_residual > 60 {
        score += 12.0;
    }

    // Pressure from number of open bins: prefer compacting when many bins open
    score += open_bins_count as f64 * 0.8;

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 60.0;
    }

    // NEW-BIN CANDIDATE evaluation (bin_residual == bin_capacity)
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let avg_fill = 1.0 - (mean_residual / cap_f);
        // Opening a bin is costly unless the stream is early or fills are poor
        score += 240.0 - avg_fill * 300.0 - progress * 70.0;
        // Large items deserve fresh space
        if item_size >= bin_capacity * 3 / 4 {
            score -= 55.0;
        }
        if next_item_size > 0 && next_item_size >= bin_capacity / 2 {
            score -= 30.0;
        }
        // If a snug fit exists elsewhere, opening a new bin is bad
        if fitting_bins_count > 0 {
            let snug = item_size as f64 / (bin_residual.min(bin_capacity - 1).max(1) as f64);
            score += (fitting_bins_count as f64).min(5.0) * 9.0;
            if snug > 0.9 { score += 40.0; }
            if snug > 0.95 { score += 28.0; }
        }
        // Compare new-bin waste to existing residual availability
        let newbin_waste = (bin_capacity - item_size) as f64;
        if newbin_waste > 0.0 && newbin_waste < mean_residual * 0.6 {
            score -= 30.0;
        }
        if fitting_bins_count > 0 {
            let best_alt = if item_size as f64 <= mean_residual {
                mean_residual - item_size as f64
            } else {
                mean_residual
            };
            if newbin_waste > best_alt + cap_f * 0.08 {
                score += 22.0;
            }
        }
    } else {
        // Tightness preference: fill existing bins well
        let tightness = 1.0 - (item_size as f64 / bin_residual.max(1) as f64);
        score += tightness * 85.0;
        score += (mean_residual - bin_residual as f64) * 1.5;

        let dead_ratio = post_residual as f64 / cap_f;
        if dead_ratio < 0.03 {
            score -= 38.0;
        } else if dead_ratio < 0.08 {
            score -= 14.0;
        } else if dead_ratio > 0.35 {
            score += 24.0;
        } else if dead_ratio > 0.25 {
            score += 10.0;
        }

        if item_size == bin_residual {
            score -= 45.0;
        }
        if post_residual > 0 && post_residual % 10 == 0 {
            score -= 10.0;
        }
        if post_residual > 0 && post_residual < 25 && next_item_size > post_residual {
            score += (25 - post_residual) as f64 * 1.2;
        }
        // Chain potential: residual divisible by next item enables repeats
        if post_residual > 0 && next_item_size > 0 && post_residual >= next_item_size {
            let chain = post_residual / next_item_size;
            if chain >= 2 {
                score -= (chain.min(4)) as f64 * 6.0;
            }
        }
        if fitting_bins_count <= 2 && post_residual > 0 {
            score -= 8.0;
        }
    }

    // Mild preference for tighter fits via relative fill ratio
    score -= (item_size as f64 / cap_f) * 10.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap_f = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Dead-space shaping (borrowed strength from best heuristic)
    if post_residual == 0 {
        score -= 900.0; // perfect fit
    } else if post_residual <= 3 {
        score -= 380.0;
    } else if post_residual <= 12 {
        score -= 70.0;
    } else if post_residual < 20 {
        score += 18.0;
    } else if post_residual < 30 {
        score += 18.0 + (30 - post_residual) as f64 * 0.6;
    }

    // Lookahead chain: reward placements that keep room for the next item
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 700.0;
        } else if next_item_size <= post_residual {
            let post2 = post_residual - next_item_size;
            score -= 110.0 - post2 as f64 * 2.0;
            if post2 == 0 { score -= 90.0; }
            if post2 > 0 && post2 <= 2 { score -= 14.0; }
            if post2 > 0 && post2 < 5 { score -= 24.0; }
            if post2 % 10 == 0 && post2 > 0 { score -= 22.0; }
            if post_residual % next_item_size == 0 { score -= 16.0; }
            let chain = post_residual / next_item_size;
            if chain >= 2 { score -= (chain.min(4)) as f64 * 6.0; }
        } else {
            // next item won't fit here: penalize small dead gaps
            score += 20.0;
            if post_residual > 0 && post_residual < 15 { score += 40.0; }
            let gap = next_item_size - post_residual;
            if gap <= 5 { score += (6 - gap) as f64 * 4.0; }
            if post_residual as f64 > mean_residual * 1.4 { score -= 12.0; }
        }
    }

    // Pressure to compact when many bins are open
    score += open_bins_count as f64 * 0.8;

    // Last-chance bin: strongly favor using it
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // Tightness preference
    score -= (item_size as f64 / cap_f) * 10.0;

    // ---- NEW-BIN CANDIDATE GATING ----
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let avg_fill = 1.0 - (mean_residual / cap_f);
        // Open a new bin only when bins are well-filled or item is large
        score += 220.0 - avg_fill * 300.0 - progress * 60.0;
        if item_size >= bin_capacity * 3 / 4 { score -= 55.0; }
        if bin_capacity - item_size <= 4 { score -= 70.0; }
        if fitting_bins_count > 0 {
            score += (fitting_bins_count.min(5)) as f64 * 9.0 + 20.0;
            let snug = item_size as f64 / bin_residual.max(1) as f64;
            if snug > 0.9 { score += 40.0; }
            if snug > 0.95 { score += 28.0; }
        }
        let newbin_waste = (bin_capacity - item_size) as f64;
        if newbin_waste > 0.0 && newbin_waste < mean_residual * 0.6 { score -= 30.0; }
        if next_item_size > 0 && next_item_size >= bin_capacity / 2 { score -= 30.0; }
    } else {
        // Existing-bin fine shaping
        let tightness = 1.0 - (item_size as f64 / bin_residual.max(1) as f64);
        score += tightness * 85.0;
        score += (mean_residual - bin_residual as f64) * 1.5;
        let dead_ratio = post_residual as f64 / cap_f;
        if dead_ratio < 0.03 { score -= 38.0; }
        else if dead_ratio < 0.08 { score -= 14.0; }
        else if dead_ratio > 0.35 { score += 24.0; }
        else if dead_ratio > 0.25 { score += 10.0; }
        if item_size == bin_residual { score -= 45.0; }
        if post_residual > 0 && post_residual % 5 == 0 && post_residual <= 30 { score -= 8.0; }
        if post_residual > 0 && (post_residual as f64) < cap_f * 0.015 { score -= 18.0; }
        if fitting_bins_count <= 2 && post_residual > 0 { score -= 8.0; }
        let progress = step_index as f64 / total_items.max(1) as f64;
        if post_residual > 0 && next_item_size > 0 && post_residual < next_item_size as u32 {
            score += (1.0 - progress) * 14.0;
        }
    }

    // Early stream: slight diversity bonus
    let progress = step_index as f64 / total_items.max(1) as f64;
    if progress < 0.1 { score += 3.0; }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong preference for tight fits: reward small post-residual nonlinearly.
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 12.0 * tightness * tightness;

    // Penalize large dead space exponentially when it cannot fit a typical item.
    if post_residual > 0 && post_residual < 10 {
        score -= 8.0; // near-perfect fill
    } else if post_residual < 20 {
        score -= 3.0;
    } else if post_residual < 35 {
        score += 2.0;
    } else {
        score += 5.0 * (post_residual as f64 / bin_capacity as f64);
    }

    // Lookahead: if the next item fits exactly in the post-residual, big reward.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 25.0;
        } else if next_item_size < post_residual {
            let slack = post_residual - next_item_size;
            score -= 6.0 * (1.0 - slack as f64 / bin_capacity as f64);
        } else {
            // next item won't fit here; mild penalty for wasting space the next item could use
            score += 2.0;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate handling: make empty bins attractive only when fits are poor.
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        // Baseline neutral-ish; beats bad fits, loses to good fits.
        score += 10.0;
        if fitting_bins_count <= 1 {
            score -= 30.0; // no real alternative -> open new bin
        }
        if post_residual as f64 > mean_residual {
            score += 3.0;
        }
    } else {
        // Prefer filling bins that are already relatively full (below mean residual).
        score += 0.15 * (bin_residual as f64 - mean_residual);
    }

    // Time horizon: later in the stream, consolidate more aggressively.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 4.0 * progress * tightness;

    // Many open bins: encourage closing them out (prefer fullest bins).
    if open_bins_count > 4 {
        score -= 0.5 * (open_bins_count as f64).ln() * (1.0 - bin_residual as f64 / bin_capacity as f64);
    }

    score
}

