    score -= tightness * tightness * (1.0 + 2.0 * progress) * cap * 0.3;

    // Lookahead coupling: reward leaving room for the next item (smooth kernel).
    if next_item_size > 0 {
        let n = next_item_size as f64;
        let gap = (x * cap - n).abs();
        let kernel = 1.0 / (1.0 + gap * gap / (cap * cap * 0.02));
        score -= kernel * n * 0.25;
    } else {
        // Last item: strongly prefer filling bins tightly.
        score -= tightness * cap * 0.6;
    }

    // Last-chance bin: avoid opening a new bin when this is the only fit.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= cap * 0.8;
    }

    // New-bin candidate: penalize mildly, more so when open bins exist and
    // mean residual is ample (smooth logistic-like gate).
    if bin_residual == bin_capacity {
        let gate = mean_residual / cap;
        let logistic = 1.0 / (1.0 + (-6.0 * (gate - 0.5)).exp());
        score += cap * (0.35 + 0.55 * logistic + 0.2 * progress);
    } else {
        // Prefer fuller bins among open bins: mild reward scaled by occupancy.
        score -= (item_size as f64 / cap) * 10.0;
        // Fragmentation guard: penalize bins far from mean residual (smooth).
        let dev = (pr - mean_residual) / cap;
        score += dev * dev * cap * 0.15;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
