        }
        if post_residual % 5 == 0 && post_residual <= 30 { score -= 8.0; }
    }

    // Mild early-stream diversity nudge
    if progress < 0.1 { score += 3.0; }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic classes: bucket post_residual by capacity fraction.
    let post = post_residual as f64;
    let frac = post / cap; // 0..1

    // Class index via integer division thresholds (eighths of capacity).
    let class = (post_residual * 8) / bin_capacity; // 0..=8
    let class_penalty: [f64; 9] = [0.0, 14.0, 10.0, 7.0, 5.0, 3.5, 2.0, 1.0, 0.0];
    score += class_penalty[class.min(8) as usize];

    // Dead-space trap: residual in (0, 10) is nearly unusable.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Reward tight fits (small post_residual).
    score -= (1.0 - frac) * 8.0;

    // Perfect fill bonus.
    if post_residual == 0 {
        score -= 40.0;
    }

    // Lookahead coupling: if next item exactly fits the post_residual, strongly favor.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 60.0;
        } else if next_item_size <= post_residual {
            // leftover after next item, modular check: does it leave a "good" class?
            let npost = post_residual - next_item_size;
            let nclass = (npost * 8) / bin_capacity;
            score -= 10.0 - nclass as f64 * 1.2;
            if npost == 0 {
                score -= 35.0;
            }
            if npost > 0 && npost < 10 {
                score += 18.0; // would create dead space next round
            }
        } else {
            // next item can't use this residual: residual value decays
            score += 6.0;
        }
    }

    // Last-chance bin: strongly prefer using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 30.0;
    }

    // New-bin candidate handling: only attractive early or when open bins are fragmented.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    if bin_residual == bin_capacity {
        score = cap * 0.55
            + open_bins_count as f64 * 1.5
            - progress * 20.0
            + (mean_residual - post).max(0.0);
        if next_item_size > 0 && next_item_size >= 60 {
            score -= 15.0; // big item coming, fresh bin useful
        }
        if fitting_bins_count <= 1 {
            score += 40.0; // don't open new bin when it's the only fit anyway
        }
    }

    // Mild preference to spread load when many bins open and mean residual high.
    if open_bins_count > 3 && mean_residual > 40.0 {
        score -= (post - mean_residual).max(0.0) * 0.15;
    }

    score
}

