pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap_f = bin_capacity as f64;
    let mut score = post_residual as f64;
    let progress = step_index as f64 / total_items.max(1) as f64;

    // Perfect fit: dominant reward.
    if post_residual == 0 {
        score -= 1000.0;
    } else if post_residual <= 3 {
        score -= 400.0;
    } else if post_residual <= 12 {
        score -= 80.0;
    } else if post_residual < 25 {
        score += 15.0 + (25 - post_residual) as f64 * 0.5;
    } else if post_residual < cap_f * 0.5 {
        score += 5.0;
    } else {
        score -= 10.0;
    }

    // Divisibility-friendly residual shaping.
    if post_residual > 0 {
        if post_residual % 10 == 0 { score -= 8.0; }
        if post_residual % 20 == 0 { score -= 4.0; }
        let est_item = if step_index > 0 { (cap_f - mean_residual).max(1.0) } else { item_size as f64 };
        let m = post_residual as f64 % est_item;
        if m < 2.0 || est_item - m < 2.0 { score -= 7.0; }
        // Continuity: reward residuals near running mean item size.
        let dist = (post_residual as f64 - mean_residual.max(1.0)).abs();
        score += dist * 0.3;
        if dist < cap_f * 0.03 { score -= 9.0; }
    }

    // Lookahead coupling with next item.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 500.0;
        } else if next_item_size <= post_residual {
            let post2 = post_residual - next_item_size;
            score -= 100.0 - (post2 as f64) * 2.0;
            if post2 == 0 { score -= 80.0; }
            if post2 > 0 && post2 < 5 { score -= 20.0; }
            if post2 % 10 == 0 && post2 > 0 { score -= 20.0; }
            // Chain: residual absorbs next item twice cleanly.
            if post_residual >= next_item_size * 2 {
                let post3 = post_residual - next_item_size * 2;
                if post3 == 0 { score -= 22.0; }
                else if post3 <= 3 { score -= 10.0; }
            }
            let chain = post_residual / next_item_size;
            if chain >= 2 { score -= (chain.min(4)) as f64 * 5.0; }
        } else {
            score += 12.0;
            let gap = next_item_size as f64 - post_residual as f64;
            if post_residual > 0 && gap <= 3.0 { score += 30.0; }
            if post_residual > 0 && gap <= 8.0 { score += 12.0; }
            if post_residual > 0 && post_residual < 15 { score += 35.0; }
            // Dead space unusable by next item: penalize proportionally.
            if post_residual > 0 && gap > mean_residual * 0.6 && fitting_bins_count > 2 {
                score += gap * 0.7;
            }
            if post_residual > 0 && post_residual < 25 && next_item_size > post_residual {
                score += (25 - post_residual) as f64 * 1.0;
            }
        }
    }

    // Last-chance bonus: only fitting bin.
    if fitting_bins_count == 1 {
        score -= 25.0;
    }

    // New-bin candidate logic.
    if bin_residual == bin_capacity {
        let avg_fill = 1.0 - (mean_residual / cap_f);
        score += 200.0 - avg_fill * 280.0 - progress * 60.0;
        let newbin_waste = (bin_capacity - item_size) as f64;
        if fitting_bins_count > 0 {
            score += (fitting_bins_count.min(5) as f64) * 8.0;
            let snug = item_size as f64 / (bin_residual.max(1) as f64);
            if snug > 0.9 { score += 35.0; }
            if snug > 0.95 { score += 25.0; }
            // Compare new-bin waste against best alternative residual.
            let best_alt = if item_size as f64 <= mean_residual { mean_residual - item_size as f64 } else { mean_residual };
            if newbin_waste > best_alt + cap_f * 0.08 { score += 20.0; }
            if newbin_waste > best_alt + cap_f * 0.2 { score += 12.0; }
        }
        // Late-stream tightening: waste tolerance shrinks.
        if progress > 0.6 && fitting_bins_count > 0 {
            let waste_tol = (1.0 - progress) * cap_f * 0.35;
            if newbin_waste > waste_tol { score += 10.0 + progress * 20.0; }
        }
