pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap_f = bin_capacity as f64;
    let progress = step_index as f64 / total_items.max(1) as f64;
    let mut score = post_residual as f64;

    // Tiered dead-space avoidance (strengthened exact/near fits)
    if post_residual == 0 {
        score -= 900.0;
    } else if post_residual <= 3 {
        score -= 350.0;
    } else if post_residual <= 12 {
        score -= 80.0;
    } else if post_residual < 20 {
        score += 18.0;
    } else if post_residual < 30 {
        score += 18.0 + (30 - post_residual) as f64 * 0.6;
    }

    // Lookahead on next item
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 700.0;
        } else if next_item_size <= post_residual {
            let post2 = post_residual - next_item_size;
            score -= 120.0 - (post2 as f64) * 2.0;
            if post2 == 0 { score -= 90.0; }
            if post2 > 0 && post2 < 5 { score -= 26.0; }
            if post2 > 0 && post2 <= 2 { score -= 12.0; }
            if post2 > 0 && post2 % 10 == 0 { score -= 20.0; }
            if post2 > 0 && post2 <= next_item_size / 4 { score -= 10.0; }
            // two-step chain: residual can host next item twice cleanly
            if post_residual >= next_item_size * 2 {
                let post3 = post_residual - next_item_size * 2;
                if post3 == 0 { score -= 30.0; }
                else if post3 <= 3 { score -= 14.0; }
            }
            let chain = post_residual / next_item_size;
            if chain >= 2 { score -= (chain.min(4)) as f64 * 6.0; }
        } else {
            let gap = next_item_size - post_residual;
            if post_residual > 0 {
                if gap <= 3 { score += 35.0; }
                else if gap <= 8 { score += 12.0; }
                if post_residual < 15 { score += 40.0; }
                if (gap as f64) > mean_residual * 0.5 { score += 14.0; }
                if gap <= 5 { score += (6 - gap) as f64 * 4.0; }
            }
        }
    }

    // Compaction pressure scaled by open bins
    score += open_bins_count as f64 * 0.8;

    // Last-chance bin: strongly favor using it
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 45.0;
    }

    // Tightness via relative fill
    let snug = item_size as f64 / bin_residual.max(1) as f64;
    score -= snug * 40.0;

    // Dead-space shaping for open bins
    if bin_residual < bin_capacity {
        score += (mean_residual - bin_residual as f64) * 1.2;
        let dead_ratio = post_residual as f64 / cap_f;
        if dead_ratio < 0.03 { score -= 30.0; }
        else if dead_ratio > 0.30 { score += 20.0; }
