            let dist = (post_residual as f64 - mean_residual.max(1.0)).abs();
            score += dist * 0.3;
            if dist < cap_f * 0.03 { score -= 10.0; }
        }
        if item_size == bin_residual { score -= 45.0; }
        if post_residual > 0 && post_residual % 10 == 0 { score -= 8.0; }
    }

    // NEW-BIN CANDIDATE handling
    if bin_residual == bin_capacity {
        let newbin_waste = (bin_capacity - item_size) as f64;
        let avg_fill = 1.0 - (mean_residual / cap_f);
        score += 230.0 - avg_fill * 320.0 - progress * 60.0;
