        let dead_ratio = post_residual as f64 / cap_f;
        if dead_ratio < 0.03 { score -= 30.0; }
        else if dead_ratio < 0.08 { score -= 12.0; }
        else if dead_ratio > 0.35 { score += 20.0; }
        else if dead_ratio > 0.25 { score += 10.0; }

        // Unusable-gap penalty relative to next item
        if post_residual > 0 && next_item_size > 0 && post_residual < next_item_size {
            let wasted = next_item_size as f64 - post_residual as f64;
            score += wasted * 0.6;
        }
        if post_residual > 0 && next_item_size > 0 && post_residual >= next_item_size {
            let reuse = (post_residual / next_item_size) as f64 * (next_item_size as f64 / cap_f);
            score -= reuse * 22.0;
        }
        if item_size == bin_residual { score -= 45.0; }
        if post_residual > 0 && post_residual % 10 == 0 { score -= 10.0; }
        if post_residual > 0 && (post_residual as f64) < mean_residual * 0.25 { score -= 15.0; }
    }

    // Mild progress-based diversity nudge for open bins
    let progress = step_index as f64 / total_items.max(1) as f64;
    if progress < 0.1 && bin_residual != bin_capacity { score += 3.0; }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap_f = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Strong perfect / near-perfect fit rewards
    if post_residual == 0 {
        score -= 1100.0;
    } else if post_residual <= 3 {
        score -= 480.0;
    } else if post_residual <= 12 {
        score -= 90.0;
    } else if post_residual < 20 {
        score += 16.0;
    } else if post_residual < 30 {
        score += 16.0 + (30 - post_residual) as f64 * 0.6;
    }

    // Lookahead: two-step chain planning
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 850.0;
        } else if next_item_size <= post_residual {
            let post2 = post_residual - next_item_size;
            score -= 130.0 - post2 as f64 * 2.0;
            if post2 == 0 { score -= 100.0; }
            if post2 > 0 && post2 < 5 { score -= 26.0; }
            if post2 > 0 && post2 <= 2 { score -= 12.0; }
            if post2 % 10 == 0 && post2 > 0 { score -= 25.0; }
            if post2 >= 20 && post2 % 5 == 0 { score -= 10.0; }
            if post_residual >= next_item_size * 2 {
                let post3 = post_residual - next_item_size * 2;
                if post3 == 0 { score -= 24.0; } else if post3 <= 3 { score -= 12.0; }
            }
            if post_residual % next_item_size == 0 { score -= 16.0; }
            if post2 > 0 && post2 <= next_item_size / 4 { score -= 8.0; }
        } else {
            // next item won't fit here; penalize small dead gaps
            score += 18.0;
            if post_residual > 0 && post_residual < 15 { score += 40.0; }
            if post_residual > 0 && (next_item_size - post_residual) <= 3 { score += 32.0; }
            let gap = next_item_size as f64 - post_residual as f64;
            if gap > 0.0 && gap <= 8.0 { score += 10.0; }
            if post_residual as f64 > mean_residual * 1.4 { score -= 10.0; }
        }
    }

    // NEW-BIN CANDIDATE branch
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let avg_fill = 1.0 - (mean_residual / cap_f);
        score += 240.0 - avg_fill * 320.0 - progress * 60.0;
        if item_size as f64 > mean_residual { score -= 40.0; }
        if fitting_bins_count > 0 {
            score += (fitting_bins_count as f64).min(5.0) * 9.0 + 18.0;
            let snug = item_size as f64 / (bin_residual.max(1) as f64);
            if snug > 0.9 { score += 38.0; }
            if snug > 0.95 { score += 26.0; }
        }
        if next_item_size > 0 && next_item_size >= bin_capacity / 2 { score -= 30.0; }
        if item_size >= bin_capacity * 3 / 4 { score -= 50.0; }
        if next_item_size > 0 && next_item_size <= bin_capacity - item_size { score -= 22.0; }
        if bin_capacity - item_size <= 4 { score -= 65.0; }
        if next_item_size > 0 {
            let leftover = bin_capacity - item_size;
            if leftover >= next_item_size {
                let tail = leftover % next_item_size;
                if tail <= 4 { score -= 14.0; }
                if tail == 0 { score -= 10.0; }
            }
            if leftover < next_item_size && leftover < 10 { score += 16.0; }
        }
        let newbin_waste = (bin_capacity - item_size) as f64;
        if newbin_waste > 0.0 && newbin_waste < mean_residual * 0.6 { score -= 28.0; }
        if progress > 0.6 {
            let waste_tol = (1.0 - progress) * cap_f * 0.35;
            if newbin_waste > waste_tol && fitting_bins_count > 0 {
                score += 10.0 + progress * 20.0;
            }
        }
    } else {
        // Existing bin: prefer tight fits and residual matching
        let tightness = 1.0 - (item_size as f64 / bin_residual.max(1) as f64);
        score += tightness * 80.0;
        score += (mean_residual - bin_residual as f64) * 1.4;
        if item_size == bin_residual { score -= 42.0; }

        let dead_ratio = post_residual as f64 / cap_f;
        if dead_ratio < 0.03 { score -= 36.0; }
        else if dead_ratio < 0.08 { score -= 12.0; }
        else if dead_ratio > 0.35 { score += 22.0; }
        else if dead_ratio > 0.25 { score += 9.0; }

        if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
            let wasted = next_item_size as f64 - post_residual as f64;
            score += wasted * 0.6;
            let unusable = (next_item_size - post_residual) > 12;
            if unusable { score += dead_ratio * 85.0; }
        } else if next_item_size > 0 && post_residual > 0 {
            let reuse = (post_residual / next_item_size) as f64 * (next_item_size as f64 / cap_f);
            score -= reuse * 20.0;
            let chain = post_residual / next_item_size;
            if chain >= 2 { score -= (chain.min(4)) as f64 * 5.0; }
        }

        if post_residual > 0 && post_residual < 6 { score -= 20.0; }
        if post_residual > 0 && (post_residual as f64) < mean_residual * 0.25 { score -= 14.0; }
        if post_residual > 0 && post_residual % 10 == 0 { score -= 9.0; }
        if post_residual > 0 && post_residual % 5 == 0 && post_residual <= 30 { score -= 7.0; }
        if bin_residual as f64 > cap_f * 0.6 { score -= 10.0; }

        let progress = step_index as f64 / total_items.max(1) as f64;
        if post_residual > 0 && next_item_size > 0 && post_residual < next_item_size {
            score += (1.0 - progress) * 12.0;
        }
        if post_residual > 0 && (post_residual as f64) > mean_residual * 1.6 && fitting_bins_count > 2 {
            score += 9.0;
        }
        if fitting_bins_count <= 2 && post_residual > 0 { score -= 7.0; }
    }

    // Pressure from number of open bins
    score += open_bins_count as f64 * 0.6;
    // Last-chance bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity { score -= 22.0; }
    // Mild fill-ratio preference
    score -= (item_size as f64 / cap_f) * 10.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
