pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap_f = bin_capacity as f64;
    let progress = step_index as f64 / total_items.max(1) as f64;
    let mut score = post_residual as f64;

    // Tiered dead-space avoidance (strengthened)
    if post_residual == 0 {
        score -= 900.0;
    } else if post_residual <= 3 {
        score -= 380.0;
    } else if post_residual <= 12 {
        score -= 80.0;
    } else if post_residual < 20 {
        score += 18.0;
    } else if post_residual < 30 {
        score += 18.0 + (30 - post_residual) as f64 * 0.5;
    }

    // Lookahead: next-item fits
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 700.0;
        } else if next_item_size <= post_residual {
            let post2 = post_residual - next_item_size;
            score -= 110.0 - (post2 as f64) * 2.0;
            if post2 == 0 { score -= 100.0; }
            if post2 > 0 && post2 < 5 { score -= 26.0; }
            if post2 % 10 == 0 && post2 > 0 { score -= 20.0; }
            if post_residual % next_item_size == 0 { score -= 14.0; }
            if post_residual >= next_item_size * 2 {
                let post3 = post_residual - next_item_size * 2;
                if post3 == 0 { score -= 22.0; } else if post3 <= 3 { score -= 12.0; }
            }
            let chain = post_residual / next_item_size;
            if chain >= 2 { score -= (chain.min(4)) as f64 * 6.0; }
        } else {
            // next item won't fit here: penalize near-fitting gaps
            let gap = next_item_size - post_residual;
            if post_residual > 0 {
                if gap <= 3 { score += 40.0; }
                else if gap <= 8 { score += 14.0; }
                if gap as f64 > mean_residual * 0.5 { score += 12.0; }
                if post_residual < 15 { score += 30.0; }
                if post_residual as f64 > mean_residual * 1.4 { score -= 10.0; }
            }
            if post_residual % 10 == 0 { score -= 12.0; }
        }
    }

    // Compaction pressure
    score += open_bins_count as f64 * 0.8;

    // Last-chance bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 50.0;
    }

    // Tightness via relative fill
    score -= (item_size as f64 / bin_residual.max(1) as f64) * 30.0;

    // Consolidate slack: prefer below-average residuals
    if bin_residual < bin_capacity {
        score += (mean_residual - bin_residual as f64) * 1.2;
        let dead_ratio = post_residual as f64 / cap_f;
        if dead_ratio < 0.03 { score -= 30.0; }
        else if dead_ratio < 0.08 { score -= 12.0; }
        else if dead_ratio > 0.35 { score += 22.0; }
        else if dead_ratio > 0.25 { score += 10.0; }
        if post_residual > 0 && post_residual < 6 { score -= 18.0; }
        if item_size == bin_residual { score -= 40.0; }
        if post_residual > 0 {
            let mres = mean_residual.max(1.0);
            let dist = (post_residual as f64 - mres).abs();
            score += dist * 0.3;
        }
    }

    // NEW-BIN CANDIDATE handling
    if bin_residual == bin_capacity {
        let avg_fill = 1.0 - (mean_residual / cap_f);
        let newbin_waste = (bin_capacity - item_size) as f64;
        score += 200.0 - avg_fill * 300.0 - progress * 60.0;
        if item_size as f64 / cap_f > 0.75 { score -= 55.0; }
        if item_size >= bin_capacity * 3 / 4 { score -= 45.0; }
        if bin_capacity - item_size <= 4 { score -= 65.0; }
        if item_size as f64 > mean_residual { score -= 30.0; }
        if newbin_waste < mean_residual * 0.5 { score -= 30.0; }
        if next_item_size > 0 {
            let leftover = bin_capacity - item_size;
            if leftover >= next_item_size {
                let tail = leftover % next_item_size;
                if tail == 0 { score -= 12.0; }
                else if tail <= 4 { score -= 16.0; }
                if leftover - next_item_size <= 6 { score -= 35.0; }
            } else if leftover < 10 {
                score += 18.0;
            }
        }
        if fitting_bins_count > 3 { score += (fitting_bins_count.min(6) as f64) * 7.0; }
        // late stream: resist opening bins unless waste is small
        if progress > 0.6 {
            let waste_tol = (1.0 - progress) * cap_f * 0.35;
            if newbin_waste > waste_tol && fitting_bins_count > 0 {
                score += 12.0 + progress * 20.0;
            }
        }
        if progress < 0.1 { score -= 5.0; }
    }

    // Mild early diversity nudge for open bins
    if progress < 0.1 && bin_residual < bin_capacity { score += 3.0; }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
