pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps (1..=9) are heavily penalized,
    // since item sizes are >= 10 and such gaps can never be filled.
    if post_residual > 0 && post_residual < 10 {
        score += 40.0 + (10 - post_residual) as f64 * 3.0;
    }

    // Perfect fit is strongly rewarded.
    if post_residual == 0 {
        score -= 60.0;
    }

    // Tight fit: item consumes most of the bin's residual.
    let fill_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= fill_ratio * 15.0;

    // Lookahead: if the next item fits exactly in the post residual, reward.
    if next_item_size > 0 && next_item_size <= post_residual {
        score -= 8.0;
        if next_item_size == post_residual {
            score -= 20.0;
        }
    }
    // Lookahead conflict: next item would fit here but only barely,
    // leaving a dead gap for it -> penalize.
    if next_item_size > 0 && post_residual > 0 && next_item_size > post_residual && next_item_size < post_residual + 10 {
        score += 10.0;
    }

    // Last-chance bin: if this is the only bin that fits, avoid opening a new bin
    // unless the fit is truly terrible.
    if fitting_bins_count == 1 && post_residual < bin_capacity {
        score -= 25.0;
        // still avoid creating dead space even as last resort
        if post_residual > 0 && post_residual < 10 {
            score += 35.0;
        }
    }

    // Open bins pressure: many open bins -> prefer consolidating into existing bins,
    // penalize opening yet another bin (new-bin candidate has bin_residual == bin_capacity).
    if bin_residual == bin_capacity {
        score += 12.0 + open_bins_count as f64 * 4.0;
        // Late in the stream, opening new bins is less attractive.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += progress * 10.0;
    } else {
        score -= 3.0;
    }

    // Prefer bins with residual close to the mean (keep residuals balanced),
    // but favor bins with less residual (more full) overall.
    score += (bin_residual as f64 - mean_residual) * 0.15;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Aggressive 2-step lookahead: reward exact match of post_residual with next item
    if next_item_size > 0 {
        let diff = (post_residual as i64 - next_item_size as i64).unsigned_abs();
        // Exact fit for the next item -> very strong reward
        if diff == 0 {
            score -= 200.0;
        } else {
            // Penalize gap between post_residual and next item size
            score += diff as f64 * 0.8;
            // If next item fits exactly into current residual (item then next both fit well)
            if bin_residual >= item_size + next_item_size {
                score -= 40.0;
            }
        }
        // Dead space that neither current nor next item can use
        if post_residual < next_item_size && post_residual > 0 {
            score += (post_residual as f64) * 0.5;
        }
    } else {
        // Last item: prefer tightest packing
        score += post_residual as f64 * 0.1;
    }

    // Compare post_residual against mean residual: leaving less than average is good
    score -= (mean_residual - post_residual as f64) * 0.3;

    // Last-chance bin: if this is the only fitting bin, strongly prefer using it
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 60.0;
    }

    // New-bin candidate: only attractive when no open bin fits decently
    if bin_residual == bin_capacity {
        let base = 90.0 + post_residual as f64;
        let penalty = if fitting_bins_count == 0 { -150.0 } else { 0.0 };
        score = base + penalty
            - (step_index as f64 / (total_items as f64).max(1.0)) * 10.0
            + open_bins_count as f64 * 2.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tight fit reward: fraction of bin consumed by this item.
    let fill = item_size as f64 / bin_capacity as f64;
    score -= 30.0 * fill;

    // Penalize small but wasteful post-residuals (dead space below min item size).
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Lookahead: reward if the next item fits exactly into the post-residual.
    if next_item_size > 0 && post_residual >= next_item_size {
        let gap = (post_residual - next_item_size) as f64;
        score -= 18.0 * (1.0 - gap / bin_capacity as f64);
    } else if next_item_size > 0 && post_residual < next_item_size {
        score += 8.0 * (1.0 - post_residual as f64 / bin_capacity as f64);
    }

    // Last-chance bin: strongly favor using the only fitting bin.
    if fitting_bins_count == 1 {
        score -= 40.0;
    } else if fitting_bins_count > 1 {
        score += 3.0 * (fitting_bins_count as f64 - 1.0);
    }

    // Time horizon: early on, consolidate into open bins; late, prefer new bins for balance.
    let progress = step_index as f64 / total_items.max(1) as f64;

    // New-bin candidate handling: only attractive when open bins are fragmented or fit is poor.
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        let fragmentation = (mean_residual - post_residual as f64).abs();
        let poor_fit = fill < 0.4 && post_residual < next_item_size as f64;
        score = 60.0
            + 20.0 * progress
            - if poor_fit { 45.0 } else { 0.0 }
            - if open_bins_count > 6 { 10.0 } else { 0.0 }
            + fragmentation * 0.2;
    }

    // Discourage scattering across many bins when mean residual is already small.
    if !is_new_bin {
        score += 0.15 * (open_bins_count as f64) * (1.0 - progress);
        score -= 0.1 * mean_residual * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
