pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let norm_post = post_residual as f64 / bin_capacity as f64;
    let norm_item = item_size as f64 / bin_capacity as f64;

    // Smooth polynomial coupling: penalize large post_residual more strongly as stream progresses.
    let poly = norm_post * norm_post * (1.0 + 3.0 * progress);
    score += 2.0 * poly * bin_capacity as f64;

    // Reward tight fits (small post_residual) with a smooth quadratic discount.
    score -= 4.0 * (1.0 - norm_post) * (1.0 - norm_post) * (1.0 + progress);

    // Smooth lookahead interaction: if the next item fits the post residual, reward.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if nxt <= post_residual as f64 {
            let fit_quality = 1.0 - (post_residual as f64 - nxt) / bin_capacity as f64;
            score -= 3.0 * fit_quality * fit_quality;
        } else {
            score += 1.5 * progress;
        }
    }

    // Penalize when this is the only fitting bin but fit is poor (last-chance pressure).
    if fitting_bins_count == 1 && norm_post > 0.0 {
        score -= 2.0 * (1.0 - norm_post) * (1.0 + 2.0 * progress);
    }

    // Smooth mean-residual coupling: prefer bins below mean residual (tighter bins).
    score += 0.5 * (mean_residual - post_residual as f64) / bin_capacity as f64 * (1.0 + progress);

    // Mild penalty for spreading across many open bins late in the stream.
    score += 0.1 * open_bins_count as f64 * progress * norm_post;

    // New-bin candidate: only attractive when fit is terrible.
    if bin_residual == bin_capacity {
        score += 3.0 * (1.0 - norm_item) * (1.0 - norm_item) + 1.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic classes: partition post_residual into residue classes mod 10.
    // Residuals that are "harmonically useful" (multiples of 10, or >= typical
    // small item sizes) are dead-space-friendly; odd/prime-ish residues are waste.
    let res = post_residual as i64;
    let res_mod = (post_residual % 10) as i64;
    let res_div = (post_residual / 10) as i64;

    // Perfect-fill reward: residual 0 is ideal.
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Reward residuals that are multiples of 10 (clean harmonic slots).
    score -= (10.0 - res_mod as f64) * 0.5;

    // Penalize small unusable residues (1..9) more aggressively as they shrink.
    if res_mod > 0 && post_residual < 10 {
        score += 60.0;
    }

    // Harmonic ladder: reward residual slots in {10,20,30,50,70,100} classes
    // since many item sizes (10..80) align with these.
    let harmonic = matches!(post_residual, 10 | 20 | 30 | 50 | 70);
    if harmonic {
        score -= 25.0;
    }

    // Lookahead coupling: if next item fits exactly into post_residual,
    // strongly favor this bin (chained perfect fit).
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 400.0;
