pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: gaps that no item can plausibly use are toxic.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    } else if post_residual < 20 {
        score += 20.0;
    } else if post_residual < 30 {
        score += 8.0;
    }

    // Reward near-perfect fits.
    if post_residual == 0 {
        score -= 50.0;
    } else if post_residual <= 10 {
        score -= 10.0;
    }

    // Lookahead coupling: if the next item fits into the post residual, reward it.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 12.0;
    }
    // Penalize if next item would exactly exhaust the bin but this placement creates waste now.
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size && post_residual < 10 {
        score += 15.0;
    }

    // Last-chance bin: strongly favor using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // Open-bin pressure: many open bins -> prefer consolidating into existing bins.
    let pressure = (open_bins_count as f64).ln().max(0.0) * 6.0;
    score += pressure;

    // New empty bin candidate: make it unattractive unless nothing fits well.
    if bin_residual == bin_capacity {
        score += 45.0 + pressure;
    }

    // Mild preference for bins tighter than average (best-fit flavor).
    score += (mean_residual - bin_residual as f64) * 0.3;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let score = (post_residual as f64) * 1.11;
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap_f = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Tiered dead-space avoidance (stronger, borrowed from best)
    if post_residual == 0 {
        score -= 800.0;
    } else if post_residual <= 3 {
        score -= 400.0;
    } else if post_residual <= 12 {
        score -= 90.0;
    } else if post_residual < 20 {
        score += 18.0;
    } else if post_residual < 30 {
        score += 18.0 + (30 - post_residual) as f64 * 0.6;
    }

    // Lookahead: exact and near-exact fits for the next item
    if next_item_size > 0 {
        let nres = next_item_size as u32;
        if nres == post_residual {
            score -= 700.0;
        } else if nres <= post_residual {
            let post2 = post_residual - nres;
            score -= 120.0 - (post2 as f64) * 2.0;
            if post2 == 0 { score -= 100.0; }
            if post2 > 0 && post2 < 5 { score -= 28.0; }
            if post2 % 10 == 0 && post2 > 0 { score -= 20.0; }
            if post2 >= 20 && post2 % 5 == 0 { score -= 12.0; }
            if post_residual >= nres * 2 {
                let post3 = post_residual - nres * 2;
                if post3 == 0 { score -= 26.0; }
                else if post3 <= 3 { score -= 12.0; }
            }
            if post_residual % nres == 0 { score -= 18.0; }
            let chain = post_residual / nres;
            if chain >= 2 { score -= (chain.min(4)) as f64 * 6.0; }
        } else {
            let gap = (nres - post_residual) as f64;
            if post_residual > 0 {
                if gap <= 3.0 { score += 35.0; }
                else if gap <= 8.0 { score += 12.0; }
                if gap > mean_residual * 0.5 { score += 14.0; }
                if gap > mean_residual * 0.6 && fitting_bins_count > 2 { score += gap * 0.8; }
                if post_residual as f64 > mean_residual * 1.4 { score -= 12.0; }
                if post_residual < bin_capacity / 10 { score += 18.0; }
                let dead_frac = post_residual as f64 / cap_f;
                if gap > 12.0 { score += dead_frac * 90.0; }
            }
        }
    }

    // Compaction pressure scaled by open bins
    score += open_bins_count as f64 * 0.8;

    // Last-chance bin: strongly favor using it
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 45.0;
    }

    // Tightness via relative fill
    score -= (item_size as f64 / bin_residual.max(1) as f64) * 30.0;

    // Consolidate slack: prefer bins below-average residual
    if bin_residual < bin_capacity {
        score += (mean_residual - bin_residual as f64) * 1.2;
        let dead_ratio = post_residual as f64 / cap_f;
        if dead_ratio < 0.03 { score -= 38.0; }
        else if dead_ratio < 0.08 { score -= 14.0; }
        else if dead_ratio > 0.35 { score += 24.0; }
        else if dead_ratio > 0.25 { score += 10.0; }
        if item_size == bin_residual { score -= 45.0; }
        if post_residual > 0 && post_residual % 10 == 0 { score -= 10.0; }
        if post_residual > 0 && post_residual % 5 == 0 && post_residual <= 30 { score -= 8.0; }
    }

    // NEW-BIN CANDIDATE handling
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let avg_fill = 1.0 - (mean_residual / cap_f);
        let newbin_waste = (bin_capacity - item_size) as f64;
        score += 250.0 - avg_fill * 330.0 - progress * 65.0;
        if item_size as f64 / cap_f > 0.75 { score -= 55.0; }
        if item_size >= bin_capacity * 3 / 4 { score -= 55.0; }
        if item_size as f64 > mean_residual { score -= 40.0; }
        if newbin_waste < mean_residual * 0.5 { score -= 30.0; }
        if bin_capacity - item_size <= 4 { score -= 70.0; }
        if next_item_size > 0 && (bin_capacity - item_size) >= next_item_size
            && (bin_capacity - item_size) - next_item_size <= 6 {
            score -= 38.0;
        }
        if next_item_size > 0 {
            let leftover = bin_capacity - item_size;
            if leftover >= next_item_size {
                let tail = leftover % next_item_size;
                if tail == 0 { score -= 12.0; }
                else if tail <= 4 { score -= 16.0; }
            }
            if leftover < next_item_size && leftover < 10 { score += 18.0; }
        }
        if fitting_bins_count > 0 {
            score += (fitting_bins_count.min(6) as f64) * 8.0 + 15.0;
        }
        if item_size as f64 / cap_f > 0.85 && mean_residual > cap_f * 0.35 { score -= 40.0; }
        if progress > 0.6 {
            let waste_tol = (1.0 - progress) * cap_f * 0.35;
            if newbin_waste > waste_tol && fitting_bins_count > 0 {
                score += 10.0 + progress * 22.0;
            }
        }
        if progress < 0.1 { score -= 5.0; }
    } else {
        let progress = step_index as f64 / total_items.max(1) as f64;
        if progress < 0.1 { score += 3.0; }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits (small post_residual) non-linearly.
    let tightness = 1.0 - (post_residual as f64) / (bin_capacity as f64);
    score -= 12.0 * tightness * tightness;

    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 50.0;
    }

    // Aggressive 2-step lookahead: strongly reward bins whose post_residual
    // can exactly host the next item (chain packing).
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 40.0;
        } else if post_residual >= next_item_size {
            let slack = (post_residual - next_item_size) as f64;
            score -= 15.0 * (1.0 - slack / (bin_capacity as f64));
        } else {
            // Next item cannot fit here: penalize proportionally to leftover waste.
            let gap = (next_item_size - post_residual) as f64;
            score += 0.3 * gap;
        }
    }

    // Compare post_residual against mean residual: leaving this bin far below
    // the mean creates fragmented small residuals; prefer bins that stay near it.
    let dev = (post_residual as f64 - mean_residual).abs();
    score += 0.15 * dev;

    // Last-chance bin: if this is the only bin that fits, strongly prefer using it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate handling: opening a new bin is only attractive when no
    // open bin fits well (post_residual large relative to item) or many bins
    // are already open with fragmented residuals.
    if bin_residual == bin_capacity {
        // Base cost of a fresh bin.
        score += 30.0;
        // More attractive when open bins are heavily fragmented (high mean residual
        // spread) and many bins exist.
        score -= 0.2 * open_bins_count as f64;
        // Discourage opening a new bin if the next item is small enough to use
        // leftovers elsewhere.
        if next_item_size > 0 && next_item_size <= mean_residual {
            score += 10.0;
        }
        // If this item would leave a large residual anyway, a fresh bin is fine.
        if post_residual >= 40 {
            score -= 15.0;
        }
    }

    // Mild stream-progression pressure: later in the stream, consolidation matters
    // more; slightly favor reusing existing bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual < bin_capacity {
        score -= 5.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: relative fill of the bin.
    let fill_ratio = item_size as f64 / bin_capacity as f64;
    score -= 18.0 * fill_ratio;

    // Penalize large dead space relative to capacity, superlinearly.
    let dead = post_residual as f64 / bin_capacity as f64;
    score += 12.0 * dead * dead;

    // Lookahead: reward bins whose post-residual can host the next item.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 8.0;
            // Extra reward if the next item fills the leftover nearly exactly.
            let pair_waste = (post_residual - next_item_size) as f64;
            score -= 6.0 * (1.0 - pair_waste / bin_capacity as f64);
        } else {
            // Leftover too small for next item: penalize proportionally.
            score += 5.0 * (1.0 - post_residual as f64 / next_item_size.max(1) as f64);
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 15.0;
    } else {
        // Many fitting bins: prefer the one that preserves flexibility elsewhere.
        score += 2.0 * (fitting_bins_count as f64).ln();
    }

    // Prefer bins with residuals close to the item (best-fit coupling).
    let gap = (bin_residual as f64 - item_size as f64) / bin_capacity as f64;
    score += 10.0 * gap * gap;

    // Global state: when many bins are open with large mean residual,
    // discourage opening new bins and favor consolidating into existing ones.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity {
        // New-bin candidate: penalize more when open bins have slack and late in stream.
        let slack = (mean_residual / bin_capacity as f64).clamp(0.0, 1.0);
        score += 6.0 + 10.0 * slack + 8.0 * progress;
    } else {
        // Reward using existing bins when mean residual is high.
        score -= 4.0 * (mean_residual / bin_capacity as f64).clamp(0.0, 1.0);
    }

    // Slight time pressure: early on, be more exploratory (accept looser fits);
    // late in the stream, tighten packing aggressively.
    score += 6.0 * (1.0 - progress) * dead;

    // Small penalty for accumulating many open bins.
    score += 0.5 * (open_bins_count as f64).ln().max(0.0);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let cap = bin_capacity as f64;
    let pr = post_residual as f64 / cap;
    let is_new_bin = if bin_residual == bin_capacity { 1.0 } else { 0.0 };

    // Smooth non-linear polynomial coupling of post_residual with stream progress
    let base = pr * pr * (1.0 + 3.0 * progress * (1.0 - progress)) + pr * (0.5 + progress);

    // Penalize dead space more strongly as the stream matures (smooth cubic in progress)
    let dead_penalty = pr * pr * pr * (2.0 + 4.0 * progress * progress);

    // Reward tight fits (small post_residual) with a smooth saturating term
    let tight_bonus = -(1.0 - pr).powi(4) * (1.5 + 2.0 * (1.0 - progress));

    // Last-chance bin: smooth reward via fitting_bins_count
    let last_chance = -(1.0 / (fitting_bins_count as f64 + 1.0)) * (1.0 + progress);

    // Lookahead coupling: reward residual that pairs with next item size (smooth)
    let n = next_item_size as f64;
    let lookahead = if n > 0.0 {
        let diff = (pr * cap - n).abs() / cap;
        -0.8 * (1.0 - diff) * (1.0 - diff) * (1.0 - 0.5 * progress)
    } else {
        0.0
    };

    // New-bin candidate: penalize mildly early, less late (smooth in progress)
    let new_bin_pen = is_new_bin * (3.0 - 2.0 * progress) * (1.0 + mean_residual / cap) * 0.5;

    base + dead_penalty + tight_bonus + last_chance + lookahead + new_bin_pen
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: dead-space quality via integer division
    // into capacity-fraction classes (C/16 buckets). Small classes are good.
    let class = (post_residual * 16) / bin_capacity; // 0..=16
    let class_bonus: f64 = match class {
        0 => 60.0,                       // perfect fit
        1 => 35.0,                       // nearly perfect
        2 => 18.0,
        3 => 8.0,
        4 => 2.0,
        5 => -4.0,
        6 => -10.0,
        7 => -16.0,
        8 => -22.0,                      // half-full leftover: worst class
        _ => -18.0 - (class as f64),
    };
    score -= class_bonus;

    // Reward exact fit strongly
    if post_residual == 0 {
        score -= 200.0;
    }

    // Lookahead coupling: does post_residual accommodate next item's class?
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            // next item fits here: strong reward, scaled by tightness
            let slack = (post_residual - next_item_size) as f64;
            score -= 25.0 + 20.0 * (1.0 - slack / bin_capacity as f64);
            // harmonic match: next item leaves a small class too
            let next_post = post_residual - next_item_size;
            let nclass = (next_post * 16) / bin_capacity;
            if nclass <= 2 {
                score -= 20.0;
            }
        } else {
            // next item won't fit here: mild penalty proportional to gap
            let gap = (next_item_size - post_residual) as f64;
            score += 0.3 * gap.min(30.0);
        }
    } else {
        // last item: just minimize waste
        score -= 30.0;
    }

    // Last-chance bin: strongly prefer using it over opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 80.0;
    }

    // New-bin candidate logic: opening a new bin is only attractive when the
    // item fits poorly everywhere (large post_residual class) and many bins
    // are already open. Otherwise penalize spreading.
    if bin_residual == bin_capacity {
        let poor_fit = if post_residual as f64 > mean_residual { 1.0 } else { 0.0 };
        let pressure = (open_bins_count as f64).min(20.0) / 20.0;
        let progress = step_index as f64 / (total_items.max(1) as f64);
        // base penalty keeps consolidation preferred
        score += 90.0
            - 55.0 * poor_fit
            - 25.0 * pressure
            - 15.0 * progress;
        if next_item_size > 0 && next_item_size <= post_residual {
            // fresh bin serves next item well too
            score -= 20.0;
        }
    }

    // Slight preference for bins with below-average residual (denser bins)
    score += 0.15 * (bin_residual as f64 - mean_residual);

    // Tiny tie-break toward earlier progress (stable ordering)
    score += 0.001 * (step_index as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let score = post_residual as f64;
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals that are too small to hold
    // typical future items are "dead space". Penalize them nonlinearly.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0 - (post_residual as f64) * 5.0; // gaps of 1..9 are nearly useless
    }

    // Reward perfect and near-perfect fits strongly.
    if post_residual == 0 {
        score -= 50.0;
    } else if post_residual <= 5 {
        score -= 20.0;
    }

    // Dead-space zone: residual in (10, 20) can only fit tiny items.
    if post_residual > 10 && post_residual < 20 {
        score += 15.0;
    }

    // Lookahead coupling: if the next item fits exactly in the post residual,
    // this placement chains nicely; reward it.
    if next_item_size > 0 && post_residual >= next_item_size {
        let gap = post_residual - next_item_size;
        score -= 12.0 - (gap as f64) * 0.3;
    }
    // If next item cannot fit anywhere afterward, penalize leaving a gap
    // smaller than the next item (wasted capacity).
    if next_item_size > post_residual && post_residual > 0 {
        score += 6.0;
    }

    // Last-chance bin: if this is the only bin that fits, strongly favor
    // using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 25.0;
    }

    // Open-bin pressure: with many open bins, discourage spreading into
    // fresh bins; concentrate load.
    score += (open_bins_count as f64) * 0.8;

    // New-bin candidate handling: an empty bin has bin_residual == bin_capacity.
    // Prefer it only when the current item fits poorly everywhere else,
    // i.e. when post_residual here would be a large awkward gap.
    if bin_residual == bin_capacity {
        // Baseline for a fresh bin: moderate score, lowered by open-bin pressure
        // (opening new bins is worse when many bins are already open).
        score = 45.0 + (open_bins_count as f64) * 1.5;
        // A new bin is more attractive early in the stream.
        if total_items > 0 {
            score -= 20.0 * (1.0 - step_index as f64 / total_items as f64);
        }
        // If the next item is small, a fresh bin can absorb it well.
        if next_item_size > 0 && next_item_size <= 30 {
            score -= 5.0;
        }
    }

    // Slight tilt toward bins with above-average residual (use roomy bins first,
    // keep tight bins for tight fits).
    score += (mean_residual - post_residual as f64) * 0.15;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong reward for exact or near-exact fit with the NEXT item (2-step lookahead).
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 60.0;
        } else if post_residual > next_item_size {
            // Reward proportional to how well the next item fills the remaining space.
            let fill = next_item_size as f64 / post_residual as f64;
            score -= 40.0 * fill;
        } else {
            // Next item cannot fit here: penalize proportionally to the leftover gap.
            let gap = (next_item_size - post_residual) as f64;
            score += gap * 0.4;
        }
    } else {
        // Last item: prefer bins that end emptier is irrelevant; prefer tight fit now.
        score -= 10.0;
    }

    // Favor bins whose residual is close to (below) mean residual — balanced packing.
    let dev = post_residual as f64 - mean_residual;
    score += 0.25 * dev;

    // Penalize large dead space that few items could ever use.
    if post_residual < 10 {
        score -= 15.0;
    } else if post_residual > 50 {
        score += 0.3 * (post_residual as f64 - 50.0);
    }

    // Last-chance bin: strong bonus to avoid opening a new bin unnecessarily.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 25.0;
    }

    // New-bin candidate: make it unattractive unless no good fit exists.
    if bin_residual == bin_capacity {
        score += 45.0;
        // But if the current item perfectly matches an empty bin with the next item
        // (item + next fills it), opening is reasonable.
        if next_item_size > 0 && item_size + next_item_size == bin_capacity {
            score -= 70.0;
        }
        if next_item_size == 0 && item_size == bin_capacity {
            score -= 70.0;
        }
    }

    // Slight late-stream conservatism: consolidate into fewer bins as stream ends.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 5.0 * progress * (open_bins_count as f64).ln().max(0.0) * 0.1;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap_f = bin_capacity as f64;
    let progress = step_index as f64 / total_items.max(1) as f64;
    let mut score = post_residual as f64;

    // Tiered dead-space avoidance (strengthened toward best-known magnitudes)
    if post_residual == 0 {
        score -= 1180.0;
    } else if post_residual <= 3 {
        score -= 500.0;
    } else if post_residual <= 12 {
        score -= 98.0;
    } else if post_residual < 20 {
        score += 18.0;
    } else if post_residual < 30 {
        score += 18.0 + (30 - post_residual) as f64 * 0.6;
    }

    // Lookahead: exact and near-exact fits for next item
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 900.0;
        } else if next_item_size <= post_residual {
            let post2 = post_residual - next_item_size;
            score -= 135.0 - (post2 as f64) * 2.0;
            if post2 == 0 { score -= 110.0; }
            if post2 > 0 && post2 < 5 { score -= 28.0; }
            if post2 > 0 && post2 <= 2 { score -= 14.0; }
            if post2 % 10 == 0 && post2 > 0 { score -= 28.0; }
            if post2 >= 20 && post2 % 5 == 0 { score -= 12.0; }
            if post_residual % next_item_size == 0 { score -= 18.0; }
            if post_residual >= next_item_size * 2 {
                let post3 = post_residual - next_item_size * 2;
                if post3 == 0 { score -= 26.0; } else if post3 <= 3 { score -= 12.0; }
            }
            let chain = post_residual / next_item_size;
            if chain >= 2 { score -= (chain.min(4)) as f64 * 6.0; }
        } else {
            // next item won't fit here
            let gap = (next_item_size - post_residual) as f64;
            if post_residual > 0 {
                if gap <= 3.0 { score += 35.0; }
                else if gap <= 8.0 { score += 12.0; }
                if gap <= 5.0 { score += (6.0 - gap) * 4.0; }
                if gap > mean_residual * 0.6 && fitting_bins_count > 2 { score += gap * 0.8; }
                if post_residual as f64 > mean_residual * 1.4 { score -= 12.0; }
            }
        }
    }

    // Compaction pressure scaled by open bins
    score += open_bins_count as f64 * 0.8;

    // Last-chance bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 45.0;
    }

    if bin_residual == bin_capacity {
        // NEW-BIN CANDIDATE
        let avg_fill = 1.0 - (mean_residual / cap_f);
        score += 250.0 - avg_fill * 330.0 - progress * 65.0;
        let newbin_waste = (bin_capacity - item_size) as f64;
        if item_size as f64 > mean_residual { score -= 45.0; }
        if item_size >= bin_capacity * 3 / 4 { score -= 55.0; }
        if bin_capacity - item_size <= 4 { score -= 70.0; }
        if fitting_bins_count > 0 {
            score += (fitting_bins_count.min(5) as f64) * 9.0 + 20.0;
            let snug = item_size as f64 / bin_residual.max(1) as f64;
            if snug > 0.9 { score += 40.0; }
            if snug > 0.95 { score += 28.0; }
        }
        if next_item_size > 0 {
            let leftover = bin_capacity - item_size;
            if leftover >= next_item_size {
                let tail = leftover % next_item_size;
                if tail == 0 { score -= 10.0; }
                else if tail <= 4 { score -= 16.0; }
                if leftover - next_item_size <= 6 { score -= 38.0; }
            } else if leftover < 10 {
                score += 18.0;
            }
        }
        if newbin_waste > 0.0 && newbin_waste < mean_residual * 0.6 { score -= 30.0; }
        if fitting_bins_count > 0 {
            let best_alt = if item_size as f64 <= mean_residual { mean_residual - item_size as f64 } else { mean_residual };
            if newbin_waste > best_alt + cap_f * 0.08 { score += 22.0; }
            if newbin_waste > best_alt + cap_f * 0.2 { score += 14.0; }
        }
        if progress > 0.6 {
            let waste_tol = (1.0 - progress) * cap_f * 0.35;
            if newbin_waste > waste_tol && fitting_bins_count > 0 {
                score += 10.0 + progress * 22.0;
            }
        }
    } else {
        // Existing-bin branch (borrowed consolidation logic)
        let tightness = 1.0 - (item_size as f64 / bin_residual.max(1) as f64);
        score += tightness * 85.0;
        score += (mean_residual - bin_residual as f64) * 1.5;
        if item_size == bin_residual { score -= 45.0; }
        let dead_ratio = post_residual as f64 / cap_f;
        if dead_ratio < 0.03 { score -= 38.0; }
        else if dead_ratio < 0.08 { score -= 14.0; }
        else if dead_ratio > 0.35 { score += 24.0; }
        else if dead_ratio > 0.25 { score += 10.0; }
        if post_residual > 0 {
            let mres = mean_residual.max(1.0);
            let dist = (post_residual as f64 - mres).abs();
            score += dist * 0.35;
            if dist < cap_f * 0.03 { score -= 10.0; }
            if (post_residual as f64) < mres * 0.25 { score -= 15.0; }
            if post_residual < 6 { score -= 22.0; }
            if next_item_size > 0 && post_residual < next_item_size {
                let wasted = next_item_size as f64 - post_residual as f64;
                score += wasted * 0.6;
                let unusable = (next_item_size - post_residual) > 12;
                if unusable {
                    score += dead_ratio * 90.0;
                } else {
                    score += (1.0 - progress) * 14.0;
                }
            }
            if next_item_size > 0 && post_residual >= next_item_size {
                let reuse = (post_residual / next_item_size) as f64 * (next_item_size as f64 / cap_f);
                score -= reuse * 22.0;
            }
            if post_residual % 5 == 0 && post_residual <= 30 { score -= 8.0; }
        }
        if fitting_bins_count <= 2 && post_residual > 0 { score -= 8.0; }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
