pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tightness reward: favor bins where the item fills a large fraction of residual.
    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 30.0 * fit_ratio * fit_ratio;

    // Penalize small unusable post-residuals (< 10, dead space) unless exact fit.
    if post_residual > 0 && post_residual < 10 {
        score += 8.0;
    }
    if post_residual == 0 {
        score -= 25.0; // perfect fit is excellent
    }

    // Last-chance bin: strongly favor the only bin that can fit the item.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 20.0;
    }

    // Lookahead: reward leaving post_residual that can host the next item exactly.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 18.0;
        } else if post_residual >= next_item_size {
            score -= 4.0 * (post_residual as f64 / (post_residual as f64 + next_item_size as f64));
        } else {
            score += 3.0; // next item won't fit here; mild penalty for waste
        }
    }

    // Global pressure: many open bins with low mean residual -> prefer consolidation.
    let pressure = open_bins_count as f64 / (mean_residual.max(1.0) / 10.0 + 1.0);
    if bin_residual < bin_capacity {
        score -= 2.0 * pressure.min(10.0);
    }

    // New-bin candidate logic: only attractive when no open bin fits well
    // (poor fits into existing bins create dead space) or stream is early.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let bad_fit = fit_ratio < 0.5;
        if bad_fit || fitting_bins_count == 0 {
            score -= 15.0 + 10.0 * (1.0 - progress);
        } else {
            score += 12.0; // keep using existing bins when they fit decently
        }
    }

    // Time-horizon modulation: late in stream, be greedy about tight fits.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= 5.0 * progress * fit_ratio;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
