        let avg_fill = 1.0 - (mean_residual / cap_f);
        score += 240.0 - avg_fill * 320.0 - progress * 65.0;
        if item_size as f64 / cap_f > 0.75 { score -= 55.0; }
        if item_size >= bin_capacity * 3 / 4 { score -= 20.0; }
        if item_size as f64 > mean_residual { score -= 30.0; }
        if bin_capacity - item_size <= 4 { score -= 70.0; }
        if newbin_waste < mean_residual * 0.6 { score -= 30.0; }
        if next_item_size > 0 {
            let leftover = bin_capacity - item_size;
            if leftover >= next_item_size {
                let tail = leftover % next_item_size;
                if tail == 0 { score -= 26.0; }
                else if tail <= 4 { score -= 16.0; }
                if leftover - next_item_size <= 6 { score -= 35.0; }
            } else if leftover < 10 { score += 18.0; }
            if next_item_size >= bin_capacity / 2 { score -= 30.0; }
        }
        if fitting_bins_count > 0 {
