            }
        }
        if progress < 0.1 { score -= 5.0; }
    }

    // Mild early-stream diversity nudge
    if progress < 0.1 && bin_residual < bin_capacity { score += 3.0; }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = (step_index as f64 / total_items.max(1) as f64).clamp(0.0, 1.0);
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let pr_norm = pr / cap;

    // Base: prefer small post-residual, with a non-linear convex penalty
    // that grows super-linearly for medium dead space (hard to fill later).
    let mut score = pr_norm.powf(1.6 + 1.2 * progress) * cap;

    // Smooth interaction: dead space is worse as the stream progresses
    // (fewer future chances to fill gaps).
    score += 18.0 * pr_norm * (1.0 + progress * progress) * (1.0 - pr_norm);

    // Reward tight fits (post_residual near zero) with a smooth bump.
    score -= 25.0 * (-(pr_norm * pr_norm) / 0.02).exp();

    // Lookahead: if the next item fits exactly in the post-residual,
    // strongly reward; if it nearly fits, mildly penalize wasted potential.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if nxt <= pr {
            let slack = (pr - nxt) / cap;
            score -= 20.0 * (1.0 - slack).powi(2);
        } else {
            let gap = (nxt - pr) / cap;
            score += 8.0 * (1.0 - gap).exp();
        }
    }

    // Last-chance bonus: if this is the only bin that fits, avoid opening
    // a new bin unless the fit is terrible.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0 * (1.0 - pr_norm);
    }

    // New-bin candidate: neutral-ish, slightly penalized early, favored
    // when open bins are all heavily fragmented (high mean residual).
    if bin_residual == bin_capacity {
        let frag = (mean_residual / cap).clamp(0.0, 1.0);
        score = 30.0 + 20.0 * (1.0 - progress) - 25.0 * frag * frag;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let score = post_residual as f64 / bin_capacity.max(1) as f64;
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer tight fits (small post_residual).

    // Harmonic class of post_residual: dead space is worse when it falls
    // into "awkward" residue classes modulo small divisors (likely gaps).
    let pr = post_residual;
    if pr > 0 {
        // Penalize post-residuals that no plausible future item (1..=100) can use well
        // i.e., very small residuals are dead space unless nearly zero.
        if pr <= 10 {
            score += 12.0; // tiny dead space, almost unusable
        } else if pr <= 20 {
            score += 6.0;
        }
        // Modulo-10 classes: residuals divisible by 10 are "friendly"
        // (items often come in multiples of 10 in classic streams).
        if pr % 10 == 0 {
            score -= 4.0;
        } else if pr % 5 == 0 {
            score -= 2.0;
        } else {
            score += 2.0;
        }
        // Integer-division threshold: residuals in (50, 100) are half-full-ish,
        // still very reusable; residuals in (0, 30] risk being stranded.
        if pr > 50 {
            score -= 3.0;
        } else if pr <= 30 {
            score += 3.0;
        }
    } else {
        score -= 15.0; // perfect closure of the bin — strongly reward
    }

    // Lookahead coupling: reward if next item fits into the post-residual,
    // penalize if it doesn't (this bin would be useless for the next item).
    if next_item_size > 0 {
        if next_item_size <= pr {
            score -= 6.0;
            // harmonic bonus: exact modulo match between next item and residual
            if pr % next_item_size.max(1) == 0 {
                score -= 3.0;
            }
        } else {
            score += (next_item_size - pr) as f64 * 0.15;
        }
    }

    // Last-chance bonus: if this is the only bin that can fit the item,
    // strongly favor using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate handling: an empty bin should only win when existing
    // placements are poor. Penalize the fresh bin moderately; escalate penalty
    // late in the stream when consolidation matters, and when few bins are open.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score += 18.0 + 10.0 * progress + (open_bins_count.min(10) as f64);
    }

    // Mild preference for bins below mean residual (balance the pool) —
    // keeps a portfolio of usable mid-size residuals.
    let resid_f = bin_residual as f64;
    if resid_f < mean_residual {
        score -= 1.5;
    } else if resid_f > mean_residual + 20.0 {
        score += 1.5;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps are the worst outcome.
    // A residual gap is "unusable" if it is smaller than the smallest plausible item.
    // Penalize gaps in (0, 10) heavily, and gaps just below the next item size.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0; // tiny dead space: bin becomes nearly useless
    }

    // If the leftover can't fit the lookahead item but could fit a small item,
    // it's still acceptable; if it can't fit anything typical, penalize.
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        // leftover smaller than next item: mild penalty proportional to gap
        score += (next_item_size - post_residual) as f64 * 0.3;
    }

    // Reward perfect fits strongly.
    if post_residual == 0 {
        score -= 100.0;
    }

    // Reward leaving room for the next item (good chaining).
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 8.0;
    }

    // Last-chance bin pressure: if this is the only bin that fits, prefer using it
    // to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // Open bins pressure: when many bins are open, discourage spreading into
    // fresh bins; when few bins are open, opening new bins is cheaper.
    let ob = open_bins_count as f64;
    if bin_residual == bin_capacity {
        // New-bin candidate: base cost grows with number of open bins,
        // but relax when existing residuals are fragmented (mean residual low).
        score += 40.0 + 3.0 * ob - 0.2 * mean_residual;
        // If this is a last-chance situation, opening a new bin is fine.
        if fitting_bins_count == 0 {
            score -= 100.0;
        }
    } else {
        // Using an existing bin relieves bin-count pressure slightly.
        score -= 0.5 * ob;
    }

    // Early in the stream, opening bins is cheaper (no penalty adjustment needed);
    // late in the stream, consolidate more aggressively.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    if bin_residual == bin_capacity {
        score += 20.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer tight fits (small post_residual), but dead space that
    // cannot fit the next item is wasted — penalize it extra.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if (post_residual as f64 - nxt).abs() < 0.5 {
            // Perfect 2-step match: leave exactly room for next item.
            score -= 45.0;
        } else if post_residual >= next_item_size {
            // Room left for next item: mildly reward proportional closeness.
            let diff = post_residual as f64 - nxt;
            score -= 20.0 - (diff / bin_capacity as f64) * 15.0;
        } else {
            // Dead space: unusable for the lookahead item.
            let waste = nxt - post_residual as f64;
            score += waste * 0.6;
        }
    }

    // Relative-to-mean coupling: bins with residual near the mean are the
    // "typical" bins; placing there keeps the fleet homogeneous. Prefer
    // filling above-average-residual bins, penalize draining small ones.
    let dev = post_residual as f64 - mean_residual;
    score += dev * 0.25;

    // Last-chance bonus: if this is the only bin that fits, avoid forcing
    // a new bin unless the fit is terrible.
    if fitting_bins_count == 1 {
        score -= 12.0 + (item_size as f64 / bin_capacity as f64) * 10.0;
    }

    // New-bin candidate handling: an empty bin has post_residual == 99..
    // only attractive when no open bin fits well. Penalize opening a new
    // bin, more strongly when many bins are already open and stream is late.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score += 30.0 + open_bins_count as f64 * 2.0 + progress * 20.0;
        // But if next item is huge and this item is small, a fresh bin may
        // be the right pairing container — soften the penalty.
        if next_item_size >= 60 && item_size <= 40 {
            score -= 25.0;
        }
    }

    // Small late-stage tiebreak toward minimal post residual.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += post_residual as f64 * 0.1 * (1.0 - progress);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Penalize dead space that cannot fit typical items (wasted capacity).
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Lookahead: reward bins whose post-residual can still host the next item.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 6.0;
        } else {
            score += 8.0 * (1.0 - post_residual as f64 / bin_capacity as f64);
        }
        // Chain fit: post-residual can host next item AND leftover after that stays useful
        if post_residual >= next_item_size && post_residual - next_item_size >= 10 {
            score -= 3.0;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 12.0;
    }

    // Many open bins with slack: discourage fragmenting space further.
    if open_bins_count > 3 {
        score += 0.15 * open_bins_count as f64 * (1.0 - item_size as f64 / bin_capacity as f64);
    }

    // Compare residual to mean residual: prefer tighter-than-average bins.
    score -= 0.5 * (bin_residual as f64 - mean_residual);

    // Time horizon: early in stream, encourage consolidation; late, prefer exact fills.
    let t = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score *= 1.0 - 0.2 * t;

    // Reward near-perfect fits scaled by progress.
    let tightness = 1.0 - post_residual as f64 / bin_capacity as f64;
    score -= (2.0 + 6.0 * t) * tightness * tightness;

    // New-bin candidate: penalize opening a new bin unless existing fit is terrible.
    if bin_residual == bin_capacity {
        score += 10.0 + 0.5 * open_bins_count as f64;
        if post_residual > 0 && post_residual < 20 {
            score += 15.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let progress = (step_index as f64) / (total_items.max(1) as f64);
    let norm_post = post / cap;

    // Smooth polynomial coupling of post_residual with stream progress
    let poly = norm_post * norm_post * (1.0 + 2.0 * progress) + norm_post * (1.0 - progress);
    let mut score = post + 30.0 * poly;

    // Reward tight fits (small post_residual) with a smooth non-linear bonus
    let tightness = 1.0 - norm_post;
    score -= 40.0 * tightness * tightness * (1.0 + progress);

    // Penalize dead space that cannot fit the next item (smooth interaction)
    if next_item_size > 0 {
        let gap = (post - next_item_size as f64).max(0.0);
        score += 0.5 * gap * gap / cap * (1.0 + progress);
    }

    // Last-chance bonus: smooth reward when this is the only fitting bin
    if fitting_bins_count == 1 {
        score -= 10.0 + 20.0 * progress;
    }

    // Mild penalty tied to crowding of open bins
    score += (open_bins_count as f64).ln().max(0.0) * 2.0 * (1.0 - progress);

    // Deviation from mean residual (smooth quadratic)
    score += 0.2 * (post - mean_residual) * (post - mean_residual) / cap;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let mut score = post;

    // Exact fit is perfect.
    if post_residual == 0 {
        score -= 1000.0;
        return score;
    }

    // Harmonic classes of post_residual relative to capacity fractions.
    let frac = post / cap;
    let class = ((frac * 10.0).floor()) as i64; // 0..9 decile of leftover
    // Penalize dead space: leftover that cannot hold typical next items.
    if let Some(nx) = (next_item_size > 0).then_some(next_item_size) {
        if (post_residual as u64) < (nx as u64) {
            // leftover unusable by lookahead: strong penalty scaled by class
            score += 12.0 + 3.0 * class as f64;
        } else {
            // leftover fits lookahead exactly or snugly: reward
            let slack = post_residual - nx;
            if slack == 0 {
                score -= 60.0; // chains perfectly with lookahead
            } else if slack <= 10 {
                score -= 25.0;
            }
        }
        // Harmonic mod classes on next_item_size: big items (>=50) prefer large residuals
        let nx_class = nx / 25; // 0..3 harmonic tier
        match nx_class {
            0 => { if post_residual >= 40 { score -= 8.0; } }
            1 => { if post_residual >= 60 { score -= 10.0; } }
            2 => { if post_residual >= 80 { score -= 14.0; } }
            _ => { score += (post_residual as f64) * 0.05; }
        }
    }

    // Last chance: only this bin fits -> strong reward to avoid opening a bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 80.0;
    }

    // New-bin candidate: neutral-ish score; only chosen when open bins are bad.
    if bin_residual == bin_capacity {
        score = cap * 0.75 + 0.1 * open_bins_count as f64;
        if next_item_size > 0 && next_item_size >= 60 {
            score -= 15.0; // big lookahead favors fresh bin
        }
        return score;
    }

    // Prefer filling bins with small residuals (tight packing), harmonic penalty
    // on integer division of residual by 10 creating threshold steps.
    let decile = post_residual / 10;
    score += (decile as f64) * (decile as f64) * 0.15;

    // Mild preference to keep mean residual spread balanced.
    if (post - mean_residual).abs() > cap * 0.4 {
        score += 5.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap_f = bin_capacity as f64;
    let progress = step_index as f64 / total_items.max(1) as f64;
    let mut score = post_residual as f64;

    // Tiered dead-space avoidance (stronger, borrowed from best)
    if post_residual == 0 {
        score -= 1180.0;
    } else if post_residual <= 3 {
        score -= 500.0;
    } else if post_residual <= 12 {
        score -= 98.0;
    } else if post_residual < 20 {
        score += 18.0;
    } else if post_residual < 30 {
        score += 18.0 + (30 - post_residual) as f64 * 0.6;
    }

    // Lookahead on next item
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 900.0;
        } else if next_item_size <= post_residual {
            let post2 = post_residual - next_item_size;
            score -= 135.0 - (post2 as f64) * 2.0;
            if post2 == 0 { score -= 110.0; }
            if post2 > 0 && post2 < 5 { score -= 28.0; }
            if post2 > 0 && post2 <= 2 { score -= 14.0; }
            if post2 % 10 == 0 && post2 > 0 { score -= 28.0; }
            if post2 >= 20 && post2 % 5 == 0 { score -= 12.0; }
            if post_residual % next_item_size == 0 { score -= 18.0; }
            if post_residual >= next_item_size * 2 && post_residual - next_item_size * 2 <= 4 {
                score -= 20.0;
            }
            let chain = post_residual / next_item_size;
            if chain >= 2 { score -= (chain.min(4)) as f64 * 6.0; }
            if post2 > 0 && post2 <= next_item_size / 4 { score -= 10.0; }
        } else {
            let gap = (next_item_size - post_residual) as f64;
            score += 20.0;
            if post_residual > 0 && post_residual < 15 { score += 45.0; }
            if post_residual > 0 && gap <= 3.0 { score += 35.0; }
            if gap <= 8.0 { score += 12.0; }
            if gap > mean_residual * 0.5 { score += 14.0; }
            if post_residual as f64 > mean_residual * 1.4 { score -= 12.0; }
            // unusable dead-space penalty scaled by gap
            if post_residual > 0 && gap > 12.0 {
                score += (post_residual as f64 / cap_f) * 90.0;
            }
        }
    }

    // Compaction pressure
    score += open_bins_count as f64 * 0.8;

    if bin_residual < bin_capacity {
        // tightness + slack consolidation
        let tightness = 1.0 - (item_size as f64 / bin_residual.max(1) as f64);
        score += tightness * 85.0;
        score += (mean_residual - bin_residual as f64) * 1.5;
        let dead_ratio = post_residual as f64 / cap_f;
        if dead_ratio < 0.03 { score -= 38.0; }
        else if dead_ratio < 0.08 { score -= 14.0; }
        else if dead_ratio > 0.35 { score += 24.0; }
        else if dead_ratio > 0.25 { score += 10.0; }
        if item_size == bin_residual { score -= 45.0; }
        if post_residual > 0 && post_residual % 10 == 0 { score -= 10.0; }
        if post_residual > 0 && post_residual % 5 == 0 && post_residual <= 30 { score -= 8.0; }
        if post_residual > 0 && (post_residual as f64) < mean_residual * 0.25 { score -= 15.0; }
        if fitting_bins_count <= 2 && post_residual > 0 { score -= 8.0; }
        if next_item_size > 0 && post_residual >= next_item_size {
            let reuse = (post_residual / next_item_size) as f64 * (next_item_size as f64 / cap_f);
            score -= reuse * 22.0;
        }
        // distance from mean residual: prefer distinct useful sizes
        let dist = (post_residual as f64 - mean_residual.max(1.0)).abs();
        score += dist * 0.35;
        if dist < cap_f * 0.03 { score -= 10.0; }
        if progress < 0.1 { score += 3.0; }
    }

    // NEW-BIN CANDIDATE handling
    if bin_residual == bin_capacity {
        let leftover = bin_capacity - item_size;
        let newbin_waste = leftover as f64;
        let avg_fill = 1.0 - (mean_residual / cap_f);
        score += 250.0 - avg_fill * 330.0 - progress * 65.0;
        if item_size as f64 > mean_residual { score -= 45.0; }
        if fitting_bins_count > 0 {
            score += (fitting_bins_count as f64).min(5.0) * 9.0 + 20.0;
            let snug = item_size as f64 / bin_residual.max(1) as f64;
            if snug > 0.9 { score += 40.0; }
            if snug > 0.95 { score += 28.0; }
        }
        if item_size >= bin_capacity * 3 / 4 { score -= 55.0; }
        if leftover <= 4 { score -= 70.0; }
        if next_item_size > 0 {
            if leftover >= next_item_size {
                let tail = leftover % next_item_size;
                if tail == 0 { score -= 10.0; }
                else if tail <= 4 { score -= 16.0; }
                if leftover - next_item_size <= 6 { score -= 38.0; }
            } else if leftover < 10 {
                score += 18.0;
            }
        }
        if newbin_waste < mean_residual * 0.6 { score -= 30.0; }
        if fitting_bins_count > 0 {
            let best_alt = if item_size as f64 <= mean_residual { mean_residual - item_size as f64 } else { mean_residual };
            if newbin_waste > best_alt + cap_f * 0.08 { score += 22.0; }
            if newbin_waste > best_alt + cap_f * 0.2 { score += 14.0; }
        }
        if progress > 0.6 {
            let waste_tol = (1.0 - progress) * cap_f * 0.35;
            if newbin_waste > waste_tol && fitting_bins_count > 0 {
                score += 10.0 + progress * 22.0;
            }
        }
        if progress < 0.1 { score -= 5.0; }
    }

    // Last-chance bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 45.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps (1..=10) are heavily penalized.
    if post_residual > 0 && post_residual <= 10 {
        score += (11.0 - post_residual as f64) * 8.0;
    }
    // Perfect fit: strong reward.
    if post_residual == 0 {
        score -= 40.0;
    }
    // Reward tight fits relative to bin residual (high fill ratio).
    let fill_ratio = item_size as f64 / bin_residual as f64;
    score -= fill_ratio * 15.0;

    // Pressure from number of open bins: prefer compacting when many bins are open.
    score += open_bins_count as f64 * 0.5;

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 20.0;
    }

    // Lookahead: if next item can use the post residual, reward leaving it.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 10.0;
        } else if post_residual > 0 {
            score += 5.0;
        }
    }

    // New-bin candidate: only attractive when current bin would leave bad dead space
    // or fit is very loose.
    if bin_residual == bin_capacity {
        let dead = post_residual > 0 && post_residual <= 10;
        if dead {
            score -= 5.0; // fresh bin may be better than creating dead space
        } else {
            score += 25.0; // prefer existing bins on decent fits
        }
    }

    // Mild progression scaling: early stream, be slightly more conservative.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += (1.0 - progress) * 3.0;

