    // Last-chance bin: strongly favor using it
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 50.0;
    }

    // Tightness via relative fill (dead-space ratio shaping)
    let tightness = 1.0 - (item_size as f64 / bin_residual.max(1) as f64);
    score += tightness * 60.0;

    // Consolidate slack: prefer bins below average residual
    if bin_residual < bin_capacity {
        score += (mean_residual - bin_residual as f64) * 1.2;
        let dead_ratio = post_residual as f64 / cap_f;
        if dead_ratio < 0.03 { score -= 30.0; }
        else if dead_ratio > 0.30 { score += 20.0; }
    }

    // NEW-BIN CANDIDATE handling
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let avg_fill = 1.0 - (mean_residual / cap_f);
        let newbin_waste = (bin_capacity - item_size) as f64;
        score += 230.0 - avg_fill * 300.0 - progress * 60.0;
        // big items deserve a fresh bin when few alternatives fit well
        if item_size as f64 / cap_f > 0.75 { score -= 55.0; }
        if item_size as f64 / cap_f > 0.85 && mean_residual > cap_f * 0.35 { score -= 30.0; }
        if item_size as f64 > mean_residual { score -= 35.0; }
        if newbin_waste < mean_residual * 0.6 { score -= 30.0; }
        if bin_capacity - item_size <= 4 { score -= 60.0; }
        // fresh bin pairs perfectly with next item
        if next_item_size > 0 {
            let leftover = bin_capacity - item_size;
            if leftover >= next_item_size {
                if leftover - next_item_size <= 6 { score -= 38.0; }
                let tail = leftover % next_item_size;
                if tail == 0 { score -= 12.0; }
                else if tail <= 4 { score -= 14.0; }
            } else if leftover < 10 {
                score += 16.0;
            }
        }
        if fitting_bins_count > 0 {
            score += (fitting_bins_count.min(5) as f64) * 9.0 + 15.0;
            let snug = item_size as f64 / bin_residual.max(1) as f64;
            if snug > 0.9 { score += 35.0; }
            if snug > 0.95 { score += 25.0; }
        }
        // late stream: resist opening wasteful bins
        if progress > 0.6 {
            let waste_tol = (1.0 - progress) * cap_f * 0.35;
            if newbin_waste > waste_tol && fitting_bins_count > 0 {
                score += 10.0 + progress * 22.0;
            }
        }
        if progress > 0.85 && newbin_waste > cap_f * 0.3 { score += 8.0; }
        // early stream: allow diversity
        if progress < 0.1 { score -= 5.0; }
    }

    // Mild progress-based diversity nudge for open bins
    let progress = step_index as f64 / total_items.max(1) as f64;
    if progress < 0.1 { score += 3.0; }

    // Unusable-gap penalty: residual too small for the next item
    if post_residual > 0 && next_item_size > 0 && post_residual < next_item_size {
        let wasted = next_item_size as f64 - post_residual as f64;
        score += wasted * 0.6;
        if post_residual >= item_size * 2 { score += 10.0; }
        score += (1.0 - progress) * 12.0;
    } else if next_item_size > 0 && post_residual > 0 {
        let reuse = (post_residual / next_item_size) as f64 * (next_item_size as f64 / cap_f);
        score -= reuse * 20.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
