pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Core: aggressive 2-step lookahead matching.
    // If the next item fits exactly into the post residual, this is a perfect chain.
    if next_item_size > 0 {
        let next_fits = (next_item_size as f64) <= post_residual as f64;
        if next_fits {
            let chain_gap = post_residual as f64 - next_item_size as f64;
            // Reward chain: subtract more the tighter the follow-up fit.
            score -= 30.0 + 40.0 * (1.0 - chain_gap / bin_capacity as f64);
            // Perfect exact chain (post_residual == next_item_size) is ideal.
            if chain_gap == 0.0 {
                score -= 25.0;
            }
        } else {
            // Next item does NOT fit here: penalize proportionally to wasted potential.
            let overshoot = next_item_size as f64 - post_residual as f64;
            score += 10.0 + 0.3 * overshoot.min(80.0);
        }
    } else {
        // Last item: only tightness matters.
        score += 5.0;
    }

    // Tight fit reward relative to item size (small post residual is good, but
    // only if it doesn't create unusable dead space given the lookahead).
    let tightness = 1.0 - (post_residual as f64) / (bin_capacity as f64);
    score -= 20.0 * tightness;

    // Penalize dead space that is too small to be useful for typical items (1..100).
    let dead = post_residual as f64;
    if dead > 0.0 && dead < 10.0 {
        score += 15.0 * (10.0 - dead);
    }

    // Last-chance bin: if this is the only bin that fits, strongly prefer using it.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 35.0;
    }

    // Prefer bins that are already relatively full compared to the fleet mean.
    if bin_residual < bin_capacity {
        let rel = (bin_residual as f64 - mean_residual) / bin_capacity as f64;
        score += 10.0 * rel; // below-mean residual (fuller bin) => lower score
    }

    // New-bin candidate: only attractive when no open bin fits well,
    // i.e., when many bins compete but none is tight, or stream is early.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let pressure = if fitting_bins_count == 0 { 0.0 } else { (fitting_bins_count as f64).ln() + 1.0 };
        // Base penalty so new bins aren't opened casually; relax late in stream
        // when open bins are fragmented.
        score += 60.0 + 40.0 * pressure - 30.0 * progress;
        // If the next item is large and a fresh bin can host the chain, soften penalty.
        if next_item_size >= 50 && next_item_size <= bin_capacity {
            score -= 20.0;
        }
    }

    // Mild penalty for proliferating open bins (fragmentation control).
    score += 0.5 * open_bins_count as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect-fit reward
    if post_residual == 0 {
        score -= 500.0;
    }

    // Tightness: reward small post-residual nonlinearly
    let t = post_residual as f64 / bin_capacity as f64;
    score += t * t * 60.0;

    // Last-chance bonus: if this is the only fitting bin, strongly prefer it
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 150.0;
    }

    // Lookahead: penalize if the next item could have fit better in this residual
    if next_item_size > 0 && next_item_size > post_residual && next_item_size <= bin_residual {
        score += 80.0;
    }
    // Reward if post residual exactly (or nearly) matches next item
    if next_item_size > 0 && post_residual >= next_item_size {
        let gap = (post_residual - next_item_size) as f64;
        score -= (1.0 - gap / bin_capacity as f64) * 60.0;
    }

    // Dead-space penalty: residual too small for the smallest plausible item (<= 10)
    if post_residual > 0 && post_residual < 10 {
        score += 120.0;
    }

    // New-bin candidate handling: penalize opening a new bin unless nothing fits well
    if bin_residual == bin_capacity {
        let pressure = (fitting_bins_count == 0) as i32 as f64;
        let progress = step_index as f64 / (total_items.max(1) as f64);
        // Base penalty so open bins are preferred; reduced late in stream or when no bin fits
        score += 90.0 - pressure * 200.0 - progress * 30.0;
        // If mean residual across open bins is large, opening new bin is wasteful
        score += mean_residual.max(0.0) * 0.5;
    }

    // Slight preference to fill bins with larger residuals when many bins are open
    score += (open_bins_count as f64).ln().max(0.0) * (bin_residual as f64 - post_residual as f64) * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap_f = bin_capacity as f64;
    let mut score = post_residual as f64;
    let quarter = bin_capacity / 4;
    let half = bin_capacity / 2;
