    // Residual class structure (mutated: stronger perfect / dead-space split)
    if post == 0 {
        score -= 900.0;
    } else if post <= 3 {
        score -= 400.0;
    } else if post < quarter {
        score += 25.0;
        if next_item_size > post {
            score += 25.0;
            let gap = (next_item_size - post) as f64;
            score += gap * 0.5;
        }
