    if next_item_size > 0 {
        if next_item_size == post {
            score -= 400.0;
        } else if next_item_size <= post {
            let slack = post - next_item_size;
            if slack < quarter {
                score -= 25.0;
            } else {
                score -= 5.0;
            }
            if post % next_item_size == 0 {
                score -= 14.0;
            }
            let chain = post / next_item_size;
            if chain >= 2 {
                score -= (chain.min(4)) as f64 * 5.0;
            }
        } else {
            score += 12.0;
            let gap = (next_item_size - post) as f64;
            if gap <= 5.0 {
