            score -= 40.0;
        }
        if bin_residual as f64 > cap_f * 0.6 {
            score -= 10.0;
        }

        // Unusable dead space vs next item
        if post > 0 && next_item_size > post {
            let wasted = (next_item_size - post) as f64;
            score += wasted * 0.6;
        }
        // Residual near mean is a "typical" leftover, mildly preferred
        let dist = (post as f64 - mean_residual.max(1.0)).abs();
        score += dist * 0.3;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Normalized stream progress
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    // Smooth non-linear coupling of post_residual with progress:
    // early on, prefer tight fits mildly; later, penalize wasted space more strongly.
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let pr_norm = pr / cap;

    // Quadratic/cubic polynomial in pr_norm modulated by progress
    let poly = pr_norm * pr_norm * (1.0 + 2.0 * progress) + pr_norm * pr_norm * pr_norm * (3.0 * progress);
    score += 40.0 * poly;

    // Reward filling a bin nearly exactly, smoothly via gaussian-like term
    let tightness = 1.0 - (pr_norm * 4.0 - 0.0) * (pr_norm * 4.0 - 0.0);
    score -= 10.0 * tightness * (1.0 - progress);

    // Dead-space penalty: residuals too small for any plausible future item (sizes >= 1)
    let small_dead = (1.0 - pr_norm).max(0.0);
    score += 15.0 * small_dead * small_dead * progress;

    // Last-chance bonus: if this is the only fitting bin, strongly prefer using it
    if fitting_bins_count == 1 {
        score -= 25.0;
    }

    // Lookahead: if next item fits exactly into post_residual, reward this placement
    if next_item_size > 0 && (post_residual as u32) == next_item_size {
        score -= 12.0;
    } else if next_item_size > 0 && (next_item_size as f64) > pr {
        // next item cannot fit here anyway; slight penalty for leaving awkward gap
        score += 3.0 * (1.0 - pr_norm);
    }

    // Mean residual coupling: prefer bins whose residual is below the mean (tighter bins)
    let diff = (mean_residual - bin_residual as f64) / cap;
    score += 8.0 * diff * (0.5 + progress);

    // Mild penalty for proliferating open bins early in the stream
    score += (open_bins_count as f64).ln().max(0.0) * (1.0 - progress) * 2.0;

    // New-bin candidate: make empty bin attractive only when no open bin fits well
    if bin_residual == bin_capacity {
        // baseline cost of opening a new bin, reduced as stream progresses
        score = cap * 0.9 + 20.0 * (1.0 - progress);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap_f = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Dead-space avoidance: strong tiered rewards for tight fits
    if post_residual == 0 {
        score -= 900.0;
    } else if post_residual <= 3 {
        score -= 400.0;
    } else if post_residual <= 12 {
        score -= 80.0;
    } else if post_residual < 20 {
        score += 15.0;
    } else if post_residual < 30 {
        score += 15.0 + (30 - post_residual) as f64 * 0.5;
    }

    // Lookahead: exact and near-exact fits for the next item
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 700.0;
        } else if next_item_size <= post_residual {
            let post2 = post_residual - next_item_size;
            score -= 100.0 - post2 as f64 * 1.8;
            if post2 == 0 { score -= 90.0; }
            if post2 > 0 && post2 < 5 { score -= 25.0; }
            if post2 % 10 == 0 && post2 > 0 { score -= 20.0; }
            if post_residual >= next_item_size * 2 && post_residual - next_item_size * 2 <= 4 {
                score -= 18.0;
            }
            if post_residual % next_item_size == 0 { score -= 15.0; }
            let chain = post_residual / next_item_size;
            if chain >= 2 { score -= (chain.min(4)) as f64 * 6.0; }
        } else {
            // next item won't fit here: penalize leaving a nearly-fitting gap
            let gap = next_item_size - post_residual;
            if post_residual > 0 {
                if gap <= 3 { score += 35.0; }
                else if gap <= 8 { score += 12.0; }
                if (gap as f64) > mean_residual * 0.5 { score += 12.0; }
                if post_residual < 15 { score += 40.0; }
                score += (6usize.saturating_sub(gap as usize)) as f64 * 4.0;
            }
        }
    }

    // Compaction pressure scaled by open bins
    score += open_bins_count as f64 * 0.8;

    // Last-chance bin: strongly favor using it
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 45.0;
    }

    // Tightness via relative fill
    score -= (item_size as f64 / bin_residual.max(1) as f64) * 30.0;

    // Consolidate slack: prefer bins below average residual
    if bin_residual < bin_capacity {
        score += (mean_residual - bin_residual as f64) * 1.2;
    }

    // NEW-BIN CANDIDATE handling
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let newbin_waste = (bin_capacity - item_size) as f64;
        score += 200.0 - progress * 70.0;
        if item_size as f64 / cap_f > 0.75 { score -= 55.0; }
        if item_size as f64 > mean_residual { score -= 35.0; }
        if newbin_waste < mean_residual * 0.5 { score -= 30.0; }
        if bin_capacity - item_size <= 4 { score -= 60.0; }
        if next_item_size > 0 && (bin_capacity - item_size) >= next_item_size
            && (bin_capacity - item_size) - next_item_size <= 6 {
            score -= 35.0;
        }
        if next_item_size > 0 {
            let leftover = bin_capacity - item_size;
            if leftover >= next_item_size {
                let tail = leftover % next_item_size;
                if tail == 0 { score -= 12.0; }
                else if tail <= 4 { score -= 14.0; }
            }
            if leftover < next_item_size && leftover < 10 { score += 18.0; }
        }
        if fitting_bins_count > 0 {
            score += (fitting_bins_count.min(6) as f64) * 7.0;
            let best_alt = if item_size as f64 <= mean_residual { mean_residual - item_size as f64 } else { mean_residual };
            if newbin_waste > best_alt + cap_f * 0.1 { score += 20.0; }
        }
        if progress > 0.7 {
            let waste_tol = (1.0 - progress) * cap_f * 0.35;
            if newbin_waste > waste_tol && fitting_bins_count > 0 {
                score += 10.0 + progress * 20.0;
            }
        }
        if progress < 0.1 { score -= 5.0; }
    } else {
        // Dead-space ratio analysis for open bins
        let dead_ratio = post_residual as f64 / cap_f;
        if dead_ratio < 0.03 {
            score -= 35.0;
        } else if dead_ratio < 0.08 {
            score -= 12.0;
        } else if dead_ratio > 0.35 {
            score += 22.0;
        } else if dead_ratio > 0.25 {
            score += 10.0;
        }

        // Penalize residuals that are unusable for the next item
        if post_residual > 0 && next_item_size > 0 && post_residual < next_item_size {
            let wasted = next_item_size as f64 - post_residual as f64;
            score += wasted * 0.6;
            if wasted > 12.0 {
                score += dead_ratio * 80.0;
            }
        }
        // Reward reusability for the next item
        if post_residual > 0 && next_item_size > 0 && post_residual >= next_item_size {
            let reuse = (post_residual / next_item_size) as f64 * (next_item_size as f64 / cap_f);
            score -= reuse * 22.0;
        }
        if item_size == bin_residual { score -= 45.0; }
        if post_residual > 0 && post_residual < 6 { score -= 20.0; }
        if post_residual > 0 && (post_residual as f64) < mean_residual * 0.25 { score -= 15.0; }
        if post_residual > 0 && post_residual % 10 == 0 { score -= 10.0; }
        if post_residual > 0 && (post_residual as f64) < cap_f * 0.015 { score -= 18.0; }

        let progress = step_index as f64 / total_items.max(1) as f64;
        if post_residual > 0 && next_item_size > 0 && post_residual < next_item_size {
            score += (1.0 - progress) * 14.0;
        }
        if fitting_bins_count <= 2 && post_residual > 0 { score -= 8.0; }
        if post_residual > 0 {
            let mres = mean_residual.max(1.0);
            let dist = (post_residual as f64 - mres).abs();
            score += dist * 0.3;
            if dist < cap_f * 0.03 { score -= 10.0; }
        }
        if post_residual > 0 && next_item_size > 0 && post_residual + next_item_size <= bin_capacity
            && (post_residual as f64) < mean_residual * 0.5 {
            score -= 9.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: quantize dead space into capacity fractions.
    let frac = post_residual as f64 / bin_capacity as f64;
    // Penalize small-but-unusable residuals (dead space) more than large residuals.
    if post_residual > 0 && post_residual < 10 {
        score += 40.0;
    } else if post_residual == 0 {
        score -= 60.0; // perfect fit is best
    } else {
        // modulo class logic: residuals divisible by 4/8 tend to fit future small items
        if post_residual % 8 == 0 {
            score -= 6.0;
        } else if post_residual % 4 == 0 {
            score -= 3.0;
        }
        // integer division thresholds: residual >= 25 can host a mid item
        if post_residual >= 25 {
            score -= 8.0;
        }
        score += frac * 10.0;
    }

    // Lookahead: if next item fits exactly in post_residual, reward strongly.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 50.0;
        } else if next_item_size < post_residual {
            let gap = post_residual - next_item_size;
            if gap < 10 {
                score -= 20.0; // near-exact chain
            } else if gap < 25 {
                score -= 10.0;
            }
            // harmonic class of gap
            if gap % 5 == 0 {
                score -= 4.0;
            }
        } else {
            score += 12.0; // next item cannot follow here
        }
    }

    // Last chance bin: strongly prefer using it before opening a new bin.
    if fitting_bins_count == 1 {
        score -= 30.0;
    }

    // New-bin candidate: penalize opening a bin unless current item creates a nice class.
    if bin_residual == bin_capacity {
        // opening new bin baseline: its post_residual = capacity - item_size
        let new_frac = post_residual as f64 / bin_capacity as f64;
        score += 25.0;
        if post_residual % 10 == 0 && post_residual > 0 {
            score -= 15.0; // round-class residual is reusable
        }
        if new_frac < 0.2 {
            score += 20.0; // would create tiny residual immediately
        }
        if open_bins_count > 0 && mean_residual > item_size as f64 {
            score += 15.0; // existing bins already have room
        }
    }

    // Late in stream: tighten packing, avoid spreading.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += progress * 5.0 * (open_bins_count as f64).sqrt().ln_1p();

    // Mild preference for bins below mean residual (fill emptier bins first).
    if (bin_residual as f64) < mean_residual {
        score -= 3.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;
    let size_f = item_size as f64;
    let nxt = next_item_size as f64;

    // Base: post-residual waste with progress coupling
    let progress_coupling = 1.0 + 2.0 * progress * progress;
    let mut score = pr * progress_coupling;

    // Super-linear penalty on large dead space
    score += 40.0 * norm_pr * norm_pr * norm_pr * norm_pr * cap;

    // Strong bonus for perfect / near-perfect fits (borrowed from best)
    if post_residual == 0 {
        score -= 1180.0;
    } else if post_residual <= 3 {
        score -= 500.0;
    } else if post_residual <= 12 {
        score -= 98.0;
    } else if post_residual < 20 {
        score += 18.0;
    } else if post_residual < 30 {
        score += 18.0 + (30 - post_residual) as f64 * 0.6;
    }

    // Smooth tightness bump
    let tightness = (-norm_pr * norm_pr / 0.02).exp();
    score -= 25.0 * tightness * cap * (0.5 + progress);

    // Lookahead coupling: chain reuse reward
    if next_item_size > 0 {
        let gap = pr - nxt;
        if gap < 0.0 {
            score += 0.5 * (-gap) * (1.0 + progress);
            // unusable dead space for the next item
            if (-gap) > 12.0 {
                score += norm_pr * 90.0;
            }
        } else {
            let fit_bonus = (-(gap / cap) * (-(gap / cap)) / 0.01).exp();
            score -= 12.0 * fit_bonus;
            // exact next-item fit: strong reward
            if post_residual == next_item_size {
                score -= 900.0;
            } else if post_residual % next_item_size == 0 {
                score -= 18.0;
            } else {
                let post2 = post_residual - next_item_size;
                score -= 135.0 - post2 as f64 * 2.0;
                if post2 == 0 { score -= 110.0; }
                if post2 > 0 && post2 < 5 { score -= 28.0; }
                if post2 >= 20 && post2 % 5 == 0 { score -= 12.0; }
                // chain: residual can hold next item multiple times
                let chain = post_residual / next_item_size;
                if chain >= 2 {
                    score -= (chain.min(4)) as f64 * 6.0;
                }
            }
        }
    }

    // Last-chance bin
    if fitting_bins_count == 1 {
        score -= 30.0;
    }

    // Consolidation pressure
    score += 0.3 * open_bins_count as f64 * norm_pr;
    score += 0.2 * (mean_residual - bin_residual as f64);

    // NEW-BIN CANDIDATE LOGIC (bin_residual == bin_capacity)
    if bin_residual == bin_capacity {
        let avg_fill = 1.0 - (mean_residual / cap);
        score += 250.0 - avg_fill * 330.0 - progress * 65.0;
        if size_f > mean_residual {
            score -= 45.0;
        }
        if fitting_bins_count > 0 {
            score += (fitting_bins_count as f64).min(5.0) * 9.0 + 20.0;
            let snug = size_f / bin_residual.max(1) as f64;
            if snug > 0.9 { score += 40.0; }
            if snug > 0.95 { score += 28.0; }
            if snug > 0.98 { score += 18.0; }
        }
        if nxt > 0.0 && nxt >= cap / 2.0 { score -= 32.0; }
        if size_f >= cap * 3.0 / 4.0 { score -= 55.0; }
        if nxt > 0.0 && nxt <= cap - size_f { score -= 25.0; }
        let newbin_waste = (bin_capacity - item_size) as f64;
        if newbin_waste > 0.0 && newbin_waste < mean_residual * 0.6 {
            score -= 30.0;
        }
        if progress > 0.6 && fitting_bins_count > 0 {
            let waste_tol = (1.0 - progress) * cap * 0.35;
            if newbin_waste > waste_tol {
                score += 10.0 + progress * 22.0;
            }
        }
        if progress > 0.85 && newbin_waste > cap * 0.3 {
            score += 8.0;
        }
    } else {
        // Existing-bin refinements
        let dead_ratio = pr / cap;
        if dead_ratio < 0.03 {
            score -= 38.0;
        } else if dead_ratio > 0.35 {
            score += 24.0;
        } else if dead_ratio > 0.25 {
            score += 10.0;
        }
        if post_residual > 0 && pr < mean_residual * 0.25 {
            score -= 15.0;
        }
        if item_size == bin_residual {
            score -= 45.0;
        }
        if next_item_size > 0 && post_residual > 0 && pr > nxt * 3.0 && post_residual < bin_capacity / 3 {
            score += 12.0;
        }
        if fitting_bins_count <= 2 && post_residual > 0 {
            score -= 8.0;
        }
        // unusable-for-next dead space penalty scaled by progress
        if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
            let wasted = nxt - pr;
            score += wasted * 0.6 + (1.0 - progress) * 14.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps are heavily penalized.
    if post_residual > 0 && post_residual < 10 {
        score += (10 - post_residual) as f64 * 6.0;
    }

    // Reward tight fits (small post_residual relative to item size).
    let tightness = item_size as f64 / bin_residual.max(1) as f64;
    score -= tightness * 12.0;

    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 30.0;
    }

    // Last-chance bin: strongly favor using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // Open-bins pressure: many open bins -> discourage spreading, prefer filling.
    let open_pressure = open_bins_count as f64 / (open_bins_count as f64 + 4.0);
    score += open_pressure * (post_residual as f64) * 0.8;

    // Lookahead: if the next item fits in the post residual, reward this placement.
    if next_item_size > 0 && next_item_size <= post_residual {
        score -= 10.0;
    }
    // If next item is large and would not fit anywhere after this placement, penalize.
    if next_item_size > post_residual && next_item_size > bin_capacity - post_residual.max(0) {
        // no-op; new bins handle it
    }

    // New-bin candidate: prefer it only when the item is large and residuals are fragmented.
    if bin_residual == bin_capacity {
        let fragmentation = mean_residual / bin_capacity as f64;
        let large_item = item_size as f64 / bin_capacity as f64;
        score = bin_capacity as f64 - 15.0 * large_item + 20.0 * fragmentation;
        // If a last-chance bin exists, discourage opening a new bin.
        if fitting_bins_count == 1 {
            score += 40.0;
        }
        // Late in the stream, prefer closing out existing bins.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += progress * 10.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong 2-step lookahead: reward exact/near-exact matches with next item.
    if next_item_size > 0 {
        let gap = (post_residual as i64 - next_item_size as i64).abs() as f64;
        // Perfect 2-item fill (post_residual == next_item_size) is ideal.
        score -= 20.0 * (1.0 - gap / (bin_capacity as f64)).max(0.0);

        // Penalize residual that is too small for the next item (dead space trap),
        // but only mildly if the leftover is tiny (near-perfect fill).
        if post_residual > 0 && post_residual < next_item_size {
            score += 6.0 * (next_item_size - post_residual) as f64 / 100.0;
        }
    }

    // Compare against mean residual across open bins: prefer bins whose post
    // residual stays below the mean (consolidating space) when mean is large.
    let post = post_residual as f64;
    if mean_residual > 0.0 {
        score += 0.35 * (post - mean_residual).max(0.0);
        score -= 0.15 * (mean_residual - post).max(0.0);
    }

    // Last chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 15.0;
    }

    // Penalize leaving large awkward residuals (hard-to-fill dead space),
    // especially mid-range leftovers that neither fit typical items nor close out.
    if post > 0 && post < 10.0 {
        score -= 8.0; // tiny leftover ~ closed bin, great
    } else if post > 40.0 {
        score += 0.1 * (post - 40.0);
    }

    // Early in the stream, be slightly more willing to spread items (open bins
    // for future flexibility); late in the stream, tighten packing.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score -= (1.0 - progress) * 2.0;

    // Mild penalty for having many open bins: encourage consolidation.
    score += 0.05 * open_bins_count as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
