pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: small post-residual is good, but dead space below ~10 is wasted.
    if post_residual > 0 {
        let dead = if post_residual < 10 { (10 - post_residual) as f64 * 2.0 } else { 0.0 };
        score += dead;
    } else {
        score -= 15.0; // perfect fill
    }

    // Lookahead: if next item fits in the post-residual, reward this placement.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 8.0 + 0.1 * next_item_size as f64;
    } else if next_item_size > 0 && next_item_size > post_residual {
        // Next item won't fit here anyway; mild penalty if we leave a big awkward gap.
        let gap = post_residual as f64;
        if gap > 0.0 && gap < next_item_size as f64 {
            score += 0.3 * (next_item_size as f64 - gap);
        }
    }

    // Last-chance bonus: if this is the only fitting bin, strongly prefer using it.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // New-bin candidate handling: penalize opening a new bin unless current bins fit poorly.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let avg_fit_gap = mean_residual - item_size as f64;
        // Opening a bin is attractive when mean residual is large but fragmented (no tight fits),
        // or when many bins already exist and we want to preserve flexibility.
        score += 25.0;
        if avg_fit_gap > 20.0 {
            score -= 10.0; // open bins are roomy; new bin keeps options open
        }
        if open_bins_count > 5 {
            score += 0.5 * open_bins_count as f64;
        }
        if progress > 0.8 {
            score += 15.0; // late stream: consolidate, avoid new bins
        }
        if next_item_size > 0 && next_item_size >= bin_capacity - item_size {
            score -= 12.0; // next item will fill the remainder of a fresh bin
        }
    }

    // Prefer bins whose residual is close to the mean (balanced packing).
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += 0.15 * dev;

    // Slight preference for fuller bins overall.
    score -= 0.05 * (bin_capacity - bin_residual) as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;

    // Base: prefer small post residual, but non-linearly (quadratic coupling)
    let mut score = norm_pr * norm_pr * 60.0 + norm_pr * 20.0;

    // Smooth polynomial coupling with stream progress:
    // early on, waste tolerance is higher; late, punish residual sharply
    let p3 = progress * progress * progress;
    score += (p3 * 40.0 - progress * 10.0) * norm_pr;

    // Interaction: post residual vs mean residual (avoid fragmenting bins
    // that deviate from the fleet's average usefulness)
    let mr = mean_residual / cap;
    score += (norm_pr - mr) * (norm_pr - mr) * 15.0 * (0.5 + progress);

    // Last-chance bonus: strongly reward using the only fitting bin
    if fitting_bins_count == 1 {
        score -= 25.0 + 30.0 * progress;
    }

    // Lookahead: reward if next item can use the post residual smoothly
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        if nx <= pr {
            let fit_quality = (pr - nx) / cap;
            score -= (1.0 - fit_quality * fit_quality * 4.0).max(0.0) * 12.0 * (1.0 - progress * 0.5);
        } else {
            score += (nx - pr) / cap * 8.0;
