    // Mild penalty for proliferation of open bins
    score += (open_bins_count as f64).ln().max(0.0) * 2.0 * norm_pr;

    // Slight reward for tight fits (small item in large residual bin)
    let tightness = item_size as f64 / bin_residual.max(1) as f64;
    score -= tightness * tightness * 5.0;

    score
}

