    // hold a realistic item (<= 9) are pure waste — heavy penalty.
    if post_residual > 0 && post_residual < 10 {
        score += 40.0;
    }

    // Perfect fit is heavily rewarded.
    if post_residual == 0 {
        score -= 25.0;
    }

    // Penalize leaving gaps just below the next item's size when the next
    // item could otherwise have fit here (wasted opportunity).
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size as f64 {
