        if item_size >= bin_capacity * 3 / 4 { score -= 45.0; }
        if item_size as f64 > mean_residual { score -= 30.0; }
        if newbin_waste < mean_residual * 0.5 { score -= 35.0; }
        if bin_capacity - item_size <= 4 { score -= 70.0; }
        if next_item_size > 0 && (bin_capacity - item_size) >= next_item_size
            && (bin_capacity - item_size) - next_item_size <= 6 {
            score -= 38.0;
        }
        if next_item_size > 0 {
            let leftover = bin_capacity - item_size;
            if leftover >= next_item_size {
                let tail = leftover % next_item_size;
                if tail == 0 { score -= 12.0; }
                else if tail <= 4 { score -= 16.0; }
            }
            if leftover < next_item_size && leftover < 10 { score += 18.0; }
        }
        if fitting_bins_count > 3 {
            score += (fitting_bins_count.min(6) as f64) * 7.0;
            if item_size as f64 / cap_f < 0.5 { score += 30.0; }
        }
        if progress > 0.6 {
            let waste_tol = (1.0 - progress) * cap_f * 0.35;
            if newbin_waste > waste_tol && fitting_bins_count > 0 {
                score += 10.0 + progress * 22.0;
            }
        }
        if progress < 0.1 { score -= 5.0; }
    } else {
        // Prefer bins whose residual is below average (consolidating slack)
        score += (mean_residual - bin_residual as f64) * 1.2;

        // Dead-space ratio shaping
        let dead_ratio = post_residual as f64 / cap_f;
        if dead_ratio < 0.03 { score -= 35.0; }
        else if dead_ratio < 0.08 { score -= 12.0; }
        else if dead_ratio > 0.35 { score += 22.0; }
        else if dead_ratio > 0.25 { score += 10.0; }

        // Unusable gap penalty: next item can't use the leftover
        if post_residual > 0 && next_item_size > 0 && post_residual < next_item_size {
            let wasted = next_item_size as f64 - post_residual as f64;
            if wasted > 12.0 {
                score += wasted * 0.6 + dead_ratio * 60.0;
            } else {
                score += wasted * 0.4;
            }
        } else if next_item_size > 0 && post_residual > 0 {
            let reuse = (post_residual / next_item_size) as f64 * (next_item_size as f64 / cap_f);
            score -= reuse * 20.0;
        }

        if item_size == bin_residual { score -= 45.0; }
        if post_residual > 0 && post_residual % 10 == 0 { score -= 8.0; }
        if bin_residual as f64 > cap_f * 0.6 { score -= 10.0; }
        if fitting_bins_count <= 2 && post_residual > 0 { score -= 8.0; }
        if progress < 0.1 { score += 3.0; }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // --- Harmonic class logic on post_residual ---
    // Class 0: post_residual == 0 -> perfect fit, huge reward.
    // Class 1: post_residual in 1..=9 -> dead space, heavy penalty.
    // Class 2: post_residual in 10..=19 -> marginal but potentially usable.
    // Class 3: post_residual >= 20 -> reusable space.
    let pr = post_residual;
    if pr == 0 {
        score -= 1000.0;
    } else if pr < 10 {
        // Dead space: penalize proportionally to how "wasted" it is,
        // scaled by stream position (later in stream, dead space hurts more).
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score += 40.0 + 60.0 * progress;
    } else if pr < 20 {
        score += 8.0;
    }

    // --- Lookahead coupling: does the next item fit the post-residual? ---
    if next_item_size > 0 && next_item_size <= pr {
        // Reward deeper: the smaller the leftover after the hypothetical next placement,
        // the better the pairing.
        let after_next = pr - next_item_size;
        score -= 25.0 + (after_next as f64).min(20.0);
        // Extra harmonic bonus if next placement also lands in class 0.
        if after_next == 0 {
            score -= 30.0;
        }
    } else if next_item_size > pr && pr > 0 && pr < 10 {
        // Next item cannot use this dead space: extra penalty.
        score += 15.0;
    }

    // --- Last-chance logic ---
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        // This is the only bin that fits; strongly prefer it over opening a new bin.
        score -= 120.0;
    }

    // --- New-bin candidate handling (bin_residual == bin_capacity) ---
    if bin_residual == bin_capacity {
        // New bin baseline: post_residual = capacity - item_size (large).
        // Penalize so it only wins when existing fits are truly bad,
        // but soften the penalty when many bins are open (fragmentation risk).
        let crowding = (open_bins_count as f64).min(20.0);
        score += 55.0 - crowding;
        // If the item is large, a fresh bin is more attractive (large items
        // pair well with an empty bin's flexibility).
        if item_size >= 50 {
            score -= 20.0;
        }
        // If next item is also large, opening a fresh bin now is risky.
        if next_item_size >= 50 {
            score += 25.0;
        }
    }

    // --- Mean-residual coupling: prefer bins whose residual is below the mean
    // (fill the fuller bins first, keep flexible bins open). ---
    let residual_f = bin_residual as f64;
    if residual_f < mean_residual {
        score -= (mean_residual - residual_f).min(15.0) * 0.5;
    } else {
        score += (residual_f - mean_residual).min(15.0) * 0.3;
    }

    // --- Modulo harmonic tie-breaker: post_residual divisible by common
    // item sizes (10/20/25/50) is more reusable. ---
    if pr > 0 && (pr % 10 == 0 || pr % 20 == 0 || pr % 25 == 0 || pr % 50 == 0) {
        score -= 5.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: penalize unusable small gaps.
    // A post_residual is "dead" if it's too small to fit even the smallest
    // plausible item; treat gaps below ~10 as pure waste, and gaps that
    // cannot fit the lookahead item as semi-waste.
    if post_residual > 0 {
        if post_residual < 10 {
            score += 40.0; // pure dead space
        } else if next_item_size > 0 && post_residual < next_item_size {
            // gap unusable for the next item: partial dead-space penalty
            score += 12.0 * (1.0 - (post_residual as f64) / (next_item_size as f64));
        }
    }

    // Reward tight fits (small post_residual relative to item size).
    if item_size > 0 {
        score -= 8.0 * (item_size as f64) / (bin_residual as f64);
    }

    // Last-chance bonus: if this is the only fitting bin, strongly prefer it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 25.0;
    }

    // Open-bins pressure: when many bins are open, discourage opening new
    // ones; the new-bin candidate has residual == capacity, so add a term
    // that scales with open_bins_count to penalize it via its own score.
    score += (open_bins_count as f64) * ((bin_residual as f64) / (bin_capacity as f64));

    // Lookahead synergy: reward leaving a gap that exactly fits the next item.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 15.0;
    }

    // Mild mean-residual coupling: prefer bins whose residual is near the mean
    // (balanced packing), penalize outliers.
    score += 0.05 * ((bin_residual as f64) - mean_residual).abs();

    // New-bin candidate guard: opening a fresh bin should only win when the
    // current item is large relative to typical residuals; make the empty-bin
    // call slightly less attractive as the stream progresses.
    if bin_residual == bin_capacity {
        score += 5.0 + 10.0 * (step_index as f64 / (total_items.max(1) as f64));
    }

    score
}

