    let mut score = post_residual as f64;

    // Lookahead: reward when the next item exactly fills the post residual (perfect 2-step packing).
    if next_item_size > 0 {
        let gap = if (post_residual as i64 - next_item_size as i64).abs() as f64 > 0.0 {
            (post_residual as f64 - next_item_size as f64).abs()
        } else { 0.0 };
        if post_residual == next_item_size {
            score -= 40.0; // perfect chain: this bin absorbs both items fully
        } else if next_item_size <= post_residual {
            score -= 12.0 * (1.0 - gap / bin_capacity as f64); // next item fits, closer is better
        } else {
            score += 8.0 + 0.15 * gap; // next item won't fit here; penalize tight-but-broken chains
        }
    }

    // Penalize dead space relative to mean residual: post_residual far above mean = wasteful.
    score += 0.6 * (post_residual as f64 - mean_residual).max(0.0);
    // Slight reward for bins tighter than average (consolidating space).
    score -= 0.2 * (mean_residual - post_residual as f64).max(0.0);

    // Last-chance bonus: only this bin fits, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 25.0;
    }

    // New-bin candidate: only attractive when current bin would leave very awkward residue
    // or no open bins exist / item is huge relative to typical residual.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let awkward = post_residual as f64 > 0.0 && post_residual < 10;
        if open_bins_count == 0 || (item_size as f64 > mean_residual * 1.5 && progress < 0.9) {
            score -= 20.0;
        }
        if awkward { score += 15.0; } // opening a bin that leaves tiny dead space immediately is bad
