    let mut score = post_residual as f64;

    // Tight-fit reward: strongly favor bins where the item fills most of the residual.
    let tightness = 1.0 - (post_residual as f64) / (bin_capacity as f64);
    score -= 24.0 * tightness * tightness;

    // Penalize post-residual dead space that is too small for the smallest plausible item (1..100 range).
    if post_residual > 0 && post_residual < 10 {
        score += 18.0;
    } else if post_residual > 0 && post_residual < item_size {
        score += 6.0; // mild penalty: leftover can't fit a repeat of this item
    }

    // Lookahead: reward bins whose leftover can host the next item.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
