pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: reward residuals in "useful" classes
    // (divisible into common item sizes), penalize dead-space classes.
    let pr = post_residual;
    if pr == 0 {
        score -= 60.0; // perfect fit
    } else if pr % 10 == 0 {
        score -= 12.0; // clean decade residual
    } else if pr < 10 {
        score += 25.0; // unusable sliver
    } else if pr % 5 == 0 {
        score -= 5.0;
    } else {
        score += (pr % 5) as f64 * 2.5; // odd classes penalized
    }

    // Integer-division threshold: big chunks of leftover are good for future items
    let half = bin_capacity / 2;
    if pr >= half {
        score -= 8.0;
    } else if pr >= bin_capacity / 4 {
        score -= 3.0;
    } else {
        score += 4.0;
    }

    // Lookahead coupling: if next item fits exactly into post_residual, big reward
    if next_item_size > 0 {
        if next_item_size == pr {
            score -= 40.0;
        } else if next_item_size <= pr {
            let slack = (pr - next_item_size) as f64;
            score -= 10.0 - slack * 0.3;
        } else {
            // next item cannot use this residual at all
            score += 6.0;
        }
    }

    // Last-chance bin: strongly prefer using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // New empty bin candidate: baseline competitive score, opened only when
    // no open bin offers a decent fit.
    if bin_residual == bin_capacity {
        score = cap * 0.75 + (open_bins_count as f64) * 1.5;
        if fitting_bins_count == 0 {
            score -= 100.0; // nothing else fits: must open
        }
        if next_item_size > 0 && next_item_size >= item_size {
            score -= 10.0; // pairing big items into fresh bins can help
        }
        return score;
    }

    // Tight fit bonus relative to item size
    let tightness = 1.0 - (post_residual as f64) / cap;
    score -= tightness * 15.0;

    // Mild stream-phase adaptation: later in stream, prefer tighter packing
    let phase = step_index as f64 / (total_items.max(1) as f64);
    score += phase * (mean_residual - post_residual as f64).abs() * 0.2;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Penalize small unusable dead space heavily
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Reward tight fits
    if post_residual == 0 {
        score -= 30.0;
    }

    // Penalize if post_residual cannot fit next item but is small
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 8.0;
    }

    // Reward using last fitting bin (avoid opening new bin)
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // Open bins pressure: discourage opening new bins when many are open
    if bin_residual == bin_capacity {
        score += 20.0 + (open_bins_count as f64) * 3.0;
    }

    // Dead space relative to mean residual
    if (post_residual as f64) > mean_residual {
        score += 3.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong base preference for tight fits.
    score += (post_residual as f64) * (post_residual as f64) * 0.02;

    // 2-step lookahead: reward bins whose post_residual matches next_item_size exactly.
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        let pr = post_residual as f64;
        if post_residual >= next_item_size {
            let gap = pr - nx;
            score -= 30.0 * (1.0 - gap / bin_capacity as f64);
            if gap == 0.0 {
                score -= 60.0; // perfect two-item pairing
            }
        } else {
            // next item cannot fit here: penalize proportionally to leftover dead space
            score += 0.05 * pr;
        }
    } else {
        // last item: just minimize residual
        score += 0.1 * post_residual as f64;
    }

    // Relative to mean residual: prefer bins tighter than average.
    score += (post_residual as f64 - mean_residual) * 0.3;

    // Last-chance bin bonus: if this is the only fitting bin, strongly prefer using it
    // over opening a new bin (unless fit is terrible).
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate: make it attractive only when no open bin fits well.
    if bin_residual == bin_capacity {
        score += 40.0 + 0.5 * mean_residual;
    }

    // Late in the stream, avoid opening new bins even more.
    let progress = step_index as f64 / total_items as f64;
    if bin_residual == bin_capacity {
        score += 30.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
