    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 18.0;
    }

    // Many fitting bins -> mild penalty for hoarding placements in the tightest
    // is already handled; instead penalize spreading into very empty bins when
    // alternatives exist.
    if fitting_bins_count > 2 && post_residual > bin_capacity / 2 {
        score += 4.0;
    }

    // New-bin candidate: only attractive when no open bin fits well.
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
