        score += 6.0;
    }

    // Reward tight fits: small post_residual that is still usable is excellent.
    let tightness = (bin_residual - item_size) as f64 / bin_capacity as f64;
    score -= (1.0 - tightness) * 10.0;

    // Dead space relative to the next item: if next item cannot use the leftover, penalize.
    if next_item_size > 0 {
        if post_residual < next_item_size {
            score += 8.0;
        } else {
            score -= 4.0; // leftover can potentially host the lookahead item
        }
    }

    // Open-bin pressure: discourage spreading across many bins when not a tight fit.
    let pressure = open_bins_count as f64 / (1.0 + mean_residual / bin_capacity as f64);
    score += pressure * 0.5;

    // Last-chance bin: strongly favor using it before opening a new bin.
    if fitting_bins_count == 1 {
        score -= 15.0;
    }

    // New-bin candidate: prefer opening a fresh bin only when current fit is poor
    // and many bins are open with low mean residual.
    if bin_residual == bin_capacity {
        let poor_fit = post_residual as f64 / bin_capacity as f64;
        score -= 12.0 * poor_fit;
        score += 3.0 * (open_bins_count as f64).ln();
        if next_item_size > 0 && next_item_size > post_residual {
            score -= 5.0; // fresh bin preserves room for the next item
        }
    }

    // Slight late-stream conservatism: fewer wasted gaps toward the end.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += progress * 2.0 * (post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit reward: strongly favor bins that get filled exactly.
    if post_residual == 0 {
        score -= 1000.0;
    }

    // 2-step lookahead: reward exact match of post_residual with next item size.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 500.0;
    }
    // Penalize residuals too small for the next item (dead space).
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 0.5 * (next_item_size - post_residual) as f64;
    }
    // Reward residuals that can still host the next item later.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 0.25 * (post_residual as f64 - next_item_size as f64).min(30.0);
    }

    // Relative to mean residual: prefer bins tighter than the mean.
    score += 0.3 * (bin_residual as f64 - mean_residual);

    // Last-chance bin: strongly encourage using it to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 200.0;
    }

    // New-bin candidate: penalize opening a new bin unless current fit is terrible.
    if bin_residual == bin_capacity {
        score += 60.0 + (item_size as f64 * 0.2);
    }

    // Early in stream: slightly discourage proliferation of open bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += open_bins_count as f64 * (1.0 - progress) * 0.5;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap_f = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Dead-space avoidance with strong perfect-fit reward
    if post_residual == 0 {
        score -= 800.0;
    } else if post_residual <= 3 {
        score -= 350.0;
    } else if post_residual <= 12 {
        score -= 70.0;
    } else if post_residual < 20 {
        score += 18.0;
    } else if post_residual < 30 {
        score += 18.0 + (30 - post_residual) as f64 * 0.6;
    }

    // Lookahead on next item
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 500.0;
        } else if next_item_size <= post_residual {
            let post2 = post_residual - next_item_size;
            score -= 100.0 - (post2 as f64) * 2.0;
            if post2 == 0 {
                score -= 90.0;
            }
            if post2 > 0 && post2 < 5 {
                score -= 25.0;
            }
            if post_residual % next_item_size == 0 {
                score -= 15.0;
            }
            if post_residual >= next_item_size * 2 {
                score -= 10.0;
            }
        } else {
            // next item won't fit here
            let gap = (next_item_size - post_residual) as f64;
            score += 15.0;
            if post_residual > 0 && gap <= 5.0 {
                score += 30.0;
            }
            if post_residual as f64 > mean_residual * 1.4 {
                score -= 10.0;
            }
        }
    }

    // New-bin candidate handling
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let avg_fill = 1.0 - (mean_residual / cap_f);
        score += 220.0 - avg_fill * 300.0 - progress * 60.0;
        if fitting_bins_count > 0 {
            score += (fitting_bins_count as f64).min(5.0) * 9.0;
            let snug = item_size as f64 / (bin_residual.max(1) as f64);
            if snug > 0.9 { score += 35.0; }
            if snug > 0.95 { score += 25.0; }
        }
        let newbin_waste = (bin_capacity - item_size) as f64;
        if newbin_waste < mean_residual * 0.6 {
            score -= 30.0;
        }
        if next_item_size > 0 && next_item_size >= bin_capacity / 2 {
            score -= 30.0;
        }
        if item_size >= bin_capacity * 3 / 4 {
            score -= 50.0;
        }
        if progress > 0.6 {
            let waste_tol = (1.0 - progress) * cap_f * 0.35;
            if newbin_waste > waste_tol && fitting_bins_count > 0 {
                score += 10.0 + progress * 20.0;
            }
        }
    } else {
        // Open-bin placement: prefer tight fits and compact bins
        let tightness = 1.0 - (item_size as f64 / bin_residual.max(1) as f64);
        score += tightness * 80.0;
        score += (mean_residual - bin_residual as f64) * 1.5;

        if item_size == bin_residual {
            score -= 40.0;
        }
        let dead_ratio = post_residual as f64 / cap_f;
        if dead_ratio < 0.03 {
            score -= 35.0;
        } else if dead_ratio > 0.3 {
            score += 20.0;
        }
        if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
            let wasted = (next_item_size - post_residual) as f64;
            score += wasted * 0.6;
        }
        if next_item_size > 0 && post_residual >= next_item_size {
            let chain = post_residual / next_item_size;
            if chain >= 2 {
                score -= (chain.min(4)) as f64 * 6.0;
            }
        }
        if post_residual > 0 && (post_residual as f64) < cap_f * 0.015 {
            score -= 18.0;
        }
        if fitting_bins_count == 1 && bin_residual < bin_capacity {
            score -= 25.0;
        }
    }

    // Compaction pressure
    score += open_bins_count as f64 * 0.8;
    score -= (item_size as f64 / cap_f) * 10.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tightness reward: strongly favor bins where the item fills most of the residual.
    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 12.0 * fit_ratio * fit_ratio;

    // Penalize large dead space quadratically.
    score += 0.02 * (post_residual as f64) * (post_residual as f64) / 10.0;

    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 50.0;
    } else if post_residual < 10 {
        score -= 20.0;
    }

    // Lookahead: penalize leaving a residual that fails to host the next item
    // (wasting the bin's future usefulness), reward compatible leftovers.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 8.0;
        } else if post_residual > 0 {
            score += 6.0 * (1.0 - post_residual as f64 / next_item_size.max(1) as f64);
        }
        // If this bin can host both current and next item, big reward.
        if bin_residual >= item_size + next_item_size {
            score -= 15.0;
        }
    }

    // Last-chance bin: this is the only bin that fits; avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // Prefer fuller bins among many open bins (reduce bin fragmentation).
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score -= 0.1 * (bin_capacity - bin_residual) as f64 * (0.5 + progress);

    // Global pressure: when many bins are open relative to items seen, discourage spreading.
    if open_bins_count > 0 {
        let spread = open_bins_count as f64 / (step_index.max(1) as f64 + 1.0);
        score += 5.0 * spread * (mean_residual / bin_capacity as f64);
    }

    // New-bin candidate handling: only attractive when no open bin fits well.
    if bin_residual == bin_capacity {
        let open_pressure = if fitting_bins_count == 0 { -30.0 } else { 10.0 + 5.0 * fitting_bins_count as f64 };
        score += open_pressure;
        // Early in stream, opening bins is cheap; late, prefer consolidation.
        score += 20.0 * progress;
        // If next item is huge and current item small, a fresh bin is fine.
        if next_item_size >= 70 && item_size <= 30 {
            score -= 10.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let score = 0.0;
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let r = post_residual as f64;
    let c = bin_capacity as f64;
    let rn = r / c;
    let mut score = r;
    // smooth non-linear coupling of residual with stream progress
    let poly = 1.0 + 0.35 * progress * progress + 0.25 * progress * rn * rn - 0.15 * (1.0 - progress) * rn * (1.0 - rn);
    score *= poly;
    // penalize dead space relative to next item fit
    if next_item_size > 0 {
        let gap = (next_item_size as f64 - r).max(0.0);
        score += 0.6 * gap * (0.5 + 0.5 * progress);
        if next_item_size as u32 <= post_residual {
            score -= 0.4 * (r - next_item_size as f64).min(20.0);
        }
    }
    // last-chance bin bonus
    if fitting_bins_count == 1 {
        score -= 0.8 * item_size as f64 * (1.0 - progress);
    }
    // mild penalty for leaving residual near mean (fragmentation)
    score += 0.2 * (r - mean_residual).abs() * progress;
    // slight bias toward filling existing bins vs opening new
    if bin_residual == bin_capacity {
        score += 5.0 + 5.0 * progress;
    }
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post-residual: reward residuals that are "nice"
    // fractions of capacity (small remainders, divisible classes).
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;

    // Modulo classes on post_residual: residuals near multiples of common
    // item sizes (10, 20, 25, 50) are more reusable.
    let harmonics: [u32; 5] = [10, 20, 25, 40, 50];
    for h in harmonics.iter() {
        let d = (post_residual % h) as f64;
        score += (h as f64 / 10.0) * (1.0 - d / (*h as f64)) * 2.0;
    }

    // Penalize post_residual in awkward dead zone: too small for typical items
    // (below the minimum plausible next item) but nonzero.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    }

    // Reward tight fits: small post_residual relative to capacity.
    score -= (1.0 - pr / cap) * 30.0;

    // Lookahead coupling: if next item fits exactly in post_residual, big bonus.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 80.0;
        } else if next_item_size < post_residual {
            score -= 10.0 * (1.0 - (post_residual - next_item_size) as f64 / cap);
        } else {
            // next item cannot follow here; mild penalty scaled by how much it misses
            score += ((next_item_size - post_residual) as f64) * 0.15;
        }
    }

    // Last-chance bin: strongly favor using the only bin that fits.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 50.0;
    }

    // New-bin candidate handling: only attractive when open bins are crowded
    // or mean residual is low (poor fits everywhere).
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let crowd = open_bins_count as f64;
        let new_bin_score = 45.0
            - mean_residual * 0.6
            - crowd * 1.5
            - progress * 10.0
            + item_size as f64 * 0.2;
        return new_bin_score;
    }

    // Prefer bins whose residual deviates favorably from the mean
    // (consolidate space into fewer bins).
    score -= (bin_residual as f64 - mean_residual) * 0.3;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals too small for any realistic item (1..=100)
    // are worthless; penalize small unusable gaps super-linearly.
    if post_residual > 0 {
        let dead = 100.0f64.min(post_residual as f64);
        // unusable gap: nothing smaller than ~post_residual can ever use it
        let unusable = (post_residual as f64) < 10.0; // min item size floor
        if unusable {
            score += (10.0 - post_residual as f64) * 40.0; // heavy penalty for near-full bins
        } else {
            // value of residual decays as it shrinks toward the smallest useful size
            let usefulness = ((post_residual as f64) - 10.0) / 90.0;
            score -= usefulness * 20.0;
            // quadratic dead-space term for mid-range gaps
            score += (1.0 - usefulness) * (1.0 - usefulness) * 15.0;
        }
        let _ = dead;
    }

    // Perfect fit bonus
    if post_residual == 0 {
        score -= 60.0;
    }

    // Lookahead coupling: if next item fits exactly in the post residual, reward strongly
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 50.0;
        } else if next_item_size < post_residual {
            // residual left after next item would fit too
            let r2 = post_residual - next_item_size;
            if r2 >= 1 {
                score -= 10.0 + (r2 as f64).sqrt() * 3.0;
            }
        } else {
            // next item won't fit here: slight penalty for blocking
            score += 5.0;
        }
    }

    // Last-chance bin: if this is the only bin that fits, strongly favor using it
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 35.0;
    }

    // Open-bin pressure: prefer spreading into fewer bins when many are open
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += (open_bins_count as f64).ln().max(0.0) * (8.0 + 10.0 * progress);

    // Mean residual coupling: when average residual is tight, reward conserving space (tight fits)
    if mean_residual > 0.0 {
        let tight = 1.0 - ((post_residual as f64) / mean_residual).min(2.0) / 2.0;
        score += (1.0 - tight) * 12.0;
    }

    // New-bin candidate: make empty bins attractive only when open bins are crowded
    if bin_residual == bin_capacity {
        let crowd = (open_bins_count as f64) * 3.0 + mean_residual * 0.15;
        score = 95.0 - crowd.min(70.0);
        if next_item_size > 0 && next_item_size >= bin_residual {
            score -= 10.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
