pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit: strongest reward.
    if post_residual == 0 {
        score -= 1000.0;
    }

    // 2-step lookahead: reward when next item exactly fills the new residual.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 500.0;
        } else if next_item_size <= post_residual {
            // next item fits: reward proportional to how snugly it would fit
            let after_next = post_residual - next_item_size;
            score -= 100.0 - after_next as f64 * 0.5;
        } else {
            // next item will NOT fit in this residual: penalize wasted space
            let gap = next_item_size - post_residual;
            score += gap as f64 * 0.3;
        }
    }

    // Penalize residuals that are small-but-unusable dead space relative to mean.
    if post_residual > 0 && (post_residual as f64) < mean_residual * 0.5 {
        score += (mean_residual - post_residual as f64) * 0.4;
    }

    // Last-chance bin: strongly favor using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 200.0;
    }

    // New-bin candidate: mildly discourage opening a new bin unless residuals are tight.
    if bin_residual == bin_capacity {
        score += 50.0 + open_bins_count as f64 * -0.5;
        if mean_residual >= item_size as f64 {
            score += 80.0; // an open bin already accommodates this item
        }
    }

    // Slight early-stream conservatism: keep bins mergeable early on.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += (1.0 - progress) * post_residual as f64 * 0.1;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strongly reward tight fits (low post residual).
    let tight = 1.0 - (post_residual as f64) / (bin_capacity as f64);
    score -= 12.0 * tight * tight;

    // Penalize dead space that is too small to ever hold a typical item.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Last-chance bonus: if this is the only fitting bin, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 8.0;
    }

    // New-bin candidate: penalize opening a new bin unless the fit elsewhere is bad.
    if bin_residual == bin_capacity {
        score += 18.0;
        // If lookahead item is large, a fresh bin is more attractive.
        if next_item_size > 0 && next_item_size as f64 > mean_residual {
            score -= 10.0;
        }
    }

    // Lookahead synergy: reward if next item fits into post_residual exactly-ish.
    if next_item_size > 0 {
        let gap = (post_residual as i64 - next_item_size as i64).abs() as f64;
        score += 0.15 * gap;
        if post_residual == next_item_size {
            score -= 20.0; // perfect pairing
        }
    }

    // Global balance: prefer bins whose residual is near the mean residual.
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += 0.05 * dev;

    // Time horizon: late in the stream, consolidate more aggressively.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= progress * 4.0 * tight;

    // Prefer filling bins that are already relatively full.
    let fill = 1.0 - (bin_residual as f64) / (bin_capacity as f64);
    score -= 3.0 * fill;

    // Mild penalty for too many open bins (encourage consolidation).
    score += 0.02 * open_bins_count as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = step_index as f64 / total_items.max(1) as f64;
    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;

    // Base: non-linear polynomial coupling of post_residual with progress.
    // Early on, larger post_residual is acceptable; late in stream, dead space hurts.
    let progress_coupling = pr * (1.0 + 1.5 * progress * progress + 2.0 * progress.powi(3));

    // Reward tight fits (fit_ratio near 1) with a smooth non-linear term.
    let tight_fit_bonus = -30.0 * fit_ratio * fit_ratio * fit_ratio;

    // Penalize moderate slack quadratically; small slack (<= threshold-free smooth) is fine.
    let slack_penalty = (pr / cap).powi(2) * 40.0 * (1.0 - progress * 0.5);

    // Last-chance bonus: strongly favor using the only bin that fits.
    let last_chance = if fitting_bins_count == 1 && bin_residual != bin_capacity {
        -25.0
    } else {
        0.0
    };

    // New-bin candidate: penalize opening a new bin smoothly, scaled by how
    // much residual it would create and how well existing bins could fit.
    let is_new_bin = bin_residual == bin_capacity;
    let new_bin_penalty = if is_new_bin {
        35.0 * (pr / cap) + 10.0 * (1.0 - fit_ratio) + 8.0 * (open_bins_count as f64 / (open_bins_count as f64 + 5.0))
    } else {
        0.0
    };

    // Lookahead: if next item fits the post-residual, reward this placement.
    let lookahead_bonus = if next_item_size > 0 && (next_item_size as f64) <= pr {
        -12.0 * (next_item_size as f64 / cap)
    } else if next_item_size > 0 {
        6.0 * (pr - next_item_size as f64).abs() / cap
    } else {
        0.0
    };

    // Deviation from mean residual: prefer bins whose resulting residual
    // harmonizes with the fleet, smooth quadratic coupling.
    let mean_coupling = ((pr - mean_residual) / cap).powi(2) * 15.0;

    let mut score = progress_coupling + slack_penalty + new_bin_penalty + mean_coupling
        + tight_fit_bonus + last_chance + lookahead_bonus;
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let score = post_residual as f64 / bin_capacity.max(1) as f64;
