pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap_f = bin_capacity as f64;
    let mut score = post_residual as f64;
    let progress = step_index as f64 / total_items.max(1) as f64;

    // Dead-space avoidance (tiered, stronger than parent)
    if post_residual == 0 {
        score -= 900.0; // perfect fit
    } else if post_residual <= 3 {
        score -= 350.0;
    } else if post_residual <= 12 {
        score -= 70.0;
    } else if post_residual < 20 {
        score += 18.0;
    } else if post_residual < 30 {
        score += 18.0 + (30 - post_residual) as f64 * 0.6;
    }

    // Lookahead: exact and near-exact fits for the next item
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 700.0;
        } else if next_item_size <= post_residual {
            let post2 = post_residual - next_item_size;
            score -= 100.0 - (post2 as f64) * 2.0;
            if post2 == 0 { score -= 90.0; }
            if post2 > 0 && post2 < 5 { score -= 26.0; }
            if post2 > 0 && post2 <= 2 { score -= 14.0; }
            if post2 % 10 == 0 && post2 > 0 { score -= 20.0; }
            if post2 > 0 && post2 <= next_item_size / 4 { score -= 10.0; }
            if post_residual % next_item_size == 0 { score -= 16.0; }
            if post_residual >= next_item_size * 2 && post_residual - next_item_size * 2 <= 4 {
                score -= 20.0;
            }
            let chain = post_residual / next_item_size;
            if chain >= 2 { score -= (chain.min(4)) as f64 * 6.0; }
        } else {
            // next item won't fit here: penalize leaving a nearly-fitting gap
            let gap = next_item_size - post_residual;
            if post_residual > 0 {
                if gap <= 3 { score += 35.0; }
                else if gap <= 8 { score += 12.0; }
                if (gap as f64) > mean_residual * 0.5 { score += 12.0; }
                if post_residual < 15 { score += 40.0; }
                if gap <= 5 { score += (6 - gap) as f64 * 4.0; }
            }
        }
    }

    // Compaction pressure scaled by open bins
    score += open_bins_count as f64 * 0.8;

    // Last-chance bin: strongly favor using it
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 55.0;
    }

    // Tightness via relative fill (inverted dead-space)
    let tightness = 1.0 - (item_size as f64 / bin_residual.max(1) as f64);
    score += tightness * 60.0;

    // Consolidate slack: prefer bins whose residual is below average
    if bin_residual < bin_capacity {
        score += (mean_residual - bin_residual as f64) * 1.2;
    }

    // Dead-space ratio shaping for open bins
    if bin_residual < bin_capacity {
        let dead_ratio = post_residual as f64 / cap_f;
        if dead_ratio < 0.03 {
            score -= 35.0;
        } else if dead_ratio < 0.08 {
            score -= 12.0;
        } else if dead_ratio > 0.35 {
            score += 24.0;
        } else if dead_ratio > 0.25 {
            score += 10.0;
        }
        // residual unusable for next item and tiny => dead space
        if post_residual > 0 && next_item_size > 0 && post_residual < next_item_size {
            let unusable_gap = (next_item_size - post_residual) as f64;
            if unusable_gap > 12.0 {
                score += dead_ratio * 70.0;
            }
        }
    }

    // NEW-BIN CANDIDATE handling
    if bin_residual == bin_capacity {
        let newbin_waste = (bin_capacity - item_size) as f64;
        let avg_fill = 1.0 - (mean_residual / cap_f);
        score += 230.0 - avg_fill * 300.0 - progress * 60.0;
        // big items deserve a fresh bin
        if item_size >= bin_capacity * 3 / 4 { score -= 55.0; }
        if item_size as f64 > mean_residual { score -= 30.0; }
        if newbin_waste < mean_residual * 0.5 { score -= 35.0; }
        if bin_capacity - item_size <= 4 { score -= 65.0; }
        // fresh bin pairs perfectly with next item
        if next_item_size > 0 {
            let leftover = bin_capacity - item_size;
            if leftover >= next_item_size && leftover - next_item_size <= 6 { score -= 38.0; }
            if leftover >= next_item_size {
                let tail = leftover % next_item_size;
                if tail == 0 { score -= 14.0; }
                else if tail <= 4 { score -= 12.0; }
            }
            if leftover < next_item_size && leftover < 10 { score += 18.0; }
        }
        // many alternatives exist: keep the fresh bin closed
        if fitting_bins_count > 3 {
            score += (fitting_bins_count.min(6) as f64) * 8.0;
        }
        if fitting_bins_count > 0 && newbin_waste > cap_f * 0.5 && progress > 0.6 {
            score += 12.0 + progress * 20.0;
        }
        if progress < 0.1 { score -= 5.0; }
    } else {
        // mild progress-based diversity nudge for open bins
        if progress < 0.1 { score += 3.0; }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap_f = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Strong dead-space shaping
    if post_residual == 0 {
        score -= 900.0;
    } else if post_residual <= 3 {
        score -= 400.0;
    } else if post_residual <= 12 {
        score -= 90.0;
    } else if post_residual < 20 {
        score += 15.0;
    } else if post_residual < 30 {
        score += 15.0 + (30 - post_residual) as f64 * 0.6;
    }

    // Lookahead on next item
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 800.0;
        } else if next_item_size <= post_residual {
            let post2 = post_residual - next_item_size;
            score -= 120.0 - post2 as f64 * 1.5;
            if post2 == 0 { score -= 90.0; }
            if post2 > 0 && post2 < 5 { score -= 25.0; }
            if post2 >= 20 && post2 % 5 == 0 { score -= 10.0; }
            if post_residual % next_item_size == 0 { score -= 15.0; }
            if post2 <= next_item_size / 4 { score -= 8.0; }
            if post_residual >= next_item_size * 2 { score -= 8.0; }
        } else {
            score += 18.0;
            let gap = (next_item_size - post_residual) as f64;
            if post_residual > 0 && gap <= 3.0 { score += 30.0; }
            else if gap <= 8.0 { score += 10.0; }
            if post_residual > 0 && post_residual as f64 > mean_residual * 1.4 { score -= 10.0; }
        }
        if next_item_size > post_residual && post_residual > 0 && post_residual < 15 {
            score += 35.0;
        }
    }

    // Pressure to compact
    score += open_bins_count as f64 * 0.6;

    // Last-chance bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // Relative fill tightness
    score -= (item_size as f64 / cap_f) * 12.0;

    // NEW-BIN CANDIDATE logic
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let newbin_waste = (bin_capacity - item_size) as f64;
        score += 200.0 + progress * 60.0;
        if fitting_bins_count > 0 {
            score += (fitting_bins_count.min(6) as f64) * 10.0;
            let snug = item_size as f64 / bin_residual.max(1) as f64;
            if snug > 0.9 { score += 35.0; }
            if snug > 0.95 { score += 25.0; }
        }
        if item_size >= bin_capacity * 3 / 4 { score -= 50.0; }
        if bin_capacity - item_size <= 4 { score -= 60.0; }
        if next_item_size > 0 && next_item_size <= bin_capacity - item_size {
            let leftover = bin_capacity - item_size;
            let tail = leftover % next_item_size;
            if tail == 0 { score -= 12.0; }
            else if tail <= 4 { score -= 14.0; }
            if leftover >= next_item_size * 2 { score -= 12.0; }
        }
        if newbin_waste < mean_residual * 0.6 { score -= 28.0; }
        if progress > 0.6 {
            let waste_tol = (1.0 - progress) * cap_f * 0.35;
            if newbin_waste > waste_tol && fitting_bins_count > 0 {
                score += 10.0 + progress * 20.0;
            }
        }
    } else {
        let tightness = 1.0 - (item_size as f64 / bin_residual.max(1) as f64);
        score += tightness * 70.0;
        score += (mean_residual - bin_residual as f64) * 1.2;
        let dead_ratio = post_residual as f64 / cap_f;
        if dead_ratio < 0.03 { score -= 35.0; }
        else if dead_ratio < 0.08 { score -= 12.0; }
        else if dead_ratio > 0.35 { score += 22.0; }
        else if dead_ratio > 0.25 { score += 9.0; }
        if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
            let wasted = (next_item_size - post_residual) as f64;
            score += wasted * 0.6;
        }
        if item_size == bin_residual { score -= 40.0; }
        if post_residual > 0 && post_residual % 10 == 0 { score -= 8.0; }
        if next_item_size > 0 && post_residual >= next_item_size {
            let chain = post_residual / next_item_size;
            if chain >= 2 { score -= (chain.min(4)) as f64 * 5.0; }
        }
        if post_residual > 0 && (post_residual as f64) < mean_residual * 0.25 { score -= 12.0; }
        if post_residual > 0 && (post_residual as f64) > mean_residual * 1.6 && fitting_bins_count > 2 { score += 8.0; }
        if post_residual > 0 && next_item_size > 0 && post_residual < next_item_size {
            let dead_frac = post_residual as f64 / cap_f;
            if (next_item_size - post_residual) > 12 {
                score += dead_frac * 80.0;
            }
        }
    }

    // Early stream: mild diversity bonus
    let progress = step_index as f64 / total_items.max(1) as f64;
    if progress < 0.1 { score += 3.0; }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: small post_residual relative to capacity.
    let tightness = post_residual as f64 / bin_capacity as f64;
    score += 8.0 * tightness * tightness;

    // Penalize post_residual that is too small to ever be useful again
    // (dead space below the minimum plausible item size).
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Lookahead: if the next item fits into the post residual, reward this bin.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 12.0;
        } else {
            // Next item won't fit here; slight penalty proportional to waste.
            score += 3.0 * (1.0 - (post_residual as f64 / bin_residual.max(1) as f64));
        }
    }

    // Last-chance bonus: if this is the only bin that can fit the item,
    // strongly prefer using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate handling: only attractive when the item is large
    // relative to residual and open bins are crowded with large residuals.
    if bin_residual == bin_capacity {
        let crowd = mean_residual / bin_capacity as f64;
        let large_item = item_size as f64 / bin_capacity as f64;
        // Penalize new bins mildly; discount when many open bins are wasted space.
        score += 20.0 - 15.0 * crowd * large_item;
    } else {
        // Slight preference for reusing bins proportional to how full they are.
        let fill = (bin_capacity - bin_residual) as f64 / bin_capacity as f64;
        score -= 5.0 * fill;
    }

    // Global state coupling: when mean residual is high, prefer bins that
    // reduce dispersion (bring post_residual near the mean).
    let disp = (post_residual as f64 - mean_residual).abs();
    score += 0.05 * disp;

    // Time horizon: early in the stream, be conservative with new bins
    // (many items remain, keep bins reusable); late in stream, prefer tight fits.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score -= 6.0 * (1.0 - progress) * (bin_residual < bin_capacity) as i32 as f64;
    score += 4.0 * progress * tightness;

    // Mild pressure to consolidate when many bins are open.
    score += 0.01 * open_bins_count as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let norm_post = post / cap; // 0..1
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let mut score = post;

    // Smooth polynomial coupling: post-residual shaped by stream progress.
    // Early on, keep bins flexible (penalize tiny residuals mildly);
    // later, reward tight packing more aggressively.
    let tightness = 1.0 - norm_post;
    let poly = norm_post * norm_post * (3.0 - 2.0 * norm_post); // smoothstep in [0,1]
    score += 12.0 * poly * (1.0 - progress);          // early: extra penalty for leftover space
    score -= 18.0 * tightness * tightness * progress;  // late: reward tight fits

    // Interaction with mean residual: prefer bins deviating below mean (consolidation)
    let dev = (mean_residual - post) / cap;
    score += 6.0 * dev * (1.0 - norm_post);

    // Last-chance bin bonus (avoid opening new bin unnecessarily)
    if fitting_bins_count == 1 {
        score -= 10.0 + 8.0 * progress;
    }

    // Lookahead: if next item fits exactly into post_residual, reward strongly
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        let gap = (post - nx).abs() / cap;
        score -= 10.0 * (1.0 - gap) * (1.0 - gap);
        // penalize if next item cannot fit (dead space risk)
        if nx > post {
            score += 4.0 * (nx - post) / cap;
        }
    }

    // Mild penalty for many open bins to encourage consolidation
    score += 0.5 * (open_bins_count as f64).ln().max(0.0) * norm_post;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap_f = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: which capacity fraction slot it lands in.
    let quarter = bin_capacity / 4;
    let eighth = bin_capacity / 8;
    let class = match post_residual {
        0 => 0u32,                      // perfect fill
        r if r <= eighth => 1,          // near-full: tiny dead space
        r if r < quarter * 2 => 2,      // awkward mid-low residual
        r if r == quarter * 2 => 3,     // exactly half: harmonically ideal
        _ => 4,                         // large residual: wasteful
    };
    score += match class {
        0 => -40.0,
        1 => -15.0,
        2 => 12.0,
        3 => -20.0,
        _ => 18.0,
    };

    // Modulo harmony: residuals that are multiples of common item sizes are reusable.
    for m in [10u32, 20, 25, 50] {
        if post_residual % m == 0 && post_residual > 0 {
            score -= 6.0;
        }
    }

    // Lookahead coupling: does next item fit the post residual?
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            score -= 10.0 + (next_item_size as f64 / cap_f) * 8.0;
        } else {
            // next item won't fit: dead space penalty scaled by gap
            let gap = (next_item_size - post_residual) as f64;
            score += (gap / cap_f) * 25.0;
        }
    }

    // Last-chance bin: strongly favor using it before opening a new one.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate handling.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        // Opening a new bin is fine early or when many bins already open,
        // but penalize when few bins exist and we're mid-stream (fragmentation risk).
        score += 25.0
            - progress * 15.0
            + (open_bins_count as f64).ln().max(0.0) * 5.0;
        // If the item is huge relative to capacity, a fresh bin is naturally fine.
        if item_size as f64 / cap_f > 0.7 {
            score -= 10.0;
        }
    }

    // Slight preference for bins tighter than the mean residual (best-fit flavor).
    score += (mean_residual - bin_residual as f64) * 0.15;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals too small for any item are worthless.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    }
    // Penalize gaps that can't fit the known next item (k=2 lookahead).
    if next_item_size > 0 && post_residual < next_item_size {
        score += 8.0 * (next_item_size as f64 - post_residual as f64).sqrt();
    }
    // Reward near-perfect fits.
    score -= 12.0 * (1.0 - post_residual as f64 / bin_capacity as f64);

    // Last-chance bonus: if this is the only fitting bin, avoid opening a new bin
    // unless the fit would be terrible.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0 + 0.05 * post_residual as f64;
    }

    // Open-bin pressure: discourage spreading across many bins unless fit is good.
    score += 0.15 * open_bins_count as f64 * (post_residual as f64 / bin_capacity as f64);

    // New-bin candidate: only attractive when all fits would leave large dead space
    // or no open bins exist.
    if bin_residual == bin_capacity {
        let dead_space_pressure = if post_residual > 0 { 0.0 } else { 0.0 };
        let _ = dead_space_pressure;
        let worst_case_gap = if next_item_size > 0 && post_residual < next_item_size { 1.0 } else { 0.0 };
        let fit_quality = post_residual as f64 / bin_capacity as f64;
        score = 40.0 + 55.0 * fit_quality + 20.0 * worst_case_gap - 10.0 * (open_bins_count as f64).ln().max(0.0);
        if open_bins_count == 0 {
            score = -100.0;
        }
    }

    // Slight late-stream tightening: waste matters more as stream progresses.
    score *= 1.0 + 0.3 * (step_index as f64 / total_items.max(1) as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap_f = bin_capacity as f64;
    let mut score = post_residual as f64;
    let post = post_residual;
    let quarter = bin_capacity / 4;
    let half = bin_capacity / 2;

    if post == 0 {
        // Perfect fit: very strong reward (mutation: amplified from parent).
        score -= 900.0;
    } else if post <= 3 {
        // Near-perfect: tiny dead space, almost as good as exact.
        score -= 400.0;
    } else if post <= 12 {
        // Small but potentially reusable dead space.
        score -= 60.0;
    } else if post < quarter {
        // Dead-space class: residual too small for typical items.
        score += 30.0;
        if next_item_size > post {
            score += 20.0;
        }
    } else if post < half {
        score += 5.0;
    } else {
        score -= 10.0;
    }

    // Lookahead: harmonic pair with next item.
    if next_item_size > 0 {
        if next_item_size == post {
            score -= 700.0; // exact chain: mutation, strong exact-match bonus
        } else if next_item_size <= post {
            let post2 = post - next_item_size;
            score -= 90.0 - post2 as f64 * 2.0;
            if post2 == 0 {
                score -= 60.0;
            }
            if post2 > 0 && post2 <= 4 {
                score -= 25.0;
            }
            if post2 >= 20 && post2 % 10 == 0 {
                score -= 12.0;
            }
            if post % next_item_size == 0 {
                score -= 18.0;
            }
            if post >= next_item_size * 2 {
                score -= 8.0;
            }
        } else {
            let gap = (next_item_size - post) as f64;
            score += 12.0;
            if gap <= 4.0 {
                score += 25.0; // next item barely misses: bad fit
            }
            if post > 0 && post < 15 {
                score += 35.0;
            }
            if post as f64 > mean_residual * 1.4 {
                score -= 10.0;
            }
        }
    }

    // Divisibility bonuses.
    if post % 10 == 0 && post > 0 {
        score -= 8.0;
    }
    if post % 20 == 0 && post > 0 {
        score -= 4.0;
    }

    // Last-chance: only fitting bin.
    if fitting_bins_count == 1 {
        score -= 25.0;
    }

    // New-bin candidate logic (mutated: waste-aware, progress-scaled).
    if bin_residual == bin_capacity {
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 1.0 };
        let newbin_waste = (bin_capacity - item_size) as f64;
        score += 200.0;
        score += newbin_waste * 0.5;
        score -= 60.0 * (1.0 - progress);
        // If the new-bin leftover can chain with the next item, prefer it.
        if next_item_size > 0 && newbin_waste >= next_item_size as f64 {
            let tail = newbin_waste as u32 % next_item_size;
            if tail <= 4 {
                score -= 30.0;
            }
            if newbin_waste >= next_item_size as f64 * 2.0 {
                score -= 12.0;
            }
        }
        // If no open bin fits at all, opening is mandatory: soften score.
        if fitting_bins_count == 0 {
            score -= 120.0;
        }
        // Large items deserve fresh bins.
        if item_size >= bin_capacity * 3 / 4 {
            score -= 50.0;
        }
        if next_item_size > 0 && next_item_size >= bin_capacity / 2 {
            score -= 30.0;
        }
        // Late stream: avoid wasting fresh capacity.
        if progress > 0.75 && newbin_waste > cap_f * 0.5 {
            score += 15.0;
        }
    } else {
        // Tightness preference: prefer bins where item fills most of residual.
        let tightness = 1.0 - (item_size as f64 / bin_residual.max(1) as f64);
        score += tightness * 40.0;
        if item_size == bin_residual {
            score -= 45.0;
        }
        // Prefer bins whose residual is below the mean (compacting small bins).
        score += (mean_residual - bin_residual as f64) * 1.0;
        let dead_ratio = post as f64 / cap_f;
        if dead_ratio < 0.03 {
            score -= 35.0;
        } else if dead_ratio > 0.35 {
            score += 20.0;
        }
        // Unusable dead space relative to next item.
        if next_item_size > 0 && post > 0 && post < next_item_size {
            let wasted = (next_item_size - post) as f64;
            score += wasted * 0.6;
        }
    }

    // Mild penalty for many open bins with poor mean residual.
    if mean_residual > cap_f * 0.6 && open_bins_count > 3 {
        score += 3.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect 2-step match: post_residual exactly equals next item size.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        let diff = (post_residual as f64 - nxt).abs();
        // Reward exact match strongly; decay with distance.
        score -= 40.0 * (-diff / 12.0).exp();
        // Penalize leaving a gap that is too small for the next item (dead space).
        if post_residual > 0 && post_residual < next_item_size {
            score += 15.0 + 0.3 * (next_item_size - post_residual) as f64;
        }
        // If next item could perfectly fill this bin's post_residual, extra reward.
        if post_residual == next_item_size && next_item_size > 0 {
            score -= 25.0;
        }
    } else {
        // Last item: prefer minimal waste.
        score += 0.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // Compare against mean residual: bins tighter than average are better targets.
    score -= 0.5 * (mean_residual - post_residual as f64);

    // New-bin candidate: only attractive when current fit is poor (large post_residual
    // relative to capacity or dead-space risk), otherwise discourage opening bins.
    if bin_residual == bin_capacity {
        let poor_fit = if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
            1.0
        } else {
            0.0
        };
        let tight_open = if open_bins_count == 0 { 1.0 } else { 0.0 };
        score += 30.0 - 25.0 * poor_fit - 20.0 * tight_open;
        // As stream progresses, slightly discourage hoarding new bins.
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score += 10.0 * progress;
    }

    // Mild preference for fuller bins overall.
    score += 0.05 * (bin_capacity - bin_residual) as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strongly prefer tight fits (low waste).
    score += 0.35 * (post_residual as f64).powf(1.3);

    // Reward bins where the next item also fits (chain packing).
    if next_item_size > 0 && next_item_size <= post_residual {
        score -= 12.0 + 0.2 * (next_item_size as f64);
    }

    // Last-chance bonus: if this is the only fitting bin, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 18.0;
    }

    // Penalize opening a new empty bin when decent open bins exist,
    // unless the current fit is very poor.
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let poor_fit = (post_residual as f64) > 0.5 * bin_capacity as f64;
        if !poor_fit {
            score += 25.0 + 15.0 * (1.0 - progress);
        } else {
            score += 5.0;
        }
    }

    // Prefer bins whose residual deviates below the mean (consolidate large gaps).
    score -= 0.15 * (mean_residual - bin_residual as f64);

    // Mild penalty for leaving residuals that no typical item can use (dead space).
    if post_residual > 0 && post_residual < 10 {
        score += 20.0;
    }

    // Slight preference for bins with more open bins (spread load early, consolidate late).
    let progress = step_index as f64 / (total_items.max(1) as f64);
    if open_bins_count > 4 && progress > 0.5 {
        score -= 2.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let score = (post_residual as f64) * 0.91;
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;

    // Base: prefer small post_residual, with non-linear polynomial shaping
    let mut score = pr * (1.0 + 0.5 * norm_pr * norm_pr);

    // Smooth coupling of post_residual with stream progress:
    // late in the stream, tight fits matter more
    let progress_coupling = 1.0 + 2.0 * progress * progress;
    score *= progress_coupling;

    // Reward near-perfect fits smoothly (quadratic trough at pr == 0)
    score -= 15.0 * (1.0 - norm_pr).powi(3) * (0.5 + progress);

    // Penalize dead space that can't fit the next item (smooth interaction)
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        let deficit = ((nxt - pr) / cap).max(0.0);
        score += 8.0 * deficit * deficit * (1.0 + progress);
        // Reward leaving exactly enough room for the next item
        let match_bonus = (pr - nxt).abs() / cap;
        score -= 5.0 * (1.0 - match_bonus.min(1.0)) * (1.0 - match_bonus.min(1.0));
    }

    // Last-chance bin: strong smooth reward to use it
    if fitting_bins_count == 1 {
        score -= 12.0 * (1.0 + progress);
    }

    // Mild penalty when bin residual deviates from mean residual across open bins
    score += 0.3 * (bin_residual as f64 - mean_residual).abs() / cap;

    // Slight preference for filling existing bins vs opening new ones, scaled by progress
    if bin_residual == bin_capacity {
        score += 6.0 + 10.0 * progress - 0.2 * open_bins_count as f64;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Perfect fit: huge reward.
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Harmonic class of post_residual: residues that are "useless" (too small
    // for the minimum item size 1) or awkward modulo classes get penalized.
    let min_item = 1u32;
    if post_residual > 0 && post_residual < min_item {
        score += 500.0; // dead space, can never be reused
    }

    // Dead-space classes: residuals in (0, 10] can only be filled by tiny items.
    if post_residual > 0 && post_residual <= 10 {
        score += 120.0;
    }

    // Modulo-10 harmonic classes: residuals that are multiples of 10 align with
    // the classic capacity fractions and are easier to fill exactly later.
    if post_residual % 10 == 0 && post_residual > 0 {
        score -= 15.0;
    }
    // Odd/awkward classes (mod 10 in {1,3,7,9}) are harder to pair.
    let m = post_residual % 10;
    if m == 1 || m == 3 || m == 7 || m == 9 {
        score += 8.0;
    }

    // Integer-division thresholds: can the lookahead item fit into post_residual?
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            // Excellent chaining: pair (item, next) fills bin tightly.
            let chain_waste = post_residual - next_item_size;
            score -= 60.0 - (chain_waste as f64) * 0.5;
            // Exact two-item closure is the best outcome.
            if chain_waste == 0 {
                score -= 200.0;
            }
        } else {
            // Lookahead cannot follow into this bin; penalize proportionally
            // to how stranded the residual is.
            score += 25.0;
        }
        // Harmonic complement: post_residual + next_item_size exactly = capacity
        // class boundary (multiple of 25) is desirable.
        if (post_residual + next_item_size) % 25 == 0 && next_item_size <= post_residual {
            score -= 20.0;
        }
    }

    // Capacity-fraction thresholds: residuals below quarter capacity are risky.
    let quarter = cap / 4.0;
    let half = cap / 2.0;
    if (post_residual as f64) < quarter && post_residual > 0 {
        score += 30.0;
    } else if (post_residual as f64) >= half {
        score -= 10.0; // bin still flexible
    }

    // Last-chance bin: if this is the only fitting bin, strongly prefer using it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 80.0;
    }

    // New-bin candidate: baseline cost of opening a fresh bin. It should win
    // only when every open bin would leave awkward residue. Score it against
    // the mean residual: if open bins are mostly full, a new bin is fine.
    if bin_residual == bin_capacity {
        score = 40.0 + mean_residual * 0.3;
        // Late in the stream, avoid proliferating bins.
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score += progress * 30.0;
        // If many bins are open, discourage opening yet another.
        score += (open_bins_count as f64) * 2.0;
        // But if the lookahead item is huge and no bin will pair, a fresh bin
        // with full flexibility is valuable.
        if next_item_size > 0 && next_item_size as f64 > cap * 0.5 {
            score -= 15.0;
        }
    }

    // Mild preference for tighter bins overall (best-fit flavor).
    score -= (bin_residual as f64) * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small leftovers are the worst outcome.
    // Treat residuals below the minimum plausible item size as pure waste.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0 - 5.0 * post_residual as f64; // 55..5 penalty for tiny gaps
    }
    // Medium dead space that few items can use (10..30) is also risky.
    if post_residual >= 10 && post_residual < 30 {
        score += 12.0 - 0.3 * post_residual as f64;
    }

    // Reward perfect and near-perfect fits strongly.
    if post_residual == 0 {
        score -= 40.0;
    }

    // Lookahead: if the next item fits exactly into the post residual,
    // this placement chains nicely; reward it.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 25.0;
        } else if post_residual > next_item_size {
            score -= 5.0;
        } else if post_residual > 0 && post_residual < next_item_size {
            // next item cannot use this bin; leftover is likely dead space
            score += 8.0;
        }
    }

    // Last-chance bonus: if this is the only bin that fits, strongly prefer it
    // over opening a new bin (fitting_bins_count == 1 identifies it).
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 20.0;
    }

    // Open-bin pressure: with many open bins, avoid spreading; favor filling
    // existing bins and discourage opening new ones.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    let pressure = open_bins_count as f64 / (1.0 + mean_residual / 20.0);
    score += 0.35 * pressure * (0.5 + progress);

    // New-bin candidate handling: an empty bin gets a baseline cost that grows
    // with open-bin count, so it only wins when existing fits are truly bad.
    if bin_residual == bin_capacity {
        score += 18.0 + 1.5 * open_bins_count as f64;
        // But if no open bin can take the item, opening is necessary.
        if fitting_bins_count == 0 {
            score -= 100.0;
        }
    } else {
        // Slight reward for bins tighter than average (good consolidation).
        if (bin_residual as f64) < mean_residual {
            score -= 3.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;
    let size_f = item_size as f64;
    let nxt = next_item_size as f64;

    // Base: post-residual waste with progress coupling
    let progress_coupling = 1.0 + 2.0 * progress * progress;
    let mut score = pr * progress_coupling;

    // Super-linear penalty on large dead space
    score += 40.0 * norm_pr * norm_pr * norm_pr * norm_pr * cap;

    // Strong bonus for perfect / near-perfect fits
    if post_residual == 0 {
        score -= 1180.0;
    } else if post_residual <= 3 {
        score -= 500.0;
    } else if post_residual <= 12 {
        score -= 98.0;
    } else if post_residual < 20 {
        score += 18.0;
    } else if post_residual < 30 {
        score += 18.0 + (30 - post_residual) as f64 * 0.6;
    }

    // Smooth tightness bump
    let tightness = (-norm_pr * norm_pr / 0.02).exp();
    score -= 25.0 * tightness * cap * (0.5 + progress);

    // Lookahead coupling: chain reuse reward (merged with best-heuristic refinements)
    if next_item_size > 0 {
        let gap = pr - nxt;
        if gap < 0.0 {
            score += 0.5 * (-gap) * (1.0 + progress);
            if (-gap) > 12.0 {
                score += norm_pr * 90.0;
            }
            // near-miss penalty: residual just barely too small for next item
            if (-gap) <= 8.0 {
                score += (9.0 - (-gap)) * 3.5;
            }
            if post_residual > 0 && post_residual < 15 {
                score += 45.0;
            }
            if post_residual > 0 && (-gap) <= 3.0 {
                score += 35.0;
            }
            if pr > mean_residual * 1.4 {
                score -= 12.0;
            }
        } else {
            let fit_bonus = (-(gap / cap) * (-(gap / cap)) / 0.01).exp();
            score -= 12.0 * fit_bonus;
            if post_residual == next_item_size {
                score -= 900.0;
            } else if post_residual % next_item_size == 0 {
                score -= 18.0;
            } else {
                let post2 = post_residual - next_item_size;
                score -= 135.0 - post2 as f64 * 2.0;
                if post2 == 0 { score -= 110.0; }
                if post2 > 0 && post2 < 5 { score -= 28.0; }
                if post2 >= 20 && post2 % 5 == 0 { score -= 12.0; }
                if post2 % 10 == 0 && post2 > 0 { score -= 28.0; }
                if post2 > 0 && post2 <= 2 { score -= 14.0; }
                if post2 > 0 && post2 <= next_item_size / 4 { score -= 10.0; }
                if post_residual >= next_item_size * 2 && post_residual - next_item_size * 2 <= 4 {
                    score -= 20.0;
                }
                let chain = post_residual / next_item_size;
                if chain >= 2 {
                    score -= (chain.min(4)) as f64 * 6.0;
                }
                if post_residual >= next_item_size * 2 && post_residual / 2 >= next_item_size && post_residual % 2 == 0 {
                    score -= 10.0;
                }
            }
        }
    }

    // Last-chance bin
    if fitting_bins_count == 1 {
        score -= 30.0;
    }

    // Consolidation pressure
    score += 0.3 * open_bins_count as f64 * norm_pr;
    score += 0.2 * (mean_residual - bin_residual as f64);

    // NEW-BIN CANDIDATE LOGIC
    if bin_residual == bin_capacity {
        let avg_fill = 1.0 - (mean_residual / cap);
        score += 250.0 - avg_fill * 330.0 - progress * 65.0;
        if size_f > mean_residual {
            score -= 45.0;
        }
        if fitting_bins_count > 0 {
            score += (fitting_bins_count as f64).min(5.0) * 9.0 + 20.0;
            let snug = size_f / bin_residual.max(1) as f64;
            if snug > 0.9 { score += 40.0; }
            if snug > 0.95 { score += 28.0; }
            if snug > 0.98 { score += 18.0; }
        }
        if nxt > 0.0 && nxt >= cap / 2.0 { score -= 32.0; }
        if size_f >= cap * 3.0 / 4.0 { score -= 55.0; }
        if nxt > 0.0 && nxt <= cap - size_f { score -= 25.0; }
        let newbin_waste = (bin_capacity - item_size) as f64;
        if newbin_waste > 0.0 && newbin_waste < mean_residual * 0.6 {
            score -= 30.0;
        }
        if bin_capacity - item_size <= 4 { score -= 70.0; }
        if size_f / cap > 0.85 && mean_residual > cap * 0.35 { score -= 40.0; }
        if nxt > 0 {
            let leftover = bin_capacity - item_size;
            if leftover >= next_item_size {
                let tail = leftover % next_item_size;
                if tail <= 4 { score -= 16.0; }
                if tail == 0 { score -= 10.0; }
            }
            if leftover < next_item_size && leftover < 10 { score += 18.0; }
            if nxt <= cap - size_f && (bin_capacity - item_size) as f64 - nxt <= 6.0 {
                score -= 38.0;
            }
            if leftover >= next_item_size * 2 { score -= 14.0; }
        }
        if fitting_bins_count > 0 {
            let best_alt = if item_size as f64 <= mean_residual { mean_residual - size_f } else { mean_residual };
            if newbin_waste > best_alt + cap * 0.08 { score += 22.0; }
            if newbin_waste > best_alt + cap * 0.2 { score += 14.0; }
        }
        if progress > 0.6 && fitting_bins_count > 0 {
            let waste_tol = (1.0 - progress) * cap * 0.35;
            if newbin_waste > waste_tol {
                score += 10.0 + progress * 22.0;
            }
        }
        if progress > 0.85 && newbin_waste > cap * 0.3 {
            score += 8.0;
        }
    } else {
        // Existing-bin refinements
        let dead_ratio = pr / cap;
        if dead_ratio < 0.03 {
            score -= 38.0;
        } else if dead_ratio < 0.08 {
            score -= 14.0;
        } else if dead_ratio > 0.35 {
            score += 24.0;
        } else if dead_ratio > 0.25 {
            score += 10.0;
        }
        if post_residual > 0 && pr < mean_residual * 0.25 {
            score -= 15.0;
        }
        if item_size == bin_residual {
            score -= 45.0;
        }
        if next_item_size > 0 && post_residual > 0 && pr > nxt * 3.0 && post_residual < bin_capacity / 3 {
            score += 12.0;
        }
        if fitting_bins_count <= 2 && post_residual > 0 {
            score -= 8.0;
        }
        // unusable-for-next dead space penalty scaled by progress
        if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
            let wasted = nxt - pr;
            score += wasted * 0.6 + (1.0 - progress) * 14.0;
            if pr > mean_residual * 1.3 { score += 8.0; }
            if dead_ratio > 0.2 { score += dead_ratio * 30.0; }
        } else if next_item_size > 0 && post_residual > 0 {
            let reuse = (post_residual / next_item_size) as f64 * (nxt / cap);
            score -= reuse * 22.0;
            if post_residual >= next_item_size * 2 { score -= 6.0; }
        }
        if post_residual > 0 && post_residual < 6 {
            score -= 22.0;
        }
        if post_residual > 0 && (pr) < cap * 0.015 {
            score -= 18.0;
        }
        if post_residual > 0 && post_residual % 5 == 0 && post_residual <= 30 {
            score -= 8.0;
        }
        if post_residual > 0 && next_item_size > 0 && post_residual + next_item_size <= bin_capacity && pr < mean_residual * 0.5 {
            score -= 9.0;
        }
        // distance-from-mean shaping
        if post_residual > 0 {
            let dist = (pr - mean_residual.max(1.0)).abs();
            score += dist * 0.35;
            if dist < cap * 0.03 { score -= 10.0; }
        }
        if post_residual > 0 && pr > mean_residual * 1.6 && fitting_bins_count > 2 {
            score += 10.0;
        }
        if post_residual + item_size as f64 <= cap / 2.0 && post_residual > item_size * 3 {
            score += 9.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Exact-fit bonus: perfectly filled bins are ideal.
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Aggressive 2-step lookahead: reward bins whose post residual
    // matches the next item size well (chained placements).
    if next_item_size > 0 {
        let gap = (post_residual as i64 - next_item_size as i64).abs() as f64;
        if gap <= 5.0 {
            score -= 60.0 - 8.0 * gap; // near-perfect chain fit
        } else if post_residual >= next_item_size {
            score -= 20.0 / gap; // next item still fits: mild reward
        } else {
            // next item won't fit here; penalize proportionally to waste
            score += 0.5 * (next_item_size - post_residual) as f64;
        }
    }

    // Compare post_residual against mean residual: leaving less than
    // average waste is good, more is bad (dead space creation).
    score += 0.6 * (post_residual as f64 - mean_residual);

    // Penalize creating tiny unusable residuals (dead space) that
    // likely can't fit typical items (>= 10).
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Last-chance bin: if this is the only bin that fits, avoid opening
    // a new bin unless the fit is terrible.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // New-bin candidate: penalize moderately so it's chosen only when
    // all open bins fit poorly, but keep it attractive early in stream.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 30.0 - 20.0 * progress;
    }

    // Slight preference for fuller bins among many open bins.
    score -= 0.1 * (bin_capacity - bin_residual) as f64 / open_bins_count.max(1) as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let score = post_residual as f64;
    score
