pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Classic best-fit sharpening: reward tight fits nonlinearly.
    let tightness = 1.0 - (post_residual as f64) / (bin_capacity as f64);
    score -= 14.0 * tightness * tightness * tightness;

    // Penalize dead space: residuals too small to hold even a small item.
    if post_residual > 0 && post_residual < 10 {
        score += 22.0;
    }

    // Lookahead coupling: if next item fits the post-residual exactly-ish, big reward.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 30.0;
        } else if next_item_size <= post_residual {
            let gap = (post_residual - next_item_size) as f64;
            score -= 8.0 * (1.0 - gap / (bin_capacity as f64));
        } else {
            // Next item won't fit here; mild penalty for squandering residual.
            let waste = (next_item_size - post_residual) as f64;
            score += 0.15 * waste;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 25.0;
    }

    // Time horizon: early in stream, prefer consolidating into few bins;
    // late in stream, be less conservative about opening fresh bins.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score -= 6.0 * progress * (1.0 - tightness);

    // Global state: many open bins with high mean residual -> discourage new bins,
    // encourage filling underused ones.
    if bin_residual == bin_capacity {
        // New-bin candidate baseline: slightly above current mean residual usage.
        let mut new_bin_score = bin_capacity as f64 - 18.0 * (mean_residual / bin_capacity as f64);
        if open_bins_count > 0 && mean_residual > 0.0 {
            // If plenty of slack exists across open bins, penalize opening new bin.
            new_bin_score += 0.35 * (mean_residual - item_size as f64).max(0.0);
        }
        if progress < 0.15 {
            new_bin_score += 5.0 * (1.0 - progress / 0.15);
        }
        return new_bin_score;
    }

    // Prefer bins whose residual is close to item (harmony with mean residual).
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += 0.08 * dev;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let progress = step_index as f64 / total_items.max(1) as f64;
    let fit_ratio = item_size as f64 / cap;

    // Base: penalize wasted residual, quadratically (dead space is super-linearly bad)
    let mut score = post * post / cap;

    // Smooth coupling: early in the stream, prefer tight fills; later, tolerate slack
    let tightness = (1.0 - post / cap).powi(3);
    score -= tightness * (1.0 + 2.0 * progress) * 10.0;

    // Reward leaving room for the next item (smooth bump when post_residual ~ next_item_size)
    if next_item_size > 0 {
        let gap = post - next_item_size as f64;
        let bump = (-gap * gap / (2.0 * (cap * 0.05).powi(2))).exp();
        score -= bump * 8.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 {
        score -= 15.0;
    }

    // Mild penalty when bin's residual deviates from the mean (encourage balance)
    score += ((bin_residual as f64 - mean_residual) / cap).abs() * 2.0;

    // Slight preference for consolidating into fewer bins as stream progresses
    score += (open_bins_count as f64 / (1.0 + progress)) * 0.05;

    // New-bin candidate: make it mildly unattractive unless residuals are very tight
    if bin_residual == bin_capacity {
        score += 6.0 - 6.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
