pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit reward
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Harmonic class of post_residual: mod-10 buckets (classic waste classes)
    let r10 = post_residual % 10;
    let r20 = post_residual % 20;
    // Small dead-space classes are bad; large clean classes may host small items later.
    score += match r10 {
        0 => -8.0,
        1 | 2 => 6.0,   // nearly unusable slivers
        9 => 3.0,
        _ => 0.0,
    };
    // mod-20 harmonic refinement
    if r20 == 0 { score -= 5.0; }
    if r20 == 10 { score -= 2.0; }

    // Integer-division thresholds on post_residual: usable zone vs dead zone
    if post_residual >= bin_capacity / 2 {
        score += 12.0; // leaving half a bin empty is wasteful
    } else if post_residual <= 10 {
        score += 4.0; // tiny residual is fine but not perfect
    }

    // Lookahead coupling: does next item fit into post_residual?
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            // harmonic class match: exact fit next step
            if post_residual == next_item_size { score -= 60.0; }
            else { score -= 10.0 + (post_residual - next_item_size) as f64 * 0.3; }
            // bonus if next item lands post_residual in a clean mod class
            let nr = post_residual - next_item_size;
            if nr % 10 == 0 { score -= 6.0; }
        } else {
            // next item won't fit here; penalize tight residuals slightly
            score += (next_item_size - post_residual) as f64 * 0.1;
        }
    }

    // Last-chance bin: strongly favor using it
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate: only attractive when open bins fit poorly
    if bin_residual == bin_capacity {
        score = 55.0
            + mean_residual * 0.2
            - (open_bins_count as f64) * 1.5
            + (step_index as f64 / (total_items as f64).max(1.0)) * 10.0;
        if next_item_size > 0 && next_item_size > item_size {
            score -= 8.0; // big item coming, fresh bin useful
        }
        if fitting_bins_count == 1 { score += 20.0; } // discourage abandoning last chance
    }

    // Mild preference for tighter bins overall
    score += (bin_residual as f64 - mean_residual) * 0.15;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: gaps too small for the smallest plausible item are pure waste.
    if post_residual > 0 {
        let min_item = 1.0f64;
        let gap = post_residual as f64;
        if gap < 10.0 {
            // tiny dead sliver: heavily penalize
            score += (10.0 - gap) * 6.0;
        }
        // penalize gaps that cannot fit the lookahead item either
        if next_item_size > 0 && gap < next_item_size as f64 {
            score += (next_item_size as f64 - gap) * 1.5;
        }
        // reward gaps that can still accommodate a future item proportionally
        if next_item_size > 0 && gap >= next_item_size as f64 {
            score -= (gap - next_item_size as f64) * 0.3;
        }
        let _ = min_item;
    }

    // Perfect fit bonus
    if post_residual == 0 {
        score -= 25.0;
    }

    // Last-chance bin: if this is the only bin that fits, avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 12.0;
    }

    // Open-bin pressure: with many open bins, prefer filling existing ones over new bins
    let progress = step_index as f64 / (total_items.max(1) as f64);
    let pressure = open_bins_count as f64 * (0.4 + 0.6 * progress);
    if bin_residual == bin_capacity {
        // new-bin candidate: penalize more when many bins are open or mean residual is large
        score += pressure * 2.0 + mean_residual * 0.8;
        // but a new bin is attractive when the item barely fits elsewhere (large post_residual elsewhere)
        if item_size >= 60 {
            score -= 5.0;
        }
    } else {
        // existing bin: mild reward scaled by how much of the bin we consume
        let fill_ratio = item_size as f64 / bin_capacity as f64;
        score -= fill_ratio * 10.0;
        // prefer bins with residuals close to the item (tight fits)
        let tightness = 1.0 - (bin_residual as f64 - item_size as f64) / bin_capacity as f64;
        score -= tightness * 4.0;
    }

    // Mean-residual coupling: when mean residual is small, existing bins are nearly full, favor new bin less aggressively
    if bin_residual != bin_capacity {
        score -= (mean_residual / bin_capacity as f64) * 3.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward exact or near-exhaustive fits strongly.
    if post_residual == 0 {
        score -= 1000.0;
    } else if post_residual <= 5 {
        score -= 300.0;
    } else if post_residual <= 10 {
        score -= 120.0;
    }

    // Aggressive 2-step lookahead: if next item fits exactly in the post residual,
    // this is a perfect chain placement.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 500.0;
        } else if post_residual > next_item_size {
            let gap = (post_residual - next_item_size) as f64;
            // Reward chains where the next item leaves little dead space after it.
            score -= 200.0 * (1.0 - gap / bin_capacity as f64).max(0.0);
        } else {
            // Next item won't fit here; penalize leftover residual that is too small
            // to be useful for typical items (dead space).
            let dead = post_residual as f64;
            if dead < 10.0 {
                score += 250.0 * (10.0 - dead);
            }
        }
    }

    // Relative-to-mean coupling: prefer bins whose residual after placement
    // stays close to the mean residual (keeps options balanced), unless it's a
    // near-perfect fit which we already rewarded.
    let dev = (post_residual as f64 - mean_residual).abs();
    score += 0.5 * dev;

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 400.0;
    }

    // New-bin candidate: default cost of opening a fresh bin. Make it attractive
    // only when no open bin offers a good (tight or chainable) fit.
    if bin_residual == bin_capacity {
        score += 150.0;
        // If lookahead shows the next item pairs with this item in a fresh bin
        // (item + next <= capacity), a new bin is a great chain start.
        if next_item_size > 0 && item_size + next_item_size <= bin_capacity {
            score -= 220.0;
        }
        // Late in the stream, avoid proliferating bins.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 100.0 * progress;
    }

    // Mild penalty for spreading across many open bins when residual is large.
    if open_bins_count > 4 && post_residual > 40 {
        score += 0.5 * open_bins_count as f64;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
