pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tightness reward: strongly favor bins where the item fills most of the residual.
    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 40.0 * fit_ratio * fit_ratio;

    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 25.0;
    } else if post_residual < 10 {
        score -= 12.0; // near-perfect fit leaves unusable sliver, that's fine
    }

    // Penalize leaving large dead space that small future items could still use poorly.
    if post_residual > 0 && post_residual < item_size {
        score += 5.0; // awkward leftover smaller than the current item class
    }

    // Lookahead: if the next item fits exactly in the post residual, big reward.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 30.0;
        } else if next_item_size <= post_residual {
            // next item still fits: mild reward proportional to leftover tightness
            score -= 10.0 * (next_item_size as f64 / post_residual as f64);
        } else {
            // next item won't fit here: penalize more if we created large unusable gap
            score += 0.15 * (post_residual as f64 - (post_residual % next_item_size.max(1)) as f64);
        }
    }

    // Last-chance bin: if this is the only fitting bin, strongly prefer using it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 20.0;
    }

    // New-bin candidate handling: opening a bin is expensive when many open bins
    // still have room; cheap early in the stream or when open bins are nearly full.
    if bin_residual == bin_capacity {
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        let avg_fill = mean_residual / bin_capacity as f64; // high mean residual => open bins are empty-ish
        let pressure = open_bins_count as f64 * (1.0 - avg_fill);
        score = 55.0 + 30.0 * progress + 3.0 * pressure - 0.5 * mean_residual;
        // If no bin fits at all, opening is the only option: make it attractive.
        if fitting_bins_count == 0 {
            score -= 100.0;
        }
    }

    // Mild global consolidation: when many bins are open, prefer bins below mean residual
    // (fill the emptier ones first to consolidate).
    if bin_residual < bin_capacity {
        if (bin_residual as f64) < mean_residual {
            score -= 4.0;
        } else {
            score += 2.0;
        }
    }

    // Time-horizon modulation: late in the stream, prioritize closing bins tightly.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score -= 8.0 * progress * fit_ratio;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;

    // Base: prefer small post_residual, with non-linear (quadratic) sharpening
    let mut score = pr + 20.0 * norm_pr * norm_pr * cap;

    // Smooth polynomial coupling with stream progress:
    // early on, waste matters less; later, tighten packing harder
    let prog_term = 1.0 + 2.0 * progress * progress;
    score *= prog_term;

    // Reward near-perfect fits smoothly (cubic trough at norm_pr ~ 0)
    score -= 15.0 * (1.0 - norm_pr) * (1.0 - norm_pr) * (1.0 - norm_pr) * 0.0
        + 12.0 * (1.0 - norm_pr) * (1.0 - norm_pr) * item_size as f64 / cap;

    // Lookahead: penalize leaving residual that fails to fit the next item
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if pr < nxt {
            score += 8.0 * (nxt - pr) / cap * (1.0 + progress);
        } else {
            // smooth reward when next item also fits
            score -= 4.0 * (pr - nxt) / cap;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 {
        score -= 25.0;
    } else if fitting_bins_count > 1 {
        // mild competition scaling
        score += 2.0 * (fitting_bins_count as f64 - 1.0).ln().max(0.0);
    }

    // Penalize bins far from mean residual (fragmentation smoothing), smooth quadratic
    let dev = pr - mean_residual;
    score += 0.05 * dev * dev / cap;

    // Penalize opening a new bin when open bins exist, more so late in stream
    if bin_residual == bin_capacity && open_bins_count > 0 {
        score += 30.0 + 40.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit reward
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Harmonic class: residual capacity fraction of bin
    let frac = bin_residual as f64 / bin_capacity as f64;
    let ifrac = frac * 4.0; // quarter-capacity harmonic classes
    let class = ifrac.floor() as i64; // 0..4
    match class {
        0 => score += 50.0,          // tiny residual: nearly useless bin, penalize
        1 => score += 10.0,          // quarter class
        2 => score -= 5.0,           // half class: good target
        3 => score -= 15.0,          // three-quarters: very reusable
        _ => score -= 20.0,          // full/empty class
    }

    // Modulo logic on post_residual: residuals that pair with common item classes
    let pr = post_residual;
    if pr > 0 {
        // residual divisible by common small sizes => likely reusable
        if pr % 10 == 0 { score -= 8.0; }
        if pr % 20 == 0 { score -= 6.0; }
        if pr % 25 == 0 { score -= 4.0; }
        // awkward residuals (prime-ish / odd small leftovers)
        if pr < 10 { score += 30.0; }
    }

    // Lookahead coupling: does next item fit into post_residual?
    if next_item_size > 0 {
        if next_item_size <= pr {
            // next item chains perfectly: strong reward, scaled by tightness
            let tight = 1.0 - (pr - next_item_size) as f64 / bin_capacity as f64;
            score -= 25.0 + 20.0 * tight;
        } else {
            // next item won't fit here: slight penalty proportional to gap
            score += 5.0 + 0.1 * ((next_item_size - pr) as f64);
        }
        // harmonic pairing: next_item_size + item_size divides capacity evenly
        if (item_size + next_item_size) % 50 == 0 || (item_size + next_item_size) == bin_capacity {
            score -= 12.0;
        }
    }

    // Last-chance bin: strongly prefer using it before opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // New-bin candidate: penalize opening a new bin unless current fits are bad
    if bin_residual == bin_capacity {
        score += 35.0;
        if fitting_bins_count == 0 { score -= 60.0; }
        // early stream: be liberal with new bins
        if total_items > 0 && (step_index as f64) / (total_items as f64) < 0.2 {
            score -= 10.0;
        }
    }

    // Mean residual coupling: prefer bins deviating favorably from mean
    score += 0.3 * (mean_residual - bin_residual as f64).abs() * (bin_residual as f64 - mean_residual).signum();

    // Many open bins: encourage consolidation into existing bins
    if open_bins_count > 3 {
        score -= 0.5 * open_bins_count as f64;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap_f = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Dead-space avoidance (borrowed stronger tiers from best heuristic)
    if post_residual == 0 {
        score -= 900.0;
    } else if post_residual <= 3 {
        score -= 300.0;
    } else if post_residual < 10 {
        score += 60.0;
    } else if post_residual < 20 {
        score += 18.0 + (20 - post_residual) as f64 * 0.4;
    } else if post_residual > 60 {
        score += 12.0;
    }

    // Compaction pressure
    score += open_bins_count as f64 * 0.8;

    // Last-chance bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // Lookahead on next item
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 400.0;
        } else if post_residual >= next_item_size {
            let post2 = post_residual - next_item_size;
            score -= 60.0 - post2 as f64 * 1.5;
            if post2 == 0 { score -= 60.0; }
            if post2 > 0 && post2 < 5 { score -= 20.0; }
            if post_residual % next_item_size == 0 { score -= 12.0; }
        } else {
            // next item won't fit here: penalize small dead residual
            if post_residual > 0 && (next_item_size - post_residual) <= 3 {
                score += 35.0;
            }
            if post_residual > 0 && post_residual < 15 {
                score += 40.0;
            }
            if post_residual as f64 > mean_residual * 1.4 {
                score -= 12.0;
            }
        }
    }

    // Tighter fits via fill ratio
    score -= (item_size as f64 / cap_f) * 10.0;

    // NEW-BIN CANDIDATE handling
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let avg_fill = 1.0 - (mean_residual / cap_f);
        score += 220.0 - avg_fill * 300.0 - progress * 70.0;

        if item_size as f64 > mean_residual {
            score -= 40.0;
        }
        if fitting_bins_count > 0 {
            score += fitting_bins_count.min(5) as f64 * 8.0;
            let snug = item_size as f64 / bin_residual.max(1) as f64;
            if snug > 0.9 { score += 35.0; }
            if snug > 0.95 { score += 25.0; }
        }
        if item_size >= bin_capacity * 3 / 4 {
            score -= 50.0;
        }
        let newbin_waste = (bin_capacity - item_size) as f64;
        if next_item_size > 0 {
            let leftover = bin_capacity - item_size;
            if leftover >= next_item_size {
                let tail = leftover % next_item_size;
                if tail == 0 { score -= 14.0; }
                else if tail <= 4 { score -= 10.0; }
            }
        }
        if progress > 0.6 {
            let waste_tol = (1.0 - progress) * cap_f * 0.35;
            if newbin_waste > waste_tol && fitting_bins_count > 0 {
                score += 10.0 + progress * 20.0;
            }
        }
    } else {
        // Open-bin branch: prefer bins whose residual is close to mean (harmonize)
        let tightness = 1.0 - (item_size as f64 / bin_residual.max(1) as f64);
        score += tightness * 60.0;
        score += (mean_residual - bin_residual as f64) * 1.2;

        if item_size == bin_residual {
            score -= 45.0;
        }
        let dead_ratio = post_residual as f64 / cap_f;
        if dead_ratio < 0.03 {
            score -= 30.0;
        } else if dead_ratio > 0.35 {
            score += 20.0;
        }
        if post_residual > 0 && next_item_size > 0 && post_residual < next_item_size {
            let gap = next_item_size as f64 - post_residual as f64;
            if gap > mean_residual * 0.6 && fitting_bins_count > 2 {
                score += gap * 0.7;
            }
        }
        if post_residual > 0 && next_item_size > 0 && post_residual >= next_item_size * 2 {
            score -= 6.0;
        }
        if post_residual > 0 && post_residual % 10 == 0 {
            score -= 8.0;
        }
    }

    // Early stream: slight diversity
    let progress = step_index as f64 / total_items.max(1) as f64;
    if progress < 0.1 {
        score += 3.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals that are too small to hold
    // even the smallest future item (1..=100 unknown) are "dead space".
    // Penalize small nonzero post_residuals super-linearly.
    if post_residual > 0 && post_residual < 20 {
        score += (20 - post_residual) as f64 * 3.0;
    }

    // Perfect or near-perfect fits are heavily rewarded.
    if post_residual == 0 {
        score -= 25.0;
    } else if post_residual <= 5 {
        score -= 10.0;
    }

    // Reward leaving room for the lookahead item if it fits.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 6.0;
    } else if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        // Creating a gap just smaller than the next item is wasteful.
        score += 4.0;
    }

    // Open-bin pressure: with many open bins, prefer packing tighter
    // into existing bins rather than spreading.
    score += (open_bins_count as f64) * 0.8;

    // Last-chance bin: strongly favor using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate: only attractive when current bin fits poorly
    // (large post_residual waste relative to capacity) or residuals are
    // generally tight. Penalize opening new bins under normal conditions.
    if bin_residual == bin_capacity {
        score += 30.0 + mean_residual * 0.3;
        if fitting_bins_count > 0 && post_residual >= 0 {
            // extra push to reuse existing bins when a reasonable fit exists
            score += 10.0;
        }
    }

    // Prefer bins whose residual is close to the item (tight fit).
    let tightness = (bin_residual as f64 - item_size as f64) / bin_capacity as f64;
    score += tightness * 8.0;

    // Mild stream-progression bias: later in the stream, consolidate more.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += progress * 3.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Aggressive 2-step lookahead: reward exact/near match between post_residual
    // and the next item size (perfect two-item chaining).
    if next_item_size > 0 {
        let lookahead_gap = (post_residual as i64 - next_item_size as i64).abs() as f64;
        // Perfect match => strong reward; decays quadratically with gap.
        let match_reward = 30.0 * (1.0 - (lookahead_gap / 40.0).min(1.0)).powi(2);
        score -= match_reward;

        // If next item fits exactly after this one, this is a golden pairing.
        if post_residual == next_item_size {
            score -= 25.0;
        }
        // If next item cannot fit anywhere else afterwards, prefer keeping room for it.
        if post_residual < next_item_size && post_residual > 0 {
            score += 0.5 * (next_item_size - post_residual) as f64;
        }
    }

    // Penalize residuals that are dead space (too small for the smallest plausible item).
    let min_item = 1u32;
    if post_residual < min_item.max(next_item_size.min(item_size)) {
        score += 10.0;
    }

    // Relative-to-mean-residual coupling: prefer bins whose post_residual is close
    // to the mean residual (keeps the fleet homogeneous and predictable).
    let mean_gap = (post_residual as f64 - mean_residual).abs();
    score += 0.15 * mean_gap;

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 20.0;
    }

    // Late in the stream, prefer tighter packing (smaller post_residual) more aggressively.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score *= 1.0 + 0.5 * progress;

    // Mild penalty for spreading across many open bins; encourage consolidation.
    score += 0.05 * open_bins_count as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;
    let size_f = item_size as f64;
    let nxt = next_item_size as f64;

    // Base: post-residual waste with progress coupling
    let progress_coupling = 1.0 + 2.0 * progress * progress;
    let mut score = pr * progress_coupling;

    // Super-linear penalty on large dead space
    score += 40.0 * norm_pr * norm_pr * norm_pr * norm_pr * cap;

    // Perfect / near-perfect fit rewards
    if post_residual == 0 {
        score -= 1180.0;
    } else if post_residual <= 3 {
        score -= 500.0;
    } else if post_residual <= 12 {
        score -= 98.0;
    } else if post_residual < 20 {
        score += 18.0;
    } else if post_residual < 30 {
        score += 18.0 + (30 - post_residual) as f64 * 0.6;
    }

    // Smooth tightness bump
    let tightness = (-norm_pr * norm_pr / 0.02).exp();
    score -= 25.0 * tightness * cap * (0.5 + progress);

    // Lookahead coupling: chain reuse reward
    if next_item_size > 0 {
        let gap = pr - nxt;
        if gap < 0.0 {
            score += 0.5 * (-gap) * (1.0 + progress);
            if (-gap) > 12.0 {
                score += norm_pr * 90.0;
            }
            // near-miss dead space: next item almost fits
            if (-gap) <= 3.0 {
                score += 35.0;
            }
            if post_residual > 0 && post_residual < 15 {
                score += 45.0;
            }
        } else {
            let fit_bonus = (-(gap / cap) * (-(gap / cap)) / 0.01).exp();
            score -= 12.0 * fit_bonus;
            if post_residual == next_item_size {
                score -= 900.0;
            } else if post_residual % next_item_size == 0 {
                score -= 18.0;
            } else {
                let post2 = post_residual - next_item_size;
                score -= 135.0 - post2 as f64 * 2.0;
                if post2 == 0 { score -= 110.0; }
                if post2 > 0 && post2 < 5 { score -= 28.0; }
                if post2 > 0 && post2 <= 2 { score -= 14.0; }
                if post2 > 0 && post2 % 10 == 0 { score -= 28.0; }
                if post2 >= 20 && post2 % 5 == 0 { score -= 12.0; }
                if post2 > 0 && post2 <= next_item_size / 4 { score -= 10.0; }
                if post2 > 0 && post2 <= next_item_size / 2 && post2 > next_item_size / 4 { score -= 4.0; }
                // two-step lookahead: residual holds next item twice with tiny tail
                if post_residual >= next_item_size * 2 && post_residual - next_item_size * 2 <= 4 {
                    score -= 20.0;
                }
                let chain = post_residual / next_item_size;
                if chain >= 2 {
                    score -= (chain.min(4)) as f64 * 6.0;
                }
                if post_residual / 2 >= next_item_size && post_residual % 2 == 0 {
                    score -= 10.0;
                }
            }
        }
    }

    // Last-chance bin
    if fitting_bins_count == 1 {
        score -= 30.0;
    }

    // Consolidation pressure
    score += 0.3 * open_bins_count as f64 * norm_pr;
    score += 0.2 * (mean_residual - bin_residual as f64);

    // NEW-BIN CANDIDATE LOGIC
    if bin_residual == bin_capacity {
        let avg_fill = 1.0 - (mean_residual / cap);
        score += 250.0 - avg_fill * 330.0 - progress * 65.0;
        if size_f > mean_residual {
            score -= 45.0;
        }
        if fitting_bins_count > 0 {
            score += (fitting_bins_count as f64).min(5.0) * 9.0 + 20.0;
            let snug = size_f / bin_residual.max(1) as f64;
            if snug > 0.9 { score += 40.0; }
            if snug > 0.95 { score += 28.0; }
            if snug > 0.98 { score += 18.0; }
        }
        if nxt > 0.0 && nxt >= cap / 2.0 { score -= 32.0; }
        if size_f >= cap * 3.0 / 4.0 { score -= 55.0; }
        if nxt > 0.0 && nxt <= cap - size_f { score -= 25.0; }
        let newbin_waste = (bin_capacity - item_size) as f64;
        if newbin_waste > 0.0 && newbin_waste < mean_residual * 0.6 {
            score -= 30.0;
        }
        // leftover tail compatibility with next item
        if next_item_size > 0 {
            let leftover = bin_capacity - item_size;
            if leftover >= next_item_size {
                let tail = leftover % next_item_size;
                if tail == 0 { score -= 10.0; }
                else if tail <= 4 { score -= 16.0; }
            }
            if leftover < next_item_size && leftover < 10 { score += 18.0; }
            if next_item_size <= leftover && leftover - next_item_size <= 6 { score -= 38.0; }
            if leftover >= next_item_size * 2 { score -= 14.0; }
        }
        // compare against best alternative waste
        if fitting_bins_count > 0 {
            let best_alt = if item_size as f64 <= mean_residual { mean_residual - size_f } else { mean_residual };
            if newbin_waste > best_alt + cap * 0.08 { score += 22.0; }
            if newbin_waste > best_alt + cap * 0.2 { score += 14.0; }
        }
        if progress > 0.6 && fitting_bins_count > 0 {
            let waste_tol = (1.0 - progress) * cap * 0.35;
            if newbin_waste > waste_tol {
                score += 10.0 + progress * 22.0;
            }
        }
        if progress > 0.75 && newbin_waste > cap * 0.5 { score += 12.0; }
        if progress > 0.85 && newbin_waste > cap * 0.3 { score += 8.0; }
        if newbin_waste <= 4.0 { score -= 70.0; }
        if fitting_bins_count > 3 && size_f / cap < 0.5 { score += 30.0; }
    } else {
        // Existing-bin refinements
        let dead_ratio = pr / cap;
        if dead_ratio < 0.03 {
            score -= 38.0;
        } else if dead_ratio < 0.08 {
            score -= 14.0;
        } else if dead_ratio > 0.35 {
            score += 24.0;
        } else if dead_ratio > 0.25 {
            score += 10.0;
        }
        if post_residual > 0 && pr < mean_residual * 0.25 {
            score -= 15.0;
        }
        if item_size == bin_residual {
            score -= 45.0;
        }
        if next_item_size > 0 && post_residual > 0 && pr > nxt * 3.0 && post_residual < bin_capacity / 3 {
            score += 12.0;
        }
        if fitting_bins_count <= 2 && post_residual > 0 {
            score -= 8.0;
        }
        // unusable-for-next dead space penalty scaled by progress
        if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
            let wasted = nxt - pr;
            score += wasted * 0.6 + (1.0 - progress) * 14.0;
            if wasted > 12.0 && dead_ratio > 0.2 {
                score += dead_ratio * 30.0;
            }
            if wasted > mean_residual * 0.6 && fitting_bins_count > 2 {
                score += wasted * 0.8;
            }
        }
        // usable dead space: reuse reward
        if next_item_size > 0 && post_residual > 0 && post_residual >= next_item_size {
            let reuse = (post_residual / next_item_size) as f64 * (next_item_size as f64 / cap);
            score -= reuse * 22.0;
            if post_residual <= next_item_size + 4 {
                score -= 22.0;
            }
        }
        // small residual bonuses
        if post_residual > 0 && post_residual < 6 { score -= 22.0; }
        if post_residual > 0 && post_residual % 10 == 0 { score -= 10.0; }
        if post_residual > 0 && post_residual % 5 == 0 && post_residual <= 30 { score -= 8.0; }
        if post_residual > 0 && (pr) < cap * 0.015 { score -= 18.0; }
        if post_residual > 0 && next_item_size > post_residual && post_residual < 25 {
            score += (25 - post_residual) as f64 * 1.2;
        }
        // near-miss for next item
        if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size
            && (next_item_size - post_residual) <= 3 {
            score += 35.0;
        }
        // residual close to mean is neutral-good
        if post_residual > 0 {
            let dist = (pr - mean_residual.max(1.0)).abs();
            score += dist * 0.35;
            if dist < cap * 0.03 { score -= 10.0; }
        }
        if post_residual > 0 && pr > mean_residual * 1.6 && fitting_bins_count > 2 {
            score += 10.0;
        }
        if post_residual > 0 && next_item_size > 0 && post_residual + next_item_size <= bin_capacity
            && pr < mean_residual * 0.5 {
            score -= 9.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tight fit reward: strongly favor bins where the item fills most of the space.
    let fill_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 12.0 * fill_ratio * fill_ratio;

    // Penalize dead space: residual too small for the smallest plausible item.
    if post_residual > 0 && post_residual < 10 {
        score += 30.0;
    }

    // Lookahead coupling: reward if post_residual exactly accommodates next item,
    // penalize if next item nearly fits but not quite (wasted near-fit).
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 25.0;
        } else if next_item_size > post_residual && next_item_size <= post_residual + 10 {
            score += 10.0;
        }
        // Bonus for leaving space that still fits the next item comfortably.
        if post_residual >= next_item_size && post_residual < next_item_size + 15 {
            score -= 8.0;
        }
    }

    // Last-chance dynamics: if this is the only fitting bin, strongly prefer using it
    // over opening a new bin (unless the fit is terrible).
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0 + 0.15 * item_size as f64;
    }

    // New-bin candidate handling: penalize opening a new bin when good fits exist.
    if bin_residual == bin_capacity {
        let pressure = if fitting_bins_count > 0 { 1.0 } else { 0.0 };
        score += 35.0 * pressure
            + 0.05 * open_bins_count as f64
            - 10.0 * (1.0 - (step_index as f64 / (total_items as f64).max(1.0)));
    }

    // Global state: many open bins with high mean residual -> favor consolidation
    // into bins below mean residual (tighter bins).
    if open_bins_count > 1 {
        let dev = mean_residual - post_residual as f64;
        score += 0.05 * dev;
    }

    // Time horizon: late in the stream, be more conservative (prefer tight packing).
    let progress = step_index as f64 / (total_items as f64).max(1.0);
    score *= 1.0 + 0.2 * progress;

    // Prefer bins with larger residual absorbing large items (best-fit inverted for big items).
    if item_size > 60 && bin_residual >= item_size {
        score -= 5.0;
    }

    score
}

