            score -= 12.0 * (1.0 - (pr - nxt) / cap) * (0.4 + 0.6 * progress);
        } else {
            score += 6.0 * (nxt - pr) / cap;
        }
    }

    // New-bin candidate: mildly penalize early, penalize more when open bins fit poorly
    if bin_residual == bin_capacity {
        score += 30.0 * (1.0 - progress) + 5.0 * (fitting_bins_count as f64);
    }

    // Slight preference to fill existing bins as open bins accumulate
    score += 0.5 * open_bins_count as f64 * norm_pr;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit is unbeatable.
    if post_residual == 0 {
        return -1000.0;
    }

    // Harmonic class of the post-residual: classify leftover space by
    // capacity fractions (1/2, 1/3, 1/4 of capacity) via integer division.
    let cap = bin_capacity as f64;
    let half = (cap / 2.0) as u32;
    let third = (cap / 3.0) as u32;
    let quarter = (cap / 4.0) as u32;

    // Dead-space penalty grows super-linearly when the leftover is too small
    // to host any plausible future item (items >= 1, but useful class >= 10).
    if post_residual < 10 {
        score += 60.0 + (10 - post_residual) as f64 * 8.0;
    } else {
        // Harmonic bucket: how many "thirds" of capacity remain.
        let bucket = post_residual / third.max(1);
        score -= bucket as f64 * 6.0;
    }

    // Reward leaving exactly a half/third/quarter class residual
    // (classic harmonic-friendly leftovers).
    if post_residual == half || post_residual == third || post_residual == quarter {
        score -= 12.0;
    }

    // Modulo arithmetic on post_residual: multiples of small harmonics (5, 10)
    // pair well with common item sizes.
    if post_residual % 10 == 0 {
        score -= 5.0;
    } else if post_residual % 5 == 0 {
        score -= 2.5;
    }

    // Lookahead coupling: if the next item fits exactly in the post-residual,
    // strongly favor this bin (chained perfect fit).
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 200.0;
        } else if next_item_size < post_residual {
            let next_post = post_residual - next_item_size;
            // Reward chains that also leave a harmonic-class remainder.
            if next_post % 10 == 0 {
                score -= 15.0;
            }
            score -= (next_post.min(40)) as f64 * 0.3;
        } else {
            // Next item cannot follow in this bin: penalize tight leftovers
            // that block the lookahead item.
            if post_residual < next_item_size && post_residual >= next_item_size - 5 {
                score += 10.0;
            }
        }
    }

    // Last-chance bin: if this is the only bin that fits, strongly prefer it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 80.0;
    }

    // New-bin candidate handling: opening a fresh bin wastes capacity if any
    // open bin gives a decent fit. Penalize the empty-bin call unless the
    // item is large relative to residual (poor fits elsewhere).
    if bin_residual == bin_capacity {
        let fill = item_size as f64 / cap;
        // A new bin is only attractive for very large items or many open bins
        // with scattered residuals.
        score += 25.0 - fill * 30.0 + open_bins_count as f64 * 2.0;
        if next_item_size > 0 && next_item_size + item_size <= bin_capacity {
            score -= 20.0; // new bin can host item + lookahead pair
        }
    }

    // Progress-based tightening: late in the stream, prefer tighter packing
    // (smaller post_residual weighted more).
    let progress = step_index as f64 / total_items.max(1) as f64;
    score *= 1.0 + 0.5 * progress;

    // Mild pressure against spreading across many bins.
    score += open_bins_count as f64 * 0.5;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: penalize small unusable gaps hard.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0 * (1.0 - post_residual as f64 / 10.0);
    }

    // Reward tight fits (small post_residual relative to item size).
    if item_size > 0 {
        let tightness = 1.0 - post_residual as f64 / bin_residual.max(1) as f64;
        score -= 8.0 * tightness;
    }

    // Open bins pressure: discourage spreading across many bins when this bin fits well.
    score += 0.6 * open_bins_count as f64 * (post_residual as f64 / bin_capacity as f64);

    // Last chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // Lookahead: if next item fits exactly in post_residual, big bonus.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 30.0;
    }
    // If next item would fit in post_residual, mild bonus.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 6.0;
    }
    // If post_residual is dead space that next item cannot use, penalize.
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size && post_residual < 10 {
        score += 15.0;
    }

    // New-bin candidate handling: empty bin gets a moderate default score,
    // so it only wins when all open bins would create bad dead space.
    if bin_residual == bin_capacity {
        score = 45.0 + 0.5 * open_bins_count as f64;
        if next_item_size > 0 && next_item_size <= bin_capacity {
            score -= 4.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
