pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap_f = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Dead-space avoidance: reward near-zero residuals heavily
    if post_residual == 0 {
        score -= 400.0;
    } else if post_residual <= 3 {
        score -= 180.0;
    } else if post_residual < 10 {
        score += 45.0;
    } else if post_residual < 20 {
        score += 18.0;
    } else if post_residual < 30 {
        score += 18.0 + (30 - post_residual) as f64 * 0.6;
    }

    // Lookahead: exact fit for next item is excellent
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 300.0;
        } else if next_item_size <= post_residual {
            let post2 = post_residual - next_item_size;
            score -= 40.0 - (post2 as f64) * 2.0;
            if post2 == 0 {
                score -= 60.0;
            }
            if post2 > 0 && post2 < 5 {
                score -= 25.0;
            }
            if post_residual % next_item_size == 0 {
                score -= 15.0;
            }
        } else {
            // next item won't fit here: penalize small dead gaps
            score += 20.0;
            if post_residual > 0 && post_residual < 15 {
                score += 40.0;
            }
            if post_residual > 0 && (next_item_size - post_residual) <= 3 {
                score += 30.0;
            }
            if post_residual as f64 > mean_residual * 1.4 {
                score -= 12.0;
            }
        }
    }

    // NEW-BIN CANDIDATE handling
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let avg_fill = 1.0 - (mean_residual / cap_f);
        score += 220.0 - avg_fill * 300.0 - progress * 60.0;
        if fitting_bins_count > 0 {
            score += (fitting_bins_count as f64).min(5.0) * 9.0 + 20.0;
            let snug = item_size as f64 / (bin_residual.max(1) as f64);
            if snug > 0.9 { score += 35.0; }
            if snug > 0.95 { score += 25.0; }
        }
        if item_size >= bin_capacity * 3 / 4 {
            score -= 50.0;
        }
        if next_item_size > 0 && next_item_size <= bin_capacity - item_size {
            score -= 25.0;
        }
        if bin_capacity - item_size <= 4 {
            score -= 60.0;
        }
        // late in stream: avoid opening new bins with big waste
        if progress > 0.6 {
            let waste_tol = (1.0 - progress) * cap_f * 0.35;
            if (bin_capacity - item_size) as f64 > waste_tol && fitting_bins_count > 0 {
                score += 10.0 + progress * 22.0;
            }
        }
    } else {
        // Open bin: prefer tighter fits
        let tightness = 1.0 - (item_size as f64 / bin_residual.max(1) as f64);
        score += tightness * 85.0;
        score += (mean_residual - bin_residual as f64) * 1.5;

        let dead_ratio = post_residual as f64 / cap_f;
        if dead_ratio < 0.03 {
            score -= 35.0;
        } else if dead_ratio < 0.08 {
            score -= 14.0;
        } else if dead_ratio > 0.35 {
            score += 24.0;
        } else if dead_ratio > 0.25 {
            score += 10.0;
        }

        if item_size == bin_residual {
            score -= 45.0;
        }

        // unusable gap ahead of next item
        if post_residual > 0 && next_item_size > 0 && post_residual < next_item_size {
            let dead_frac = post_residual as f64 / cap_f;
            if (next_item_size - post_residual) > 12 {
                score += dead_frac * 90.0;
            }
            if post_residual >= item_size * 2 {
                score += 10.0;
            }
        }
