            let chain = post_residual / next_item_size;
            if chain >= 2 {
                score -= (chain.min(4)) as f64 * 6.0;
            }
        }
        if post_residual > 0 && post_residual < 6 {
            score -= 22.0;
        }
        if post_residual > 0 && post_residual % 10 == 0 {
            score -= 10.0;
        }
    }

    // Pressure from number of open bins: compact when many bins open
    score += open_bins_count as f64 * 0.8;

    // Last-chance bin: strongly favor using it
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // Mild preference for larger items placed first
    score -= (item_size as f64 / cap_f) * 10.0;

    let progress = step_index as f64 / total_items.max(1) as f64;
    if progress < 0.1 {
        score += 3.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong reward for tight fits (small dead space), non-linearly.
    let tightness = 1.0 - (post_residual as f64) / (bin_capacity as f64);
    score -= 40.0 * tightness * tightness;

    // Penalize large post_residual that can't host the lookahead item (dead space).
    if next_item_size > 0 {
        if post_residual < next_item_size {
            score += 12.0 + 0.35 * (next_item_size - post_residual) as f64;
        } else {
            // Reward bins that can also host the next item.
            score -= 8.0;
        }
    }

    // Last-chance bonus: if this is the only fitting bin, strongly prefer using it.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // Time horizon: early in stream, prefer consolidating into open bins;
    // late in stream, avoid wasting near-full bins on small items.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += 6.0 * (1.0 - progress) * (post_residual as f64 / bin_capacity as f64);

    // Penalize bins far from the mean residual (prefer balanced usage) mildly.
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += 0.05 * dev;

    // Discourage opening new bins when several open bins can already fit.
    if bin_residual == bin_capacity {
        let pressure = fitting_bins_count as f64;
        score += 15.0 + 8.0 * pressure;
        // But allow a fresh bin if the item would leave an awkward remainder
        // in every open bin and lookahead is large.
