pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let pr_norm = pr / cap;

    // Non-linear polynomial coupling of post_residual with stream progress
    let poly = pr_norm * pr_norm * (1.0 + 2.0 * progress) + pr_norm * (1.0 - progress);

    let mut score = pr + 8.0 * poly * cap.sqrt();

    // Penalize near-full waste slightly less as stream ends
    let tight_fit = (bin_residual as f64 - item_size as f64) / cap;
    score -= 10.0 * (1.0 - tight_fit).powi(3) * (1.0 - progress);

    // Reward using a bin when it's the last fitting bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // Lookahead: penalize if next item fits better elsewhere (residual too small for next item)
    if next_item_size > 0 && post_residual > 0 {
        let waste = (post_residual as f64 - next_item_size as f64).abs();
        if post_residual < next_item_size {
            score += 3.0 * (next_item_size - post_residual) as f64;
        } else {
            score -= 2.0 * (post_residual - next_item_size) as f64 * (1.0 - progress);
        }
        let _ = waste;
    }

    // New-bin candidate: mild penalty early, discount late
    if bin_residual == bin_capacity {
        score = score * (1.0 - 0.3 * progress) + 5.0 * (1.0 - progress) + open_bins_count as f64;
    }

    score += 0.01 * mean_residual * (1.0 - progress);
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap_f = bin_capacity as f64;
    let progress = step_index as f64 / total_items.max(1) as f64;
    let mut score = post_residual as f64;

    // Dead-space avoidance (tiered, strengthened)
    if post_residual == 0 {
        score -= 900.0; // perfect fit
    } else if post_residual <= 3 {
        score -= 380.0;
    } else if post_residual <= 12 {
        score -= 90.0;
    } else if post_residual < 20 {
        score += 18.0;
    } else if post_residual < 30 {
        score += 18.0 + (30 - post_residual) as f64 * 0.6;
    }

    // Lookahead: exact and near-exact fits for the next item
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 700.0;
        } else if next_item_size <= post_residual {
            let post2 = post_residual - next_item_size;
            score -= 120.0 - (post2 as f64) * 2.0;
            if post2 == 0 { score -= 100.0; }
            if post2 > 0 && post2 < 5 { score -= 28.0; }
            if post2 > 0 && post2 <= 2 { score -= 14.0; }
            if post2 % 10 == 0 && post2 > 0 { score -= 20.0; }
            if post2 > 0 && post2 <= next_item_size / 4 { score -= 10.0; }
            if post_residual % next_item_size == 0 { score -= 16.0; }
            if post_residual >= next_item_size * 2 && post_residual - next_item_size * 2 <= 4 {
                score -= 20.0;
            }
            // chain fits: residual can host next item multiple times
            let chain = post_residual / next_item_size;
            if chain >= 2 { score -= (chain.min(4)) as f64 * 6.0; }
            // divisibility bonus: leaves clean multiples
            if post2 > 0 && post2 % 5 == 0 && post2 >= 20 { score -= 10.0; }
        } else {
            // next item won't fit here: penalize leaving a nearly-fitting gap
            let gap = (next_item_size - post_residual) as f64;
            if post_residual > 0 {
                if gap <= 3.0 { score += 40.0; }
                else if gap <= 8.0 { score += 14.0; }
                if gap <= 5.0 { score += (6.0 - gap) * 4.0; }
                if gap > mean_residual * 0.6 && fitting_bins_count > 2 { score += gap * 0.5; }
            }
            if post_residual % 10 == 0 && post_residual > 0 { score -= 12.0; }
        }
    }

    // Compaction pressure scaled by open bins
    score += open_bins_count as f64 * 0.8;

    // Last-chance bin: strongly favor using it
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 60.0;
    }

    // Tightness via relative fill
    let snug = item_size as f64 / bin_residual.max(1) as f64;
    score -= snug * 30.0;

    // NEW-BIN CANDIDATE handling
    if bin_residual == bin_capacity {
        let newbin_waste = (bin_capacity - item_size) as f64;
        let avg_fill = 1.0 - (mean_residual / cap_f);
        score += 230.0 - avg_fill * 300.0 - progress * 65.0;
        // big items deserve a fresh bin when few alternatives fit well
        if item_size as f64 / cap_f > 0.75 { score -= 55.0; }
        if item_size as f64 > mean_residual { score -= 35.0; }
        if newbin_waste < mean_residual * 0.5 { score -= 30.0; }
        if next_item_size > 0 {
            let leftover = bin_capacity - item_size;
            if leftover >= next_item_size {
                let tail = leftover % next_item_size;
                if tail == 0 { score -= 25.0; }
                else if tail <= 4 { score -= 16.0; }
                if leftover - next_item_size <= 6 { score -= 35.0; }
                if leftover >= next_item_size * 2 { score -= 14.0; }
            } else if leftover < 10 {
                score += 18.0;
            }
        }
        if fitting_bins_count > 3 { score += (fitting_bins_count.min(6) as f64) * 7.0; }
        if bin_capacity - item_size <= 4 { score -= 60.0; }
        if snug > 0.9 { score -= 30.0; } // item nearly fills fresh bin: good
        if progress > 0.75 && newbin_waste > cap_f * 0.5 { score += 14.0; }
        // early stream: allow diversity
        if progress < 0.1 { score -= 6.0; }
    } else {
        // Prefer bins whose residual is below average (consolidating slack)
        score += (mean_residual - bin_residual as f64) * 1.2;

        // dead-space ratio shaping
        let dead_ratio = post_residual as f64 / cap_f;
        if dead_ratio < 0.03 { score -= 30.0; }
        else if dead_ratio < 0.08 { score -= 12.0; }
        else if dead_ratio > 0.35 { score += 22.0; }
        else if dead_ratio > 0.25 { score += 10.0; }

        // unusable-gap penalty relative to next item
        if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
            let wasted = (next_item_size - post_residual) as f64;
            if wasted > 12.0 { score += wasted * 0.6; }
            score += (1.0 - progress) * 12.0;
        }

        // very tight residuals are valuable, keep them usable
        if post_residual > 0 && post_residual < 6 { score -= 20.0; }
        if post_residual > 0 && (post_residual as f64) < mean_residual * 0.25 { score -= 14.0; }
        if item_size == bin_residual { score -= 40.0; }
        if post_residual > 0 && (post_residual as f64) < cap_f * 0.015 { score -= 16.0; }
        if bin_residual as f64 > cap_f * 0.6 { score -= 10.0; }
        if post_residual > 0 && post_residual % 5 == 0 && post_residual <= 30 { score -= 8.0; }
        if post_residual > 0 && next_item_size > 0 && post_residual + next_item_size as u32 <= bin_capacity
            && (post_residual as f64) < mean_residual * 0.5 { score -= 9.0; }
        if fitting_bins_count <= 2 && post_residual > 0 { score -= 8.0; }
    }

    // Mild progress-based diversity nudge for open bins
    if progress < 0.1 { score += 3.0; }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
