pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the residual: residuals divisible by small denominators
    // are more reusable by typical items (which cluster on multiples of 5/10).
    let post = post_residual;
    let harmony = if post == 0 {
        3.0
    } else if post % 10 == 0 {
        2.5
    } else if post % 5 == 0 {
        1.5
    } else if post % 2 == 0 {
        0.5
    } else {
        0.0
    };
    score -= harmony * (bin_capacity as f64 / 100.0);

    // Dead space penalty: residual that no plausible item can ever fill.
    // Items are >= 1, but tiny unusable slivers (< 10) are near-dead in practice.
    if post > 0 && post < 10 {
        score += 12.0;
    }
    // Mid-range awkward residuals (mod 10 == 1) pair poorly with integer sizes.
    if post >= 10 && post % 10 == 1 {
        score += 3.0;
    }

    // Perfect fit reward, stronger when this is the only fitting bin.
    if post == 0 {
        score -= 20.0;
        if fitting_bins_count == 1 {
            score -= 10.0;
        }
    }

    // Lookahead coupling: reward residuals that can also host the next item
    // (harmonic packing of two consecutive items).
    if next_item_size > 0 && post >= next_item_size {
        score -= 6.0 + (next_item_size as f64) / 20.0;
        // extra reward if after both items the residual is again harmonious
        let post2 = post - next_item_size;
        if post2 % 10 == 0 {
            score -= 4.0;
        }
    }
    // Penalize leaving a residual that cannot host the next item if this is
    // the last-chance bin (avoid wasting the only fitting bin on a bad split).
    if next_item_size > 0 && post < next_item_size && fitting_bins_count == 1 {
        score += 5.0;
    }

    // New-bin candidate handling: only prefer a fresh bin when no open bin
    // offers a tight fit; penalize opening bins unnecessarily.
    if bin_residual == bin_capacity {
        score += 30.0;
        if fitting_bins_count == 0 {
            score -= 40.0;
        } else {
            // scale pressure with stream progress and bin count
            let progress = step_index as f64 / (total_items.max(1) as f64);
            score += 10.0 * (1.0 - progress) + (open_bins_count as f64).sqrt();
        }
    }

    // Mild preference for fuller bins relative to the fleet mean residual:
    // placing into a below-average-residual bin keeps a diverse residual pool.
    score -= 0.5 * (mean_residual - post as f64).max(0.0);

    // Tightness term: fraction of capacity consumed by this placement.
    score -= (item_size as f64 / bin_capacity as f64) * 8.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals too small for the smallest item are pure waste.
    if post_residual < 10 && post_residual > 0 {
        score += 60.0; // unusable gap penalty
    } else if post_residual == 0 {
        score -= 40.0; // perfect closure reward
    }

    // Penalize residuals that can't fit the known next item (likely dead space).
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 25.0;
    }

    // Reward tight fits relative to capacity.
    let tightness = item_size as f64 / cap;
    score -= 30.0 * tightness * tightness;

    // Open-bin pressure: discourage spreading across many bins.
    score += 0.6 * open_bins_count as f64;

    // Last-chance bin: strong incentive to use it rather than open a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 45.0;
    }

    // New-bin candidate: only attractive when current bin fit is poor.
    if bin_residual == bin_capacity {
        score += 15.0 + 8.0 * (mean_residual / cap);
    }

    // Mean-residual coupling: prefer bins below mean residual (denser bins).
    score += 0.15 * (mean_residual - post_residual as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit bonus
    if post_residual == 0 {
