    }

    // 2-step lookahead: reward when next item exactly matches post_residual
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 800.0;
        } else if next_item_size <= post_residual {
            // next item fits here too; penalize proportional leftover after both
            let two_step_left = post_residual - next_item_size;
            score += two_step_left as f64 * 0.5;
        } else {
            // next item cannot use this residual: dead space risk
            score += (next_item_size - post_residual) as f64 * 0.3;
        }
    }

    // Compare post_residual against mean residual: keep bin residual near mean
    score += (post_residual as f64 - mean_residual).abs() * 0.2;

    // Last chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 500.0;
    }

    // Penalize opening a new bin when open bins could fit reasonably well
    if bin_residual == bin_capacity {
        score += 300.0 + mean_residual * 0.5;
        if next_item_size > 0 && next_item_size >= item_size {
            score += 100.0;
        }
    }

    // Late in stream, prefer tighter packing
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += post_residual as f64 * progress * 0.3;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let is_new_bin = bin_residual == bin_capacity;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    // Tight-fit reward: fraction of the residual consumed by this item.
    let fill_frac = item_size as f64 / bin_residual.max(1) as f64;
    score -= 10.0 * fill_frac * fill_frac;

    // Lookahead: reward bins whose leftover can host the next item (chain packing).
    if next_item_size > 0 && next_item_size <= post_residual {
        let chain_waste = (post_residual - next_item_size) as f64;
        score -= 8.0 - 0.08 * chain_waste;
    } else if next_item_size > post_residual {
        // Leftover too small for next item: penalize dead space mildly.
        score += 0.05 * post_residual as f64;
    }

    // Last-chance bonus: if this is the only open bin that fits, strongly prefer using it.
    if !is_new_bin && fitting_bins_count == 1 {
        score -= 15.0;
    }

    // New-bin candidate handling: penalize opening a new bin unless the item
    // is large (leaving little residual) or many bins are already open.
    if is_new_bin {
        let large_item_bonus = if item_size >= 50 { 14.0 } else { 0.0 };
        let crowd_bonus = (open_bins_count as f64).min(10.0);
