    if !is_new_bin {
        score += 0.03 * (mean_residual - bin_residual as f64).max(0.0);
    }

    // Slight global pressure: as stream progresses, discourage hoarding capacity.
    score -= 2.0 * progress * (bin_capacity - post_residual) as f64 / bin_capacity as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
