            score += g * g * (3.0 + 5.0 * progress) * cap * 0.1;
        }
    }

    // Last-chance bin bonus (only bin that fits): smooth reward
    if fitting_bins_count == 1 {
        score -= 4.0 + 6.0 * progress;
    }

    // Mild penalty for spreading across many open bins, growing with progress
    let ob = open_bins_count as f64;
    score += (ob / (ob + 4.0)) * (1.0 + 2.0 * progress) * (mean_residual / cap) * 2.0;

    // New-bin candidate: penalize opening a new bin, unless residual of this placement is tiny
    if bin_residual as f64 == cap {
        score += cap * (0.6 + 0.4 * progress);
        if nis > 0.0 && pr >= nis {
            score -= 1.5;
        }
    }

    score
}

