        }
        // late-stream waste tolerance
        if progress > 0.6 {
            let waste_tol = (1.0 - progress) * cap_f * 0.35;
            if newbin_waste > waste_tol && fitting_bins_count > 0 {
                score += 10.0 + progress * 20.0;
            }
        }
        if progress > 0.85 && newbin_waste > cap_f * 0.3 { score += 8.0; }
        if progress < 0.1 { score -= 5.0; }
    } else {
        // Prefer bins whose residual is below average (consolidating slack)
        score += (mean_residual - bin_residual as f64) * 1.2;

        if item_size == bin_residual { score -= 45.0; }

        // dead ratio shaping
        let dead_ratio = post_residual as f64 / cap_f;
        if dead_ratio < 0.03 {
            score -= 35.0;
        } else if dead_ratio < 0.08 {
            score -= 12.0;
        } else if dead_ratio > 0.35 {
            score += 22.0;
        } else if dead_ratio > 0.25 {
            score += 10.0;
        }

        // unusable-gap penalty relative to next item
        if post_residual > 0 && next_item_size > 0 && post_residual < next_item_size {
            let wasted = (next_item_size - post_residual) as f64;
            score += wasted * 0.6;
            if wasted > 12.0 { score += dead_ratio * 60.0; }
        }

        if post_residual > 0 && post_residual < 6 { score -= 20.0; }
        if post_residual > 0 && post_residual % 10 == 0 { score -= 10.0; }
        if post_residual > 0 && post_residual % 5 == 0 && post_residual <= 30 { score -= 8.0; }
        if post_residual > 0 && (post_residual as f64) < mean_residual * 0.25 { score -= 14.0; }
        if post_residual > 0 && bin_residual as f64 > cap_f * 0.6 { score -= 10.0; }

        let progress = step_index as f64 / total_items.max(1) as f64;
        if post_residual > 0 && next_item_size > 0 && post_residual < next_item_size {
            score += (1.0 - progress) * 12.0;
        }
        if post_residual > 0 && post_residual < 25 && next_item_size > post_residual {
            score += (25 - post_residual) as f64 * 1.0;
        }
        if post_residual > 0 && next_item_size > 0 && post_residual > next_item_size * 3
            && post_residual < bin_capacity / 3 {
            score += 12.0;
        }
        if post_residual > 0 && (post_residual as f64) < cap_f * 0.015 { score -= 16.0; }
        if fitting_bins_count <= 2 && post_residual > 0 { score -= 8.0; }
        if post_residual > 0 && (post_residual as f64) > mean_residual * 1.6 && fitting_bins_count > 2 {
            score += 10.0;
        }
    }

    // Mild progress-based diversity nudge for open bins
    let progress = step_index as f64 / total_items.max(1) as f64;
    if progress < 0.1 { score += 3.0; }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let score = (post_residual as f64) * 0.90;
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward near-perfect fits heavily
    if post_residual == 0 {
        score -= 1000.0;
    } else if post_residual <= 5 {
        score -= 200.0;
    } else if post_residual <= 15 {
        score -= 50.0;
    }

    // 2-step lookahead: reward if next item fits in the post residual
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 800.0;
        } else if next_item_size < post_residual {
            let leftover = post_residual - next_item_size;
            if leftover <= 10 {
                score -= 150.0 - leftover as f64 * 5.0;
            } else {
                score -= 50.0 / leftover as f64;
            }
        } else {
            // next item won't fit here: penalize wasting too much space
            let waste = post_residual as f64 - next_item_size as f64;
            if waste > 20.0 {
                score += waste * 0.5;
            }
        }
    }

    // Compare post residual to mean residual: keeping balance is good,
    // but leaving much more than mean means wasted space
    let dev = post_residual as f64 - mean_residual;
    if dev > 0.0 {
        score += dev * 0.3;
    } else {
        score += dev * 0.1; // slightly reward tighter-than-average bins
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 120.0;
    }

    // Penalize opening new bins when decent existing options exist
    if bin_residual == bin_capacity {
        // new-bin candidate: only attractive if item is large and existing residuals are small
        let tightness = mean_residual / bin_capacity as f64;
        score += 150.0 * (1.0 - tightness);
        if item_size >= 60 {
            score -= 40.0;
        }
        // late in stream, prefer closing out existing bins
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += progress * 80.0;
    }

    // Mild penalty per open bin to encourage consolidation
    score += open_bins_count as f64 * 0.5;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap_f = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Residual ladder: strongly reward near-perfect fits, penalize small dead space.
    if post_residual == 0 {
        score -= 900.0;
    } else if post_residual <= 3 {
        score -= 350.0;
    } else if post_residual <= 8 {
        score -= 60.0;
    } else if post_residual < 12 {
        score -= 20.0;
    } else if post_residual < 20 {
        score += 14.0;
    } else if post_residual < 30 {
        score += 10.0 + (30 - post_residual) as f64 * 0.5;
    }

    // Lookahead: exact next-item match is a huge win.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 700.0;
        } else if next_item_size <= post_residual {
            let post2 = post_residual - next_item_size;
            score -= 90.0 - (post2 as f64) * 1.5;
            if post2 == 0 { score -= 60.0; }
            if post2 > 0 && post2 < 5 { score -= 20.0; }
            if post_residual % next_item_size == 0 { score -= 14.0; }
            if post2 <= next_item_size / 2 { score -= 8.0; }
        } else {
            // Next item won't fit here: penalize leaving a nearly-fitting gap.
            let gap = next_item_size as f64 - post_residual as f64;
            if post_residual > 0 {
                score += 16.0;
                if gap <= 6.0 { score += 22.0; }
                if post_residual < 15 { score += 30.0; }
                if post_residual as f64 > mean_residual * 1.5 { score -= 10.0; }
            }
        }
    }

    // Compaction pressure when many bins are open.
    score += open_bins_count as f64 * 0.6;

    // Last-chance bin: strongly favor using it.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    } else if fitting_bins_count == 2 && bin_residual < bin_capacity {
        score -= 10.0;
    }

    // Relative fill tightness.
    score -= (item_size as f64 / cap_f) * 12.0;
    if item_size == bin_residual {
        score -= 40.0;
    }

    // NEW-BIN CANDIDATE LOGIC (bin_residual == bin_capacity).
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let avg_fill = 1.0 - (mean_residual / cap_f);
        // Base new-bin cost: higher when bins are already well-filled.
        score += 240.0 - avg_fill * 300.0 - progress * 60.0;

        let newbin_waste = (bin_capacity - item_size) as f64;
        if fitting_bins_count > 0 {
            score += (fitting_bins_count as f64).min(5.0) * 9.0;
            let snug = item_size as f64 / (bin_residual.max(1) as f64);
            if snug > 0.9 { score += 35.0; }
            if snug > 0.95 { score += 25.0; }
        }
        // Large items deserve a fresh bin rather than a bad squeeze.
        if item_size as f64 > mean_residual { score -= 40.0; }
        if item_size >= bin_capacity * 3 / 4 { score -= 50.0; }
        if bin_capacity - item_size <= 4 { score -= 60.0; }
        // Pairing lookahead: fresh bin that pairs well with next item.
        if next_item_size > 0 {
            let leftover = bin_capacity - item_size;
            if leftover >= next_item_size {
                let tail = leftover % next_item_size;
                if tail == 0 { score -= 20.0; }
                else if tail <= 4 { score -= 12.0; }
            }
            if next_item_size >= bin_capacity / 2 && leftover >= next_item_size { score -= 25.0; }
        }
        // Late in stream: avoid opening wasteful bins.
        if progress > 0.6 {
            let waste_tol = (1.0 - progress) * cap_f * 0.35;
            if newbin_waste > waste_tol && fitting_bins_count > 0 {
                score += 12.0 + progress * 20.0;
            }
        }
        if progress > 0.85 && newbin_waste > cap_f * 0.4 { score += 10.0; }
    } else {
        // Existing bin: dead-space ratio shaping.
        let dead_ratio = post_residual as f64 / cap_f;
        if dead_ratio < 0.03 && post_residual > 0 { score -= 30.0; }
        else if dead_ratio > 0.35 { score += 20.0; }
        else if dead_ratio > 0.25 { score += 8.0; }

        // Distance from mean residual: prefer residuals near the pack average.
        let mres = mean_residual.max(1.0);
        let dist = (post_residual as f64 - mres).abs();
        score += dist * 0.3;
        if dist < cap_f * 0.03 { score -= 8.0; }

        // Unusable gap for the next item is costly.
        if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
            let wasted = next_item_size as f64 - post_residual as f64;
            score += wasted * 0.7;
            if wasted > 12.0 { score += 10.0; }
        } else if next_item_size > 0 && post_residual >= next_item_size {
            let chain = post_residual / next_item_size;
            if chain >= 2 { score -= (chain.min(4)) as f64 * 5.0; }
        }

        // Nice round residuals are easier to fill later.
        if post_residual > 0 && post_residual % 10 == 0 { score -= 8.0; }
        if post_residual > 0 && post_residual % 5 == 0 && post_residual <= 30 { score -= 6.0; }

        // Prefer filling fuller bins first.
        if bin_residual as f64 > cap_f * 0.6 { score -= 10.0; }
    }

    // Early stream: mild diversity bonus.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if progress < 0.05 {
        score += 3.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits (small post_residual) nonlinearly.
    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 12.0 * fit_ratio * fit_ratio;

    // Penalize dead space that is too small for typical future items.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 40.0;
    }

    // Lookahead: if next item fits exactly in post_residual, big reward.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 35.0;
        } else if next_item_size <= post_residual {
            score -= 8.0 * (next_item_size as f64 / post_residual.max(1) as f64);
        } else {
            // Next item won't fit here; slight penalty proportional to waste.
            score += 4.0 * (1.0 - (bin_residual - post_residual) as f64 / bin_residual.max(1) as f64);
        }
    }

    // Prefer bins with residual below mean (denser bins) early, spread later.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let dev = bin_residual as f64 - mean_residual;
    score += dev * (0.05 + 0.15 * progress);

    // Many open bins: encourage filling existing ones rather than opening new.
    score -= (open_bins_count as f64).ln().max(0.0) * 2.0;

    // New-bin candidate: make it attractive only when no good fit exists.
    if bin_residual == bin_capacity {
        let pressure = if fitting_bins_count == 0 { 60.0 } else { 0.0 };
        score = bin_capacity as f64 - pressure - 5.0 * progress;
        if fitting_bins_count == 1 {
            score += 50.0; // don't abandon a last-chance bin
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let score = post_residual as f64 / bin_capacity.max(1) as f64;
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let is_new_bin = (bin_residual as f64 - cap).abs() < 0.5;

    // Base: prefer small post-residual (tight fit), mildly non-linear.
    let mut score = pr * (1.0 + 0.35 * pr / cap);

    // Dead-space penalty grows as stream progresses: early on, waste is cheap.
    let dead = pr / cap;
    score += 18.0 * dead * dead * (0.3 + 0.7 * progress);

    // Reward bins whose post-residual matches the next item (lookahead chaining).
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        let gap = (pr - nxt).abs() / cap;
        score -= 10.0 * (1.0 - gap) * (1.0 - gap);
    } else {
        // Last item: any residual is pure waste; strongly prefer tightest fit.
        score += 12.0 * dead;
    }

    // Last-chance bonus: if this is the only bin that fits, avoid opening a new bin.
    if fitting_bins_count == 1 && !is_new_bin {
        score -= 15.0;
    }

    // New-bin candidate: penalize opening extra bins, but relax penalty when
    // open bins are crowded (mean residual small) or late in the stream.
    if is_new_bin {
        let crowding = (mean_residual / cap).clamp(0.0, 1.0);
        score += (6.0 + 2.0 * open_bins_count as f64) * (0.5 + 0.5 * (1.0 - progress)) - 20.0 * crowding * crowding;
    }

    // Smooth coupling: bins with residual far above the mean are less attractive.
    let dev = (bin_residual as f64 - mean_residual) / cap;
    score += 4.0 * dev * dev;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap_f = bin_capacity as f64;
    let progress = step_index as f64 / total_items.max(1) as f64;
    let mut score = post_residual as f64;

    // Tiered dead-space avoidance (strengthened)
    if post_residual == 0 {
        score -= 900.0; // perfect fit
    } else if post_residual <= 3 {
        score -= 400.0;
    } else if post_residual <= 12 {
        score -= 90.0;
    } else if post_residual < 20 {
        score += 18.0;
    } else if post_residual < 30 {
        score += 18.0 + (30 - post_residual) as f64 * 0.6;
    }

    // Lookahead: exact and near-exact fits for the next item
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 700.0;
        } else if next_item_size <= post_residual {
            let post2 = post_residual - next_item_size;
            score -= 110.0 - (post2 as f64) * 1.8;
            if post2 == 0 { score -= 90.0; }
            if post2 > 0 && post2 < 5 { score -= 26.0; }
            if post2 % 10 == 0 && post2 > 0 { score -= 20.0; }
            if post_residual >= next_item_size * 2 && post_residual - next_item_size * 2 <= 4 {
                score -= 18.0;
            }
            if post_residual % next_item_size == 0 { score -= 14.0; }
            let chain = post_residual / next_item_size;
            if chain >= 2 { score -= (chain.min(4)) as f64 * 6.0; }
            if post2 > 0 && post2 <= next_item_size / 4 { score -= 8.0; }
        } else {
            let gap = next_item_size as f64 - post_residual as f64;
            if post_residual > 0 {
                if gap <= 3.0 { score += 35.0; }
                else if gap <= 8.0 { score += 12.0; }
                if gap > mean_residual * 0.5 { score += 12.0; }
                if post_residual < 15 { score += 40.0; }
                if gap <= 5.0 { score += (6.0 - gap) * 4.0; }
            }
        }
    }

    // Compaction pressure scaled by open bins
    score += open_bins_count as f64 * 0.8;

    // Last-chance bin: strongly favor using it
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 50.0;
    }

    // Tightness via relative fill
    let snug = item_size as f64 / bin_residual.max(1) as f64;
    score -= snug * 45.0;
    if item_size == bin_residual { score -= 40.0; }

    // Dead-space ratio shaping
    if bin_residual < bin_capacity {
        let dead_ratio = post_residual as f64 / cap_f;
        if dead_ratio < 0.03 { score -= 30.0; }
        else if dead_ratio < 0.08 { score -= 12.0; }
        else if dead_ratio > 0.35 { score += 22.0; }
        else if dead_ratio > 0.25 { score += 10.0; }
        score += (mean_residual - bin_residual as f64) * 1.2;
    }

    // NEW-BIN CANDIDATE handling
    if bin_residual == bin_capacity {
        let newbin_waste = (bin_capacity - item_size) as f64;
        let avg_fill = 1.0 - (mean_residual / cap_f);
        score += 230.0 - avg_fill * 300.0 - progress * 60.0;
        if item_size as f64 / cap_f > 0.75 { score -= 55.0; }
        if item_size >= bin_capacity * 3 / 4 { score -= 40.0; }
        if item_size as f64 > mean_residual { score -= 30.0; }
        if newbin_waste < mean_residual * 0.5 { score -= 30.0; }
        if bin_capacity - item_size <= 4 { score -= 60.0; }
        if next_item_size > 0 {
            let leftover = bin_capacity - item_size;
            if leftover >= next_item_size {
                let tail = leftover % next_item_size;
                if tail == 0 { score -= 20.0; }
                else if tail <= 4 { score -= 14.0; }
                if leftover - next_item_size <= 6 { score -= 35.0; }
                if leftover >= next_item_size * 2 { score -= 12.0; }
            } else if leftover < 10 {
                score += 18.0;
            }
            if next_item_size >= bin_capacity / 2 { score -= 28.0; }
        }
        if fitting_bins_count > 0 {
            score += (fitting_bins_count.min(6) as f64) * 8.0 + 15.0;
            if snug > 0.9 { score += 35.0; }
            if snug > 0.95 { score += 25.0; }
        }
        if fitting_bins_count > 3 && item_size as f64 / cap_f < 0.5 { score += 25.0; }
        if progress > 0.6 {
            let waste_tol = (1.0 - progress) * cap_f * 0.35;
            if newbin_waste > waste_tol && fitting_bins_count > 0 {
                score += 10.0 + progress * 20.0;
            }
        }
        if progress < 0.1 { score -= 5.0; }
    }

    // Mild progress-based diversity nudge for open bins
    if progress < 0.1 { score += 3.0; }

    // Unusable-gap penalty relative to next item
    if post_residual > 0 && next_item_size > 0 && post_residual < next_item_size {
        let wasted = next_item_size as f64 - post_residual as f64;
        score += wasted * 0.5 + (1.0 - progress) * 10.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post-residual: classify dead space into capacity fractions.
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;

    // Exact fit is perfect.
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Small usable leftovers are good; tiny unusable slivers are dead space.
    // Class A: post_residual <= 10 -> highly usable by smallest items (1..=10).
    if post_residual <= 10 && post_residual > 0 {
        score -= 30.0;
    }
    // Class B: 11..=20 -> still usable by small items.
    else if post_residual <= 20 {
        score -= 12.0;
    }
    // Class C: 21..=50 -> moderate.
    else if post_residual <= 50 {
        score -= 4.0;
    }
    // Class D: large leftover -> wasteful placement, penalize.
    else {
        score += 15.0;
    }

    // Coupling with lookahead: if next item fits exactly in post_residual, big reward.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 80.0;
        } else if next_item_size <= post_residual {
            // Harmonic remainder: how close next item comes to filling post_residual.
            let gap = (post_residual - next_item_size) as f64;
            score -= 20.0 * (1.0 - gap / cap).max(0.0);
        } else {
            // Next item cannot use this residual; slight penalty proportional to excess.
            let over = (next_item_size - post_residual) as f64;
            score += 5.0 * (over / cap);
        }
    }

    // Integer-division harmonic classes on post_residual (mod arithmetic).
    let class = post_residual / 25; // 0..4 quarter classes
    score += match class {
        0 => -6.0,
        1 => -2.0,
        2 => 0.0,
        3 => 3.0,
        _ => 6.0,
    };

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 45.0;
    }

    // Prefer filling bins that are already relatively full (low residual).
    score += (bin_residual as f64 / cap) * 10.0;

    // Prefer bins whose residual deviates below the mean (tighter bins first).
    score -= (mean_residual - pr) * 0.5;

    // Late in the stream, be more aggressive about closing bins tightly.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score -= progress * pr * 0.3;

    // Avoid spreading too thin when many bins are open: prefer tightest fits.
    score += (open_bins_count as f64).ln() * (pr / cap) * 3.0;

    // New-bin candidate: only attractive when no open bin fits well.
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin.
        score += 25.0;
        // But if many bins are open and their mean residual is large, a fresh bin
        // with full capacity can be better than jamming into fragmented bins.
        if open_bins_count > 3 && mean_residual > 40.0 {
            score -= 20.0;
        }
        if next_item_size > 0 && next_item_size >= item_size.saturating_mul(2).min(bin_capacity) {
            score -= 5.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let score = post_residual as f64 / bin_capacity.max(1) as f64;
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Penalize unusable small gaps: post_residual below the minimum item size is dead space.
    if post_residual > 0 && post_residual < 10 {
        score += 40.0 * (10.0 - post_residual as f64);
    }
    if post_residual == 0 {
        score -= 30.0; // perfect fit reward
    }

    // Penalize near-full-but-not-perfect fits that leave awkward residuals
    if post_residual > 0 && post_residual < 30 {
        score += (30.0 - post_residual as f64) * 0.8;
    }

    // Open bins pressure: discourage spreading across many bins
    score += open_bins_count as f64 * 2.0;

    // If this is the only bin that fits, strongly favor using it
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 50.0;
    }

    // New-bin candidate: penalize opening a new bin unless it enables a great fit
    if bin_residual == bin_capacity {
        score += 25.0;
        // opening a new bin is fine if many bins are open (load spreading late)
        if open_bins_count > 3 {
            score -= 10.0;
        }
    }

    // Lookahead: if next item fits in post_residual, reward
    if next_item_size > 0 && (post_residual as u32) >= next_item_size {
        score -= 15.0;
    }
    // If next item almost fits, slight penalty for wasting that chance
    if next_item_size > post_residual && (next_item_size - post_residual) <= 5 && post_residual > 0 {
        score += 8.0;
    }

    // Mild preference to fill bins tighter as stream progresses
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= progress * (bin_residual - post_residual) as f64 * 0.1;

    // Mean residual coupling: prefer bins below mean residual (tighter bins)
    score += (mean_residual - post_residual as f64) * 0.3;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward perfect 2-step match: post_residual equals next item size exactly.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 60.0;
    }

    // Reward near-perfect 2-step match (small slack left for next item).
    if next_item_size > 0 && post_residual > next_item_size {
        let slack = (post_residual - next_item_size) as f64;
        if slack <= 10.0 {
            score -= 25.0 - 1.8 * slack;
        } else {
            // Penalize dead space that next item cannot use.
            score += 0.35 * slack;
        }
    }

    // Penalize when next item cannot fit here at all (dead space for lookahead).
    if next_item_size > post_residual as u32 {
        score += 12.0;
    }

    // Compare post_residual against mean residual across open bins:
    // prefer bins whose remaining space ends up below average (tight packing).
    let pr = post_residual as f64;
    if mean_residual > 0.0 {
        let dev = (pr - mean_residual) / mean_residual;
        score += 3.0 * dev;
    }

    // Tight fit reward relative to capacity.
    let tightness = (item_size as f64) / (bin_capacity as f64);
    score -= 20.0 * tightness;

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate: penalize opening a new bin unless current bins are poor fits.
    if bin_residual == bin_capacity {
        score += 55.0;
        // If no existing bin fits, opening is necessary.
        if fitting_bins_count == 0 {
            score -= 70.0;
        }
        // Late in the stream, prefer consolidating into open bins.
        if total_items > 0 {
            let progress = step_index as f64 / total_items as f64;
            score += 25.0 * progress;
        }
    }

    // Mild penalty for many open bins: encourage consolidation.
    score += 0.4 * open_bins_count as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tight-fit reward: small post-residual is good, non-linear bonus
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 14.0 * tightness * tightness;

    // Exact-fit celebration
    if post_residual == 0 {
        score -= 60.0;
    }

    // Lookahead: reward bins whose post-residual can host the next item
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 10.0 + 0.05 * next_item_size as f64;
    } else if next_item_size > 0 {
        // penalize dead space the next item can't use, worse if post_residual small-but-nonzero
        score += 0.08 * post_residual as f64;
    }

    // Last-chance bin: strongly favor using the only bin that fits
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 25.0;
    }

    // Penalize scattering across many open bins
    score += 1.5 * open_bins_count as f64;

    // Prefer bins with residual below mean residual (fills fuller bins first)
    score += 0.25 * (bin_residual as f64 - mean_residual);

    // Time horizon: late in the stream, be greedy about closing bins; early, keep options open
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score += (1.0 - progress) * 4.0 * (post_residual as f64 / bin_capacity as f64);

    // New-bin candidate: only attractive when nothing fits well or item is huge
    let is_new_bin = bin_residual == bin_capacity && bin_capacity >= item_size;
    if is_new_bin {
        let desperation = if fitting_bins_count == 0 { 1.0 }
            else if post_residual < 15 { 0.6 }
            else { 0.0 };
        score += 30.0 - 55.0 * desperation - 0.2 * item_size as f64 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap_f = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Dead-space avoidance (tiered, strengthened)
    if post_residual == 0 {
        score -= 900.0;
    } else if post_residual <= 3 {
        score -= 400.0;
    } else if post_residual <= 12 {
        score -= 90.0;
    } else if post_residual < 20 {
        score += 18.0;
    } else if post_residual < 30 {
        score += 18.0 + (30 - post_residual) as f64 * 0.6;
    }

    // Lookahead on next item
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 800.0;
        } else if next_item_size <= post_residual {
            let post2 = post_residual - next_item_size;
            score -= 120.0 - (post2 as f64) * 2.0;
            if post2 == 0 { score -= 100.0; }
            if post2 > 0 && post2 < 5 { score -= 28.0; }
            if post2 % 10 == 0 && post2 > 0 { score -= 25.0; }
            if post_residual % next_item_size == 0 { score -= 18.0; }
            if post_residual >= next_item_size * 2 && post_residual - next_item_size * 2 <= 4 {
                score -= 20.0;
            }
            let chain = post_residual / next_item_size;
            if chain >= 2 { score -= (chain.min(4)) as f64 * 6.0; }
            if post2 > 0 && post2 <= next_item_size / 4 { score -= 10.0; }
        } else {
            let gap = next_item_size - post_residual;
            if post_residual > 0 {
                if gap <= 3 { score += 35.0; }
                else if gap <= 8 { score += 12.0; }
                if (gap as f64) > mean_residual * 0.5 { score += 14.0; }
                if post_residual < 15 { score += 40.0; }
                if gap <= 5 { score += (6 - gap) as f64 * 4.0; }
                if post_residual as f64 > mean_residual * 1.4 { score -= 12.0; }
            } else {
                score += 20.0;
            }
        }
    }

    // Compaction pressure
    score += open_bins_count as f64 * 0.8;

    // Last-chance bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 45.0;
    }

    // Tightness
    score -= (item_size as f64 / bin_residual.max(1) as f64) * 30.0;

    // NEW-BIN CANDIDATE handling
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let avg_fill = 1.0 - (mean_residual / cap_f);
        let newbin_waste = (bin_capacity - item_size) as f64;
        score += 250.0 - avg_fill * 330.0 - progress * 65.0;
        if item_size as f64 / cap_f > 0.75 { score -= 55.0; }
        if item_size >= bin_capacity * 3 / 4 { score -= 55.0; }
        if item_size as f64 > mean_residual { score -= 40.0; }
        if newbin_waste < mean_residual * 0.5 { score -= 30.0; }
        if bin_capacity - item_size <= 4 { score -= 70.0; }
        if next_item_size > 0 {
            let leftover = bin_capacity - item_size;
            if leftover >= next_item_size {
                let tail = leftover % next_item_size;
                if tail == 0 { score -= 12.0; }
                else if tail <= 4 { score -= 16.0; }
                if leftover >= next_item_size * 2 { score -= 14.0; }
                if leftover - next_item_size <= 6 { score -= 35.0; }
            } else if leftover < 10 {
                score += 18.0;
            }
        }
        if fitting_bins_count > 0 {
            score += (fitting_bins_count.min(5) as f64) * 9.0;
            let snug = item_size as f64 / bin_residual.max(1) as f64;
            if snug > 0.9 { score += 40.0; }
            if snug > 0.95 { score += 28.0; }
        }
        if fitting_bins_count > 3 && item_size as f64 / cap_f < 0.5 { score += 30.0; }
        // late stream: resist opening bins with big waste
        if progress > 0.6 && newbin_waste > (1.0 - progress) * cap_f * 0.35 && fitting_bins_count > 0 {
            score += 10.0 + progress * 22.0;
        }
        if progress > 0.85 && newbin_waste > cap_f * 0.3 { score += 8.0; }
        if progress < 0.1 { score -= 5.0; }
    } else {
        // Consolidation of slack toward below-average residuals
        score += (mean_residual - bin_residual as f64) * 1.5;

        let dead_ratio = post_residual as f64 / cap_f;
        if dead_ratio < 0.03 { score -= 38.0; }
        else if dead_ratio < 0.08 { score -= 14.0; }
        else if dead_ratio > 0.35 { score += 24.0; }
        else if dead_ratio > 0.25 { score += 10.0; }

        if post_residual > 0 && next_item_size > 0 && post_residual < next_item_size {
            let wasted = (next_item_size - post_residual) as f64;
            score += wasted * 0.6;
            let unusable = (next_item_size - post_residual) > 12;
            if unusable { score += dead_ratio * 90.0; }
        }
        if post_residual > 0 && post_residual < 6 { score -= 22.0; }
        if post_residual > 0 && (post_residual as f64) < mean_residual * 0.25 { score -= 15.0; }
        if item_size == bin_residual { score -= 45.0; }
        if post_residual > 0 && post_residual % 10 == 0 { score -= 10.0; }
        if post_residual > 0 && post_residual % 5 == 0 && post_residual <= 30 { score -= 8.0; }
        if bin_residual as f64 > cap_f * 0.6 { score -= 12.0; }
        if fitting_bins_count <= 2 && post_residual > 0 { score -= 8.0; }
        if post_residual > 0 && (post_residual as f64) > mean_residual * 1.6 && fitting_bins_count > 2 {
            score += 10.0;
        }
        let progress = step_index as f64 / total_items.max(1) as f64;
        if post_residual > 0 && next_item_size > 0 && post_residual < next_item_size {
            score += (1.0 - progress) * 14.0;
            if dead_ratio > 0.2 { score += dead_ratio * 30.0; }
        }
        if post_residual > 0 && next_item_size > 0 && post_residual >= next_item_size {
            let mres = mean_residual.max(1.0);
            let dist = (post_residual as f64 - mres).abs();
            score += dist * 0.35;
            if dist < cap_f * 0.03 { score -= 10.0; }
            let reuse = (post_residual / next_item_size) as f64 * (next_item_size as f64 / cap_f);
            score -= reuse * 22.0;
        }
        if post_residual > 0 && next_item_size > 0 && post_residual + next_item_size <= bin_capacity
            && (post_residual as f64) < mean_residual * 0.5 {
            score -= 9.0;
        }
    }

    // Mild early-stream diversity nudge
    let progress = step_index as f64 / total_items.max(1) as f64;
    if progress < 0.1 && bin_residual < bin_capacity { score += 3.0; }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let pr_norm = pr / cap;
    let nxt = next_item_size as f64;

    // Base: prefer small post_residual (tight fit), with smooth non-linear emphasis
    let mut score = pr_norm * (1.0 + 2.0 * pr_norm * (1.0 + progress));

    // Dead-space penalty: residual too small for the lookahead item (smooth ramp)
    if next_item_size > 0 {
        let dead = (nxt - pr).max(0.0) / cap;
        score += 3.0 * dead * dead / (0.05 + progress * 0.5);
        // Reward residual that exactly accommodates the next item
        let fits_next = (pr - nxt).max(0.0) / cap;
        score -= 0.8 * (1.0 - fits_next / (1.0 + fits_next));
    }

    // Last-chance bonus: avoid opening a new bin when this is the only fitting one
    if fitting_bins_count == 1 {
        score -= 2.5 * (1.0 - progress * 0.5);
    }

    // Mild penalty for spreading across many open bins when residuals are large
    score += 0.05 * open_bins_count as f64 * (mean_residual / cap) * (0.5 + progress);

    // Encourage consolidation late in the stream
    score -= 1.5 * progress * (1.0 - pr_norm);

    // Slight penalty if this bin is nearly full already (avoid over-tight packing churn)
    let tightness = 1.0 - bin_residual as f64 / cap;
    score += 0.3 * tightness * tightness * (1.0 - progress);

    // New-bin candidate: keep it competitive only when item is large relative to capacity
    if bin_residual == bin_capacity {
        score -= 0.6 * (item_size as f64 / cap);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: bins whose leftover falls into
    // "usable" small-residue classes are preferred.
    let cap_f = bin_capacity as f64;
    let frac = post_residual as f64 / cap_f; // residual fraction of capacity

    // Perfect-fit / near-perfect-fit reward (strong).
    if post_residual == 0 {
        score -= 1000.0;
    } else if post_residual <= 5 {
        score -= 200.0;
    }

    // Harmonic class penalty: residual in dead zones (too small for typical
    // items 10..80, i.e. 1..10) is wasted space.
    if post_residual >= 1 && post_residual < 10 {
        score += 150.0; // unusable sliver
    }

    // Modulo-10 harmonic classes: residuals that are multiples of 10 pair
    // cleanly with the integer item-size grid.
    if post_residual % 10 == 0 {
        score -= 30.0;
    }

    // Integer-division thresholds: classify residual into bands.
    let band = post_residual / 20; // 0..=5 bands
    let band_bonus: [f64; 6] = [0.0, -60.0, -40.0, -10.0, 20.0, 40.0];
    let bi = (band as usize).min(5);
    score += band_bonus[bi];

    // Lookahead coupling: if next item fits exactly in post_residual,
    // reward heavily (chain packing).
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 400.0;
        } else if next_item_size <= post_residual {
            score -= 50.0 + 0.5 * (next_item_size as f64);
        } else {
            // next item cannot use this residual: penalize large leftovers
            score += 0.3 * frac * 100.0;
        }
    }

    // Last-chance bin: if this is the only bin that fits, strongly favor it
    // over opening a new bin (unless fit is terrible).
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 120.0;
    }

    // New-bin candidate handling: opening a new bin is only attractive when
    // current residuals are fragmented (high mean residual spread) or the
    // item fits badly everywhere.
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        // Base cost of a fresh bin: discourage unless placement elsewhere is bad.
        score = cap_f + 40.0;
        // If mean residual across open bins is large (fragmented), new bin
        // becomes relatively more attractive.
        score -= 0.4 * mean_residual;
        // If no other bin fits (this call is the only candidate), open it.
        if fitting_bins_count == 0 {
            score -= 1000.0;
        }
        // Late in the stream, prefer consolidating rather than opening bins.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 30.0 * progress;
    } else {
        // Mild preference for filling fuller bins first (best-fit core),
        // scaled by how many alternatives exist.
        if fitting_bins_count > 2 {
            score += 5.0; // with many options, tie-break toward tight fits
        }
    }

    // Harmonic sine modulation on residual fraction: smooth class coupling.
    score += 8.0 * (std::f64::consts::PI * frac).sin();

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals that are too small to ever be
    // useful (below the minimum plausible item size of 1..100, treat tiny
    // gaps < 10 as near-wasted) are heavily penalized.
    if post_residual < 10 {
        score += 60.0;
    } else if post_residual < 25 {
        score += 20.0;
    }

    // Perfect or near-perfect fit is extremely desirable.
    if post_residual == 0 {
        score -= 50.0;
    } else if post_residual <= 5 {
        score -= 15.0;
    }

    // Reward bins whose residual tightly matches the item (good fit).
    let tightness = item_size as f64 / bin_residual.max(1) as f64;
    score -= 30.0 * tightness;

    // Last-chance bin: strongly prefer using it before opening a new one.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 40.0;
    }

    // Lookahead coupling: if the next item fits the post-residual exactly or
    // closely, reward this placement.
    if next_item_size > 0 && post_residual >= next_item_size {
        let slack = (post_residual - next_item_size) as f64;
        score -= 25.0 * (1.0 - slack / 100.0);
    } else if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        // Post-residual too small for the next item -> dead space penalty.
        score += 15.0;
    }

    // Open-bin pressure: with many open bins, discourage spreading into new
    // bins; with few open bins, opening a new bin (full residual) is cheaper.
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pressure = open_bins_count as f64 / (1.0 + progress);
    score += 0.5 * pressure * (mean_residual / bin_capacity as f64);

    // New-bin candidate: only attractive when existing bins fit poorly
    // (high mean residual mismatch) or few bins are open.
    if bin_residual == bin_capacity {
        let mismatch = (mean_residual - item_size as f64).abs();
        score += 20.0 + 0.3 * open_bins_count as f64 - 0.2 * mismatch;
        if fitting_bins_count == 0 {
            score -= 100.0; // no alternative: new bin is fine
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Aggressive 2-step lookahead: reward exact match between post_residual
    // and the next item's size (perfect two-item packing).
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if (post_residual as f64 - nxt).abs() < 0.5 {
            score -= 60.0; // exact match: next item fills this bin perfectly
        } else if post_residual >= next_item_size {
            // next item fits here: partial reward scaled by how much slack remains after
            let second_post = post_residual as f64 - nxt;
            score -= 30.0 * (1.0 - second_post / bin_capacity as f64);
        } else {
            // next item cannot fit after placing: penalize proportionally to the gap
            let gap = nxt - post_residual as f64;
            score += 8.0 * (gap / bin_capacity as f64);
        }
    }

    // Penalize unusable dead space: residuals too small for any realistic item
    // (items >= 1, but small slivers are wasted in practice).
    if post_residual > 0 && post_residual < 10 {
        score += 15.0;
    }

    // Relative-to-mean-residual coupling: prefer bins that are already
    // tighter than average (consolidating fill), avoid near-empty bins
    // when others are fuller.
    let residual_f = bin_residual as f64;
    if residual_f < mean_residual {
        score -= 6.0 * (mean_residual - residual_f) / bin_capacity as f64;
    } else {
        score += 6.0 * (residual_f - mean_residual) / bin_capacity as f64;
    }

    // Last-chance bin: if this is the only bin that fits, strongly favor it
    // to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate handling: empty bin should only win when it is
    // genuinely attractive (large item / no good existing fit). Penalize
    // opening a new bin mildly, scaled by stream progression and how many
    // bins are already open.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 20.0 + 10.0 * progress + 0.5 * open_bins_count as f64;
        // But if the item exactly halves a fresh bin and the next item
        // matches the other half, opening new is great.
        if next_item_size > 0 && (post_residual as i64 - next_item_size as i64).abs() < 2 {
            score -= 70.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap_f = bin_capacity as f64;
    let progress = step_index as f64 / total_items.max(1) as f64;
    let mut score = post_residual as f64;

    // Dead-space avoidance: tiered, stronger than parent
    if post_residual == 0 {
        score -= 900.0;
    } else if post_residual <= 3 {
        score -= 380.0;
    } else if post_residual <= 12 {
        score -= 70.0;
    } else if post_residual < 20 {
        score += 16.0;
    } else if post_residual < 30 {
        score += 16.0 + (30 - post_residual) as f64 * 0.5;
    }

    // Lookahead: exact and near-exact fits for next item
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 650.0;
        } else if next_item_size <= post_residual {
            let post2 = post_residual - next_item_size;
            score -= 100.0 - (post2 as f64) * 1.6;
            if post2 == 0 { score -= 90.0; }
            if post2 > 0 && post2 < 5 { score -= 26.0; }
            if post2 % 10 == 0 && post2 > 0 { score -= 20.0; }
            if post2 <= next_item_size / 4 { score -= 10.0; }
            if post_residual % next_item_size == 0 { score -= 14.0; }
            if post_residual >= next_item_size * 2 && post_residual - next_item_size * 2 <= 4 {
                score -= 20.0;
            }
            let chain = post_residual / next_item_size;
            if chain >= 2 { score -= (chain.min(4)) as f64 * 6.0; }
        } else {
            // next item won't fit here: penalize near-fitting gaps
            let gap = next_item_size - post_residual;
            if post_residual > 0 {
                if gap <= 3 { score += 35.0; }
                else if gap <= 8 { score += 12.0; }
                if (gap as f64) > mean_residual * 0.5 { score += 12.0; }
                if post_residual < 15 { score += 30.0; }
                if post_residual as f64 > mean_residual * 1.4 { score -= 10.0; }
            }
        }
    }

    // Compaction pressure scaled by open bins
    score += open_bins_count as f64 * 0.8;

    // Last-chance bin: strongly favor using it
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 55.0;
    }

    // Tightness via relative fill
    score -= (item_size as f64 / bin_residual.max(1) as f64) * 30.0;

    // Consolidate slack: prefer bins whose residual is below average
    if bin_residual < bin_capacity {
        score += (mean_residual - bin_residual as f64) * 1.1;
        // dead-space ratio shaping
        let dead_ratio = post_residual as f64 / cap_f;
        if dead_ratio < 0.03 { score -= 30.0; }
        else if dead_ratio < 0.08 { score -= 12.0; }
        else if dead_ratio > 0.30 { score += 20.0; }
    }

    // NEW-BIN CANDIDATE handling
    if bin_residual == bin_capacity {
        let newbin_waste = (bin_capacity - item_size) as f64;
        let avg_fill = 1.0 - (mean_residual / cap_f);
        score += 220.0 - avg_fill * 300.0 - progress * 60.0;
        // big items deserve a fresh bin when few alternatives fit well
        if item_size as f64 / cap_f > 0.75 { score -= 55.0; }
        if item_size >= bin_capacity * 3 / 4 { score -= 20.0; }
        if item_size as f64 > mean_residual { score -= 30.0; }
        if newbin_waste < mean_residual * 0.5 { score -= 30.0; }
        if bin_capacity - item_size <= 4 { score -= 60.0; }
        // fresh bin pairs perfectly with next item
        if next_item_size > 0 {
            let leftover = bin_capacity - item_size;
            if leftover >= next_item_size && leftover - next_item_size <= 6 { score -= 35.0; }
            if leftover >= next_item_size {
                let tail = leftover % next_item_size;
                if tail == 0 { score -= 12.0; }
                else if tail <= 4 { score -= 14.0; }
            } else if leftover < 10 { score += 18.0; }
            if next_item_size >= bin_capacity / 2 { score -= 28.0; }
        }
        // alternatives exist and are decent: discourage new bin
        if fitting_bins_count > 0 {
            score += (fitting_bins_count.min(6)) as f64 * 8.0 + 15.0;
            let snug = item_size as f64 / cap_f;
            if snug > 0.95 { score -= 20.0; }
            if fitting_bins_count > 3 && item_size as f64 / cap_f < 0.5 { score += 25.0; }
        }
        // late stream: waste tolerance shrinks
        if progress > 0.6 {
            let waste_tol = (1.0 - progress) * cap_f * 0.35;
            if newbin_waste > waste_tol && fitting_bins_count > 0 {
                score += 10.0 + progress * 20.0;
            }
        }
        if progress < 0.1 { score -= 5.0; }
    }

    // Early-stream diversity nudge for open bins
    if progress < 0.1 { score += 3.0; }

    // Reusability of the resulting gap for future items
    if post_residual > 0 && next_item_size > 0 {
        if post_residual < next_item_size {
            let wasted = next_item_size as f64 - post_residual as f64;
            if wasted > 12.0 { score += wasted * 0.5; }
        } else {
            let reuse = (post_residual / next_item_size) as f64 * (next_item_size as f64 / cap_f);
            score -= reuse * 20.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Progress of the stream (0..1)
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    // Tightness: reward near-perfect fits (small post_residual) nonlinearly.
    let tight = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 30.0 * tight * tight;

    // Dead-space penalty: residuals too small for any plausible item (1..100).
    if post_residual < 1 {
        score -= 1000.0;
    } else if post_residual < 10 {
        // unusable sliver for most distributions -> strong penalty
        score += 40.0 * (10.0 - post_residual as f64);
    }

    // Last-chance bonus: if this is the only bin that fits, strongly prefer using it.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 60.0;
    }

    // Lookahead coupling: if the next item fits in the post residual, reward;
    // if this placement barely blocks the next item, penalize.
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        if post_residual as f64 >= nx {
            score -= 15.0;
            // extra reward when next item fills the remainder almost exactly
            let gap = post_residual as f64 - nx;
            score -= 10.0 * (1.0 - gap / bin_capacity as f64);
        } else {
            score += 8.0 * (nx - post_residual as f64) / 100.0;
        }
    }

    // Prefer bins below mean residual (keep a spread of residual sizes).
    let dev = bin_residual as f64 - mean_residual;
    score += 0.15 * dev;

    // Early in stream: encourage compact packing (prefer fuller bins).
    // Late in stream: prefer spreading to keep options open.
    score += (1.0 - progress) * 5.0 * (bin_residual as f64 / bin_capacity as f64);
    score -= progress * 5.0 * (bin_residual as f64 / bin_capacity as f64);

    // New-bin candidate logic: opening a new bin is only attractive when no
    // open bin fits well (large item relative to residuals) or many bins are open.
    if bin_residual == bin_capacity {
        // base cost of opening a new bin
        let mut new_bin_score = bin_capacity as f64 + 25.0;
        // cheaper to open when open bins are crowded / few fit
        if fitting_bins_count == 0 {
            new_bin_score -= 200.0;
        }
        new_bin_score -= 10.0 * open_bins_count as f64;
        // large current item with big lookahead -> new bin keeps flexibility
        if next_item_size as f64 > mean_residual {
            new_bin_score -= 15.0;
        }
        // late stream: avoid proliferating bins
        new_bin_score += 40.0 * progress;
        score = new_bin_score;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;

    // Base: penalize residual, with non-linear polynomial shaping
    let mut score = pr * (1.0 + 0.5 * norm_pr * norm_pr);

    // Smooth coupling of residual quality with stream progress:
    // later in stream, tighter fills matter more (reward small post_residual harder)
    let late = progress * progress;
    score -= (cap - pr) * late * 0.8;

    // Penalize residual far from mean residual (fragmentation signal), smoothly
    let dev = (pr - mean_residual) / cap;
    score += 12.0 * dev * dev;

    // Lookahead: reward leaving space that fits the next item
    if next_item_size > 0 {
        let ns = next_item_size as f64;
        if pr >= ns {
            let fit_margin = (pr - ns) / cap;
            score -= 15.0 * (1.0 - fit_margin).max(0.0);
        } else {
            // residual too small for next item: penalize proportionally
            score += 10.0 * (ns - pr) / cap;
        }
    }

    // Last-chance bin: strong reward to use it rather than open new
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // Many open bins: discourage spreading; slight penalty scaled smoothly
    let ob = open_bins_count as f64;
    score += ob * (1.0 + late) * 0.5;

    // New-bin candidate: only attractive when nothing fits well
    if bin_residual == bin_capacity {
        let scarcity = 1.0 / (fitting_bins_count as f64 + 1.0);
        score = cap * (1.0 - scarcity * 0.9) + late * 20.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post-residual: small residues in low classes are dead space.
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;

    // Perfect fits get a huge reward.
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Harmonic classes: residue buckets of size cap/8.
    let class = (pr / (cap / 8.0)).floor(); // 0..7
    score -= class * 8.0;

    // Modulo arithmetic on post_residual: residues near multiples of common item sizes
    // (10, 20, 25, 50) are more likely to be filled by future items.
    for m in [10u32, 20, 25, 50] {
        let r = post_residual % m;
        let d = r.min(m - r) as f64;
        score -= (m as f64 / 10.0) * (1.0 - d / (m as f64 / 2.0)) * 3.0;
    }

    // Next-item lookahead: if next item fits exactly in post_residual, big reward.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 500.0;
        } else if next_item_size < post_residual {
            let leftover = post_residual - next_item_size;
            score -= 30.0 - (leftover as f64).min(30.0);
        } else {
            // next item cannot use this residue: penalize large residues mildly
            score += 5.0;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // New-bin candidate: only attractive when no open bin fits well.
    if bin_residual == bin_capacity {
        score += 60.0;
        if fitting_bins_count == 0 {
            score -= 200.0;
        }
    }

    // Prefer tight fills relative to mean residual across open bins.
    score -= (mean_residual - pr).max(0.0) * 0.5;

    // Slight preference for keeping number of open bins low early in the stream.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += open_bins_count as f64 * (1.0 - progress) * 0.5;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
