pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Aggressive 2-step lookahead: reward post_residual matching next item exactly.
    if next_item_size > 0 {
        let gap = (post_residual as i64 - next_item_size as i64).abs() as f64;
        // Perfect two-item fill => strong reward
        score -= 60.0 * (1.0 - gap / bin_capacity as f64).powi(3);
        // Penalize leaving residuals that are too small for the next item (dead space)
        if post_residual < next_item_size && post_residual > 0 {
            score += 25.0 * (1.0 - post_residual as f64 / next_item_size as f64);
        }
        // Slight reward if next item could still fit (flexibility kept)
        if post_residual >= next_item_size {
            score -= 5.0;
        }
    }

    // Relative tightness against mean residual: prefer bins tighter than average
    score += 0.4 * (bin_residual as f64 - mean_residual);

    // Last-chance bin: strong reward to avoid opening a new bin unnecessarily
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 40.0;
    }

    // New-bin candidate: penalize opening a new bin when others fit,
    // unless item is large and few bins are open.
    if bin_residual == bin_capacity {
        let base_penalty = 30.0;
        let relief = (item_size as f64 / bin_capacity as f64) * 20.0
            + (open_bins_count as f64).ln().max(0.0) * 3.0;
        score += base_penalty - relief;
    }

    // Encourage tight fits overall (small post_residual relative to item)
    score += 10.0 * (post_residual as f64 / bin_capacity as f64).powi(2);

    // Mild stream-phase modulation: tighten packing as stream progresses
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score += 8.0 * progress * (post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
