pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits (small post_residual relative to capacity).
    let tightness = 1.0 - (post_residual as f64) / (bin_capacity as f64);
    score -= 18.0 * tightness;

    // Penalize dead space that is too small to be useful later.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Lookahead: if the next item fits exactly into the post residual, big reward.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 40.0;
        } else if next_item_size <= post_residual {
            // next item fits, but imperfectly: mild reward scaled by fill
            score -= 12.0 * (next_item_size as f64 / post_residual.max(1) as f64);
        } else {
            // next item won't fit here: penalize leaving awkward gaps
            let gap = (post_residual as f64 - next_item_size as f64).abs();
            score += 6.0 * (1.0 - gap / (bin_capacity as f64));
        }
    }

    // Last chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate: only attractive when the item fits poorly everywhere
    // (i.e., this empty bin yields a large post_residual is bad; but a fresh bin
    // has full flexibility). Penalize opening new bins mildly, more early on.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    if bin_residual == bin_capacity {
        score += 45.0 - 25.0 * progress;
        // opening a bin is more attractive when few bins are open
        score -= (open_bins_count as f64).min(5.0) * 2.0;
    } else {
        // Favor bins whose residual deviates favorably from the mean
        let dev = bin_residual as f64 - mean_residual;
        score += 0.15 * dev;
    }

    // Prefer filling bins with larger residual when many bins are open.
    score -= 0.05 * (bin_residual as f64) * (open_bins_count as f64 / 10.0);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
