pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let mut score = post;

    // Smooth polynomial coupling of post_residual with stream progress
    let pr_norm = post / cap;
    let p2 = pr_norm * pr_norm;
    score += (2.0 + 8.0 * progress) * p2 * cap * 0.15;

    // Reward tight fits more strongly later in the stream
    let tightness = 1.0 - pr_norm;
    score -= tightness * tightness * (10.0 + 30.0 * progress);

    // Penalize dead space relative to mean residual
    score += 0.3 * (post - mean_residual).abs();

    // Lookahead: reward residual that can host next item
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if post >= nxt {
            score -= 6.0 * (1.0 - (post - nxt) / cap);
        } else {
            score += 4.0 * (nxt - post) / cap;
        }
    }

    // Last-chance bin bonus
    if fitting_bins_count == 1 {
        score -= 8.0;
    }

    // Mild penalty on spreading across many bins
    score += 0.05 * open_bins_count as f64 * pr_norm;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strongly reward tight fits (harmonic classes: post_residual small relative to capacity)
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let tight = 1.0 - (pr / cap);
    score -= 2.5 * tight * tight;

    // Perfect fit: overwhelming reward
    if post_residual == 0 {
        score -= 100.0;
    } else if post_residual <= bin_capacity / 20 {
        score -= 15.0;
    }

    // Harmonic class penalty: dead space in awkward residue classes is hard to reuse.
    // Items sizes 1..100; residues mod 10 matter for typical distributions.
    let dead_class = post_residual % 10;
    if post_residual > 0 && dead_class != 0 {
        // penalize non-round dead space slightly, more if below smallest plausible item
        score += 1.0 + (dead_class as f64) * 0.1;
        if post_residual < 10 {
            score += 10.0; // unusable dead space
        }
    }

    // Lookahead: if next item fits exactly into post_residual, big reward (chained pair)
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 30.0;
        } else if next_item_size <= post_residual {
            let slack_after_next = post_residual - next_item_size;
            score -= 6.0 * (1.0 - slack_after_next as f64 / cap);
        } else {
            // next item cannot use this bin's residue: mild penalty for wasting space
            score += 0.5 * (next_item_size as f64 - post_residual as f64) / cap;
        }
    }

    // Last chance bin: strongly favor using it over opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // New-bin candidate: neutral-ish baseline, but discourage opening new bins
    // when there are many open bins with mean residual that could absorb the item.
    if bin_residual == bin_capacity {
        score = cap * 0.75;
        if next_item_size > 0 && next_item_size >= bin_capacity / 2 {
            // large next item: a fresh bin is more attractive
            score -= 10.0;
        }
        if fitting_bins_count > 0 {
            score += 5.0 + 2.0 * (fitting_bins_count as f64).sqrt();
        }
        if open_bins_count > 0 && mean_residual > item_size as f64 {
            score += 8.0; // existing bins have plenty of room; don't open new
        }
        // early stream: allow more bins
        let progress = step_index as f64 / total_items.max(1) as f64;
        score -= 5.0 * (1.0 - progress);
    }

    // Congestion control: many open bins -> prefer consolidating into existing ones
    if bin_residual != bin_capacity {
        score -= 0.3 * (open_bins_count as f64).ln().max(0.0);
        // favor bins whose residual is below mean (filling the emptier ones)
        if (bin_residual as f64) < mean_residual {
            score -= 1.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap_f = bin_capacity as f64;
    let progress = step_index as f64 / total_items.max(1) as f64;
