                else if gap <= 8.0 { score += 12.0; }
                if gap > mean_residual * 0.5 { score += 12.0; }
                if post_residual < 15 { score += 40.0; }
                if post_residual as f64 > mean_residual * 1.4 { score -= 10.0; }
            }
        }
        if post_residual > 0 && post_residual < next_item_size && post_residual >= item_size * 2 {
            score += 10.0;
        }
        if post_residual > next_item_size * 2 && post_residual / 2 >= next_item_size {
            score -= 10.0;
        }
    }

    // Compaction pressure scaled by open bins
    score += open_bins_count as f64 * 0.8;

    // Last-chance bin: strongly favor using it
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 50.0;
    }

    // Tightness via relative fill
    let snug = item_size as f64 / bin_residual.max(1) as f64;
    score -= snug * 30.0;
    if snug > 0.95 && bin_residual < bin_capacity { score -= 12.0; }
    if item_size == bin_residual { score -= 45.0; }

    // Consolidate slack: prefer bins below-average residual
    if bin_residual < bin_capacity {
        score += (mean_residual - bin_residual as f64) * 1.2;
    }

    // NEW-BIN CANDIDATE handling
    if bin_residual == bin_capacity {
        let avg_fill = 1.0 - (mean_residual / cap_f);
        let newbin_waste = (bin_capacity - item_size) as f64;
        score += 220.0 - avg_fill * 300.0 - progress * 60.0;
        if item_size as f64 / cap_f > 0.75 { score -= 55.0; }
        if item_size >= bin_capacity * 3 / 4 { score -= 25.0; }
        if item_size as f64 > mean_residual { score -= 30.0; }
        if newbin_waste < mean_residual * 0.6 { score -= 30.0; }
        if bin_capacity - item_size <= 4 { score -= 60.0; }
        if next_item_size > 0 {
            let leftover = bin_capacity - item_size;
            if leftover >= next_item_size {
                let tail = leftover % next_item_size;
                if tail == 0 { score -= 20.0; }
                else if tail <= 4 { score -= 16.0; }
                if leftover - next_item_size <= 6 { score -= 35.0; }
                if leftover >= next_item_size * 2 { score -= 12.0; }
            } else if leftover < 10 {
                score += 18.0;
            }
            if next_item_size >= bin_capacity / 2 { score -= 25.0; }
        }
        if fitting_bins_count > 0 {
            score += (fitting_bins_count.min(5) as f64) * 9.0 + 20.0;
            if snug > 0.9 { score += 40.0; }
            if snug > 0.95 { score += 28.0; }
            if snug > 0.98 { score += 18.0; }
        }
        if fitting_bins_count > 3 && item_size as f64 / cap_f < 0.5 { score += 30.0; }
        // late stream: resist opening bins with big waste
        if progress > 0.6 {
            let waste_tol = (1.0 - progress) * cap_f * 0.35;
            if newbin_waste > waste_tol && fitting_bins_count > 0 {
                score += 10.0 + progress * 22.0;
            }
        }
        if progress < 0.1 { score -= 5.0; }
    } else {
        // Dead-ratio shaping for open bins
        let dead_ratio = post_residual as f64 / cap_f;
        if dead_ratio < 0.03 { score -= 38.0; }
        else if dead_ratio < 0.08 { score -= 14.0; }
        else if dead_ratio > 0.35 { score += 24.0; }
        else if dead_ratio > 0.25 { score += 10.0; }

        if post_residual > 0 && post_residual < 6 { score -= 22.0; }
        if post_residual > 0 && (post_residual as f64) < cap_f * 0.015 { score -= 18.0; }
        if post_residual > 0 && post_residual % 10 == 0 { score -= 10.0; }

        // unusable-gap penalty scaled by dead fraction
        if post_residual > 0 && next_item_size > 0 && post_residual < next_item_size {
            let wasted = next_item_size as f64 - post_residual as f64;
            score += wasted * 0.6 + dead_ratio * 25.0;
            if wasted > 12.0 { score += dead_ratio * 60.0; }
        } else if next_item_size > 0 && post_residual > 0 {
            let reuse = (post_residual / next_item_size) as f64 * (next_item_size as f64 / cap_f);
            score -= reuse * 22.0;
        }
        if fitting_bins_count <= 2 && post_residual > 0 { score -= 8.0; }
        if progress < 0.1 { score += 3.0; }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals that are too small to be useful
    // for any future item (assume minimum plausible item ~ 1..15) are toxic.
    let dead_threshold = 12.0;
    if post_residual > 0 && (post_residual as f64) < dead_threshold {
        // Waste penalty dominates: perfect-fit gets huge reward instead.
        score += (dead_threshold - post_residual as f64) * 40.0;
    }

    // Reward tight fits (small post_residual relative to item size).
    let tightness = item_size as f64 / (post_residual as f64 + 1.0);
    score -= tightness * 8.0;

    // Reward near-exact fills.
    if post_residual == 0 {
        score -= 60.0;
    } else if post_residual <= 5 {
        score -= 30.0;
    }

    // Lookahead coupling: if next item fits exactly in post_residual, big reward.
    if next_item_size > 0 && next_item_size == post_residual {
        score -= 50.0;
    } else if next_item_size > 0 && next_item_size > post_residual {
        // Next item won't fit here anyway; residual is dead unless reusable later.
        score += (post_residual as f64) * 0.5;
    }

    // Last chance: if this is the only bin that fits, strongly prefer using it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 25.0;
    }

    // Open-bin pressure: with many open bins, avoid spreading; prefer filling
    // existing bins rather than opening new ones.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score += open_bins_count as f64 * 1.5 * (0.5 + progress);

    // Penalize bins whose residual is far below mean (fragmented bins) mildly,
    // prefer placing into bins with above-average residual when post_residual large.
    if (post_residual as f64) > mean_residual {
        score -= 5.0;
    } else {
        score += 3.0;
    }

    // New-bin candidate (empty bin): make it attractive only when the fit here
    // is poor (large post_residual) — otherwise discourage opening new bins.
    if bin_residual == bin_capacity {
        if post_residual as f64 > 40.0 {
            score -= 10.0; // poor fits elsewhere -> fresh bin is fine
        } else {
            score += 45.0; // good fit exists -> keep item in open bin
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong reward for perfect fit
    if post_residual == 0 {
        score -= 500.0;
    }

    // 2-step lookahead: reward when leftover exactly fits next item
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 300.0;
        } else if post_residual >= next_item_size {
            // leftover can host next item: mild bonus scaled by tightness
            let slack = (post_residual - next_item_size) as f64;
            score -= 150.0 / (1.0 + slack / 10.0);
        } else {
            // leftover too small for next item: penalize dead space
            let dead = (next_item_size - post_residual) as f64;
            score += dead * 0.5;
        }
    }

    // Compare post_residual to mean residual: avoid creating outlier-large holes
    score += (post_residual as f64 - mean_residual).abs() * 0.3;

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 200.0;
    }

    // Penalize opening a new bin when open bins exist and fit reasonably
    if bin_residual == bin_capacity {
        if fitting_bins_count > 0 {
            score += 250.0;
        } else {
            score -= 50.0;
        }
        // later in the stream, prefer consolidating into existing bins
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score += progress * 100.0;
    }

    // Mild preference for tighter current fits
    score += (bin_residual - item_size) as f64 * 0.1;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let score = 0.0;
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits (small post_residual) nonlinearly.
    let cap = bin_capacity as f64;
    let tightness = 1.0 - (post_residual as f64) / cap;
    score -= 12.0 * tightness * tightness;

    // Penalize dead space that no plausible future item can use.
    if post_residual > 0 {
        let dead = if post_residual < 10 { 0.0 } else { post_residual as f64 };
        score += 0.35 * dead;
    }

    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 25.0;
    }

    // Lookahead: reward if the next item fits into the resulting residual.
    if next_item_size > 0 {
        if (post_residual as u64) >= (next_item_size as u64) {
            score -= 8.0 + 0.1 * (next_item_size as f64);
        } else {
            // Wasted lookahead opportunity if gap is small but unusable.
            let gap = next_item_size as f64 - post_residual as f64;
            if gap > 0.0 && gap <= 15.0 {
                score += 3.0 * (1.0 - gap / 15.0);
            }
        }
    }

    // Last-chance bin: strongly prefer using it before opening a new bin.
    if fitting_bins_count == 1 {
        score -= 20.0;
    }

    // Many fitting bins: mild penalty to prefer consolidation into fewer bins.
    if fitting_bins_count > 1 {
        score += 1.5 * (fitting_bins_count as f64 - 1.0);
    }

    // Time horizon: early in the stream, be more conservative (favor new bins
    // for poor fits); late in the stream, squeeze into existing bins.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score -= 6.0 * progress * tightness;

    // Global state: penalize spreading across many open bins when mean residual
    // is large (fragmentation risk), reward consolidation.
    if open_bins_count > 0 {
        let frag = mean_residual / cap;
        score += 2.0 * frag * (open_bins_count as f64).ln().max(0.0);
    }

    // New-bin candidate handling: an empty bin has residual == capacity.
    // Make it attractive only when the item is large relative to capacity or
    // no open bin is a good fit; otherwise discourage opening new bins.
    if bin_residual == bin_capacity {
        let item_ratio = item_size as f64 / cap;
        if item_ratio > 0.5 {
            score -= 10.0 * item_ratio;
        } else {
            score += 8.0 * (1.0 - item_ratio);
        }
        if fitting_bins_count == 0 {
            score -= 30.0;
        }
    }

    // Small coupling: reward placing large items into large residuals.
    let size_ratio = item_size as f64 / cap;
    let res_ratio = bin_residual as f64 / cap;
    score -= 4.0 * size_ratio * res_ratio;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;

    // Base: prefer tight fits (small post_residual), with non-linear shaping
    let mut score = pr as f64;
    score += 40.0 * norm_pr * norm_pr;
    score -= 25.0 * norm_pr * norm_pr * norm_pr;

    // Smooth interaction: post_residual vs stream progress
    score += 30.0 * norm_pr * progress * (1.0 - progress) * 4.0;
    score -= 15.0 * (1.0 - progress) * (1.0 - progress) * norm_pr;

    // Penalize large dead space relative to mean residual (waste coupling)
    let mr = mean_residual / cap;
    score += 20.0 * (norm_pr - mr).abs() * (norm_pr - mr).abs();

    // Lookahead: reward residuals that can host next item
    if next_item_size > 0 && (post_residual as u32) >= next_item_size {
        let fit_margin = (post_residual as f64 - next_item_size as f64) / cap;
        score -= 12.0 * (1.0 - fit_margin * fit_margin);
    } else if next_item_size > 0 {
        // penalize residual that cannot host next item, scaled by gap
        let gap = (next_item_size as f64 - pr) / cap;
        score += 18.0 * gap * gap;
    }

    // Last-chance bin: strong reward to use it before opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 35.0 * (1.0 + progress);
    }

    // New-bin candidate: penalize mildly, more so early when open bins exist
    if bin_residual == bin_capacity {
        let openness = open_bins_count as f64 / (open_bins_count as f64 + 3.0);
        score += 25.0 + 20.0 * openness * (1.0 - progress);
    }

    // Item size coupling: large items prefer very tight residuals
    let isz = item_size as f64 / cap;
    score += 10.0 * isz * norm_pr;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap_f = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Dead-space shaping: reward near-perfect fits, penalize small unusable gaps
    if post_residual == 0 {
        score -= 300.0;
    } else if post_residual <= 3 {
        score -= 120.0;
    } else if post_residual < 10 {
        score += 60.0;
    } else if post_residual < 20 {
        score += 18.0;
    } else if post_residual < 30 {
        score += 18.0 + (30 - post_residual) as f64 * 0.6;
    }

    // Lookahead: next item exactly fills the post residual
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 200.0;
        } else if next_item_size <= post_residual {
            let post2 = post_residual - next_item_size;
            score -= 30.0 + (post2 as f64).min(30.0);
            if post2 == 0 { score -= 60.0; }
            if post2 > 0 && post2 < 5 { score -= 20.0; }
            if post_residual % next_item_size == 0 { score -= 12.0; }
            if post_residual >= next_item_size * 2 { score -= 8.0; }
        } else {
            // next item won't fit here: penalize small dead residuals
            score += 15.0;
            if post_residual > 0 && post_residual < 15 { score += 30.0; }
            if post_residual > 0 && (next_item_size - post_residual) <= 5 {
                score += (6 - (next_item_size - post_residual)) as f64 * 4.0;
            }
        }
    }

    // Compactness pressure
    score += open_bins_count as f64 * 0.8;

    // Last-chance bin: strongly favor using it
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // Tightness preference
    score -= (item_size as f64 / cap_f) * 10.0;

    // NEW-BIN CANDIDATE logic
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let avg_fill = 1.0 - (mean_residual / cap_f);
        // base cost of a fresh bin; cheaper to open when existing bins are well filled
        score += 250.0 - avg_fill * 330.0 - progress * 65.0;
        // large items deserve a fresh bin rather than a bad squeeze
        if item_size >= bin_capacity * 3 / 4 { score -= 55.0; }
        if bin_capacity - item_size <= 4 { score -= 70.0; }
        // if next item fits in the leftover of a new bin, reward
        let leftover = bin_capacity - item_size;
        if next_item_size > 0 && leftover >= next_item_size {
            let tail = leftover % next_item_size;
            if tail == 0 { score -= 12.0; }
            else if tail <= 4 { score -= 8.0; }
        }
        if next_item_size > 0 && next_item_size >= bin_capacity / 2 { score -= 32.0; }
        // waste comparison against mean residual of open bins
        let newbin_waste = leftover as f64;
        if newbin_waste < mean_residual * 0.6 { score -= 30.0; }
        if fitting_bins_count > 0 {
            let best_alt = if item_size as f64 <= mean_residual { mean_residual - item_size as f64 } else { mean_residual };
            if newbin_waste > best_alt + cap_f * 0.08 { score += 22.0; }
            if newbin_waste > best_alt + cap_f * 0.2 { score += 14.0; }
        }
        if progress > 0.75 && newbin_waste > cap_f * 0.5 { score += 12.0; }
        if progress > 0.6 {
            let waste_tol = (1.0 - progress) * cap_f * 0.35;
            if newbin_waste > waste_tol && fitting_bins_count > 0 {
                score += 10.0 + progress * 22.0;
            }
        }
    } else {
        // Existing-bin branch: prefer bins whose residual is below mean (well used)
        let tightness = 1.0 - (item_size as f64 / bin_residual.max(1) as f64);
        score += tightness * 85.0;
        score += (mean_residual - bin_residual as f64) * 1.5;

        let dead_ratio = post_residual as f64 / cap_f;
        if dead_ratio < 0.03 { score -= 38.0; }
        else if dead_ratio < 0.08 { score -= 14.0; }
        else if dead_ratio > 0.35 { score += 24.0; }
        else if dead_ratio > 0.25 { score += 10.0; }

        // unusable gap ahead of next item is costly
        if post_residual > 0 && next_item_size > 0 && post_residual < next_item_size {
            let wasted = next_item_size as f64 - post_residual as f64;
            score += wasted * 0.6;
            if (next_item_size - post_residual) > 12 {
                score += dead_ratio * 90.0;
            }
        }
        // reusable residual for next item
        if post_residual > 0 && next_item_size > 0 && post_residual >= next_item_size {
            let reuse = (post_residual / next_item_size) as f64 * (next_item_size as f64 / cap_f);
            score -= reuse * 22.0;
        }
        if item_size == bin_residual { score -= 45.0; }
        if post_residual > 0 && post_residual % 10 == 0 { score -= 10.0; }
        if post_residual > 0 && (post_residual as f64) < mean_residual * 0.25 { score -= 15.0; }
        if fitting_bins_count <= 2 && post_residual > 0 { score -= 8.0; }

        // early stream: slight diversity bonus
        let progress = step_index as f64 / total_items.max(1) as f64;
        if progress < 0.1 { score += 3.0; }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: bins whose leftover falls into
    // "dead" classes (small, unusable slivers) are penalized; leftovers
    // that remain serviceable are rewarded.
    let cap = bin_capacity as f64;
    let post = post_residual as f64;

    // Class A: perfect fit -> strong reward.
    if post_residual == 0 {
        score -= 1000.0;
    } else {
        // Class B: leftover too small for the minimum item (1..=100 unknown,
        // but small leftovers are typically dead space) -> penalize.
        // Use harmonic classes via integer division thresholds on post_residual.
        let class = post_residual / 10; // 0..10 harmonic decile of leftover
        match class {
            0 => score += 60.0,           // 1..9  : near-dead sliver
            1 => score += 25.0,           // 10..19: awkward
            2 => score += 5.0,            // 20..29: marginal
            3 => score -= 5.0,            // 30..39: usable
            4 => score -= 10.0,           // 40..49: quite usable
            _ => score -= 15.0,           // 50+   : half-empty, very reusable
        }

        // Coupling: leftover should ideally accommodate the lookahead item.
        if next_item_size > 0 {
            if post_residual >= next_item_size {
                // Bonus scaled by how snugly the next item fits the leftover.
                let snug = 1.0 - ((post_residual - next_item_size) as f64 / cap);
                score -= 8.0 + 12.0 * snug;
            } else {
                // Leftover can't host next item: penalize proportionally to waste.
                score += (next_item_size - post_residual) as f64 * 0.3;
            }
        }

        // Last-chance bin: strongly favor using it before opening a new bin.
        if fitting_bins_count == 1 && bin_residual < bin_capacity {
            score -= 40.0;
        }

        // New-bin candidate (empty bin): only attractive when existing bins
        // would create dead space or when many bins are open but sparse.
        if bin_residual == bin_capacity {
            let waste_if_placed_elsewhere = mean_residual.max(0.0);
            let pressure = (open_bins_count as f64) * (step_index as f64 / total_items.max(1) as f64);
            // Prefer new bin only if the stream is early or mean residual is tiny.
            score += 30.0 + 0.5 * waste_if_placed_elsewhere - 20.0 * pressure.min(1.0);
        }

        // Mild preference for tighter bins overall (small residual before placement).
        score += (bin_residual as f64) * 0.05;

        // Late-stream consolidation: fewer open bins is better as stream ends.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += progress * (open_bins_count as f64) * 0.2;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: gaps too small for the smallest plausible
    // future item are pure waste; punish them super-linearly.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    } else if post_residual < 25 {
        score += 25.0 * (1.0 - post_residual as f64 / 25.0);
    }

    // Perfect / near-perfect fits get strong reward.
    if post_residual == 0 {
        score -= 80.0;
    } else if post_residual <= 5 {
        score -= 30.0;
    }

    // Reward bins whose residual was already fragmented (tight packing culture).
    let tightness = 1.0 - (bin_residual as f64 / bin_capacity as f64);
    score -= 15.0 * tightness * tightness;

    // Last-chance bin: strongly prefer using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // Open-bin pressure: when many bins are open, avoid opening new ones;
    // when few are open, a fresh bin is cheaper.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let pressure = (open_bins_count as f64).ln().max(0.0);
    if bin_residual == bin_capacity {
        // New-bin candidate: baseline near mean residual, penalized by pressure
        // and late-stream consolidation, slightly relaxed early on.
        score = mean_residual + 8.0 + pressure * 4.0 + progress * 6.0;
        if post_residual == 0 { score = 1e9; } // meaningless for empty bin
    }

    // Lookahead: if the next item fits exactly in the post-residual, big reward;
    // if post-residual is too small for next item but next item fits elsewhere, mild penalty.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 45.0;
        } else if next_item_size < post_residual {
            score -= 12.0 * (1.0 - (post_residual - next_item_size) as f64 / bin_capacity as f64);
        } else if post_residual > 0 && post_residual < next_item_size && post_residual < 10 {
