    // Last-chance bin: strongly favor using it instead of opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate: only attractive when existing bins are all nearly full
    // or the fit is terrible.
    if bin_residual == bin_capacity {
        let pressure = mean_residual / bin_capacity as f64;
        let poor_fit = (bin_residual - item_size) as f64 / bin_capacity as f64;
