pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let nxt = next_item_size as f64;
    let item = item_size as f64;

    // Base: prefer small post_residual (tight fit), with smooth non-linear emphasis
    let pr_norm = pr / cap;
    let mut score = pr_norm * (1.0 + 2.0 * pr_norm * (1.0 + progress));

    // Discrete tightness bonuses (borrowed idea: exact / near-exact fits dominate)
    if post_residual == 0 {
        score -= 900.0;
    } else if post_residual <= 3 {
        score -= 420.0;
    } else if post_residual <= 12 {
        score -= 90.0;
    } else if post_residual < 20 {
        score += 14.0;
    } else if post_residual < 30 {
        score += 14.0 + (30 - post_residual) as f64 * 0.6;
    }

