        let dead = (nxt - pr).max(0.0) / cap;
        score += 3.0 * dead * dead / (0.05 + progress * 0.5);
        let fits_next = (pr - nxt).max(0.0) / cap;
        score -= 0.8 * (1.0 - fits_next / (1.0 + fits_next));

        if next_item_size == post_residual {
            score -= 700.0;
        } else if next_item_size <= post_residual {
            let post2 = post_residual - next_item_size;
            score -= 110.0 - post2 as f64 * 2.0;
            if post2 == 0 {
                score -= 90.0;
            }
            if post2 > 0 && post2 < 5 {
                score -= 24.0;
            }
            if post2 >= 20 && post2 % 5 == 0 {
                score -= 10.0;
            }
            if post_residual % next_item_size == 0 {
                score -= 15.0;
            }
        } else {
            let gap = nxt - pr;
            score += 18.0;
            if gap <= 3.0 {
