    if bin_residual == bin_capacity {
        let avg_fill = 1.0 - (mean_residual / cap);
        score += 230.0 - avg_fill * 300.0 - progress * 60.0;

        if fitting_bins_count > 0 {
            score += (fitting_bins_count as f64).min(5.0) * 8.0;
            let snug = item / bin_residual.max(1) as f64;
            if snug > 0.9 { score += 35.0; }
            if snug > 0.95 { score += 25.0; }
            if snug > 0.98 { score += 15.0; }
        }

        // Large items prefer a fresh bin
        if item >= cap * 0.75 {
            score -= 50.0;
        }
        if cap - item_size <= 4 {
            score -= 60.0;
        }
        if next_item_size > 0 && nxt <= cap - item {
            score -= 22.0;
        }

        let newbin_waste = cap - item;
        if newbin_waste > 0.0 && newbin_waste < mean_residual * 0.6 {
            score -= 28.0;
        }
        if fitting_bins_count > 0 {
            let best_alt = if item_size as f64 <= mean_residual { mean_residual - item } else { mean_residual };
            if newbin_waste > best_alt + cap * 0.08 {
                score += 20.0;
            }
            if newbin_waste > best_alt + cap * 0.2 {
                score += 12.0;
            }
        }
