pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small leftovers are useless.
    if post_residual > 0 && post_residual < 10 {
        score += 200.0;
    } else if post_residual == 0 {
        // Perfect fit is highly rewarded.
        score -= 150.0;
    }

    // Reward tight fits relative to bin residual.
    score -= 0.5 * (item_size as f64 / bin_residual.max(1) as f64) * 100.0;

    // Lookahead: if next item fits exactly in post_residual, reward strongly.
    if next_item_size > 0 && next_item_size <= post_residual {
        score -= 40.0;
    }
    // If next item almost fits (small gap), mild penalty for blocking.
    if next_item_size > post_residual && next_item_size - post_residual < 10 && next_item_size > 0 {
        score += 30.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 120.0;
    }

    // Open-bins pressure: with many open bins, avoid opening new ones.
    if bin_residual == bin_capacity {
        // New-bin candidate: penalize more when few bins open, relax when many.
        score += 80.0 + 15.0 * open_bins_count as f64;
        // Late in the stream, opening new bins is cheaper than dead space.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score -= 60.0 * progress;
    }

    // Mean residual coupling: prefer bins whose residual is near the mean (balanced packing).
    score += 0.3 * ((bin_residual as f64 - mean_residual).abs());

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward perfect or near-perfect fits strongly (non-linear).
    let tightness = post_residual as f64 / bin_capacity as f64;
    score -= 40.0 * (-tightness * 12.0).exp();

    // 2-step lookahead: if the next item fits exactly into post_residual, big reward.
    if next_item_size > 0 && post_residual >= next_item_size {
        let chain_fit = (post_residual - next_item_size) as f64;
        score -= 25.0 * (-chain_fit * 0.08).exp();
    } else if next_item_size > 0 {
        // Penalize leaving residuals that block the next item.
        let gap = (next_item_size - post_residual) as f64;
        score += 6.0 * (-gap * 0.05).exp();
    }

    // Prefer bins with residuals close to the mean (avoid fragmenting outliers).
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += 0.15 * dev;

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 30.0;
    } else if fitting_bins_count > 1 {
        // Among many fitting bins, mild penalty to keep ordering by fit quality.
        score += 2.0 * (fitting_bins_count as f64).ln();
    }

    // Penalize opening a new bin when decent open bins exist, unless it's a good long-term split.
    if bin_residual == bin_capacity {
        let open_f = open_bins_count as f64;
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let mut new_bin_penalty = 18.0 - 10.0 * progress;
        if next_item_size > 0 && post_residual >= next_item_size {
            new_bin_penalty -= 12.0; // fresh bin supports the next item well
        }
        if open_f > 0.0 && mean_residual > item_size as f64 {
            new_bin_penalty += 4.0;
        }
        score += new_bin_penalty.max(-5.0);
    }

    // Slight preference for fuller bins overall.
    score -= 0.05 * (bin_capacity - bin_residual) as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Progress in stream (0..1)
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    // Reward tight fits: penalize waste proportionally, with a non-linear knee
    let waste_ratio = post_residual as f64 / bin_capacity as f64;
    score += 30.0 * waste_ratio * waste_ratio;

    // Lookahead: if next item fits exactly in post_residual, strongly reward this placement
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 25.0;
        } else if next_item_size <= post_residual {
            // leftover after chaining both items; smaller leftover is better
            let chained_left = (post_residual - next_item_size) as f64;
            score -= 12.0 * (1.0 - chained_left / bin_capacity as f64);
        } else {
            // next item cannot follow here: slight penalty if post_residual is a tiny dead space
            if post_residual > 0 && post_residual < 10 {
                score += 15.0;
            }
        }
    }

    // Last-chance bin: if this is the only bin that fits, heavily reward using it
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // New-bin candidate handling: opening a new bin is only attractive when
    // no good fit exists (item leaves large residual in all bins) or stream is early
    if bin_residual == bin_capacity {
        let open_penalty = 8.0 * (open_bins_count as f64).ln().max(1.0);
        score += open_penalty;
        // early stream: new bins are cheap-ish; late stream: avoid sprawl
        score -= 10.0 * (1.0 - progress);
        // if the item would leave a big unusable hole in existing bins, new bin looks better
        if post_residual <= 5 {
            score -= 18.0;
        }
        // lookahead: fresh bin can host the next item too
        if next_item_size > 0 && next_item_size + item_size <= bin_capacity {
            score -= 6.0;
        }
    }

    // Prefer bins whose residual is far below the mean residual (i.e. we are
    // consuming the emptiest bins first, keeping uniform bins flexible)
    let deviation = mean_residual - bin_residual as f64;
    score -= 0.15 * deviation;

    // Slight preference for keeping many open bins consolidating as stream ends
    score += 0.05 * progress * open_bins_count as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let progress = step_index as f64 / total_items.max(1) as f64;
    let norm_post = post_residual as f64 / bin_capacity as f64;
    let norm_item = item_size as f64 / bin_capacity as f64;

    // Smooth non-linear coupling: residual cost warped by stream progress
    score += 12.0 * norm_post * norm_post * (0.5 + progress) * (1.0 - norm_post);

    // Penalize creating dead space that cannot fit the next item (smooth gate)
    if next_item_size > 0 {
        let gap = (next_item_size as f64 - post_residual as f64).max(0.0) / bin_capacity as f64;
        score += 8.0 * gap * gap * (1.0 + progress);
        // Reward exact-ish fit for the lookahead item
        let fit_quality = 1.0 - (post_residual as f64 - next_item_size as f64).abs() / bin_capacity as f64;
        score -= 6.0 * fit_quality * fit_quality * (1.0 - progress);
    }

    // Last-chance bonus: strong smooth reward when this is the only fitting bin
    if fitting_bins_count == 1 {
        score -= 15.0 * (1.0 - norm_post) * (0.6 + 0.4 * progress);
    } else if fitting_bins_count > 1 {
        score += 3.0 * (fitting_bins_count as f64 - 1.0).ln().max(0.0) * norm_post;
    }

    // Mild pressure toward consolidation relative to mean residual
    score += 2.0 * (post_residual as f64 - mean_residual) / bin_capacity as f64 * (0.5 + progress);

    // New-bin candidate: penalize opening fresh bins unless residual is tiny
    if bin_residual == bin_capacity {
        let scarcity = (fitting_bins_count as f64).recip();
        score += 10.0 + 20.0 * (1.0 - norm_item) * (1.0 - progress) * scarcity;
    }

    score
}

