pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of post_residual via integer division thresholds.
    let cls = post_residual / 10; // 0..=10 harmonic band
    match cls {
        0 => { score -= 40.0; }            // perfect fit / near-zero waste
        1 => { score -= 12.0; }            // tiny dead space, still good
        2 | 3 => { score += 6.0; }         // awkward small gap
        4 | 5 => { score += 2.0; }         // half-full band, neutral
        _ => { score += 0.0; }             // large residual, room stays useful
    }

    // Lookahead coupling: does next_item_size fit into post_residual?
    if next_item_size > 0 {
        if (next_item_size as f64) <= post_residual as f64 {
            // Harmonic match: next item lands in same class bucket
            let pair = (post_residual / 10) == ((post_residual - next_item_size) / 10);
            if pair { score -= 15.0; } else { score -= 6.0; }
        } else {
            // Next item won't fit here; penalize leaving a gap that blocks it
            score += 8.0;
            if post_residual < next_item_size && post_residual >= 1 {
                score += (post_residual as f64) * 0.15;
            }
        }
    }

    // Last-chance bin: strongly prefer using the only fitting bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // Prefer tighter-than-average bins (best-fit flavor).
    score += (mean_residual - post_residual as f64) * 0.3;

    // New-bin candidate: make it mildly unattractive unless item is huge
    // relative to mean residual (opening fresh may be better then).
    if bin_residual == bin_capacity {
        score += 10.0;
        if (item_size as f64) > mean_residual + 0.5 * cap {
            score -= 30.0;
        }
        // Early stream: opening bins is cheaper; late stream: consolidate.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += (1.0 - progress) * 15.0 - 7.5;
    }

    // Slight penalty per open bin to discourage bin proliferation.
    score += open_bins_count as f64 * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Penalize "dead" residual: small unusable gaps (< 10) are worst.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    } else if post_residual < 25 {
        score += 12.0; // risky small gap
    } else if post_residual > 50 {
        score += 4.0; // large residual is somewhat wasted potential too
    }

    // Perfect fit bonus
    if post_residual == 0 {
        score -= 50.0;
    }

    // Last-chance pressure: if this is the only fitting bin, strongly favor using it
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // Open-bin pressure: with many open bins, prefer filling existing ones
    score += (open_bins_count as f64) * 2.0 * (1.0 - post_residual as f64 / bin_capacity as f64);

    // Lookahead: if next item fits exactly in the post residual, reward this placement
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= (next_item_size as f64) * 0.5;
    }
    // Penalize if next item cannot use the leftover gap (creates dead space)
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 8.0;
    }

    // Progression: early in stream, be slightly more willing to open new bins (score new bin better)
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity {
        score -= 15.0 * (1.0 - progress);
    }

    // Deviation from mean residual: prefer bins whose residual is near mean (balanced packing)
    score += (post_residual as f64 - mean_residual).abs() * 0.3;

