        score -= 15.0;
    } else if post_residual <= 20 {
        score -= 6.0;
    } else if post_residual > 60 {
        score += 10.0 * (post_residual as f64 / bin_capacity as f64);
    }

    // --- Mean residual coupling: prefer bins below mean residual (tighter bins) ---
    score += 0.25 * (post_residual as f64 - mean_residual);

    // --- Last-chance bin: strongly favor using the only fitting bin to avoid a new bin ---
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // --- New-bin candidate handling ---
    if bin_residual == bin_capacity {
        // Opening a new bin is only attractive when no open bin offers a good fit
        // (post_residual would equal capacity - item_size, i.e., large leftover)
        let fresh_post = bin_capacity - item_size;
        if next_item_size > 0 && fresh_post <= next_item_size {
            score -= 12.0; // fresh bin chains well with next item
        } else {
            score += 20.0 + 30.0 * progress; // late in stream, prefer existing bins
        }
        // If other bins can fit and are reasonably tight, discourage new bin
        if fitting_bins_count > 0 {
            score += 10.0;
        }
    }

    // --- Slight preference for filling more-open-bins states early ---
    score -= 0.5 * open_bins_count as f64 * (1.0 - progress);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit: strong reward
    if post_residual == 0 {
        score -= 60.0;
    } else {
        // Penalize tiny dead space (unusable slivers) superlinearly
        if post_residual < 10 {
            score += (10 - post_residual) as f64 * 4.0;
        }
        // Reward moderately tight fits relative to item size
        score -= (item_size as f64) * (post_residual as f64) / (bin_capacity as f64) * 0.5;
    }

    // Lookahead: penalize bins whose post_residual cannot host the next item
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 6.0 + (next_item_size as f64) * 0.15;
        } else if post_residual > 0 {
            score += 8.0;
        }
    } else {
        // Last item: pure tightness matters most
        score = post_residual as f64 * 1.5;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 12.0;
    }

    // New empty bin candidate: neutral-ish baseline, slightly worse than good fits
    if bin_residual == bin_capacity {
        score = 55.0 + 10.0 * (step_index as f64 / total_items.max(1) as f64);
        if next_item_size > 0 && item_size + next_item_size <= bin_capacity {
            score -= 4.0; // pairing next item is fine
        }
        if fitting_bins_count <= 1 {
            score -= 15.0; // no real alternative anyway
        }
    }

    // Global pressure: many open bins with low mean residual -> prefer consolidating
    if open_bins_count > 2 && mean_residual < (item_size as f64) * 1.5 {
        score += 3.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
