pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;

    // Base: post-residual with non-linear polynomial shaping
    let mut score = pr * (1.0 + 0.8 * norm_pr * norm_pr) - 12.0 * norm_pr * (1.0 - norm_pr);

    // Stream-progress coupling: later in stream, tighter packing preferred
    score *= 1.0 + 0.5 * progress * norm_pr;

    // Penalize dead space that cannot fit the lookahead item
    if next_item_size > 0 && (pr as u32) < next_item_size {
        score += (next_item_size as f64 - pr) * (0.3 + 0.7 * progress);
    }

    // Reward perfect fits
    if pr == 0 {
        score -= 25.0;
    }

    // Last-chance bonus: only bin that fits
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 15.0;
    }

    // New-bin candidate handling: discourage opening new bins unless residuals are fragmented
    if bin_residual == bin_capacity {
        score = pr + 10.0 + 20.0 * progress * (mean_residual / cap) - (fitting_bins_count as f64).min(3.0);
        if next_item_size > 0 && (bin_capacity as u32) >= next_item_size {
            score += 5.0;
        }
    }

    // Mild pressure toward consolidating among many open bins
    score += 0.15 * (open_bins_count as f64).ln().max(0.0) * norm_pr;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap_f = bin_capacity as f64;
    let progress = step_index as f64 / total_items.max(1) as f64;
    let mut score = post_residual as f64;

    // Tiered dead-space avoidance (strengthened, borrowed from best)
    if post_residual == 0 {
        score -= 900.0;
    } else if post_residual <= 3 {
        score -= 380.0;
    } else if post_residual <= 12 {
        score -= 60.0;
    } else if post_residual < 20 {
        score += 16.0;
    } else if post_residual < 30 {
        score += 10.0 + (30 - post_residual) as f64 * 0.5;
    }

    // Lookahead: exact and near-exact fits for the next item
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 650.0;
        } else if next_item_size <= post_residual {
            let post2 = post_residual - next_item_size;
            score -= 90.0 - (post2 as f64) * 1.6;
            if post2 == 0 { score -= 90.0; }
            if post2 > 0 && post2 < 5 { score -= 26.0; }
            if post2 % 10 == 0 && post2 > 0 { score -= 20.0; }
            if post2 > 0 && post2 <= next_item_size / 4 { score -= 12.0; }
            if post_residual % next_item_size == 0 { score -= 16.0; }
            if post_residual >= next_item_size * 2 && post_residual - next_item_size * 2 <= 4 {
                score -= 20.0;
            }
            let chain = post_residual / next_item_size;
            if chain >= 2 { score -= (chain.min(4)) as f64 * 6.0; }
        } else {
            let gap = next_item_size - post_residual;
            if post_residual > 0 {
                if gap <= 3 { score += 35.0; }
                else if gap <= 8 { score += 12.0; }
                if post_residual < 15 { score += 30.0; }
                if (gap as f64) > mean_residual * 0.5 { score += 12.0; }
                if gap <= 5 { score += (6 - gap) as f64 * 4.0; }
            }
        }
    }

    // Compaction pressure scaled by open bins
    score += open_bins_count as f64 * 0.8;

    // Last-chance bin: strongly favor using it
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 45.0;
    }

    // Tightness via relative fill
    let tightness = 1.0 - (item_size as f64 / bin_residual.max(1) as f64);
    score += tightness * 70.0;

    // NEW-BIN CANDIDATE handling
    if bin_residual == bin_capacity {
        let newbin_waste = (bin_capacity - item_size) as f64;
        let avg_fill = 1.0 - (mean_residual / cap_f);
        score += 200.0 - avg_fill * 250.0 - progress * 60.0;
        if item_size as f64 / cap_f > 0.75 { score -= 55.0; }
        if item_size as f64 > mean_residual { score -= 35.0; }
        if newbin_waste < mean_residual * 0.5 { score -= 30.0; }
        if next_item_size > 0 {
            let leftover = bin_capacity - item_size;
            if leftover >= next_item_size && leftover - next_item_size <= 6 { score -= 35.0; }
            if leftover >= next_item_size {
                let tail = leftover % next_item_size;
                if tail == 0 { score -= 14.0; }
                else if tail <= 4 { score -= 10.0; }
            } else if leftover < 10 { score += 18.0; }
        }
        if bin_capacity - item_size <= 4 { score -= 60.0; }
        if fitting_bins_count > 0 {
            score += (fitting_bins_count.min(5) as f64) * 9.0 + 15.0;
            let snug = item_size as f64 / bin_residual.max(1) as f64;
            if snug > 0.9 { score += 35.0; }
            if snug > 0.95 { score += 25.0; }
        }
        if fitting_bins_count > 3 && item_size as f64 / cap_f < 0.5 { score += 30.0; }
        if progress > 0.6 {
            let waste_tol = (1.0 - progress) * cap_f * 0.35;
            if newbin_waste > waste_tol && fitting_bins_count > 0 { score += 10.0 + progress * 22.0; }
        }
        if progress < 0.1 { score -= 5.0; }
    } else {
        // Consolidating slack: prefer bins whose residual is below average
        score += (mean_residual - bin_residual as f64) * 1.4;

        let dead_ratio = post_residual as f64 / cap_f;
        if dead_ratio < 0.03 { score -= 35.0; }
        else if dead_ratio < 0.08 { score -= 14.0; }
        else if dead_ratio > 0.35 { score += 24.0; }
        else if dead_ratio > 0.25 { score += 10.0; }

        if post_residual > 0 && next_item_size > 0 {
            let pr = post_residual;
            let ni = next_item_size as u32;
            if pr < ni {
                let wasted = (ni - pr) as f64;
                score += wasted * 0.6;
                if (ni - pr) > 12 { score += dead_ratio * 80.0; }
                score += (1.0 - progress) * 12.0;
            } else {
                let reuse = (pr / ni) as f64 * (next_item_size as f64 / cap_f);
                score -= reuse * 22.0;
                if pr <= ni + 4 { score -= 20.0; }
            }
        }
        if item_size == bin_residual { score -= 45.0; }
        if post_residual > 0 && post_residual < 6 { score -= 20.0; }
        if post_residual > 0 && post_residual % 10 == 0 { score -= 10.0; }
        if post_residual > 0 && (post_residual as f64) < mean_residual * 0.25 { score -= 15.0; }
        if fitting_bins_count <= 2 && post_residual > 0 { score -= 8.0; }
        if post_residual > 0 && next_item_size > 0 && post_residual + next_item_size as u32 <= bin_capacity
            && (post_residual as f64) < mean_residual * 0.5 { score -= 9.0; }
    }

    if progress < 0.1 && bin_residual < bin_capacity { score += 3.0; }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: dead space is worst when it falls into
    // "unfillable" residue classes modulo common small item sizes.
    let dead_classes: [u32; 8] = [1, 2, 3, 4, 5, 6, 7, 8];
    if post_residual > 0 {
        for d in dead_classes.iter() {
            if post_residual < *d * 10 {
                score += 12.0; // residue too small for any realistic item
                break;
            }
        }
    }

    // Reward near-perfect fits with a harmonic bonus.
    if post_residual == 0 {
        score -= 50.0;
    } else if post_residual <= 5 {
        score -= 20.0;
    }

    // Integer-division threshold: bins whose post_residual lands in a "good"
    // class (divisible by 10, i.e., likely reusable by decade-sized items).
    if post_residual % 10 == 0 && post_residual > 0 {
        score -= 8.0;
    }

    // Lookahead coupling: if the next item fits exactly into the post_residual,
    // strongly favor this bin (chain fit).
    if next_item_size > 0 && post_residual >= next_item_size {
        let gap = post_residual - next_item_size;
        if gap == 0 {
            score -= 30.0;
        } else if gap <= 10 {
            score -= 10.0;
        } else {
            score -= 4.0;
        }
    } else if next_item_size > 0 && post_residual < next_item_size && post_residual > 0 {
        // post_residual cannot host next item: mild penalty proportional to waste
        score += (next_item_size - post_residual) as f64 * 0.3;
    }

    // Last-chance bin: strongly prefer using it to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 15.0;
    } else if fitting_bins_count > 3 {
        score += 2.0; // many alternatives: be pickier
    }

    // New-bin candidate handling: empty bin gets a moderate baseline so it is
    // chosen only when existing bins would create heavy dead space.
    if bin_residual == bin_capacity {
        score = bin_capacity as f64 * 0.6 + mean_residual * 0.1;
        if next_item_size > 0 && item_size + next_item_size <= bin_capacity {
            score += 5.0; // pair fits fresh: slight bonus for new bin
        }
        if open_bins_count == 0 {
            score -= 100.0; // must open first bin
        }
    }

    // Progress-aware tightness: later in the stream, waste penalized more.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += post_residual as f64 * 0.2 * progress;

    // Penalize bins far below mean residual (fragmented outliers) mildly.
    if (bin_residual as f64) < mean_residual - 20.0 {
        score += 3.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps are heavily penalized.
    let dead_zone = 12.0; // gaps <= 12 are rarely usable (min item ~1..100, but small gaps waste capacity)
    if post_residual > 0 && (post_residual as f64) < dead_zone {
        score += (dead_zone - post_residual as f64) * 4.0;
    }
    if post_residual == 0 {
        // Perfect fit: strong reward.
        score -= 60.0;
    }

    // Reward bins whose residual closely matches the item (tight fit).
    let tightness = (bin_residual as f64 - item_size as f64).abs();
    score += tightness * 0.3;

    // Lookahead: if next item fits exactly in post_residual, reward strongly.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 45.0;
    }
    // Penalize if post_residual can't fit the (nonzero) next item but is small.
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size && post_residual < 20 {
        score += 15.0;
    }

    // Last-chance bonus: if this is the only fitting bin, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // Open-bin pressure: with many open bins, prefer filling existing ones.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += open_bins_count as f64 * (0.4 + 0.6 * progress);

    // New-bin candidate: make it attractive only when it's genuinely better,
    // i.e., penalize it moderately so it wins only for large items / poor fits.
    if bin_residual == bin_capacity {
        score += 30.0 + mean_residual * 0.5;
    }

    // Slight preference toward bins below mean residual (concentrate filling).
    if (bin_residual as f64) < mean_residual {
        score -= 5.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
