pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits (small post_residual) nonlinearly.
    let fit_ratio = item_size as f64 / bin_residual as f64;
    score -= 12.0 * fit_ratio * fit_ratio;

    // Penalize leaving dead space that cannot fit the smallest plausible item.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Last-chance bin: strong reward to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate handling: penalize opening a new bin unless the item
    // is large or the current fit is terrible.
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        score += 15.0;
        if fit_ratio > 0.75 {
            score -= 25.0; // large item: prefer fresh bin
        }
        if post_residual == 0 {
            score -= 40.0; // perfect fit in fresh bin
        }
    }

    // Lookahead coupling: if next item fits well in the post-residual, reward.
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            let lookahead_fit = next_item_size as f64 / post_residual as f64;
            score -= 8.0 * lookahead_fit;
        } else {
            score += 4.0; // dead space for the known next item
        }
    }

    // Global state: many open bins with high mean residual -> prefer filling
    // existing bins rather than spreading.
    if open_bins_count > 2 && mean_residual > item_size as f64 * 1.5 && !is_new_bin {
        score -= 6.0;
    }

    // Time horizon: early in the stream, be more exploratory (penalize new
    // bins less); late in the stream, consolidate aggressively.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    if progress > 0.7 {
        score -= 5.0 * (1.0 - fit_ratio); // prefer any reasonable fit late
    } else if progress < 0.2 && is_new_bin {
        score -= 5.0; // allow fresh bins early
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let t = step_index as f64 / total_items.max(1) as f64;
    let r = post_residual as f64;
    let c = bin_capacity as f64;
    let rn = r / c;

    // Non-linear polynomial coupling of post_residual with stream progress
    let mut score = rn * (1.0 + 2.0 * t * rn) * (1.0 + t * rn * rn);

    // Reward tight fits (small post_residual) more strongly later in the stream
    score -= (1.0 - rn).powi(3) * (1.0 + 3.0 * t);

    // Penalize dead space relative to mean residual across open bins
    score += 0.5 * (r - mean_residual).abs() / c;

    // Last-chance bin: strongly reward using it
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 5.0;
    }

    // Lookahead: reward residual that could accommodate next item
    if next_item_size > 0 {
        let nn = next_item_size as f64;
        if r >= nn {
            score -= 1.5 * (r / nn).ln().max(0.0);
        } else {
            score += 0.5 * (nn - r) / c;
        }
    }

    // Mild penalty for proliferating open bins early
    score += 0.05 * open_bins_count as f64 * (1.0 - t);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Reward tight fits: post_residual close to 0 is best.
    score -= 8.0 * (1.0 - post_residual as f64 / cap);

    // Harmonic class of post_residual: dead space that no future item
    // (sizes 1..=100) can ever fill exactly is penalized.
    let pr = post_residual;
    if pr > 0 {
        // Usable window: items up to 80 in original spec, 1..=100 here.
        // A residual of exactly 0 is perfect; small residuals (<10) are
        // nearly dead; residuals that match common item sizes are good.
        if pr < 10 {
            score += 6.0; // tiny unusable sliver
        }
        // Modulo-10 harmonic classes: residuals divisible by 10 align with
        // the classic size grid and are easier to fill later.
        if pr % 10 == 0 {
            score -= 3.0;
        } else if pr % 5 == 0 {
            score -= 1.5;
        } else {
            score += 1.0; // awkward non-aligned residual
        }
        // Integer-division thresholds: large residuals are flexible.
        if pr / 25 >= 1 {
            score -= 2.0 * (pr / 25) as f64;
        }
    }

    // Lookahead coupling: if the next item fits the post residual exactly,
    // this placement is part of a perfect chain — reward heavily.
    if next_item_size > 0 {
        if next_item_size == pr {
            score -= 12.0;
        } else if next_item_size <= pr {
            score -= 3.0;
            // harmonic pairing: next item leaves a class-aligned residual too
            let npr = pr - next_item_size;
            if npr % 10 == 0 {
                score -= 2.0;
            }
        } else {
            score += 2.0; // next item won't fit here anyway
        }
    }

    // Last-chance bin: if this is the only bin that fits, avoid opening a
    // new bin unless the fit is terrible.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 10.0;
    }

    // New-bin candidate: opening a new bin should only win when no open bin
    // gives a reasonable fit. Penalize it, scaled by how many bins fit.
    if bin_residual == bin_capacity {
        let pressure = (mean_residual / cap).clamp(0.0, 1.0);
        score += 14.0 + 6.0 * (1.0 - pressure);
        // Late in the stream, prefer consolidating into open bins.
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score += 4.0 * progress;
    } else {
        // Mild reward for using already-open bins to limit bin proliferation.
        score -= 1.0 + (open_bins_count as f64).ln().max(0.0);
    }

    // Prefer bins whose residual is below the mean (consolidate fuller bins).
    score += 0.05 * (bin_residual as f64 - mean_residual);

    // Small deterministic tie-break on residual alignment.
    score += 0.01 * ((pr as f64 * 0.6180339887) % 1.0);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap_f = bin_capacity as f64;
    let progress = step_index as f64 / total_items.max(1) as f64;
    let mut score = post_residual as f64;

    // Perfect / near-perfect fit rewards (borrowed from best heuristic)
    if post_residual == 0 {
        score -= 900.0;
    } else if post_residual <= 3 {
        score -= 350.0;
    } else if post_residual <= 12 {
        score -= 70.0;
    } else if post_residual < 20 {
        score += 18.0;
    } else if post_residual < 30 {
        score += 18.0 + (30 - post_residual) as f64 * 0.6;
    }

    // Lookahead: exact next-item fit is gold
    if next_item_size > 0 {
        if next_item_size == post_residual {
