            score += 22.0;
        }
    } else {
        let tightness = 1.0 - (item_size as f64 / bin_residual.max(1) as f64);
        score += tightness * 80.0;
        score += (mean_residual - bin_residual as f64) * 1.5;

        let dead_ratio = post as f64 / cap_f;
        if dead_ratio < 0.03 {
            score -= 35.0;
        } else if dead_ratio < 0.08 {
            score -= 12.0;
        } else if dead_ratio > 0.35 {
            score += 22.0;
        } else if dead_ratio > 0.25 {
            score += 9.0;
        }

        if next_item_size > 0 && post > 0 && post < next_item_size {
            let wasted = next_item_size as f64 - post as f64;
            score += wasted * 0.6;
            let progress = step_index as f64 / total_items.max(1) as f64;
            if next_item_size - post <= 2 {
                score += 10.0 * (1.0 - progress);
            }
        }
        if item_size == bin_residual {
            score -= 40.0;
        }
        if post > 0 && post < 6 {
            score -= 20.0;
        }
        if next_item_size > 0 && post >= next_item_size {
            let chain = post / next_item_size;
            if chain >= 2 {
                score -= (chain.min(4)) as f64 * 5.0;
            }
        }
