            score += 22.0;
        } else if dead_ratio > 0.25 {
            score += 9.0;
        }
        if item_size == bin_residual { score -= 40.0; }
        if post_residual > 0 && next_item_size > 0 && post_residual < next_item_size && (next_item_size - post_residual) <= 2 {
            score += 9.0 * (1.0 - progress);
        }
        if post_residual > 0 && pr < mean_residual * 0.25 { score -= 13.0; }
        if post_residual > 0 && pr > mean_residual * 1.6 && fitting_bins_count > 2 { score += 8.0; }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
