    score -= (item_size as f64 / bin_residual.max(1) as f64) * 30.0;

    // Consolidate slack: prefer bins below-average residual
    if bin_residual < bin_capacity {
        score += (mean_residual - bin_residual as f64) * 1.0;
        // dead-space ratio shaping
        let dead_ratio = post_residual as f64 / cap_f;
        if dead_ratio < 0.03 { score -= 30.0; }
        else if dead_ratio < 0.08 { score -= 12.0; }
        else if dead_ratio > 0.35 { score += 22.0; }
        else if dead_ratio > 0.25 { score += 10.0; }
        if item_size == bin_residual { score -= 45.0; }
        // unusable sliver for next item
        if post_residual > 0 && next_item_size > 0 && post_residual < next_item_size
            && (next_item_size - post_residual) > 12 {
            score += dead_ratio * 80.0;
        }
        if post_residual > 0 && post_residual < 6 { score -= 20.0; }
        if post_residual > 0 && post_residual % 10 == 0 { score -= 8.0; }
        if fitting_bins_count <= 2 && post_residual > 0 { score -= 8.0; }
    }

    // NEW-BIN CANDIDATE handling
    if bin_residual == bin_capacity {
        let newbin_waste = (bin_capacity - item_size) as f64;
        let avg_fill = 1.0 - (mean_residual / cap_f);
        score += 250.0 - avg_fill * 300.0 - progress * 65.0;
        if item_size as f64 / cap_f > 0.75 { score -= 55.0; }
        if item_size as f64 > mean_residual { score -= 40.0; }
        if newbin_waste < mean_residual * 0.5 { score -= 30.0; }
        if bin_capacity - item_size <= 4 { score -= 60.0; }
        // fresh bin pairs perfectly with next item
        if next_item_size > 0 {
            let leftover = bin_capacity - item_size;
            if leftover >= next_item_size {
                let tail = leftover % next_item_size;
                if tail == 0 { score -= 28.0; }
                else if tail <= 4 { score -= 16.0; }
                if leftover - next_item_size <= 6 { score -= 35.0; }
                if leftover >= next_item_size * 2 { score -= 14.0; }
            } else if leftover < 10 {
                score += 18.0;
            }
            if newbin_waste > 0.0 && (newbin_waste as u32) < next_item_size && newbin_waste < cap_f * 0.12 {
                score += 26.0;
            }
        }
        if fitting_bins_count > 0 {
            score += (fitting_bins_count.min(5) as f64) * 9.0 + 15.0;
            let snug = item_size as f64 / bin_residual.max(1) as f64;
            if snug > 0.9 { score += 35.0; }
            if snug > 0.95 { score += 25.0; }
        }
        if fitting_bins_count > 3 && item_size as f64 / cap_f < 0.5 { score += 30.0; }
        if progress > 0.6 {
            let waste_tol = (1.0 - progress) * cap_f * 0.35;
            if newbin_waste > waste_tol && fitting_bins_count > 0 {
                score += 10.0 + progress * 22.0;
            }
        }
        if progress < 0.1 { score -= 5.0; }
    } else if progress < 0.1 {
        score += 3.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap_f = bin_capacity as f64;
    let progress = step_index as f64 / total_items.max(1) as f64;
    let mut score = post_residual as f64;

    // Tiered dead-space shaping (combined from parent + best)
    if post_residual == 0 {
        score -= 900.0; // perfect fit dominates
    } else if post_residual <= 3 {
        score -= 420.0;
    } else if post_residual <= 12 {
        score -= 80.0;
    } else if post_residual < 20 {
        score += 18.0;
    } else if post_residual < 30 {
        score += 18.0 + (30 - post_residual) as f64 * 0.6;
    }

    let next_f = next_item_size as f64;
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 750.0; // next item exactly fills residual
        } else if next_item_size <= post_residual {
            let post2 = post_residual - next_item_size;
            score -= 120.0 - post2 as f64 * 2.0;
            if post2 == 0 { score -= 90.0; }
            if post2 > 0 && post2 < 5 { score -= 26.0; }
            if post2 % 10 == 0 && post2 > 0 { score -= 24.0; }
            if post2 >= 20 && post2 % 5 == 0 { score -= 10.0; }
            if post_residual >= next_item_size * 2 && post_residual - next_item_size * 2 <= 4 {
                score -= 18.0;
            }
            if post_residual % next_item_size == 0 { score -= 14.0; }
            let chain = post_residual / next_item_size;
            if chain >= 2 { score -= (chain.min(4)) as f64 * 6.0; }
        } else {
            // next item won't fit here: penalize near-miss gaps
            let gap = next_item_size - post_residual;
            if post_residual > 0 {
                if gap <= 3 { score += 40.0; }
                else if gap <= 8 { score += 14.0; }
                if gap as f64 > mean_residual * 0.5 { score += 12.0; }
                if post_residual < 15 { score += 30.0; }
                if post_residual as f64 > mean_residual * 1.4 { score -= 10.0; }
            }
        }
        if post_residual > 0 && post_residual < next_item_size {
            let wasted = next_f - post_residual as f64;
            score += wasted * 0.6;
            score += (1.0 - progress) * 12.0;
        }
    }

    // Compaction pressure
    score += open_bins_count as f64 * 0.8;

    // Last-chance bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 40.0;
    }

    if bin_residual == bin_capacity {
        // NEW-BIN CANDIDATE
        let leftover = bin_capacity - item_size;
        let newbin_waste = leftover as f64;
        let avg_fill = 1.0 - (mean_residual / cap_f);
        score += 250.0 - avg_fill * 330.0 - progress * 65.0;

        if item_size >= bin_capacity * 3 / 4 { score -= 55.0; }
        if bin_capacity - item_size <= 4 { score -= 70.0; }
        if item_size as f64 > mean_residual { score -= 40.0; }
        if item_size as f64 / cap_f > 0.85 && mean_residual > cap_f * 0.35 { score -= 35.0; }

        if fitting_bins_count > 0 {
            score += (fitting_bins_count.min(5) as f64) * 9.0 + 20.0;
            let snug = item_size as f64 / bin_residual.max(1) as f64;
            if snug > 0.9 { score += 40.0; }
            if snug > 0.95 { score += 25.0; }
            if snug > 0.98 { score += 18.0; }
        }
        if next_item_size > 0 && next_item_size >= bin_capacity / 2 { score -= 30.0; }
        if next_item_size > 0 && next_item_size <= leftover { score -= 25.0; }

        if next_item_size > 0 {
            if leftover >= next_item_size {
                let tail = leftover % next_item_size;
                if tail == 0 { score -= 18.0; }
                else if tail <= 4 { score -= 14.0; }
                if leftover >= next_item_size * 2 { score -= 12.0; }
            } else if leftover < 10 {
                score += 18.0;
            }
            if leftover >= next_item_size && leftover - next_item_size <= 6 { score -= 35.0; }
        }

        if newbin_waste > 0.0 && newbin_waste < mean_residual * 0.6 { score -= 28.0; }
        if fitting_bins_count > 0 {
            let best_alt = if item_size as f64 <= mean_residual { mean_residual - item_size as f64 } else { mean_residual };
            if newbin_waste > best_alt + cap_f * 0.08 { score += 22.0; }
            if newbin_waste > best_alt + cap_f * 0.2 { score += 14.0; }
        }
        if progress > 0.6 {
            let waste_tol = (1.0 - progress) * cap_f * 0.35;
            if newbin_waste > waste_tol && fitting_bins_count > 0 {
                score += 10.0 + progress * 22.0;
            }
        }
        if newbin_waste > 0.0 && leftover < next_item_size && newbin_waste < cap_f * 0.12 {
            score += 24.0;
        }
        if next_item_size > 0 && newbin_waste >= next_f && leftover as f64 % next_f == 0.0 {
            score -= 18.0;
        }
        if progress < 0.1 { score -= 5.0; }
    } else {
        // OPEN-BIN candidate: dead-ratio and slack consolidation
        let tightness = 1.0 - (item_size as f64 / bin_residual.max(1) as f64);
        score += tightness * 85.0;
        score += (mean_residual - bin_residual as f64) * 1.5;

        let dead_ratio = post_residual as f64 / cap_f;
        if dead_ratio < 0.03 { score -= 38.0; }
        else if dead_ratio < 0.08 { score -= 14.0; }
        else if dead_ratio > 0.35 { score += 24.0; }
        else if dead_ratio > 0.25 { score += 10.0; }
        score += dead_ratio * 30.0;

        if item_size == bin_residual { score -= 45.0; }
        if post_residual > 0 && post_residual < 6 { score -= 20.0; }
        if post_residual > 0 && (post_residual as f64) < mean_residual * 0.25 { score -= 15.0; }
        if post_residual > 0 && post_residual % 5 == 0 && post_residual <= 30 { score -= 8.0; }

        if next_item_size > 0 && post_residual > 0 {
            let unusable = post_residual < next_item_size && (next_item_size - post_residual) > 12;
            if unusable {
                score += dead_ratio * 90.0;
            } else {
                let reuse = (post_residual / next_item_size) as f64 * (next_f / cap_f);
                score -= reuse * 22.0;
            }
            if post_residual >= next_item_size && (post_residual % next_item_size) <= 2 { score -= 8.0; }
            let gap = (next_f - post_residual as f64) / next_f.max(1.0);
            if gap > 0.0 && gap < 0.12 { score -= 10.0; }
        }
        if fitting_bins_count <= 2 && post_residual > 0 { score -= 8.0; }
        if post_residual > 0 && (post_residual as f64) > mean_residual * 1.6 && fitting_bins_count > 2 {
            score += 10.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals that are too small to ever be
    // usable (below the minimum plausible item size) are pure waste.
    let dead_zone = 10.0f64;
    if (post_residual as f64) < dead_zone {
        score += 40.0; // unusable gap -> heavy penalty
    } else if post_residual == 0 {
        score -= 60.0; // perfect closure: best possible outcome
    } else {
        // Reward small-but-usable residuals super-linearly (tight fit).
        let pr = post_residual as f64;
        score -= (bin_capacity as f64 - pr).max(0.0) * 0.15;
    }

    // Tightness bonus: fraction of the bin consumed by this item.
    let fill = item_size as f64 / bin_capacity as f64;
    score -= fill * 25.0;

    // Open-bin pressure: with many open bins, prefer consolidating into
    // existing bins; when few bins are open, spreading is cheaper.
    let pressure = (open_bins_count as f64).ln() + 1.0;
    score += pressure * 6.0;

    // Last-chance bin: if this is the only bin that fits, using it avoids
    // opening a new bin -> strong reward.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // Lookahead coupling: if the next item fits the post-residual exactly,
    // this placement sets up a perfect follow-up.
    if next_item_size > 0 && (post_residual as f64) >= next_item_size as f64 {
        if post_residual == next_item_size {
            score -= 20.0;
        } else if (post_residual as f64) < next_item_size as f64 + 10.0 {
            score -= 8.0;
        }
    }
    // If next item would leave the post-residual dead, mild penalty.
    if next_item_size > 0 && (post_residual as f64) < next_item_size as f64 && post_residual > 0 {
        score += 5.0;
    }

    // Mean-residual coupling: placing into a bin far below the mean residual
    // keeps the fleet balanced; penalize draining already-small bins.
    let dev = mean_residual - post_residual as f64;
    score += dev * 0.3;

    // New-bin candidate handling: an empty bin has residual == capacity.
    // Open a new bin only when existing fits are poor (large dead space) or
    // the item is large enough to dominate a fresh bin.
    if bin_residual == bin_capacity {
        let waste_if_open = post_residual as f64;
        if waste_if_open > 45.0 || fitting_bins_count == 0 {
            score -= 35.0; // fresh bin is attractive for big items / no alternatives
        } else {
            score += 20.0; // discourage needless bin proliferation
        }
    }

    // Late-stream tightening: as the stream progresses, favor closing bins.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= progress * 10.0 * (1.0 - fill);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
