pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward near-perfect fills strongly.
    if post_residual == 0 {
        score -= 1000.0;
    } else if post_residual <= 2 {
        score -= 400.0;
    }

    // Aggressive 2-step lookahead: reward bins whose post_residual exactly
    // matches the next item size (perfect chained packing).
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 600.0;
        } else if post_residual > next_item_size {
            // Next item fits too: penalize leftover gap proportional to slack.
            let gap = (post_residual - next_item_size) as f64;
            score -= 150.0 - gap.min(150.0);
        } else {
            // Next item does NOT fit this bin afterwards: penalize dead space
            // especially if it is small-but-unusable relative to the lookahead.
            let dead = (next_item_size - post_residual) as f64;
            score += dead * 2.0;
        }
    }

    // Compare post_residual against mean residual across open bins:
    // leaving less than average residual is good (denser bin).
    let pr = post_residual as f64;
    if pr < mean_residual {
        score -= (mean_residual - pr) * 0.5;
    } else {
        score += (pr - mean_residual) * 0.3;
    }

    // Last-chance bin: strongly favor using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 250.0;
    }

    // Penalize opening a new bin when a decent fit exists elsewhere,
    // unless current bin residual is very fragmented.
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        // New bin only attractive if no open bin achieves a tight fit.
        if post_residual <= 10 {
            score -= 500.0; // fresh bin for tiny item is fine (tight start)
        } else {
            score += 300.0 + open_bins_count as f64 * 5.0;
        }
    }

    // Mild progression term: later in stream, prefer tighter packing.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += progress * 20.0;

    score
}

