pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits strongly.
    let tightness = 1.0 - (post_residual as f64) / (bin_capacity as f64);
    score -= 3.0 * tightness * tightness;

    // Penalize dead space relative to mean residual: if this bin's post residual
    // is much larger than the mean residual of open bins, it's wasted capacity.
    score += 0.5 * ((post_residual as f64) - mean_residual).max(0.0);

    // Lookahead: penalize if the next item cannot fit in the post residual
    // (creates fragmentation for the immediate future).
    if next_item_size > 0 {
        if post_residual < next_item_size {
            score += 2.0 * (next_item_size as f64 - post_residual as f64);
        } else {
            // Reward leaving room for the next item.
            score -= 1.0 * (1.0 - (post_residual - next_item_size) as f64 / bin_capacity as f64);
        }
    }

    // Last-chance bin: strongly favor using the only bin that fits.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 10.0;
    }

    // New-bin candidate: penalize opening a new bin, more so when good fits exist
    // or late in the stream; but relax penalty early when many bins are open
    // (spreading load can help future items).
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let mut new_bin_penalty = 8.0 + 6.0 * progress;
        // If next item is large and this bin would stay nearly empty, soften penalty.
        if next_item_size >= item_size.saturating_mul(2).min(bin_capacity) {
            new_bin_penalty -= 2.0;
        }
        score += new_bin_penalty;
    }

    // Slight preference for bins with larger residual among equals (consolidate waste).
    score -= 0.05 * (bin_residual as f64 / bin_capacity as f64);

    // Mild scaling with open bins count to discourage bin proliferation.
    score += 0.02 * open_bins_count as f64;

    score
}

