        score += 18.0 + (30 - post_residual) as f64 * 0.6;
    }

    // Lookahead anticipation
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 650.0;
        } else if next_item_size <= post_residual {
            let post2 = post_residual - next_item_size;
            score -= 100.0 - (post2 as f64) * 1.8;
            if post2 == 0 { score -= 90.0; }
            if post2 > 0 && post2 < 5 { score -= 25.0; }
            if post2 % 10 == 0 && post2 > 0 { score -= 20.0; }
            if post2 <= next_item_size / 4 { score -= 10.0; }
            if post_residual >= next_item_size * 2 && post_residual - next_item_size * 2 <= 4 {
                score -= 20.0;
            }
            let chain = post_residual / next_item_size;
            if chain >= 2 { score -= (chain.min(4)) as f64 * 6.0; }
            if post_residual % next_item_size == 0 { score -= 14.0; }
        } else {
            let gap = next_item_size - post_residual;
            if post_residual > 0 {
                if gap <= 3 { score += 35.0; }
                else if gap <= 8 { score += 12.0; }
                if (gap as f64) > mean_residual * 0.5 { score += 12.0; }
                if post_residual < 15 { score += 30.0; }
            }
        }
    }

    // Compaction pressure
    score += open_bins_count as f64 * 0.8;

    // Last-chance bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 45.0;
    }

    // Tightness
    score -= (item_size as f64 / bin_residual.max(1) as f64) * 30.0;

    // NEW-BIN CANDIDATE handling
    if bin_residual == bin_capacity {
        let newbin_waste = (bin_capacity - item_size) as f64;
        let avg_fill = 1.0 - (mean_residual / cap_f);
        score += 220.0 - avg_fill * 200.0 - progress * 60.0;
        if item_size as f64 / cap_f > 0.75 { score -= 55.0; }
        if item_size as f64 > mean_residual { score -= 30.0; }
        if newbin_waste < mean_residual * 0.5 { score -= 30.0; }
        if bin_capacity - item_size <= 4 { score -= 60.0; }
        if next_item_size > 0 && (bin_capacity - item_size) >= next_item_size
            && (bin_capacity - item_size) - next_item_size <= 6 {
            score -= 35.0;
        }
        if fitting_bins_count > 0 {
            score += (fitting_bins_count.min(6) as f64) * 8.0;
            let snug = item_size as f64 / bin_residual.max(1) as f64;
            if snug > 0.9 { score += 35.0; }
            if snug > 0.95 { score += 20.0; }
        }
        if newbin_waste > 0.0 && (newbin_waste as u32) < next_item_size && newbin_waste < cap_f * 0.12 {
            score += 25.0;
        }
        if next_item_size > 0 {
            let leftover = bin_capacity - item_size;
            if leftover >= next_item_size {
                let tail = leftover % next_item_size;
                if tail <= 4 { score -= 16.0; }
                if tail == 0 { score -= 10.0; }
            }
        }
        if progress < 0.1 { score -= 5.0; }
    } else {
        // Dead-space ratio shaping for open bins
        let dead_ratio = post_residual as f64 / cap_f;
        if dead_ratio < 0.03 { score -= 30.0; }
        else if dead_ratio < 0.08 { score -= 12.0; }
        else if dead_ratio > 0.35 { score += 22.0; }
        else if dead_ratio > 0.25 { score += 10.0; }

        // Unusable-gap penalty vs next item
        if post_residual > 0 && next_item_size > 0 && post_residual < next_item_size {
            let wasted = next_item_size as f64 - post_residual as f64;
            if wasted > 12.0 {
                score += wasted * 0.7 + dead_ratio * 60.0;
            } else {
                score += wasted * 0.5;
            }
        }

        // Consolidate slack: prefer below-average residuals
        score += (mean_residual - bin_residual as f64) * 1.2;

        if item_size == bin_residual { score -= 40.0; }
        if post_residual > 0 && post_residual < 6 { score -= 18.0; }
        if post_residual > 0 && (post_residual as f64) < mean_residual * 0.25 { score -= 12.0; }
        if post_residual > 0 && post_residual % 5 == 0 && post_residual <= 30 { score -= 8.0; }
    }

    // Early-stream diversity nudge
    if progress < 0.1 && bin_residual != bin_capacity { score += 3.0; }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let norm_pr = pr / cap;

    // Base: leftover space, weighted by a smooth progress-dependent polynomial
    let progress_weight = 1.0 + 0.8 * progress * progress - 0.4 * progress;
    let mut score = pr * progress_weight;

    // Non-linear coupling: penalize small-but-nonzero residuals quadratically
    // (dead space), but reward near-zero residuals strongly.
    let tightness = (norm_pr - 0.15) * (norm_pr - 0.15);
    score += 40.0 * tightness * (1.0 - progress * 0.5);

    // Smooth reward for exact-ish fits near zero residual
    score -= 25.0 * (1.0 - norm_pr).powi(6);

    // Lookahead coupling: if next item fits smoothly into post_residual, reward
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        let fit_gap = pr - nx;
        if fit_gap >= 0.0 {
            let g = fit_gap / cap;
            score -= 15.0 * (1.0 - g).powi(3) * (1.0 - progress);
        } else {
            let g = (-fit_gap) / cap;
            score += 10.0 * g * (0.5 + progress);
        }
    }

    // Last-chance bin: strongly prefer using it to avoid opening new bins
    if fitting_bins_count == 1 {
        score -= 30.0 * (1.0 - 0.5 * progress);
    }

    // Mild penalty for spreading across many open bins relative to mean residual
    score += 0.05 * open_bins_count as f64 * (norm_pr - mean_residual / cap).abs();

    // New-bin candidate: keep it moderately attractive only when existing bins
    // would leave very poor fits (large dead space)
    if bin_residual == bin_capacity {
        let poor_fit = (norm_pr - 0.2).max(0.0);
        score = pr + 12.0 - 20.0 * poor_fit * (1.0 - progress);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: dead-space classes modulo small divisors.
    // Residuals divisible by 10 (harmonic with capacity 100) are "reusable" classes.
    let harmonic = (post_residual % 10 == 0) as f64;
    let semi_harmonic = (post_residual % 5 == 0) as f64;
    score -= harmonic * 12.0;
    score -= semi_harmonic * 4.0;

    // Odd/prime-ish residuals (mod 2, mod 3 non-zero) create fragmented classes.
    if post_residual % 2 == 1 {
        score += 3.0;
    }
    if post_residual % 3 != 0 {
        score += 1.5;
    }

    // Integer-division thresholds: residual buckets relative to capacity.
    let quarter = bin_capacity / 4;
    let half = bin_capacity / 2;
    if post_residual < quarter {
        score += 10.0; // tiny dead space class
    } else if post_residual < half {
        score -= 2.0;  // sweet spot: fits medium future items
    }

    // Lookahead coupling: does the next item fit the post residual?
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            // Harmonic match: next item lands exactly in this bin's class
            let gap = (post_residual - next_item_size) as f64;
            score -= 15.0 - gap.min(15.0); // reward tight two-step packing
            if (post_residual - next_item_size) % 10 == 0 {
                score -= 5.0; // chain of harmonic residuals
            }
        } else {
            score += 4.0; // next item won't reuse this bin
        }
    } else {
        // Last item: prefer filling as tightly as possible
        score -= 20.0;
    }

    // Last-chance bin: if this is the only bin that fits, strongly prefer using it.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate: opening a fresh bin is only good if no open bin fits well.
    if bin_residual == bin_capacity {
        let pressure = if fitting_bins_count == 0 { 0.0 } else { 30.0 };
        score += pressure;
        // Early in stream, allow more open bins; later, consolidate.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += (1.0 - progress) * 10.0;
    }

    // Prefer bins whose residual is far from the mean (balance class distribution).
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += dev * 0.05;

    // Slight preference for fewer open bins.
    score += open_bins_count as f64 * 0.2;

    // Exact fill is ideal.
    if post_residual == 0 {
        score -= 50.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Dead-space penalty: residuals too small for the smallest plausible item (<= ~10)
    // are essentially wasted; penalize them quadratically.
    if post_residual < 10 {
        score += (10 - post_residual) as f64 * 25.0;
    } else if post_residual < 25 {
        // "Awkward zone": gap too small for most mid-size items.
        score += (25 - post_residual) as f64 * 6.0;
    }

    // Reward tight fits (near-zero post_residual) strongly.
    if post_residual == 0 {
        score -= 60.0;
    } else if post_residual <= 5 {
        score -= 30.0;
    }

    // Perfect fill of the bin is ideal.
    if post_residual == 0 && bin_residual == item_size {
        score -= 20.0;
    }

    // Open-bin pressure: penalize spreading across many bins, encouraging
    // consolidation into existing bins rather than opening new ones.
    score += open_bins_count as f64 * 1.5;

    // Last-chance bonus: if this is the only bin that can fit the item,
    // strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 80.0;
    }

    // New-bin candidate handling: only attractive when item fits poorly
    // everywhere else (large item, small mean residual headroom).
    if bin_residual == bin_capacity {
        score += 120.0; // base cost of opening a new bin
        if item_size >= 60 {
            score -= 40.0; // large items justify a fresh bin more readily
        }
        if fitting_bins_count == 0 {
            score -= 150.0; // nothing else fits: must open a new bin
        }
        // Lookahead: if next item is large, a fresh bin is more useful.
        if next_item_size >= 50 {
            score -= 15.0;
        }
    }

    // Lookahead synergy: if this bin's post_residual exactly matches the next
    // item size, reward the chaining effect.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 25.0;
    } else if next_item_size > 0 && post_residual >= next_item_size && post_residual < next_item_size + 10 {
        score -= 10.0;
    }

    // Early in the stream, be slightly more willing to open bins (build options);
    // late in the stream, consolidate aggressively.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += (1.0 - progress) * 5.0;

    // Mild tie-break toward bins with lower mean residual (already crowded bins).
    score += mean_residual * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap_f = bin_capacity as f64;
    let mut score = post_residual as f64;

    let quarter = bin_capacity / 4;
    let half = bin_capacity / 2;
    let post = post_residual;

    // Residual class with strong exact/small-fit rewards (borrowed from best).
    if post == 0 {
        score -= 1000.0;
    } else if post <= 3 {
        score -= 400.0;
    } else if post < quarter {
        score += 30.0;
        if next_item_size > post {
            score += 20.0;
        }
    } else if post < half {
        score += 5.0;
    } else {
        score -= 10.0;
    }

    // Divisibility bonuses.
    if post % 10 == 0 && post > 0 {
        score -= 8.0;
    }
    if post % 20 == 0 && post > 0 {
        score -= 4.0;
    }

    // Lookahead coupling, strengthened for snug chains.
    if next_item_size > 0 {
        if next_item_size == post {
            score -= 500.0;
        } else if next_item_size <= post {
            let slack = post - next_item_size;
            if slack < quarter {
                score -= 15.0;
            } else {
                score -= 3.0;
            }
            if post % next_item_size == 0 {
                score -= 18.0;
            }
            if slack > 0 && slack <= 4 {
                score -= 22.0;
            }
        } else {
            score += 10.0;
            if post > 0 && (next_item_size - post) <= 3 {
                score += 30.0;
            }
        }
    }

    // Last-chance bonus: only fitting bin.
    if fitting_bins_count == 1 {
        score -= 30.0;
    }

    // New-bin candidate: baseline high enough that it only wins on bad fits,
    // with progress- and waste-aware modulation (borrowed from best).
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let avg_fill = 1.0 - (mean_residual / cap_f);
        score += 220.0 - avg_fill * 300.0 - progress * 60.0;

        let newbin_waste = (bin_capacity - item_size) as f64;
        if item_size as f64 > mean_residual {
            score -= 40.0;
        }
        if newbin_waste > 0.0 && newbin_waste < mean_residual * 0.6 {
            score -= 25.0;
        }
        if fitting_bins_count > 0 {
            let snug = item_size as f64 / (bin_residual.max(1) as f64);
            if snug > 0.9 {
                score += 35.0;
            }
            if newbin_waste > mean_residual + cap_f * 0.15 {
                score += 20.0;
            }
        }
        if next_item_size > 0 {
            let leftover = bin_capacity - item_size;
            if leftover >= next_item_size {
                let tail = leftover % next_item_size;
                if tail == 0 {
                    score -= 18.0;
                } else if tail <= 4 {
                    score -= 12.0;
                }
            }
            if leftover < next_item_size && leftover < 10 {
                score += 18.0;
            }
        }
        if item_size >= bin_capacity * 3 / 4 {
            score -= 50.0;
        }
        if newbin_waste > 0.0 && (newbin_waste as u32) < next_item_size && newbin_waste < cap_f * 0.12 {
            score += 24.0;
        }
        if progress > 0.7 {
            let waste_tol = (1.0 - progress) * cap_f * 0.35;
            if newbin_waste > waste_tol && fitting_bins_count > 0 {
                score += 10.0 + progress * 20.0;
            }
        }
    } else {
        // Tightness preference: prefer filling fuller bins.
        let tightness = 1.0 - (item_size as f64 / bin_residual.max(1) as f64);
        score += tightness * 70.0;
        score += (mean_residual - bin_residual as f64) * 1.5;

        let dead_ratio = post as f64 / cap_f;
        if dead_ratio < 0.03 {
            score -= 35.0;
        } else if dead_ratio < 0.08 {
            score -= 12.0;
        } else if dead_ratio > 0.35 {
            score += 22.0;
        }

        if item_size == bin_residual {
            score -= 45.0;
        }
        if post > 0 && post < 6 {
            score -= 20.0;
        }
        if post > 0 && next_item_size > 0 && post < next_item_size {
            let gap = next_item_size as f64 - post as f64;
            score += gap * 0.6;
            if gap <= 2.0 {
                score += 8.0;
            }
        }
        if fitting_bins_count <= 2 && post > 0 {
            score -= 8.0;
        }
        if post > 0 && next_item_size > 0 && post >= next_item_size {
            let chain = post / next_item_size;
            if chain >= 2 {
                score -= (chain.min(4)) as f64 * 6.0;
            }
        }
    }

    // Mild penalty for many open bins with poor mean residual.
    if mean_residual > cap_f * 0.6 && open_bins_count > 3 {
        score += 3.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect 2-step match: post_residual exactly equals next item size -> strong reward.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 45.0;
    }
    // Near-match: next item fits tightly into post residual (small leftover after next item).
    else if next_item_size > 0 && next_item_size <= post_residual {
        let leftover = (post_residual - next_item_size) as f64;
        score -= 30.0 * (1.0 - leftover / bin_capacity as f64);
    } else if next_item_size > 0 {
        // Next item won't fit here: penalize proportionally to wasted potential.
        let gap = (next_item_size - post_residual) as f64;
        score += 0.35 * gap;
    }

    // Penalize post_residuals that are awkward (small but nonzero dead space).
    if post_residual > 0 && post_residual < 10 {
        score += 12.0;
    }

    // Favor bins whose residual deviates below the mean (already committed bins).
    score -= (mean_residual - post_residual as f64) * 0.15;

    // Last-chance bin: strongly reward using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // Mild penalty for opening new bins when few bins are open relative to stream length.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 8.0 + 10.0 * (1.0 - progress);
    }

    // Slight preference for tighter fits overall.
    score += (item_size as f64 / bin_capacity as f64) * 2.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Lookahead: strongly reward placements whose residual can host the next item.
    if next_item_size > 0 && post_residual >= next_item_size {
        let pair_waste = (post_residual - next_item_size) as f64;
        score -= 60.0 + 0.5 * next_item_size as f64 - 0.3 * pair_waste;
    } else if next_item_size > 0 {
        // Penalize blocking the next item into this bin's leftover.
        score += 10.0 + 0.2 * (next_item_size as f64 - post_residual as f64);
    }

    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 50.0;
    } else {
        // Penalize small dead space that is hard to reuse (relative to typical item sizes).
        let frac = post_residual as f64 / bin_capacity as f64;
        if frac < 0.10 {
            score += 15.0;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 25.0;
    }

    // Many fitting bins -> prefer the tightest; add mild pressure scaled by competition.
    if fitting_bins_count > 1 {
        score += 2.0 * (fitting_bins_count as f64 - 1.0);
    }

    // Time horizon: early on, prefer compact packing; late, be more open to new bins.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score -= 8.0 * progress * (mean_residual / bin_capacity as f64);

    // Global state: when many open bins with large mean residual, discourage spreading.
    if open_bins_count > 3 && mean_residual > item_size as f64 {
        score += 0.05 * open_bins_count as f64;
    }

    // New-bin candidate: only attractive if current bin would leave awkward residual.
    if bin_residual == bin_capacity {
        let awkward = post_residual as f64 > 0.0 && (next_item_size as f64 > post_residual as f64);
        if awkward {
            score -= 20.0; // fresh bin may pair better with next item
        } else {
            score += 30.0; // prefer existing bins otherwise
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;

    // Non-linear polynomial coupling of post_residual with stream progress
    let mut score = pr * (1.0 + 0.8 * progress) + 40.0 * norm_pr * norm_pr * (0.5 + progress);

    // Reward tight fits (small post_residual) more strongly as stream progresses
    score -= 60.0 * (1.0 - norm_pr) * (1.0 - norm_pr) * (0.3 + 0.7 * progress);

    // Penalize dead space that cannot fit the next item
    if next_item_size > 0 && post_residual > 0 {
        let waste = (next_item_size as f64 - pr).max(0.0) / cap;
        score += 90.0 * waste * (1.0 + progress);
    } else if next_item_size == 0 {
        // Last item: strongly prefer filling existing bins completely
        score -= 100.0 * (1.0 - norm_pr);
    }

    // Last-chance bin bonus: avoid opening a new bin when this is the only fit
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 50.0 * (1.0 - 0.5 * progress);
    }

    // New-bin candidate: mildly discourage opening new bins early, allow later
    if bin_residual == bin_capacity {
        score += 30.0 * (1.0 - progress) - 10.0 * progress;
    }

    // Penalize bins far from mean residual (fragmentation signal)
    let dev = (pr - mean_residual).abs() / cap;
    score += 15.0 * dev * dev;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap_f = bin_capacity as f64;
    let progress = step_index as f64 / total_items.max(1) as f64;
    let mut score = post_residual as f64;

    // Perfect and near-perfect fits
    if post_residual == 0 {
        score -= 900.0;
    } else if post_residual <= 3 {
        score -= 420.0;
    } else if post_residual <= 12 {
        score -= 80.0;
    } else if post_residual < 20 {
        score += 15.0;
    }

    // Lookahead on next item
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 700.0;
        } else if next_item_size <= post_residual {
            let post2 = post_residual - next_item_size;
            score -= 110.0 - post2 as f64 * 1.5;
            if post2 == 0 {
