        }
    }

    // NEW-BIN CANDIDATE handling
    if bin_residual == bin_capacity {
        let avg_fill = 1.0 - (mean_residual / cap_f);
        score += 230.0 - avg_fill * 300.0 - progress * 55.0;
        if fitting_bins_count > 0 {
            score += (fitting_bins_count.min(6)) as f64 * 8.0 + 18.0;
            let snug = item_size as f64 / bin_residual.max(1) as f64;
            if snug > 0.9 {
                score += 35.0;
            }
            if snug > 0.95 {
                score += 25.0;
            }
        }
        if item_size >= bin_capacity * 3 / 4 {
            score -= 50.0;
        }
        if next_item_size > 0 && next_item_size <= bin_capacity - item_size {
            score -= 22.0;
        }
        let newbin_waste = (bin_capacity - item_size) as f64;
        if newbin_waste > 0.0 && newbin_waste < mean_residual * 0.6 {
            score -= 28.0;
        }
        if progress > 0.6 {
            let waste_tol = (1.0 - progress) * cap_f * 0.35;
            if newbin_waste > waste_tol && fitting_bins_count > 0 {
                score += 10.0 + progress * 20.0;
            }
        }
        if newbin_waste > 0.0 && (newbin_waste as u32) < next_item_size && newbin_waste < cap_f * 0.12 {
            score += 24.0;
        }
        if next_item_size > 0 && newbin_waste >= next_item_size as f64 * 2.0 {
            score -= 12.0;
        }
    } else {
        // Existing bin: prefer tight fits
        let tightness = 1.0 - (item_size as f64 / bin_residual.max(1) as f64);
        score += tightness * 70.0;
        score += (mean_residual - bin_residual as f64) * 1.4;

        let dead_ratio = post_residual as f64 / cap_f;
        if dead_ratio < 0.03 {
            score -= 35.0;
        } else if dead_ratio < 0.08 {
            score -= 12.0;
        } else if dead_ratio > 0.35 {
            score += 22.0;
        } else if dead_ratio > 0.25 {
            score += 9.0;
        }

        if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
            let wasted = next_item_size as f64 - post_residual as f64;
            score += wasted * 0.6;
            score += (1.0 - progress) * 12.0;
        }
        if next_item_size > 0 && post_residual >= next_item_size {
            let chain = post_residual / next_item_size;
            if chain >= 2 {
                score -= (chain.min(4)) as f64 * 5.0;
            }
        }
        if item_size == bin_residual {
            score -= 40.0;
        }
        if post_residual > 0 && post_residual % 10 == 0 {
            score -= 8.0;
        }
        if bin_residual as f64 > cap_f * 0.6 {
            score -= 10.0;
        }
        if post_residual > 0 && post_residual < 6 {
            score -= 20.0;
        }
        if post_residual > 0 && (post_residual as f64) < mean_residual * 0.25 {
            score -= 12.0;
        }
        // unusable dead space vs next item
        if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size && (next_item_size - post_residual) > 12 {
            score += dead_ratio * 80.0;
        }
        if fitting_bins_count <= 2 && post_residual > 0 {
            score -= 7.0;
        }
        if fitting_bins_count == 1 && bin_residual < bin_capacity {
            score -= 22.0;
        }
    }

    // Pressure from number of open bins
    score += open_bins_count as f64 * 0.6;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual modulo common divisor classes (capacity C=100)
    let cap = bin_capacity as f64;
    let pr = post_residual as u32;

    // Class 1: post_residual in {0} is perfect fit -> strong reward
    if pr == 0 {
        score -= 1000.0;
    }

    // Class 2: harmonic classes by integer division of post_residual into capacity tenths
    let tenth = (pr * 10) / bin_capacity; // 0..10 class
    match tenth {
        0 => score -= 50.0,                       // near-perfect fill
        1 => score += 30.0,                       // awkward tiny dead space (1..10)
        2 => score += 20.0,                       // 10..20 dead zone (min item is 1..100 range)
        3 => score -= 10.0,                       // 20..30 can host small items
        4 | 5 => score -= 15.0,                   // 30..50 flexible band
        6 => score += 5.0,
        7 | 8 => score -= 20.0,                   // 70..90 good future capacity
        _ => score -= 25.0,                       // 90..100 nearly fresh
    }

    // Class 3: modulo-5 residue classes of post_residual (divisibility harmony)
    let m5 = pr % 5;
    if m5 == 0 {
        score -= 8.0; // divisible residuals pair well with rounded item sizes
    } else {
        score += m5 as f64 * 2.0;
    }

    // Class 4: lookahead harmonic compatibility: does next_item_size divide into post_residual classes?
    if next_item_size > 0 {
        let ni = next_item_size;
        if ni <= pr {
            // next item fits here: reward, stronger if it nearly fills
            let fill = ni as f64 / pr.max(1) as f64;
            score -= 40.0 * fill;
            // harmonic bonus when next item exactly matches a residual class (pr % ni == 0)
            if pr % ni == 0 {
                score -= 25.0;
            }
        } else {
            // next item cannot use this residual: penalize large residuals we cannot chain
            score += 15.0;
            // extra penalty if residual falls in the unusable band relative to next item
            if pr > 0 && pr < ni {
                score += (ni - pr) as f64 * 0.8;
            }
        }
    }

    // Class 5: capacity fraction coupling of item to residual (tightness)
    let tightness = item_size as f64 / bin_residual.max(1) as f64;
    score -= 60.0 * tightness * tightness;

    // Class 6: last-chance bin logic
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 35.0;
    }

    // New-bin candidate handling: only prefer fresh bin early or when current fit is terrible
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let fresh_bonus = 40.0 * (1.0 - progress) + 10.0;
        score -= fresh_bonus;
        if post_residual as f64 > mean_residual + 20.0 {
            score -= 15.0;
        }
    }

    // Mild open-bin pressure: discourage scattering when many bins open
    score += open_bins_count as f64 * 0.5;

    // Mean residual alignment: prefer bins whose residual is near mean (balanced packing)
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += dev * 0.3;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small gaps (< 10, the classic min item size)
    // are unusable dead space -> heavy penalty. Larger useful gaps get mild penalty.
    if post_residual > 0 && post_residual < 10 {
        score += 40.0;
    } else if post_residual < 20 {
        score += 12.0;
    }

    // Reward tight fits (exact fill is perfect).
    if post_residual == 0 {
        score -= 30.0;
    } else {
        let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
        score -= 8.0 * tightness * tightness;
    }

    // Lookahead: if next item fits exactly into the post residual, strong reward.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 25.0;
        } else if next_item_size <= post_residual {
            score -= 6.0;
        } else {
            // next item won't fit: residual likely becomes dead space
            score += 4.0;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // Open-bin pressure: with many open bins, discourage spreading; prefer filling.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += 0.35 * open_bins_count as f64 * (0.5 + 0.5 * progress);

    // Prefer bins below mean residual (fill emptier bins first when spreading is needed,
    // but this mild term keeps balance).
    score += 0.05 * (mean_residual - bin_residual as f64);

    // New-bin candidate: penalize moderately so it is chosen only when fits are bad,
    // but make it more attractive late in the stream when consolidation pays off.
    if bin_residual == bin_capacity {
        score += 15.0 - 10.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap_f = bin_capacity as f64;
    let mut score = post_residual as f64;
    let progress = step_index as f64 / total_items.max(1) as f64;
    let post = post_residual;
    let next = next_item_size;

    // Perfect / near-perfect fits: strongly reward.
    if post == 0 {
        score -= 1000.0;
    } else if post <= 3 {
        score -= 400.0;
    } else if post <= 12 {
        score -= 80.0;
    } else if post < 20 {
        score += 16.0;
    } else if post < 30 {
        score += 16.0 + (30 - post) as f64 * 0.6;
    } else {
        // Large residual class: good leftover.
        score -= 8.0;
    }

    // Dead-space ratio shaping.
    let dead_ratio = post as f64 / cap_f;
    if post > 0 {
        if dead_ratio < 0.03 { score -= 30.0; }
        else if dead_ratio < 0.08 { score -= 10.0; }
        else if dead_ratio > 0.35 { score += 22.0; }
        else if dead_ratio > 0.25 { score += 8.0; }
    }

    // Divisibility bonuses.
    if post > 0 && post % 10 == 0 { score -= 8.0; }
    if post > 0 && post % 20 == 0 { score -= 4.0; }
    if post > 0 && post % 5 == 0 && post <= 30 { score -= 6.0; }

    // Lookahead coupling with next item.
    if next > 0 {
        if next == post {
            score -= 700.0;
        } else if next <= post {
            let post2 = post - next;
            score -= 100.0 - post2 as f64 * 2.0;
            if post2 == 0 { score -= 80.0; }
            if post2 > 0 && post2 < 5 { score -= 22.0; }
            if post2 >= 20 && post2 % 5 == 0 { score -= 10.0; }
            if post % next == 0 { score -= 14.0; }
            if post >= next * 2 && post - next * 2 <= 4 { score -= 16.0; }
            let chain = post / next;
            if chain >= 2 { score -= (chain.min(4)) as f64 * 5.0; }
        } else {
            score += 16.0;
            let gap = next - post;
            if gap <= 3 { score += 28.0; }
            else if gap <= 8 { score += 10.0; }
            if post < 15 { score += 35.0; }
            if post as f64 > mean_residual * 1.4 { score -= 10.0; }
            if post as f64 > mean_residual * 1.3 { score += 6.0; }
            let wasted = gap as f64;
            if post > 0 { score += wasted * 0.5; }
        }
        // Snug-gap fine tuning.
        if post > 0 && post >= next {
            if post % next <= 2 { score -= 8.0; }
        }
        if post > 0 && post < next {
            let gap = (next - post) as f64 / next.max(1) as f64;
            if gap < 0.12 { score -= 8.0; }
            score += (1.0 - progress) * 12.0;
        }
    }

    // Only fitting bin: keep it alive.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    } else if fitting_bins_count == 2 && bin_residual != bin_capacity {
        score -= 6.0;
    }

    // New-bin candidate evaluation.
    if bin_residual == bin_capacity {
        let avg_fill = 1.0 - mean_residual / cap_f;
        score += 220.0 - avg_fill * 300.0 - progress * 60.0;
        let newbin_waste = (bin_capacity - item_size) as f64;
        if item_size as f64 > mean_residual { score -= 40.0; }
        if bin_capacity - item_size <= 4 { score -= 60.0; }
        if item_size >= bin_capacity * 3 / 4 { score -= 45.0; }
        if next > 0 && next >= bin_capacity / 2 { score -= 30.0; }
        if next > 0 && next <= bin_capacity - item_size { score -= 22.0; }
        if fitting_bins_count > 0 {
            score += (fitting_bins_count.min(5) as f64) * 8.0 + 18.0;
            let snug = item_size as f64 / bin_residual.max(1) as f64;
            if snug > 0.9 { score += 35.0; }
            if snug > 0.95 { score += 25.0; }
            if snug > 0.98 { score += 15.0; }
        }
        if next > 0 {
            let leftover = bin_capacity - item_size;
            if leftover >= next {
                let tail = leftover % next;
                if tail <= 4 { score -= 14.0; }
                if tail == 0 { score -= 10.0; }
                if leftover >= next * 2 { score -= 12.0; }
            } else if leftover < 10 {
                score += 16.0;
            }
        }
        if newbin_waste > 0.0 && newbin_waste < mean_residual * 0.6 { score -= 26.0; }
        if newbin_waste > 0.0 && (newbin_waste as u32) < next && newbin_waste < cap_f * 0.12 { score += 22.0; }
        if progress > 0.6 && fitting_bins_count > 0 {
            let waste_tol = (1.0 - progress) * cap_f * 0.35;
            if newbin_waste > waste_tol { score += 10.0 + progress * 20.0; }
        }
        if progress > 0.75 && newbin_waste > cap_f * 0.5 { score += 10.0; }
        if next > 0 && newbin_waste > 0.0 && (newbin_waste as u32) % next == 0 && newbin_waste >= next as f64 { score -= 18.0; }
    } else {
        // Existing bin: tightness and mean-residual deviation shaping.
        let tightness = 1.0 - item_size as f64 / bin_residual.max(1) as f64;
        score += tightness * 70.0;
        score += (mean_residual - bin_residual as f64) * 1.2;
        if item_size == bin_residual { score -= 40.0; }
        if bin_residual as f64 > cap_f * 0.6 { score -= 10.0; }
        if post > 0 && (post as f64) < mean_residual * 0.25 { score -= 12.0; }
        if post > 0 && (post as f64) < cap_f * 0.015 { score -= 16.0; }
        if post > 0 && (post as f64) > mean_residual * 1.6 && fitting_bins_count > 2 { score += 8.0; }
        if post > 0 && next > 0 && post < next && (next - post) > 12 {
            score += dead_ratio * 80.0;
        }
        if post > 0 && next > 0 && post >= next {
            let dev = (post as f64 - mean_residual).abs();
            if dev < cap_f * 0.03 { score -= 8.0; }
        }
    }

    // Mild penalty for too many open bins with poor mean residual.
    if mean_residual > cap_f * 0.6 && open_bins_count > 3 { score += 3.0; }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Perfect fit bonus: strong reward for leaving zero or tiny residual.
    if post_residual == 0 {
        score -= 1000.0;
    } else if post_residual <= 5 {
        score -= 200.0;
    }

    // Aggressive 2-step lookahead: reward if next item fits into post_residual exactly.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        let pr = post_residual as f64;
        if nxt == pr {
            score -= 800.0;
        } else if nxt < pr {
            // next item fits: reward proportionally to how tight the pair-fit is
            let tightness = 1.0 - (pr - nxt) / cap;
            score -= 300.0 * tightness * (nxt / cap);
        } else {
            // next item does NOT fit here: penalize more if post_residual is a large dead zone
            let waste = (pr - nxt).min(pr);
            score += 0.5 * waste * (1.0 - pr / cap);
        }
    }

    // Compare residual against mean residual across open bins.
    if mean_residual > 0.0 {
        let rel = post_residual as f64 / mean_residual;
        // Prefer bins with residual below the mean (tighter bins) mildly
        score += 20.0 * (rel - 1.0);
    }

    // Last-chance bin: if this is the only bin that fits, strongly prefer using it
    // over opening a new bin, unless the fit is terrible.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        let fit_ratio = item_size as f64 / bin_residual as f64;
        if fit_ratio > 0.5 {
            score -= 400.0 * fit_ratio;
        }
    }

    // New-bin candidate handling: penalize opening a new bin, more so early in the
    // stream and when many open bins exist; allow it if item is large relative to cap.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let new_bin_penalty = 350.0 + 200.0 * (1.0 - progress) + 15.0 * open_bins_count as f64;
        score += new_bin_penalty;
        // Large items make new bins more acceptable
        score -= 2.0 * item_size as f64;
        // If next item is large too, a fresh bin is actually good (keeps small bins free)
        if next_item_size > 50 {
            score -= 150.0;
        }
    }

    // Mild preference to fill existing bins more fully
    score -= 0.3 * item_size as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let score = post_residual as f64;
    score
