pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let mut score = post;

    // Tight-fit reward: strongly favor bins where the item fills most of the residual.
    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 12.0 * fit_ratio * fit_ratio;

    // Penalize large dead space left behind (unusable chunks).
    if post > 0.0 && post < 10.0 {
        score -= 6.0; // near-perfect fill bonus
    } else if post > 0.0 {
        // small residuals (<10) can't fit typical items; larger leftovers are more reusable
        score += 0.05 * post;
    }

    // Lookahead: reward bins whose leftover can host the next item exactly.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 20.0;
        } else if post_residual > next_item_size {
            score -= 3.0 * (1.0 - (post_residual - next_item_size) as f64 / cap);
        } else {
            // leftover too small for next item: mild penalty proportional to waste
            score += 0.02 * post;
        }
    }

    // Last-chance bin: if this is the only bin that fits, strongly prefer using it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate logic: opening a new bin is justified when existing bins
    // would leave bad fits and the stream is still early/middle (future items
    // can fill a fresh bin).
    if bin_residual == bin_capacity {
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        let horizon = 1.0 - progress;
        // Base cost of a new bin, discounted by remaining stream length.
        score += 30.0 + 40.0 * horizon;
        // If many bins are open with slack, discourage yet another bin.
        score += 1.5 * open_bins_count as f64;
        // If mean residual is large, prefer reusing open bins.
        score += 0.3 * mean_residual;
        // But if the next item is huge, a fresh bin may pair well later: slight relief.
        if next_item_size >= 70 {
            score -= 8.0;
        }
    }

    // Mild preference to consolidate into fewer bins when many are open.
    score += 0.02 * open_bins_count as f64;

    // Time-dependent exploration: early in the stream, be slightly more willing
    // to spread items (keeps residual flexibility); late, pack tightly.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score -= 4.0 * (1.0 - progress) * fit_ratio;
    score += 3.0 * progress * (post / cap);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    // Base: waste after placement, mildly damped by smooth power
    let mut score = pr.powf(1.35);

    // Reward tight fits: quadratic coupling of item size with capacity
    score -= (item_size as f64 / cap) * (item_size as f64 / cap) * 12.0;

    // Penalize leaving residual that no plausible item can use:
    // smooth interaction between post_residual and next item size
    let nx = next_item_size as f64;
    if nx > 0.0 {
        let gap = (pr - nx).abs();
        // if next item fits exactly-ish, big reward
        let fit_quality = 1.0 - (gap / cap).min(1.0);
        score -= fit_quality * fit_quality * 8.0 * (nx / cap);
        // penalize residual too small for next item (dead space risk)
        let dead = ((nx - pr) / cap).max(0.0);
        score += dead * dead * 10.0;
    }

    // Last-chance bonus: if this is the only fitting bin, strongly favor using it
    if fitting_bins_count <= 1 && bin_residual < bin_capacity {
        score -= 15.0 * (1.0 - progress * 0.5);
    }

    // Stream progress coupling: later in stream, be more aggressive about
    // consolidating (prefer fuller bins), smooth polynomial in progress
    let fill_ratio = 1.0 - pr / cap;
    score -= progress * fill_ratio * fill_ratio * 10.0;

    // Mild penalty if this bin's residual deviates from mean residual
    // (encourage uniform packing states)
    let dev = (pr as f64 - mean_residual) / cap;
    score += dev * dev * 3.0;

    // New-bin candidate: make it unattractive unless residuals are all terrible
    if bin_residual == bin_capacity {
        let open_penalty = (open_bins_count as f64).ln().max(0.0);
        score = cap * (1.0 - progress) + open_penalty * 5.0 + pr;
        // allow new bin late in stream when open bins are fragmented
        let fragmentation = (mean_residual - pr).abs() / cap;
        score -= progress * fragmentation * 20.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let is_new_bin = bin_residual == bin_capacity;
    let mut score = post;

    // ---- Tight-fit rewards (harmonic small classes) ----
    if post_residual == 0 {
        score -= 60.0; // perfect fit
    } else if post_residual <= 5 {
        score -= 40.0;
    } else if post_residual <= 10 {
        score -= 25.0;
    } else if post_residual <= 20 {
        score -= 10.0;
    }

    // ---- Harmonic class logic via integer division on post_residual ----
    let class = post_residual / 10; // residual decade class
    // Larger classes waste more space: quadratic penalty on class index
    score += (class as f64) * (class as f64) * 0.8;
    // Awkward sub-class: residual not a multiple of 10 leaves unusable slivers
    let rem = post_residual % 10;
    if rem != 0 {
        score += 3.0 + (rem as f64) * 0.3;
    }
    // Class 3 (residual 30..39) is a "sweet spot" for mid-size items
    if class == 3 {
        score -= 8.0;
    }

    // ---- Lookahead coupling (k=2) ----
    if next_item_size > 0 {
        if (next_item_size as f64) <= post {
            // this bin remains useful for the next item: reward
            score -= 6.0 + (next_item_size as f64) * 0.05;
        } else if post_residual > 0 {
            // dead space: next item cannot use it
            score += 5.0 + (post - next_item_size as f64).abs() * 0.1;
        }
    }

    // ---- Last-chance bonus: only this bin fits the item ----
    if fitting_bins_count == 1 && !is_new_bin {
        score -= 35.0;
    }

    // ---- New-bin candidate arbitration ----
    if is_new_bin {
        // Opening a new bin costs roughly one full empty slot; make it
        // attractive only when existing fits are scarce or poor.
        let reuse_pressure = fitting_bins_count as f64;
        score += 12.0 + reuse_pressure * 6.0;
        // A fresh bin is naturally good for large items (small post_residual)
        if post_residual <= 25 {
            score -= 15.0;
        }
        // Early in stream, opening bins is cheaper (future flexibility)
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score -= (1.0 - progress) * 10.0;
    } else {
        // Reusing open bins keeps bin count down; mild global reward
        score -= 4.0;
        // Prefer bins with residual near the mean (balanced packing)
        score += (post - mean_residual).abs() * 0.15;
        // Many open bins: encourage consolidation into emptier bins
        if open_bins_count > 8 {
            score -= 3.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap_f = bin_capacity as f64;
    let progress = step_index as f64 / total_items.max(1) as f64;
    let mut score = post_residual as f64;

    // Perfect / near-perfect fit rewards (borrowed from best heuristic)
    if post_residual == 0 {
        score -= 1180.0;
    } else if post_residual <= 3 {
        score -= 500.0;
    } else if post_residual <= 12 {
        score -= 98.0;
    } else if post_residual < 20 {
        score += 18.0;
    } else if post_residual < 30 {
        score += 18.0 + (30 - post_residual) as f64 * 0.6;
    }

    // Lookahead: exact next-item match is highly valuable
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 900.0;
        } else if next_item_size <= post_residual {
            let post2 = post_residual - next_item_size;
            score -= 135.0 - (post2 as f64) * 2.0;
            if post2 == 0 {
                score -= 110.0;
            }
            if post2 > 0 && post2 < 5 {
                score -= 28.0;
            }
            if post2 >= 20 && post2 % 5 == 0 {
                score -= 12.0;
            }
            if post_residual % next_item_size == 0 {
                score -= 18.0;
            }
        } else {
            // next item won't fit here: penalize small dead residuals
            score += 20.0;
            if post_residual > 0 && post_residual < 15 {
                score += 45.0;
            }
            if post_residual > 0 && (next_item_size - post_residual) <= 3 {
                score += 35.0;
            }
            if post_residual as f64 > mean_residual * 1.4 {
                score -= 12.0;
            }
        }
    }

    // NEW-BIN CANDIDATE handling
    if bin_residual == bin_capacity {
        let avg_fill = 1.0 - (mean_residual / cap_f);
        score += 250.0 - avg_fill * 330.0 - progress * 65.0;
        if item_size as f64 > mean_residual {
            score -= 45.0;
        }
        if fitting_bins_count > 0 {
            score += (fitting_bins_count as f64).min(5.0) * 9.0 + 20.0;
            let snug = item_size as f64 / (bin_residual.max(1) as f64);
            if snug > 0.9 { score += 40.0; }
            if snug > 0.95 { score += 28.0; }
            if snug > 0.98 { score += 18.0; }
        }
        if next_item_size > 0 && next_item_size >= bin_capacity / 2 {
            score -= 32.0;
        }
        if item_size >= bin_capacity * 3 / 4 {
            score -= 55.0;
        }
        if next_item_size > 0 && next_item_size <= bin_capacity - item_size {
            score -= 25.0;
        }
        if bin_capacity - item_size <= 4 {
            score -= 70.0;
        }
        // new-bin waste analysis
        let newbin_waste = (bin_capacity - item_size) as f64;
        if newbin_waste > 0.0 && newbin_waste < mean_residual * 0.6 {
            score -= 30.0;
        }
        if fitting_bins_count > 0 {
            let best_alt = if item_size as f64 <= mean_residual { mean_residual - item_size as f64 } else { mean_residual };
            if newbin_waste > best_alt + cap_f * 0.08 {
                score += 22.0;
            }
            if newbin_waste > best_alt + cap_f * 0.2 {
                score += 14.0;
            }
        }
        if progress > 0.6 {
            let waste_tol = (1.0 - progress) * cap_f * 0.35;
            if newbin_waste > waste_tol && fitting_bins_count > 0 {
                score += 10.0 + progress * 22.0;
            }
        }
        if newbin_waste > 0.0 && (newbin_waste as u32) < next_item_size && newbin_waste < cap_f * 0.12 {
            score += 26.0;
        }
        if next_item_size > 0 && newbin_waste >= next_item_size as f64 && (newbin_waste as u32) % next_item_size == 0 {
            score -= 20.0;
        }
    } else {
        // Existing-bin branch: tightness and dead-space control
        let tightness = 1.0 - (item_size as f64 / bin_residual.max(1) as f64);
        score += tightness * 85.0;
        score += (mean_residual - bin_residual as f64) * 1.5;

        let dead_ratio = post_residual as f64 / cap_f;
        if dead_ratio < 0.03 {
            score -= 38.0;
        } else if dead_ratio < 0.08 {
            score -= 14.0;
        } else if dead_ratio > 0.35 {
            score += 24.0;
        } else if dead_ratio > 0.25 {
            score += 10.0;
        }

        if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
            let wasted = next_item_size as f64 - post_residual as f64;
            score += wasted * 0.6;
        }
        if item_size == bin_residual {
            score -= 45.0;
        }
        if post_residual > 0 && post_residual < 6 {
            score -= 22.0;
        }
        if post_residual > 0 && post_residual % 5 == 0 && post_residual <= 30 {
            score -= 8.0;
        }
        if next_item_size > 0 && post_residual >= next_item_size {
            let chain = post_residual / next_item_size;
            if chain >= 2 {
                score -= (chain.min(4)) as f64 * 6.0;
            }
            if post_residual <= next_item_size + 4 {
                score -= 22.0;
            }
        }
        if next_item_size > 0 && post_residual > 0 {
            let dead_frac = post_residual as f64 / cap_f;
            let unusable = post_residual < next_item_size && (next_item_size - post_residual) > 12;
            if unusable {
                score += dead_frac * 90.0;
            } else {
                let reuse = (post_residual / next_item_size) as f64 * (next_item_size as f64 / cap_f);
                score -= reuse * 22.0;
            }
        }
        if fitting_bins_count == 1 && bin_residual < bin_capacity {
            score -= 25.0;
        }
        if fitting_bins_count <= 2 && post_residual > 0 {
            score -= 8.0;
        }
    }

    // Compaction pressure
    score += open_bins_count as f64 * 0.8;
    score -= (item_size as f64 / cap_f) * 10.0;

    if progress < 0.1 {
        score += 3.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap_f = bin_capacity as f64;
    let progress = step_index as f64 / total_items.max(1) as f64;
    let mut score = post_residual as f64;

    // Strong rewards for perfect / near-perfect fits
    if post_residual == 0 {
        score -= 900.0;
    } else if post_residual <= 3 {
        score -= 420.0;
    } else if post_residual <= 12 {
        score -= 70.0;
    } else if post_residual < 20 {
        score += 18.0;
    } else if post_residual < 30 {
        score += 18.0 + (30 - post_residual) as f64 * 0.6;
    }

    // Lookahead on next item fitting post_residual
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 600.0;
        } else if next_item_size <= post_residual {
            let post2 = post_residual - next_item_size;
            score -= 100.0 - post2 as f64 * 2.0;
            if post2 == 0 {
                score -= 80.0;
            }
            if post2 > 0 && post2 <= 4 {
                score -= 22.0;
            }
            if post_residual % next_item_size == 0 {
                score -= 14.0;
            }
        } else {
            score += 16.0;
            if post_residual > 0 && post_residual < 15 {
                score += 40.0;
            }
            let gap = next_item_size as f64 - post_residual as f64;
            if gap <= 5.0 {
                score += (6.0 - gap) * 4.0;
            }
        }
    }

    // Pressure to compact when many bins open
    score += open_bins_count as f64 * 0.6;

    // Last-chance bin: strongly favor using it
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // Relative fill ratio preference
    score -= (item_size as f64 / cap_f) * 10.0;

    // NEW-BIN CANDIDATE handling
    if bin_residual == bin_capacity {
        let avg_fill = 1.0 - (mean_residual / cap_f);
        score += 220.0 - avg_fill * 300.0 - progress * 60.0;
        if item_size as f64 > mean_residual {
            score -= 40.0;
        }
        if fitting_bins_count > 0 {
            score += (fitting_bins_count as f64).min(5.0) * 8.0;
            let snug = item_size as f64 / (bin_residual.max(1) as f64);
            if snug > 0.9 {
                score += 35.0;
            }
            if snug > 0.95 {
                score += 25.0;
            }
        }
        let newbin_waste = (bin_capacity - item_size) as f64;
        if newbin_waste > 0.0 && newbin_waste < mean_residual * 0.6 {
            score -= 30.0;
        }
        if next_item_size > 0 && newbin_waste as u32 >= next_item_size {
            let tail = newbin_waste as u32 - next_item_size;
            if tail <= 4 {
                score -= 16.0;
            }
            if tail == 0 {
                score -= 10.0;
            }
        }
        if progress > 0.6 {
            let waste_tol = (1.0 - progress) * cap_f * 0.35;
            if newbin_waste > waste_tol && fitting_bins_count > 0 {
                score += 10.0 + progress * 20.0;
            }
        }
    } else {
        // Tightness preference on existing bins
        let tightness = 1.0 - (item_size as f64 / bin_residual.max(1) as f64);
        score += tightness * 70.0;
        score += (mean_residual - bin_residual as f64) * 1.2;

        let dead_ratio = post_residual as f64 / cap_f;
        if dead_ratio < 0.03 {
            score -= 30.0;
        } else if dead_ratio < 0.08 {
            score -= 12.0;
        } else if dead_ratio > 0.35 {
            score += 22.0;
        } else if dead_ratio > 0.25 {
            score += 10.0;
        }

        if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
            let wasted = next_item_size as f64 - post_residual as f64;
            score += wasted * 0.6;
            if wasted > 12.0 {
                score += dead_ratio * 60.0;
            }
        }
        if item_size == bin_residual {
            score -= 40.0;
        }
        if post_residual > 0 && next_item_size > 0 && post_residual >= next_item_size {
            let chain = post_residual / next_item_size;
            if chain >= 2 {
                score -= (chain.min(4)) as f64 * 5.0;
            }
        }
        if post_residual > 0 && (post_residual as f64) < mean_residual * 0.25 {
            score -= 14.0;
        }
        if post_residual > 0 && (post_residual as f64) > mean_residual * 1.5 && fitting_bins_count > 2 {
            score += 8.0;
        }
        if post_residual > 0 && post_residual % 10 == 0 {
            score -= 8.0;
        }
    }

    // Early in stream: slight diversity bonus
    if progress < 0.1 {
        score += 3.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: heavily penalize small unusable gaps.
    if post_residual > 0 && post_residual < 10 {
        score += 40.0;
    } else if post_residual > 0 && post_residual < 20 {
        score += 15.0;
    }

    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 60.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // Open-bin pressure: with many open bins, prefer compacting into existing bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += open_bins_count as f64 * (0.8 + 0.6 * progress);

    // Dead space relative to mean residual: penalize bins that would be left far below the mean.
    if post_residual as f64 > mean_residual * 1.5 {
        score += 8.0;
    }

    // Lookahead: reward leaving a gap that the next item can fill.
    if next_item_size > 0 && post_residual > 0 && next_item_size <= post_residual {
        score -= 12.0;
    }

    // New-bin candidate: baseline score so it wins only when fits are poor.
    if bin_residual == bin_capacity {
        score += 18.0 + open_bins_count as f64 * 0.3;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit reward
    if post_residual == 0 {
        score -= 1000.0;
    }

    // 2-step lookahead: reward if next item fits the post residual exactly
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 500.0;
        } else if post_residual >= next_item_size {
            score -= 50.0 + (post_residual - next_item_size) as f64 * 0.5;
        } else {
            // next item won't fit; penalize wasted space relative to next item
            score += (next_item_size - post_residual) as f64 * 0.3;
        }
    }

    // Compare post_residual to mean residual: prefer bins left tighter than average
    score -= (mean_residual - post_residual as f64) * 0.2;

    // Last chance bin: strongly favor using it before opening a new one
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 300.0;
    }

    // Penalize opening a new bin when open bins fit reasonably well
    if bin_residual == bin_capacity {
        score += 200.0 + mean_residual * 0.5;
        if next_item_size > 0 && next_item_size <= post_residual {
            score -= 100.0;
        }
    }

    // Late in stream: prefer tighter packing
    let progress = step_index as f64 / total_items.max(1) as f64;
    score *= 1.0 - 0.1 * progress;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tight-fit reward: strongly prefer bins whose post_residual is small,
    // with a super-linear penalty on large leftover space.
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    score += 0.35 * (post * post) / cap;

    // Lookahead (k=2): reward if the next item can also fit into the
    // resulting residual — this bin enables a chain of placements.
    if next_item_size > 0 && (next_item_size as f64) <= post {
        score -= 12.0 + 0.25 * (next_item_size as f64);
    }
    // Penalize if next item would be blocked by this placement's waste.
    if next_item_size > post_residual && next_item_size <= bin_residual {
        score += 6.0;
    }

    // Last-chance bin: if this is the only bin that fits, use it rather
    // than opening a new bin (unless the fit is terrible).
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 10.0 + 0.1 * (bin_residual as f64 - post);
    }

    // New-bin candidate handling: opening a bin is only attractive when
    // existing bins are nearly full (low mean_residual) or item fits badly.
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        let crowdedness = 1.0 - (mean_residual / cap).min(1.0);
        score += 18.0 - 14.0 * crowdedness;
        // Late in the stream, be more conservative about opening bins.
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score += 8.0 * progress;
    } else {
        // Prefer bins whose residual is far below the mean (they are the
        // "odd ones out" and should be consolidated).
        let dev = mean_residual - bin_residual as f64;
        if dev > 0.0 {
            score -= 0.15 * dev;
        }
    }

    // Global pressure: many open bins → encourage filling existing ones.
    score -= 0.5 * (open_bins_count as f64).ln().max(0.0);

    // Item-size coupling: large items should prefer emptier bins.
    let size_frac = item_size as f64 / cap;
    score += 10.0 * size_frac * (bin_residual as f64 / cap - size_frac).max(0.0);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;
    let mut score = pr;
    // Non-linear polynomial coupling between post_residual and stream progress
    let coupling = norm_pr * norm_pr * (1.0 - progress) + norm_pr * progress * progress;
    score += 40.0 * coupling * cap;
    // Lookahead: reward residual that can host the next item
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        let fits = (nx <= pr) as i32 as f64;
        score -= 12.0 * fits * (1.0 - pr / (pr + nx));
        score += 6.0 * (nx / (pr + nx)) * (1.0 - fits);
    }
    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0 * (1.0 + progress);
    }
    // Penalize spreading when many bins are open
    score += 3.0 * (open_bins_count as f64).ln() * norm_pr;
    // Mild attraction to mean residual balance
    score += 0.5 * (pr - mean_residual).abs();
    // Smooth tightness reward
    let tightness = 1.0 - norm_pr;
    score -= 10.0 * tightness * tightness;
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: residues modulo 10 create
    // "usable classes" of leftover space for future integer items.
    let residue = post_residual % 10;
    let class_bonus = match residue {
        0 => 12.0, // perfectly reusable leftover
        1..=3 => 6.0,
        4..=6 => 0.0,
        7..=9 => -8.0, // awkward dead-space class
        _ => 0.0,
    };
    score -= class_bonus;

    // Fraction-of-capacity classes: post_residual near multiples of
    // capacity quarters are structurally attractive.
    let quarter = bin_capacity / 4;
    let qdist = (post_residual as i32 - ((post_residual as i32 + quarter as i32 / 2) / quarter as i32 * quarter as i32)).abs();
    score -= (quarter as f64 - qdist as f64).max(0.0) * 0.4;

    // Integer-division threshold: leftover that can still host the
    // lookahead item is valuable.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 10.0;
            // harmonic pairing: exact fit of the next item
            if post_residual == next_item_size {
                score -= 25.0;
            }
        } else {
            score += 6.0;
        }
    }

    // Last-chance bin: strongly favor using it before opening a new one.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // Penalize opening new bins when plenty of open bins exist.
    if bin_residual == bin_capacity {
        score += 15.0 + 2.0 * open_bins_count as f64;
        // but allow fresh bins early in the stream
        let progress = step_index as f64 / total_items.max(1) as f64;
        score -= 10.0 * (1.0 - progress);
    }

    // Tight fit reward relative to item size (harmonic ratio).
    let ratio = item_size as f64 / bin_capacity as f64;
    score -= ratio * 8.0;

    // Keep scores in a sane band.
    score = score.max(0.0);
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let score = (post_residual as f64) * 0.89;
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals too small for the smallest plausible
    // future item are "dead space" — penalize them heavily.
    let min_useful = 1u32;
    if post_residual < min_useful {
        score += 1000.0;
    }

    // Dead zone: post_residual that cannot fit the lookahead item is wasted
    // unless it is zero (perfect fit).
    if post_residual > 0 && next_item_size > 0 && post_residual < next_item_size {
        score += 25.0 + 0.5 * (next_item_size - post_residual) as f64;
    }

    // Perfect fit gets strong reward.
    if post_residual == 0 {
        score -= 60.0;
    }

    // Tight fits (small but nonzero remainder) mildly rewarded relative to
    // leaving large gaps, since archetype is strict dead-space avoidance.
    if post_residual > 0 && post_residual <= 10 {
        score -= 10.0;
    }

    // Last-chance bin: strongly prefer using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 40.0;
    }

    // Open-bin pressure: many open bins -> discourage spreading, favor filling
    // existing bins (penalize the new-bin candidate).
    if bin_residual == bin_capacity {
        score += 30.0 + 4.0 * open_bins_count as f64;
    }

    // Coupling with mean residual: if this bin's residual is far below the mean,
    // it is already well-packed; reward using it further.
    let residual_f = bin_residual as f64;
    if residual_f < mean_residual {
        score -= 0.3 * (mean_residual - residual_f);
    } else {
        score += 0.15 * (residual_f - mean_residual);
    }

    // Late in the stream, close out bins aggressively (avoid stragglers).
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += 20.0 * progress * (post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong reward for near-perfect fits (post_residual small).
    score -= (bin_capacity as f64 - post_residual as f64).max(0.0) * 0.0;
    score -= (item_size as f64 / bin_capacity as f64) * 10.0;

    // Reward exact / tight fits: the smaller post_residual relative to capacity, the better.
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= tightness * 20.0;

    // 2-step lookahead: if next item fits exactly into post_residual, big reward.
    if next_item_size > 0 {
        let diff = (post_residual as i64 - next_item_size as i64).abs() as f64;
        score -= 15.0 * (1.0 - diff / bin_capacity as f64).max(0.0);
        // Penalize if post_residual is too small for next item (dead space risk).
        if (post_residual as i64) < (next_item_size as i64) {
            score += (next_item_size as f64 - post_residual as f64) * 0.3;
        }
    }

    // Penalize creating residuals that are small and hard to reuse (dead space).
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Penalize wasting a mostly-full bin's residual when other bins could fit.
    if fitting_bins_count > 1 && post_residual > 50 {
        score += 5.0;
    }

    // Last-chance bin: strong reward to use it rather than open a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 12.0;
    }

    // New-bin candidate handling: discourage opening a new bin unless no good fit exists.
    if bin_residual == bin_capacity {
        // Base penalty for opening a new bin.
        score += 30.0;
        // If current bin would leave a very awkward residual, opening new bin is OK.
        if post_residual > 0 && post_residual < 10 {
            score -= 40.0;
        }
        // If lookahead next item is large and current bin residual small, new bin attractive.
        if next_item_size > 0 && (bin_residual as i64 - next_item_size as i64) < 0 {
            score -= 10.0;
        }
        // Fewer open bins -> cheaper to open.
        score -= (open_bins_count as f64).sqrt() * 2.0;
    }

    // Mild preference to balance residuals against mean residual across open bins.
    score += (post_residual as f64 - mean_residual).abs() * 0.05;

    // Slight stream-progression tilt: later in stream, favor filling existing bins harder.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= progress * 3.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tight fits are strongly preferred.
    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 30.0 * fit_ratio * fit_ratio;

    // Penalize large dead space with non-linear coupling.
    if post_residual > 0 {
        let dead = post_residual as f64 / bin_capacity as f64;
        score += 12.0 * dead * dead;
    } else {
        score -= 25.0; // perfect fill bonus
    }

    // Lookahead: reward bins whose post-residual can host the next item.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 10.0;
    }
    // Penalize leaving a gap just below the next item (wasted sliver).
    if next_item_size > post_residual && post_residual > 0 {
        let gap = (next_item_size - post_residual) as f64;
        score += 0.15 * gap;
    }

    // Last-chance bin before opening a new one: strong reward.
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // New-bin candidate: make it moderately unattractive so we only open
    // a new bin when existing fits are genuinely bad.
    if bin_residual == bin_capacity {
        score += 55.0;
        // Opening a new bin is more attractive early (plenty of stream left)
        // and when few bins are open.
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score -= 20.0 * (1.0 - progress);
        score -= 2.0 * (open_bins_count as f64).recip() * 10.0;
        // If the item is large relative to capacity, new bin is safer.
        if item_size > bin_capacity / 2 {
            score -= 15.0;
        }
    }

    // Prefer bins with residuals below the mean (consolidate emptier space usage).
    score += 0.1 * (mean_residual - bin_residual as f64);

    // Late in the stream, be greedier about filling bins tightly.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= 8.0 * progress * fit_ratio;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let score = 0.0;
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    let progress = step_index as f64 / total_items.max(1) as f64;
    let cap = bin_capacity as f64;
    let fit_ratio = item_size as f64 / cap;
    let post_norm = post_residual as f64 / cap;
    let res_norm = bin_residual as f64 / cap;

    // Non-linear polynomial coupling of post_residual with stream progress.
    // Early on, waste is cheap (bins get combined later); late, waste is costly.
    let progress_coupling = post_norm * post_norm * (0.5 + 1.5 * progress * progress);
    score += 30.0 * progress_coupling;

    // Reward tight fits (small post_residual relative to residual) with smooth decay.
    let tightness = 1.0 - post_norm;
    score -= 20.0 * tightness * tightness * tightness * (1.0 + progress);

    // Penalize leaving residuals that are too small to be useful for future items,
    // smoothed via a quadratic bump around the "dead zone".
    let dead = if post_residual > 0 { post_norm * (1.0 - post_norm) } else { 0.0 };
    score -= 10.0 * dead * dead;

    // Lookahead: if next item fits exactly in post_residual, reward strongly (smooth).
    if next_item_size > 0 && (next_item_size as u32) <= post_residual {
        let gap = (post_residual as f64 - next_item_size as f64) / cap;
        score -= 15.0 * (1.0 - gap * gap) * (1.0 - progress * 0.5);
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 25.0 * (1.0 - post_norm);
    }

    // Prefer bins with residual close to item size (best-fit smoothing, quadratic).
    let diff = res_norm - fit_ratio;
    score += 8.0 * diff * diff;

    // Mild penalty for spreading across many open bins late in the stream.
    score += 0.05 * open_bins_count as f64 * progress;

    // Slight preference toward bins with below-mean residual (consolidation).
    score += 0.1 * (mean_residual - bin_residual as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: residues divisible by common item
    // granularities (5, 10, 20) are more reusable -> reward them.
    let pr = post_residual;
    if pr > 0 {
        if pr % 10 == 0 { score -= 6.0; }
        else if pr % 5 == 0 { score -= 3.0; }
        if pr % 20 == 0 { score -= 2.0; }
        // Small unusable dead space (1..=4) is a near-loss: penalize hard.
        if pr <= 4 { score += 25.0; }
        // Harmonic quadrant thresholds: mid-range leftovers (41..60) are
        // awkward for typical item sizes; penalize slightly.
        if pr > 40 && pr < 61 { score += 4.0; }
    }

    // Lookahead coupling: reward if next item fits perfectly or well.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 20.0; // perfect chaining
        } else if post_residual >= next_item_size {
            let slack = (post_residual - next_item_size) as f64;
            score -= 8.0 * (1.0 - slack / bin_capacity as f64);
        } else {
            // Next item cannot fit here: mild penalty scaled by overflow.
            score += 0.05 * (next_item_size - post_residual) as f64;
        }
    }

    // Tight fit reward: ratio of item to residual.
    if bin_residual > 0 {
        let fill = item_size as f64 / bin_residual as f64;
        score -= 10.0 * fill;
    }

    // Last-chance bin: if this is the only fitting bin, strongly prefer it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate: default penalty so it's only chosen when no open
    // bin scores well. Reduce penalty late in the stream or when mean
    // residual across open bins is small (open bins nearly full).
    if bin_residual == bin_capacity {
        score = bin_capacity as f64 + 5.0;
        let progress = step_index as f64 / total_items.max(1) as f64;
        score -= 5.0 * progress;
        if mean_residual < item_size as f64 {
            score -= 30.0; // open bins are too full; new bin justified
        }
        if fitting_bins_count == 0 {
            score -= 100.0; // nothing fits anywhere: must open
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap_f = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Dead-space shaping (borrowed from best heuristic, tuned)
    if post_residual == 0 {
        score -= 1100.0;
    } else if post_residual <= 3 {
        score -= 420.0;
    } else if post_residual <= 12 {
        score -= 90.0;
    } else if post_residual < 20 {
        score += 16.0;
    } else if post_residual < 30 {
        score += 18.0 + (30 - post_residual) as f64 * 0.6;
    }

    if post_residual > 60 {
        score += 12.0;
    }

    // Lookahead: next-item fit analysis
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 850.0;
        } else if next_item_size <= post_residual {
            let post2 = post_residual - next_item_size;
            score -= 120.0 - post2 as f64 * 2.0;
            if post2 == 0 { score -= 100.0; }
            if post2 > 0 && post2 < 5 { score -= 25.0; }
            if post2 > 0 && post2 % 10 == 0 { score -= 24.0; }
            if post_residual % next_item_size == 0 { score -= 16.0; }
            let chain = post_residual / next_item_size;
            if chain >= 2 { score -= (chain.min(4)) as f64 * 6.0; }
        } else {
            score += 18.0;
            if post_residual > 0 && post_residual < 15 { score += 42.0; }
            let gap = next_item_size as f64 - post_residual as f64;
            if post_residual > 0 && gap <= 3.0 { score += 32.0; }
            else if gap <= 8.0 { score += 10.0; }
            if post_residual as f64 > mean_residual * 1.4 { score -= 10.0; }
            let dead_frac = post_residual as f64 / cap_f;
            if post_residual > 0 && gap > 12.0 { score += dead_frac * 80.0; }
        }
    }

    // Pressure from number of open bins
    score += open_bins_count as f64 * 0.8;

    // Last-chance bin: strongly favor using it
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // Relative fill tightness
    score -= (item_size as f64 / cap_f) * 10.0;
    if bin_residual < bin_capacity {
        let snug = item_size as f64 / bin_residual.max(1) as f64;
        if snug > 0.95 { score -= 25.0; }
        else if snug > 0.9 { score -= 12.0; }
        if item_size == bin_residual { score -= 40.0; }
    }

    // NEW-BIN CANDIDATE evaluation
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let avg_fill = 1.0 - (mean_residual / cap_f);
        score += 240.0 - avg_fill * 320.0 - progress * 60.0;
        if fitting_bins_count > 0 {
            score += (fitting_bins_count as f64).min(5.0) * 8.0 + 18.0;
        }
        let newbin_waste = (bin_capacity - item_size) as f64;
        if item_size >= bin_capacity * 3 / 4 { score -= 50.0; }
        if bin_capacity - item_size <= 4 { score -= 65.0; }
        if next_item_size > 0 && next_item_size <= bin_capacity - item_size { score -= 22.0; }
        let leftover = bin_capacity - item_size;
        if next_item_size > 0 && leftover >= next_item_size {
            let tail = leftover % next_item_size;
            if tail == 0 { score -= 14.0; }
            else if tail <= 4 { score -= 12.0; }
        }
        if newbin_waste > 0.0 && (newbin_waste as u32) < next_item_size && newbin_waste < cap_f * 0.12 {
            score += 24.0;
        }
        if progress > 0.6 {
            let waste_tol = (1.0 - progress) * cap_f * 0.35;
            if newbin_waste > waste_tol && fitting_bins_count > 0 {
                score += 10.0 + progress * 20.0;
            }
        }
        if newbin_waste > 0.0 && newbin_waste < mean_residual * 0.6 { score -= 28.0; }
    }

    // Early stream: slight diversity preference
    let progress = step_index as f64 / total_items.max(1) as f64;
    if progress < 0.1 {
        score += 3.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward perfect fits strongly.
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Dead-space penalty: small positive gaps are likely unusable.
    if post_residual > 0 {
        let min_item = 1.0; // unknown distribution, assume smallest possible item
        let unusable = (post_residual as f64) < min_item.max(0.0);
        if unusable {
            score += 500.0;
        }
        // Penalize gaps too small to fit the known next item.
        if next_item_size > 0 && post_residual < next_item_size {
            score += 30.0 + 0.5 * (next_item_size - post_residual) as f64;
        }
        // Bonus if this bin can still fit the next item (keeps it useful).
        if next_item_size > 0 && post_residual >= next_item_size {
            score -= 20.0;
        }
    }

    // Tightness reward: prefer bins where the item fills a large fraction.
    let fill_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 40.0 * fill_ratio;

    // Open-bin pressure: with many open bins, discourage spreading into new bins
    // unless this is a new empty bin candidate.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    if bin_residual == bin_capacity {
        // New-bin candidate: acceptable early or when existing fits are poor.
        score = 200.0 + 300.0 * progress + 10.0 * open_bins_count as f64;
        if post_residual == 0 { score -= 1000.0; } // never happens, but safe
    } else {
        score -= 5.0 * open_bins_count as f64 * (1.0 - progress);
    }

    // Last-chance bin: strongly prefer using the only bin that fits.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 200.0;
    }

    // Prefer bins below mean residual (worse-fit bins absorb the item,
    // preserving roomier bins for future large items).
    score += 0.3 * ((bin_residual as f64) - mean_residual);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let capacity = bin_capacity as f64;
    let post = post_residual as f64;
    let mut score = post;

    // Perfect fit reward
    if post_residual == 0 {
        score -= 1000.0;
    }

    // 2-step lookahead: reward if next item exactly fills post_residual
    if next_item_size > 0 {
        let next = next_item_size as f64;
        if (next - post).abs() < f64::EPSILON {
            score -= 800.0;
        } else if next <= post {
            // next item fits: reward proportional to how well it fills leftover
            score -= 300.0 * (next / post.max(1.0));
            score -= (post - next) * 0.5;
        } else {
            // next item won't fit: penalize large leftover dead space
            score += (post - next) * 0.3;
        }
    }

    // Compare against mean residual: bins with less residual than average are precious
    if post < mean_residual {
        score -= (mean_residual - post) * 0.4;
    } else {
        score += (post - mean_residual) * 0.2;
    }

    // Last-chance bin: strongly favor using it
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 500.0;
    }

    // New-bin candidate: penalize opening a new bin early on
    if bin_residual == bin_capacity {
        score += 250.0 * (1.0 - step_index as f64 / total_items.max(1) as f64);
        score += open_bins_count as f64 * 10.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let score = post_residual as f64 / bin_capacity.max(1) as f64;
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap_f = bin_capacity as f64;
    let progress = step_index as f64 / total_items.max(1) as f64;
    let mut score = post_residual as f64;

    // Tiered dead-space avoidance (combined: strong perfect-fit rewards + graded penalties)
    if post_residual == 0 {
        score -= 600.0;
    } else if post_residual <= 3 {
        score -= 260.0;
    } else if post_residual <= 12 {
        score -= 60.0;
    } else if post_residual < 20 {
        score += 18.0;
    } else if post_residual < 30 {
        score += 18.0 + (30 - post_residual) as f64 * 0.6;
    }

    // Lookahead: exact and near-exact fits for the next item
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 450.0;
        } else if next_item_size <= post_residual {
            let post2 = post_residual - next_item_size;
            score -= 80.0 - (post2 as f64) * 1.6;
            if post2 == 0 { score -= 90.0; }
            if post2 > 0 && post2 < 5 { score -= 26.0; }
            if post2 % 10 == 0 && post2 > 0 { score -= 20.0; }
            if post2 > 0 && post2 <= next_item_size / 4 { score -= 10.0; }
            if post_residual % next_item_size == 0 { score -= 14.0; }
            if post_residual >= next_item_size * 2 && post_residual - next_item_size * 2 <= 4 {
                score -= 18.0;
            }
            let chain = post_residual / next_item_size;
            if chain >= 2 { score -= (chain.min(4)) as f64 * 6.0; }
        } else {
            // next item won't fit here: penalize leaving a nearly-fitting gap
            let gap = next_item_size - post_residual;
            if post_residual > 0 {
                if gap <= 3 { score += 35.0; }
                else if gap <= 8 { score += 12.0; }
                if (gap as f64) > mean_residual * 0.5 { score += 12.0; }
                if post_residual < 15 { score += 30.0; }
                score += (1.0 - progress) * 12.0;
            }
        }
    }

    // Compaction pressure scaled by open bins
    score += open_bins_count as f64 * 0.8;

    // Last-chance bin: strongly favor using it
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 50.0;
    }

    // Tightness via relative fill
    score -= (item_size as f64 / bin_residual.max(1) as f64) * 30.0;

    // NEW-BIN CANDIDATE handling
    if bin_residual == bin_capacity {
        let newbin_waste = (bin_capacity - item_size) as f64;
        let avg_fill = 1.0 - (mean_residual / cap_f);
        score += 220.0 - avg_fill * 200.0 - progress * 60.0;
        // big items deserve a fresh bin when few alternatives fit well
        if item_size as f64 / cap_f > 0.75 { score -= 55.0; }
        if item_size >= bin_capacity * 3 / 4 { score -= 30.0; }
        if bin_capacity - item_size <= 4 { score -= 60.0; }
        if item_size as f64 > mean_residual { score -= 25.0; }
        if newbin_waste < mean_residual * 0.5 { score -= 30.0; }
        if next_item_size > 0 && (bin_capacity - item_size) >= next_item_size
            && (bin_capacity - item_size) - next_item_size <= 6 {
            score -= 35.0;
        }
        // fresh-bin leftover divisible by next item => chain packing
        if next_item_size > 0 {
            let leftover = bin_capacity - item_size;
            if leftover >= next_item_size {
                let tail = leftover % next_item_size;
                if tail == 0 { score -= 14.0; }
                else if tail <= 4 { score -= 12.0; }
            }
            if leftover < next_item_size && leftover < 10 { score += 16.0; }
        }
        if fitting_bins_count > 3 { score += (fitting_bins_count.min(6) as f64) * 6.0; }
        if progress > 0.6 {
            let waste_tol = (1.0 - progress) * cap_f * 0.35;
            if newbin_waste > waste_tol && fitting_bins_count > 0 {
                score += 10.0 + progress * 20.0;
            }
        }
        if progress < 0.1 { score -= 5.0; }
    }

    // Mild progress-based diversity nudge for open bins
    if progress < 0.1 { score += 3.0; }

    // Prefer bins whose residual is below average (consolidating slack)
    if bin_residual < bin_capacity {
        score += (mean_residual - bin_residual as f64) * 1.0;
        // dead-ratio shaping: reward small residuals, punish large unusable ones
        let dead_ratio = post_residual as f64 / cap_f;
        if dead_ratio < 0.03 {
            score -= 30.0;
        } else if dead_ratio < 0.08 {
            score -= 12.0;
        } else if dead_ratio > 0.35 {
            score += 22.0;
        } else if dead_ratio > 0.25 {
            score += 10.0;
        }
        // unusable gap relative to next item
        if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
            let unusable_gap = (next_item_size - post_residual) as f64;
            if unusable_gap > 12.0 {
                score += dead_ratio * 70.0;
            }
        }
    }

