pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap_f = bin_capacity as f64;
    let progress = step_index as f64 / total_items.max(1) as f64;
    let mut score = post_residual as f64;

    // Dead-space avoidance with graded penalties
    if post_residual == 0 {
        score -= 900.0;
    } else if post_residual <= 3 {
        score -= 400.0;
    } else if post_residual < 10 {
        score += 55.0;
    } else if post_residual < 20 {
        score += 18.0;
    } else if post_residual < 30 {
        score += 18.0 + (30 - post_residual) as f64 * 0.6;
    }

    // Lookahead: reward placements that chain with the next item
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 700.0;
        } else if next_item_size <= post_residual {
            let post2 = post_residual - next_item_size;
            score -= 110.0 - post2 as f64 * 2.0;
            if post2 == 0 { score -= 90.0; }
            if post2 > 0 && post2 < 5 { score -= 25.0; }
            if post_residual % next_item_size == 0 { score -= 16.0; }
            let chain = post_residual / next_item_size;
            if chain >= 2 { score -= (chain.min(4)) as f64 * 6.0; }
        } else {
            score += 20.0;
            if post_residual > 0 && post_residual < 15 { score += 45.0; }
            let gap = (next_item_size - post_residual) as f64;
            if post_residual > 0 && gap <= 3.0 { score += 35.0; }
            if post_residual > 0 && gap <= 8.0 { score += 12.0; }
            if post_residual as f64 > mean_residual * 1.4 { score -= 12.0; }
        }
    }

    // Wasted large residual penalty
    if post_residual > 60 {
        score += 12.0;
    }

    // Pressure from number of open bins
    score += open_bins_count as f64 * 0.8;

    // Last-chance bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // Tightness preference
    score -= (item_size as f64 / cap_f) * 10.0;

    // NEW-BIN CANDIDATE handling
    if bin_residual == bin_capacity {
        let avg_fill = 1.0 - (mean_residual / cap_f);
        score += 250.0 - avg_fill * 330.0 - progress * 65.0;
        if item_size as f64 > mean_residual { score -= 45.0; }
        if fitting_bins_count > 0 {
            score += (fitting_bins_count as f64).min(5.0) * 9.0 + 20.0;
            let snug = item_size as f64 / (bin_residual.max(1) as f64);
            if snug > 0.9 { score += 40.0; }
            if snug > 0.95 { score += 28.0; }
        }
        if next_item_size > 0 && next_item_size >= bin_capacity / 2 { score -= 32.0; }
        if item_size >= bin_capacity * 3 / 4 { score -= 55.0; }
        if bin_capacity - item_size <= 4 { score -= 70.0; }
        let newbin_waste = (bin_capacity - item_size) as f64;
        if newbin_waste > 0.0 && (newbin_waste as u32) < next_item_size && newbin_waste < cap_f * 0.12 {
            score += 26.0;
        }
        if progress > 0.6 {
            let waste_tol = (1.0 - progress) * cap_f * 0.35;
            if newbin_waste > waste_tol && fitting_bins_count > 0 {
                score += 10.0 + progress * 22.0;
            }
        }
    } else {
        let tightness = 1.0 - (item_size as f64 / bin_residual.max(1) as f64);
        score += tightness * 85.0;
        score += (mean_residual - bin_residual as f64) * 1.5;

        let dead_ratio = post_residual as f64 / cap_f;
        if dead_ratio < 0.03 {
            score -= 38.0;
        } else if dead_ratio < 0.08 {
            score -= 14.0;
        } else if dead_ratio > 0.35 {
            score += 24.0;
        } else if dead_ratio > 0.25 {
            score += 10.0;
        }
        score += dead_ratio * 30.0;

        if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
            let wasted = (next_item_size - post_residual) as f64;
            score += wasted * 0.6;
            score += (1.0 - progress) * 14.0;
        }
        if item_size == bin_residual { score -= 45.0; }
        if post_residual > 0 && post_residual < 6 { score -= 22.0; }
        if post_residual > 0 && (post_residual as f64) < mean_residual * 0.25 { score -= 15.0; }
        if post_residual > 0 && (post_residual as f64) < cap_f * 0.015 { score -= 18.0; }
        if post_residual > 0 && post_residual % 10 == 0 { score -= 10.0; }
        if post_residual > 0 && post_residual % 5 == 0 && post_residual <= 30 { score -= 8.0; }
        if bin_residual as f64 > cap_f * 0.6 { score -= 12.0; }
        if post_residual > 0 && next_item_size > 0 && post_residual >= next_item_size && post_residual <= next_item_size + 4 {
            score -= 22.0;
        }
        if post_residual > 0 && (post_residual as f64) > mean_residual * 1.6 && fitting_bins_count > 2 {
            score += 10.0;
        }
        if post_residual > 0 && next_item_size > 0 {
            let unusable = post_residual < next_item_size && (next_item_size - post_residual) > 12;
            if unusable {
                score += dead_ratio * 90.0;
            } else {
                let reuse = (post_residual / next_item_size) as f64 * (next_item_size as f64 / cap_f);
                score -= reuse * 22.0;
            }
        }
        if post_residual > 0 && fitting_bins_count <= 2 { score -= 8.0; }
    }

    // Early stream: slight diversity bonus
    if progress < 0.1 {
        score += 3.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap_f = bin_capacity as f64;
    let progress = step_index as f64 / total_items.max(1) as f64;
    let mut score = post_residual as f64;

    // Tiered dead-space avoidance (strengthened)
    if post_residual == 0 {
        score -= 900.0;
    } else if post_residual <= 3 {
        score -= 380.0;
    } else if post_residual <= 12 {
        score -= 80.0;
    } else if post_residual < 20 {
        score += 18.0;
    } else if post_residual < 30 {
        score += 18.0 + (30 - post_residual) as f64 * 0.6;
    }

    // Lookahead: exact and near-exact fits for the next item
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 700.0;
        } else if next_item_size <= post_residual {
            let post2 = post_residual - next_item_size;
            score -= 120.0 - (post2 as f64) * 2.0;
            if post2 == 0 { score -= 100.0; }
            if post2 > 0 && post2 < 5 { score -= 26.0; }
            if post2 % 10 == 0 && post2 > 0 { score -= 24.0; }
            if post_residual % next_item_size == 0 { score -= 16.0; }
            if post_residual >= next_item_size * 2 && post_residual - next_item_size * 2 <= 4 {
                score -= 20.0;
            }
            let chain = post_residual / next_item_size;
            if chain >= 2 { score -= (chain.min(4)) as f64 * 6.0; }
            if post2 > 0 && post2 <= next_item_size / 4 { score -= 10.0; }
        } else {
            // next item won't fit here: penalize leaving a nearly-fitting gap
            let gap = next_item_size - post_residual;
            if post_residual > 0 {
                if gap <= 3 { score += 35.0; }
                else if gap <= 8 { score += 12.0; }
                if (gap as f64) > mean_residual * 0.5 { score += 12.0; }
                if post_residual < 15 { score += 30.0; }
                if post_residual % 10 == 0 { score -= 12.0; }
            }
        }
    }

    // Compaction pressure scaled by open bins
    score += open_bins_count as f64 * 0.8;

    // Last-chance bin: strongly favor using it
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 45.0;
    }

    // Tightness via relative fill
    let snug = item_size as f64 / bin_residual.max(1) as f64;
    score -= snug * 30.0;
    if item_size == bin_residual { score -= 40.0; }

    // Consolidate slack: prefer bins below average residual
    if bin_residual < bin_capacity {
        score += (mean_residual - bin_residual as f64) * 1.1;
    }

    // NEW-BIN CANDIDATE handling
    if bin_residual == bin_capacity {
        let avg_fill = 1.0 - (mean_residual / cap_f);
        score += 240.0 - avg_fill * 320.0 - progress * 60.0;
        let newbin_waste = (bin_capacity - item_size) as f64;
        if item_size as f64 / cap_f > 0.75 { score -= 55.0; }
        if item_size as f64 > mean_residual { score -= 40.0; }
        if newbin_waste < mean_residual * 0.5 { score -= 30.0; }
        if bin_capacity - item_size <= 4 { score -= 70.0; }
        if next_item_size > 0 {
            let leftover = bin_capacity - item_size;
            if leftover >= next_item_size {
                let tail = leftover % next_item_size;
                if tail == 0 { score -= 25.0; }
                else if tail <= 4 { score -= 16.0; }
                if leftover - next_item_size <= 6 { score -= 35.0; }
                if leftover >= next_item_size * 2 { score -= 14.0; }
            } else if leftover < 10 {
                score += 18.0;
            }
            if leftover < next_item_size && leftover < cap_f * 0.12 { score += 26.0; }
        }
        if snug > 0.95 { score -= 30.0; }
        if fitting_bins_count > 0 {
            score += (fitting_bins_count.min(6) as f64) * 8.0 + 15.0;
        }
        // late stream: discourage wasteful fresh bins
        if progress > 0.75 && newbin_waste > cap_f * 0.4 { score += 15.0 + progress * 15.0; }
        if progress < 0.1 { score -= 5.0; }
    }

    // Mild progress-based diversity nudge for open bins
    if progress < 0.1 { score += 3.0; }

    // Dead-space ratio shaping for open bins
    if bin_residual < bin_capacity {
        let dead_ratio = post_residual as f64 / cap_f;
        if dead_ratio < 0.03 { score -= 30.0; }
        else if dead_ratio > 0.30 { score += 20.0; }
        if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
            let unusable_gap = (next_item_size as f64 - post_residual as f64) / next_item_size.max(1) as f64;
            score += unusable_gap * 40.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tight-fit reward: strongly favor bins whose residual is almost exactly consumed.
    let fill_ratio = item_size as f64 / bin_residual as f64;
    score -= 40.0 * fill_ratio * fill_ratio;

    // Penalize dead space that can never host typical items (small leftovers).
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    } else if post_residual < 20 {
        score += 15.0 * (1.0 - post_residual as f64 / 20.0);
    }

    // Lookahead: reward bins that can also host the next item after this placement.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 25.0;
            if post_residual - next_item_size < 10 {
                score -= 15.0; // perfect pairing
            }
        } else if bin_residual >= next_item_size && post_residual < next_item_size {
            // this placement destroys the ability to fit the next item here
            score += 10.0 * (next_item_size - post_residual) as f64 / 10.0;
        }
    }

    // Last-chance bonus: if this is the only bin that fits, strongly prefer it.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 100.0;
    }

    // New-bin candidate handling: penalize opening a new bin unless no open bin fits well.
    if bin_residual == bin_capacity {
        let base_penalty = 55.0;
        let scarcity = if fitting_bins_count == 0 { 0.0 } else { 45.0 };
        let early = 1.0 - (step_index as f64 / total_items.max(1) as f64);
        score += base_penalty + scarcity + 20.0 * early;
        // If the item is large relative to mean residual, opening fresh is less bad.
        score -= 30.0 * (item_size as f64 / bin_capacity as f64);
    }

    // Global state: many open bins with high mean residual -> prefer consolidating
    // into bins with residual close to mean (keeps a spread of usable gaps).
    if open_bins_count > 1 {
        let dev = (bin_residual as f64 - mean_residual).abs();
        score += 3.0 * dev / (mean_residual.max(1.0));
    }

    // Prefer bins with small residual overall (pack tight bins first).
    score += 0.15 * (bin_residual as f64 - post_residual as f64);

    // Late-stream consolidation: as the stream ends, avoid opening bins and
    // prefer using up existing space aggressively.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 20.0 * progress * (1.0 - post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;

    // Base: post-residual, non-linearly coupled with stream progress.
    // Early on, prefer filling bins tightly (low post_residual) but keep flexibility;
    // later, tighten more aggressively as remaining stream length shrinks.
    let mut score = pr * (1.0 + 0.8 * progress * norm_pr);

    // Smooth polynomial penalty on very small post-residuals (dead space creation),
    // scaled by how much of the stream remains.
    let dead = (1.0 - norm_pr).powi(3);
    score += 40.0 * dead * (1.0 - progress);

    // Reward bins that can also fit the lookahead item smoothly.
    if next_item_size > 0 && next_item_size <= post_residual {
        score -= 12.0 * (1.0 - (next_item_size as f64 / cap));
    }

    // Last-chance bonus: only one fitting bin -> strongly prefer using it.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0 * (0.5 + 0.5 * progress);
    }

    // Mild preference for bins deviating from mean residual (balance preservation),
    // as a smooth quadratic coupling with open-bin count.
    let dev = (bin_residual as f64 - mean_residual) / cap;
    score += 3.0 * dev * dev * (open_bins_count as f64).ln().max(1.0);

    // Slight bias against opening new bins when many are open and residual is large.
    if bin_residual == bin_capacity {
        score += 6.0 + 10.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the resulting residual: bins whose post_residual falls
    // into "usable" residue classes (multiples of small sizes) are more likely
    // to absorb future items exactly.
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;

    // Reward residuals divisible by common small sizes (harmonic alignment).
    let mut harmony = 0.0;
    for d in [10u32, 20, 25, 50].iter() {
        if post_residual % d == 0 && post_residual > 0 {
            harmony += 6.0;
        }
    }
    score -= harmony;

    // Penalize dead space: residuals below the smallest plausible item.
    if post_residual < 10 && post_residual > 0 {
        score += 25.0;
    }

    // Perfect fit is golden.
    if post_residual == 0 {
        score -= 40.0;
    }

    // Fractional fill of the bin: prefer bins that become well-filled.
    let fill_after = 1.0 - pr / cap;
    score -= 10.0 * fill_after * fill_after;

    // Lookahead: if the next item fits exactly into the post residual, reward strongly.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 30.0;
        } else if next_item_size <= post_residual {
            score -= 8.0;
            // Harmonic check: next item leaves a divisible remainder again.
            if post_residual >= next_item_size && (post_residual - next_item_size) % 10 == 0 {
                score -= 6.0;
            }
        } else {
            // Next item cannot use this bin's remainder; penalize tight leftovers
            // that are smaller than the next item.
            if post_residual < next_item_size {
                score += 5.0;
            }
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate: only attractive when current bins are crowded or fit is poor.
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        let pressure = mean_residual / cap;
        // Penalize opening new bins mildly; escalate when many bins are open but empty.
        score += 18.0;
        if pressure < 0.25 && open_bins_count > 2 {
            score -= 12.0; // existing bins nearly full anyway -> new bin ok
        }
        if next_item_size > 0 && next_item_size >= 70 {
            score -= 10.0; // big item coming, fresh capacity valuable
        }
    }

    // Stream progression: late in the stream, consolidate harder.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 6.0 * progress * (1.0 - fill_after);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps are heavily penalized.
    // A residual gap is "dead" if no plausible future item (>=1, but realistically
    // small items exist) can pair with it. Penalize gaps in the awkward 1..=15 band.
    if post_residual > 0 && post_residual <= 15 {
        score += 40.0 * (1.0 - post_residual as f64 / 16.0);
    }

    // Reward tight fits (small post_residual relative to capacity).
    score -= 0.5 * (bin_capacity - post_residual) as f64 / bin_capacity as f64 * 10.0;

    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 25.0;
    }

    // Lookahead: if the next item fits exactly into the post_residual, reward strongly.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 30.0;
        } else if next_item_size > post_residual {
            // next item cannot use this bin's remainder; penalize leaving large gaps
            // that will strand space.
            score += 0.15 * post_residual as f64;
        }
    }

    // Last-chance pressure: if this is the only fitting bin, strongly prefer using it
    // over opening a new bin (unless the fit is terrible).
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 20.0;
    }

    // Open-bin pressure: many open bins -> discourage spreading; prefer filling
    // existing bins to keep bin count low.
    score += open_bins_count as f64 * 0.8;

    // New-bin candidate handling: an empty bin has maximal residual; make it
    // moderately attractive only when the current fit is bad or no open bin fits well.
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin, offset by how badly other fits would strand space.
        score += 30.0;
        if post_residual >= 20 {
            // A fresh bin leaves a large usable residual: discount it when the item
            // would otherwise create dead space.
            score -= 25.0;
        }
        if next_item_size > 0 && next_item_size <= post_residual {
            score -= 5.0;
        }
    }

    // Progress coupling: late in the stream, avoid leaving residual gaps since
    // fewer items remain to fill them.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += progress * post_residual as f64 * 0.3;

    // Mean residual coupling: if open bins already hold lots of slack, prefer
    // compacting into this bin rather than leaving more slack around.
    if mean_residual > 0.0 {
        score += (mean_residual - post_residual as f64).abs() * 0.05;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let score = (post_residual as f64) * 0.84;
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect lookahead match: post_residual exactly equals next item size
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 60.0;
    }
    // Near match: next item fits with small leftover
    else if next_item_size > 0 && post_residual >= next_item_size {
        let leftover_after_next = (post_residual - next_item_size) as f64;
        score -= 25.0 - leftover_after_next * 0.6;
    }
    // Next item does NOT fit in residual: penalize proportionally to wasted potential
    else if next_item_size > post_residual {
        score += 12.0;
    }

    // Penalize creating unusable dead space (residual below minimum item size 1..10 zone)
    if post_residual < 10 && post_residual > 0 {
        score += 8.0;
    }

    // Relative to mean residual: prefer bins tighter/looser than average adaptively
    score += (post_residual as f64 - mean_residual) * 0.35;

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 20.0;
    }

    // New-bin candidate: only attractive when current bin fit is poor
    if bin_residual == bin_capacity {
        // Baseline new-bin score slightly above a decent fit's post_residual
        score = 45.0;
        if next_item_size > 0 {
            // new bin will have plenty of room for the next item
            score -= 10.0;
        }
        // As stream progresses, prefer consolidating into open bins
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 15.0 * progress;
        // Many open bins already: discourage opening more
        score += open_bins_count as f64 * 1.5;
        // If this is the only fitting bin (none fit), new bin is necessary
        if fitting_bins_count == 0 {
            score -= 100.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Prefer tight fits: reward small post_residual relative to item size.
    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 30.0 * fit_ratio;

    // Penalize dead space: post_residual below next item size is likely wasted.
    if next_item_size > 0 && (post_residual as u32) < next_item_size {
        score += 0.5 * (next_item_size - post_residual) as f64;
    }
    // Reward if next item fits exactly in the leftover space.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 15.0;
    }

    // Last-chance bonus: if this is the only fitting bin, strongly prefer using it.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate handling: only open a new bin when fits are poor or crowded.
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let crowd = open_bins_count as f64 / (mean_residual / bin_capacity as f64).max(0.1);
        score += 40.0 - 10.0 * progress + 2.0 * crowd;
        // Opening a new bin is attractive if the item is large and mean residual is low.
        score -= 0.3 * item_size as f64;
    }

    // Global pressure: many open bins with high mean residual -> encourage consolidation.
    score += 0.05 * open_bins_count as f64;
    score -= 0.1 * mean_residual;

    // Dynamic time horizon: early stream, be greedy on tightness; late stream, minimize waste.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score *= 1.0 + 0.5 * progress * (1.0 - fit_ratio);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;

    // Base: quadratic penalty on post residual (prefer tight fits)
    let mut score = pr * (1.0 + norm_pr);

    // Smooth non-linear coupling with stream progress:
    // early on, be more tolerant of residual; late, demand tightness.
    let prog_coupling = norm_pr * (1.0 - progress) * (1.0 - progress) * cap * 0.5;
    score += prog_coupling;

    // Reward bins whose residual closely matches next item (lookahead synergy)
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        let diff = (pr - nx) / cap;
        score -= (1.0 - diff * diff) * nx * 0.3;
    } else {
        // last item: strongly reward minimal residual
        score -= cap * 0.25 * (1.0 - norm_pr);
    }

    // Last-chance bin bonus: if this is the only fitting bin, prefer using it
    if fitting_bins_count == 1 {
        score -= cap * 0.6 * (1.0 - progress);
    }

    // Penalize opening new bins when many bins already fit the item
    if bin_residual == bin_capacity {
        score += cap * (0.5 + 0.5 * progress) + open_bins_count as f64 * 2.0;
    }

    // Mild deviation penalty from mean residual to balance bin loads
    let dev = (pr - mean_residual) / cap;
    score += dev * dev * cap * 0.15;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
