pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: bins whose leftover falls into "useful"
    // residue classes (divisible by common item sizes) are more valuable.
    let cap = bin_capacity as f64;

    // Reward small post_residual (tight fit), but reward "clean" leftovers more.
    if post_residual == 0 {
        score -= 60.0; // perfect closure
    } else {
        // Harmonic bonus: leftover divisible by 10, 20, 25, 50 is reusable.
        let mut harmonic_bonus = 0.0;
        if post_residual % 10 == 0 { harmonic_bonus += 2.0; }
        if post_residual % 20 == 0 { harmonic_bonus += 2.0; }
        if post_residual % 25 == 0 { harmonic_bonus += 2.5; }
        if post_residual % 50 == 0 { harmonic_bonus += 3.0; }
        score -= harmonic_bonus;

        // Penalize dead space: leftover too small for the smallest plausible item.
        if post_residual < 10 {
            score += 25.0 * (10 - post_residual) as f64;
        }

        // Penalize awkward leftover: not divisible by 5 (odd residue classes).
        if post_residual % 5 != 0 {
            score += 6.0;
        }
    }

    // Lookahead coupling: if next item fits exactly in post_residual, big reward.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 40.0;
        } else if next_item_size < post_residual {
            // Prefer leaving room for next item; reward proportional closeness.
            let slack = (post_residual - next_item_size) as f64;
            score -= 15.0 * (1.0 - slack / cap).max(0.0);
        } else {
            // Next item won't fit here; slight penalty for blocking.
            score += 5.0;
        }
    }

    // Last-chance bin: strongly favor using the only bin that fits.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate handling: penalize opening a new bin unless current
    // residuals are all large (item would waste little in an existing bin).
    if bin_residual == bin_capacity {
        // Base cost of a fresh bin: its "score" is full capacity.
        // Discount it when stream is late or many bins already open poorly fit.
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score -= 10.0 + 20.0 * progress;
        // If mean residual is small, existing bins are nearly full -> new bin ok.
        if mean_residual < item_size as f64 * 1.2 {
            score -= 25.0;
        }
    } else {
        // Using an existing bin conserves bins; reward fraction of bin filled.
        let fill_frac = item_size as f64 / cap;
        score -= 12.0 * fill_frac;
    }

    // Mild preference for balancing open bins count downward.
    score += 0.05 * open_bins_count as f64;

    // Integer-division threshold on post_residual tiers.
    let tier = post_residual / 25; // 0..4 harmonic tiers
    score -= tier as f64 * 1.5;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap_f = bin_capacity as f64;
    let progress = step_index as f64 / total_items.max(1) as f64;
    let mut score = post_residual as f64;

    // Tiered dead-space avoidance (strengthened)
    if post_residual == 0 {
        score -= 900.0; // perfect fit
    } else if post_residual <= 3 {
        score -= 400.0;
    } else if post_residual <= 12 {
        score -= 80.0;
    } else if post_residual < 20 {
        score += 18.0;
    } else if post_residual < 30 {
        score += 12.0 + (30 - post_residual) as f64 * 0.5;
    }

    let dead_ratio = post_residual as f64 / cap_f;
    if dead_ratio < 0.03 {
        score -= 35.0;
    } else if dead_ratio > 0.35 {
        score += 22.0;
    } else if dead_ratio > 0.25 {
        score += 10.0;
    }

    // Lookahead: exact and near-exact fits for the next item
    if next_item_size > 0 {
        let n = next_item_size as u32;
        if n == post_residual {
            score -= 700.0;
        } else if n <= post_residual {
            let post2 = post_residual - n;
            score -= 110.0 - (post2 as f64) * 2.0;
            if post2 == 0 { score -= 90.0; }
            if post2 > 0 && post2 < 5 { score -= 25.0; }
            if post2 % 10 == 0 && post2 > 0 { score -= 20.0; }
            if post_residual % n == 0 { score -= 15.0; }
            if post_residual >= n * 2 && post_residual - n * 2 <= 4 { score -= 18.0; }
            let chain = post_residual / n;
            if chain >= 2 { score -= (chain.min(4)) as f64 * 6.0; }
            if post2 > 0 && post2 <= n / 4 { score -= 10.0; }
        } else {
            // next item won't fit here: penalize leaving a nearly-fitting gap
            let gap = next_item_size - post_residual;
            if post_residual > 0 {
                if gap <= 3 { score += 35.0; }
                else if gap <= 8 { score += 12.0; }
                if (gap as f64) > mean_residual * 0.5 { score += 12.0; }
                if post_residual < 15 { score += 35.0; }
                score += gap as f64 * 0.5;
            }
        }
    }

    // Compaction pressure scaled by open bins
    score += open_bins_count as f64 * 0.8;

    // Last-chance bin: strongly favor using it
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 50.0;
    }

    // Tightness via relative fill
    let snug = item_size as f64 / bin_residual.max(1) as f64;
    score -= snug * 30.0;
    if snug > 0.97 { score -= 12.0; }

    // NEW-BIN CANDIDATE handling
    if bin_residual == bin_capacity {
        let newbin_waste = (bin_capacity - item_size) as f64;
        let avg_fill = 1.0 - (mean_residual / cap_f);
        score += 230.0 - avg_fill * 300.0 - progress * 70.0;
        // big items deserve a fresh bin when few alternatives fit well
        if item_size >= bin_capacity * 3 / 4 { score -= 55.0; }
        if item_size as f64 > mean_residual { score -= 35.0; }
        if newbin_waste < mean_residual * 0.5 { score -= 30.0; }
        if bin_capacity - item_size <= 4 { score -= 60.0; }
        if next_item_size > 0 {
            let leftover = bin_capacity - item_size;
            if leftover >= next_item_size && leftover - next_item_size <= 6 {
                score -= 38.0; // fresh bin pairs perfectly with next item
            }
            if leftover >= next_item_size {
                let tail = leftover % next_item_size;
                if tail == 0 { score -= 18.0; }
                else if tail <= 4 { score -= 14.0; }
                if leftover >= next_item_size * 2 { score -= 12.0; }
            } else if leftover < 10 {
                score += 18.0;
            }
            if next_item_size >= bin_capacity / 2 { score -= 25.0; }
        }
        if fitting_bins_count > 3 { score += (fitting_bins_count.min(6) as f64) * 7.0; }
        // late stream: penalize opening bins with big waste
        if progress > 0.6 {
            let waste_tol = (1.0 - progress) * cap_f * 0.35;
            if newbin_waste > waste_tol && fitting_bins_count > 0 {
                score += 12.0 + progress * 25.0;
            }
        }
        if progress < 0.1 { score -= 5.0; }
    } else {
        // Prefer bins whose residual is below average (consolidating slack)
        score += (mean_residual - bin_residual as f64) * 1.2;
        if bin_residual as f64 > cap_f * 0.6 { score -= 10.0; }
        if item_size == bin_residual { score -= 40.0; }
        if post_residual > 0 && next_item_size > 0 && post_residual < next_item_size {
            let wasted = next_item_size as f64 - post_residual as f64;
            score += wasted * 0.6 + (1.0 - progress) * 12.0;
        }
        if fitting_bins_count <= 2 && post_residual > 0 { score -= 8.0; }
    }

    // Mild progress-based diversity nudge for open bins
    if progress < 0.1 { score += 3.0; }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: tiny leftover gaps are nearly useless.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    }
    // Perfect fit: strong reward.
    if post_residual == 0 {
        score -= 25.0;
    }

    // Reward leaving room for the lookahead item (k=2 lookahead).
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 20.0;
        } else if post_residual >= next_item_size {
            score -= 6.0 * (post_residual as f64 / (post_residual + next_item_size) as f64);
        } else {
            // post_residual can't hold next item: penalize proportionally to wasted lookahead
            score += 8.0 * (1.0 - post_residual as f64 / next_item_size as f64);
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 15.0;
    }

    // Open-bins pressure: with many open bins, prefer filling existing ones.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += open_bins_count as f64 * (0.4 + 0.6 * progress);

    // Relative fill quality vs mean residual: tighter-than-average bins preferred.
    score -= (bin_residual as f64 - mean_residual) * 0.3;

    // New-bin candidate: only attractive when no decent fit exists.
    if bin_residual == bin_capacity {
        let decent_fit_exists = post_residual as f64 <= mean_residual * 0.5;
        if decent_fit_exists {
            score += 120.0; // discourage opening new bin when a tight fit exists
        } else {
            score -= 5.0; // slight encouragement to open a fresh bin
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward perfect or near-perfect fits strongly.
    if post_residual == 0 {
        score -= 1000.0;
    } else if post_residual <= 5 {
        score -= 300.0;
    }

    // 2-step lookahead: reward bins whose post_residual matches next_item_size.
    if next_item_size > 0 {
        let diff = (post_residual as i64 - next_item_size as i64).abs() as f64;
        score -= 250.0 / (1.0 + diff);
        if post_residual == next_item_size {
            score -= 400.0;
        }
        // Penalize leaving a dead space smaller than the smallest plausible item
        if post_residual < next_item_size && post_residual < 10 {
            score += 200.0;
        }
        // If next item won't fit here either way, mild penalty for wasting this bin
        if next_item_size > bin_residual {
            score += 20.0;
        }
    }

    // Relative-to-mean coupling: bins tighter than mean are more valuable to fill now.
    score -= 0.5 * (mean_residual - bin_residual as f64);

    // Last-chance bonus: if this is the only bin that fits, strongly prefer it.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 150.0;
    }

    // Penalize opening new bins when open bins fit comfortably.
    if bin_residual == bin_capacity {
        score += 120.0 + 3.0 * open_bins_count as f64;
    } else {
        score += 10.0 * open_bins_count as f64;
    }

    // Early in stream: be less picky, fill bins greedily; late: conserve quality.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 50.0 * progress;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits (low post residual) more aggressively via non-linear coupling
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 12.0 * tightness * tightness;

    // Penalize dead space that cannot fit a typical future item
    if post_residual > 0 && post_residual < 10 {
        score += 25.0; // unusable sliver
    }

    // Last-chance bonus: if this is the only bin that fits, strongly favor it
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 40.0;
    }

    // Lookahead: reward if next item fits into post residual (chaining)
    if next_item_size > 0 {
        if post_residual >= next_item_size {
