    let residual_gap = mean_residual - bin_residual as f64;
    score += 0.15 * residual_gap;

    // When open bins are numerous, discourage opening new bins
    let new_bin_candidate = bin_residual == bin_capacity;
    if new_bin_candidate {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let open_pressure = open_bins_count as f64 / 10.0;
        score += 20.0 + 15.0 * open_pressure * (1.0 - progress);
