        if post_residual > 60 && fitting_bins_count > 2 {
            score -= 30.0;
        }
    }

    // Time horizon: late in stream, be conservative, prefer filling existing bins
    let progress = step_index as f64 / total_items.max(1) as f64;
    if !new_bin_candidate {
        score -= 10.0 * progress * tightness;
    }

    score
}

