pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;
    let norm_item = item_size as f64 / cap;
    let mut score = pr;

    // Non-linear polynomial coupling of post_residual with stream progress
    let poly = norm_pr * norm_pr * (1.0 + 3.0 * progress) - 0.5 * norm_pr * norm_item * progress;
    score += 8.0 * poly;

    // Reward tight fits, scaled by progress
    score -= (1.0 - norm_pr) * (1.0 - norm_pr) * (4.0 + 6.0 * progress);

    // Dead-space penalty: residuals too small for typical items, smoothed via cubic
    let dead = if pr > 0.0 { (1.0 - norm_pr / (80.0 / cap)) } else { 1.0 };
    let dead_cubed = dead * dead * dead;
    score += 6.0 * dead_cubed * norm_pr * (1.0 - progress);

    // Last-chance bonus
    if fitting_bins_count == 1 {
        score -= 5.0 + 10.0 * progress;
    }

    // Lookahead coupling: favor bins whose post residual matches next item
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        let match_term = 1.0 - (pr - nxt).abs() / cap;
        score -= 3.0 * match_term * match_term * (1.0 - progress);
    }

    // Open bins pressure: mildly discourage spreading when many bins open
    score += 0.3 * (open_bins_count as f64).ln().max(0.0) * (1.0 - progress);

    // Mean residual coupling
    score += 0.05 * (mean_residual - pr);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap_f = bin_capacity as f64;
    let mut score = post_residual as f64;
    let quarter = bin_capacity / 4;
    let half = bin_capacity / 2;
    let post = post_residual;

    if post == 0 {
        score -= 1000.0;
    } else if post <= 3 {
        score -= 200.0;
    } else if post < quarter {
        score += 30.0;
        if next_item_size > post {
            score += 20.0;
        }
    } else if post < half {
        score += 5.0;
    } else {
        score -= 10.0;
    }

    if post % 10 == 0 && post > 0 {
        score -= 8.0;
    }
    if post % 20 == 0 && post > 0 {
        score -= 4.0;
    }

    if next_item_size > 0 {
        if next_item_size == post {
            score -= 200.0;
        } else if next_item_size <= post {
            let slack = post - next_item_size;
            if slack < quarter {
                score -= 15.0;
            } else {
                score -= 3.0;
            }
            if post % next_item_size == 0 {
                score -= 18.0;
            }
            if slack > 0 && slack <= 2 {
                score -= 14.0;
            }
            let chain = post / next_item_size;
            if chain >= 2 {
                score -= (chain.min(4)) as f64 * 6.0;
            }
        } else {
            score += 10.0;
            let gap = next_item_size - post;
            if gap <= 3 {
                score += 35.0;
            } else if gap <= 8 {
                score += 12.0;
            }
            if post > 0 && post < 15 {
                score += 45.0;
            }
        }
    }

    if fitting_bins_count == 1 {
        score -= 25.0;
    }

    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let avg_fill = 1.0 - (mean_residual / cap_f);
        score += 250.0 - avg_fill * 330.0 - progress * 65.0;
        if item_size as f64 > mean_residual {
            score -= 45.0;
        }
        if fitting_bins_count > 0 {
            score += fitting_bins_count.min(5) as f64 * 9.0 + 20.0;
            let snug = item_size as f64 / bin_residual.max(1) as f64;
            if snug > 0.9 {
                score += 40.0;
            }
            if snug > 0.95 {
                score += 28.0;
            }
        }
        if next_item_size > 0 && next_item_size >= bin_capacity / 2 {
            score -= 32.0;
        }
        if item_size >= bin_capacity * 3 / 4 {
            score -= 55.0;
        }
        let leftover = bin_capacity - item_size;
        if next_item_size > 0 && leftover >= next_item_size {
            score -= 25.0;
            let tail = leftover % next_item_size;
            if tail == 0 {
                score -= 10.0;
            } else if tail <= 4 {
                score -= 16.0;
            }
        }
        let newbin_waste = leftover as f64;
        if newbin_waste > 0.0 && newbin_waste < mean_residual * 0.6 {
            score -= 30.0;
        }
        if progress > 0.6 && fitting_bins_count > 0 {
            let waste_tol = (1.0 - progress) * cap_f * 0.35;
            if newbin_waste > waste_tol {
                score += 10.0 + progress * 22.0;
            }
        }
        if newbin_waste > 0.0 && (newbin_waste as u32) < next_item_size && newbin_waste < cap_f * 0.12 {
            score += 26.0;
        }
    } else {
        let tightness = 1.0 - (item_size as f64 / bin_residual.max(1) as f64);
        score += tightness * 85.0;
        score += (mean_residual - bin_residual as f64) * 1.5;
        let dead_ratio = post as f64 / cap_f;
        if dead_ratio < 0.03 {
            score -= 38.0;
        } else if dead_ratio < 0.08 {
            score -= 14.0;
        } else if dead_ratio > 0.35 {
            score += 24.0;
        } else if dead_ratio > 0.25 {
            score += 10.0;
        }
        if post > 0 && post < 6 {
            score -= 22.0;
        }
        if post > 0 && (post as f64) < mean_residual * 0.25 {
            score -= 15.0;
        }
        if item_size == bin_residual {
            score -= 45.0;
        }
        if post > 0 && next_item_size > 0 && post < next_item_size {
            let wasted = next_item_size as f64 - post as f64;
            score += wasted * 0.6;
        }
        if post > 0 && next_item_size > 0 && post >= next_item_size {
            let slack = post - next_item_size;
            if slack > 0 && slack < next_item_size && (slack as f64) < cap_f * 0.02 {
                score -= 14.0;
            }
        }
        if post > 0 && (post as f64) < cap_f * 0.015 {
            score -= 18.0;
        }
        let progress = step_index as f64 / total_items.max(1) as f64;
        if post > 0 && next_item_size > 0 && post < next_item_size {
            score += (1.0 - progress) * 14.0;
        }
        if post > 0 && (post as f64) > mean_residual * 1.6 && fitting_bins_count > 2 {
            score += 10.0;
        }
        if post > 0 && next_item_size > 0 {
            let unusable = post < next_item_size && (next_item_size - post) > 12;
            if unusable {
                score += dead_ratio * 90.0;
            } else {
                let reuse = (post / next_item_size) as f64 * (next_item_size as f64 / cap_f);
                score -= reuse * 22.0;
            }
        }
        if post > 0 && fitting_bins_count <= 2 {
            score -= 8.0;
        }
    }

    if mean_residual > cap_f * 0.6 && open_bins_count > 3 {
        score += 3.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the leftover space: residual mod 25 buckets
    let class = post_residual % 25;
    // Small classes are "dead space" -> penalize; class 0 (perfect fill) -> reward
    if post_residual == 0 {
        score -= 60.0; // perfect fill
    } else if class == 0 {
        score -= 12.0; // leftover is a multiple of 25, likely reusable
    } else if class >= 20 {
        score -= 6.0;  // large leftover chunk, fairly reusable
    } else if class <= 5 {
        score += 10.0 + (5 - class) as f64; // tiny sliver: dead space penalty
    }

    // Lookahead coupling: if next item fits exactly into post_residual, big reward
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 45.0;
        } else if next_item_size < post_residual {
            let nxt_class = (post_residual - next_item_size) % 25;
            if nxt_class == 0 { score -= 15.0; }
            else if nxt_class <= 5 { score += 8.0; }
            // harmonic divisibility: next item divides leftover nicely
            if post_residual % next_item_size.max(1) == 0 {
                score -= 10.0;
            }
        } else {
            // next item cannot fit here regardless; slight penalty for tight bins
            score += 3.0;
        }
    }

    // Last-chance bin: strongly favor using it before opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate handling: neutral baseline, penalize opening new bins
    // unless current fit is terrible (large post_residual) or many bins open
    if bin_residual == bin_capacity {
        // base cost of a fresh bin: its full residual, slightly discounted
        score = post_residual as f64 - 5.0;
        // opening new bins is costly when few bins are open
        score += 15.0 + (open_bins_count as f64).sqrt() * 2.0;
        // if the fit into some open bin would leave almost nothing, discourage new bin
        if post_residual >= 40 && fitting_bins_count > 0 {
            score += 10.0;
        }
    }

    // Prefer tighter fits relative to mean residual of open bins
    score += (post_residual as f64 - mean_residual).max(0.0) * 0.15;

    // Early in the stream, be slightly more willing to spread items (explore)
    let progress = step_index as f64 / (total_items.max(1) as f64);
    if progress < 0.2 && bin_residual == bin_capacity {
        score -= 5.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
