pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect 2-step lookahead match: post_residual exactly equals next item size.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 1000.0;
    }
    // Next item fits with small leftover: strong reward.
    if next_item_size > 0 && post_residual >= next_item_size {
        let slack = (post_residual - next_item_size) as f64;
        score -= 200.0 - slack * 2.0;
    }
    // Next item does NOT fit in the leftover: penalize dead space proportional to gap.
    if next_item_size > 0 && post_residual < next_item_size {
        let gap = (next_item_size - post_residual) as f64;
        score += gap * 1.5;
        // Tiny unusable leftover is very bad.
        if post_residual < 10 {
            score += 50.0;
        }
    }

    // Reward tightening relative to mean residual (best-fit style coupling).
    score -= (mean_residual - post_residual as f64) * 0.5;

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 300.0;
    }

    // New-bin candidate: penalize opening a new bin, more when other bins fit the item
    // or when the stream is late and open bins exist.
    if bin_residual == bin_capacity {
        score += 400.0;
        if fitting_bins_count > 1 {
            score += 200.0;
        }
        // Early stream: opening bins is cheaper; late stream: consolidate.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += (1.0 - progress) * 100.0;
        // If next item is large, an empty bin is actually useful.
        if next_item_size >= 60 {
            score -= 150.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
