    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 40.0;
    }

    // Prefer bins with smaller residuals among fitting bins (best-fit coupling).
    if bin_residual < bin_capacity {
        score -= 10.0 * (1.0 - bin_residual as f64 / bin_capacity as f64);
    }

    // New-bin candidate handling: penalize opening a new bin unless nothing fits well.
    if bin_residual == bin_capacity {
