        score += 35.0 + 2.0 * pressure;
        if next_item_size > 0 && post_residual >= next_item_size {
            score -= 5.0;
        }
        // If other bins can fit the item, make new bin less attractive unless their fits are bad.
        if fitting_bins_count > 0 {
            score += 20.0;
        }
    }

    // Global state: many open bins with high mean residual -> encourage consolidating into existing bins.
    let consolidation_bonus = (mean_residual / bin_capacity as f64) * (open_bins_count as f64).ln().max(0.0);
    if bin_residual < bin_capacity {
        score -= 3.0 * consolidation_bonus;
    }

    // Time horizon: late in the stream, waste matters more.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += 10.0 * progress * (post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap_f = bin_capacity as f64;
    let progress = step_index as f64 / total_items.max(1) as f64;
    let mut score = post_residual as f64;

    // Dead-space avoidance (tiered, strengthened)
    if post_residual == 0 {
        score -= 900.0; // perfect fit
    } else if post_residual <= 3 {
        score -= 380.0;
    } else if post_residual <= 12 {
        score -= 60.0;
    } else if post_residual < 20 {
        score += 18.0;
    } else if post_residual < 30 {
        score += 18.0 + (30 - post_residual) as f64 * 0.6;
    }

    // Lookahead: exact and near-exact fits for the next item
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 700.0;
        } else if next_item_size <= post_residual {
            let post2 = post_residual - next_item_size;
            score -= 110.0 - (post2 as f64) * 2.0;
            if post2 == 0 { score -= 90.0; }
            if post2 > 0 && post2 < 5 { score -= 26.0; }
            if post2 % 10 == 0 && post2 > 0 { score -= 20.0; }
            if post2 > 0 && post2 <= next_item_size / 4 { score -= 10.0; }
            if post_residual >= next_item_size * 2 && post_residual - next_item_size * 2 <= 4 {
                score -= 18.0;
            }
            let chain = post_residual / next_item_size;
            if chain >= 2 { score -= (chain.min(4)) as f64 * 6.0; }
            if post_residual % next_item_size == 0 { score -= 14.0; }
        } else {
            let gap = next_item_size - post_residual;
            if post_residual > 0 {
                if gap <= 3 { score += 35.0; }
                else if gap <= 8 { score += 12.0; }
                if (gap as f64) > mean_residual * 0.5 { score += 12.0; }
                if post_residual < 15 { score += 30.0; }
            }
        }
    }

    // Compaction pressure scaled by open bins
    score += open_bins_count as f64 * 0.8;

    // Last-chance bin: strongly favor using it
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 55.0;
    }

    // Tightness via relative fill
    score -= (item_size as f64 / bin_residual.max(1) as f64) * 30.0;

    // Dead-ratio shaping for open bins
    if bin_residual < bin_capacity {
        let dead_ratio = post_residual as f64 / cap_f;
        if dead_ratio < 0.03 { score -= 30.0; }
        else if dead_ratio < 0.08 { score -= 12.0; }
        else if dead_ratio > 0.35 { score += 22.0; }
        else if dead_ratio > 0.25 { score += 10.0; }
        if post_residual > 0 && next_item_size > 0 && post_residual < next_item_size {
            let wasted = next_item_size as f64 - post_residual as f64;
            score += wasted * 0.6;
            if wasted > 12.0 { score += dead_ratio * 60.0; }
        }
        score += (mean_residual - bin_residual as f64) * 1.2;
        if item_size == bin_residual { score -= 40.0; }
    }

    // NEW-BIN CANDIDATE handling
    if bin_residual == bin_capacity {
        let avg_fill = 1.0 - (mean_residual / cap_f);
        let newbin_waste = (bin_capacity - item_size) as f64;
        score += 240.0 - avg_fill * 320.0 - progress * 65.0;
        if item_size as f64 / cap_f > 0.75 { score -= 55.0; }
        if item_size >= bin_capacity * 3 / 4 { score -= 30.0; }
        if bin_capacity - item_size <= 4 { score -= 70.0; }
        if item_size as f64 > mean_residual { score -= 35.0; }
        if newbin_waste < mean_residual * 0.5 { score -= 30.0; }
        if next_item_size > 0 {
            let leftover = bin_capacity - item_size;
            if leftover >= next_item_size {
                let tail = leftover % next_item_size;
                if tail == 0 { score -= 22.0; }
                else if tail <= 4 { score -= 14.0; }
                if leftover - next_item_size <= 6 { score -= 35.0; }
                if leftover >= next_item_size * 2 { score -= 12.0; }
            } else if leftover < 10 {
                score += 18.0;
            }
            if next_item_size >= bin_capacity / 2 { score -= 28.0; }
        }
        if fitting_bins_count > 0 {
            score += (fitting_bins_count.min(6) as f64) * 8.0;
            let snug = item_size as f64 / cap_f;
            if snug > 0.9 { score += 30.0; }
            if snug > 0.95 { score += 20.0; }
        }
        if fitting_bins_count > 3 && item_size as f64 / cap_f < 0.5 { score += 30.0; }
        if progress > 0.6 {
            let waste_tol = (1.0 - progress) * cap_f * 0.35;
            if newbin_waste > waste_tol && fitting_bins_count > 0 {
                score += 10.0 + progress * 22.0;
            }
        }
        if newbin_waste > 0.0 && (newbin_waste as u32) < next_item_size && newbin_waste < cap_f * 0.12 {
            score += 26.0;
        }
        if progress < 0.1 { score -= 5.0; }
    }

    // Mild progress-based diversity nudge for open bins
    if progress < 0.1 && bin_residual < bin_capacity { score += 3.0; }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let mut score = post;

    // Non-linear coupling: waste matters more later in the stream.
    let waste_weight = 1.0 + 2.0 * progress * progress;
    score += waste_weight * (post / cap) * (post / cap) * 10.0;

    // Reward tight fits (post_residual near zero) with smooth saturation.
    let tightness = (-post / cap).exp();
    score -= 15.0 * tightness * (0.5 + progress);

    // Penalize bins with residual far below item size already handled implicitly;
    // penalize bins whose residual deviates strongly from mean residual.
    let dev = (bin_residual as f64 - mean_residual).abs() / cap;
    score += 5.0 * dev * (1.0 - progress);

    // Last-chance bonus: if this is the only fitting bin, strongly prefer using it.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // New-bin candidate handling: opening a bin is cheap early, expensive late.
    if bin_residual == bin_capacity {
        let new_bin_penalty = 8.0 + 30.0 * progress + 0.5 * open_bins_count as f64;
        // If lookahead item could use leftover space, soften penalty.
        if next_item_size > 0 && (post_residual as u32) >= next_item_size {
            score += new_bin_penalty * 0.5;
        } else {
            score += new_bin_penalty;
        }
    }

    // Lookahead coupling: prefer bins whose post residual still fits the next item.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 6.0 * (1.0 - (post - next_item_size as f64) / cap);
    } else if next_item_size > 0 {
        score += 3.0 * progress;
    }

    // Mild pressure to consolidate when many bins are open.
    score += 0.3 * open_bins_count as f64 * progress;

    score
}

