pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: classify by integer division thresholds
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let frac = pr / cap; // residual fraction of capacity

    // Class boundaries: residual classes (0-10 dead, 11-30 poor, 31-60 usable, 61-100 good)
    let class = post_residual / 10; // 0..10 harmonic class index
    let class_bonus: f64 = match class {
        0 => 25.0,                 // near-perfect fit
        1 => 18.0,                 // excellent
        2 => 12.0,
        3 => 6.0,
        4 => 0.0,
        5 => -4.0,
        6 => -8.0,
        7 => -12.0,
        8 => -18.0,
        9 => -25.0,                // half-empty bin
        _ => -30.0,                // mostly empty
    };
    score -= class_bonus;

    // Modulo coupling: post_residual divisible chunks harmonize with next item
    if next_item_size > 0 {
        let nxt = next_item_size;
        if post_residual >= nxt {
            // next item fits here: strong reward, scaled by how snugly
            let slack_after_next = post_residual - nxt;
            score -= 10.0 + (slack_after_next as f64).min(40.0) * -0.1;
        } else {
            // next item cannot follow into this residual
            score += 6.0;
            // penalize residuals that waste mod-10 harmony
            if post_residual % 10 != 0 && post_residual > nxt {
                score += 3.0;
            }
        }
        // harmonic class match: residual class equals next-size class
        if post_residual / 10 == nxt / 10 && post_residual >= nxt {
            score -= 8.0;
        }
    }

    // Last-chance bin: must use it or open a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate handling
    if bin_residual == bin_capacity {
        // Opening a new bin: base penalty so existing bins are preferred
        let mut new_bin_score = 55.0 + frac * 40.0; // empty residual = 100 => high
        // But if item leaves a large residual that nothing else could use, new bin is fine
        if fitting_bins_count == 0 {
            new_bin_score -= 100.0;
        }
        // Late in stream, prefer closing out existing bins
        let progress = step_index as f64 / total_items.max(1) as f64;
        new_bin_score += progress * 10.0;
        // Many open bins: discourage opening more
        new_bin_score += (open_bins_count as f64).sqrt() * 4.0;
        score = new_bin_score;
    }

    // Mild preference for bins tighter than the mean residual (good packing)
    if bin_residual < bin_capacity {
        score += (mean_residual - bin_residual as f64) * 0.05;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals that are too small to hold any
    // plausible future item are pure waste -> penalize them heavily.
    let min_item = 1.0f64;
    if (post_residual as f64) < min_item.max(next_item_size as f64) {
        // gap below next item size: dead space unless next item is 0/last
        if next_item_size > 0 {
            score += 25.0;
        }
    }
    // Very tight gaps (near zero) are the worst kind of dead space.
    if post_residual <= 3 {
        score += 40.0;
    }

    // Reward tight fits (low post_residual relative to item size).
    let fit_ratio = post_residual as f64 / bin_residual.max(1) as f64;
    score -= 20.0 * (1.0 - fit_ratio);

    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 60.0;
    }

    // Lookahead: if the next item fits exactly in the post residual, reward.
    if next_item_size > 0 && next_item_size <= post_residual {
        let slack = (post_residual - next_item_size) as f64;
        score -= 15.0 * (1.0 - slack / bin_capacity as f64);
    } else if next_item_size > post_residual && next_item_size > 0 {
        // next item cannot follow here -> mild penalty proportional to gap
        score += 5.0;
    }

    // Open-bin pressure: with many open bins, prefer consolidating into
    // existing ones; opening new bins should get progressively worse.
    let progress = step_index as f64 / total_items.max(1) as f64;
    let new_bin_penalty = 8.0 + 12.0 * progress + 0.6 * open_bins_count as f64;
    if bin_residual == bin_capacity {
        // Candidate is a brand-new empty bin.
        score += new_bin_penalty;
        // Only attractive if existing bins would leave bad dead space.
        score -= 5.0 * (1.0 - fit_ratio.min(1.0));
    } else {
        // Existing bin: reward using it, more so when bins are many.
        score -= 0.3 * open_bins_count as f64;
    }

    // Last-chance bin: if this is the only bin that fits, strongly prefer it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // Align with global mean residual: bins far below mean residual are
    // already tight; prefer bins whose residual is close to the item need.
    score += 0.1 * (mean_residual - bin_residual as f64).abs();

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap_f = bin_capacity as f64;
    let progress = step_index as f64 / total_items.max(1) as f64;
    let mut score = post_residual as f64;

    // Dead-space avoidance: stronger tiered penalties (borrowed from best)
    if post_residual == 0 {
        score -= 900.0;
    } else if post_residual <= 3 {
        score -= 400.0;
    } else if post_residual <= 12 {
        score -= 80.0;
    } else if post_residual < 20 {
        score += 18.0;
    } else if post_residual < 30 {
        score += 18.0 + (30 - post_residual) as f64 * 0.6;
    }

    // Lookahead: exact and near-exact fits for the next item
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 700.0;
        } else if next_item_size <= post_residual {
            let post2 = post_residual - next_item_size;
            score -= 120.0 - (post2 as f64) * 2.0;
            if post2 == 0 { score -= 90.0; }
            if post2 > 0 && post2 < 5 { score -= 28.0; }
            if post2 % 10 == 0 && post2 > 0 { score -= 22.0; }
            if post_residual >= next_item_size * 2 && post_residual - next_item_size * 2 <= 4 {
                score -= 20.0;
            }
            if post_residual % next_item_size == 0 { score -= 15.0; }
            let chain = post_residual / next_item_size;
            if chain >= 2 { score -= (chain.min(4)) as f64 * 6.0; }
            if post2 > 0 && post2 <= next_item_size / 4 { score -= 10.0; }
        } else {
            // next item won't fit here: penalize leaving a nearly-fitting gap
            let gap = next_item_size - post_residual;
            if post_residual > 0 {
                if gap <= 3 { score += 35.0; }
                else if gap <= 8 { score += 12.0; }
                if (gap as f64) > mean_residual * 0.5 { score += 14.0; }
                if gap <= 5 { score += (6 - gap) as f64 * 4.0; }
            }
            if post_residual > 0 && post_residual < 15 {
                score += 45.0;
            }
        }
    }

    // Compaction pressure scaled by open bins
    score += open_bins_count as f64 * 0.8;

    // Last-chance bin: strongly favor using it
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 50.0;
    }

    // Tightness via relative fill
    let snug = item_size as f64 / bin_residual.max(1) as f64;
    score -= snug * 30.0;
    if snug > 0.97 && post_residual >= next_item_size { score -= 14.0; }

    // Consolidate slack: prefer bins whose residual is below average
    if bin_residual < bin_capacity {
        score += (mean_residual - bin_residual as f64) * 1.2;
        let dead_ratio = post_residual as f64 / cap_f;
        if dead_ratio < 0.03 { score -= 30.0; }
        else if dead_ratio > 0.30 { score += 20.0; }
    }

    // NEW-BIN CANDIDATE handling
    if bin_residual == bin_capacity {
        let avg_fill = 1.0 - (mean_residual / cap_f);
        score += 220.0 - avg_fill * 300.0 - progress * 60.0;
        let newbin_waste = (bin_capacity - item_size) as f64;
        // big items deserve a fresh bin when few alternatives fit well
        if item_size as f64 / cap_f > 0.75 { score -= 55.0; }
        if item_size >= bin_capacity * 3 / 4 { score -= 40.0; }
        if bin_capacity - item_size <= 4 { score -= 70.0; }
        if item_size as f64 > mean_residual { score -= 30.0; }
        if newbin_waste < mean_residual * 0.5 { score -= 30.0; }
        if next_item_size > 0 {
            let leftover = bin_capacity - item_size;
            if leftover >= next_item_size {
                let tail = leftover % next_item_size;
                if tail == 0 { score -= 22.0; }
                else if tail <= 4 { score -= 16.0; }
                if leftover - next_item_size <= 6 { score -= 38.0; }
                if leftover >= next_item_size * 2 { score -= 14.0; }
            } else if leftover < 10 {
                score += 18.0;
            }
        }
        if fitting_bins_count > 3 { score += (fitting_bins_count.min(6) as f64) * 7.0; }
        if item_size as f64 / cap_f > 0.85 && mean_residual > cap_f * 0.35 { score -= 40.0; }
        // late stream: discourage opening bins with large waste
        if progress > 0.6 {
            let waste_tol = (1.0 - progress) * cap_f * 0.35;
            if newbin_waste > waste_tol && fitting_bins_count > 0 {
                score += 10.0 + progress * 22.0;
            }
        }
        if progress < 0.1 { score -= 5.0; }
    } else {
        if progress < 0.1 { score += 3.0; }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit bonus: strongly favor bins where the item leaves nothing behind.
    if post_residual == 0 {
        score -= 1000.0;
    }

    // 2-step lookahead: reward exact two-item fills (post_residual == next_item_size).
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 500.0;
    }

    // Penalize post-residuals that are small but unusable relative to the next item.
    if next_item_size > 0 {
        let gap = post_residual as f64 - next_item_size as f64;
        if gap < 0.0 && post_residual > 0 {
            // Dead space: too small for the next item.
            score += 0.5 * (-gap);
        }
    }

    // Prefer bins whose residual is close to the item (tight fit) relative to mean residual.
    let tightness = (bin_residual as f64 - item_size as f64) / bin_capacity as f64;
    score += 30.0 * tightness;

    // Relative residual comparison against mean residual across open bins.
    score += 2.0 * (post_residual as f64 - mean_residual);

    // Last-chance bonus: if this is the only bin that fits, use it rather than opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 200.0;
    }

    // New-bin candidate handling: discourage opening a new bin unless no good fit exists.
    if bin_residual == bin_capacity {
        let waste_if_new = (bin_capacity - item_size) as f64;
        // Base penalty for opening a new bin.
        score += 150.0;
        // But if the item is large and would leave a very small residual, opening may be good.
        if waste_if_new < 20.0 {
            score -= 300.0;
        }
        // If existing bins are all poor fits (high mean residual mismatch), allow new bin.
        if mean_residual < (bin_capacity - item_size) as f64 * 0.5 {
            score -= 120.0;
        }
    }

    // Early in the stream, be slightly more willing to open bins for better packing structure.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity {
        score -= 50.0 * (1.0 - progress);
    }

    // Slight penalty per number of open bins to consolidate when many bins exist.
    score += 0.3 * open_bins_count as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
