pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: fraction of bin consumed by this item.
    let fill = item_size as f64 / bin_capacity as f64;
    score -= 12.0 * fill * (post_residual as f64 / bin_capacity as f64);

    // Penalize small, hard-to-use residuals nonlinearly (dead space).
    if post_residual > 0 {
        let r = post_residual as f64 / bin_capacity as f64;
        if post_residual < 10 {
            score += 8.0 * (1.0 - r);
        } else {
            score += 3.0 * r * r;
        }
    } else {
        score -= 20.0; // perfect closure
    }

    // Lookahead: if next item fits exactly in post_residual, strong reward.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 30.0;
        } else if next_item_size <= post_residual {
            let waste = post_residual - next_item_size;
            score -= 15.0 * (1.0 - waste as f64 / bin_capacity as f64);
        } else {
            // next item won't fit here; slight penalty for stranding space
            score += 2.0;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 10.0;
    }

    // Many open bins: prefer compacting into existing bins.
    let open_pressure = open_bins_count as f64 / (1.0 + total_items as f64 / 20.0);
    score -= 4.0 * open_pressure * (bin_residual as f64 / bin_capacity as f64);

    // Mean residual coupling: bins with residual near mean are neutral;
    // outliers (much larger residual) get preference to be filled down.
    let dev = (bin_residual as f64 - mean_residual).abs();
    score -= 1.5 * dev / bin_capacity as f64;

    // Time horizon: late in stream, be greedy about closing bins.
    let t = step_index as f64 / (total_items.max(1) as f64);
    score -= 6.0 * t * fill;

    // New-bin candidate: only attractive when no good existing fit exists.
    if bin_residual == bin_capacity {
        let scarcity = if fitting_bins_count == 0 { 1.0 } else { 0.0 };
        let poor_fits = mean_residual - item_size as f64; // positive => existing bins fit poorly
        let bonus = 8.0 * scarcity + 0.35 * poor_fits.max(0.0) - 10.0 * (1.0 - t);
        score += bonus;
        // Opening a bin when item is large and residual would remain big is fine;
        // opening for tiny items is wasteful.
        if item_size < 25 {
            score += 10.0;
        }
    }

    score
}

