pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;

    let mut score = pr;

    // Non-linear coupling: residual penalty grows super-linearly, modulated by progress
    score += norm_pr * norm_pr * cap * (0.5 + 0.5 * progress);

    // Reward tight fits (small post_residual) more strongly as stream progresses
    score -= (1.0 - norm_pr).powi(3) * cap * 0.4 * (0.3 + 0.7 * progress);

    // Lookahead: if next item fits exactly in post_residual, strongly favor this bin
    if next_item_size > 0 && (next_item_size as f64 - pr).abs() < 1e-9 {
        score -= cap * 0.6;
    } else if next_item_size > 0 {
        let gap = (next_item_size as f64 - pr).abs() / cap;
        score += gap * cap * 0.2;
    }

    // Last-chance bonus: avoid opening a new bin when this is the only fitting one
    if fitting_bins_count == 1 {
        score -= cap * 0.35 * (1.0 - progress);
    }

    // Penalize bins far from mean residual (diversity of residual sizes)
    let dev = (pr - mean_residual).abs() / cap;
    score += dev * dev * cap * 0.15;

    // Mild pressure to consolidate when many bins are open
    score += (open_bins_count as f64).ln().max(0.0) * norm_pr * 2.0;

    // New-bin candidate: slightly penalize opening a new bin early, allow it late
    if bin_residual == bin_capacity {
        score += cap * (0.25 - 0.2 * progress);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: bins whose leftover lands on
    // "nice" modular classes (multiples of small divisors) are more reusable.
    let pr = post_residual;
    let class_penalty: f64 = if pr == 0 {
        -40.0 // perfect fill
    } else if pr % 10 == 0 {
        -12.0
    } else if pr % 5 == 0 {
        -6.0
    } else if pr % 2 == 0 {
        -2.0
    } else {
        4.0 // odd residual: harder to pair later
    };
    score += class_penalty;

    // Integer-division threshold: small residuals are dead space unless exactly 0.
    let div_class = pr / 25; // 0,1,2,3
    score += match div_class {
        0 => 10.0,          // tiny leftover (<25) mostly wasted
        1 => 0.0,
        2 => -3.0,
        _ => -5.0,
    };

    // Lookahead coupling: reward if next item fits exactly or near-exactly.
    if next_item_size > 0 {
        if next_item_size == pr {
            score -= 30.0;
        } else if next_item_size < pr {
            let gap = pr - next_item_size;
            score -= 10.0 / (1.0 + gap as f64);
            if gap % 10 == 0 {
                score -= 4.0;
            }
        } else {
            score += 6.0; // next item cannot use this bin's leftover
        }
    } else {
        // Last item: waste directly.
        score += pr as f64 * 0.5;
    }

    // Last-chance bin: strongly prefer using it before opening a new one.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 15.0;
    }

    // New-bin candidate handling: opening a fresh bin is only good when
    // current bins fit poorly (large item, many open bins, big mean residual).
    if bin_residual == bin_capacity {
        let pressure = open_bins_count as f64 / (1.0 + mean_residual);
        score = 60.0 + pressure - (item_size as f64 * 0.3);
        if fitting_bins_count == 0 {
            score -= 50.0; // no alternative: new bin mandatory
        }
    }

    // Mild preference for tighter bins as the stream progresses.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= (bin_capacity - bin_residual) as f64 * 0.05 * (0.5 + progress);

    // Penalize creating residual just below the minimum item size (dead zone).
    if pr > 0 && pr < 10 {
        score += 25.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
