pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps are heavily penalized.
    if post_residual > 0 && post_residual < 10 {
        score += (10 - post_residual) as f64 * 12.0;
    }
    // Perfect fit reward.
    if post_residual == 0 {
        score -= 30.0;
    }

    // Reward tight fits (small post_residual relative to capacity).
    score -= (1.0 - (post_residual as f64) / (bin_capacity as f64)) * 5.0;

    // Last-chance bin bonus: avoid opening a new bin unnecessarily.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 15.0;
    }

    // Lookahead: if next item fits the post residual, reward this placement.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 10.0;
    } else if next_item_size > 0 && post_residual > 0 {
        score += 5.0;
    }

    // Open-bin pressure: penalize creating new bins when many are open.
    if bin_residual == bin_capacity {
        score += 8.0 + (open_bins_count as f64) * 1.5;
    } else {
        score -= 3.0;
    }

    // Mild preference for filling fuller bins as stream progresses.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= (bin_residual as f64 / bin_capacity as f64) * (1.0 + progress);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer tight fits (small post_residual).
    score = (post_residual as f64).powf(1.3);

    // 2-step lookahead: strongly reward bins where the NEXT item also fits.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            // Perfect chaining: subtract proportional to how snugly next item fits.
            let chain_waste = (post_residual - next_item_size) as f64;
            score -= 60.0 + 0.5 * (bin_capacity as f64 - chain_waste);
        } else if next_item_size <= bin_capacity {
            // Next item won't fit here: penalize creating dead space it can't use,
            // scaled by how close the chain came to working.
            let miss = (next_item_size - post_residual) as f64;
            score += 10.0 + miss * 0.4;
        }
    }

    // Relative-to-mean coupling: bins with residual above mean are more "valuable"
    // to fill now; below-mean bins get a penalty for being consumed early.
    let dev = post_residual as f64 - mean_residual;
    score += 0.15 * dev;

    // Last-chance bonus: if this is the only fitting bin, avoid opening a new bin
    // unless the fit is terrible.
    if fitting_bins_count == 1 {
        score -= 25.0;
        if post_residual as f64 > mean_residual * 1.5 {
            score += 20.0; // poor fit, maybe better to open fresh bin
        }
    }

    // New-bin candidate handling: an empty bin is attractive only when the item
    // is large relative to capacity (would leave big dead space elsewhere) or
    // late in the stream when opening bins is cheap.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let fill_ratio = item_size as f64 / bin_capacity as f64;
        score = 70.0 - 30.0 * fill_ratio - 20.0 * progress;
        if next_item_size > 0 && post_residual >= next_item_size {
            score -= 15.0; // fresh bin supports a good chain too
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: small post_residual is good, but dead space below a
    // plausible minimum item size is wasted. Penalize residuals that are
    // unusably small (< 10) so bins don't end with scraps.
    if post_residual > 0 {
        score += 12.0 * (1.0 - (post_residual as f64 / 40.0).min(1.0));
    }

    // Lookahead: if the next item fits exactly into the post-residual,
    // strongly reward this placement (perfect chaining).
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 25.0;
        } else if post_residual >= next_item_size {
            score -= 6.0 * (1.0 - (post_residual - next_item_size) as f64 / bin_capacity as f64);
        } else {
            // next item cannot use this bin's remainder; slight penalty
            score += 4.0;
        }
    }

    // Last-chance bonus: if this is the only bin that fits the item,
    // strongly prefer using it over opening a new bin.
    if fitting_bins_count == 1 {
        score -= 30.0;
    } else if fitting_bins_count >= 2 {
        // competition: prefer bins where this item is a relatively tight fit
        score += 2.0 * (fitting_bins_count as f64 - 1.0).sqrt();
    }

    // Global state coupling: prefer filling bins with above-average residual
    // when the mean residual is large (consolidate waste).
    score += 0.15 * (mean_residual - post_residual as f64);

    // Time horizon: early in the stream, be conservative (favor tight fits
    // even more); late in the stream, just close out bins aggressively.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score *= 1.0 + 0.3 * (1.0 - progress);

    // New-bin candidate: penalize opening a new bin unless the item is large
    // and no existing bin offers a decent fit.
    if bin_residual == bin_capacity {
        score += 45.0
            - 0.4 * item_size as f64
            + (fitting_bins_count as f64) * 3.0;
    }

    // Mild preference for bins with larger residual when many bins are open
    // (keeps a diverse pool of residuals for future items).
    score -= 0.05 * (bin_residual as f64) * (open_bins_count as f64).ln().max(0.0);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap_f = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Tiered dead-space reaction (stronger than parent)
    if post_residual == 0 {
        score -= 1180.0;
    } else if post_residual <= 3 {
        score -= 500.0;
    } else if post_residual <= 12 {
        score -= 98.0;
    } else if post_residual < 20 {
        score += 18.0;
    } else if post_residual < 30 {
        score += 18.0 + (30 - post_residual) as f64 * 0.6;
    }

    // Lookahead: exact and near-exact fits for the next item
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 900.0;
        } else if next_item_size <= post_residual {
            let post2 = post_residual - next_item_size;
            score -= 135.0 - (post2 as f64) * 2.0;
            if post2 == 0 { score -= 110.0; }
            if post2 > 0 && post2 < 5 { score -= 28.0; }
            if post2 > 0 && post2 <= 2 { score -= 14.0; }
            if post2 % 10 == 0 && post2 > 0 { score -= 28.0; }
            if post2 >= 20 && post2 % 5 == 0 { score -= 12.0; }
            if post_residual % next_item_size == 0 { score -= 18.0; }
            if post_residual >= next_item_size * 2 && post_residual - next_item_size * 2 <= 4 {
                score -= 20.0;
            }
            if post2 > 0 && post2 <= next_item_size / 4 { score -= 10.0; }
            let chain = post_residual / next_item_size;
            if chain >= 2 { score -= (chain.min(4)) as f64 * 6.0; }
        } else {
            score += 20.0;
            if post_residual > 0 && (next_item_size - post_residual) <= 3 { score += 35.0; }
            let gap = next_item_size as f64 - post_residual as f64;
            if gap > 0.0 && gap <= 8.0 { score += 12.0; }
            if post_residual > 0 && gap > mean_residual * 0.5 { score += 14.0; }
            if post_residual > 0 && gap <= 5 { score += (6 - (next_item_size - post_residual)) as f64 * 4.0; }
            if post_residual as f64 > mean_residual * 1.4 { score -= 12.0; }
            if post_residual > 0 && post_residual < 15 { score += 45.0; }
        }
    }

    // Compaction pressure scaled by open bins
    score += open_bins_count as f64 * 0.8;

    // Last-chance bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 45.0;
    }

    // Tightness via relative fill
    let tightness = 1.0 - (item_size as f64 / bin_residual.max(1) as f64);
    score += tightness * 85.0;

    // NEW-BIN CANDIDATE handling
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let avg_fill = 1.0 - (mean_residual / cap_f);
        let newbin_waste = (bin_capacity - item_size) as f64;
        score += 250.0 - avg_fill * 330.0 - progress * 65.0;
        if item_size as f64 > mean_residual { score -= 45.0; }
        if item_size >= bin_capacity * 3 / 4 { score -= 55.0; }
        if bin_capacity - item_size <= 4 { score -= 70.0; }
        if item_size as f64 / cap_f > 0.85 && mean_residual > cap_f * 0.35 { score -= 40.0; }
        if next_item_size > 0 && next_item_size <= bin_capacity - item_size {
            let leftover = bin_capacity - item_size;
            score -= 25.0;
            let tail = leftover % next_item_size;
            if tail == 0 { score -= 10.0; }
            else if tail <= 4 { score -= 16.0; }
            if leftover - next_item_size <= 6 { score -= 38.0; }
            if leftover >= next_item_size * 2 { score -= 14.0; }
        }
        if next_item_size > 0 && next_item_size >= bin_capacity / 2 { score -= 32.0; }
        if newbin_waste > 0.0 && newbin_waste < mean_residual * 0.6 { score -= 30.0; }
        if fitting_bins_count > 0 {
            score += (fitting_bins_count as f64).min(5.0) * 9.0 + 20.0;
            let snug = item_size as f64 / (bin_residual.max(1) as f64);
            if snug > 0.9 { score += 40.0; }
            if snug > 0.95 { score += 28.0; }
            if snug > 0.98 { score += 18.0; }
        }
        if fitting_bins_count > 3 && item_size as f64 / cap_f < 0.5 { score += 30.0; }
        if progress > 0.6 {
            let waste_tol = (1.0 - progress) * cap_f * 0.35;
            if newbin_waste > waste_tol && fitting_bins_count > 0 {
                score += 10.0 + progress * 22.0;
            }
        }
        if newbin_waste > 0.0 && (newbin_waste as u32) < next_item_size && newbin_waste < cap_f * 0.12 {
            score += 26.0;
        }
    } else {
        score += (mean_residual - bin_residual as f64) * 1.5;

        let dead_ratio = post_residual as f64 / cap_f;
        if dead_ratio < 0.03 { score -= 38.0; }
        else if dead_ratio < 0.08 { score -= 14.0; }
        else if dead_ratio > 0.35 { score += 24.0; }
        else if dead_ratio > 0.25 { score += 10.0; }
        score += dead_ratio * 30.0;

        if post_residual > 0 && post_residual < 6 { score -= 22.0; }
        if post_residual > 0 && (post_residual as f64) < mean_residual * 0.25 { score -= 15.0; }
        if item_size == bin_residual { score -= 45.0; }
        if post_residual % 10 == 0 && post_residual > 0 { score -= 10.0; }
        if post_residual % 5 == 0 && post_residual > 0 && post_residual <= 30 { score -= 8.0; }
        if bin_residual as f64 > cap_f * 0.6 { score -= 12.0; }

        if next_item_size > 0 {
            if post_residual >= next_item_size {
                if post_residual <= next_item_size + 4 { score -= 22.0; }
                else { score -= 18.0; }
                let slack = post_residual - next_item_size;
                if slack > 0 && (slack as f64) < cap_f * 0.02 { score -= 14.0; }
            } else {
                let wasted = next_item_size as f64 - post_residual as f64;
                score += wasted * 0.6;
                if post_residual >= item_size * 2 { score += 10.0; }
                let gap = wasted / next_item_size.max(1) as f64;
                if gap < 0.12 { score -= 10.0; }
                if post_residual < bin_capacity / 10 { score += 18.0; }
            }
            if post_residual > next_item_size * 3 && post_residual < bin_capacity / 3 { score += 12.0; }
            if post_residual + next_item_size <= bin_capacity && (post_residual as f64) < mean_residual * 0.5 {
                score -= 9.0;
            }
        }

        if fitting_bins_count <= 2 && post_residual > 0 { score -= 8.0; }
        if post_residual > 0 && (post_residual as f64) > mean_residual * 1.6 && fitting_bins_count > 2 {
            score += 10.0;
        }
        let dev = (post_residual as f64 - mean_residual).abs();
        if post_residual > 0 && dev < cap_f * 0.03 { score -= 9.0; }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let capacity = bin_capacity as f64;
    let progress = (step_index as f64 / total_items.max(1) as f64).clamp(0.0, 1.0);
    let residual_f = post_residual as f64;
    let norm_res = residual_f / capacity;
    let norm_item = item_size as f64 / capacity;

    // Base: quadratic in normalized post-residual (dead-space penalty grows super-linearly)
    let mut score = norm_res * norm_res * capacity + residual_f * 0.5;

    // Smooth coupling of residual with stream progress: late in stream, tighter packing valued more
    let progress_coupling = (norm_res - 0.5).powi(2) * (0.5 + progress) * capacity;
    score += progress_coupling;

    // Cubic interaction: small residuals late are rewarded
    score -= (1.0 - norm_res).powi(3) * progress * capacity * 0.3;

    // Last-chance bonus: strongly favor the only bin that fits
    if fitting_bins_count == 1 {
        score -= 40.0;
    } else {
        // mild preference for bins among few fitting options
        score -= 5.0 / fitting_bins_count.max(1) as f64;
    }

    // Lookahead: reward if next item can fit into post-residual
    if next_item_size > 0 && (post_residual as u64) >= (next_item_size as u64) {
        score -= 8.0 + 6.0 * (next_item_size as f64 / capacity);
    } else if next_item_size > 0 {
        // penalize leaving residual just below next item (unusable dead space)
        let gap = (next_item_size as f64) - residual_f;
        score += 6.0 * (gap / capacity).min(1.0);
    }

    // Alignment with mean residual: prefer bins near the mean (balanced packing)
    score += ((residual_f - mean_residual) / capacity).abs() * 4.0;

    // New-bin candidate: penalize heavily unless current bins are poor fits / late stream
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        let scarcity = 1.0 / fitting_bins_count.max(1) as f64;
        score += 30.0 + 20.0 * (1.0 - progress) - 25.0 * scarcity;
    }

    // Slight preference for fuller bins (smaller post-residual) among open bins
    score -= norm_item * 2.0;

    score
}

