        else if dead_ratio > 0.25 { score += 10.0; }
        score += dead_ratio * 30.0;

        if item_size == bin_residual { score -= 45.0; }
        if post_residual > 0 && post_residual < 6 { score -= 22.0; }
        if post_residual > 0 && (post_residual as f64) < mean_residual * 0.25 { score -= 15.0; }
        if post_residual > 0 && post_residual % 10 == 0 { score -= 10.0; }
        if post_residual > 0 && post_residual % 5 == 0 && post_residual <= 30 { score -= 8.0; }
        if post_residual > 0 && (post_residual as f64) < cap_f * 0.015 { score -= 18.0; }

        if next_item_size > 0 {
            if post_residual >= next_item_size {
                score -= 18.0;
                if post_residual <= next_item_size + 4 { score -= 22.0; }
                let slack = post_residual - next_item_size;
                if slack > 0 && (slack as f64) < cap_f * 0.02 { score -= 14.0; }
            } else {
                let wasted = next_item_size as f64 - post_residual as f64;
                score += wasted * 0.6;
                if post_residual >= item_size * 2 { score += 10.0; }
                score += (1.0 - progress) * 14.0;
                if wasted <= 2.0 { score += 10.0 * (1.0 - progress); }
            }
        }

        if fitting_bins_count <= 2 && post_residual > 0 { score -= 8.0; }
        let dev = (post_residual as f64 - mean_residual).abs();
        if post_residual > 0 && dev < cap_f * 0.03 { score -= 9.0; }
        if post_residual > 0 && item_size as f64 / bin_residual.max(1) as f64 > 0.97
            && next_item_size > 0 && post_residual >= next_item_size {
            score -= 16.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: residuals that are "good" leave room for
    // common small item sizes (perfect-fit classes). Penalize dead space that
    // cannot host typical items.
    if post_residual > 0 {
        let r = post_residual;
        // Dead-space penalty: tiny residuals are wasted capacity.
        if r < 10 {
            score += 25.0; // unusable sliver
        } else if r < 20 {
            score += 8.0;
        } else if r < 30 {
            score += 2.0;
        } else if r >= 30 && r <= 70 {
            score -= 3.0; // sweet spot: fits mid-size items
        }
        // Modulo harmonic classes: residuals divisible by 10 align with item grid
        if r % 10 == 0 {
            score -= 2.0;
        } else if r % 5 == 0 {
            score -= 1.0;
        }
    } else {
        // Perfect packing: bin closed exactly. Strong reward.
        score -= 30.0;
    }

    // Lookahead coupling: if the next item fits the post residual, big reward.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 12.0;
        // Extra reward for exact lookahead fit (harmonic alignment).
        if post_residual == next_item_size {
            score -= 15.0;
        }
        // Penalize leaving post_residual that fits next item only wastefully
        let slack = (post_residual - next_item_size) as f64;
        if slack > 0.0 && slack < 10.0 {
            score += 4.0; // near-miss creates sliver
        }
    } else if next_item_size > 0 {
        // Next item won't fit here; mild penalty for hoarding space.
        score += 3.0;
    }

    // Last chance: if this is the only fitting bin, strongly prefer using it
    // over opening a new bin (unless fit is terrible).
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
        if post_residual < 10 {
            score -= 10.0; // still better to consume the sliver
        }
    }

    // New-bin candidate handling: opening a new bin should only win when the
    // item fits no open bin well. Penalize new bin by default.
    if bin_residual == bin_capacity {
        score += 40.0;
        // But if many open bins are nearly full (mean residual low), new bin
        // is natural: reduce penalty.
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score -= mean_residual * 0.2 + progress * 5.0;
        // Small items start fresh bins cheaply.
        if item_size <= 30 {
            score -= 10.0;
        }
    }

    // Tight-fit reward: item fills most of the residual.
    let fill_ratio = item_size as f64 / bin_residual.max(1) as f64;
    if fill_ratio > 0.9 {
        score -= 10.0;
    } else if fill_ratio > 0.7 {
        score -= 4.0;
    } else if fill_ratio < 0.3 && bin_residual != bin_capacity {
        score += 6.0; // wasteful tiny item in a big bin
    }

    // Congestion: many open bins with high mean residual -> prefer filling them.
    if open_bins_count > 4 && mean_residual > item_size as f64 {
        score -= 2.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: gaps that are too small for the smallest
    // possible item (size 1) are already counted by post_residual, but gaps
    // that cannot fit the NEXT item are worse than they look.
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        // Dead space relative to lookahead: unusable for the next arrival.
        score += (next_item_size - post_residual) as f64 * 2.5;
    }

    // Perfect fit: best possible outcome, strongly reward.
    if post_residual == 0 {
        score -= 40.0;
    } else if post_residual <= 3 {
        // Near-perfect fit: residual too small for most items, effectively dead.
        score -= 20.0;
    }

    // Penalize mid-range residuals that are hard to fill later
    // (typical awkward gap: 30..60) more than large comfortable residuals.
    let pr = post_residual as f64;
    if pr > 30.0 && pr < 60.0 {
        score += 6.0;
    }

    // Last-chance pressure: if this is the only bin that fits, avoid opening
    // a new bin unless the fit is truly terrible.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 12.0;
    }

    // Open-bin pressure: discourage spreading across many bins when a tight
    // fit exists; encourage consolidating into bins with low residual.
    score += open_bins_count as f64 * 0.8;

    // Favor bins whose residual is below the mean residual (tighter bins),
    // i.e. prefer filling the fullest bin.
    score += (mean_residual - bin_residual as f64) * 0.5;

    // New-bin candidate handling: opening a new bin is only attractive when
    // no open bin fits well (large item, many open bins, poor fits).
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        // Base penalty for opening a new bin, reduced for large items and
        // when many bins are already open.
        score = 55.0
            - (item_size as f64) * 0.35
            - open_bins_count as f64 * 0.4
            - progress * 5.0;
        // If lookahead item would also fit nicely in a fresh bin, slightly favor.
        if next_item_size > 0 && item_size + next_item_size <= bin_capacity {
            score -= 6.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Aggressive 2-step lookahead: reward exact match of post_residual to next item
    if next_item_size > 0 {
        let diff = (post_residual as i64 - next_item_size as i64).abs() as f64;
        score += diff * 0.8;
        if post_residual == next_item_size {
            score -= 25.0; // perfect 2-step chain
        }
        // next item fits exactly into residual after this placement
        if post_residual >= next_item_size {
            score -= 8.0;
        }
    } else {
        // last item: strongly prefer tightest fill
        score -= 10.0;
    }

    // Penalize dead space relative to mean residual
    let dead = post_residual as f64 - mean_residual;
    if dead > 0.0 {
        score += dead * 0.3;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate: penalize unless open bins are badly fragmented
    if bin_residual == bin_capacity {
        let fragmentation = mean_residual / bin_capacity as f64;
        if fragmentation < 0.35 || fitting_bins_count == 0 {
            score -= 20.0; // open new bin when existing ones are poor
        } else {
            score += 30.0; // prefer reusing open bins
        }
    }

    // Slight preference for filling larger residuals early in stream
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += (bin_residual as f64 / bin_capacity as f64) * (1.0 - progress) * 3.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let score = (post_residual as f64) * 0.90;
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits (small post residual) nonlinearly.
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 8.0 * tightness * tightness;

    // Penalize dead space: residuals too small for typical future items.
    if post_residual > 0 && post_residual < 10 {
        score += 15.0;
    }

    // Last-chance bonus: if this is the only bin that fits, strongly prefer it.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // Lookahead coupling: reward if next item fits into post residual.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 6.0 + 0.05 * next_item_size as f64;
        } else {
            // Penalize leaving a residual that wastes the next item's fit options.
            let gap = (next_item_size - post_residual) as f64;
            score += 0.08 * gap;
        }
    }

    // Prefer fuller bins when many bins are open (consolidation pressure).
    let fill_ratio = 1.0 - (bin_residual as f64 / bin_capacity as f64);
    score -= 5.0 * fill_ratio * (open_bins_count as f64).ln().max(1.0);

    // Global residual balance: prefer bins below mean residual (more filled).
    score += 0.05 * (mean_residual - bin_residual as f64);

    // Time horizon: early in the stream, be more willing to open new bins
    // (make score for a fresh bin relatively lower); late, consolidate.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity {
        // New-bin candidate: baseline cost plus exploration discount early on.
        score = 40.0 - 20.0 * (1.0 - progress);
        // Penalize opening a new bin when a decent fit exists elsewhere.
        if fitting_bins_count > 0 && post_residual >= 0 {
            score += 10.0 * progress;
        }
        // If next item is large and this fresh bin could hold both, slight bonus.
        if next_item_size > 0 && bin_capacity >= (item_size + next_item_size) {
            score -= 5.0;
        }
    } else {
        // Late stream: extra reward for using nearly-full bins.
        score -= 10.0 * progress * fill_ratio;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;
    let mut score = pr as f64;

    // Smooth non-linear polynomial coupling of post_residual with stream progress
    let p = progress;
    let coupling = norm_pr * norm_pr * (1.0 + 2.0 * p) - 0.5 * norm_pr * p * (1.0 - p);
    score += 40.0 * coupling;

    // Penalize dead space that cannot fit the next item (smooth quadratic)
    if next_item_size > 0 {
        let gap = (post_residual as i64 - next_item_size as i64).max(0) as f64;
        let waste = gap / cap;
        score -= 15.0 * waste * (1.0 - waste) * (1.0 + p);
    }

    // Reward last-chance bins smoothly
    if fitting_bins_count == 1 {
        score -= 10.0 * (1.0 - norm_pr) * (1.0 + p);
    }

    // Mild pressure toward consolidating residuals as stream progresses
    score += 5.0 * (norm_pr - mean_residual / cap) * p;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: residuals that are "friendly"
    // to typical item sizes (multiples of 10 / large halves) are worth less
    // dead space than awkward classes.
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let frac = pr / cap;

    // Class A: near-perfect fit (tiny dead space) -> strong reward
    if post_residual <= 2 {
        score -= 40.0;
    } else if post_residual <= 5 {
        score -= 18.0;
    }

    // Class B: post residual is a "usable" harmonic chunk (multiple of 10)
    if post_residual >= 10 && post_residual % 10 == 0 {
        score -= 6.0;
    }

    // Class C: awkward dead space: small but nonzero, unusable by min items (1..9)
    if post_residual >= 1 && post_residual <= 9 {
        score += 12.0;
    }

    // Lookahead coupling: if the next item fits exactly into the post residual,
    // this bin closes perfectly -> big reward.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 35.0;
        } else if next_item_size <= post_residual {
            let nxt = next_item_size as f64;
            // reward proportional to how much of the post residual the next item consumes
            score -= 10.0 * (nxt / pr).min(1.0);
            // harmonic class match: next item leaves another clean residual
            if (post_residual - next_item_size) % 10 == 0 {
                score -= 5.0;
            }
        } else {
            // next item cannot use this bin's leftover; penalize large leftovers slightly
            score += 0.05 * pr;
        }
    }

    // Last-chance bin: if this is the only bin that fits, strongly prefer using it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate: empty bin. Prefer it only when the item is large and
    // no open bin offers a tight fit; otherwise penalize so we reuse bins.
    if bin_residual == bin_capacity {
        let big_item = item_size as f64 / cap;
        if big_item > 0.6 {
            score -= 8.0;
        } else {
            score += 20.0 + 15.0 * (1.0 - big_item);
        }
        // late in the stream, be more conservative about opening bins
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 10.0 * progress;
    }

    // Mean residual pressure: when open bins are generally full, avoid wasting
    // the scarce large residuals; when bins are loose, prefer tight fits.
    if bin_residual as f64 > mean_residual {
        score += 0.08 * (bin_residual as f64 - mean_residual);
    } else {
        score -= 0.05 * (mean_residual - bin_residual as f64);
    }

    // Fractional harmonic penalty: residuals just above half capacity are
    // flexible (fit most items), residuals just below half are traps.
    if frac > 0.45 && frac < 0.55 {
        score -= 4.0;
    } else if frac >= 0.05 && frac < 0.2 {
        score += 3.0;
    }

    score
}

