pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps are heavily penalized.
    if post_residual > 0 && post_residual < 10 {
        score += 40.0;
    } else if post_residual >= 10 && post_residual < 25 {
        score += 12.0;
    }

    // Reward tight fits.
    score -= (item_size as f64 / bin_capacity as f64) * 8.0;

    // Open-bin pressure: discourage opening new bins when many bins exist.
    if bin_residual == bin_capacity {
        score += 6.0 + open_bins_count as f64;
    } else {
        score -= 2.0;
    }

    // Last chance bin: strongly favor using it.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // Lookahead: if next item fits the post-residual, reward this placement.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 6.0;
    }
    // If next item cannot fit post-residual but would fit an empty bin, penalize.
    if next_item_size > post_residual as u32 && post_residual > 0 {
        score += 4.0;
    }

    // Mild preference for bins with residuals close to the item (best-fit flavor).
    score += ((bin_residual as f64 - item_size as f64) / bin_capacity as f64) * 4.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap_f = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Perfect / near-perfect fits are heavily rewarded
    if post_residual == 0 {
        score -= 900.0;
    } else if post_residual <= 3 {
        score -= 350.0;
    } else if post_residual <= 12 {
        score -= 60.0;
    } else if post_residual < 20 {
        score += 12.0;
    } else if post_residual < 30 {
        score += 10.0 + (30 - post_residual) as f64 * 0.5;
    }

    // Lookahead: reward placements whose leftover chains with the next item
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 700.0;
        } else if next_item_size <= post_residual {
            let post2 = post_residual - next_item_size;
            score -= 100.0 - post2 as f64 * 2.0;
            if post2 == 0 {
                score -= 90.0;
            }
            if post2 > 0 && post2 < 5 {
                score -= 25.0;
            }
            if post2 >= 20 && post2 % 5 == 0 {
                score -= 10.0;
            }
            if post_residual % next_item_size == 0 {
                score -= 15.0;
            }
            let chain = post_residual / next_item_size;
            if chain >= 2 {
                score -= (chain.min(4)) as f64 * 6.0;
            }
        } else {
            // next item won't fit here; penalize small dead leftovers
            score += 15.0;
            if post_residual > 0 && post_residual < 15 {
                score += 35.0;
            }
            let gap = next_item_size as f64 - post_residual as f64;
            if post_residual > 0 && gap <= 6.0 {
                score += 20.0;
            }
            if post_residual > 0 && post_residual as f64 > mean_residual * 1.4 {
                score -= 10.0;
            }
        }
    }

    // NEW-BIN CANDIDATE LOGIC (bin_residual == bin_capacity)
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let newbin_waste = (bin_capacity - item_size) as f64;
        let avg_fill = 1.0 - (mean_residual / cap_f);
        score += 220.0 - avg_fill * 300.0 - progress * 60.0;

        if fitting_bins_count > 0 {
            score += (fitting_bins_count as f64).min(5.0) * 8.0 + 18.0;
            let snug = item_size as f64 / (bin_residual.max(1) as f64);
            if snug > 0.9 {
                score += 35.0;
            }
            if snug > 0.95 {
                score += 25.0;
            }
            if snug > 0.98 {
                score += 15.0;
            }
        }
        if item_size >= bin_capacity * 3 / 4 {
            score -= 50.0;
        }
        if bin_capacity - item_size <= 4 {
            score -= 60.0;
        }
        if next_item_size > 0 && next_item_size <= bin_capacity - item_size {
            score -= 20.0;
            let leftover = bin_capacity - item_size;
            if leftover >= next_item_size {
                let tail = leftover % next_item_size;
                if tail == 0 {
                    score -= 12.0;
                } else if tail <= 4 {
                    score -= 8.0;
                }
            }
        }
        // Avoid opening a bin whose waste is small relative to existing residuals
        if newbin_waste > 0.0 && newbin_waste < mean_residual * 0.6 {
            score -= 25.0;
        }
        if progress > 0.6 {
            let waste_tol = (1.0 - progress) * cap_f * 0.35;
            if newbin_waste > waste_tol && fitting_bins_count > 0 {
                score += 10.0 + progress * 20.0;
            }
        }
        if newbin_waste > 0.0 && (newbin_waste as u32) < next_item_size && newbin_waste < cap_f * 0.12 {
            score += 22.0;
        }
    } else {
        // Existing-bin placement: prefer tight fits and low dead space
        let tightness = 1.0 - (item_size as f64 / bin_residual.max(1) as f64);
        score += tightness * 70.0;
        score += (mean_residual - bin_residual as f64) * 1.2;

        let dead_ratio = post_residual as f64 / cap_f;
        if dead_ratio < 0.03 {
            score -= 30.0;
        } else if dead_ratio < 0.08 {
            score -= 12.0;
        } else if dead_ratio > 0.35 {
            score += 20.0;
        } else if dead_ratio > 0.25 {
            score += 8.0;
        }
        score += dead_ratio * 25.0;

        if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
            let dead_frac = post_residual as f64 / cap_f;
            let unusable = (next_item_size - post_residual) > 12;
            if unusable {
                score += dead_frac * 80.0;
            } else {
                score += (next_item_size - post_residual) as f64 * 0.8;
            }
        }

        if item_size == bin_residual {
            score -= 40.0;
        }
        if post_residual > 0 && post_residual % 10 == 0 {
            score -= 8.0;
        }
        // Last-chance bin: favor using it to avoid opening a new bin
        if fitting_bins_count == 1 {
            score -= 20.0;
        }
        if post_residual > 0 && item_size as f64 / bin_residual.max(1) as f64 > 0.97 && post_residual >= next_item_size {
            score -= 14.0;
        }
        let progress = step_index as f64 / total_items.max(1) as f64;
        if post_residual > 0 && next_item_size > 0 && post_residual < next_item_size {
            score += (1.0 - progress) * 12.0;
        }
    }

    // Compaction pressure when many bins are open
    score += open_bins_count as f64 * 0.5;

    score
