    }

    // Compare post_residual against mean residual: prefer tightening spread.
    let pr = post_residual as f64;
    let spread = (pr - mean_residual).abs();
    score += 0.3 * spread;

    // Reward tight fits (low post residual) more strongly.
    score += 0.5 * pr;

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 20.0;
    }

    // New-bin candidate: only attractive when residuals are fragmented or item is huge.
    if bin_residual == bin_capacity {
        let fragmented = mean_residual < (bin_capacity as f64) * 0.35 && open_bins_count > 2;
