        if post_residual == next_item_size {
            score -= 30.0;
        } else if post_residual >= next_item_size {
            score -= 8.0 * (post_residual as f64 / next_item_size as f64).min(3.0);
        }
    } else {
        // Last item: just minimize residual.
        score += 20.0 * fit_ratio;
    }

    // Last-chance bonus: if this is the only fitting bin, strongly favor using it.
    if fitting_bins_count == 1 {
        score -= 35.0;
    } else if fitting_bins_count > 1 {
        // With many options, prefer bins that are already quite full.
        let fill = 1.0 - bin_residual as f64 / bin_capacity as f64;
        score -= 12.0 * fill;
    }

    // New-bin candidate logic: opening a new bin is only attractive when the item
    // fits poorly everywhere else (large item, small mean residual headroom).
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let poor_fit_elsewhere = mean_residual < item_size as f64 * 0.95;
        let big_item = item_size as f64 > bin_capacity as f64 * 0.6;
        if poor_fit_elsewhere || (big_item && fitting_bins_count <= 2) {
            score -= 20.0 + 15.0 * (1.0 - progress);
        } else {
            // Discourage wasteful bin proliferation.
            score += 30.0 + 5.0 * open_bins_count as f64;
        }
    }

    // Mild global pressure: many open bins -> prefer consolidating into fuller bins.
    score += 0.05 * open_bins_count as f64 * fit_ratio;

    // Prefer bins whose residual deviates favorably from the mean (fill outliers).
    score -= 0.15 * (bin_residual as f64 - mean_residual);

    // Small time-horizon modulation: early on, be slightly exploratory toward tight fits.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 6.0 * (1.0 - progress) * (1.0 - fit_ratio);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
