pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;
    let norm_item = item_size as f64 / cap;
    let norm_next = next_item_size as f64 / cap;
    let fit_norm = fitting_bins_count as f64;

    // Base: quadratic penalty on post residual (dead space), modulated by stream progress
    let mut score = pr * (1.0 + 1.5 * progress * norm_pr);

    // Smooth coupling: prefer tight fits more strongly as the stream progresses
    score -= 20.0 * (1.0 - norm_pr).powi(2) * (0.5 + progress);

    // Interaction of item size with post residual: medium residuals are valuable
    let bump = (-((norm_pr - 0.3).powi(2)) / 0.08).exp();
    score -= 8.0 * bump * (1.0 - progress);

    // Lookahead: reward if next item fits into the resulting post residual
    if next_item_size > 0 && next_item_size <= post_residual {
        let snug = 1.0 - ((post_residual - next_item_size) as f64 / cap).abs();
        score -= 6.0 * snug * (0.4 + 0.6 * progress);
    } else if next_item_size > 0 {
        // penalize residuals that waste space relative to the next item
        score += 3.0 * (norm_pr - norm_next).max(0.0);
    }

    // Last-chance bin: strong bonus to use it rather than open a new one
    if fitting_bins_count == 1 {
        score -= 12.0 * (1.0 - norm_item);
    } else {
        // mild penalty when many bins compete, to keep diversity
        score += 1.5 * (fit_norm / (open_bins_count.max(1) as f64 + 1.0));
    }

    // Mean residual coupling: avoid fragmenting when average residual is already small
    let mean_norm = mean_residual / cap;
    score += 5.0 * mean_norm * norm_item * (1.0 - progress);

    // New-bin candidate shaping: empty bin gets a moderate default so it wins only on bad fits
    if bin_residual == bin_capacity {
        score += 10.0 * (1.0 - norm_item) * (0.5 + 0.5 * (1.0 - progress));
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
