pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Dead-space penalty: residuals < 10 are nearly unusable (min item size ~10)
    if post_residual > 0 && post_residual < 10 {
        score += 15.0;
    }

    // Harmonic class of post_residual: prefer residuals in "useful" decade classes
    // (multiples of 10 leave room for typical items)
    score += (post_residual % 10) as f64 * 0.3;
    if post_residual % 20 == 0 && post_residual > 0 {
        score -= 3.0;
    }

    // Lookahead coupling: exact fit for next item is gold
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 40.0;
        } else if next_item_size <= post_residual {
            score -= 5.0;
            // reward if post residual lands in same harmonic class as next item
            if post_residual % 10 == next_item_size % 10 {
                score -= 2.0;
            }
        } else {
            // next item cannot use this residual at all
            score += 4.0;
        }
    }

    // Last-chance bonus: only open bin that fits -> strong preference
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // Tightness reward: filling a bin densely is good
    score -= (item_size as f64 / bin_capacity as f64) * 10.0;

    // New-bin candidate handling: generally penalize, but less so for large items
    // (large items open fresh bins, preserving small residuals for small items)
    let is_new = bin_residual == bin_capacity;
    if is_new {
        score += 20.0 - (item_size as f64) * 0.25;
        if next_item_size > 0 && next_item_size >= item_size {
            score += 5.0; // consecutive large items pair well in fresh bins
        }
    }

    // Mild stream-progression pressure: late in stream, prefer consolidating
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= progress * 2.0;

    // Slight preference for bins with below-average residual (keep big gaps free)
    if !is_new {
        score += (mean_residual - bin_residual as f64).max(-20.0).min(20.0) * 0.1;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps are heavily penalized.
    if post_residual > 0 && post_residual < 10 {
        score += 40.0;
    } else if post_residual >= 10 && post_residual < 20 {
        score += 12.0;
    }

    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 100.0;
    }

    // Last-chance bin: strongly prefer using it before opening a new one.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 35.0;
    }

    // Pressure from number of open bins: discourage spreading across many bins.
    score += (open_bins_count as f64) * 0.8;

    // Lookahead: if next item fits exactly in post_residual, reward this placement.
    if next_item_size > 0 && post_residual > 0 {
        if next_item_size == post_residual {
            score -= 60.0;
        } else if next_item_size <= post_residual {
            score -= (post_residual - next_item_size) as f64 * 0.3;
        } else {
            // Next item cannot use the leftover: penalize proportional dead space.
            score += (next_item_size - post_residual) as f64 * 0.15;
        }
    }

    // Compare residual to mean residual: bins tighter than average are better targets.
    score += (post_residual as f64 - mean_residual) * 0.5;

    // New-bin candidate: only attractive when current bins are badly fragmented.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let fragmented = (mean_residual < item_size as f64 * 1.3) as i32 as f64;
        score -= fragmented * 25.0 - progress * 5.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Aggressive 2-step lookahead: reward bins whose post_residual matches next_item_size
    if next_item_size > 0 {
        let diff = (post_residual as i64 - next_item_size as i64).abs() as f64;
        // Perfect match (next item exactly fills the bin) is heavily rewarded
        if post_residual == next_item_size {
            score -= 60.0;
        } else {
            score += diff * 0.8;
        }
        // Penalize post_residual too small for the next item (dead space likely)
        if post_residual < next_item_size {
            score += (next_item_size as f64 - post_residual as f64) * 0.5;
        }
        // Bonus if next item can chain into this bin AND still leave usable space
        if post_residual >= next_item_size && post_residual - next_item_size <= 10 {
            score -= 15.0;
        }
    }

    // Relative to mean residual: prefer bins with residual below/at the mean
    // (tighter bins get packed first, keeping large residuals flexible)
    let mean_diff = mean_residual - post_residual as f64;
    score -= mean_diff * 0.3;

    // Penalize creating tiny unusable slivers (dead space < 10)
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Last-chance bin: if this is the only fitting bin, strongly prefer using it
    if fitting_bins_count == 1 {
        score -= 20.0;
    }

    // Penalize wasting a nearly-empty bin on a small item
    if post_residual > 60 {
        score += (post_residual as f64 - 60.0) * 0.4;
    }

    // Early in the stream, be more willing to open/use fresh space
    let progress = step_index as f64 / total_items.max(1) as f64;
    score *= 1.0 - 0.15 * progress;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap_f = bin_capacity as f64;
    let progress = step_index as f64 / total_items.max(1) as f64;
    let mut score = post_residual as f64;

    // Tiered dead-space avoidance (strengthened toward best-known magnitudes)
    if post_residual == 0 {
        score -= 900.0;
    } else if post_residual <= 3 {
        score -= 420.0;
    } else if post_residual <= 12 {
        score -= 80.0;
    } else if post_residual < 20 {
        score += 18.0;
    } else if post_residual < 30 {
        score += 12.0 + (30 - post_residual) as f64 * 0.5;
    }

    // Lookahead: exact and near-exact fits for the next item
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 700.0;
        } else if next_item_size <= post_residual {
            let post2 = post_residual - next_item_size;
            score -= 110.0 - (post2 as f64) * 1.8;
            if post2 == 0 { score -= 90.0; }
            if post2 > 0 && post2 < 5 { score -= 26.0; }
            if post2 % 10 == 0 && post2 > 0 { score -= 20.0; }
            if post_residual % next_item_size == 0 { score -= 16.0; }
            if post_residual >= next_item_size * 2 && post_residual - next_item_size * 2 <= 4 {
                score -= 18.0;
            }
            let chain = post_residual / next_item_size;
            if chain >= 2 { score -= (chain.min(4)) as f64 * 6.0; }
            if post2 > 0 && post2 <= next_item_size / 4 { score -= 10.0; }
        } else {
            let gap = next_item_size - post_residual;
            if post_residual > 0 {
                if gap <= 3 { score += 35.0; }
                else if gap <= 8 { score += 12.0; }
                if (gap as f64) > mean_residual * 0.5 { score += 12.0; }
                if post_residual < 15 { score += 30.0; }
                score += (6u32.min(gap)) as f64 * 3.0;
            }
        }
    }

    // Compaction pressure scaled by open bins
    score += open_bins_count as f64 * 0.8;

    // Last-chance bin: strongly favor using it
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 45.0;
    }

    // Tightness via relative fill
    score -= (item_size as f64 / bin_residual.max(1) as f64) * 30.0;

    // Consolidate slack: prefer bins with below-average residual
    if bin_residual < bin_capacity {
        score += (mean_residual - bin_residual as f64) * 1.2;
        let dead_ratio = post_residual as f64 / cap_f;
        if dead_ratio < 0.03 { score -= 30.0; }
        else if dead_ratio > 0.3 { score += 20.0; }
        if item_size == bin_residual { score -= 40.0; }
    }

    // NEW-BIN CANDIDATE handling
    if bin_residual == bin_capacity {
        let newbin_waste = (bin_capacity - item_size) as f64;
        let avg_fill = 1.0 - (mean_residual / cap_f);
        score += 220.0 - avg_fill * 300.0 - progress * 60.0;
        if item_size as f64 / cap_f > 0.75 { score -= 55.0; }
        if item_size as f64 > mean_residual { score -= 35.0; }
        if newbin_waste < mean_residual * 0.5 { score -= 30.0; }
        if next_item_size > 0 {
            let leftover = bin_capacity - item_size;
            if leftover >= next_item_size && leftover - next_item_size <= 6 { score -= 38.0; }
            if leftover >= next_item_size {
                let tail = leftover % next_item_size;
                if tail == 0 { score -= 14.0; }
                else if tail <= 4 { score -= 12.0; }
            }
            if leftover < next_item_size && leftover < 10 { score += 18.0; }
            if leftover >= next_item_size * 2 { score -= 14.0; }
        }
        if bin_capacity - item_size <= 4 { score -= 65.0; }
        if fitting_bins_count > 0 {
            score += (fitting_bins_count.min(6) as f64) * 7.0;
            let snug = item_size as f64 / bin_residual.max(1) as f64;
            if snug > 0.95 { score += 25.0; }
        }
        if fitting_bins_count > 3 && item_size as f64 / cap_f < 0.5 { score += 25.0; }
        if progress > 0.6 && newbin_waste > (1.0 - progress) * cap_f * 0.35 && fitting_bins_count > 0 {
            score += 10.0 + progress * 20.0;
        }
        if progress < 0.1 { score -= 5.0; }
    } else {
        // Mild progress-based diversity nudge for open bins
        if progress < 0.1 { score += 3.0; }
        if post_residual > 0 && next_item_size > 0 && post_residual < next_item_size {
            score += (1.0 - progress) * 12.0;
        }
        if fitting_bins_count <= 2 && post_residual > 0 { score -= 8.0; }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

