            if post_residual < 10 {
                score += 40.0;
            }
            // dead space that could have held next item is extra bad
            score += (next_item_size as f64 - post_residual as f64) * 0.3;
        }
    }

    // Last chance bin: strongly favor using it before opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 500.0;
    }

    // Penalize opening a new bin when good open options exist
    if bin_residual == bin_capacity {
        // new bin baseline: slightly worse than a decent fit in an open bin
        score += 25.0;
        // but if open bins are fragmented (mean residual low) and item is large, new bin is fine
        let frag = mean_residual / bin_capacity as f64;
        if item_size as f64 > frag * bin_capacity as f64 {
            score -= 40.0;
        }
        // late in stream, prefer consolidating into open bins
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score += progress * 30.0;
    }

    // Prefer fuller bins: reward small bin_residual
    score -= (bin_capacity as f64 - bin_residual as f64) * 0.2;

    // Penalize spreading across many bins when residuals are large
    if open_bins_count > 3 && mean_residual > item_size as f64 * 1.5 {
        score += 5.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let norm_pr = pr / cap;

    // Base: post residual, with non-linear shaping (quadratic dead-space penalty)
    let mut score = pr + 40.0 * norm_pr * norm_pr * cap * 0.01;

    // Smooth coupling of residual waste with stream progress
    score += 15.0 * (1.0 - progress) * norm_pr * (1.0 - norm_pr);

    // Penalize bins whose residual diverges from mean residual (smooth interaction)
    let dev = (pr - mean_residual) / cap;
    score += 10.0 * dev * dev * cap * 0.01;

    // Reward tight fits: smooth sigmoid-like term on post residual
    score -= 12.0 * (-pr / (cap * 0.15)).exp();

    // Last-chance bin bonus (smoothly damped by progress)
    if fitting_bins_count == 1 {
        score -= 8.0 * (1.0 - progress);
    }

    // Lookahead coupling: reward residual that fits next item smoothly
    if next_item_size > 0 && (next_item_size as f64) <= pr {
        let fit_frac = next_item_size as f64 / pr.max(1.0);
        score -= 6.0 * fit_frac * (1.0 - fit_frac) * 4.0 * fit_frac * (1.0 - progress);
    } else if next_item_size > 0 {
        // next item cannot fit in post residual: mild penalty
        score += 4.0 * (1.0 - progress);
    }

    // New-bin candidate handling: prefer opening a new bin only for large items / poor fits
    if bin_residual == bin_capacity {
        let tight = item_size as f64 / cap;
        score = pr + 30.0 * (1.0 - tight) * (1.0 - progress) - 5.0 * tight;
    }

    score
}

