        }
        // Waste tolerance grows with progress
        let waste_tol = (1.0 - progress) * cap_f * 0.32;
        if newbin_waste > waste_tol && fitting_bins_count > 0 {
            score += 10.0 + progress * 20.0;
        }
        if newbin_waste > 0.0 && (newbin_waste as u32) < next_item_size && newbin_waste < cap_f * 0.12 {
            score += 24.0;
        }
        if newbin_waste > 0.0 && newbin_waste < mean_residual * 0.6 {
            score -= 26.0;
        }
    } else {
        // Existing bin: prefer tight fits and low dead ratio
        let tightness = 1.0 - (item_size as f64 / bin_residual.max(1) as f64);
        score += tightness * 70.0;
        score += (mean_residual - bin_residual as f64) * 1.4;
        let dead_ratio = post_residual as f64 / cap_f;
        if dead_ratio < 0.03 {
            score -= 34.0;
        } else if dead_ratio < 0.08 {
            score -= 12.0;
        } else if dead_ratio > 0.35 {
            score += 22.0;
        } else if dead_ratio > 0.25 {
            score += 9.0;
        }
        score += dead_ratio * 28.0;
        if item_size == bin_residual {
            score -= 40.0;
        }
        if post_residual > 0 && post_residual < 6 {
            score -= 20.0;
        }
        if post_residual > 0 && (post_residual as f64) < mean_residual * 0.25 {
            score -= 13.0;
        }
        if post_residual > 0 && post_residual % 10 == 0 {
            score -= 8.0;
        }
        if fitting_bins_count == 1 {
            score -= 22.0;
        } else if fitting_bins_count == 2 {
            score -= 6.0;
        }
        if post_residual > 0 && next_item_size > 0 && post_residual >= next_item_size {
            let slack = post_residual - next_item_size;
            if slack > 0 && slack < next_item_size && (slack as f64) < cap_f * 0.02 {
                score -= 12.0;
            }
        }
        if post_residual > 0 && (post_residual as f64) < cap_f * 0.015 {
            score -= 16.0;
        }
        if item_size as f64 / bin_residual.max(1) as f64 > 0.97 && post_residual >= next_item_size {
            score -= 14.0;
        }
        // Compact when many bins are open
        score += open_bins_count as f64 * 0.5;
    }

    // Late-stream compaction pressure
    if progress > 0.8 {
        score -= 6.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: modulo classes over capacity fractions
    let pr = post_residual;
    let cap_frac = bin_capacity / 4; // 25-unit harmonic quarter
    let octile = bin_capacity / 8;   // 12-unit fine class

    // Reward post-residuals that land on "harmonic" residue classes:
    // residuals divisible by 25 or 12 are more reusable by typical item sizes.
    if pr == 0 {
        score -= 60.0; // perfect closure is best
    } else {
        if pr % cap_frac == 0 {
            score -= 25.0;
        }
        if pr % octile == 0 {
            score -= 12.0;
        }
        // penalize dead space: residuals too small for the smallest item
        if pr < 10 {
            score += 40.0;
        }
        // class-based dead-zone penalty: residual in (0,10) or awkward mid band
        if pr > 0 && pr < 10 {
            score += 25.0;
        }
        if pr > 50 && pr < 60 {
            score += 8.0;
        }
    }

    // Lookahead coupling: harmonic compatibility between post_residual and next item
    if next_item_size > 0 && pr >= next_item_size {
        let gap = pr - next_item_size;
        // reward exact or harmonic fits for the next item
        if gap == 0 {
            score -= 45.0;
        } else if gap % cap_frac == 0 {
            score -= 18.0;
        } else if gap < 10 {
            score += 20.0; // would create tiny dead space after next item
        }
    } else if next_item_size > 0 && pr < next_item_size {
        // this bin can't host the next item; mildly penalize if next is large
        score += (next_item_size as f64) * 0.15;
    }

    // Last-chance bonus: if this is the only fitting bin, strongly prefer using it
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 70.0;
    }

    // New-bin candidate: penalize opening a new bin unless current residuals are tight
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let avg_open_residual = if open_bins_count > 0 { mean_residual } else { bin_capacity as f64 };
        // open new bin only when mean residual across open bins is small (packed state)
        let pressure = avg_open_residual / bin_capacity as f64;
        if pressure > 0.35 {
            score += 30.0 + 40.0 * pressure;
        } else {
            score -= 10.0 * (1.0 - pressure);
        }
        // early stream: prefer consolidating into open bins
        score += 15.0 * (1.0 - progress);
    }

    // Prefer filling larger residual gaps proportionally (tightness reward)
    score -= (bin_residual - post_residual) as f64 * 0.05;

    // Mild penalty when bin's residual deviates far from mean (keep residuals uniform)
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += dev * 0.02;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
