pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps are heavily penalized.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0 * (10.0 - post_residual as f64) / 10.0;
    }
    // Perfect fit gets a strong bonus.
    if post_residual == 0 {
        score -= 80.0;
    }

    // Reward filling a bin whose residual was already small (compaction).
    if bin_residual <= 40 {
        score -= 12.0;
    }

    // Last-chance bin before opening a new one: favor using it.
    if fitting_bins_count == 1 {
        score -= 25.0;
    }

    // Open-bin pressure: with many open bins, prefer tightening existing bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += open_bins_count as f64 * (0.35 + 0.3 * progress);

    // Lookahead: if next item fits into post_residual, reward this placement.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 10.0;
    }
    // If next item would NOT fit the dead space we leave, penalize slightly.
    if next_item_size > post_residual && post_residual > 0 {
        score += 5.0;
    }

    // New empty bin candidate: make it unattractive unless nothing reasonable exists.
    if bin_residual == bin_capacity {
        score += 45.0 + mean_residual * 0.2;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap_f = bin_capacity as f64;
    let progress = step_index as f64 / total_items.max(1) as f64;
    let mut score = post_residual as f64;

    // Tiered dead-space shaping (stronger exact-fit rewards)
    if post_residual == 0 {
        score -= 900.0;
    } else if post_residual <= 3 {
        score -= 400.0;
    } else if post_residual <= 12 {
        score -= 80.0;
    } else if post_residual < 20 {
        score += 18.0;
    } else if post_residual < 30 {
        score += 18.0 + (30 - post_residual) as f64 * 0.5;
    }

    // Dead-ratio shaping
    let dead_ratio = post_residual as f64 / cap_f;
    if post_residual > 0 {
        if dead_ratio < 0.03 { score -= 30.0; }
        else if dead_ratio < 0.08 { score -= 12.0; }
        else if dead_ratio > 0.35 { score += 22.0; }
        else if dead_ratio > 0.25 { score += 10.0; }
        score += dead_ratio * 30.0;
    }

    // Lookahead: exact and near-exact fits for the next item
    if next_item_size > 0 {
        let nxt = next_item_size as u32;
        if nxt == post_residual {
            score -= 700.0;
        } else if nxt <= post_residual {
            let post2 = post_residual - nxt;
            score -= 120.0 - (post2 as f64) * 2.0;
            if post2 == 0 { score -= 90.0; }
            if post2 > 0 && post2 < 5 { score -= 26.0; }
            if post2 > 0 && post2 <= 2 { score -= 14.0; }
            if post2 > 0 && post2 <= nxt / 4 { score -= 10.0; }
            if post2 % 10 == 0 && post2 > 0 { score -= 20.0; }
            if post2 >= 20 && post2 % 5 == 0 { score -= 10.0; }
            if post_residual % nxt == 0 { score -= 16.0; }
            if post_residual >= nxt * 2 && post_residual - nxt * 2 <= 4 { score -= 18.0; }
            let chain = post_residual / nxt;
            if chain >= 2 { score -= (chain.min(4)) as f64 * 6.0; }
        } else {
            // next item won't fit here: penalize near-fitting gaps
            let gap = nxt - post_residual;
            if post_residual > 0 {
                if gap <= 3 { score += 35.0; }
                else if gap <= 8 { score += 12.0; }
                if gap <= 5 { score += (6 - gap) as f64 * 4.0; }
                if (gap as f64) > mean_residual * 0.5 { score += 12.0; }
                if post_residual < 15 { score += 40.0; }
                let wasted = gap as f64;
                score += wasted * 0.5;
                if gap > 12 { score += dead_ratio * 70.0; }
            }
        }
    }

    // Compaction pressure scaled by open bins
    score += open_bins_count as f64 * 0.8;

    // Last-chance bin: strongly favor using it
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 45.0;
    }
    if fitting_bins_count <= 2 && post_residual > 0 {
        score -= 8.0;
    }

    // Tightness via relative fill
    let snug = item_size as f64 / bin_residual.max(1) as f64;
    score -= snug * 30.0;
    if item_size == bin_residual { score -= 40.0; }

    // Prefer bins whose residual is below average (consolidating slack)
    if bin_residual < bin_capacity {
        score += (mean_residual - bin_residual as f64) * 1.2;
        if bin_residual as f64 > cap_f * 0.6 { score -= 10.0; }
    }

    // NEW-BIN CANDIDATE handling
    if bin_residual == bin_capacity {
        let newbin_waste = (bin_capacity - item_size) as f64;
        let avg_fill = 1.0 - (mean_residual / cap_f);
        score += 220.0 - avg_fill * 280.0 - progress * 60.0;
        if item_size as f64 / cap_f > 0.75 { score -= 55.0; }
        if item_size >= bin_capacity * 3 / 4 { score -= 25.0; }
        if item_size as f64 > mean_residual { score -= 35.0; }
        if newbin_waste < mean_residual * 0.6 { score -= 30.0; }
        if bin_capacity - item_size <= 4 { score -= 60.0; }
        if next_item_size > 0 {
            let leftover = bin_capacity - item_size;
            if leftover >= next_item_size {
                let tail = leftover % next_item_size;
                if tail == 0 { score -= 18.0; }
                else if tail <= 4 { score -= 14.0; }
                if leftover - next_item_size <= 6 { score -= 35.0; }
                if leftover >= next_item_size * 2 { score -= 12.0; }
            } else if leftover < 10 {
                score += 18.0;
            }
            if next_item_size >= bin_capacity / 2 { score -= 30.0; }
            if (newbin_waste as u32) < next_item_size && newbin_waste < cap_f * 0.12 { score += 24.0; }
            if newbin_waste >= next_item_size as f64 && (newbin_waste as u32) % next_item_size == 0 { score -= 18.0; }
        }
        if fitting_bins_count > 0 {
            score += (fitting_bins_count.min(6) as f64) * 8.0;
            if snug > 0.9 { score += 35.0; }
            if snug > 0.95 { score += 22.0; }
        } else {
            score -= 20.0;
        }
        if progress > 0.6 {
            let waste_tol = (1.0 - progress) * cap_f * 0.35;
            if newbin_waste > waste_tol && fitting_bins_count > 0 { score += 10.0 + progress * 20.0; }
        }
        if progress < 0.1 { score -= 5.0; }
    } else if progress < 0.1 {
        score += 3.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward near-exact fits: dead space below a small threshold is heavily discounted.
    if post_residual < 10 {
        score -= 25.0;
    }
    // Strong reward for perfect fit.
    if post_residual == 0 {
        score -= 40.0;
    }

    // 2-step lookahead: if the next item fits exactly into the post residual,
    // this bin becomes a perfect two-item chain -> very attractive.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 45.0;
        } else if post_residual >= next_item_size {
            // Next item fits: residual after both items is the true dead space.
            let two_step_dead = post_residual - next_item_size;
            score = score * 0.5 + two_step_dead as f64;
            if two_step_dead < 10 {
                score -= 20.0;
            }
        } else {
            // Next item cannot fit here: penalize bins whose residual is only
            // slightly larger than next_item_size (that space will be wasted).
            let gap = next_item_size - post_residual;
            if gap <= 10 {
                score += (10 - gap) as f64 * 1.5;
            }
        }
    }

    // Relative-to-mean coupling: bins tighter than the mean are preferred
    // (concentrate filling), bins looser than the mean are penalized mildly.
    score += (mean_residual - bin_residual as f64) * 0.3;

    // Last-chance bonus: if this is the only fitting bin, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate handling: an empty bin should only win when the item
    // is large or no open bin gives a decent fit. Penalize opening new bins
    // early on unless the item is huge.
    if bin_residual == bin_capacity {
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        let large_item = item_size as f64 > 0.6 * bin_capacity as f64;
        if !large_item && fitting_bins_count > 0 {
            score += 30.0 - 10.0 * progress;
        }
        // A fresh bin is fine if the next item is large too (future capacity).
        if next_item_size > 0 && next_item_size as f64 > 0.6 * bin_capacity as f64 {
            score -= 10.0;
        }
    }

    // Slight preference for filling bins with more content already (fewer open bins better).
    score += open_bins_count as f64 * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: post_residual small relative to item size.
    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 18.0 * fit_ratio;

    // Penalize dead space that is too small to hold typical future items.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    } else if post_residual >= 10 && post_residual < 20 {
        score += 8.0;
    }

    // Last-chance bonus: only this bin fits, avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 30.0;
    }

    // Lookahead coupling: if next item could pair with the post residual,
    // reward leaving exactly that much space.
    if next_item_size > 0 {
        let diff = (post_residual as i64 - next_item_size as i64).abs() as f64;
        score += 0.6 * diff;
        if post_residual as i64 == next_item_size as i64 {
            score -= 22.0;
        }
        // If next item won't fit anywhere else, prefer conserving space.
        if next_item_size > post_residual {
            score += 4.0;
        }
    }

    // Time horizon: early in the stream, be more liberal with tight packing;
    // late in the stream, strongly avoid opening new bins.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score -= 20.0 * progress * (fitting_bins_count == 1) as i32 as f64;
    score += 10.0 * (1.0 - progress) * (post_residual as f64 / bin_capacity as f64);

    // Global state: many open bins with slack -> prefer using existing slack.
    if open_bins_count > 2 {
        let slack = mean_residual - post_residual as f64;
        score += 0.15 * slack;
        score -= 0.05 * open_bins_count as f64 * (1.0 - fit_ratio);
    }

    // New-bin candidate: penalize opening a bin unless current residual is unusable.
    if bin_residual == bin_capacity {
        let waste_threshold = 12.0 + 20.0 * progress;
        if fitting_bins_count > 0 {
            let best_possible = (bin_residual - item_size) as f64;
            if best_possible <= waste_threshold && post_residual >= item_size as f64 * 0.5 {
                score -= 15.0; // allow opening a fresh bin for a good future
            } else {
                score += 40.0; // keep using existing bins
            }
        } else {
            score -= 50.0; // nothing fits elsewhere: must open new bin
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let mut score = pr;

    // Normalize post-residual and couple with progress via smooth polynomial terms
    let pr_norm = pr / cap;
    let tightness = 1.0 - pr_norm;

    // Reward tight fits more strongly as stream progresses (smooth quadratic coupling)
    score -= tightness * tightness * (1.0 + 2.0 * progress) * 20.0;

    // Penalize large residuals mildly, increasing with progress (wasted capacity late)
    score += pr_norm * pr_norm * progress * 15.0;

    // Lookahead coupling: reward if next item fits the post-residual
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        let slack = pr - nxt;
        if slack >= 0.0 {
            let fit_quality = 1.0 - (slack / cap).abs();
            score -= fit_quality * (10.0 + 10.0 * (1.0 - progress));
        } else {
            score += 5.0;
        }
    }

    // Last-chance bin: strong reward to use it before opening a new bin
    if fitting_bins_count == 1 {
        score -= 25.0 * (1.0 + progress);
    }

    // Mild penalty when many bins are open (discourage bin sprawl)
    score += open_bins_count as f64 * 0.05;

    // Deviation from mean residual: prefer bins near the mean (smooth coupling)
    let dev = (pr - mean_residual) / cap;
    score += dev * dev * 8.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
