pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: bins whose leftover falls into
    // "small residue" classes are more likely to be closed out efficiently.
    let quarter = bin_capacity / 4;
    let half = bin_capacity / 2;

    // Reward near-perfect fits strongly.
    if post_residual == 0 {
        score -= 60.0;
    } else if post_residual <= 10 {
        score -= 35.0;
    } else if post_residual <= quarter {
        score -= 12.0;
    }

    // Penalize residues in the "dead zone": too small for the minimum item
    // (min size 10) but wasteful.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Modulo / integer-division classes on post_residual:
    // residues divisible by 10 pair cleanly with minimum-size items.
    if post_residual % 10 == 0 && post_residual > 0 {
        score -= 8.0;
    }
    // Half-capacity residues are versatile harmonic anchors.
    if post_residual == half {
        score -= 6.0;
    }

    // Lookahead coupling: if the next item fits exactly in post_residual,
    // this bin becomes a two-item chain — reward heavily.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 45.0;
        } else if next_item_size <= post_residual {
            score -= 15.0;
            // bonus if next item lands in a good harmonic class too
            if (post_residual - next_item_size) <= 10 {
                score -= 10.0;
            }
        } else {
            // next item cannot follow: leftover likely dead space
            score += 10.0;
            if post_residual < 10 {
                score += 10.0;
            }
        }
    }

    // Last-chance bin: strongly prefer using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate: only attractive when the item is large relative to
    // capacity or no good existing fit exists (post_residual small already
    // handles fits; here penalize opening bins for small items).
    if bin_residual == bin_capacity {
        let frac = item_size as f64 / bin_capacity as f64;
        if frac < 0.5 {
            score += 30.0 * (0.5 - frac);
        }
        if next_item_size > 0 && next_item_size >= item_size {
            score -= 10.0; // large stream ahead: fresh bin is fine
        }
        if open_bins_count == 0 {
            score -= 100.0;
        }
    }

    // Mild pressure to consolidate: prefer bins tighter than the mean.
    let mean_gap = mean_residual - bin_residual as f64;
    score += 0.05 * mean_gap;

    // Slight stream-position modulation: late in the stream, avoid leaving
    // many half-empty bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += progress * (post_residual as f64) * 0.1;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
