        } else if nis <= post_residual {
            let post2 = post_residual - nis;
            score -= 120.0 - (post2 as f64) * 2.0;
            if post2 == 0 { score -= 110.0; }
            if post2 > 0 && post2 < 5 { score -= 28.0; }
            if post2 % 10 == 0 && post2 > 0 { score -= 28.0; }
            if post_residual % nis == 0 { score -= 18.0; }
            if post_residual >= nis * 2 && post_residual - nis * 2 <= 4 { score -= 20.0; }
            let chain = post_residual / nis;
            if chain >= 2 { score -= (chain.min(4)) as f64 * 6.0; }
            if post2 > 0 && post2 <= nis / 4 { score -= 10.0; }
        } else {
            // next item won't fit here: penalize leaving a nearly-fitting gap
            let gap = next_item_size - post_residual;
            if post_residual > 0 {
                if gap <= 3 { score += 35.0; }
                else if gap <= 8 { score += 12.0; }
                if (gap as f64) > mean_residual * 0.5 { score += 14.0; }
                if gap <= 5 { score += (6 - gap) as f64 * 4.0; }
                if post_residual < 15 { score += 30.0; }
            }
        }
    }

    // Compaction pressure scaled by open bins
    score += open_bins_count as f64 * 0.8;

    // Last-chance bin: strongly favor using it
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 55.0;
    }

    // Tightness via relative fill
    score -= (item_size as f64 / bin_residual.max(1) as f64) * 30.0;

    // NEW-BIN CANDIDATE handling
    if bin_residual == bin_capacity {
        let avg_fill = 1.0 - (mean_residual / cap_f);
        let newbin_waste = (bin_capacity - item_size) as f64;
        score += 220.0 - avg_fill * 280.0 - progress * 65.0;
        // big items deserve a fresh bin when few alternatives fit well
        if item_size as f64 / cap_f > 0.75 { score -= 55.0; }
        if item_size as f64 > mean_residual { score -= 40.0; }
        if newbin_waste < mean_residual * 0.5 { score -= 30.0; }
        if bin_capacity - item_size <= 4 { score -= 70.0; }
        if next_item_size > 0 && (bin_capacity - item_size) >= next_item_size
            && (bin_capacity - item_size) - next_item_size <= 6 {
            score -= 38.0;
        }
        if next_item_size > 0 {
            let leftover = bin_capacity - item_size;
            if leftover >= next_item_size {
                let tail = leftover % next_item_size;
                if tail == 0 { score -= 20.0; }
                else if tail <= 4 { score -= 14.0; }
            }
            if leftover < next_item_size && leftover < 10 { score += 18.0; }
        }
        if fitting_bins_count > 0 {
            score += (fitting_bins_count.min(5) as f64) * 9.0 + 20.0;
            if newbin_waste > cap_f * 0.35 { score += 18.0; }
        }
        if progress > 0.6 {
            let waste_tol = (1.0 - progress) * cap_f * 0.35;
            if newbin_waste > waste_tol && fitting_bins_count > 0 { score += 12.0 + progress * 20.0; }
        }
        if next_item_size > 0 && newbin_waste > 0.0 && (newbin_waste as u32) < next_item_size && newbin_waste < cap_f * 0.12 {
            score += 26.0;
        }
    } else {
        // Dead-space ratio shaping for open bins
        let dead_ratio = post_residual as f64 / cap_f;
        if dead_ratio < 0.03 { score -= 38.0; }
        else if dead_ratio < 0.08 { score -= 14.0; }
        else if dead_ratio > 0.35 { score += 24.0; }
        else if dead_ratio > 0.25 { score += 10.0; }
        score += dead_ratio * 30.0;

        // unusable gap ahead of next item
        if post_residual > 0 && next_item_size > 0 && post_residual < next_item_size {
            let wasted = next_item_size as f64 - post_residual as f64;
            score += wasted * 0.6;
            if wasted > 12.0 { score += dead_ratio * 60.0; }
        }
        // reusable residual: divisible by next item
        if post_residual > 0 && next_item_size > 0 && post_residual % next_item_size.max(1) <= 2 && post_residual >= next_item_size {
            score -= 10.0;
        }
        if item_size == bin_residual { score -= 45.0; }
    }

    // Prefer bins whose residual is below average (consolidating slack)
    if bin_residual < bin_capacity {
        score += (mean_residual - bin_residual as f64) * 1.2;
    }

    // Early stream diversity nudge
    if progress < 0.1 { score += 3.0; }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: penalize small unusable gaps heavily.
    // A gap is "dead" if it cannot fit even the smallest plausible item.
    let dead_threshold = 10u32;
    if post_residual < dead_threshold {
        score += 40.0 * (dead_threshold - post_residual) as f64;
    }
    // Non-linear penalty for awkward mid-range gaps that few items can use.
    if post_residual > 0 && post_residual < item_size.min(30) {
        score += (30 - post_residual.min(30)) as f64 * 0.8;
    }

    // Reward near-perfect fits strongly.
    if post_residual == 0 {
        score -= 100.0;
    } else if post_residual <= 5 {
        score -= 25.0;
    }

    // Lookahead: if the next item fits exactly in the post residual, big reward.
    if next_item_size > 0 && post_residual >= next_item_size {
        let gap = post_residual - next_item_size;
        if gap < 10 {
            score -= 30.0;
        } else {
            score -= 8.0;
        }
    } else if next_item_size > post_residual && post_residual > 0 {
        // Next item won't fit here; penalize leaving a stranded gap.
        score += 6.0;
    }

    // Open-bin pressure: discourage scattering across many bins.
    score += open_bins_count as f64 * 0.5;

    // Last-chance bonus: if this is the only bin that fits, prefer using it
    // to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 20.0;
    }

    // Mild alignment with mean residual: prefer bins tighter than average.
    score -= (mean_residual - post_residual as f64) * 0.3;

    // Early in the stream, be slightly more willing to open fresh bins
    // (keeps flexibility); later, consolidate tightly.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity {
        score += 10.0 - 15.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit reward
    if post_residual == 0 {
        score -= 1000.0;
    } else if post_residual <= 5 {
        score -= 50.0;
    }

    // Aggressive 2-step lookahead: reward when next item fits the post residual
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 900.0;
        } else if next_item_size < post_residual {
            let waste = (post_residual - next_item_size) as f64;
            score -= 300.0 / (1.0 + waste / 10.0);
        } else {
            // next item cannot fit: penalize large post residuals
            let unusable = (post_residual as f64).min((next_item_size - post_residual) as f64);
            score += unusable * 0.8;
        }
    } else {
        // last item: minimize post residual strongly
        score += post_residual as f64 * 2.0;
    }

    // Relative to mean residual: bins tighter than average are more valuable
    score += (mean_residual - bin_residual as f64) * 0.6;

    // Last-chance bin bonus
    if fitting_bins_count == 1 {
        score -= 120.0;
    }

    // New-bin candidate: penalize opening a bin unless the item is huge or fit is poor
    if bin_residual == bin_capacity {
        score += 250.0;
        if item_size > bin_capacity / 2 {
            score -= 150.0;
        }
        if next_item_size > 0 && post_residual < next_item_size {
            score -= 100.0; // opening a bin gives room for the next item
        }
    }

    // Late in stream: prefer closing bins tightly
    let progress = step_index as f64 / total_items as f64;
    score += post_residual as f64 * progress * 0.5;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: small post_residual is good; amplify near-perfect fits.
    let fit_ratio = item_size as f64 / bin_residual as f64;
    score -= 30.0 * fit_ratio * fit_ratio;

    // Penalize leaving dead space that the next item cannot use.
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            // Next item fits here: strong reward for chaining.
            score -= 15.0;
            let chain_waste = post_residual - next_item_size;
            score -= 10.0 * (1.0 - chain_waste as f64 / bin_capacity as f64);
        } else {
            // Dead space: penalize proportionally to unusable gap.
            let dead = post_residual.min(next_item_size - 1) as f64;
            score += 0.3 * dead;
        }
    } else {
        // Last item: only post_residual matters, tighten it.
        score += 0.2 * post_residual as f64;
    }

    // Last-chance bin: strongly prefer using it over opening a new bin.
    if fitting_bins_count == 1 {
        score -= 25.0;
    } else if fitting_bins_count > 2 {
        // Many alternatives: mild penalty so the best-fitting bin wins.
        score += 1.5 * (fitting_bins_count as f64).ln();
    }

    // Global state coupling: prefer filling bins when mean residual is low
    // (bins are already tight); prefer new bins when open bins are loose.
    let mr = mean_residual.max(0.0);
    score += 0.15 * (mr - post_residual as f64);

    // Time horizon: late in the stream, consolidate aggressively;
    // early, allow opening new bins to preserve flexibility.
    let t = step_index as f64 / total_items.max(1) as f64;
    let new_bin_bias = 20.0 * (1.0 - t);
    if bin_residual == bin_capacity {
        // New-bin candidate: base cost plus early-stream flexibility bonus.
        score += 8.0 + new_bin_bias;
        // Opening a bin is attractive if item is large (hard to place later)
        // and no existing bin fits well.
        if item_size >= 60 && fitting_bins_count <= 1 {
            score -= 18.0;
        }
    } else {
        // Existing bin: slight preference when many bins are open (consolidate).
        score -= 0.05 * open_bins_count as f64;
    }

    // Non-linear residual shaping: residuals in awkward mid-range (too big
    // for small items, too small for large ones) are penalized.
    if post_residual >= 1 && post_residual < 10 {
        score += 12.0; // tiny unusable sliver
    } else if post_residual > 50 {
        score -= 3.0; // roomy remainder is reusable
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 1 { step_index as f64 / (total_items - 1) as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let norm_post = post / cap;
    let norm_item = item_size as f64 / cap;
    let norm_next = next_item_size as f64 / cap;

    let mut score = post;

    // Smooth polynomial coupling: post_residual penalized more as stream progresses
    let poly = norm_post * norm_post * (1.0 + progress) + norm_post * norm_item * (0.5 + progress);
    score += 40.0 * poly;

    // Reward tight fits (small post residual) more strongly late in the stream
    score -= (1.0 - norm_post) * (1.0 - norm_post) * (20.0 + 30.0 * progress);

    // Dead space penalty: unusable space relative to smallest plausible item
    if post > 0.0 && post < 10.0 {
        score += 15.0 * (10.0 - post) / 10.0;
    }

    // Lookahead: favor leaving space compatible with the next item
    if next_item_size > 0 {
        let diff = (post - norm_next * cap) / cap;
        score += 10.0 * diff * diff;
    }

    // Last-chance bonus: if this is the only fitting bin, strongly prefer using it
    if fitting_bins_count == 1 {
        score -= 25.0 + 15.0 * progress;
    }

    // Mild preference for bins below mean residual (balance load) with smooth coupling
    let dev = (bin_residual as f64 - mean_residual) / cap;
    score += 5.0 * dev * (1.0 - progress);

    // New-bin candidate: penalize slightly so we prefer open bins unless they fit poorly
    if bin_residual == bin_capacity {
        score += 8.0 + 20.0 * norm_item * (1.0 - progress);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap_f = bin_capacity as f64;
    let mut score = post_residual as f64;
    let progress = step_index as f64 / total_items.max(1) as f64;

    // ---- New-bin candidate branch ----
    if bin_residual == bin_capacity {
        let avg_fill = 1.0 - (mean_residual / cap_f);
        score += 260.0 - avg_fill * 340.0 - progress * 70.0;
        if fitting_bins_count > 0 {
            score += (fitting_bins_count as f64).min(5.0) * 9.0 + 20.0;
            let snug = item_size as f64 / (bin_residual.max(1) as f64);
            if snug > 0.9 { score += 40.0; }
            if snug > 0.95 { score += 28.0; }
            if snug > 0.98 { score += 18.0; }
        }
        let leftover = bin_capacity - item_size;
        if next_item_size > 0 {
            if leftover >= next_item_size {
                let tail = leftover % next_item_size;
                if tail == 0 { score -= 12.0; }
                else if tail <= 4 { score -= 16.0; }
            } else if leftover < 10 {
                score += 18.0;
            }
        }
        if item_size >= bin_capacity * 3 / 4 { score -= 55.0; }
        let newbin_waste = leftover as f64;
        if newbin_waste > 0.0 && (newbin_waste as u32) < next_item_size && newbin_waste < cap_f * 0.12 {
            score += 26.0;
        }
        if progress > 0.6 && fitting_bins_count > 0 {
            let waste_tol = (1.0 - progress) * cap_f * 0.35;
            if newbin_waste > waste_tol { score += 10.0 + progress * 22.0; }
        }
        return score;
    }

    // ---- Open-bin branch ----
    if post_residual == 0 {
        score -= 1180.0;
    } else if post_residual <= 3 {
        score -= 500.0;
    } else if post_residual <= 12 {
        score -= 98.0;
    } else if post_residual < 20 {
        score += 18.0;
    } else if post_residual < 30 {
        score += 18.0 + (30 - post_residual) as f64 * 0.6;
    }

    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 900.0;
        } else if next_item_size <= post_residual {
            let post2 = post_residual - next_item_size;
            score -= 135.0 - (post2 as f64) * 2.0;
            if post2 == 0 { score -= 110.0; }
            if post2 > 0 && post2 < 5 { score -= 28.0; }
            if post2 % 10 == 0 && post2 > 0 { score -= 28.0; }
            if post2 >= 20 && post2 % 5 == 0 { score -= 12.0; }
            if post_residual >= next_item_size * 2 && post_residual - next_item_size * 2 <= 4 { score -= 20.0; }
            if post_residual % next_item_size == 0 { score -= 18.0; }
            let chain = post_residual / next_item_size;
            if chain >= 2 { score -= (chain.min(4)) as f64 * 6.0; }
        } else {
            score += 20.0;
            if post_residual % 10 == 0 { score -= 15.0; }
            if post_residual > 0 && post_residual < 15 { score += 45.0; }
            if post_residual > 0 && (next_item_size - post_residual) <= 3 { score += 35.0; }
            let gap = next_item_size as f64 - post_residual as f64;
            if gap > 0.0 && gap <= 8.0 { score += 12.0; }
            if post_residual as f64 > mean_residual * 1.4 { score -= 12.0; }
        }
    }

    // Dead-space ratio shaping
    let dead_ratio = post_residual as f64 / cap_f;
    if dead_ratio < 0.03 { score -= 38.0; }
    else if dead_ratio < 0.08 { score -= 14.0; }
    else if dead_ratio > 0.35 { score += 24.0; }
    else if dead_ratio > 0.25 { score += 10.0; }
    score += dead_ratio * 30.0;

    // Tightness and residual alignment
    let tightness = 1.0 - (item_size as f64 / bin_residual.max(1) as f64);
    score += tightness * 85.0;
    score += (mean_residual - bin_residual as f64) * 1.5;
    if item_size == bin_residual { score -= 45.0; }

    // Last-chance bin: strongly favor using it
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // Compaction pressure
    score += open_bins_count as f64 * 0.8;

    // Late stream: prefer reusing bins with usable residuals
    if progress > 0.75 && post_residual > 0 && post_residual < next_item_size {
        score += 14.0;
    }
    if post_residual > 60 { score += 12.0; }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: residues modulo 10 define "dead space classes".
    let residue = post_residual % 10;
    // Penalize awkward residues (1..9 non-zero small remainders are hard to fill).
    if residue > 0 && residue < 10 {
        score += (10 - residue) as f64 * 1.5;
    }
    // Perfect-fit classes (residue 0) get a strong reward.
    if residue == 0 {
        score -= 12.0;
    }
    // Exact fill reward.
    if post_residual == 0 {
        score -= 25.0;
    }

    // Capacity fraction thresholds: post_residual in (0, 10] is a near-dead bin.
    if post_residual > 0 && post_residual <= 10 {
        score += 8.0;
    }

    // Lookahead coupling: if next item fits the post residual, reward strongly.
    if next_item_size > 0 && post_residual >= next_item_size {
        let next_class = next_item_size % 10;
        // Harmonic bonus when next item also lands on a good residue after placement.
        let post2 = post_residual - next_item_size;
        if post2 % 10 == 0 {
            score -= 18.0;
        } else {
            score -= 6.0 + (post2 % 10) as f64 * 0.4;
        }
        let _ = next_class;
    } else if next_item_size > 0 {
        // Next item won't fit here: penalize proportionally to wasted capacity fraction.
        score += (next_item_size as f64 / bin_capacity as f64) * 10.0;
    }

    // Last-chance bin: strongly favor using it before opening a new one.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate: make it moderately attractive only when current fit is bad
    // (large post residual or awkward residue) and stream is early.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let fit_quality = (post_residual as f64 / bin_capacity as f64) + (residue as f64) * 0.05;
        score = 100.0 - 30.0 * (1.0 - progress) + 20.0 * fit_quality;
        if next_item_size > 0 && next_item_size <= bin_capacity {
            score -= 5.0;
        }
        if open_bins_count == 0 {
            score -= 40.0;
        }
    }

    // Mild tie-break toward bins with low mean residual (compact packing).
    score += (mean_residual - post_residual as f64) * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals too small for any item (1..100 range,
    // but small gaps < 12 are almost surely unusable) are heavily penalized.
    if post_residual > 0 && post_residual < 12 {
        score += 60.0;
    }
    // Medium unusable gaps (below typical small item sizes) get graded penalty.
    if post_residual >= 12 && post_residual < 20 {
        score += 15.0;
    }

    // Perfect or near-perfect fit reward.
    if post_residual == 0 {
        score -= 40.0;
    } else if post_residual <= 5 {
        score -= 15.0;
    }

    // Last-chance bin: if this is the only bin that fits, strongly prefer it
    // to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // Open-bins pressure: many open bins -> prefer consolidation into existing bins.
    let pressure = open_bins_count as f64 * 0.6;
    score += pressure * (post_residual as f64 / bin_capacity as f64);

    // New-bin candidate: only attractive when the item fits poorly everywhere
    // (large post_residual relative to capacity) or few bins are open.
    if bin_residual == bin_capacity {
        score += 10.0 + 0.5 * open_bins_count as f64;
        // Lookahead: if next item is large, a fresh bin is more valuable.
        if next_item_size > 0 && next_item_size >= 60 {
            score -= 20.0;
        }
        // Early stream: opening bins is cheap.
        if total_items > 0 && (step_index as f64) / (total_items as f64) < 0.3 {
            score -= 8.0;
        }
    }

    // Lookahead synergy: if the next item exactly fits the post_residual, reward.
    if next_item_size > 0 && next_item_size == post_residual {
        score -= 30.0;
    } else if next_item_size > 0 && next_item_size <= post_residual {
        score -= 5.0;
    }

    // Mean residual coupling: prefer bins whose residual is below average
    // (tighter bins get priority, keeps large residuals for large future items).
    if (bin_residual as f64) > mean_residual {
        score += 4.0;
    } else {
        score -= 2.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strongly prefer exact/near-exact fills.
    if post_residual == 0 {
        score -= 500.0;
    } else if post_residual <= 5 {
        score -= 200.0;
    }

    // 2-step lookahead: reward bins whose post_residual can host the next item.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if (post_residual as f64) >= nxt {
            // Perfect 2-step chain: post_residual == next_item_size exactly.
            if (post_residual as u32) == next_item_size {
                score -= 300.0;
            } else {
                // Reward proportional to how well next item fills the residual after it.
                let second_residual = post_residual as f64 - nxt;
                score -= 150.0 * (1.0 - second_residual / bin_capacity as f64);
            }
        } else {
            // Next item won't fit: penalize dead-space creation.
            score += 0.5 * (nxt - post_residual as f64);
        }
    }

    // Compare post_residual against mean residual: leaving less than average
    // residual is good (tight packing); leaving more is wasteful.
    let pr = post_residual as f64;
    if mean_residual > 0.0 {
        let rel = (pr - mean_residual) / mean_residual;
        score += 30.0 * rel;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 250.0;
    }

    // Penalize choosing an empty/new bin when open bins could fit the item,
    // unless the item is large and a fresh bin yields a clean split.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let new_bin_bonus = 120.0 * (item_size as f64 / bin_capacity as f64) * (1.0 - 0.5 * progress);
        if fitting_bins_count > 0 {
            score += 400.0; // discourage new bin when alternatives exist
        }
        score -= new_bin_bonus;
    }

    // Mild penalty for very small leftovers that are hard to reuse later.
    if post_residual > 0 && post_residual < 10 {
        score += 40.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits (small post_residual) with a superlinear bonus.
    let tight = 1.0 - (post_residual as f64) / (bin_capacity as f64);
    score -= 12.0 * tight * tight;

    // Penalize dead space that is too small for typical future items.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Lookahead: if the next item fits exactly into the post residual, reward heavily.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            let gap = (post_residual - next_item_size) as f64;
            score -= 8.0 * (1.0 - gap / (bin_capacity as f64));
        } else {
            score += 4.0;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 15.0;
    }

    // Many open bins with high mean residual: prefer consolidation into fuller bins.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    if (bin_residual as f64) < mean_residual {
        score -= 3.0 * (0.5 + progress);
    } else {
        score += 2.0 * progress;
    }

    // New-bin candidate: penalize mildly early, more strongly when open bins exist
    // that could absorb the item (encourage consolidation), but allow opening when
    // the item would leave a very awkward residual.
    if bin_residual == bin_capacity {
        let awkward = (post_residual == 0) as i32; // exact fit into fresh bin is impossible here
        let _ = awkward;
        score += 10.0 + 6.0 * (open_bins_count as f64).sqrt();
        if fitting_bins_count == 0 {
            score -= 30.0; // no open bin fits: opening is necessary
        }
        if next_item_size > 0 && next_item_size <= bin_capacity {
            score -= 4.0; // fresh bin is flexible for the lookahead
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap_f = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Tiered residual rewards: perfect and near-perfect fits are heavily preferred.
    if post_residual == 0 {
        score -= 900.0;
    } else if post_residual <= 3 {
        score -= 400.0;
    } else if post_residual <= 12 {
        score -= 80.0;
    } else if post_residual < 20 {
        score += 16.0;
    } else if post_residual < 30 {
        score += 16.0 + (30 - post_residual) as f64 * 0.6;
    }

    // Lookahead: reward placements whose residual can host the next item.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 700.0;
        } else if next_item_size <= post_residual {
            let post2 = post_residual - next_item_size;
            score -= 110.0 - post2 as f64 * 1.8;
            if post2 == 0 {
                score -= 90.0;
            }
            if post2 > 0 && post2 < 5 {
                score -= 24.0;
            }
            if post_residual % next_item_size == 0 {
                score -= 15.0;
            }
            let chain = post_residual / next_item_size;
            if chain >= 2 {
                score -= (chain.min(4)) as f64 * 6.0;
            }
        } else {
            score += 18.0;
            let gap = next_item_size as f64 - post_residual as f64;
            if post_residual > 0 && gap <= 3.0 {
                score += 30.0;
            }
            if post_residual > 0 && post_residual < 15 {
                score += 40.0;
            }
            if post_residual as f64 > mean_residual * 1.4 {
                score -= 10.0;
            }
        }
    }

    // Dead-space characterization relative to next item.
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        let unusable = (next_item_size - post_residual) > 12;
        let dead_frac = post_residual as f64 / cap_f;
        if unusable {
            score += dead_frac * 80.0;
        } else {
            score += (next_item_size as f64 - post_residual as f64) * 0.5;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 28.0;
    }
    if fitting_bins_count > 1 {
        score += 2.0 * (fitting_bins_count as f64 - 1.0).min(6.0);
    }

    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    // Global state: discourage spreading when many bins hold slack.
    if open_bins_count > 3 && mean_residual > item_size as f64 {
        score += 0.05 * open_bins_count as f64;
    }

    // New-bin candidate: open a fresh bin only when it beats awkward reuse.
    if bin_residual == bin_capacity {
        let newbin_waste = (bin_capacity - item_size) as f64;
        score += 200.0 - (1.0 - mean_residual / cap_f) * 260.0 - progress * 55.0;
        if next_item_size > 0 && post_residual > 0 && next_item_size as f64 > post_residual as f64 {
            score -= 18.0;
        }
        if fitting_bins_count > 0 {
            score += (fitting_bins_count as f64).min(5.0) * 9.0 + 20.0;
            let snug = item_size as f64 / bin_residual.max(1) as f64;
            if snug > 0.9 { score += 35.0; }
            if snug > 0.95 { score += 25.0; }
        }
        if item_size >= bin_capacity * 3 / 4 {
            score -= 50.0;
        }
        if next_item_size > 0 && next_item_size <= bin_capacity - item_size {
            let tail = (bin_capacity - item_size) % next_item_size;
            if tail == 0 { score -= 18.0; }
            else if tail <= 4 { score -= 12.0; }
        }
        if newbin_waste > 0.0 && (newbin_waste as u32) < next_item_size && newbin_waste < cap_f * 0.12 {
            score += 22.0;
        }
        if progress > 0.6 {
            let waste_tol = (1.0 - progress) * cap_f * 0.35;
            if newbin_waste > waste_tol && fitting_bins_count > 0 {
                score += 10.0 + progress * 20.0;
            }
        }
    } else {
        // Existing bin: prefer bins whose residual is tight relative to the mean.
        let tightness = 1.0 - (item_size as f64 / bin_residual.max(1) as f64);
        score += tightness * 70.0;
        score += (mean_residual - bin_residual as f64) * 1.2;
        let dead_ratio = post_residual as f64 / cap_f;
        if dead_ratio < 0.03 {
            score -= 35.0;
        } else if dead_ratio > 0.35 {
            score += 22.0;
        }
        if item_size == bin_residual {
            score -= 40.0;
        }
        if post_residual > 0 && (post_residual as f64) < mean_residual * 0.25 {
            score -= 12.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 1 { step_index as f64 / (total_items as f64 - 1.0) } else { 0.0 };
    let cap = bin_capacity as f64;
    let post = post_residual as f64;

    // Base: prefer tight fits (small post_residual), scaled non-linearly.
    let mut score = post * (1.0 + 0.8 * post / cap);

    // Smooth polynomial coupling of post_residual with stream progress:
    // late in the stream, waste is more costly.
    let p = progress;
    let coupling = 1.0 + 1.5 * p * p + 2.0 * p * p * p;
    score *= coupling;

    // Penalize dead space that can't plausibly fit future items (smooth term).
    let dead = (post - next_item_size as f64).max(0.0) / cap;
    score += 6.0 * dead * dead * (1.0 + p);

    // Reward if next item fits exactly in post_residual (smooth lookahead bonus).
    if next_item_size > 0 {
        let gap = (post - next_item_size as f64).abs();
        score -= 4.0 * (1.0 - gap / cap).max(0.0) * (1.0 + 0.5 * p);
    }

    // Last-chance bin: strongly prefer using it over opening a new bin.
    if fitting_bins_count == 1 {
        score -= 8.0 + 6.0 * p;
    }

    // Slight preference to fill bins when many are open.
    score += 0.15 * open_bins_count as f64 * (post / cap);

    // Mild pull toward bins with residual close to item need (relative to mean).
    score += 0.3 * (bin_residual as f64 - mean_residual).abs() / cap;

    // New-bin candidate: make it attractive only when fits are terrible.
    if bin_residual == bin_capacity {
        let worst = (post_residual as f64) > 0.0; // empty bin post_residual == capacity
        if worst && post > 0.35 * cap * (1.0 + p) {
            score -= 5.0 + 10.0 * p;
        } else {
            score += 3.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: modulo classes capture "how reusable" the leftover is.
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;

    // Fractional fill of the bin achieved by this placement.
    let fill = (bin_capacity - post_residual) as f64 / cap;

    // Reward high fill strongly (non-linear).
    score -= 12.0 * fill * fill;

    // Harmonic class bonus: post_residual divisible by common small item sizes (e.g. 10, 20, 25, 50)
    // is more likely reusable by future items.
    if post_residual > 0 {
        if post_residual % 10 == 0 { score -= 3.0; }
        if post_residual % 20 == 0 { score -= 2.0; }
        if post_residual % 25 == 0 { score -= 1.5; }
        if post_residual % 50 == 0 { score -= 2.0; }
    } else {
        // Perfect fit: huge reward.
        score -= 25.0;
    }

    // Penalize dead space: post_residual too small for the smallest plausible item.
    if post_residual > 0 && post_residual < 10 {
        score += 15.0;
    }

    // Lookahead coupling: if the next item fits exactly in the post_residual, big reward.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 20.0;
        } else if next_item_size <= post_residual {
            score -= 4.0 * (next_item_size as f64 / (post_residual as f64 + 1.0));
        } else {
            score += 2.0; // next item can't use this residual
        }
    }

    // Last-chance bin: strongly prefer using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 8.0;
    }

    // New-bin candidate handling: penalize opening a new bin unless current fit is poor.
    if bin_residual == bin_capacity {
        // Opening fresh bin: neutral baseline, penalize when many bins already fit the item.
        score += 6.0 + 2.0 * fitting_bins_count as f64;
        if fitting_bins_count == 0 {
            score -= 30.0; // must open a new bin
        }
    }

    // Mild preference to consolidate when many bins are open.
    score += 0.05 * open_bins_count as f64;

    // Slight drift with stream progress to prefer tighter packing later.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= 2.0 * progress * fill;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps are heavily penalized.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    } else if post_residual == 0 {
        // Perfect fit is strongly rewarded.
        score -= 80.0;
    } else {
        // Usable residual: mild reward proportional to post space, but only
        // if it can plausibly host the next item.
        if next_item_size > 0 && post_residual >= next_item_size {
            score -= 8.0;
        }
    }

    // Dead-space coupling: penalize residuals that no realistic item (>=1)
    // can fill well — i.e., residual in (0, min_item). Already handled, but
    // add gradient pressure for tiny-but-nonzero leftovers.
    if post_residual > 0 && post_residual < 20 {
        score += (20 - post_residual) as f64 * 2.5;
    }

    // Last-chance pressure: if this is the only bin that fits, avoid opening
    // a new bin unless the fit is terrible.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // Open-bin pressure: with many open bins, prefer consolidating into
    // existing bins rather than opening new ones.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    let pressure = open_bins_count as f64 * (1.0 + progress);
    if bin_residual == bin_capacity {
        // New-bin candidate: penalize proportional to open-bin pressure,
        // but discount when the current fit would create dead space.
        score += 40.0 + pressure * 2.0;
        if post_residual > 0 && post_residual < 10 {
            score -= 55.0; // opening a new bin beats creating dead space
        }
    } else {
        // Existing bin: slight reward scaled by pressure to keep bins closed.
        score -= pressure * 0.5;
    }

    // Prefer bins tighter than average (better consolidated).
    score += (mean_residual - bin_residual as f64) * 0.3;

    // Lookahead: if next item fits exactly in post_residual, reward.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 20.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

