    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let norm_post = post / cap;

    // Base: quadratic waste penalty (strongly prefer tight fits)
    let mut score = norm_post * norm_post * cap;

    // Smooth non-linear coupling of waste with stream progress:
    // later in the stream, waste becomes increasingly costly (fewer future items to fill gaps)
    score += norm_post * (1.0 + 3.0 * progress * progress) * 2.0;

    // Reward bins whose residual is close to mean residual (keeps bin profile balanced)
    let balance = (post - mean_residual).abs() / cap;
    score += balance * balance * cap * (0.5 + progress);

    // Last-chance bonus: if this is the only fitting bin, strongly prefer using it
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 12.0;
    }

    // Lookahead coupling: if next item fits exactly in post_residual, reward heavily
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if post >= nxt {
            let gap = (post - nxt) / cap;
            score -= 8.0 * (1.0 - gap * gap);
        } else {
            // post_residual too small for next item: mild penalty for creating dead space
            score += (nxt - post) / cap * 5.0 * (0.5 + progress);
        }
    }

    // New-bin candidate: neutral-ish baseline that only wins when all fits are terrible
    if bin_residual == bin_capacity {
        // discourage opening new bins early, more acceptable late or when many bins open
        score = cap * (1.0 - 0.3 * progress) + 0.15 * open_bins_count as f64;
        if next_item_size > 0 && (next_item_size as f64) <= cap * 0.5 {
            score += 2.0; // item likely pairs well in an existing half-empty bin
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: bins whose leftover falls into
    // "small" residue classes (mod 10) are more likely to be closed out usefully.
    let post = post_residual;
    let residue_class = (post % 10) as f64;
    let quotient_class = (post / 10) as f64;

    // Reward tight fits: post_residual near 0 is ideal.
    score -= 30.0 * (1.0 - (post as f64) / cap).powi(3);

    // Penalize dead space in awkward residue classes (leftovers that few item
    // sizes 1..=100 can exactly fill: residual r is "fillable" if r >= 1).
    if post > 0 && post < 10 {
        score -= 8.0; // tiny leftover, nearly full bin -> great
    } else if post >= 10 && post < 30 {
        score += residue_class * 0.3; // medium leftover: prefer small residue within class
    } else if post >= 30 && post < 60 {
        score += 5.0 + quotient_class * 0.8; // large leftover: wasteful
    } else {
        score += 12.0; // post >= 60: item barely dented the bin
    }

    // Lookahead coupling: if the next item fits the post residual exactly,
    // strongly reward; if it clearly cannot use the leftover, penalize.
    if next_item_size > 0 {
        let n = next_item_size as f64;
        if (next_item_size as u32) == post {
            score -= 25.0;
        } else if next_item_size <= post {
            score -= 10.0 * (1.0 - ((post - next_item_size) as f64) / cap);
        } else {
            score += 4.0 * (n / cap);
        }
    }

    // Last-chance bin: if this is the only open bin that fits, avoid opening
    // a new bin unless the fit is terrible.
    if fitting_bins_count == 1 && post < 70 {
        score -= 15.0;
    }

    // New-bin candidate (empty bin): only attractive when open bins are crowded
    // or the fit into existing bins is poor. Give it a moderate default score.
    if bin_residual == bin_capacity {
        score = cap * 0.45 + (open_bins_count as f64) * 2.0 - mean_residual * 0.4;
        if next_item_size > 0 && next_item_size >= 50 {
            score -= 6.0; // big upcoming item: a fresh bin is valuable
        }
        if post >= 60 {
            score += 10.0; // don't open new bins for tiny items
        }
    }

    // Late-stream consolidation: as the stream progresses, prefer filling
    // existing bins tighter rather than spreading.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += progress * (post as f64) * 0.15;

    // Mild preference for bins below mean residual (balance avoidance of
    // fragmentation across many half-empty bins).
    score += 0.05 * ((bin_residual as f64) - mean_residual);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let score = post_residual as f64 / bin_capacity.max(1) as f64;
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals that are too small for the
    // smallest conceivable item (<= 10) are pure waste; penalize hard.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    }
    // Semi-dead zone: residual that only fits a narrow band of items is risky.
    if post_residual >= 10 && post_residual < 25 {
        score += 15.0;
    }

    // Reward tight fits (small post_residual relative to item size).
    let tightness = item_size as f64 / bin_residual.max(1) as f64;
    score -= 25.0 * tightness;

    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 40.0;
    }

    // Lookahead coupling: if the next item fits exactly into the post
    // residual, this placement is a chain win.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 35.0;
        } else if next_item_size <= post_residual {
            score -= 10.0;
        } else {
            // Next item cannot use this bin's leftover; dead space likely.
            score += 8.0;
        }
    }

    // Open-bin pressure: with many open bins, prefer consolidating into
    // existing bins rather than spreading out.
    score += 2.0 * open_bins_count as f64 * (post_residual as f64 / bin_capacity as f64);

    // Mean-residual deviation: prefer bins whose residual is below average
    // (they are the "full" ones; keep emptier bins flexible).
    if (bin_residual as f64) < mean_residual {
        score -= 5.0;
    } else {
        score += 3.0;
    }

    // Last-chance bonus: if this is the only bin that can fit the item,
    // strongly favor using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 50.0;
    }

    // New-bin candidate handling: an empty bin should only win when no
    // existing bin offers a decent fit. Make the empty bin moderately
    // unattractive by default so consolidation wins, but not impossible
    // when all open bins would leave heavy dead space.
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin grows with open bin count.
        score += 30.0 + 3.0 * open_bins_count as f64;
        // But if existing fits are terrible (item barely fits anywhere),
        // the empty bin's clean 0 residual is attractive: soften penalty
        // when the item is large relative to capacity.
        if item_size as f64 > 0.7 * bin_capacity as f64 {
            score -= 20.0;
        }
    }

    // Mild stream-progression annealing: later in the stream, be more
    // aggressive about filling bins tightly.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= 10.0 * progress * tightness;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong reward for perfect fit
    if post_residual == 0 {
        score -= 1000.0;
    }

    // 2-step lookahead: exact match of post_residual with next item is ideal
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 500.0;
        } else if post_residual >= next_item_size {
            // next item fits: reward proportionally, but keep some residual value
            let lookahead_waste = (post_residual - next_item_size) as f64;
            score -= 100.0 - lookahead_waste.min(100.0);
        } else {
            // next item won't fit here: penalize small dead space strongly
            let dead = (next_item_size - post_residual) as f64;
            score += dead * (1.0 + 50.0 / post_residual.max(1) as f64);
        }
    }

    // Relative-to-mean coupling: bins with residual far below mean are precious
    let dev = post_residual as f64 - mean_residual;
    score += 0.5 * dev;

    // Last-chance bin: strongly prefer using it over opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 300.0;
    }

    // New-bin candidate: penalize unless current bin would leave tiny unusable space
    if bin_residual == bin_capacity {
        score += 250.0;
        if next_item_size > 0 && next_item_size <= bin_capacity {
            // a fresh bin perfectly fits next item if item is large
            if next_item_size >= 50 {
                score -= 60.0;
            }
        }
    }

    // Reward tight fills relative to capacity
    let fill = item_size as f64 / bin_capacity as f64;
    score -= 40.0 * fill;

    // Late in stream: consolidate more aggressively
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= 50.0 * progress * (post_residual as f64 / bin_capacity as f64);

    // Many open bins: favor compacting existing bins
    if open_bins_count > 3 {
        score -= 5.0 * (open_bins_count.min(20) as f64) * (post_residual as f64 / bin_capacity as f64);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: squared waste penalty.
    let tight = post_residual as f64 / bin_capacity as f64;
    score += tight * tight * 60.0;

    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 100.0;
    } else if post_residual < 10 {
        score -= 30.0;
    }

    // Last-chance bin: strongly favor using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 40.0;
    }

    // Penalize opening a new bin when existing bins fit decently.
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        // New bin acceptable only if item is large relative to capacity
        // and no bin would leave a small dead space.
        let fill_ratio = item_size as f64 / bin_capacity as f64;
        let best_possible_waste = if fitting_bins_count > 0 {
            // approximate: residual of best fit unknown; use mean residual
            (mean_residual - item_size as f64).abs()
        } else {
            0.0
        };
        score -= fill_ratio * 25.0;
        score += 15.0; // base cost of opening a new bin
        if fitting_bins_count > 0 && best_possible_waste < 12.0 {
            score += 50.0; // an open bin fits nearly perfectly; don't open new
        }
        // Late in stream, prefer consolidating into open bins.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += progress * 20.0;
    }

    // Lookahead coupling: if next item fits the post-residual, reward this placement.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 20.0;
        } else {
            // Dead space that next item can't use: penalize proportionally.
            let unusable = (next_item_size - post_residual) as f64;
            score += (unusable / 100.0) * 15.0;
        }
    }

    // Many open bins with high mean residual: encourage using laggard bins.
    if !is_new_bin {
        let residual_gap = mean_residual - bin_residual as f64;
        if residual_gap > 0.0 {
            score += residual_gap * 0.3; // prefer bins with below-average residual? no:
        }
        // Actually favor bins with residual close to mean to balance depletion.
        score -= 10.0 - (residual_gap.abs() * 0.4).min(10.0);
    }

    // Mild bonus for filling large items early (large items are hardest to place).
    let size_frac = item_size as f64 / bin_capacity as f64;
    score -= size_frac * 8.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    // Base: quadratic waste penalty on post-residual (smooth non-linear)
    let mut score = pr * (1.0 + pr / cap);

    // Reward tight fits: smooth coupling of fill ratio with post-residual
    let fill = 1.0 - pr / cap;
    score -= 30.0 * fill * fill;

    // Stream progress coupling: penalize waste more as stream progresses
    score += pr * progress * 1.5;

    // Last-chance bonus: strongly favor this bin if it's the only fitting one
    if fitting_bins_count == 1 {
        score -= 25.0;
    }

    // Lookahead coupling: reward if next item fits the post-residual exactly-ish
    if next_item_size > 0 && (next_item_size as f64) <= pr {
        let slack = pr - next_item_size as f64;
        score -= 12.0 * (1.0 - slack / cap);
    } else if next_item_size > 0 {
        score += 8.0;
    }

    // Mean residual alignment: prefer bins near the mean (smooth deviation term)
    let dev = (pr - mean_residual) / cap;
    score += 6.0 * dev * dev;

    // Mild penalty when many bins are open (encourage consolidation)
    score += open_bins_count as f64 * 0.05;

    // New-bin candidate: penalize opening a new bin smoothly, unless residual is large
    if bin_residual == bin_capacity {
        score += 20.0 - 15.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap_f = bin_capacity as f64;
    let progress = step_index as f64 / total_items.max(1) as f64;
    let mut score = post_residual as f64;

    // Tiered dead-space avoidance (strengthened perfect/near fits)
    if post_residual == 0 {
        score -= 1180.0;
    } else if post_residual <= 3 {
        score -= 500.0;
    } else if post_residual <= 12 {
        score -= 98.0;
    } else if post_residual < 20 {
        score += 18.0;
    } else if post_residual < 30 {
        score += 18.0 + (30 - post_residual) as f64 * 0.6;
    }

    // Lookahead for the next item
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 900.0;
        } else if next_item_size <= post_residual {
            let post2 = post_residual - next_item_size;
            score -= 135.0 - (post2 as f64) * 2.0;
            if post2 == 0 { score -= 110.0; }
            if post2 > 0 && post2 < 5 { score -= 28.0; }
            if post2 > 0 && post2 <= 2 { score -= 14.0; }
            if post2 % 10 == 0 && post2 > 0 { score -= 28.0; }
            if post2 >= 20 && post2 % 5 == 0 { score -= 12.0; }
            if post2 > 0 && post2 <= next_item_size / 4 { score -= 10.0; }
            if post_residual >= next_item_size * 2 && post_residual - next_item_size * 2 <= 4 {
                score -= 20.0;
            }
            if post_residual % next_item_size == 0 { score -= 18.0; }
            let chain = post_residual / next_item_size;
            if chain >= 2 { score -= (chain.min(4)) as f64 * 6.0; }
        } else {
            let gap = next_item_size - post_residual;
            if post_residual > 0 {
                score += 20.0;
                if gap <= 3 { score += 35.0; }
                if gap <= 8 { score += 12.0; }
                if gap <= 5 { score += (6 - gap) as f64 * 4.0; }
                if post_residual < 15 { score += 45.0; }
                if (gap as f64) > mean_residual * 0.5 { score += 14.0; }
                // unusable dead gap ahead of next item
                let dead_frac = post_residual as f64 / cap_f;
                if gap > 12 { score += dead_frac * 90.0; }
            }
        }
    }

    // Compaction pressure
    score += open_bins_count as f64 * 0.8;

    // Last-chance bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 45.0;
    }

    // Tightness via relative fill
    score -= (item_size as f64 / bin_residual.max(1) as f64) * 30.0;

    // NEW-BIN CANDIDATE
    if bin_residual == bin_capacity {
        let avg_fill = 1.0 - (mean_residual / cap_f);
        let newbin_waste = (bin_capacity - item_size) as f64;
        score += 250.0 - avg_fill * 330.0 - progress * 65.0;
        if item_size as f64 / cap_f > 0.75 { score -= 55.0; }
        if item_size >= bin_capacity * 3 / 4 { score -= 55.0; }
        if bin_capacity - item_size <= 4 { score -= 70.0; }
        if item_size as f64 > mean_residual { score -= 45.0; }
        if newbin_waste < mean_residual * 0.5 { score -= 30.0; }
        if next_item_size > 0 {
            let leftover = bin_capacity - item_size;
            if leftover >= next_item_size {
                let tail = leftover % next_item_size;
                if tail == 0 { score -= 20.0; }
                else if tail <= 4 { score -= 16.0; }
                if leftover - next_item_size <= 6 { score -= 38.0; }
                if leftover >= next_item_size * 2 { score -= 14.0; }
            } else if leftover < 10 {
                score += 18.0;
            }
            if (newbin_waste as u32) < next_item_size && newbin_waste < cap_f * 0.12 { score += 26.0; }
        }
        if fitting_bins_count > 0 {
            score += (fitting_bins_count.min(5) as f64) * 9.0 + 20.0;
            let snug = item_size as f64 / bin_residual.max(1) as f64;
            if snug > 0.9 { score += 40.0; }
            if snug > 0.95 { score += 28.0; }
            if snug > 0.98 { score += 18.0; }
        }
        if fitting_bins_count > 3 && item_size as f64 / cap_f < 0.5 { score += 30.0; }
        if progress > 0.6 {
            let waste_tol = (1.0 - progress) * cap_f * 0.35;
            if newbin_waste > waste_tol && fitting_bins_count > 0 {
                score += 10.0 + progress * 22.0;
            }
        }
        if progress < 0.1 { score -= 5.0; }
    } else {
        // Consolidation: prefer below-average residuals
        score += (mean_residual - bin_residual as f64) * 1.2;

        let dead_ratio = post_residual as f64 / cap_f;
        if dead_ratio < 0.03 { score -= 38.0; }
        else if dead_ratio < 0.08 { score -= 14.0; }
        else if dead_ratio > 0.35 { score += 24.0; }
        else if dead_ratio > 0.25 { score += 10.0; }
        score += dead_ratio * 30.0;

        if post_residual > 0 && post_residual < 6 { score -= 22.0; }
        if item_size == bin_residual { score -= 45.0; }
        if post_residual > 0 && (post_residual as f64) < mean_residual * 0.25 { score -= 15.0; }
        if bin_residual as f64 > cap_f * 0.6 { score -= 12.0; }
        if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
            let gap = next_item_size as f64 - post_residual as f64;
            if gap > mean_residual * 0.6 && fitting_bins_count > 2 { score += gap * 0.8; }
        }
        if next_item_size > 0 && post_residual >= next_item_size && (post_residual as f64) < mean_residual * 0.7 {
            score -= 6.0;
        }
        if post_residual > 0 && next_item_size > 0 && post_residual < next_item_size && (next_item_size - post_residual) <= 2 {
            score += 10.0 * (1.0 - progress);
        }
    }

    // Early stream diversity nudge
    if progress < 0.1 && bin_residual != bin_capacity { score += 3.0; }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Base: prefer tight fits (small post_residual), scaled by capacity fraction.
    score = post_residual as f64 * 1.0;

    // Harmonic class of post_residual: bins whose leftover falls into a
    // "usable" class (multiples of common item sizes) are rewarded.
    let pr = post_residual;
    if pr == 0 {
        score -= 50.0; // perfect fit is ideal
    } else {
        // Dead-space penalty grows when post_residual is too small to ever
        // hold a plausible future item (items >= 1, but typical >= 10).
        if pr < 10 {
            score += 60.0; // unusable sliver
        } else {
            // Reward post_residuals divisible by common size classes
            if pr % 10 == 0 { score -= 12.0; }
            if pr % 20 == 0 { score -= 8.0; }
            if pr % 25 == 0 { score -= 6.0; }
            if pr % 5 == 0 { score -= 3.0; }
        }
    }

    // Lookahead coupling: if next item fits exactly in the post_residual,
    // strongly reward; if it can't fit anywhere else, reward too.
    if next_item_size > 0 {
        if next_item_size == pr {
            score -= 40.0;
        } else if next_item_size <= pr {
            score -= (pr - next_item_size) as f64 * 0.3;
        } else {
            score += (next_item_size - pr) as f64 * 0.1;
        }
    }

    // Last-chance bin: if this is the only fitting bin, penalize opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate: penalize opening a new bin unless current fit is bad
    // or many bins are already open with slack.
    if bin_residual == bin_capacity {
        score += 15.0;
        if fitting_bins_count == 0 { score -= 100.0; }
        if post_residual >= 0 && item_size as f64 / cap < 0.5 && fitting_bins_count > 0 {
            score += 20.0; // small item into a fresh bin is wasteful
        }
    }

    // Stream progression: early on, allow more bins; later, consolidate.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score -= progress * 5.0;

    // Mean residual context: if this bin's residual is far below mean, it's
    // already "used up" — good to fill; bins above mean are slack targets.
    let bin_res_f = bin_residual as f64;
    if mean_residual > 0.0 {
        let rel = (bin_res_f - mean_residual) / mean_residual;
        score += rel * 4.0;
    }

    // Harmonic threshold on item size classes (integer division).
    let item_class = item_size / 20; // 0..4 coarse classes
    score -= item_class as f64 * 2.0; // big items deserve priority placement

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let score = 0.0;
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps (< 10) are heavily penalized
    // since typical small items (1..10) are rare; mid gaps (10..=20) mildly penalized.
    if post_residual < 10 {
        score += 25.0;
    } else if post_residual <= 20 {
        score += 6.0;
    } else if post_residual <= 35 {
        score -= 2.0;
    }

    // Reward tight fits: fraction of bin used by this placement.
    let tightness = item_size as f64 / bin_capacity as f64;
    score -= 8.0 * tightness;

    // Perfect fit is extremely desirable.
    if post_residual == 0 {
        score -= 20.0;
    }

    // Last-chance bin: strongly favor using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 12.0;
    }

    // Open-bin pressure: discourage spreading across many bins; favor filling
    // existing bins when many are open, and favor new bin when few are open.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score += (open_bins_count as f64).powf(0.7) * 0.8 * (0.5 + progress);

    // Compare against a fresh empty bin: penalize placements that leave a gap
    // smaller than the next item when a new bin could host both items.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            // this bin can still host the next item: reward chaining
            score -= 3.0;
        } else if bin_residual == bin_capacity {
            // new-bin candidate: score as post_residual of fresh bin,
            // slightly favored when item is large (better to give big items fresh space)
            score -= 2.0 + 6.0 * tightness;
        } else {
            // dead space relative to lookahead item
            score += 4.0;
        }
    }

    // Mean-residual coupling: prefer bins whose residual is below mean
    // (fill the emptier-trending bins, keep high-residual bins flexible).
    score -= 0.5 * (mean_residual - bin_residual as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer tight fits (small post_residual)
    let tightness = post_residual as f64 / bin_capacity as f64;
    score += 40.0 * tightness * tightness;

    // Perfect fit bonus
    if post_residual == 0 {
        score -= 100.0;
    }

    // Aggressive 2-step lookahead: reward bins whose post_residual matches next item
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if post_residual == next_item_size {
            score -= 120.0; // exact 2-step chain
        } else if post_residual >= next_item_size {
            let gap = (post_residual - next_item_size) as f64;
            // reward small gaps: next item can chain into this bin
            score -= 60.0 * (1.0 - gap / bin_capacity as f64);
        } else {
            // next item cannot fit in leftover; penalize proportionally to waste
            let waste = nxt - post_residual as f64;
            score += 25.0 * (waste / nxt).min(1.0);
        }
        // look two steps ahead: leftover after hypothetically placing next item
        if post_residual >= next_item_size {
            let r2 = post_residual - next_item_size;
            if r2 == 0 {
                score -= 60.0;
            } else {
                score -= 20.0 * (1.0 - r2 as f64 / bin_capacity as f64);
            }
        }
    } else {
        // last item: strongly prefer filling a bin completely
        score -= 150.0 * (1.0 - tightness);
    }

    // Relative to mean residual: prefer bins already below-average residual (consolidate)
    let dev = post_residual as f64 - mean_residual;
    score += 0.15 * dev;

    // Last-chance bin: if this is the only bin that fits, avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 80.0;
    }

    // New-bin candidate: only attractive when no open bin fits well
    if bin_residual == bin_capacity {
        let pressure = if next_item_size > 0 && next_item_size <= item_size { 1.0 } else { 0.0 };
        score += 30.0 - 25.0 * pressure;
        score += 5.0 * (open_bins_count as f64).ln().max(0.0);
    }

    // Mild stream-phase adjustment: early on, be slightly more willing to open bins
    let phase = step_index as f64 / total_items.max(1) as f64;
    score -= 10.0 * (1.0 - phase) * (post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap_f = bin_capacity as f64;
    let progress = step_index as f64 / total_items.max(1) as f64;
    let mut score = post_residual as f64;

    // Perfect / near-perfect fit rewards
    if post_residual == 0 {
        score -= 900.0;
    } else if post_residual <= 3 {
        score -= 400.0;
    } else if post_residual <= 12 {
        score -= 70.0;
    } else if post_residual < 20 {
        score += 14.0;
    } else if post_residual < 30 {
        score += 12.0 + (30 - post_residual) as f64 * 0.5;
    }

    // Lookahead: chain fitting of next item
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 700.0;
        } else if next_item_size <= post_residual {
            let post2 = post_residual - next_item_size;
            score -= 100.0 - post2 as f64 * 1.5;
            if post2 == 0 { score -= 90.0; }
            if post2 > 0 && post2 < 5 { score -= 24.0; }
            if post2 % 10 == 0 && post2 > 0 { score -= 20.0; }
            if post_residual % next_item_size == 0 { score -= 15.0; }
            if post_residual >= next_item_size * 2 && post_residual - next_item_size * 2 <= 4 { score -= 18.0; }
        } else {
            score += 18.0;
            if post_residual > 0 && post_residual < 15 { score += 40.0; }
            let gap = next_item_size as f64 - post_residual as f64;
            if post_residual > 0 && gap <= 5.0 { score += 28.0; }
            if post_residual > 0 && gap <= 8.0 { score += 10.0; }
            if post_residual as f64 > mean_residual * 1.4 { score -= 10.0; }
        }
        if post_residual >= next_item_size * 2 && next_item_size > 0 {
            let chain = post_residual / next_item_size;
            if chain >= 2 { score -= (chain.min(4)) as f64 * 6.0; }
        }
    }

    // NEW-BIN CANDIDATE evaluation
    if bin_residual == bin_capacity {
        let avg_fill = 1.0 - (mean_residual / cap_f);
        score += 220.0 - avg_fill * 300.0 - progress * 55.0;
        if fitting_bins_count > 0 {
            score += (fitting_bins_count as f64).min(5.0) * 8.0;
            let snug = item_size as f64 / bin_residual.max(1) as f64;
            if snug > 0.9 { score += 35.0; }
            if snug > 0.95 { score += 25.0; }
            if snug > 0.98 { score += 15.0; }
        }
        if item_size >= bin_capacity * 3 / 4 { score -= 50.0; }
        if next_item_size > 0 && next_item_size <= bin_capacity - item_size { score -= 22.0; }
        let leftover = bin_capacity - item_size;
        if next_item_size > 0 && leftover >= next_item_size {
            let tail = leftover % next_item_size;
            if tail == 0 { score -= 12.0; } else if tail <= 4 { score -= 14.0; }
        }
        let newbin_waste = leftover as f64;
        if newbin_waste > 0.0 && newbin_waste < mean_residual * 0.6 { score -= 28.0; }
        if progress > 0.6 {
            let waste_tol = (1.0 - progress) * cap_f * 0.35;
            if newbin_waste > waste_tol && fitting_bins_count > 0 { score += 10.0 + progress * 20.0; }
        }
        if newbin_waste > 0.0 && (newbin_waste as u32) < next_item_size && newbin_waste < cap_f * 0.12 { score += 22.0; }
    } else {
        // Existing bin: tightness and dead-space logic
        let tightness = 1.0 - (item_size as f64 / bin_residual.max(1) as f64);
        score += tightness * 70.0;
        score += (mean_residual - bin_residual as f64) * 1.2;
        let dead_ratio = post_residual as f64 / cap_f;
        if dead_ratio < 0.03 { score -= 32.0; }
        else if dead_ratio < 0.08 { score -= 12.0; }
        else if dead_ratio > 0.35 { score += 22.0; }
        else if dead_ratio > 0.25 { score += 8.0; }
        if post_residual > 0 && next_item_size > 0 && post_residual < next_item_size {
            let unusable = (next_item_size - post_residual) > 12;
            if unusable { score += dead_ratio * 80.0; }
            else { score += (next_item_size - post_residual) as f64 * 0.5; }
        }
        if item_size == bin_residual { score -= 40.0; }
        if post_residual > 0 && post_residual < 6 { score -= 20.0; }
        if post_residual > 0 && (post_residual as f64) < mean_residual * 0.25 { score -= 12.0; }
        if post_residual > 0 && (post_residual as f64) < cap_f * 0.015 { score -= 16.0; }
        if fitting_bins_count == 1 { score -= 20.0; }
        if fitting_bins_count <= 2 && post_residual > 0 { score -= 6.0; }
        if post_residual > 0 && (post_residual as f64) > mean_residual * 1.6 && fitting_bins_count > 2 { score += 8.0; }
        if next_item_size > 0 && post_residual > 0 && post_residual >= next_item_size && (post_residual % next_item_size) <= 2 { score -= 8.0; }
    }

    // Compaction pressure
    score += open_bins_count as f64 * 0.7;
    score -= (item_size as f64 / cap_f) * 10.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let item = item_size as f64;
    let post = post_residual as f64;
    let res = bin_residual as f64;
    let t = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let mut score = post;

    // Prefer tight fits: reward low post residual nonlinearly.
    let tightness = 1.0 - (post / cap);
    score -= 40.0 * tightness * tightness * tightness;

    // Penalize post residual that is too small to be useful (dead space).
    let next = next_item_size as f64;
    if next > 0.0 {
        if post < next {
            score += 25.0 * (1.0 - post / next.max(1.0));
        } else {
            // Reward bins whose leftover accommodates the lookahead item.
            score -= 15.0 * (1.0 - (post - next) / cap);
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 60.0;
    }

    // Many fitting bins: mild penalty to keep diversity, prefer best fit among them.
    if fitting_bins_count > 1 {
        score += 3.0 * (fitting_bins_count as f64 - 1.0).ln();
    }

    // Global state: penalize placing into bins with residual far from mean (imbalance).
    let dev = (res - mean_residual).abs();
    score += 0.15 * dev;

    // Early in stream: slightly encourage opening new bins to build a portfolio.
    let new_bin = bin_residual == bin_capacity;
    if new_bin {
        let horizon = 0.5 - 0.5 * t;
        score += 30.0 * horizon - 10.0 * (open_bins_count as f64).ln().max(0.0);
        // Never open a new bin if a near-perfect fit exists elsewhere.
        if post < 5.0 && !new_bin { score -= 100.0; }
        if fitting_bins_count > 0 && post > cap * 0.5 {
            score += 20.0 * t;
        }
    }

    // Late in stream: consolidate aggressively, avoid new bins.
    if t > 0.8 && new_bin {
        score += 50.0;
    }

    // Mild preference for fuller bins overall.
    score -= 0.05 * (cap - res);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let it = item_size as f64;

    // Base: prefer minimal leftover space after placement.
    let mut score = pr;

    // Smooth polynomial coupling: reward tight fits more strongly as the stream progresses.
    let tightness = 1.0 - (pr / cap); // 1.0 = perfect fit
    score -= tightness * tightness * it * (0.5 + 1.5 * progress);

    // Penalize dead space (nonlinearly): residuals too small for the smallest plausible item are waste.
    let dead = (pr / cap).powi(3);
    score += 40.0 * dead * (0.5 + progress);

    // Last-chance bonus: if this is the only fitting bin, strongly prefer using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0 + 20.0 * progress;
    }

    // New-bin candidate: make the empty bin less attractive unless the item is large
    // or the stream is early and future items may need fresh space.
    if bin_residual == bin_capacity {
        score += 8.0 + 30.0 * (1.0 - it / cap);
        // Early stream: fresh bins are cheaper to open (long horizon to amortize).
        score -= 15.0 * (1.0 - progress) * (1.0 - progress);
    }

    // Lookahead: if the next item could still fit in the post-residual, reward preserving this bin.
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        if nx <= pr {
            score -= 6.0 * (1.0 - (pr - nx) / cap);
        } else {
            // Next item won't fit here anyway; slight penalty for leaving awkward residue.
            score += 3.0 * (nx - pr) / cap;
        }
    }

    // Global context: when mean residual across bins is high, discourage spreading into low-residual bins.
    score += 0.05 * (mean_residual - pr).abs();

    // Many open bins: mild pressure to consolidate into existing bins rather than open new ones.
    score += 0.3 * open_bins_count as f64 * (pr / cap);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap_f = bin_capacity as f64;
    let mut score = post_residual as f64;
    let post = post_residual;

    // Perfect fit: heavily reward (dominant signal).
    if post == 0 {
        score -= 900.0;
    } else if post <= 3 {
        score -= 350.0;
    } else if post <= 12 {
        score -= 60.0;
    } else if post < 20 {
        score += 14.0;
    } else if post < 30 {
        score += 14.0 + (30 - post) as f64 * 0.6;
    }

    // Harmonic class of the resulting residual.
    let quarter = bin_capacity / 4;
    let half = bin_capacity / 2;
    if post >= 30 {
        if post < quarter {
            score += 20.0;
            if next_item_size > post {
                score += 15.0;
            }
        } else if post < half {
            score += 5.0;
        } else {
            score -= 10.0;
        }
    }

    // Divisible residuals are more reusable.
    if post % 10 == 0 && post > 0 {
        score -= 8.0;
    }
    if post % 20 == 0 && post > 0 {
        score -= 4.0;
    }

    // Lookahead coupling: snug chains.
    if next_item_size > 0 && post > 0 {
        if next_item_size == post {
            score -= 600.0;
        } else if next_item_size <= post {
            let slack = post - next_item_size;
            if slack < quarter {
                score -= 15.0;
            } else {
                score -= 3.0;
            }
            if slack > 0 && slack <= 4 {
                score -= 20.0;
            }
            if post % next_item_size == 0 {
                score -= 12.0;
            }
        } else {
            score += 10.0;
            let gap = (next_item_size - post) as f64;
            if gap <= 5.0 {
                score += (6.0 - gap) * 4.0;
            }
            if post < 15 {
                score += 35.0;
            }
        }
    }

    // Last-chance bonus: only fitting bin.
    if fitting_bins_count == 1 {
        score -= 25.0;
    }

    // New-bin candidate logic.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let avg_fill = 1.0 - (mean_residual / cap_f);
        score += 220.0 - avg_fill * 300.0 - progress * 60.0;

        if fitting_bins_count > 0 {
            // Snugness of item in an empty bin vs alternatives.
            let snug = item_size as f64 / cap_f;
            if snug > 0.9 {
                score -= 40.0;
            }
            if snug > 0.95 {
                score -= 25.0;
            }
            if bin_capacity - item_size <= 4 {
                score -= 60.0;
            }
            if item_size >= bin_capacity * 3 / 4 {
                score -= 45.0;
            }
            // Waste comparison against mean residual of open bins.
            let newbin_waste = (bin_capacity - item_size) as f64;
            let best_alt = if item_size as f64 <= mean_residual {
                mean_residual - item_size as f64
            } else {
                mean_residual
            };
            if newbin_waste > best_alt + cap_f * 0.08 {
                score += 20.0;
            }
            if newbin_waste > 0.0 && (newbin_waste as u32) < next_item_size && newbin_waste < cap_f * 0.12 {
                score += 24.0;
            }
            if progress > 0.6 && newbin_waste > (1.0 - progress) * cap_f * 0.35 {
                score += 10.0 + progress * 20.0;
            }
        } else {
            // No open bin fits: opening a new bin is mandatory-ish.
            score -= 120.0;
        }
        if next_item_size > 0 {
            let leftover = bin_capacity - item_size;
            if leftover >= next_item_size {
                let tail = leftover % next_item_size;
                if tail == 0 {
                    score -= 14.0;
                } else if tail <= 4 {
                    score -= 10.0;
                }
            }
            if next_item_size >= bin_capacity / 2 {
                score -= 25.0;
            }
        }
    } else {
        // Open bin: penalize poor tightness.
        let tightness = 1.0 - (item_size as f64 / bin_residual.max(1) as f64);
        score += tightness * 60.0;
        score += (mean_residual - bin_residual as f64) * 1.2;
        let dead_ratio = post as f64 / cap_f;
        if dead_ratio < 0.03 {
            score -= 30.0;
        } else if dead_ratio > 0.35 {
            score += 20.0;
        } else if dead_ratio > 0.25 {
            score += 8.0;
        }
        if post > 0 && next_item_size > 0 && post < next_item_size {
            let wasted = (next_item_size - post) as f64;
            score += wasted * 0.5;
        }
        if item_size == bin_residual {
            score -= 40.0;
        }
        if fitting_bins_count <= 2 && post > 0 {
            score -= 8.0;
        }
    }

    // Mild penalty for many open bins with poor mean residual.
    if mean_residual > cap_f * 0.6 && open_bins_count > 3 {
        score += 3.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let cap = bin_capacity as f64;

    // Harmonic class of the post residual: residues divisible by common item
    // granularity (10) are "usable" classes; odd residues are dead-space prone.
    let res = post_residual;
    if res == 0 {
        score -= 40.0; // perfect fit is king
    } else if res % 10 == 0 {
        score -= 12.0; // cleanly reusable residual
        if res >= 40 { score -= 6.0; } // fits mid-size future items
    } else if res % 5 == 0 {
        score -= 4.0;
    } else {
        score += 6.0 + (res % 5) as f64; // penalize ragged residues
    }

    // Integer-division thresholds: how many "typical" items still fit.
    let slots = res / 10;
    score -= slots as f64 * 3.0;

    // Lookahead coupling: if the next item fits exactly in post residual,
    // strongly reward; if it cannot fit, mildly penalize.
    if next_item_size > 0 {
        if next_item_size == res {
            score -= 25.0;
        } else if next_item_size < res {
            score -= (res - next_item_size) as f64 * 0.2;
        } else {
            score += 4.0;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate handling: only attractive when existing bins fit badly.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let tight = (item_size as f64) / cap;
        // Opening new bin is fine early or for large items; penalize otherwise.
        score += 8.0 + progress * 10.0 - tight * 10.0;
        if mean_residual > (item_size as f64 + 5.0) {
            score += 12.0; // existing bins actually have room; discourage new bin
        }
    }

    // Mild pressure to consolidate when many bins are open.
    if open_bins_count > 4 && bin_residual < bin_capacity {
        score -= 2.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: gaps too small for the minimum item are worthless.
    if post_residual < 10 {
        score += 60.0; // unusable sliver -> heavy penalty
    } else if post_residual < next_item_size && next_item_size > 0 {
        score += 25.0; // gap cannot host the upcoming item
    }

    // Reward near-perfect fills (post_residual close to 0 but not dead).
    if post_residual == 0 {
        score -= 80.0;
    } else if post_residual <= 15 {
        score -= 20.0;
    }

    // Reward gaps that exactly accommodate the lookahead item.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 30.0;
    }

    // Last-chance bin: strongly prefer using it before opening a new one.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 45.0;
    }

    // Open-bin pressure: discourage scattering across many bins,
    // but allow new bins when residuals are already fragmented.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    if bin_residual == bin_capacity {
        // New-bin candidate: acceptable early or when open bins are fragmented,
        // otherwise penalized so consolidation wins.
        score += 40.0 - 55.0 * progress + 2.0 * open_bins_count as f64;
    } else {
        score -= 3.0 * (bin_residual as f64 / bin_capacity as f64);
        score += 1.5 * open_bins_count as f64 * (1.0 - progress);
    }

    // Prefer bins tighter than the average residual (good packing density).
    score -= 0.3 * (mean_residual - bin_residual as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let score = post_residual as f64 / bin_capacity.max(1) as f64;
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong reward for perfect fit
    if post_residual == 0 {
        score -= 1000.0;
    }

    // 2-step lookahead: if next item fits exactly into post_residual, big reward
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 500.0;
        } else if post_residual >= next_item_size {
            // next item can also go here; penalize wasted slack relative to next item
            score -= 50.0 * (1.0 - (post_residual - next_item_size) as f64 / bin_capacity as f64);
        } else {
            // dead space for the next item: penalize proportionally to leftover gap
            score += 30.0 * (next_item_size - post_residual) as f64 / bin_capacity as f64;
        }
    }

    // Relative-to-mean coupling: prefer bins tighter than the mean residual
    score += 0.5 * (mean_residual - bin_residual as f64);

    // Last-chance bin bonus
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 200.0;
    }

    // Penalize opening a new bin unless it enables a good 2-step chain
    if bin_residual == bin_capacity {
        score += 80.0;
        if next_item_size > 0 && (bin_capacity - item_size) >= next_item_size {
            score -= 120.0;
        }
    }

    // Small late-stream conservatism: prefer filling existing bins as stream progresses
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += 20.0 * progress * (post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap_f = bin_capacity as f64;
