    if post_residual == 0 {
        score -= 900.0;
    } else if post_residual <= 3 {
        score -= 400.0;
    } else if post_residual <= 12 {
        score -= 80.0;
    } else if post_residual < 20 {
        score += 18.0;
    } else if post_residual < 30 {
        score += 18.0 + (30 - post_residual) as f64 * 0.6;
    }

    // Lookahead: chain packing against the next item
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 700.0;
        } else if next_item_size <= post_residual {
            let post2 = post_residual - next_item_size;
            score -= 110.0 - (post2 as f64) * 2.0;
            if post2 == 0 {
                score -= 90.0;
            } else if post2 < 5 {
                score -= 25.0;
            } else if post2 % 10 == 0 {
                score -= 20.0;
            }
            if post_residual % next_item_size == 0 {
                score -= 15.0;
            }
            let chain = post_residual / next_item_size;
            if chain >= 2 {
                score -= (chain.min(4)) as f64 * 6.0;
            }
        } else {
