            let gap = next_item_size as f64 - post_residual as f64;
            if post_residual > 0 && gap <= 8.0 {
                score += 12.0 + (8.0 - gap) * 3.0;
            }
            if post_residual > 0 && post_residual < 15 {
                score += 40.0;
            }
            if post_residual as f64 > mean_residual * 1.4 {
                score -= 10.0;
            }
        }
    }

    // NEW-BIN CANDIDATE logic
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let avg_fill = 1.0 - (mean_residual / cap_f);
        // Base high score; cheaper to open when average fill is already good or late in stream
        score += 230.0 - avg_fill * 300.0 - progress * 60.0;
        let newbin_waste = (bin_capacity - item_size) as f64;
        if item_size as f64 > mean_residual {
            score -= 40.0;
