        score += (mean_residual - bin_residual as f64) * 1.5;

        let dead_ratio = post_residual as f64 / cap_f;
        if dead_ratio < 0.03 {
            score -= 35.0;
        } else if dead_ratio < 0.08 {
            score -= 12.0;
        } else if dead_ratio > 0.35 {
            score += 22.0;
        } else if dead_ratio > 0.25 {
            score += 8.0;
        }

        if post_residual > 0 && post_residual < 6 {
            score -= 20.0;
        }
        if item_size == bin_residual {
            score -= 40.0;
        }
        if post_residual > 0 && post_residual % 10 == 0 {
            score -= 8.0;
        }

        // Unusable-dead-space lookahead penalty
        if next_item_size > 0 && post_residual > 0 {
            if post_residual < next_item_size && (next_item_size - post_residual) > 12 {
                score += dead_ratio * 80.0;
            } else {
