                score -= reuse * 20.0;
            }
            let gap = (next_item_size as f64 - post_residual as f64) / next_item_size.max(1) as f64;
            if gap > 0.0 && gap < 0.12 {
                score -= 9.0;
            }
        }

        // Last-chance bin: strong compaction pull
        if fitting_bins_count == 1 {
            score -= 22.0;
        } else if fitting_bins_count == 2 && post_residual > 0 {
            score -= 6.0;
        }
    }

    // Global compaction pressure
    score += open_bins_count as f64 * 0.6;

    // Mild relative fill reward
    score -= (item_size as f64 / cap_f) * 10.0;

    // Early stream: slight openness to diversity
    let progress = step_index as f64 / total_items.max(1) as f64;
    if progress < 0.1 {
        score += 3.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: small post-residual is good, but avoid useless slivers (< 10)
    if post_residual == 0 {
        score -= 60.0; // perfect fit
    } else if post_residual < 10 {
        score -= 35.0; // near-perfect fit, dead space is minimal anyway
    } else if post_residual > bin_capacity as f64 * 0.5 {
        score += 25.0; // wasteful placement into a large bin
    }

    // Lookahead: reward bins whose post-residual can host the next item (k=2 chaining)
    if next_item_size > 0 && (post_residual as u32) >= next_item_size {
        let slack = post_residual - next_item_size as f64;
        score -= 20.0 - slack * 0.15; // prefer chaining with tight leftover for next item
    } else if next_item_size > 0 && (bin_residual as u32) >= next_item_size {
        // next item fits this bin but only if we DON'T place current item here:
        // mild penalty for blocking a good future fit
        score += 6.0;
    }

    // Last-chance bonus: if this is the only fitting bin, strongly prefer using it
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate handling: opening a new bin is expensive; make it attractive
    // only when the item would leave large unusable space everywhere or fits badly.
    let is_new_bin = bin_residual == bin_capacity && bin_capacity > 0;
    if is_new_bin {
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        // early stream: prefer filling open bins; late stream: new bins less costly relatively
        score += 45.0 - 25.0 * progress;
        // if many bins already open, spreading is less harmful
        score -= (open_bins_count as f64).min(10.0) * 1.5;
        // large items leave little room anywhere; a fresh bin is fine
        if item_size >= 50 {
            score -= 15.0;
        }
        // if no open bin would leave a usable remainder, new bin is competitive
        if post_residual >= 10 && post_residual <= 20 {
            score -= 12.0;
        }
    }

    // Global fragmentation pressure: if mean residual across open bins is low,
    // bins are nearly full -> favor packing into them aggressively.
    score -= mean_residual * 0.10;

    // Slight preference for bins with less residual overall (fill fullest first)
    score += (bin_residual as f64 - mean_residual) * 0.05;

    // Late-stream tightening: as stream progresses, discourage leaving medium dead space
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    if post_residual > 0 && post_residual < 25 {
        score += (1.0 - progress) * 4.0; // early on, medium dead space may still be usable
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let prn = pr / cap;

    // Base: smooth non-linear penalty on post-residual, coupled with progress.
    let mut score = pr * (1.0 + 0.6 * progress) - 0.35 * (prn * prn * cap) * (0.5 + progress);

    // Reward tight fits more strongly as stream progresses.
    let tightness = (item_size as f64 / bin_residual.max(1) as f64).min(1.0);
    score -= 25.0 * tightness * tightness * (0.4 + 0.6 * progress);

    // Penalize dead space that cannot fit the next item (lookahead coupling).
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if pr < nxt {
            score += (nxt - pr) * (0.5 + 0.5 * progress);
        } else {
            score -= 3.0 * (1.0 - (pr - nxt) / cap);
        }
    }

    // Last-chance bonus: avoid opening a new bin when this is the only fitting bin.
    if fitting_bins_count == 1 {
        score -= 12.0 * (1.0 - progress * 0.5);
    }

    // Mild penalty when bin residual deviates from mean residual (encourage balanced bins).
    score += 0.05 * ((pr - mean_residual) / cap).abs() * cap * (0.3 + 0.7 * progress);

    // New-bin candidate: penalize moderately, scaled by how well open bins exist.
    if bin_residual == bin_capacity {
        score += 8.0 + 4.0 * (open_bins_count as f64).ln().max(0.0);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
