    let q = post_residual / (bin_capacity / 4);
    score += match q {
        0 => -30.0,          // post_residual < 25: small dead space, good
        1 => 10.0,           // 25..50: awkward zone
        2 => 25.0,           // 50..75: very awkward
        _ => 40.0,           // large residual left = wasteful placement
    };

    // Penalize post_residual in "dead zone" that few item sizes (1..100) can fill:
    // residual r is fillable if some future item size <= r; tiny r (<10) is nearly dead.
    if post_residual < 10 && post_residual > 0 {
        score += 60.0;
    }

    // Last-chance bin: reward strongly to avoid opening a new bin unnecessarily
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 80.0;
    }

    // New-bin candidate: penalize unless current bin fit is bad
    if bin_residual == bin_capacity {
        score += 120.0 + mean_residual * 0.3;
        // If this bin would leave a very awkward residual elsewhere, new bin is attractive
        if post_residual > 0 && post_residual < 15 {
            score -= 40.0;
        }
    }

    // Lookahead coupling: if next item fits exactly in post_residual, big reward
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 200.0;
        } else if next_item_size <= post_residual {
            score -= (post_residual - next_item_size) as f64 * 0.5;
        } else {
            // next item cannot use this residual: penalize proportional to wasted potential
            score += 0.2 * (next_item_size - post_residual).min(bin_capacity) as f64;
        }
    }

    // Prefer tightening well-packed bins as stream progresses
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= progress * 20.0 * (1.0 - (post_residual as f64 / bin_capacity as f64));

    // Mild preference for bins with residual close to item (snug fit)
    score += ((bin_residual as f64 - item_size as f64).abs()) * 0.1;

    // Tie-break by mean residual: favor bins deviating below mean (tighter bins)
    score += (mean_residual - bin_residual as f64).max(0.0) * 0.05;

    score
}

