        if post_residual > 0 && (post_residual as f64) < mean_residual * 0.25 {
            score -= 12.0;
        }
        if post_residual > 0 && post_residual % 5 == 0 && post_residual <= 30 {
            score -= 8.0;
        }
        if next_item_size > 0 && post_residual > 0 && post_residual >= next_item_size {
            let chain = post_residual / next_item_size;
            if chain >= 2 {
                score -= (chain.min(4)) as f64 * 6.0;
            }
        }
    }

    // Early stream: slight diversity preference
    let progress = step_index as f64 / total_items.max(1) as f64;
    if progress < 0.1 {
        score += 3.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Penalize small unusable gaps (dead space) more aggressively than large residuals.
    if post_residual > 0 && post_residual < 10 {
        score += 40.0;
    } else if post_residual < 20 {
        score += 15.0 * (20.0 - post_residual as f64) / 10.0;
    }

    // Perfect fit reward.
    if post_residual == 0 {
        score -= 25.0;
    }

    // Lookahead: reward if next item fits the post residual.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 12.0;
    } else if next_item_size > 0 && post_residual > 0 {
        score += 6.0;
    }

    // Last-chance bonus: only bin that fits the item.
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // Open-bins pressure: discourage spreading when many bins are open.
    score += (open_bins_count as f64) * 0.8;

    // Mean residual coupling: prefer bins whose residual is near the mean (balanced packing).
    score += ((bin_residual as f64 - mean_residual) / bin_capacity as f64).abs() * 10.0;

    // New-bin candidate: only attractive when no open bin is a good fit.
    if bin_residual == bin_capacity {
        let bad_open_fit = fitting_bins_count == 0
            || (post_residual < 10 && next_item_size > post_residual);
        if bad_open_fit {
            score -= 20.0;
        } else {
            // Strong penalty: prefer filling existing bins (best-fit archetype).
            score += 60.0 + (open_bins_count as f64).min(10.0);
        }
    }

    // Slight progression term: as stream advances, be more conservative with new bins.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += progress * 5.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Aggressive 2-step lookahead: reward exact/excellent fits for the NEXT item too.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 60.0; // perfect chain: next item exactly fills this bin
        } else if post_residual > next_item_size {
            // slack left after hypothetically placing next item — penalize large slack
            let slack = (post_residual - next_item_size) as f64;
            score += slack * 0.3;
            // reward if that slack is still usable (>= typical small item)
            if slack >= 10.0 {
                score -= 8.0;
            }
        } else {
            // next item won't fit here: penalize proportionally to dead space created
            let dead = (next_item_size - post_residual) as f64;
            score += dead * 0.5;
        }
    } else {
        // last item: just prefer tightest fit
        score += (post_residual as f64) * 0.1;
    }

    // Prefer bins already below mean residual (filling the emptier bins first
    // concentrates waste and keeps fatter bins flexible).
    if (bin_residual as f64) < mean_residual {
        score -= 4.0;
    } else {
        score += 3.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // Penalize opening a new bin when good existing options exist,
    // but allow it early in the stream or when residual would be tiny.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let new_bin_penalty = 20.0 + 30.0 * progress;
        score += new_bin_penalty;
        // a fresh bin is fine if the item is huge (little choice anyway)
        if item_size >= 70 {
            score -= 15.0;
        }
    }

    // Late in the stream, tighten packing harder (less future to amortize waste).
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= 10.0 * progress * (1.0 - post_residual as f64 / bin_capacity as f64);

    // Mild penalty on very small post-residuals that create unusable slivers
    // unless a next item can use them (handled above).
    if post_residual > 0 && post_residual < 10 && next_item_size != post_residual {
        score += 12.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tight fit reward: strongly favor bins where the item fills most of the residual.
    let fill_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 30.0 * fill_ratio * fill_ratio;

    // Penalize dead space that is too small to hold typical future items.
    if post_residual > 0 && post_residual < 10 {
        score += 15.0;
    }

    // Last-chance bonus: if this is the only bin that fits, strongly prefer it.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // Lookahead: if next item fits in the post residual, reward; otherwise penalize.
    if next_item_size > 0 {
        if (post_residual as u32) >= next_item_size {
            score -= 12.0;
        } else if post_residual > 0 && (post_residual as u32) < next_item_size {
            score += 6.0 * (1.0 - post_residual as f64 / next_item_size.max(1) as f64);
        }
    }

    // New-bin candidate handling: penalize opening a new bin, more so early in the
    // stream and when many bins are already open; relax when fit is terrible.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let mut new_bin_penalty = 20.0 + 10.0 * (open_bins_count as f64).ln().max(0.0) + 10.0 * progress;
        // If the item leaves a lot of dead space in any existing bin, opening fresh is fine.
        if post_residual > 0 && fill_ratio < 0.35 {
            new_bin_penalty *= 0.4;
        }
        score += new_bin_penalty;
    }

    // Mild global pressure: prefer bins below mean residual (spreading load evenly
    // keeps more mid-sized gaps available).
    score += 0.05 * (bin_residual as f64 - mean_residual);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap_f = bin_capacity as f64;
    let progress = step_index as f64 / total_items.max(1) as f64;
    let mut score = post_residual as f64;

    // Tiered dead-space avoidance (strengthened)
    if post_residual == 0 {
        score -= 1180.0;
    } else if post_residual <= 3 {
        score -= 500.0;
    } else if post_residual <= 12 {
        score -= 98.0;
    } else if post_residual < 20 {
        score += 18.0;
    } else if post_residual < 30 {
        score += 18.0 + (30 - post_residual) as f64 * 0.6;
    }

    // Lookahead: exact and near-exact fits for the next item
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 900.0;
        } else if next_item_size <= post_residual {
            let post2 = post_residual - next_item_size;
            score -= 135.0 - (post2 as f64) * 2.0;
            if post2 == 0 { score -= 110.0; }
            if post2 > 0 && post2 < 5 { score -= 28.0; }
            if post2 > 0 && post2 <= 2 { score -= 14.0; }
            if post2 % 10 == 0 && post2 > 0 { score -= 28.0; }
            if post2 >= 20 && post2 % 5 == 0 { score -= 12.0; }
            if post_residual % next_item_size == 0 { score -= 18.0; }
            if post_residual >= next_item_size * 2 && post_residual - next_item_size * 2 <= 4 {
                score -= 20.0;
            }
            let chain = post_residual / next_item_size;
            if chain >= 2 { score -= (chain.min(4)) as f64 * 6.0; }
            if post2 > 0 && post2 <= next_item_size / 4 { score -= 10.0; }
        } else {
            // next item won't fit here: penalize leaving a nearly-fitting gap
            let gap = next_item_size - post_residual;
            if post_residual > 0 {
                if gap <= 3 { score += 35.0; }
                else if gap <= 8 { score += 12.0; }
                if gap <= 5 { score += (6 - gap) as f64 * 4.0; }
                if (gap as f64) > mean_residual * 0.5 { score += 14.0; }
            }
            if post_residual % 10 == 0 { score -= 15.0; }
            if post_residual > 0 && post_residual < 15 { score += 45.0; }
            if post_residual as f64 > mean_residual * 1.4 { score -= 12.0; }
        }
        if post_residual > 0 && post_residual < next_item_size && post_residual >= item_size * 2 {
            score += 10.0;
        }
    }

    // Compaction pressure scaled by open bins
    score += open_bins_count as f64 * 0.8;

    // Last-chance bin: strongly favor using it
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 45.0;
    }

    // Tightness via relative fill
    score -= (item_size as f64 / bin_residual.max(1) as f64) * 30.0;

    // Dead-space ratio shaping
    if bin_residual < bin_capacity {
        let dead_ratio = post_residual as f64 / cap_f;
        if dead_ratio < 0.03 { score -= 38.0; }
        else if dead_ratio < 0.08 { score -= 14.0; }
        else if dead_ratio > 0.35 { score += 24.0; }
        else if dead_ratio > 0.25 { score += 10.0; }
        score += dead_ratio * 30.0;
        if post_residual > 0 && next_item_size > 0 && post_residual < next_item_size {
            let unusable = (next_item_size - post_residual) > 12;
            if unusable { score += dead_ratio * 90.0; }
        }
        // consolidate slack toward below-average residuals
        score += (mean_residual - bin_residual as f64) * 1.2;
        if post_residual > 0 && (post_residual as f64) < mean_residual * 0.25 { score -= 15.0; }
        if item_size == bin_residual { score -= 45.0; }
    }

    // NEW-BIN CANDIDATE handling
    if bin_residual == bin_capacity {
        let newbin_waste = (bin_capacity - item_size) as f64;
        let avg_fill = 1.0 - (mean_residual / cap_f);
