        if item_size as f64 / cap_f > 0.75 { score -= 55.0; }
        if item_size >= bin_capacity * 3 / 4 { score -= 55.0; }
        if bin_capacity - item_size <= 4 { score -= 70.0; }
        if item_size as f64 > mean_residual { score -= 45.0; }
        if newbin_waste < mean_residual * 0.6 { score -= 30.0; }
        if next_item_size > 0 {
            let leftover = bin_capacity - item_size;
            if leftover >= next_item_size {
                let tail = leftover % next_item_size;
                if tail == 0 { score -= 26.0; }
                else if tail <= 4 { score -= 16.0; }
                if leftover - next_item_size <= 6 { score -= 38.0; }
                if leftover >= next_item_size * 2 { score -= 14.0; }
            }
            if leftover < next_item_size && leftover < 10 { score += 18.0; }
            if (leftover as u32) < next_item_size && newbin_waste < cap_f * 0.12 { score += 26.0; }
            if next_item_size >= bin_capacity / 2 { score -= 32.0; }
        }
        if fitting_bins_count > 0 {
            score += (fitting_bins_count.min(5) as f64) * 9.0 + 20.0;
            let snug = item_size as f64 / cap_f;
            if snug > 0.9 { score += 40.0; }
            if snug > 0.95 { score += 28.0; }
            if snug > 0.98 { score += 18.0; }
        }
        if fitting_bins_count > 3 && item_size as f64 / cap_f < 0.5 { score += 30.0; }
        // late-stream waste tolerance tightens
        if progress > 0.6 {
            let waste_tol = (1.0 - progress) * cap_f * 0.35;
            if newbin_waste > waste_tol && fitting_bins_count > 0 {
                score += 10.0 + progress * 22.0;
            }
        }
        if progress > 0.85 && newbin_waste > cap_f * 0.3 { score += 8.0; }
        if progress < 0.1 { score -= 5.0; }
    }

    // Mild progress-based diversity nudge for open bins
    if progress < 0.1 { score += 3.0; }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let fit_ratio = pr / cap;
    let mut score = pr;

    // Reward tight fits: smooth quadratic coupling of post_residual with progress
    score -= 60.0 * (1.0 - fit_ratio) * (1.0 - fit_ratio) * (0.5 + progress);

    // Penalize dead space relative to mean residual (smooth cubic coupling)
    let dead = (pr - mean_residual) / cap;
    score += 25.0 * dead * dead * dead + 15.0 * dead * dead;

    // Last-chance bonus: strongly favor using the only fitting bin
    if fitting_bins_count == 1 {
        score -= 40.0 + 30.0 * (1.0 - fit_ratio);
    }

    // Lookahead coupling: reward residual that can host the next item
    if next_item_size > 0 {
        let ns = next_item_size as f64;
        let gap = pr - ns;
        if gap >= 0.0 {
            score -= 20.0 * (1.0 - (gap / cap).abs()) * (gap / cap).max(0.0);
        } else {
            score += 10.0 * (-gap / cap);
        }
    }

    // Mild penalty for spreading across many open bins early
    score += (open_bins_count as f64).ln() * (1.0 - progress) * 4.0;

    // Smooth new-bin bias: opening a fresh bin is attractive only for large items
    let fresh = (bin_residual as f64 - cap).abs() < 1e-9;
    if fresh {
        score += 30.0 - 60.0 * (item_size as f64 / cap) * (0.5 + 0.5 * progress);
    }

    score
}

