pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the resulting gap: post_residual bucketed by capacity fraction.
    let cap = bin_capacity as f64;
    let frac = post_residual as f64 / cap;

    // Dead-space penalty: gaps in (0, 10] are nearly unusable (min item is small but
    // gaps below the smallest common item class waste capacity).
    if post_residual > 0 && post_residual <= 10 {
        score += 40.0;
    }
    // Perfect fit reward.
    if post_residual == 0 {
        score -= 60.0;
    }

    // Harmonic class penalty: gaps that are NOT expressible as useful multiples
    // of common item classes (10/20/25/50) are penalized.
    let harmonic = (post_residual % 10 == 0) || (post_residual % 25 == 0) || (post_residual == 0);
    if !harmonic {
        score += 8.0;
    }

    // Large-gap waste: leaving more than half the bin empty is bad unless bin is fresh.
    if frac > 0.5 && bin_residual != bin_capacity {
        score += 15.0 * (frac - 0.5);
    }

    // Lookahead coupling: if next item fits exactly in the post residual, big reward.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 50.0;
        } else if next_item_size < post_residual {
            score -= 10.0;
        } else {
            // next item cannot follow here: mild penalty proportional to mismatch
            score += 5.0;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate handling: only attractive when nothing fits well.
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        let desperation = if fitting_bins_count == 0 { 1.0 } else { 0.0 };
        let big_item = item_size as f64 > 0.7 * cap;
        // Prefer new bin for big items or when no open bin fits; otherwise penalize.
        if desperation > 0.5 || big_item {
            score -= 25.0;
        } else {
            // Penalize proportional to how well existing bins could still absorb the item.
            let waste = (bin_capacity - item_size) as f64;
            score += 35.0 + 0.3 * waste;
        }
    }

    // Mild pressure toward consolidating many open bins as stream progresses.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += 0.02 * open_bins_count as f64 * progress;

    // Tie-break with mean residual: prefer bins tighter than average.
    score -= 0.1 * (mean_residual - post_residual as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap_f = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Strong tiered rewards for small residuals (hard-to-fill space eliminated).
    if post_residual == 0 {
        score -= 1180.0;
    } else if post_residual <= 3 {
        score -= 500.0;
    } else if post_residual <= 12 {
        score -= 98.0;
    } else if post_residual < 20 {
        score += 18.0;
    } else if post_residual < 30 {
        score += 18.0 + (30 - post_residual) as f64 * 0.6;
    }

    // Lookahead: pair with next item.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 900.0;
        } else if next_item_size <= post_residual {
            let post2 = post_residual - next_item_size;
            score -= 135.0 - post2 as f64 * 2.0;
            if post2 == 0 {
                score -= 110.0;
            }
            if post2 > 0 && post2 < 5 {
                score -= 28.0;
            }
            if post2 >= 20 && post2 % 5 == 0 {
                score -= 12.0;
            }
            if post_residual % next_item_size == 0 {
                score -= 18.0;
            }
            let chain = post_residual / next_item_size;
            if chain >= 2 {
                score -= (chain.min(4)) as f64 * 6.0;
            }
        } else {
            score += 20.0;
            let gap = next_item_size as f64 - post_residual as f64;
            if post_residual > 0 && post_residual < 15 {
                score += 45.0;
            }
            if gap <= 3.0 {
                score += 35.0;
            } else if gap <= 8.0 {
                score += 12.0;
            }
            if post_residual as f64 > mean_residual * 1.4 {
                score -= 12.0;
            }
        }
    }

    // Last-chance bin: strongly favor using it.
    if fitting_bins_count == 1 {
        score -= 25.0;
    } else if fitting_bins_count > 1 {
        score += 2.0 * (fitting_bins_count as f64 - 1.0);
    }

    // Progress-based global pressure.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score -= 8.0 * progress * (mean_residual / cap_f);

    if open_bins_count > 3 && mean_residual > item_size as f64 {
        score += 0.05 * open_bins_count as f64;
    }

    // New-bin candidate decision.
    if bin_residual == bin_capacity {
        let newbin_waste = (bin_capacity - item_size) as f64;
        let avg_fill = 1.0 - (mean_residual / cap_f);
        score += 250.0 - avg_fill * 330.0 - progress * 65.0;
        if fitting_bins_count > 0 {
            score += (fitting_bins_count as f64).min(5.0) * 9.0 + 20.0;
            let snug = item_size as f64 / bin_residual.max(1) as f64;
            if snug > 0.9 { score += 40.0; }
            if snug > 0.95 { score += 28.0; }
            if snug > 0.98 { score += 18.0; }
        }
        if item_size >= bin_capacity * 3 / 4 {
            score -= 55.0;
        }
        if next_item_size > 0 && next_item_size <= bin_capacity - item_size {
            score -= 25.0;
        }
        if bin_capacity - item_size <= 4 {
            score -= 70.0;
        }
        if newbin_waste > 0.0 && (newbin_waste as u32) < next_item_size && newbin_waste < cap_f * 0.12 {
            score += 26.0;
        }
        if progress > 0.6 {
            let waste_tol = (1.0 - progress) * cap_f * 0.35;
            if newbin_waste > waste_tol && fitting_bins_count > 0 {
                score += 10.0 + progress * 22.0;
            }
        }
        if next_item_size > 0 && next_item_size >= bin_capacity / 2 {
            score -= 32.0;
        }
    } else {
        // Tightness pressure: prefer bins where the item fills most of the residual.
        let tightness = 1.0 - (item_size as f64 / bin_residual.max(1) as f64);
        score += tightness * 85.0;
        score += (mean_residual - bin_residual as f64) * 1.5;

        let dead_ratio = post_residual as f64 / cap_f;
        if dead_ratio < 0.03 {
            score -= 38.0;
        } else if dead_ratio < 0.08 {
            score -= 14.0;
        } else if dead_ratio > 0.35 {
            score += 24.0;
        } else if dead_ratio > 0.25 {
            score += 10.0;
        }
        score += dead_ratio * 30.0;

        if post_residual > 0 && post_residual < 6 {
            score -= 22.0;
        }
        if post_residual > 0 && post_residual % 10 == 0 {
            score -= 10.0;
        }
        if item_size == bin_residual {
            score -= 45.0;
        }
        if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
            let wasted = next_item_size as f64 - post_residual as f64;
            score += wasted * 0.6;
            score += (1.0 - progress) * 14.0;
            let gap = wasted / next_item_size.max(1) as f64;
            if gap < 0.12 {
                score -= 10.0;
            }
        }
        if post_residual > 0 && next_item_size > 0 && post_residual >= next_item_size {
            let slack = post_residual - next_item_size;
            if slack > 0 && (slack as f64) < cap_f * 0.02 {
                score -= 14.0;
            }
        }
        if post_residual > 0 && (post_residual as f64) < mean_residual * 0.25 {
            score -= 15.0;
        }
        if fitting_bins_count <= 2 && post_residual > 0 {
            score -= 8.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit: strong reward
    if post_residual == 0 {
        score -= 15.0;
    }

    // Strict dead-space avoidance: small unusable gaps are heavily penalized
    if post_residual > 0 && post_residual < 10 {
        score += (10 - post_residual) as f64 * 2.5;
    }

    // Last-chance bin: strongly favor using it before opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 8.0;
    }

    // Lookahead coupling: reward if next item fits into the resulting gap
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 4.0 + next_item_size as f64 * 0.1;
        } else if post_residual > 0 {
            // gap will be dead for the next item
            score += 3.0;
        }
    }

    // New-bin candidate handling
    if bin_residual == bin_capacity {
        // Base penalty: prefer filling open bins when reasonably possible
        score += 12.0 + open_bins_count as f64 * 0.5;
        // If no open bin can fit the item, opening a new bin is necessary
        if fitting_bins_count == 0 {
            score -= 30.0;
        }
    }

    // Mild open-bins pressure scaled by residual fraction
    score += open_bins_count as f64 * 0.05 * (post_residual as f64 / bin_capacity as f64);

    score
}

