    if post_residual > 0 && post_residual < 10 {
        score += 40.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 20.0;
    }

    // New-bin candidate: penalize opening a bin when good fits exist.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score += 60.0
            + 10.0 * open_bins_count as f64
            - 15.0 * progress;
        // If next item could fill this fresh bin perfectly, allow it more.
        if next_item_size > 0 && next_item_size as f64 >= bin_capacity as f64 * 0.7 {
            score -= 20.0;
        }
    }

    // Prefer bins with residuals close to the mean (balanced packing).
    score += 0.3 * (bin_residual as f64 - mean_residual).abs();

    // Mild preference for tighter fits overall.
    score += 0.2 * (bin_residual - item_size) as f64 * (1.0 - item_size as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap_f = bin_capacity as f64;
    let progress = step_index as f64 / total_items.max(1) as f64;
    let mut score = post_residual as f64;

    // Tiered dead-space avoidance (strengthened exact/near fits)
    if post_residual == 0 {
        score -= 900.0;
    } else if post_residual <= 3 {
        score -= 380.0;
    } else if post_residual <= 12 {
        score -= 90.0 - (post_residual as f64) * 2.0;
    } else if post_residual < 20 {
        score += 16.0;
    } else if post_residual < 30 {
        score += 10.0 + (30 - post_residual) as f64 * 0.5;
    }

    // Dead-ratio shaping
    let dead_ratio = post_residual as f64 / cap_f;
    if post_residual > 0 {
        if dead_ratio < 0.03 { score -= 30.0; }
        else if dead_ratio < 0.08 { score -= 12.0; }
        else if dead_ratio > 0.35 { score += 22.0; }
        else if dead_ratio > 0.25 { score += 9.0; }
    }

    // Lookahead: exact and near-exact fits for the next item
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 700.0;
        } else if next_item_size <= post_residual {
            let post2 = post_residual - next_item_size;
            score -= 110.0 - (post2 as f64) * 2.0;
            if post2 == 0 { score -= 90.0; }
            if post2 > 0 && post2 < 5 { score -= 26.0; }
            if post2 > 0 && post2 <= 2 { score -= 12.0; }
            if post2 % 10 == 0 && post2 > 0 { score -= 20.0; }
            if post_residual % next_item_size == 0 { score -= 14.0; }
            if post_residual >= next_item_size * 2 && post_residual - next_item_size * 2 <= 4 {
                score -= 18.0;
            }
            let chain = post_residual / next_item_size;
            if chain >= 2 { score -= (chain.min(4)) as f64 * 6.0; }
            if post2 > 0 && post2 <= next_item_size / 4 { score -= 9.0; }
        } else {
            let gap = next_item_size - post_residual;
            if post_residual > 0 {
                if gap <= 3 { score += 35.0; }
                else if gap <= 8 { score += 12.0; }
                if (gap as f64) > mean_residual * 0.5 { score += 12.0; }
                if post_residual < 15 { score += 30.0 * (1.0 - progress); }
                if gap <= 5 { score += (6 - gap) as f64 * 4.0; }
            }
        }
    }

    // Compaction pressure
    score += open_bins_count as f64 * 0.8;

    // Last-chance bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 45.0;
    }

    // Tightness via relative fill
    score -= (item_size as f64 / bin_residual.max(1) as f64) * 30.0;

    // Consolidate slack: prefer bins below average residual
    if bin_residual < bin_capacity {
        score += (mean_residual - bin_residual as f64) * 1.0;
    }

    // NEW-BIN CANDIDATE handling
    if bin_residual == bin_capacity {
        let newbin_waste = (bin_capacity - item_size) as f64;
        let avg_fill = 1.0 - (mean_residual / cap_f);
        score += 220.0 - avg_fill * 300.0 - progress * 65.0;
        if item_size as f64 / cap_f > 0.75 { score -= 55.0; }
        if item_size >= bin_capacity * 3 / 4 { score -= 55.0; }
        if item_size as f64 > mean_residual { score -= 35.0; }
        if newbin_waste < mean_residual * 0.5 { score -= 30.0; }
        if bin_capacity - item_size <= 4 { score -= 70.0; }
        if next_item_size > 0 {
            let leftover = bin_capacity - item_size;
            if leftover >= next_item_size {
                let tail = leftover % next_item_size;
                if tail == 0 { score -= 22.0; }
                else if tail <= 4 { score -= 14.0; }
                if leftover - next_item_size <= 6 { score -= 35.0; }
                if leftover >= next_item_size * 2 { score -= 12.0; }
            } else if leftover < 10 {
                score += 18.0;
            }
            if next_item_size >= bin_capacity / 2 { score -= 30.0; }
        }
        if fitting_bins_count > 0 {
            score += (fitting_bins_count.min(5) as f64) * 9.0 + 20.0;
            let snug = item_size as f64 / bin_residual.max(1) as f64;
            if snug > 0.9 { score += 40.0; }
            if snug > 0.95 { score += 28.0; }
        }
        // late stream: waste tolerance shrinks
        if progress > 0.6 {
            let waste_tol = (1.0 - progress) * cap_f * 0.35;
            if newbin_waste > waste_tol && fitting_bins_count > 0 {
                score += 10.0 + progress * 22.0;
            }
        }
        if progress < 0.1 { score -= 5.0; }
    } else if progress < 0.1 {
        score += 3.0;
    }

    // Unusable-gap penalty for open bins
    if post_residual > 0 && next_item_size > 0 && post_residual < next_item_size {
        let unusable_gap = (next_item_size - post_residual) as f64;
        if unusable_gap > 12.0 {
            score += unusable_gap * 0.6 + dead_ratio * 60.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tightness: reward small post_residual non-linearly (best-fit core).
    let fit_ratio = item_size as f64 / bin_residual as f64;
    score -= 12.0 * fit_ratio * fit_ratio;

    // Penalize tiny dead space that is hard to reuse (below typical small item size).
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // Lookahead: if the next item fits exactly in the post residual, reward this placement.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 20.0;
        } else if post_residual >= next_item_size {
            score -= 5.0;
        } else {
            // Next item cannot use this bin's remainder: penalize proportionally.
            score += 4.0 * (next_item_size - post_residual) as f64 / bin_capacity as f64 * 10.0;
        }
    }

    // New-bin candidate handling: opening a bin is expensive; only attractive when
    // existing bins are crowded or the item is large.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let crowding = mean_residual / bin_capacity as f64;
        // Big items fit better in fresh bins; small items should fill leftovers.
        let big_item_bonus = (item_size as f64 / bin_capacity as f64).powi(3) * 40.0;
        score = 60.0 + 40.0 * (1.0 - crowding) - big_item_bonus
            - 15.0 * (1.0 - progress)
            - if fitting_bins_count == 0 { 50.0 } else { 0.0 };
        if next_item_size > 0 && next_item_size >= item_size {
            score -= 10.0; // fresh bin useful for a run of large items
        }
    }

    // Prefer bins whose residual is near mean residual (balanced packing),
    // mildly, so we don't fight best-fit.
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += 0.05 * dev;

    // Slight preference for fewer open bins overall (consolidation pressure).
    score += 0.5 * open_bins_count as f64 / (total_items.max(1) as f64);

    score
}

