    } else if post_residual <= 12 {
        score -= 80.0;
    } else if post_residual < 20 {
        score += 18.0;
    } else if post_residual < 30 {
        score += 18.0 + (30 - post_residual) as f64 * 0.6;
    }

    // Lookahead on next item
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 800.0;
        } else if next_item_size <= post_residual {
            let post2 = post_residual - next_item_size;
            score -= 120.0 - post2 as f64 * 2.0;
            if post2 == 0 { score -= 90.0; }
            if post2 > 0 && post2 < 5 { score -= 25.0; }
            if post2 % 10 == 0 && post2 > 0 { score -= 25.0; }
            if post_residual % next_item_size == 0 { score -= 15.0; }
        } else {
            score += 18.0;
            if post_residual > 0 && post_residual < 15 { score += 40.0; }
            if post_residual > 0 && (next_item_size - post_residual) <= 3 { score += 30.0; }
            if post_residual as f64 > mean_residual * 1.4 { score -= 10.0; }
        }
    }

    // NEW-BIN CANDIDATE handling
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let avg_fill = 1.0 - (mean_residual / cap_f);
        score += 240.0 - avg_fill * 320.0 - progress * 60.0;

        if fitting_bins_count > 0 {
            score += (fitting_bins_count as f64).min(5.0) * 9.0 + 20.0;
            let snug = item_size as f64 / bin_residual.max(1) as f64;
            if snug > 0.9 { score += 35.0; }
            if snug > 0.95 { score += 25.0; }
        }
        if item_size >= bin_capacity * 3 / 4 { score -= 50.0; }
        if bin_capacity - item_size <= 4 { score -= 60.0; }

        let newbin_waste = (bin_capacity - item_size) as f64;
        if newbin_waste > 0.0 && newbin_waste < mean_residual * 0.6 { score -= 28.0; }
        if fitting_bins_count > 0 && newbin_waste > mean_residual + cap_f * 0.08 { score += 20.0; }
        if progress > 0.6 {
            let waste_tol = (1.0 - progress) * cap_f * 0.35;
            if newbin_waste > waste_tol && fitting_bins_count > 0 {
                score += 10.0 + progress * 20.0;
            }
        }
        if next_item_size > 0 && newbin_waste > 0.0 && (newbin_waste as u32) < next_item_size && newbin_waste < cap_f * 0.12 {
            score += 24.0;
        }
        if next_item_size > 0 && newbin_waste >= next_item_size as f64 && (newbin_waste as u32) % next_item_size == 0 {
            score -= 18.0;
        }
    } else {
        // Existing bin: tightness and residual shaping
        let tightness = 1.0 - (item_size as f64 / bin_residual.max(1) as f64);
        score += tightness * 80.0;
        score += (mean_residual - bin_residual as f64) * 1.5;

        if item_size == bin_residual { score -= 40.0; }

        let dead_ratio = post_residual as f64 / cap_f;
        if dead_ratio < 0.03 { score -= 35.0; }
        else if dead_ratio < 0.08 { score -= 12.0; }
        else if dead_ratio > 0.35 { score += 22.0; }
        else if dead_ratio > 0.25 { score += 8.0; }
        score += dead_ratio * 30.0;

        if next_item_size > 0 && post_residual > 0 {
            if post_residual < next_item_size {
                let wasted = next_item_size as f64 - post_residual as f64;
                score += wasted * 0.6;
                if (next_item_size - post_residual) <= 2 {
                    let progress = step_index as f64 / total_items.max(1) as f64;
                    score += 10.0 * (1.0 - progress);
                }
            } else {
                let chain = post_residual / next_item_size;
                if chain >= 2 { score -= (chain.min(4)) as f64 * 6.0; }
                if post_residual % next_item_size <= 2 { score -= 8.0; }
            }
        }

        if post_residual > 0 && post_residual < 6 { score -= 20.0; }
        if post_residual > 0 && post_residual % 5 == 0 && post_residual <= 30 { score -= 8.0; }
        if fitting_bins_count == 1 { score -= 20.0; }
        if fitting_bins_count <= 2 && post_residual > 0 { score -= 6.0; }
        if post_residual > 0 && (post_residual as f64) < mean_residual * 0.25 { score -= 14.0; }
    }

    // Compaction pressure
    score += open_bins_count as f64 * 0.8;
    score -= (item_size as f64 / cap_f) * 10.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;

    let mut score = pr;

    // Smooth non-linear coupling of post_residual with stream progress
    score += 12.0 * norm_pr * norm_pr * (1.0 - progress);
    score -= 9.0 * norm_pr * (1.0 - norm_pr) * progress;

    // Penalize large post_residual when mean residual is high (wasteful spread)
    score += 6.0 * norm_pr * ((mean_residual / cap) - norm_pr).abs();

    // Last-chance bonus: strongly prefer using the only fitting bin
    if fitting_bins_count == 1 {
        score -= 25.0 + 15.0 * (1.0 - norm_pr);
