    // Lookahead: reward leaving room for the next item, penalize blocking it
    if next_item_size > 0 {
        let ns = next_item_size as f64;
        if ns <= pr {
            score -= 8.0 * (1.0 - (ns / pr.max(1.0)));
        } else {
            score += 10.0 * ((ns - pr) / cap);
        }
    }

    // Mild preference for keeping few open bins early, filling late
    score += 2.0 * (open_bins_count as f64).ln() * (1.0 - progress);

    score
}

