pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: bins whose leftover falls into
    // "small dead-space" classes are preferred.
    let progress = step_index as f64 / total_items.max(1) as f64;

    // Class A: post_residual divisible by 10 -> clean slots, big reward.
    if post_residual % 10 == 0 {
        score -= 8.0;
    }
    // Class B: post_residual divisible by 5 but not 10 -> mild reward.
    else if post_residual % 5 == 0 {
        score -= 3.0;
    }

    // Integer-division thresholds on post_residual: dead-space bands.
    let band = post_residual / 10; // 0..10
    match band {
        0 => score += 12.0,          // near-perfect fill, but risky waste
        1 => score -= 6.0,           // 10-19 leftover: very usable
        2 => score -= 4.0,           // 20-29
        3 => score -= 2.0,           // 30-39
        4 | 5 => score += 1.0,       // mid leftovers: mediocre
        6 | 7 => score += 3.0,       // large leftovers: wasteful
        _ => score += 5.0,           // nearly empty bin being used poorly
    }

    // Lookahead coupling: if next item fits exactly into post_residual,
    // strongly favor this bin (harmonic chaining).
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 15.0;
        } else if next_item_size <= post_residual {
            let slack = post_residual - next_item_size;
            if slack % 10 == 0 {
                score -= 7.0;
            } else if slack <= 10 {
                score -= 5.0;
            } else {
                score += slack as f64 * 0.15;
            }
        } else {
            // Next item won't fit here; penalize if this bin becomes a trap.
            score += (next_item_size - post_residual) as f64 * 0.05;
        }
    }

    // Last-chance bonus: only bin that fits -> avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 10.0;
    }

    // New-bin candidate: only attractive when existing residuals are poor.
    if bin_residual == bin_capacity {
        let poor_existing = mean_residual < item_size as f64;
        if poor_existing {
            score -= 6.0 + 4.0 * progress;
        } else {
            score += 14.0;
        }
    }

    // Prefer tightest existing bins when many bins are open.
    score += mean_residual * 0.05;
    score -= (open_bins_count as f64).ln() * 0.5;

    // Late-stream: consolidate harder.
    score += 6.0 * progress * (bin_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap_f = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Dead-space avoidance: tiered, stronger than parent
    if post_residual == 0 {
        score -= 900.0; // perfect fit
    } else if post_residual <= 3 {
        score -= 380.0;
    } else if post_residual <= 12 {
        score -= 70.0;
    } else if post_residual < 20 {
        score += 18.0;
    } else if post_residual < 30 {
        score += 18.0 + (30 - post_residual) as f64 * 0.6;
    }

    // Lookahead: exact and near-exact fits for the next item
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 700.0;
        } else if next_item_size <= post_residual {
            let post2 = post_residual - next_item_size;
            score -= 90.0 - (post2 as f64) * 1.6;
            if post2 == 0 { score -= 80.0; }
