            if post2 > 0 && post2 <= next_item_size / 4 { score -= 10.0; }
            if post_residual >= next_item_size * 2 && post_residual - next_item_size * 2 <= 4 {
                score -= 18.0;
            }
            let chain = post_residual / next_item_size;
            if chain >= 2 { score -= (chain.min(4)) as f64 * 6.0; }
        } else {
            let gap = next_item_size - post_residual;
            if post_residual > 0 {
                if gap <= 3 { score += 35.0; }
                else if gap <= 8 { score += 12.0; }
                if (gap as f64) > mean_residual * 0.5 { score += 12.0; }
                if post_residual < 15 { score += 40.0; }
                if gap <= 5 { score += (6 - gap) as f64 * 4.0; }
            }
        }
    }

    // Compaction pressure scaled by open bins
    score += open_bins_count as f64 * 0.8;

    // Last-chance bin: strongly favor using it
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 45.0;
    }

    // Tightness via relative fill
    score -= (item_size as f64 / bin_residual.max(1) as f64) * 30.0;

    // NEW-BIN CANDIDATE handling
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let newbin_waste = (bin_capacity - item_size) as f64;
        score += 220.0 - progress * 70.0;
        if item_size as f64 / cap_f > 0.75 { score -= 55.0; }
        if item_size as f64 > mean_residual { score -= 40.0; }
        if newbin_waste < mean_residual * 0.5 { score -= 30.0; }
        if bin_capacity - item_size <= 4 { score -= 70.0; }
        if next_item_size > 0 && (bin_capacity - item_size) >= next_item_size
            && (bin_capacity - item_size) - next_item_size <= 6 {
            score -= 38.0;
        }
        if next_item_size > 0 {
            let leftover = bin_capacity - item_size;
            if leftover >= next_item_size {
                let tail = leftover % next_item_size;
                if tail == 0 { score -= 18.0; }
                else if tail <= 4 { score -= 12.0; }
            }
            if leftover >= next_item_size * 2 { score -= 12.0; }
            if leftover < next_item_size && leftover < 10 { score += 18.0; }
        }
        if fitting_bins_count > 3 { score += (fitting_bins_count.min(6) as f64) * 7.0; }
        // avoid opening a bin when a decent alternative exists
        if fitting_bins_count > 0 {
            let best_alt = if item_size as f64 <= mean_residual { mean_residual - item_size as f64 } else { mean_residual };
            if newbin_waste > best_alt + cap_f * 0.08 { score += 25.0; }
        }
        if progress > 0.6 {
            let waste_tol = (1.0 - progress) * cap_f * 0.35;
            if newbin_waste > waste_tol && fitting_bins_count > 0 { score += 12.0 + progress * 20.0; }
        }
        if progress < 0.1 { score -= 5.0; }
    } else {
        // Consolidate slack: prefer below-average residuals
        score += (mean_residual - bin_residual as f64) * 1.2;
        let dead_ratio = post_residual as f64 / cap_f;
        if dead_ratio < 0.03 { score -= 35.0; }
        else if dead_ratio < 0.08 { score -= 12.0; }
        else if dead_ratio > 0.35 { score += 24.0; }
        else if dead_ratio > 0.25 { score += 10.0; }
        if item_size == bin_residual { score -= 45.0; }
        if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
            let wasted = next_item_size as f64 - post_residual as f64;
            score += wasted * 0.6;
            let gap = wasted / next_item_size.max(1) as f64;
            if gap < 0.12 { score -= 10.0; }
        }
        if post_residual > 0 && post_residual % 10 == 0 { score -= 10.0; }
        if post_residual > 0 && post_residual < 6 { score -= 20.0; }
    }

    // Mild progress-based diversity nudge for open bins
    let progress = step_index as f64 / total_items.max(1) as f64;
    if progress < 0.1 { score += 3.0; }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps are heavily penalized.
    // A residual that is too small to hold even the smallest plausible item (1)
    // is perfect, but a small-but-nonzero gap is dead space.
    let pr = post_residual as f64;
    if post_residual == 0 {
        // Perfect fit: strong reward.
        score -= 60.0;
    } else if post_residual < 10 {
        // Unusable tiny gap: heavy penalty (dead space).
        score += 45.0 * (1.0 - pr / 10.0);
    } else {
        // Usable gap: mildly prefer smaller gaps but keep them usable.
        score += 5.0 * (1.0 - pr / (bin_capacity as f64));
    }

    // Reward tight fits (item fills most of the bin).
    let fill_ratio = item_size as f64 / bin_capacity as f64;
    score -= 25.0 * fill_ratio;

    // Last-chance bonus: if this is the only fitting bin, avoid opening a new bin
    // unless the fit is terrible.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // Open-bin pressure: with many open bins, prefer filling existing ones;
    // with few open bins, opening a new bin is cheaper.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += (open_bins_count as f64) * (0.4 + 0.6 * progress);

    // New-bin candidate handling: an empty bin gets a moderate baseline score so
    // it wins only when no open bin offers a decent fit.
    if bin_residual == bin_capacity {
        score += 15.0;
        // If the next item is large and current item is small, saving residual
        // space is valuable: discourage wasting a fresh bin on a poor pairing.
        if next_item_size > 0 && (next_item_size as f64) > 0.6 * bin_capacity as f64 && item_size < 40 {
            score += 12.0;
        }
    } else {
        // Prefer bins whose residual matches the next item's needs.
        if next_item_size > 0 && post_residual >= next_item_size {
            score -= 8.0;
        }
    }

    // Mean-residual coupling: if average residual across bins is high, spread is
    // fine; if low, avoid fragmenting further.
    if mean_residual < 15.0 && bin_residual != bin_capacity {
        score += 6.0;
    }

    score
}

