        if bin_capacity - item_size <= 4 { score -= 65.0; }
        if next_item_size > 0 && (bin_capacity - item_size) >= next_item_size
            && (bin_capacity - item_size) - next_item_size <= 6 {
            score -= 40.0;
        }
        if next_item_size > 0 {
            let leftover = bin_capacity - item_size;
            if leftover >= next_item_size {
                let tail = leftover % next_item_size;
                if tail <= 4 { score -= 14.0; }
                if tail == 0 { score -= 10.0; }
                if leftover >= next_item_size * 2 { score -= 12.0; }
            }
            if leftover < next_item_size && leftover < 10 { score += 16.0; }
        }
        if fitting_bins_count > 0 {
            score += (fitting_bins_count.min(6) as f64) * 7.0;
        }
        if fitting_bins_count > 3 && item_size as f64 / cap_f < 0.5 { score += 25.0; }
        if progress > 0.75 && newbin_waste > cap_f * 0.5 { score += 12.0; }
        if progress > 0.6 {
            let waste_tol = (1.0 - progress) * cap_f * 0.35;
            if newbin_waste > waste_tol && fitting_bins_count > 0 {
                score += 10.0 + progress * 20.0;
            }
        }
        if next_item_size > 0 && newbin_waste > 0.0 && (newbin_waste as u32) < next_item_size && newbin_waste < cap_f * 0.12 {
            score += 24.0;
        }
        if progress < 0.1 { score -= 5.0; }
    } else {
        // Consolidation of slack: prefer bins below-average residual
        score += (mean_residual - bin_residual as f64) * 1.1;

        let dead_ratio = post_residual as f64 / cap_f;
        if dead_ratio < 0.03 { score -= 30.0; }
        else if dead_ratio < 0.08 { score -= 12.0; }
        else if dead_ratio > 0.35 { score += 20.0; }
        else if dead_ratio > 0.25 { score += 10.0; }

        // Unusable-gap penalty scaled by dead fraction
        if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
            let wasted = next_item_size as f64 - post_residual as f64;
            score += wasted * 0.7;
            if wasted > 12.0 { score += dead_ratio * 70.0; }
        }
        if post_residual > 0 && post_residual < 6 { score -= 18.0; }
        if post_residual > 0 && (post_residual as f64) < mean_residual * 0.25 { score -= 12.0; }
        if post_residual > 0 && post_residual % 10 == 0 { score -= 8.0; }
        if post_residual > 0 && (post_residual as f64) < cap_f * 0.015 { score -= 16.0; }

        // Reuse potential: residual can host next item multiple times
        if next_item_size > 0 && post_residual > 0 && post_residual >= next_item_size {
            let reuse = (post_residual / next_item_size) as f64 * (next_item_size as f64 / cap_f);
            score -= reuse * 20.0;
        }
        if fitting_bins_count <= 2 && post_residual > 0 { score -= 8.0; }
        if progress < 0.1 { score += 3.0; }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: fill fraction of the bin consumed by this item.
    let fill = item_size as f64 / bin_capacity as f64;
    score -= 45.0 * fill * fill;

    // Penalize large dead space after placement, nonlinearly.
    if post_residual > 0 {
        let dead = post_residual as f64 / bin_capacity as f64;
        score += 20.0 * dead * dead;
    }

    // Lookahead: if the next item fits exactly in the post-residual, big reward.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 60.0;
        } else if next_item_size <= post_residual {
            // next item fits but leaves further slack: mild reward proportional to use
            score -= 15.0 * (next_item_size as f64 / post_residual as f64);
        } else {
            // next item cannot use this bin's remainder: penalize leftover
            score += 8.0;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    } else if fitting_bins_count > 1 {
        // competition among fitting bins: prefer bins with less residual waste
        score += 2.0 * (fitting_bins_count as f64).ln();
    }

    // Time horizon: early in the stream, keep bins open (favor existing bins);
    // late in the stream, prioritize consolidation.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score -= 10.0 * progress * (1.0 - post_residual as f64 / bin_capacity as f64);

    // Global pressure: many open bins with high mean residual -> discourage
    // spreading; few open bins -> tolerate opening new ones less readily.
    score += 0.05 * open_bins_count as f64;
    score -= 0.10 * mean_residual;

    // New-bin candidate handling: empty bin is attractive only when the item
    // is large or existing fits are poor (post_residual tiny but nonzero).
    if bin_residual == bin_capacity {
        let poor_fit = post_residual > 0 && post_residual < item_size;
        if poor_fit && fitting_bins_count >= 1 {
            score -= 12.0;
        } else {
            score += 25.0;
        }
        // late stream: prefer consolidating into open bins
        score += 15.0 * progress;
    }

    // Small coupling: exact-perfect fill bonus.
    if post_residual == 0 {
        score -= 40.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let pr_norm = pr / cap;

    // Base: penalize large post-residual (wasted space), reward tight fits.
    let mut score = pr;

    // Non-linear coupling of post-residual with stream progress:
    // early on, prefer bins leaving moderate residual (flexibility);
    // later, strongly prefer minimal residual (compact packing).
    let late_weight = progress * progress;
    let early_weight = (1.0 - progress) * (1.0 - progress);
    score += late_weight * pr_norm * cap * 0.5;              // amplify waste penalty late
    score -= early_weight * (pr_norm * (1.0 - pr_norm)) * 20.0; // reward mid-range residuals early

    // Smooth interaction: residual vs mean residual deviation, scaled by progress.
    let dev = (pr as f64 - mean_residual) / cap;
    score += late_weight * dev * 15.0;

    // Lookahead coupling: reward if next item fits post-residual, penalize otherwise.
    if next_item_size > 0 {
        let next = next_item_size as f64;
        let fits_next = (next <= pr as f64) as i32 as f64;
        score -= fits_next * (10.0 + 10.0 * progress);
        score += (1.0 - fits_next) * (next / cap) * 8.0 * (0.5 + progress);
    }

    // Last-chance bonus: smooth pressure when few fitting bins.
    let scarcity = 1.0 / (fitting_bins_count as f64 + 1.0);
    score -= scarcity * (item_size as f64 / cap) * 12.0;

    // Mild penalty for spreading across many open bins, stronger late in stream.
    score += (open_bins_count as f64 / (open_bins_count as f64 + 5.0)) * late_weight * 5.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of the post-residual: residuals divisible by 10 are
    // "harmonically aligned" with typical item sizes and easier to fill later.
    let harmonic = (post_residual % 10) as f64;
    score += harmonic * 1.5;

    // Integer-division thresholds: post_residual buckets by quarter capacity.
    let quarter = bin_capacity / 4;
    if post_residual < quarter {
        // Tight fit: small dead space, reward strongly.
        score -= 12.0;
    } else if post_residual < 2 * quarter {
        score -= 4.0;
    } else if post_residual < 3 * quarter {
        score += 3.0;
    } else {
        score += 8.0;
    }

    // Perfect / near-perfect fill rewards.
    if post_residual == 0 {
        score -= 60.0;
    } else if post_residual <= 5 {
        score -= 30.0;
    }

    // Lookahead coupling: if the next item fits exactly into the post-residual
    // (harmonic match), strongly favor this bin.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 45.0;
        } else if next_item_size <= post_residual {
            let gap = post_residual - next_item_size;
            score -= (20.0 - (gap % 10) as f64).max(0.0);
        } else {
            // Next item cannot use this residual at all: penalize large leftovers.
            score += (post_residual % next_item_size.max(1)) as f64 * 0.5;
        }
    } else {
        // Last item: any residual is pure waste; minimize it hard.
        score *= 2.0;
    }

    // Last-chance bonus: if this is the only fitting bin, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate handling: an empty bin has maximal residual; make it
    // attractive only when no open bin offers a decent (harmonic) fit.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let pressure = (open_bins_count as f64 * 0.15) + mean_residual / cap;
        // Late in the stream with tight open bins, prefer opening fresh bins
        // for large items rather than fragmenting.
        if item_size > bin_capacity / 2 {
            score -= 10.0 + 20.0 * progress;
        } else {
            score += 25.0 * (1.0 - pressure.min(1.0));
        }
    }

    // Mild pressure toward consolidating into few bins early on.
    score -= (open_bins_count as f64).ln().max(0.0) * (item_size as f64 / cap) * 2.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap_f = bin_capacity as f64;
    let progress = step_index as f64 / total_items.max(1) as f64;
    let mut score = post_residual as f64;

    // Dead-space avoidance: stronger tiering (borrowed from best)
    if post_residual == 0 {
        score -= 900.0;
    } else if post_residual <= 3 {
        score -= 420.0;
    } else if post_residual <= 12 {
        score -= 90.0;
    } else if post_residual < 20 {
        score += 15.0;
    } else if post_residual < 30 {
        score += 10.0 + (30 - post_residual) as f64 * 0.5;
    }

    // Lookahead: exact and near-exact fits for the next item
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 700.0;
        } else if next_item_size <= post_residual {
            let post2 = post_residual - next_item_size;
            score -= 120.0 - post2 as f64 * 2.0;
            if post2 == 0 { score -= 90.0; }
            if post2 > 0 && post2 < 5 { score -= 28.0; }
            if post2 % 10 == 0 && post2 > 0 { score -= 20.0; }
            if post_residual % next_item_size == 0 { score -= 14.0; }
            if post_residual >= next_item_size * 2 && post_residual - next_item_size * 2 <= 4 {
                score -= 20.0;
            }
            let chain = post_residual / next_item_size;
            if chain >= 2 { score -= (chain.min(4)) as f64 * 6.0; }
            if post2 > 0 && post2 <= next_item_size / 4 { score -= 10.0; }
        } else {
            // next item won't fit here: penalize leaving a nearly-fitting gap
            let gap = next_item_size - post_residual;
            if post_residual > 0 {
                if gap <= 3 { score += 40.0; }
                else if gap <= 8 { score += 14.0; }
                if (gap as f64) > mean_residual * 0.5 { score += 12.0; }
                if post_residual < 15 { score += 35.0; }
            }
        }
    }

    // Compaction pressure scaled by open bins
    score += open_bins_count as f64 * 0.8;

    // Last-chance bin: strongly favor using it
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 55.0;
    }

    // Tightness via relative fill
    let snug = item_size as f64 / bin_residual.max(1) as f64;
    score -= snug * 30.0;
    if bin_residual < bin_capacity && snug > 0.95 { score -= 12.0; }

    // NEW-BIN CANDIDATE handling
    if bin_residual == bin_capacity {
        let newbin_waste = (bin_capacity - item_size) as f64;
        let avg_fill = 1.0 - (mean_residual / cap_f);
        score += 230.0 - avg_fill * 300.0 - progress * 60.0;
        if item_size as f64 / cap_f > 0.75 { score -= 60.0; }
        if item_size as f64 > mean_residual { score -= 35.0; }
        if newbin_waste < mean_residual * 0.5 { score -= 35.0; }
        if next_item_size > 0 {
            let leftover = bin_capacity - item_size;
            if leftover >= next_item_size && leftover - next_item_size <= 6 { score -= 40.0; }
            if leftover >= next_item_size * 2 { score -= 12.0; }
            if leftover < next_item_size && leftover < 10 { score += 20.0; }
        }
        if bin_capacity - item_size <= 4 { score -= 60.0; }
        if fitting_bins_count > 0 {
            score += (fitting_bins_count.min(6) as f64) * 8.0 + 15.0;
            if snug > 0.9 { score += 35.0; }
            if snug > 0.98 { score += 15.0; }
        }
        if progress > 0.6 {
            let waste_tol = (1.0 - progress) * cap_f * 0.35;
            if newbin_waste > waste_tol && fitting_bins_count > 0 {
                score += 12.0 + progress * 25.0;
            }
        }
        if progress < 0.1 { score -= 5.0; }
    } else {
        // Consolidate slack: prefer bins below average residual
        score += (mean_residual - bin_residual as f64) * 1.2;
        let dead_ratio = post_residual as f64 / cap_f;
        if dead_ratio < 0.03 { score -= 30.0; }
        else if dead_ratio > 0.3 { score += 20.0; }
        if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
            let wasted = next_item_size as f64 - post_residual as f64;
            score += wasted * 0.6;
        }
        if item_size == bin_residual { score -= 40.0; }
        if post_residual > 0 && post_residual < 6 { score -= 18.0; }
    }

    // Mild progress-based diversity nudge for open bins
    if progress < 0.1 && bin_residual < bin_capacity { score += 3.0; }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
