        // early stream: allow diversity
        if progress < 0.1 { score -= 5.0; }
    }

    // Prefer bins whose residual is below average (consolidating slack)
    if bin_residual < bin_capacity {
        score += (mean_residual - bin_residual as f64) * 1.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tight fit reward: small post_residual strongly favored.
    if post_residual <= 5 {
        score -= 40.0;
    } else if post_residual <= 10 {
        score -= 20.0;
    }

    // Dead space penalty: unusable small gaps (below min item size ~10).
    if post_residual > 0 && post_residual < 10 {
        score += 30.0;
    }

    // Penalize large waste relative to capacity.
    score += (post_residual as f64 / bin_capacity as f64) * 25.0;

    // Last-chance bonus: only this bin fits, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 35.0;
    }

    // Open bin pressure: prefer spreading across existing bins when many are open.
    score += open_bins_count as f64 * 0.8;

    // New-bin candidate handling: penalize opening a new bin unless existing
    // fits are poor (large post_residual elsewhere) or no bins fit.
    if bin_residual == bin_capacity {
        score += 15.0 + open_bins_count as f64 * 1.2;
        // If next item is small, a fresh bin is more attractive (keeps flexibility).
        if next_item_size > 0 && next_item_size <= 30 {
            score -= 10.0;
        }
    }

    // Lookahead: if placing here leaves room for the next item, reward.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 8.0;
    } else if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 6.0;
    }

    // Progress-based mild tightening: later in stream, favor consolidation.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += progress * (mean_residual - post_residual as f64) * 0.1;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit bonus: reward bins whose residual is exactly consumed.
    if post_residual == 0 {
        score -= 60.0;
    } else {
        // Penalize small dead space that no item (min size 1..) can use well,
        // scaled by how small the gap is relative to item size.
        let gap = post_residual as f64;
        if gap < item_size as f64 {
