        let slack = (post_residual as i64 - next_item_size as i64) as f64;
        score -= 10.0 * (1.0 - slack / bin_capacity as f64).max(0.0);
    } else if next_item_size > 0 {
        // Next item won't fit here: penalize slightly, more if post residual is tiny.
        score += 6.0 * (1.0 - post_residual as f64 / bin_capacity as f64);
    }

    // Mean residual coupling: prefer bins below the mean residual (tighter bins),
    // encouraging consolidation of small residuals.
    score -= 0.5 * (mean_residual - post_residual as f64);

    // Last-chance bin: strongly favor using the only bin that fits.
    if fitting_bins_count == 1 {
        score -= 40.0;
    }

    // New-bin candidate: penalize opening a new bin unless the item is large
    // relative to capacity (poor fits elsewhere) or few bins are open.
    if bin_residual == bin_capacity {
        let pressure = if next_item_size > 0 {
            (item_size as f64 + next_item_size as f64) / bin_capacity as f64
        } else {
            item_size as f64 / bin_capacity as f64
        };
        let base_penalty = 55.0 + 3.0 * open_bins_count as f64;
        score += base_penalty - 60.0 * pressure.max(0.0).min(1.0);
    }

    // Late in the stream: be more conservative, prefer tighter packing.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += 5.0 * progress * (post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Core best-fit bias: strongly prefer small post-residual.
    score += (post_residual as f64).powf(1.35) * 0.05;

    // Perfect fit reward.
    if post_residual == 0 {
        score -= 60.0;
    }

    // Lookahead: if the next item exactly fits the post-residual, big reward.
    if next_item_size > 0 && post_residual >= next_item_size {
        let slack = (post_residual - next_item_size) as f64;
        score -= 25.0 * (1.0 - slack / bin_capacity as f64);
        if slack == 0.0 {
            score -= 40.0;
        }
    }
    // Penalize if next item cannot use post-residual but it is small (dead space risk).
    if next_item_size > post_residual && post_residual > 0 && post_residual < 10 {
        score += 15.0;
    }

    // Last-chance bin: strongly favor using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 30.0;
    }

    // Prefer filling bins that are already quite full relative to the mean residual.
    let residual_gap = mean_residual - bin_residual as f64;
    score -= residual_gap * 0.4;

    // Mild penalty for spreading across many open bins when this bin is still large.
    let fill_ratio = 1.0 - bin_residual as f64 / bin_capacity as f64;
    if fill_ratio < 0.3 {
        score += open_bins_count as f64 * 0.6;
    }

    // Time horizon: early in the stream, allow opening bins more freely;
    // late in the stream, strongly prefer using existing bins.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score *= 1.0 - 0.25 * progress;
    if bin_residual == bin_capacity {
        // New-bin candidate: acceptable early, penalized late.
        score += 45.0 * (1.0 - progress) - 20.0 * progress;
        // Avoid opening a new bin if the item fits snugly somewhere else.
        if post_residual < 15 && bin_residual == bin_capacity {
            score += 30.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;
    let is_new_bin = (bin_residual as f64 - cap).abs() < 1e-9;
    let item = item_size as f64;
    let nxt = next_item_size as f64;

    // Base: prefer small post residual (tight fit)
    let mut score = pr;

    // Non-linear tight-fit reward: quadratic coupling of post residual with progress
    score -= (1.0 - norm_pr) * (1.0 - norm_pr) * 30.0 * (0.5 + progress);

    // Dead-space penalty: penalize small unusable residuals (smoothly)
    let dead = 1.0 - (pr / 12.0).min(1.0);
    score += dead * dead * 25.0 * (1.0 - progress * 0.5);

    // Lookahead coupling: reward residuals that can host the next item
    if nxt > 0.0 && nxt <= pr {
        let slack = (pr - nxt) / cap;
        score -= 20.0 * (1.0 - slack) * (0.4 + 0.6 * progress);
    } else if nxt > 0.0 {
        score += 8.0 * (nxt - pr) / cap;
    }

    // Last-chance bonus: strongly favor using the only fitting bin
    if fitting_bins_count == 1 {
        score -= 35.0 * (1.0 + progress);
    }

    // New-bin candidate: penalize mildly, more when many bins are open or early stream
    if is_new_bin {
        score += 15.0 + 20.0 * (1.0 - progress) + open_bins_count as f64 * 2.0;
        // But if the item is huge and would leave tiny residual elsewhere, opening is fine
        if item / cap > 0.7 {
            score -= 25.0;
        }
    }

    // Mean-residual coupling: prefer bins whose residual is below mean (concentrate waste)
    let dev = (bin_residual as f64 - mean_residual) / cap;
    score += 10.0 * dev * dev * (dev.signum() * 0.5 + 0.5);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap_f = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Perfect / near-perfect fits are strongly rewarded
    if post_residual == 0 {
        score -= 1100.0;
    } else if post_residual <= 3 {
        score -= 480.0;
    } else if post_residual <= 12 {
        score -= 90.0;
    } else if post_residual < 20 {
        score += 16.0;
    } else if post_residual < 30 {
        score += 16.0 + (30 - post_residual) as f64 * 0.55;
    }

    // Lookahead: exact next-item match is excellent
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 850.0;
        } else if next_item_size <= post_residual {
            let post2 = post_residual - next_item_size;
            score -= 120.0 - (post2 as f64) * 1.8;
            if post2 == 0 { score -= 90.0; }
            if post2 > 0 && post2 < 5 { score -= 25.0; }
            if post2 % 10 == 0 && post2 > 0 { score -= 22.0; }
            if post_residual % next_item_size == 0 { score -= 16.0; }
            if post_residual >= next_item_size * 2 && post_residual - next_item_size * 2 <= 4 { score -= 18.0; }
        } else {
            // next item won't fit here: penalize small dead gaps
            score += 18.0;
            if post_residual > 0 && post_residual < 15 { score += 40.0; }
            let gap = (next_item_size - post_residual) as f64;
            if gap <= 5.0 { score += (6.0 - gap) * 4.0; }
            if post_residual as f64 > mean_residual * 1.4 { score -= 10.0; }
        }
    }

    // NEW-BIN CANDIDATE branch: decide when opening a fresh bin beats a poor fit
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let avg_fill = 1.0 - (mean_residual / cap_f);
        score += 240.0 - avg_fill * 320.0 - progress * 60.0;
        if fitting_bins_count > 0 {
            score += (fitting_bins_count.min(5) as f64) * 8.0 + 18.0;
            let snug = item_size as f64 / (bin_residual.max(1) as f64);
            if snug > 0.9 { score += 35.0; }
            if snug > 0.95 { score += 25.0; }
        }
        let newbin_waste = (bin_capacity - item_size) as f64;
        if item_size >= bin_capacity * 3 / 4 { score -= 50.0; }
        if bin_capacity - item_size <= 4 { score -= 65.0; }
        if next_item_size > 0 && next_item_size <= bin_capacity - item_size { score -= 22.0; }
        if next_item_size > 0 && next_item_size >= bin_capacity / 2 { score -= 28.0; }
        if newbin_waste > 0.0 && (newbin_waste as u32) < next_item_size && newbin_waste < cap_f * 0.12 {
            score += 24.0;
        }
        if progress > 0.6 {
            let waste_tol = (1.0 - progress) * cap_f * 0.35;
            if newbin_waste > waste_tol && fitting_bins_count > 0 { score += 10.0 + progress * 20.0; }
        }
    } else {
        // Existing-bin branch: tightness and residual quality
        let tightness = 1.0 - (item_size as f64 / bin_residual.max(1) as f64);
        score += tightness * 80.0;
        score += (mean_residual - bin_residual as f64) * 1.4;

        let dead_ratio = post_residual as f64 / cap_f;
        if dead_ratio < 0.03 { score -= 35.0; }
        else if dead_ratio < 0.08 { score -= 12.0; }
        else if dead_ratio > 0.35 { score += 22.0; }
        else if dead_ratio > 0.25 { score += 9.0; }
        score += dead_ratio * 28.0;

        if post_residual > 0 && next_item_size > 0 && post_residual < next_item_size {
            let dead_frac = post_residual as f64 / cap_f;
            let unusable = (next_item_size - post_residual) > 12;
            if unusable { score += dead_frac * 85.0; }
            else { score -= 8.0; }
        }

        if item_size == bin_residual { score -= 40.0; }
        if post_residual > 0 && post_residual < 6 { score -= 20.0; }
        if post_residual > 0 && post_residual % 10 == 0 { score -= 9.0; }
        if post_residual > 0 && (post_residual as f64) < mean_residual * 0.25 { score -= 14.0; }
        if bin_residual as f64 > cap_f * 0.6 { score -= 10.0; }
        if fitting_bins_count == 1 && bin_residual < bin_capacity { score -= 22.0; }
        if fitting_bins_count <= 2 && post_residual > 0 { score -= 7.0; }

        let progress = step_index as f64 / total_items.max(1) as f64;
        if post_residual > 0 && next_item_size > 0 && post_residual >= next_item_size {
            let chain = post_residual / next_item_size;
            if chain >= 2 { score -= (chain.min(4) as f64) * 6.0; }
        }
        if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
            score += (1.0 - progress) * 12.0;
            let gap = (next_item_size - post_residual) as f64;
            if gap > mean_residual * 0.6 && fitting_bins_count > 2 { score += gap * 0.7; }
        }
    }

    // Compact when many bins are open
    score += open_bins_count as f64 * 0.6;
    score -= (item_size as f64 / cap_f) * 8.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: bucket by capacity/8 octants.
    let octant = (post_residual / (bin_capacity / 8)).min(7);
    // Dead-space penalty grows super-linearly for small residuals (hard-to-fill).
    match octant {
        0 => score += 60.0,                 // 0..12 : nearly dead
        1 => score += 25.0,                 // 12..25
        2 => score += 8.0,                  // 25..37
        3 => score += 0.0,                  // sweet zone
        4 => score += 0.0,
        5 => score -= 4.0,                  // roomy bins slightly favored
        6 => score -= 6.0,
        7 => score -= 8.0,
        _ => {}
    }

    // Perfect fit reward: post_residual divisible by small harmonic classes.
    if post_residual == 0 {
        score -= 100.0;
    } else if post_residual % 10 == 0 {
        score -= 12.0;
    } else if post_residual % 5 == 0 {
        score -= 5.0;
    } else if post_residual < 10 {
        score += 15.0; // sub-harmonic dead space
    }

    // Lookahead coupling: does next item fit in the resulting residual?
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            // Exact harmonic match with next item is gold.
            if next_item_size == post_residual {
                score -= 40.0;
            } else {
                score -= 10.0;
                // penalize leaving awkward gap after next placement
                let gap = post_residual - next_item_size;
                if gap < 10 { score += 10.0; }
            }
        } else {
            // next item won't fit here anyway; slight penalty for wasting lookahead
            score += 5.0;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 30.0;
    }

    // New-bin candidate handling: only attractive when current bins are fragmented
    // or the fit is terrible.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let fragmentation = (mean_residual - post_residual as f64).abs();
        // Fresh bin score ~ mid-range; open new bin if open bins are fragmented
        // or this item is large relative to typical residuals.
        score = 45.0
            + 25.0 * (1.0 - progress)
            - 20.0 * (mean_residual / bin_capacity as f64)
            + if item_size > 50 { 10.0 } else { 0.0 }
            + if open_bins_count == 0 { -100.0 } else { 0.0 }
            - if fragmentation > 30.0 { 0.0 } else { 15.0 };
    }

    // Mild tie-breaking toward tighter bins overall.
    score += (mean_residual - bin_residual as f64) * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap_f = bin_capacity as f64;
    let progress = step_index as f64 / total_items.max(1) as f64;
    let mut score = post_residual as f64;

    // Tiered dead-space avoidance (combined: stronger exact/near-exact rewards)
    if post_residual == 0 {
        score -= 900.0;
    } else if post_residual <= 3 {
        score -= 420.0;
    } else if post_residual <= 12 {
        score -= 80.0;
    } else if post_residual < 20 {
        score += 16.0;
    } else if post_residual < 30 {
        score += 16.0 + (30 - post_residual) as f64 * 0.6;
    }

    // Lookahead: exact and near-exact fits for the next item
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 700.0;
        } else if next_item_size <= post_residual {
            let post2 = post_residual - next_item_size;
            score -= 120.0 - (post2 as f64) * 2.0;
            if post2 == 0 { score -= 100.0; }
            if post2 > 0 && post2 < 5 { score -= 26.0; }
            if post2 % 10 == 0 && post2 > 0 { score -= 22.0; }
            if post2 > 0 && post2 <= next_item_size / 4 { score -= 10.0; }
            if post_residual % next_item_size == 0 { score -= 16.0; }
            if post_residual >= next_item_size * 2 && post_residual - next_item_size * 2 <= 4 {
                score -= 20.0;
            }
            let chain = post_residual / next_item_size;
            if chain >= 2 { score -= (chain.min(4)) as f64 * 6.0; }
        } else {
            // next item won't fit here: penalize near-miss gaps
            let gap = next_item_size - post_residual;
            if post_residual > 0 {
                if gap <= 3 { score += 38.0; }
                else if gap <= 8 { score += 13.0; }
                if (gap as f64) > mean_residual * 0.5 { score += 12.0; }
                if post_residual < 15 { score += 30.0; }
                score += (1.0 - progress) * 12.0;
            }
        }
    }

    // Compaction pressure scaled by open bins
    score += open_bins_count as f64 * 0.8;

    // Last-chance bin: strongly favor using it
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 50.0;
    }

    // Tightness via relative fill
    let snug = item_size as f64 / bin_residual.max(1) as f64;
    score += (1.0 - snug) * 60.0;

    // NEW-BIN CANDIDATE handling
    if bin_residual == bin_capacity {
        let avg_fill = 1.0 - (mean_residual / cap_f);
        score += 240.0 - avg_fill * 300.0 - progress * 65.0;
        let newbin_waste = (bin_capacity - item_size) as f64;
        if item_size as f64 / cap_f > 0.75 { score -= 55.0; }
        if item_size >= bin_capacity * 3 / 4 { score -= 55.0; }
        if item_size as f64 > mean_residual { score -= 35.0; }
        if newbin_waste < mean_residual * 0.5 { score -= 32.0; }
        if bin_capacity - item_size <= 4 { score -= 70.0; }
        if next_item_size > 0 && (bin_capacity - item_size) >= next_item_size
            && (bin_capacity - item_size) - next_item_size <= 6 {
            score -= 38.0;
        }
        if next_item_size > 0 {
            let leftover = bin_capacity - item_size;
            if leftover >= next_item_size {
                let tail = leftover % next_item_size;
                if tail == 0 { score -= 18.0; }
                else if tail <= 4 { score -= 12.0; }
            }
        }
        if fitting_bins_count > 3 {
            score += (fitting_bins_count.min(6) as f64) * 8.0;
            if item_size as f64 / cap_f < 0.5 { score += 30.0; }
        }
        if fitting_bins_count > 0 {
            let best_alt = if item_size <= mean_residual as u32 { mean_residual - item_size as f64 } else { mean_residual };
            if newbin_waste > best_alt + cap_f * 0.08 { score += 22.0; }
        }
        if progress > 0.6 {
            let waste_tol = (1.0 - progress) * cap_f * 0.35;
            if newbin_waste > waste_tol && fitting_bins_count > 0 {
                score += 10.0 + progress * 22.0;
            }
        }
        if newbin_waste > 0.0 && (newbin_waste as u32) < next_item_size && newbin_waste < cap_f * 0.12 {
            score += 26.0;
        }
        if progress < 0.1 { score -= 5.0; }
    } else {
        // Prefer bins whose residual is below average (consolidating slack)
        score += (mean_residual - bin_residual as f64) * 1.3;
        let dead_ratio = post_residual as f64 / cap_f;
        if dead_ratio < 0.03 { score -= 38.0; }
        else if dead_ratio < 0.08 { score -= 14.0; }
        else if dead_ratio > 0.35 { score += 24.0; }
        else if dead_ratio > 0.25 { score += 10.0; }
        if item_size == bin_residual { score -= 45.0; }
        if snug > 0.97 && post_residual >= next_item_size && next_item_size > 0 { score -= 16.0; }
        if post_residual > 0 && (post_residual as f64) < mean_residual * 0.25 { score -= 15.0; }
        if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size as u32 {
            let wasted = next_item_size as f64 - post_residual as f64;
            score += wasted * 0.6;
            if wasted > 12.0 { score += dead_ratio * 60.0; }
        }
        if next_item_size > 0 && post_residual >= next_item_size && (post_residual as f64) < mean_residual * 0.7 {
            score -= 6.0;
        }
        if post_residual > 0 && post_residual < 6 { score -= 20.0; }
        if post_residual > 0 && post_residual % 10 == 0 { score -= 8.0; }
        if fitting_bins_count <= 2 && post_residual > 0 { score -= 8.0; }
        if next_item_size > 0 && post_residual > 0 && post_residual >= next_item_size {
            let slack = post_residual - next_item_size;
            if slack > 0 && (slack as f64) < cap_f * 0.02 { score -= 14.0; }
        }
    }

    if progress < 0.1 { score += 3.0; }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals in the "unusable" band
    // (too small for the smallest plausible future item) are heavily penalized.
    let dead_threshold = 10.0f64;
    if (post_residual as f64) < dead_threshold && post_residual > 0 {
        score += (dead_threshold - post_residual as f64) * 12.0;
    }

    // Reward near-perfect fits (small but not zero post_residual).
    if post_residual <= 5 {
        score -= 15.0;
    }

    // Tightness ratio: the smaller the item relative to residual, the
    // more wasteful the placement in an already-open bin.
    let tightness = item_size as f64 / bin_residual.max(1) as f64;
    score -= tightness * 20.0;

    // Open-bin pressure: discourage scattering across many open bins
    // when few bins can fit the item; encourage consolidation.
    score += open_bins_count as f64 * 1.5;

    // Last-chance bin: strongly favor using the only bin that fits,
    // avoiding a pointless new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate handling: only attractive when the item is large
    // relative to typical open residuals or all open bins are poor fits.
    if bin_residual == bin_capacity {
        let mean_gap = mean_residual - item_size as f64;
        if mean_gap >= 0.0 && mean_gap < 15.0 {
            score += 40.0; // open bins fit reasonably well; avoid new bin
        } else {
            score -= 25.0; // poor fits elsewhere; prefer fresh bin
        }
    }

    // Lookahead: if the next item would fit snugly into the resulting
    // residual, reward this placement; if next item is bigger than the
    // residual, penalize leaving exactly an unusable gap.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 25.0;
        } else if next_item_size > post_residual {
            score += (next_item_size - post_residual) as f64 * 0.5;
        } else {
            score -= (post_residual - next_item_size) as f64 * 0.3;
        }
    }

    // Late-stream consolidation: as the stream progresses, prefer filling
    // existing bins over opening new ones.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual != bin_capacity {
        score -= progress * 10.0;
    } else {
        score += progress * 10.0;
    }

    // Mild penalty for deviating far from the mean residual: keep bin
    // residual profiles homogeneous for easier future packing.
    score += ((post_residual as f64) - mean_residual).abs() * 0.2;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // 2-step lookahead: reward bins whose post_residual can host the next item.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if (post_residual as f64) >= nxt {
            // reward proportional to how well the next item fits the leftover
            let slack_after_next = post_residual as f64 - nxt;
            score -= 18.0 * (1.0 - slack_after_next / bin_capacity as f64);
        } else {
            // dead space penalty: next item cannot use the leftover
            score += 6.0 * (1.0 - post_residual as f64 / bin_capacity as f64);
        }
    }

    // Relative-to-mean residual: prefer bins tighter than the mean (best-fit flavor).
    score -= 0.8 * (mean_residual - post_residual as f64);

    // Last chance: if this is the only bin that fits, strongly favor using it
    // to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate: penalize opening a new bin unless it yields a very
    // tight fit (large item, tiny post_residual).
    if bin_residual == bin_capacity {
        score += 30.0;
        if item_size >= 90 {
            score -= 35.0; // near-full utilization of a fresh bin
        }
    }

    // Mild preference for using existing bins as stream progresses.
    score += 0.02 * (open_bins_count as f64);

    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 25.0;
    }

    score
}

