pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap_f = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Perfect fit: extremely strong reward.
    if post_residual == 0 {
        score -= 1180.0;
    } else if post_residual <= 3 {
        score -= 500.0;
    } else if post_residual <= 12 {
        score -= 98.0;
    } else if post_residual < 20 {
        score += 18.0;
    } else if post_residual < 30 {
        score += 18.0 + (30 - post_residual) as f64 * 0.6;
    }

    // Lookahead on next item.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 900.0;
        } else if next_item_size <= post_residual {
            let post2 = post_residual - next_item_size;
            score -= 135.0 - (post2 as f64) * 2.0;
            if post2 % 10 == 0 && post2 > 0 { score -= 28.0; }
            if post2 == 0 { score -= 110.0; }
            if post2 >= 20 && post2 % 5 == 0 { score -= 12.0; }
            if post2 > 0 && post2 < 5 { score -= 28.0; }
            if post_residual >= next_item_size * 2 && post_residual - next_item_size * 2 <= 4 { score -= 20.0; }
            if post_residual % next_item_size == 0 { score -= 18.0; }
            if post2 > 0 && post2 <= 2 { score -= 14.0; }
            if post2 > 0 && post2 <= next_item_size / 4 { score -= 10.0; }
            if post2 > 0 && post2 <= next_item_size / 2 && post2 > next_item_size / 4 { score -= 4.0; }
            let chain = post_residual / next_item_size;
            if chain >= 2 { score -= (chain.min(4)) as f64 * 6.0; }
        } else {
            score += 20.0;
            if post_residual % 10 == 0 { score -= 15.0; }
            if post_residual > 0 && post_residual < 15 { score += 45.0; }
            if post_residual > 0 && (next_item_size - post_residual) <= 3 { score += 35.0; }
            let gap = next_item_size as f64 - post_residual as f64;
            if gap > 0.0 && gap <= 8.0 { score += 12.0; }
            if post_residual as f64 > mean_residual * 1.4 { score -= 12.0; }
            if post_residual > 0 && post_residual < next_item_size {
                score += gap * 0.6;
                if gap > mean_residual * 0.6 && fitting_bins_count > 2 { score += gap * 0.8; }
            }
        }
    }

    // Last-chance bin.
    if fitting_bins_count == 1 { score -= 25.0; }
    if fitting_bins_count > 1 { score += 2.0 * (fitting_bins_count as f64 - 1.0); }

    let progress = if total_items > 0 { step_index as f64 / total_items.max(1) as f64 } else { 0.0 };
    score -= 8.0 * progress * (mean_residual / cap_f);

    if open_bins_count > 3 && mean_residual > item_size as f64 {
        score += 0.05 * open_bins_count as f64;
    }

    // New-bin candidate handling.
    if bin_residual == bin_capacity {
        let avg_fill = 1.0 - (mean_residual / cap_f);
        score += 250.0 - avg_fill * 330.0 - progress * 65.0;
        let newbin_waste = (bin_capacity - item_size) as f64;
        if item_size as f64 > mean_residual { score -= 45.0; }
        if fitting_bins_count > 0 {
            score += (fitting_bins_count as f64).min(5.0) * 9.0 + 20.0;
            let snug = item_size as f64 / bin_residual.max(1) as f64;
            if snug > 0.9 { score += 40.0; }
            if snug > 0.95 { score += 28.0; }
            if snug > 0.98 { score += 18.0; }
        }
        if next_item_size > 0 && next_item_size >= bin_capacity / 2 { score -= 32.0; }
        if item_size >= bin_capacity * 3 / 4 { score -= 55.0; }
        if next_item_size > 0 && next_item_size <= bin_capacity - item_size { score -= 25.0; }
        if bin_capacity - item_size <= 4 { score -= 70.0; }
        if next_item_size > 0 {
            let leftover = bin_capacity - item_size;
            if leftover >= next_item_size {
                let tail = leftover % next_item_size;
                if tail <= 4 { score -= 16.0; }
                if tail == 0 { score -= 10.0; }
                if leftover >= next_item_size * 2 { score -= 14.0; }
            }
            if leftover < next_item_size && leftover < 10 { score += 18.0; }
        }
        if newbin_waste > 0.0 && newbin_waste < mean_residual * 0.6 { score -= 30.0; }
        if fitting_bins_count > 0 {
            let best_alt = if item_size as f64 <= mean_residual { mean_residual - item_size as f64 } else { mean_residual };
            if newbin_waste > best_alt + cap_f * 0.08 { score += 22.0; }
            if newbin_waste > best_alt + cap_f * 0.2 { score += 14.0; }
        }
        if progress > 0.75 && newbin_waste > cap_f * 0.5 { score += 12.0; }
        if progress > 0.6 {
            let waste_tol = (1.0 - progress) * cap_f * 0.35;
            if newbin_waste > waste_tol && fitting_bins_count > 0 { score += 10.0 + progress * 22.0; }
        }
        if newbin_waste > 0.0 && (newbin_waste as u32) < next_item_size && newbin_waste < cap_f * 0.12 { score += 26.0; }
        if next_item_size > 0 && newbin_waste > 0.0 && (newbin_waste as u32) % next_item_size == 0 && newbin_waste >= next_item_size as f64 { score -= 20.0; }
    } else {
        // Existing-bin refinements.
        let tightness = 1.0 - (item_size as f64 / bin_residual.max(1) as f64);
        score += tightness * 85.0;
        score += (mean_residual - bin_residual as f64) * 1.5;
        if post_residual > 0 && next_item_size > 0 && post_residual >= next_item_size {
            score -= 18.0;
            if post_residual <= next_item_size + 4 { score -= 22.0; }
        }
        let dead_ratio = post_residual as f64 / cap_f;
        if dead_ratio < 0.03 { score -= 38.0; }
        else if dead_ratio < 0.08 { score -= 14.0; }
        else if dead_ratio > 0.35 { score += 24.0; }
        else if dead_ratio > 0.25 { score += 10.0; }
        score += dead_ratio * 30.0;
        if item_size == bin_residual { score -= 45.0; }
        if post_residual > 0 && post_residual < 6 { score -= 22.0; }
        if post_residual > 0 && (post_residual as f64) < mean_residual * 0.25 { score -= 15.0; }
        if post_residual > 0 && next_item_size > 0 && post_residual >= next_item_size && (post_residual as f64) < mean_residual * 0.7 { score -= 6.0; }
        if post_residual > 0 && next_item_size > 0 {
            let unusable = post_residual < next_item_size && (next_item_size - post_residual) > 12;
            if unusable { score += dead_ratio * 90.0; }
            else {
                let reuse = (post_residual / next_item_size) as f64 * (next_item_size as f64 / cap_f);
                score -= reuse * 22.0;
            }
        }
        if post_residual > 0 && item_size as f64 / bin_residual.max(1) as f64 > 0.97 && post_residual >= next_item_size { score -= 16.0; }
        if post_residual > 0 && fitting_bins_count == 1 { score -= 6.0; }
        if post_residual > 0 && (post_residual as f64 - mean_residual).abs() < cap_f * 0.03 { score -= 9.0; }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let norm_pr = pr / cap;

    // Base: quadratic penalty on post-residual (dead space), with cubic smoothing
    let mut score = pr
        + 40.0 * norm_pr * norm_pr
        - 30.0 * norm_pr * norm_pr * norm_pr;

    // Reward tight fits: smooth coupling between post_residual and item size
    let fill_ratio = 1.0 - norm_pr;
    score -= 25.0 * fill_ratio * fill_ratio;

    // Lookahead: reward if next item fits the post-residual (smooth compatibility)
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        let fits = (pr - nx).max(0.0) / cap;
        let compat = 1.0 - (pr - nx).abs() / cap;
        score -= 15.0 * compat.max(0.0) * (1.0 - fits);
    }

    // Late-stream pressure: prefer consolidating into open bins as stream progresses
    score -= 20.0 * progress * fill_ratio;

    // Last-chance bin: strong reward to avoid opening a new bin unnecessarily
    if fitting_bins_count == 1 {
        score -= 35.0 * (1.0 - progress);
    }

    // Many open bins: slight penalty for spreading, reward consolidation
    score += 0.5 * (open_bins_count as f64).ln().max(0.0);

    // Penalize bins far from mean residual (smooth dispersion term)
    score += 0.1 * (pr - mean_residual).abs();

    // New-bin candidate: penalize mildly unless current bin residual is unusable
    if bin_residual == bin_capacity {
        score += 20.0 * (1.0 - progress) - 5.0 * progress;
        if norm_pr < (next_item_size as f64 / cap).max(0.0) && next_item_size > 0 {
            score += 10.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic classes: partition residual space into deciles of capacity.
    let residual_class = post_residual / (bin_capacity / 10).max(1);
    let next_class = if next_item_size > 0 { next_item_size / (bin_capacity / 10).max(1) } else { 0 };

    // Reward when next item's class matches residual class (perfect harmonic fit).
    if next_item_size > 0 && post_residual >= next_item_size {
        let diff = (post_residual as i64 - next_item_size as i64).unsigned_abs() as f64;
        score -= 12.0 * (1.0 - diff / cap);
        // Exact modulo match bonus
        if post_residual % next_item_size.max(1) == 0 {
            score -= 6.0;
        }
    } else if next_item_size > 0 && post_residual < next_item_size {
        // Dead space relative to lookahead: penalize proportionally to wasted class gap
        score += 4.0 + 0.35 * (next_item_size - post_residual) as f64;
    }

    // Integer-division thresholds: penalize leaving residuals in awkward small classes
    match residual_class {
        0 => score -= 8.0,           // near-perfect fill
        1 => score -= 3.0,           // good
        2 | 3 => { score += 1.0; }   // awkward middle-small
        _ => {}                      // large residual is fine
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 15.0;
    }

    // Many open bins: prefer consolidating into fuller bins
    score += 0.05 * open_bins_count as f64 * (post_residual as f64 / cap);

    // Late in stream: tighten packing, prefer minimal post_residual
    let progress = step_index as f64 / total_items.max(1) as f64;
    score *= 1.0 + 0.5 * progress;

    // New-bin candidate: only attractive when no open bin fits well
    if bin_residual == bin_capacity {
        let scarcity = if fitting_bins_count == 0 { 20.0 } else { 2.0 };
        score += scarcity + 0.1 * open_bins_count as f64;
        if next_item_size > item_size {
            score -= 5.0; // big item coming, fresh bin useful
        }
    }

    // Mean-residual coupling: penalize bins far below mean residual (fragmented)
    score += 0.3 * (mean_residual - post_residual as f64).abs() / cap;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
