pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: post_residuals that are too small to hold
    // even the smallest plausible future item are "dead space". Penalize them
    // super-linearly, but only when they are truly unusable.
    let dead_threshold = 12u32; // smallest practical future item footprint
    if post_residual > 0 && post_residual < dead_threshold {
        score += (dead_threshold - post_residual) as f64 * 8.0;
    }

    // Perfect-ish fit reward: very small post_residual (but usable) is great.
    if post_residual <= 3 {
        score -= 15.0;
    }

    // Reward bins whose residual closely matches the item (tight packing).
    let tightness = (bin_residual as f64 - item_size as f64).abs();
    score -= (bin_capacity as f64 - tightness) * 0.25;

    // If this is the ONLY bin that can fit the item, strongly favor using it
    // (last chance before opening a new bin).
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 20.0;
    }

    // Lookahead coupling: if the next item would fit in the post-residual,
    // this placement preserves a useful chain; reward it.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 6.0;
    } else if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        // post-residual too small for the next item: mild penalty if it becomes dead space
        if post_residual < dead_threshold {
            score += 4.0;
        }
    }

    // Open-bin pressure: with many open bins, prefer consolidating into
    // existing bins (penalize opening new bins implicitly by favoring fills).
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += open_bins_count as f64 * 0.15 * (0.5 + progress);

    // Mean-residual coupling: if this bin's residual is far below the mean,
    // it is already "cramped" — finishing it off is good (reward low residual).
    score -= (mean_residual - bin_residual as f64) * 0.1;

    // New-bin candidate handling: an empty bin has bin_residual == bin_capacity.
    // Only prefer it when no open bin fits well (large residual gap) or the
    // item is huge relative to capacity. Otherwise make it unattractive.
    if bin_residual == bin_capacity {
        let huge_item = item_size as f64 > 0.85 * bin_capacity as f64;
        let poor_alternatives = fitting_bins_count == 0 || (fitting_bins_count == 1 && (bin_residual - item_size) > bin_capacity / 2);
        if huge_item || poor_alternatives {
            score -= 10.0;
        } else {
            score += 25.0 + open_bins_count as f64 * 0.5;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: less waste relative to capacity.
    score -= 0.5 * (bin_capacity as f64 - post_residual as f64);

    // Aggressive 2-step lookahead: reward if next item exactly fills post_residual.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 60.0; // perfect chaining
        } else if next_item_size <= post_residual {
            // next item fits: reward proportional closeness
            let gap = (post_residual - next_item_size) as f64;
            score -= 30.0 * (1.0 - gap / bin_capacity as f64);
        } else {
            // next item does NOT fit here: penalize, worse if gap is small (dead space)
            let gap = (next_item_size - post_residual) as f64;
            score += 10.0 + 0.5 * gap;
        }
    }

    // Penalize leaving residuals that are likely unusable dead space (small, odd residuals).
    if post_residual > 0 && post_residual < 10 {
        score += 15.0;
    }

    // Compare against mean residual: prefer bins whose post residual stays near/below mean.
    score += 0.3 * (post_residual as f64 - mean_residual);

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate: penalize opening a new bin unless current bin would leave large waste
    // and the next item is large.
    if bin_residual == bin_capacity {
        score += 40.0;
        if next_item_size > 0 && post_residual >= next_item_size {
            score -= 20.0; // fresh bin is a good match for the next item
        }
        // Late in stream, avoid opening bins too eagerly.
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score += 20.0 * progress;
    }

    // Mild penalty for many open bins: prefer consolidation.
    score += 0.2 * open_bins_count as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
