pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let item = item_size as f64;
    let mut score = post;

    // Perfect fit reward
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Tightness reward: fraction of bin consumed by this placement
    let fill_ratio = item / cap;
    score -= 40.0 * fill_ratio;

    // Lookahead: residual reusable by next item is good; stranded residual is bad
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        if post_residual >= next_item_size {
            // next item fits into leftover: reward proportionally to how snugly
            let snug = 1.0 - ((post - nx) / cap);
            score -= 25.0 * snug;
        } else {
            // dead space: penalize small leftovers that nothing can use
            let dead = post / cap;
            if post < 10.0 {
                score += 30.0 * (1.0 - dead);
            } else {
                score += 8.0 * dead;
            }
        }
    }

    // Last-chance bin: avoid opening a new bin when this is the only fit
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 60.0;
    }

    // New-bin candidate handling
    if bin_residual == bin_capacity {
        // Prefer new bin when existing bins are crowded (few fitting bins)
        // and item is large; otherwise penalize opening bins wastefully.
        let scarcity = if fitting_bins_count == 0 { 1.0 } else { 1.0 / (fitting_bins_count as f64) };
        let big_item = (item - 10.0) / 90.0;
        let late = step_index as f64 / (total_items.max(1) as f64);
        score -= 70.0 * scarcity * (0.5 + 0.5 * big_item) * (0.6 + 0.4 * late);
        // But never open a new bin for a tiny item when mean residual is large
        if mean_residual > item + 20.0 && fitting_bins_count > 0 {
            score += 120.0;
        }
    }

    // Global state: many open bins with high mean residual -> consolidate,
    // favor bins below mean residual (tighter bins)
    if open_bins_count > 1 {
        let rel = (mean_residual - bin_residual as f64) / cap;
        score -= 10.0 * rel.clamp(-1.0, 1.0);
    }

    // Mild pressure to close bins early in the stream
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= 15.0 * (1.0 - progress) * (1.0 - post / cap);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let mut score = post_residual as f64;

    // Non-linear waste penalty: quadratic coupling of post_residual with capacity fraction
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    score += 0.6 * (pr / cap) * (pr / cap) * cap;

    // Reward tight fits more strongly as stream progresses
    let tightness = 1.0 - (pr / cap);
    score -= (1.0 + 2.0 * progress) * tightness * tightness * 8.0;

    // Lookahead: reward if next item fits the post residual exactly-ish
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        let gap = (pr - nxt).abs();
        if pr >= nxt {
            score -= 6.0 * (1.0 - gap / cap);
        } else {
            score += 0.25 * gap;
        }
    }

    // Penalize fragmenting bins relative to mean residual (smooth coupling)
    let dev = (pr - mean_residual) / cap;
    score += 1.5 * dev * dev * cap;

    // Last-chance bonus: if this is the only fitting bin, strongly prefer using it
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 15.0 * (1.0 + progress);
    }

    // New-bin candidate: penalize mildly early, more strongly when open bins are fragmented
    if bin_residual == bin_capacity {
        let openness = (open_bins_count as f64).ln_1p();
        score += 10.0 + 5.0 * (1.0 - progress) + 3.0 * openness;
        // But allow new bin if residuals are all tiny (nothing fits well)
        if mean_residual < 0.15 * cap {
            score -= 12.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: which capacity-fraction bucket it lands in.
    // Buckets: 0 (perfect), 1..=10 (tiny), 11..=25 (small), 26..=50 (medium), >50 (large).
    let pr = post_residual;
    let class: f64 = if pr == 0 {
        -60.0
    } else if pr <= 10 {
        -25.0
    } else if pr <= 25 {
        -5.0
    } else if pr <= 50 {
        8.0
    } else {
        20.0
    };
    score += class;

    // Modulo arithmetic: residual divisible by small item classes is "reusable".
    // A residual that is a multiple of 10 is more likely reusable by typical items.
    let mod10 = pr % 10;
    score -= (10 - mod10.min(10 - mod10)) as f64 * 0.6; // distance to nearest multiple of 10

    // Integer-division threshold: residual / next_item_size — can the next item also fit?
    if next_item_size > 0 && next_item_size <= pr {
        // next item fits: reward, stronger if it leaves another reusable remainder
        let nr = pr - next_item_size;
        let bonus = if nr == 0 { 18.0 } else if nr <= 15 { 10.0 } else { 3.0 };
        score -= bonus;
    } else if next_item_size > 0 {
        // next item would not fit here: this residual is dead space for lookahead
        score += 6.0 + (next_item_size - pr) as f64 * 0.15;
    }

    // Last-chance dynamics: if this is the only fitting bin, avoid opening a new bin
    // unless the resulting residual is truly terrible.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 12.0;
        if pr <= 30 {
            score -= 6.0; // still leaves a decent small-item slot
        }
    }

    // New-bin candidate handling: an empty bin has huge residual; make it attractive
    // only when open bins are nearly full / crowded.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64).max(1.0);
        let pressure = mean_residual / cap;
        // open new bin when existing bins are fragmented (low mean residual) or crowded
        let open_bonus = (open_bins_count as f64).min(10.0) * 1.5;
        score = 100.0 - pressure * 20.0 - open_bonus * (0.5 + 0.5 * progress) + (next_item_size as f64) * 0.1;
        if fitting_bins_count == 0 {
            score -= 200.0; // must open a new bin
        }
    }

    // Tight-fit reward: item fills most of the bin
    let fill = item_size as f64 / bin_residual as f64;
    score -= fill * 8.0;

    // Late-stream conservatism: prefer consolidating as stream ends
    let progress = step_index as f64 / (total_items.max(1) as f64).max(1.0);
    score += (1.0 - progress) * 2.0 - progress * 3.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Dead-space avoidance: residuals too small for the smallest plausible
    // future item are pure waste — penalize them heavily.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    } else if post_residual >= 10 && post_residual < 25 {
        score += 18.0;
    } else if post_residual == 0 {
        // Perfect fit: strong reward.
        score -= 40.0;
    }

    // Reward bins whose residual exactly accommodates the lookahead item
    // (k=2 lookahead synergy).
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 25.0;
    } else if next_item_size > 0 && post_residual > next_item_size && post_residual < next_item_size + 10 {
        // Residual just above next item: good but not perfect.
        score -= 8.0;
    }

    // Tight fit reward: fraction of bin consumed by this placement.
    let fill_ratio = item_size as f64 / bin_capacity as f64;
    score -= 15.0 * fill_ratio;

    // Last-chance pressure: if this is the only bin that fits, prefer using it
    // over opening a new bin (penalize the new-bin alternative implicitly by
    // rewarding this bin).
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // New-bin candidate: penalize opening a new bin, especially when many
    // bins are already open and mean residual is still usable.
    if bin_residual == bin_capacity {
        score += 12.0 + 2.5 * open_bins_count as f64;
        if mean_residual >= item_size as f64 {
            score += 15.0; // an open bin could take it; new bin is wasteful
        }
        // Late in the stream, avoid leaving many near-empty bins.
        let progress = step_index as f64 / (total_items as f64).max(1.0);
        score += 10.0 * progress;
    } else {
        // Open-bin pressure: with many open bins, prefer filling existing ones
        // (higher residual bins get slight penalty so fullest-fit wins).
        score += 0.05 * open_bins_count as f64;
        // Prefer bins with smaller residual (best-fit bias) modulated by mean.
        score += 0.1 * (bin_residual as f64 - mean_residual);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
