pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tight fit reward: strongly favor bins where the item fills most of the residual.
    let fill_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 30.0 * fill_ratio * fill_ratio;

    // Perfect fit: huge reward when post residual is tiny.
    if post_residual < 10 {
        score -= 25.0;
    }

    // Lookahead: reward if the next item can still fit in the post residual.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            // chain fit is good, but only mildly — we want tight packing now
            score -= 8.0 * (next_item_size as f64 / bin_capacity as f64);
        } else {
            // penalize leaving a gap that the next item cannot use (dead space)
            let gap = post_residual as f64;
            score += 0.3 * gap;
        }
    }

    // Last-chance bonus: if this is the only bin that fits, strongly prefer it
    // over opening a new bin — unless the fit is terrible.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        let waste = post_residual as f64;
        if waste < 40.0 {
            score -= 20.0;
        } else {
            // even last chance shouldn't absorb a huge item leaving huge waste
            score += 0.2 * (waste - 40.0);
        }
    }

    // New-bin candidate handling: opening a new bin is only attractive when
    // existing residuals are poorly matched to the item, or many bins exist
    // and the stream is early (diversification).
    if bin_residual == bin_capacity {
        // baseline cost of a fresh bin: its full residual
        score = bin_capacity as f64;
        let progress = step_index as f64 / total_items.max(1) as f64;
        // if mean residual across open bins is small relative to item, new bin is good
        let mismatch = item_size as f64 - mean_residual;
        if mismatch > 0.0 {
            score -= 15.0 * mismatch / bin_capacity as f64;
        }
        // early in stream, allow more open bins to give future items options
        score -= 10.0 * (1.0 - progress);
        // if no other bin even fits, new bin is the fallback — make it neutral
        if fitting_bins_count == 0 {
            score -= 1000.0;
        }
    } else {
        // penalize using bins whose residual deviates wildly from the mean
        let dev = (bin_residual as f64 - mean_residual).abs();
        score += 0.05 * dev;
        // slight preference for bins with larger residual when open bins are few
        // (keeps small bins available for small items)
        if open_bins_count < 4 {
            score += 0.05 * post_residual as f64;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap_f = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Tiered dead-space avoidance (combined: strong perfect-fit + graded tiers)
    if post_residual == 0 {
        score -= 900.0;
    } else if post_residual <= 3 {
        score -= 420.0;
    } else if post_residual <= 12 {
        score -= 90.0;
    } else if post_residual < 20 {
        score += 14.0;
    } else if post_residual < 30 {
        score += 10.0 + (30 - post_residual) as f64 * 0.6;
    }

    // Lookahead: exact and near-exact fits for the next item
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 700.0;
        } else if next_item_size <= post_residual {
            let post2 = post_residual - next_item_size;
            score -= 100.0 - (post2 as f64) * 2.0;
            if post2 == 0 { score -= 90.0; }
            if post2 > 0 && post2 < 5 { score -= 26.0; }
            if post2 % 10 == 0 && post2 > 0 { score -= 20.0; }
            if post2 <= next_item_size / 4 { score -= 10.0; }
            if post_residual >= next_item_size * 2 && post_residual - next_item_size * 2 <= 4 {
                score -= 18.0;
            }
            let chain = post_residual / next_item_size;
            if chain >= 2 { score -= (chain.min(4)) as f64 * 6.0; }
            if post_residual % next_item_size == 0 { score -= 14.0; }
        } else {
            let gap = next_item_size - post_residual;
            if post_residual > 0 {
                if gap <= 3 { score += 35.0; }
                else if gap <= 8 { score += 12.0; }
                if (gap as f64) > mean_residual * 0.5 { score += 12.0; }
                if post_residual < 15 { score += 30.0; }
                if gap <= 5 { score += (6 - gap) as f64 * 4.0; }
            }
        }
    }

    // Compaction pressure scaled by open bins
    score += open_bins_count as f64 * 0.8;

    // Last-chance bin: strongly favor using it
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 45.0;
    }

    // Tightness via relative fill
    let snug = item_size as f64 / bin_residual.max(1) as f64;
    score -= snug * 40.0;
    if snug > 0.95 && bin_residual < bin_capacity { score -= 12.0; }

    // Dead-ratio shaping (borrowed from best)
    if bin_residual < bin_capacity {
        let dead_ratio = post_residual as f64 / cap_f;
        if dead_ratio < 0.03 { score -= 30.0; }
        else if dead_ratio < 0.08 { score -= 12.0; }
        else if dead_ratio > 0.35 { score += 22.0; }
        else if dead_ratio > 0.25 { score += 10.0; }
        score += (mean_residual - bin_residual as f64) * 1.2;
    }

    // NEW-BIN CANDIDATE handling
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let avg_fill = 1.0 - (mean_residual / cap_f);
        let newbin_waste = (bin_capacity - item_size) as f64;
        score += 230.0 - avg_fill * 300.0 - progress * 65.0;
        if item_size as f64 / cap_f > 0.75 { score -= 55.0; }
        if item_size >= bin_capacity * 3 / 4 { score -= 40.0; }
        if item_size as f64 > mean_residual { score -= 35.0; }
        if newbin_waste < mean_residual * 0.5 { score -= 30.0; }
        if bin_capacity - item_size <= 4 { score -= 60.0; }
        if next_item_size > 0 {
            let leftover = bin_capacity - item_size;
            if leftover >= next_item_size {
                let tail = leftover % next_item_size;
                if tail == 0 { score -= 24.0; }
                else if tail <= 4 { score -= 16.0; }
                if leftover >= next_item_size * 2 { score -= 14.0; }
                if leftover - next_item_size <= 6 { score -= 35.0; }
            }
            if leftover < next_item_size && leftover < 10 { score += 18.0; }
            if next_item_size >= bin_capacity / 2 { score -= 25.0; }
        }
        if fitting_bins_count > 0 {
            score += (fitting_bins_count.min(6) as f64) * 8.0 + 15.0;
        }
        if progress > 0.6 {
            let waste_tol = (1.0 - progress) * cap_f * 0.35;
            if newbin_waste > waste_tol && fitting_bins_count > 0 {
                score += 10.0 + progress * 22.0;
            }
        }
        if progress < 0.1 { score -= 5.0; }
    }

    // Mild progress-based diversity nudge for open bins
    let progress = step_index as f64 / total_items.max(1) as f64;
    if progress < 0.1 { score += 3.0; }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;

    // Base: penalize post residual, scaled non-linearly by stream progress.
    let mut score = pr * (1.0 + 0.8 * progress * progress);

    // Non-linear polynomial coupling: waste grows quadratically in residual fraction.
    let frac = pr / cap;
    score += 12.0 * frac * frac * cap * (0.5 + 0.5 * progress);

    // Reward tight fits strongly (small post_residual relative to item).
    let tightness = item_size as f64 / bin_residual.max(1) as f64;
    score -= 20.0 * tightness * tightness * (1.0 - progress);

    // Last-chance bonus: if this is the only fitting bin, strongly prefer using it.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // Lookahead: if next item fits exactly in post_residual, reward this placement.
    if next_item_size > 0 {
        let d = (post_residual as i64 - next_item_size as i64).abs() as f64;
        score -= 15.0 * (1.0 - d / cap).max(0.0);
    }

    // Prefer bins with residuals below mean (consolidate small leftovers).
    score += 0.3 * (bin_residual as f64 - mean_residual);

    // New-bin candidate: penalize mildly early, allow late when open bins are crowded.
    if bin_residual == bin_capacity {
        score += 8.0 - 6.0 * progress + 2.0 * open_bins_count as f64;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: modulo arithmetic on capacity fractions
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let frac = pr / cap; // fraction of capacity left after placement

    // Penalize dead space that is too small to be useful later (items >= 1)
    if post_residual > 0 && post_residual < 10 {
        score += 40.0;
    }

    // Harmonic thresholds: post_residual classes by integer division
    let class = post_residual / 10; // 0..10 classes
    score -= (class as f64) * 2.0; // reward larger usable residual classes

    // Perfect fit bonus (harmonic sweet spot)
    if post_residual == 0 {
        score -= 100.0;
    }
    // Near-perfect fits
    if post_residual == 1 || post_residual == 2 {
        score -= 30.0;
    }

    // Reward residual that matches next item size exactly (lookahead harmony)
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 50.0;
        } else if post_residual > next_item_size {
            score -= 5.0; // can still host next item
        } else {
            score += 10.0; // next item won't fit here
        }
        // modulo harmony: next item divides residual cleanly
        if next_item_size > 0 && post_residual % next_item_size == 0 && post_residual > 0 {
            score -= 8.0;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 60.0;
    }

    // New empty bin candidate: penalize unless current bin fit is poor
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items as f64).max(1.0);
        // base cost of opening a new bin
        score += 30.0 + 20.0 * (1.0 - progress);
        // if many bins fit the item, opening new bin is wasteful
        if fitting_bins_count > 1 {
            score += 50.0;
        }
        // if mean residual is large, open bins are underfilled: discourage new bin
        score += (mean_residual / cap) * 40.0;
        // if item is large relative to capacity, new bin keeps flexibility
        if (item_size as f64) / cap > 0.5 {
            score -= 25.0;
        }
    }

    // Tightness coupling: prefer bins where item fills a large share of residual
    let fill = (item_size as f64) / (bin_residual as f64).max(1.0);
    score -= fill * 15.0;

    // Mild penalty proportional to open bins (prefer consolidation)
    score += 0.5 * open_bins_count as f64;

    // Modulo-class coupling between item and post_residual
    let m = (item_size + post_residual) % 25;
    if m == 0 {
        score -= 6.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
