    }

    // Lookahead: if next item fits exactly in the post residual, reward this placement
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 35.0;
        } else if post_residual > next_item_size {
            score -= 8.0;
        }
    }

    // New-bin candidate handling: only attractive when open bins are crowded or fit is terrible
    if bin_residual == bin_capacity {
        let pressure = open_bins_count as f64 * 2.0;
        let waste = item_size as f64 / bin_capacity as f64;
        score = pressure + 20.0 * (1.0 - waste) + 10.0;
        if fitting_bins_count == 1 {
            score += 50.0; // don't abandon the only fitting bin
        }
        if post_residual == 0 {
            score -= 100.0; // item fills a fresh bin exactly
        }
    }

    // Late-stream consolidation: as stream progresses, prefer filling existing bins
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= progress * 10.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong reward for near-perfect fits (small dead space).
    if post_residual <= 5 {
        score -= 40.0;
    } else if post_residual <= 15 {
        score -= 15.0;
    }

    // Aggressive 2-step lookahead: reward if next item fits into post_residual.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 60.0; // perfect chaining
        } else if post_residual >= next_item_size {
            let slack = (post_residual - next_item_size) as f64;
            score -= 25.0 * (1.0 - slack / bin_capacity as f64);
        } else {
            // next item won't fit here; penalize leftover that is too large to be dead space
            let miss = (next_item_size - post_residual) as f64;
            score += 0.3 * miss;
        }
    }

    // Compare post_residual against mean residual: avoid creating outliers.
    score += 0.5 * (post_residual as f64 - mean_residual).abs();

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate: only attractive when no open bin fits well
    // (post_residual for empty bin = capacity - item_size).
    if bin_residual == bin_capacity {
        let waste = post_residual as f64;
        score += 10.0 + 0.5 * waste;
        // If many bins are open and this is a good fit for future items, allow it
        if next_item_size > 0 && post_residual >= next_item_size && open_bins_count == 0 {
            score -= 20.0;
        }
    }

    // Early in the stream, be slightly more willing to open fresh bins.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= 5.0 * (1.0 - progress);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tight fit reward: quadratic discount for small post-residual.
    let fit_ratio = post_residual as f64 / bin_capacity as f64;
    score -= (1.0 - fit_ratio) * (1.0 - fit_ratio) * 20.0;

    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 50.0;
    } else if post_residual <= 5 {
        score -= 25.0;
    }

    // Dead-space penalty: residuals too small for typical items (>=10).
    if post_residual > 0 && post_residual < 10 {
        score += 15.0;
    }

    // Lookahead: reward bins whose post-residual can host the next item.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 8.0;
        } else {
            score += 6.0;
        }
        // Chain fit: post_residual minus next item leaves room again.
        if post_residual >= next_item_size && post_residual - next_item_size >= 10 {
            score -= 5.0;
        }
    }

    // Last-chance bin: strongly prefer using the only bin that fits.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 30.0;
    }

    // Global state coupling: when many bins are open, discourage opening new ones.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    if bin_residual == bin_capacity {
        // New-bin candidate: base cost plus pressure from open bins and mean residual.
        score += 40.0 + 6.0 * open_bins_count as f64 + mean_residual * 0.3 - 20.0 * progress;
    } else {
        // Using an existing bin is generally good; reward spreading load evenly.
        score -= (mean_residual - bin_residual as f64).abs() * 0.2;
    }

    // Early stream: be more conservative, favor filling existing bins deeply.
    score -= (1.0 - progress) * (post_residual as f64 / bin_capacity as f64) * 5.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let mut score = pr;

    // Smooth non-linear coupling of post_residual with stream progress.
    let norm_pr = pr / cap; // 0..1
    let t = progress.clamp(0.0, 1.0);
    // Polynomial interaction: dead space penalized more as stream progresses.
    let progress_weight = 0.5 + 1.5 * t * t;
    score += progress_weight * 8.0 * norm_pr * norm_pr;

    // Reward tight fits with smooth quadratic decay from perfect fit.
    let fit_gap = (pr - next_item_size as f64).abs() / cap;
    if next_item_size > 0 {
        score -= 6.0 * (1.0 - 2.0 * fit_gap).max(-1.0) * (1.0 - t);
    }

    // Last-chance bonus: smooth sigmoid-like emphasis.
    if fitting_bins_count == 1 {
        score -= 10.0 * (1.0 - norm_pr);
    }

    // Mild penalty when bin residual deviates from mean residual (balance open bins).
    score += 0.05 * (pr - mean_residual).abs();

    // Encourage consolidating into fewer bins as open bins grow.
    score -= 0.3 * (open_bins_count as f64).ln().max(0.0) * (1.0 - norm_pr);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap_f = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Perfect and near-perfect fits are extremely valuable.
    if post_residual == 0 {
        score -= 1180.0;
    } else if post_residual <= 3 {
        score -= 500.0;
    } else if post_residual <= 12 {
        score -= 98.0;
    } else if post_residual < 20 {
        score += 18.0;
    } else if post_residual < 30 {
        score += 18.0 + (30 - post_residual) as f64 * 0.6;
    }

    // Lookahead: reward placements whose residual can host the next item.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 900.0;
        } else if next_item_size <= post_residual {
            let post2 = post_residual - next_item_size;
            score -= 135.0 - post2 as f64 * 2.0;
            if post2 == 0 {
                score -= 110.0;
            }
            if post2 > 0 && post2 < 5 {
                score -= 28.0;
            }
            if post2 >= 20 && post2 % 5 == 0 {
                score -= 12.0;
            }
            if post_residual % next_item_size == 0 {
                score -= 18.0;
            }
            if post_residual >= next_item_size * 2 && post_residual - next_item_size * 2 <= 4 {
                score -= 20.0;
            }
            let chain = post_residual / next_item_size;
            if chain >= 2 {
                score -= chain.min(4) as f64 * 6.0;
            }
        } else {
            // Next item blocked: penalize small residuals that become dead space.
            score += 20.0;
            if post_residual > 0 && post_residual < 15 {
                score += 45.0;
            }
            let gap = next_item_size as f64 - post_residual as f64;
            if gap <= 3.0 {
                score += 35.0;
            } else if gap <= 8.0 {
                score += 12.0;
            }
            if gap > mean_residual * 0.5 {
                score += 14.0;
            }
            if post_residual as f64 > mean_residual * 1.4 {
                score -= 12.0;
            }
        }
    }

    // Last-chance bin: strongly favor using it.
    if fitting_bins_count == 1 {
        score -= 25.0;
    } else if fitting_bins_count > 1 {
        score += 2.0 * (fitting_bins_count as f64 - 1.0).min(4.0);
    }

    // Dead-space ratio shaping for open bins.
    let dead_ratio = post_residual as f64 / cap_f;
    if post_residual > 0 {
        if dead_ratio < 0.03 {
            score -= 38.0;
        } else if dead_ratio < 0.08 {
            score -= 14.0;
        } else if dead_ratio > 0.35 {
            score += 24.0;
        } else if dead_ratio > 0.25 {
            score += 10.0;
        }
        score += dead_ratio * 30.0;
    }

    // Progress-scaled global pressure.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 8.0 * progress * (mean_residual / cap_f);

    // New-bin candidate handling.
    if bin_residual == bin_capacity {
        let avg_fill = 1.0 - mean_residual / cap_f;
        score += 250.0 - avg_fill * 330.0 - progress * 65.0;
        if fitting_bins_count > 0 {
            score += fitting_bins_count.min(5) as f64 * 9.0 + 20.0;
            let snug = item_size as f64 / bin_residual.max(1) as f64;
            if snug > 0.9 { score += 40.0; }
            if snug > 0.95 { score += 28.0; }
            if snug > 0.98 { score += 18.0; }
        }
        if item_size as f64 > mean_residual {
            score -= 45.0;
        }
        if next_item_size > 0 && next_item_size >= bin_capacity / 2 {
            score -= 32.0;
        }
        if item_size >= bin_capacity * 3 / 4 {
            score -= 55.0;
        }
        if bin_capacity - item_size <= 4 {
            score -= 70.0;
        }
        let leftover = (bin_capacity - item_size) as f64;
        if next_item_size > 0 && leftover >= next_item_size as f64 {
            let tail = leftover as u32 % next_item_size;
            if tail <= 4 { score -= 16.0; }
            if tail == 0 { score -= 10.0; }
        }
        if leftover > 0.0 && leftover < mean_residual * 0.6 {
            score -= 30.0;
        }
        if progress > 0.6 {
            let waste_tol = (1.0 - progress) * cap_f * 0.35;
            if leftover > waste_tol && fitting_bins_count > 0 {
                score += 10.0 + progress * 22.0;
            }
        }
        if leftover > 0.0 && (leftover as u32) < next_item_size && leftover < cap_f * 0.12 {
            score += 26.0;
        }
        if next_item_size > 0 && leftover > 0.0 && (leftover as u32) % next_item_size == 0 && leftover >= next_item_size as f64 {
            score -= 20.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of post-residual: residues near 0 are ideal.
    // Classify post_residual by integer division into capacity deciles.
    let decile = (post_residual * 10) / bin_capacity.max(1);
    let decile_penalty = match decile {
        0 => -30.0,               // near-perfect fill
        1 => -15.0,               // excellent
        2 => -6.0,
        3 => 0.0,
        4 => 5.0,
        5 => 10.0,                // half-empty bin: mediocre
        6 => 12.0,
        7 => 14.0,
        8 => 16.0,
        _ => 18.0,                // nearly untouched bin: wasteful placement
    };
    score += decile_penalty;

    // Exact-fit reward (modulo zero class)
    if post_residual == 0 {
        score -= 40.0;
    } else if post_residual % 10 == 0 {
        score -= 8.0; // residue in a "usable" harmonic class (multiple of 10)
    } else if post_residual < 10 {
        score += 6.0; // tiny dead space below min item size
    }

    // Lookahead coupling: does post_residual fit next item?
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            // slack that can host the next item is valuable
            let slack_ratio = next_item_size as f64 / post_residual as f64;
            score -= 12.0 * slack_ratio.min(1.0);
        } else {
            // this placement kills the bin for the lookahead item
            score += 10.0;
            // extra penalty if next item would have fit before placement
            if bin_residual >= next_item_size && post_residual < next_item_size {
                score += 8.0;
            }
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate handling: keep it neutral-slightly-high so it is
    // chosen only when all open bins look bad.
    if bin_residual == bin_capacity {
        score = 55.0 + (post_residual as f64);
        // early in stream, opening bins is cheap
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score -= 15.0 * (1.0 - progress);
        // if many bins already open, discourage spreading
        score += 2.0 * open_bins_count as f64;
    }

    // Prefer bins tighter than average (best-fit flavor)
    score += 0.3 * (mean_residual - bin_residual as f64);

    // Mild progression scaling: be greedier (tighter fits) later in stream
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += 5.0 * progress * (post_residual as f64 / cap);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: gaps too small for the next item are "dead".
    // Penalize superlinearly as post_residual shrinks into the unusable zone.
    let min_useful = if next_item_size > 0 { next_item_size.min(80) } else { 10 };
    if post_residual < min_useful && post_residual > 0 {
        let deadness = (min_useful - post_residual) as f64;
        score += deadness * deadness * 0.5;
    }
    // Very small residual (< 10) is almost certainly dead space forever.
    if post_residual < 10 {
        score += 40.0;
    }

    // Reward near-perfect fits strongly.
    if post_residual == 0 {
        score -= 60.0;
    } else if post_residual <= 5 {
        score -= 25.0;
    }

    // If this bin can also fit the next item, it's a flexible host: reward.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 12.0;
    }

    // Last-chance bonus: if this is the only fitting bin, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate handling: empty bin gets a baseline near capacity,
    // modulated by open-bin pressure. Prefer new bin only when open bins are
    // numerous and their residuals are poor.
    if bin_residual == bin_capacity {
        score = bin_capacity as f64
            - 15.0 * (open_bins_count as f64)
            - 0.3 * mean_residual
            + 20.0 * (step_index as f64 / total_items.max(1) as f64);
        // If a fitting bin is a last chance, strongly discourage new bin.
        if fitting_bins_count == 1 {
            score += 50.0;
        }
        return score;
    }

    // Open-bin pressure: when many bins are open, tighten fills (avoid sprawl).
    score += 0.15 * (open_bins_count as f64);

    // Waste relative to mean residual: bins with residual far above mean
    // should absorb items (they are the most "spacious waste carriers").
    let dev = mean_residual - post_residual as f64;
    score += 0.1 * dev;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Aggressive 2-step lookahead: strongly reward exact match with next item size.
    if next_item_size > 0 && post_residual >= next_item_size {
        let gap = (post_residual - next_item_size) as f64;
        // Exact chain fit gets a big bonus; decay as gap grows.
        score -= 40.0 * (-gap / 8.0).exp();
