    // Penalize residuals too small for the next item (dead space).
    if next_item_size > 0 && post_residual < next_item_size {
        score += 0.8 * (next_item_size - post_residual) as f64;
    }

    // Relative-to-mean residual shaping.
    score += 0.5 * (post_residual as f64 - mean_residual);

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 30.0;
    }

    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 50.0;
    }

    // Late in stream: prefer tighter packing, penalize leftovers more.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += progress * post_residual as f64 * 0.3;

    // New-bin candidate: only attractive when existing fit is poor.
    if bin_residual == bin_capacity {
        let bad_fit = next_item_size > 0 && post_residual > 0 && post_residual < next_item_size;
        if bad_fit && fitting_bins_count <= 2 {
            score -= 20.0;
        } else {
            score += 60.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

