    }

    // Global state: many open bins with high mean residual -> prefer filling existing bins.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    let crowding = (open_bins_count as f64 / (1.0 + mean_residual / 10.0)).min(10.0);
    score -= 1.5 * crowding * (0.5 + 0.5 * progress);

    // New-bin candidate handling: make empty bin moderately attractive only
    // when current bin fits are poor or none exist.
    if bin_residual == bin_capacity {
        let poor_fits = if fitting_bins_count <= 1 { 0.0 } else { 1.0 };
        let good_fit_exists = (post_residual as f64) < 0.2 * cap;
        if good_fit_exists && poor_fits > 0.0 {
            score += 30.0; // a good existing fit exists, avoid opening new bin
        } else {
            score -= 5.0 * (1.0 - progress); // early on, fresh bins are fine
        }
    }

    // Mild penalty for leaving residuals that match no plausible item size band.
    if post_residual > 0 && post_residual < 5 {
        score += 8.0;
    }

    score
}

