        }
        if next_item_size > 0 && next_item_size >= bin_capacity / 2 { score -= 32.0; }
        if item_size >= bin_capacity * 3 / 4 { score -= 55.0; }
        if next_item_size > 0 && next_item_size <= bin_capacity - item_size { score -= 25.0; }
        if bin_capacity - item_size <= 4 { score -= 70.0; }
        let newbin_waste = (bin_capacity - item_size) as f64;
        if newbin_waste > 0.0 && newbin_waste < mean_residual * 0.6 { score -= 30.0; }
        if next_item_size > 0 {
            let leftover = bin_capacity - item_size;
            if leftover >= next_item_size {
                let tail = leftover % next_item_size;
                if tail <= 4 { score -= 16.0; }
                if tail == 0 { score -= 10.0; }
            }
        }
        if progress > 0.6 {
            let waste_tol = (1.0 - progress) * cap_f * 0.35;
            if newbin_waste > waste_tol && fitting_bins_count > 0 {
                score += 10.0 + progress * 22.0;
            }
        }
        if newbin_waste > 0.0 && (newbin_waste as u32) < next_item_size && newbin_waste < cap_f * 0.12 {
            score += 26.0;
        }
    } else {
        // Tightness pressure on open bins.
        let tightness = 1.0 - (item_size as f64 / bin_residual.max(1) as f64);
        score += tightness * 85.0;
        score += (mean_residual - bin_residual as f64) * 1.5;

        if next_item_size > 0 && post_residual >= next_item_size {
            score -= 18.0;
            if post_residual <= next_item_size + 4 { score -= 22.0; }
        }
        let dead_ratio = post_residual as f64 / cap_f;
        if dead_ratio < 0.03 {
            score -= 38.0;
        } else if dead_ratio < 0.08 {
            score -= 14.0;
        } else if dead_ratio > 0.35 {
            score += 24.0;
        } else if dead_ratio > 0.25 {
            score += 10.0;
        }
        if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
            let wasted = next_item_size as f64 - post_residual as f64;
            score += wasted * 0.6;
        }
        if post_residual > 0 && post_residual < 6 { score -= 22.0; }
        if post_residual > 0 && (post_residual as f64) < mean_residual * 0.25 { score -= 15.0; }
        if item_size == bin_residual { score -= 45.0; }
        score += dead_ratio * 30.0;
        if post_residual > 0 && next_item_size > 0 {
            let dead_frac = post_residual as f64 / cap_f;
            let unusable = post_residual < next_item_size && (next_item_size - post_residual) > 12;
            if unusable {
                score += dead_frac * 90.0;
            } else {
                let reuse = (post_residual / next_item_size) as f64 * (next_item_size as f64 / cap_f);
                score -= reuse * 22.0;
            }
        }
        if post_residual > 0 && next_item_size > 0 && post_residual < next_item_size {
            let gap = (next_item_size as f64 - post_residual as f64) / next_item_size.max(1) as f64;
            if gap > 0.0 && gap < 0.12 { score -= 10.0; }
        }
        if post_residual > 0 && fitting_bins_count == 1 { score -= 6.0; }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = step_index as f64 / total_items.max(1) as f64;
    let fit_ratio = item_size as f64 / cap;
    let mean_r = mean_residual / cap;

    // Base: post residual, damped by progress (late in stream, residual waste matters more)
    let mut score = pr * (0.9 + 0.4 * progress);

    // Non-linear penalty for awkward residuals (mid-range dead space)
    let prn = pr / cap;
    score += 12.0 * prn * (1.0 - prn) * (1.0 - progress);

    // Reward tight fits (small post residual) with smooth quadratic bonus
    score -= 15.0 * (1.0 - prn).powi(3) * fit_ratio;

    // Coupling with mean residual: prefer bins whose residual differs from mean (diversify sizes)
    score += 4.0 * (prn - mean_r).abs();

    // Last-chance bin: strongly favor using it
    if fitting_bins_count == 1 {
        score -= 20.0 + 10.0 * progress;
    }

    // Lookahead: if next item fits exactly in post residual, big reward
    if next_item_size > 0 && (next_item_size as f64) <= pr {
        let gap = (pr - next_item_size as f64) / cap;
        score -= 8.0 * (1.0 - gap * gap);
    } else if next_item_size > 0 {
        score += 5.0 * (1.0 - progress);
    }

    // Mild penalty when many bins open and residual is large (encourage consolidation)
    score += (open_bins_count as f64).ln().max(0.0) * 2.0 * prn;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit: extremely strong reward.
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Harmonic class of post_residual: classify leftover into capacity fractions.
    let cap_f = bin_capacity as f64;
    let pr = post_residual as f64;
    let frac = pr / cap_f; // 0..1

    // Dead-space penalty grows superlinearly for leftovers in awkward bands
    // (between 1/3 and 2/3 of capacity are hard to fill with items <= 80... but
    // sizes 1..100 unknown, so weight mildly).
    if frac > 0.25 && frac < 0.75 {
        score += 0.5 * pr;
    } else {
        // small or large leftovers are more reusable
        score -= 0.2 * pr;
    }

    // Harmonic residue classes on post_residual (mod 10): multiples of 10 are
    // more likely to be exactly filled by future integer items.
    if post_residual % 10 == 0 {
        score -= 8.0;
    } else {
        score += (post_residual % 10) as f64 * 0.3;
    }

    // Lookahead: if next item fits exactly into post_residual, big reward.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 400.0;
        } else if next_item_size <= post_residual {
            // next item fits: leftover after that = post_residual - next
            let second_left = post_residual - next_item_size;
            score -= 20.0 + 0.3 * second_left as f64;
        } else {
            // next item won't fit here: leftover is likely dead
            score += 0.4 * (next_item_size - post_residual) as f64;
        }
    }

    // Last-chance bin: if this is the only fitting bin, strongly prefer using it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 60.0;
    }

    // New-bin candidate handling: only attractive when this bin is a fresh empty bin
    // and no open bin fits well.
    if bin_residual == bin_capacity {
        // Opening a new bin should lose to good fits but win over terrible fits.
        // Anchor its score near the mean residual so bad fits (score > this) lose.
        score = 0.6 * cap_f + mean_residual * 0.2;
        if next_item_size > 0 && next_item_size <= bin_capacity {
            // fresh bin can hold next item too
            score -= 5.0;
        }
        // Late in stream, slightly discourage proliferating bins.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 30.0 * progress;
    }

    // Prefer fuller bins overall: closeness to capacity rewarded.
    let used = (bin_capacity - bin_residual) as f64;
    score -= 0.1 * used;

    // Many open bins: mild pressure to consolidate into existing bins.
    score += 0.5 * open_bins_count as f64;

    // Deviation from mean residual: prefer bins that deviate less (balance residuals
    // into harmonic classes together).
    let dev = (pr - mean_residual).abs();
    score += 0.15 * dev;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals that cannot fit the minimum
    // item (1 unit) are pure waste; residuals below a practical threshold
    // are near-waste. Penalize them super-linearly.
    if post_residual == 0 {
        score -= 40.0; // perfect fit is ideal
    } else {
        // dead-space ramp: unusable gap (< next_item_size) is worse than
        // a gap that could still serve the lookahead item.
        if next_item_size > 0 && post_residual < next_item_size {
            score += (next_item_size - post_residual) as f64 * 1.5;
        }
        // small-gap quadratic penalty (gap < 10 is almost certainly waste)
        if post_residual < 10 {
            let g = post_residual as f64;
            score += (10.0 - g) * (10.0 - g) * 0.8;
        }
        // gap that exactly fits the lookahead item is valuable
        if next_item_size > 0 && post_residual == next_item_size {
            score -= 12.0;
        }
    }

    // Reward tight fits relative to bin capacity (waste fraction term).
    score += (post_residual as f64 / bin_capacity as f64) * 30.0;

    // Last-chance pressure: if this is the only bin that fits, strongly
    // prefer using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // Open-bin pressure: with many open bins, discourage opening new ones
    // and encourage consolidating into existing residual capacity.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score += (open_bins_count as f64).ln().max(0.0) * (2.0 + 3.0 * progress);

    // New-bin candidate: only attractive when current bins are nearly full
    // (low mean residual) or this bin is a poor fit. Otherwise penalize.
    if bin_residual == bin_capacity {
        let mean_r = mean_residual.max(0.0);
        if mean_r < item_size as f64 + 5.0 {
            score -= 10.0; // existing bins too full, new bin is fine
        } else {
            score += 20.0 + mean_r * 0.2; // keep packing into open bins
        }
    }

    // Slight preference for bins whose residual is close to the mean
    // (balanced packing keeps future options open).
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += dev * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Aggressive 2-step lookahead: reward exact match of next item into post_residual
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 30.0; // perfect 2-chain
        } else if post_residual >= next_item_size {
            let slack = (post_residual - next_item_size) as f64;
            score -= 15.0 * (1.0 - slack / bin_capacity as f64).max(0.0);
        } else {
            // next item cannot fit here; penalize small dead space creation
            let miss = (next_item_size - post_residual) as f64;
            score += 0.3 * miss;
        }
    }

    // Prefer tight fits overall (small post_residual relative to capacity)
    let tightness = 1.0 - (post_residual as f64) / (bin_capacity as f64);
    score -= 10.0 * tightness;

    // Relative to mean residual: bins with less residual than average are more valuable to fill
    let rel = (bin_residual as f64) - mean_residual;
    score += 0.2 * rel;

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // Penalize opening a new bin when open bins can still fit reasonably
    if bin_residual == bin_capacity {
        score += 25.0;
        // early in the stream, new bins are cheaper; later, prefer consolidation
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 20.0 * progress;
        // if next item is large and current item is small, new bin may be fine
        if next_item_size > post_residual && post_residual < 15 {
            score -= 10.0;
        }
    }

    // Slight penalty when many bins are open (encourage closing them out)
    score += 0.05 * open_bins_count as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit gets strong reward.
    if post_residual == 0 {
        score -= 1000.0;
    } else {
        // Penalize large dead space nonlinearly.
        let dead = post_residual as f64 / bin_capacity as f64;
        score += dead * dead * 60.0;
    }

    // Lookahead: reward if next item fits into post-residual (great chaining),
    // penalize if post-residual is just barely too small (wasted sliver).
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 25.0;
        } else if post_residual > 0 && post_residual < 10 {
            score += 20.0; // tiny useless sliver
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 40.0;
    }

    // Early in the stream: be picky (favor tight fits), later: pack greedily.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score -= progress * 15.0;

    // If this bin's residual is far below the mean, prefer filling it (reduce fragmentation).
    let diff = mean_residual - bin_residual as f64;
    score += diff * 0.3;

    // New empty bin candidate: penalize slightly unless it's the only option or
    // current item is large and fits would be very loose.
    if bin_residual == bin_capacity {
        score += 30.0;
        if fitting_bins_count == 0 {
            score -= 100.0;
        }
        if item_size as f64 > bin_capacity as f64 * 0.7 {
            score -= 25.0;
        }
    }

    // Slight preference for keeping open_bins_count low (consolidate).
    score += open_bins_count as f64 * 0.1;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;

    // Base: prefer small post-residual (tight fit), with non-linear sharpening
    let mut score = pr * (1.0 + 2.0 * norm_pr * norm_pr);

    // Smooth polynomial coupling of post_residual with stream progress:
    // late in the stream, dead space becomes more costly
    let late = progress * progress;
    score += pr * (0.5 + 3.0 * late) * (1.0 - norm_pr);

    // Reward near-perfect fits with a smooth quadratic bonus
    let perfect = 1.0 - norm_pr;
    score -= 10.0 * perfect * perfect;

    // Last-chance bin: strongly favor using it (avoid opening a new bin)
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0 * (1.0 + progress);
    }

    // New-bin candidate: penalize, more strongly early and when many bins are open
    if bin_residual == bin_capacity {
        let openness = (open_bins_count as f64 / (1.0 + open_bins_count as f64)).sqrt();
        score += 30.0 + 20.0 * (1.0 - progress) * openness;
    }

    // Lookahead: if next item fits in the post-residual, reward this placement
    if next_item_size > 0 && (next_item_size as f64) <= pr {
        score -= 8.0 + 6.0 * (1.0 - (next_item_size as f64 / pr.max(1.0)));
    } else if next_item_size > 0 {
        // next item won't fit here: mild penalty scaled by how much it misses
        score += 3.0 * ((next_item_size as f64 - pr) / cap);
    }

    // Mean residual context: prefer bins whose residual deviates smoothly below mean (consolidation)
    let dev = (bin_residual as f64 - mean_residual) / cap;
    score += 5.0 * dev * dev.abs();

    // Tie-break: slightly prefer bins with more open bins (encourage closing out)
    score -= 0.05 * open_bins_count as f64 * (1.0 - norm_pr);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post-residual: residues near "nice" fractions of capacity
    // are more reusable, so reward them (subtract from score).
    let c = bin_capacity as f64;
    let pr = post_residual as f64;

    // Fractional position of post_residual within capacity
    let frac = pr / c;

    // Harmonic target classes: 0, 1/4, 1/3, 1/2, 2/3, 3/4 of capacity
    let targets = [0.0, 0.25, 0.3333, 0.5, 0.6667, 0.75];
    let mut min_dist = f64::INFINITY;
    for t in targets.iter() {
        let d = (frac - t).abs();
        if d < min_dist { min_dist = d; }
    }
    // Reward closeness to a harmonic class (scaled by capacity)
    score -= (c * 0.25) * (1.0 - min_dist / 0.125).max(0.0);

    // Integer-division thresholds: post_residual divisible into small buckets
    let pr_u = post_residual;
    if pr_u % 10 == 0 {
        score -= 8.0; // clean multiples of 10 are highly reusable
    }
    if pr_u % 25 == 0 {
        score -= 6.0; // quarter-capacity multiples
    }
    if pr_u % 50 == 0 {
        score -= 6.0; // half-capacity multiples
    }

    // Dead space penalty: small post-residual that can't fit typical items (10..80)
    if pr_u > 0 && pr_u < 10 {
        score += 25.0; // unusable sliver
    }

    // Lookahead coupling: if next item fits exactly into post_residual, strong reward
    if next_item_size > 0 {
        if next_item_size == pr_u {
            score -= 40.0; // perfect two-item chain
        } else if next_item_size <= pr_u {
            let slack = (pr_u - next_item_size) as f64;
            score -= 15.0 * (1.0 - slack / c).max(0.0);
        } else {
            // next item won't fit here anyway; mild penalty proportional to overflow
            score += 3.0;
        }
    }

    // Last-chance bin: strongly prefer using the only fitting bin
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 20.0;
    }

    // New-bin candidate handling: empty bin should only win when current bins are poor fits
    if bin_residual == bin_capacity {
        // Penalize opening a new bin early when plenty of open bins exist
        score += 10.0 + 2.0 * open_bins_count as f64;
        // But if the next item is large, a fresh bin is attractive
        if next_item_size >= 60 {
            score -= 12.0;
        }
    }

    // Tight fit reward: filling most of the residual is good
    let fill = 1.0 - frac;
    score -= 10.0 * fill;

    // Progression coupling: later in the stream, consolidate more aggressively
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += 5.0 * (1.0 - progress) * (pr_u as f64 / c);

    // Mean residual alignment: prefer bins whose residual is near the mean (avoid fragmentation)
    let dev = (pr - mean_residual).abs();
    score += 0.05 * dev;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals that are too small to ever
    // hold a future item (min size 1, but practically tiny gaps) are waste.
    if post_residual > 0 {
        // Penalize unusable small gaps super-linearly.
        if post_residual < 10 {
            score += (10 - post_residual) as f64 * 12.0;
        } else if post_residual < 25 {
            score += (25 - post_residual) as f64 * 4.0;
        }
    } else {
        // Perfect fit: strong reward.
        score -= 40.0;
    }

    // Reward tight fits (small waste relative to item size).
    let tightness = item_size as f64 / bin_residual.max(1) as f64;
    score -= tightness * 15.0;

    // Last-chance bin: if this is the only bin that fits, strongly prefer it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // Lookahead: if next item fits exactly in the post-residual, reward.
    if next_item_size > 0 && post_residual >= next_item_size {
        let next_fit_quality = (post_residual - next_item_size) as f64;
        score -= 10.0 - next_fit_quality.min(10.0) * 0.5;
    }
    // If next item cannot fit in post-residual, the gap becomes dead space.
    if next_item_size > 0 && post_residual < next_item_size && post_residual > 0 {
        score += 8.0;
    }

    // Open-bin pressure: many open bins -> prefer consolidating into
    // existing bins rather than opening new ones.
    score += open_bins_count as f64 * 0.8;

    // New-bin candidate handling: a fresh empty bin should only win when
    // fits elsewhere are poor. Give it a moderate baseline so tight fits
    // and last-chance bonuses beat it.
    if bin_residual == bin_capacity {
        score = 55.0 + post_residual as f64 * 0.1;
        // Late in stream with few bins, opening may be fine; slightly cheaper.
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score -= progress * 5.0;
    }

    // Prefer bins below mean residual (filling emptier bins first keeps
    // tight bins available for future tight items)? Inverse: fill tighter
    // bins first to close them out; slight nudge.
    score += (mean_residual - bin_residual as f64) * 0.15;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward near-perfect fits: small post_residual is heavily favored.
    if post_residual == 0 {
        score -= 60.0; // perfect fit
    } else if post_residual <= 5 {
        score -= 40.0;
    } else if post_residual <= 10 {
        score -= 20.0;
    }

    // Penalize large dead space quadratically (waste grows superlinearly).
    score += (post_residual as f64).powi(2) / 200.0;

    // 2-step lookahead: if the next item exactly fills the post_residual,
    // this is an ideal chaining placement -> strong reward.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 70.0;
        } else if next_item_size <= post_residual {
            // next item fits, but leaves a gap; reward proportional to tightness
            let gap = post_residual - next_item_size;
            score -= 30.0 - gap as f64 * 0.5;
        } else {
            // next item cannot fit in the leftover: penalize if the leftover
            // is small enough to be dead space relative to typical items
            let slack = post_residual as f64;
            if slack < 10.0 {
                score += 25.0;
            } else {
                score += (next_item_size as f64 - slack).max(0.0) * 0.15;
            }
        }
    }

    // Last-chance bonus: if this is the only bin that fits, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 35.0;
    }

    // Compare against mean residual: bins already more crowded than average
    // are good targets (fill tight bins first, keep loose bins flexible).
    let res = bin_residual as f64;
    if res < mean_residual {
        score -= (mean_residual - res) * 0.6;
    } else {
        score += (res - mean_residual) * 0.3;
    }

    // New-bin candidate handling: an empty bin is a fallback; make it
    // attractive only when no open bin offers a decent fit.
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin grows with how many bins are open.
        score = 100.0 + open_bins_count as f64 * 2.0;
        if fitting_bins_count == 0 {
            score -= 200.0; // forced: no open bin fits
        } else if next_item_size > 0 {
            // If the next item is large and this bin is the only fit for the
            // current item, opening fresh preserves a big contiguous space.
            if next_item_size >= 50 && post_residual < next_item_size {
                score -= 40.0;
            }
        }
        // Late in the stream, prefer consolidating into open bins.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += progress * 20.0;
        return score;
    }

    // Mild pressure to keep number of open bins low.
    score += open_bins_count as f64 * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tightness reward: quadratic penalty on leftover space.
    let pr = post_residual as f64;
    score += 0.35 * (pr / bin_capacity as f64) * pr;

    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 40.0;
    }

    // Small-dead-space bonus: leftovers below smallest plausible item are dead.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // Crowding: many open bins -> prefer filling existing ones.
    let crowding = (open_bins_count as f64 / (1.0 + step_index as f64)).min(2.0);
    score -= 8.0 * crowding * (bin_residual as f64 / bin_capacity as f64);

    // Lookahead: favor bins whose post-residual fits the next item.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 12.0;
        } else if post_residual > 0 {
            score += 6.0;
        }
    }

    // Global residual alignment: prefer bins with residual near mean (keeps spread balanced).
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += 0.05 * dev;

    // New-bin candidate: only attractive when current item is huge relative to
    // typical residuals or late in stream with few fitting bins.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let item_frac = item_size as f64 / bin_capacity as f64;
        score = bin_capacity as f64 - 20.0 * item_frac * (1.0 - progress)
            - 15.0 * (fitting_bins_count as f64).recip();
        if next_item_size > 0 && post_residual >= next_item_size {
            score -= 10.0;
        }
    }

    // Time-horizon modulation: early stream, be picky (penalize waste more).
    let progress = step_index as f64 / total_items.max(1) as f64;
    score *= 1.0 + 0.5 * (1.0 - progress);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;

    // Base: penalize wasted residual, with non-linear growth
    let mut score = pr * (1.0 + 0.5 * norm_pr * norm_pr);

    // Smooth coupling: residual penalty modulated by stream progress
    // (early on, waste matters less; late, waste is costly)
    score += 20.0 * norm_pr * norm_pr * (0.5 + progress);

    // Reward tight fits (small post_residual) especially when this is the only fitting bin
    let tightness = 1.0 - norm_pr;
    if fitting_bins_count == 1 {
        score -= 15.0 * tightness;
    } else {
        score -= 5.0 * tightness * tightness;
    }

    // Lookahead: if next item fits into post_residual, reward this bin
    if next_item_size > 0 && (next_item_size as f64) <= pr {
        score -= 8.0 * (next_item_size as f64 / cap) * (1.0 + progress);
    } else if next_item_size > 0 {
        // penalize leaving dead space relative to next item
        score += 3.0 * (pr - next_item_size as f64).abs() / cap;
    }

    // Prefer bins below mean residual slightly (use larger bins first)
    score += 2.0 * (pr - mean_residual) / cap;

    // Mild penalty for opening new bins when many bins are open
    if bin_residual == bin_capacity {
        score += 5.0 + 3.0 * (open_bins_count as f64).sqrt() * (1.0 - progress);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap_f = bin_capacity as f64;
    let progress = step_index as f64 / total_items.max(1) as f64;
    let mut score = post_residual as f64;

    // Dead-space avoidance: stronger, tiered (borrowed from best)
    if post_residual == 0 {
        score -= 1180.0;
    } else if post_residual <= 3 {
        score -= 500.0;
    } else if post_residual <= 12 {
        score -= 98.0;
    } else if post_residual < 20 {
        score += 18.0;
    } else if post_residual < 30 {
        score += 18.0 + (30 - post_residual) as f64 * 0.6;
    }

    // Lookahead for next item
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 900.0;
        } else if next_item_size <= post_residual {
            let post2 = post_residual - next_item_size;
            score -= 135.0 - (post2 as f64) * 2.0;
            if post2 == 0 { score -= 110.0; }
            if post2 > 0 && post2 < 5 { score -= 28.0; }
            if post2 % 10 == 0 && post2 > 0 { score -= 28.0; }
            if post2 > 0 && post2 <= 2 { score -= 14.0; }
            if post_residual >= next_item_size * 2 && post_residual - next_item_size * 2 <= 4 {
                score -= 20.0;
            }
            if post_residual % next_item_size == 0 { score -= 18.0; }
            let chain = post_residual / next_item_size;
            if chain >= 2 { score -= (chain.min(4)) as f64 * 6.0; }
            if post2 > 0 && post2 <= next_item_size / 4 { score -= 10.0; }
        } else {
            score += 20.0;
            let gap = next_item_size - post_residual;
            if post_residual > 0 {
                if gap <= 3 { score += 35.0; }
                else if gap <= 8 { score += 12.0; }
                if (gap as f64) > mean_residual * 0.5 { score += 14.0; }
                if gap <= 5 { score += (6 - gap) as f64 * 4.0; }
            }
            if post_residual % 10 == 0 && post_residual > 0 { score -= 15.0; }
        }
    }

    // Compaction pressure
    score += open_bins_count as f64 * 0.8;

    // Last-chance bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 45.0;
    }

    // Tightness
    score -= (item_size as f64 / bin_residual.max(1) as f64) * 30.0;

    // NEW-BIN CANDIDATE handling
    if bin_residual == bin_capacity {
        let avg_fill = 1.0 - (mean_residual / cap_f);
        let leftover = bin_capacity - item_size;
        let newbin_waste = leftover as f64;
        score += 250.0 - avg_fill * 330.0 - progress * 65.0;
        if item_size as f64 > mean_residual { score -= 45.0; }
        if fitting_bins_count > 0 {
            score += (fitting_bins_count.min(5) as f64) * 9.0 + 20.0;
            let snug = item_size as f64 / bin_residual.max(1) as f64;
            if snug > 0.9 { score += 40.0; }
            if snug > 0.95 { score += 28.0; }
            if snug > 0.98 { score += 18.0; }
        }
        if next_item_size > 0 && next_item_size >= bin_capacity / 2 { score -= 32.0; }
        if item_size >= bin_capacity * 3 / 4 { score -= 55.0; }
        if next_item_size > 0 && next_item_size <= leftover { score -= 25.0; }
        if bin_capacity - item_size <= 4 { score -= 70.0; }
        if next_item_size > 0 {
            if leftover >= next_item_size {
                let tail = leftover % next_item_size;
                if tail <= 4 { score -= 16.0; }
                if tail == 0 { score -= 10.0; }
                if leftover >= next_item_size * 2 { score -= 14.0; }
            }
            if leftover < next_item_size && leftover < 10 { score += 18.0; }
        }
        if newbin_waste > 0.0 && newbin_waste < mean_residual * 0.6 { score -= 30.0; }
        if newbin_waste > 0.0 && (newbin_waste as u32) < next_item_size && newbin_waste < cap_f * 0.12 { score += 26.0; }
        if progress > 0.6 {
            let waste_tol = (1.0 - progress) * cap_f * 0.35;
            if newbin_waste > waste_tol && fitting_bins_count > 0 { score += 10.0 + progress * 22.0; }
        }
        if progress > 0.85 && newbin_waste > cap_f * 0.3 { score += 8.0; }
    } else {
        // Consolidation of slack toward below-average residuals
        score += (mean_residual - bin_residual as f64) * 1.5;

        let dead_ratio = post_residual as f64 / cap_f;
        if dead_ratio < 0.03 { score -= 38.0; }
        else if dead_ratio < 0.08 { score -= 14.0; }
        else if dead_ratio > 0.35 { score += 24.0; }
        else if dead_ratio > 0.25 { score += 10.0; }

        if next_item_size > 0 && post_residual > 0 {
            if post_residual < next_item_size {
                let wasted = next_item_size as f64 - post_residual as f64;
                score += wasted * 0.6;
                if wasted > mean_residual * 0.6 && fitting_bins_count > 2 { score += wasted * 0.4; }
            } else {
                score -= 18.0;
                if post_residual <= next_item_size + 4 { score -= 22.0; }
                let slack = post_residual - next_item_size;
                if slack > 0 && (slack as f64) < cap_f * 0.02 { score -= 14.0; }
            }
            let unusable = post_residual < next_item_size && (next_item_size - post_residual) > 12;
            if unusable {
                score += dead_ratio * 90.0;
            } else {
                let reuse = (post_residual / next_item_size) as f64 * (next_item_size as f64 / cap_f);
                score -= reuse * 22.0;
            }
        }

        if post_residual > 0 && post_residual < 6 { score -= 22.0; }
        if item_size == bin_residual { score -= 45.0; }
        if post_residual > 0 && (post_residual as f64) < mean_residual * 0.25 { score -= 15.0; }
        if bin_residual as f64 > cap_f * 0.6 { score -= 12.0; }
        if post_residual > 0 && (post_residual as f64) < cap_f * 0.015 { score -= 18.0; }
        if post_residual > 0 && next_item_size > 0 && post_residual < next_item_size {
            score += (1.0 - progress) * 14.0;
        }
        if fitting_bins_count <= 2 && post_residual > 0 { score -= 8.0; }
        if post_residual > 0 && (post_residual as f64) > mean_residual * 1.6 && fitting_bins_count > 2 { score += 10.0; }
        if post_residual > 0 && post_residual % 5 == 0 && post_residual <= 30 { score -= 8.0; }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the leftover space: coarse residual buckets (capacity fractions).
    let cap = bin_capacity as f64;
    let frac = post_residual as f64 / cap; // fraction of capacity wasted after placement

    // Penalize leftovers in "dead zones" — residuals too small to host typical items.
    // Harmonic classes via integer division on post_residual.
    let class = post_residual / 10; // class id 0..=10
    match class {
        0 => score += 25.0,                 // 0-9: dead space (only tiny items fit)
        1 => score += 12.0,                 // 10-19: marginal
        2 => score += 4.0,                  // 20-29: ok-ish
        3 | 4 => score -= 6.0,              // 30-49: useful band
        5 | 6 => score -= 10.0,             // 50-69: very reusable
        _ => score -= 8.0,                  // 70+: large leftover (but item was small)
    }

    // Modulo-arithmetic coupling: leftover that is a multiple of common item sizes
    // is more likely reusable exactly.
    if post_residual >= 10 {
        if post_residual % 10 == 0 {
            score -= 5.0;
        } else if post_residual % 5 == 0 {
            score -= 2.0;
        }
    }

    // Lookahead: reward if the next item fits exactly in the post residual.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 20.0; // perfect chained fit
        } else if next_item_size <= post_residual {
            score -= (post_residual - next_item_size) as f64 * 0.3; // near fit
        } else {
            // next item cannot use the leftover; penalize proportionally to waste
            score += frac * 8.0;
        }
    }

    // Last-chance bin: strongly favor using the only bin that fits, avoiding a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate: only attractive when the item is large relative to capacity
    // or open bins are all tight (mean residual low).
    if bin_residual == bin_capacity {
        let tight = mean_residual / cap;
        score += 15.0 - 25.0 * tight; // cheap to open when bins are nearly full
        if item_size > 60 {
            score -= 10.0;
        }
    }

    // Mild preference to fill bins more densely as the stream progresses.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= (1.0 - frac) * progress * 3.0;

    // Slight bias toward bins with residuals close to the current mean (balance).
    score += ((bin_residual as f64 - mean_residual) / cap).abs() * 2.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let score = post_residual as f64 / bin_capacity.max(1) as f64;
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals too small for the minimum item
    // (1 unit floor, but practically anything < 10 is nearly dead) are heavily penalized.
    if post_residual < 10 {
        score += 60.0;
    } else if post_residual < 20 {
        score += 25.0 * (1.0 - post_residual as f64 / 20.0);
    }

    // Reward near-perfect fits (post_residual very small but usable).
    if post_residual <= 5 {
        score -= 40.0;
    }

    // Tight fit reward: fraction of bin used by this placement.
    let fill_ratio = item_size as f64 / bin_residual as f64;
    score -= 30.0 * fill_ratio * fill_ratio;

    // Last-chance bin: strongly favor using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 35.0;
    }

    // New-bin candidate: penalize opening a new bin unless open bins are crowded
    // or the fit in this new bin would be excellent for a large item.
    if bin_residual == bin_capacity {
        score += 45.0;
        // Large items pack cleanly into fresh bins; soften the penalty.
        if item_size >= 70 {
            score -= 25.0;
        }
        // If many open bins, spreading load is less costly.
        if open_bins_count > 6 {
            score -= 10.0;
        }
        // Late in the stream, avoid leaving many open bins with wasted space.
        if total_items > 0 && (step_index as f64) / (total_items as f64) > 0.8 {
            score += 15.0;
        }
    }

    // Lookahead: if the next item fits into the post residual, reward this bin.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 20.0 + 0.3 * next_item_size as f64;
    } else if next_item_size > 0 && post_residual > 0 {
        // Next item won't fit here: penalize leaving a gap that blocks it.
        score += 8.0;
    }

    // Open-bin pressure: many open bins -> prefer consolidating into existing ones.
    score += 0.8 * open_bins_count as f64;

    // Deviation from mean residual: prefer bins whose residual is close to item
    // needs (low waste relative to fleet average).
    score += 0.15 * (mean_residual - post_residual as f64).abs();

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect 2-step match: bin closes exactly after next item -> strong reward.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 60.0;
    }

    // Post-residual too small for the lookahead item: dead space penalty,
    // scaled by how close it is to being useful.
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 0.5 * (next_item_size - post_residual) as f64;
        // Tiny dead space (< 10) is nearly useless in any stream.
        if post_residual < 10 {
            score += 15.0;
        }
    }

    // Reward bins whose residual deviates below the mean (tighter bins first),
    // mildly, so we keep the packing compact.
    score += 0.3 * (bin_residual as f64 - mean_residual).max(0.0);

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // New-bin candidate: it's only attractive when no open bin offers a decent fit.
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        // Penalize opening a new bin; the penalty relaxes late in the stream
        // and when many bins are open (fragmentation already high).
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 35.0 + 25.0 * (1.0 - progress) - 0.2 * open_bins_count as f64;
        // If lookahead fits perfectly in a fresh bin, soften the penalty.
        if next_item_size > 0 && next_item_size >= bin_capacity.saturating_sub(item_size) {
            score -= 20.0;
        }
    }

    // Slight preference for filling large items into large residuals.
    score += 0.1 * (item_size as f64 / bin_capacity as f64) * (post_residual as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap_f = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Dead-space avoidance with graded rewards for tiny leftovers
    if post_residual == 0 {
        score -= 1100.0;
    } else if post_residual <= 3 {
        score -= 420.0;
    } else if post_residual < 10 {
        score -= 60.0;
    } else if post_residual < 20 {
        score += 14.0;
    } else if post_residual < 30 {
        score += 14.0 + (30 - post_residual) as f64 * 0.5;
    }

    // Lookahead: strongly reward placements that let the next item fit snugly
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 850.0;
        } else if next_item_size <= post_residual {
            let post2 = post_residual - next_item_size;
            score -= 120.0 - (post2 as f64) * 1.8;
            if post2 == 0 {
                score -= 90.0;
            }
            if post2 > 0 && post2 < 5 {
                score -= 26.0;
            }
            if post2 % 10 == 0 && post2 > 0 {
                score -= 22.0;
            }
            if post_residual % next_item_size == 0 {
                score -= 15.0;
            }
        } else {
            // next item won't fit here: penalize leaving a nearly-usable gap
            let gap = (next_item_size - post_residual) as f64;
            score += 16.0;
            if post_residual > 0 && gap <= 5.0 {
                score += 30.0;
            }
            if post_residual > 0 && post_residual < 15 {
                score += 35.0;
            }
            if post_residual as f64 > mean_residual * 1.4 {
                score -= 10.0;
            }
        }
    }

    // Perfect fit of item into bin residual
    if item_size == bin_residual {
        score -= 45.0;
    }

    // NEW-BIN CANDIDATE LOGIC: make opening a new bin deliberate
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let avg_fill = 1.0 - (mean_residual / cap_f);
        score += 240.0 - avg_fill * 320.0 - progress * 60.0;
        let newbin_waste = (bin_capacity - item_size) as f64;
        if fitting_bins_count > 0 {
            score += (fitting_bins_count as f64).min(5.0) * 8.0 + 18.0;
            let snug = item_size as f64 / (bin_residual.max(1) as f64);
            if snug > 0.9 {
                score += 35.0;
            }
            if snug > 0.95 {
                score += 25.0;
            }
        }
        // Large items deserve fresh bins
        if item_size >= bin_capacity * 3 / 4 {
            score -= 50.0;
        }
        if next_item_size > 0 && next_item_size <= bin_capacity - item_size {
            score -= 22.0;
        }
        // Late in stream: tolerate opening bins less; compact harder
        if progress > 0.6 {
            let waste_tol = (1.0 - progress) * cap_f * 0.35;
            if newbin_waste > waste_tol && fitting_bins_count > 0 {
                score += 10.0 + progress * 20.0;
            }
        }
        if newbin_waste > 0.0 && (newbin_waste as u32) < next_item_size && newbin_waste < cap_f * 0.12 {
            score += 24.0;
        }
    } else {
        // Existing-bin branch: prefer filling the fullest usable bin
        let tightness = 1.0 - (item_size as f64 / bin_residual.max(1) as f64);
        score += tightness * 80.0;
        score += (mean_residual - bin_residual as f64) * 1.4;

        let dead_ratio = post_residual as f64 / cap_f;
        if dead_ratio < 0.03 {
            score -= 35.0;
        } else if dead_ratio < 0.08 {
            score -= 12.0;
        } else if dead_ratio > 0.35 {
            score += 22.0;
        } else if dead_ratio > 0.25 {
            score += 9.0;
        }

        // Unusable sliver relative to next item
        if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
            let wasted = next_item_size as f64 - post_residual as f64;
            score += wasted * 0.6;
            score += (1.0 - step_index as f64 / total_items.max(1) as f64) * 12.0;
        }

        // Chain reuse: post residual can host multiple next items
        if next_item_size > 0 && post_residual >= next_item_size {
            let chain = post_residual / next_item_size;
            if chain >= 2 {
                score -= (chain.min(4)) as f64 * 6.0;
            }
        }

        // Last-chance bin: avoid opening a new bin
        if fitting_bins_count == 1 {
            score -= 22.0;
        }

        if post_residual > 0 && post_residual % 10 == 0 {
            score -= 9.0;
        }
    }

    // Pressure from open bins: compact when many bins are open
    score += open_bins_count as f64 * 0.6;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let score = (post_residual as f64) * 0.92;
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong reward for tight fits (small post_residual)
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 3.0 * tightness * (post_residual as f64 / bin_capacity as f64);

    // Perfect fit bonus
    if post_residual == 0 {
        score -= 50.0;
    }

    // Dead-space penalty: residual too small for typical future items
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 20.0;
    }

    // Lookahead: reward if next item fits the post_residual (chaining)
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 8.0 * (next_item_size as f64 / bin_capacity as f64) * 10.0;
        } else if post_residual > 0 {
            score += 5.0;
        }
        // Reward if post_residual exactly matches next item
        if post_residual == next_item_size {
            score -= 15.0;
        }
    }

    // New-bin candidate handling: penalize opening a new bin unless current bins are poor fits
    if bin_residual == bin_capacity {
        let baseline = item_size as f64;
        let mut new_bin_score = post_residual as f64 + baseline;
        // In early stream with few bins, opening new bins is cheap
        let progress = step_index as f64 / (total_items.max(1) as f64);
        if open_bins_count < 3 || progress < 0.2 {
            new_bin_score -= 30.0;
        } else {
            // Penalize new bins later in the stream
            new_bin_score += 40.0 * progress;
        }
        // If many bins fit the item, prefer them over a new bin
        if fitting_bins_count > 2 {
            new_bin_score += 25.0;
        }
        // If mean residual is high, existing bins have room; discourage new bin
        if mean_residual > item_size as f64 * 1.5 {
            new_bin_score += 20.0;
        }
        score = new_bin_score;
    } else {
        // Mild preference for fuller bins relative to global mean residual
        if (bin_residual as f64) < mean_residual {
            score -= 4.0;
        } else {
            score += 3.0;
        }
    }

    // Late-stream consolidation: prefer filling existing bins as stream ends
    let remaining = total_items.saturating_sub(step_index) as f64;
    if remaining < 20.0 && bin_residual != bin_capacity {
        score -= 10.0 * (1.0 - remaining / 20.0);
    }

    // Penalty for leaving residuals in the awkward 11-30 range (hard to fill)
    if post_residual >= 11 && post_residual <= 30 {
        score += 6.0 * (1.0 - (post_residual as f64 - 10.0) / 20.0);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let progress = step_index as f64 / total_items.max(1) as f64;
    let cap = bin_capacity as f64;
    let post = post_residual as f64;

    // Smooth non-linear coupling: reward tight fits more strongly as the stream progresses.
    let tightness = 1.0 - post / cap; // in (0,1], larger = tighter fit
    score -= 40.0 * tightness * tightness * (0.5 + progress);

    // Penalize dead space non-linearly: small residuals that nothing can use.
    let dead = (post / cap).powi(3);
    score += 60.0 * dead * (1.0 - 0.5 * progress);

    // Lookahead: if the next item fits exactly into post_residual, reward heavily.
    if next_item_size > 0 {
        if next_item_size as f64 <= post {
            let exact = 1.0 - ((post - next_item_size as f64) / cap).abs();
            score -= 25.0 * exact * exact;
        } else {
            // post_residual too small for next item: penalize proportionally
            score += 8.0 * (next_item_size as f64 - post) / cap;
        }
    }

    // Last-chance bin: strongly favor using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 50.0;
    }

    // New-bin candidate handling: only attractive early or when open bins are nearly full.
    if bin_residual == bin_capacity {
        let avg_fill = 1.0 - mean_residual / cap;
        score += 30.0 + 40.0 * avg_fill * (1.0 - progress) - 20.0 * progress * avg_fill;
    }

    // Mild preference for bins with residuals near the mean (balance load).
    let dev = (bin_residual as f64 - mean_residual).abs() / cap;
    score += 5.0 * dev * dev;

    // Slight preference for using fewer open bins when many exist.
    score += 0.05 * open_bins_count as f64 * (1.0 - progress);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: smaller classes (finer leftovers) are worse.
    let frac = post_residual as f64 / bin_capacity as f64;
    // Class index: 0 = empty, 1 = tiny leftover (<10), 2 = small (<25), 3 = medium (<50), 4 = large
    let class = if post_residual == 0 { 0 }
        else if post_residual < 10 { 1 }
        else if post_residual < 25 { 2 }
        else if post_residual < 50 { 3 }
        else { 4 };

    // Penalize dead-space classes (tiny leftovers are nearly useless).
    score += match class {
        0 => -12.0,                      // perfect fit, strongly reward
        1 => 18.0,                       // unusable sliver
        2 => 8.0,
        3 => 0.0,
        4 => -4.0,                       // big leftover still flexible
        _ => 0.0,
    };

    // Modulo harmonic coupling: leftover that can hold the lookahead item is valuable.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            let slack = (post_residual - next_item_size) as f64;
            score -= 6.0 + 0.15 * slack; // reward reserving room for next item
        } else {
            score += 5.0;                // lookahead won't fit here
        }
        // Integer-division harmonic: leftover exactly one class above next item size
        let div = post_residual / (next_item_size.max(1));
        if div == 1 { score -= 3.0; }    // snug fit for lookahead
        else if div >= 3 { score += 2.0; }
    } else {
        // Last item: prefer tightest fit overall
        score -= 10.0;
    }

    // Last-chance bin: strongly prefer using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate: discourage unless current residual is very tight relative to item.
    if bin_residual == bin_capacity {
        let tight = (bin_residual - item_size) as f64 / bin_capacity as f64;
        score += 14.0 - 20.0 * (1.0 - tight); // open new bin only if this "fit" is loose elsewhere
        if next_item_size > 0 && post_residual >= next_item_size {
            score -= 10.0; // fresh bin serves lookahead well
        }
    }

    // Mean-residual coupling: prefer bins below mean residual (tighter bins first).
    score += 0.1 * (mean_residual - post_residual as f64);

    // Stream progression: late in stream, consolidate aggressively.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= 6.0 * progress * (post_residual as f64 / bin_capacity as f64);

    // Modulo-class tiebreak on post_residual vs capacity quarters.
    let q = post_residual % (bin_capacity / 4).max(1);
    score += q as f64 * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap_f = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = step_index as f64 / total_items.max(1) as f64;
    let nxt = next_item_size as f64;
    let mut score = pr;

    // --- New-bin candidate handling (bin_residual == bin_capacity) ---
    if bin_residual == bin_capacity {
        let newbin_waste = (bin_capacity - item_size) as f64;
        let avg_fill = 1.0 - mean_residual / cap_f;
        let mut nb = 240.0 - avg_fill * 320.0 - progress * 60.0;
        if fitting_bins_count > 0 {
            nb += (fitting_bins_count as f64).min(5.0) * 9.0 + 20.0;
            let snug = item_size as f64 / bin_residual.max(1) as f64;
            if snug > 0.9 { nb += 40.0; }
            if snug > 0.95 { nb += 28.0; }
            if snug > 0.98 { nb += 18.0; }
        }
        if item_size as f64 > mean_residual { nb -= 45.0; }
        if item_size >= bin_capacity * 3 / 4 { nb -= 55.0; }
        if next_item_size > 0 && next_item_size >= bin_capacity / 2 { nb -= 32.0; }
        if next_item_size > 0 && next_item_size <= bin_capacity - item_size { nb -= 25.0; }
        if next_item_size > 0 {
            let leftover = (bin_capacity - item_size) as f64;
            if leftover >= nxt {
                let tail = leftover % nxt;
                if tail == 0.0 { nb -= 12.0; }
                else if tail <= 4.0 { nb -= 16.0; }
            }
            if leftover < nxt && leftover < 10.0 { nb += 18.0; }
            if leftover >= nxt && leftover - nxt <= 6.0 { nb -= 38.0; }
        }
        if newbin_waste > 0.0 && newbin_waste < mean_residual * 0.6 { nb -= 30.0; }
        if fitting_bins_count > 0 {
            let best_alt = if item_size as f64 <= mean_residual { mean_residual - item_size as f64 } else { mean_residual };
            if newbin_waste > best_alt + cap_f * 0.08 { nb += 22.0; }
            if newbin_waste > best_alt + cap_f * 0.2 { nb += 14.0; }
        }
        if progress > 0.6 {
            let waste_tol = (1.0 - progress) * cap_f * 0.35;
            if newbin_waste > waste_tol && fitting_bins_count > 0 { nb += 10.0 + progress * 22.0; }
        }
        if newbin_waste > 0.0 && (newbin_waste as u32) < next_item_size && newbin_waste < cap_f * 0.12 { nb += 26.0; }
        if next_item_size > 0 && newbin_waste > 0.0 && (newbin_waste as u32) % next_item_size == 0 && newbin_waste >= nxt { nb -= 20.0; }
        return nb;
    }

    // --- Existing-bin scoring ---
    // Strong rewards for tight post-residuals
    if post_residual == 0 { score -= 1180.0; }
    else if post_residual <= 3 { score -= 500.0; }
    else if post_residual <= 12 { score -= 98.0; }
    else if post_residual < 20 { score += 18.0; }
    else if post_residual < 30 { score += 18.0 + (30 - post_residual) as f64 * 0.6; }

    // Lookahead: reward exact and near-exact chain fits
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 900.0;
        } else if next_item_size <= post_residual {
            let post2 = post_residual - next_item_size;
            score -= 135.0 - post2 as f64 * 2.0;
            if post2 == 0 { score -= 110.0; }
            if post2 > 0 && post2 < 5 { score -= 28.0; }
            if post2 > 0 && post2 <= 2 { score -= 14.0; }
            if post2 > 0 && post2 <= next_item_size / 4 { score -= 10.0; }
            if post_residual >= next_item_size * 2 && post_residual - next_item_size * 2 <= 4 { score -= 20.0; }
            if post_residual % next_item_size == 0 { score -= 18.0; }
            let chain = post_residual / next_item_size;
            if chain >= 2 { score -= (chain.min(4)) as f64 * 6.0; }
        } else {
            score += 20.0;
            let gap = nxt - pr;
            if post_residual < 15 { score += 45.0; }
            if gap <= 3.0 { score += 35.0; }
            if gap <= 8.0 { score += 12.0; }
            if gap <= 5.0 { score += (6.0 - gap) * 4.0; }
            if pr > mean_residual * 1.4 { score -= 12.0; }
            if gap > mean_residual * 0.5 { score += 14.0; }
        }
    }

    // Dead-space ratio penalties
    let dead_ratio = pr / cap_f;
    if dead_ratio < 0.03 { score -= 38.0; }
    else if dead_ratio < 0.08 { score -= 14.0; }
    else if dead_ratio > 0.35 { score += 24.0; }
    else if dead_ratio > 0.25 { score += 10.0; }
    score += dead_ratio * 30.0;

    // Unusable residual (too small for next item) penalized by waste
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        let wasted = nxt - pr;
        score += wasted * 0.6 + (1.0 - progress) * 14.0;
        if wasted > 12.0 { score += dead_ratio * 90.0; }
    } else if next_item_size > 0 {
        let reuse = (post_residual / next_item_size) as f64 * (next_item_size as f64 / cap_f);
        score -= reuse * 22.0;
    }

    // Last-chance bin
    if fitting_bins_count == 1 { score -= 30.0; }

    // Consolidation and fleet-mean alignment
    score += 0.3 * open_bins_count as f64 * dead_ratio;
    score += (mean_residual - bin_residual as f64) * 0.5;
    if post_residual > 0 && (pr - mean_residual).abs() < cap_f * 0.03 { score -= 9.0; }
    if post_residual > 0 && pr < mean_residual * 0.25 { score -= 15.0; }

    // Perfect snug fit of item into residual
    if item_size == bin_residual { score -= 45.0; }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small gaps (<10, minimum item size) are pure waste.
    if post_residual < 10 {
        score -= 60.0; // perfect/usable-closure fit is excellent
    } else if post_residual <= 20 {
        // Gap that only the smallest items can use: heavily penalize relative waste.
        score += (20 - post_residual) as f64 * 1.5;
    } else {
        // Larger gaps: penalize proportionally to how much of the bin is wasted.
        score += (post_residual as f64 / bin_capacity as f64) * 25.0;
    }

    // Reward tight fits (waste relative to item size).
    score -= (item_size as f64 / (item_size + post_residual) as f64) * 15.0;

    // Open-bin pressure: discourage spreading across many bins unless fit is good.
    score += open_bins_count as f64 * 0.8;

    // Last-chance bin: strongly prefer using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // Lookahead (k=2): if post_residual cannot fit next item, the gap is likely dead.
    if next_item_size > 0 {
        if post_residual < next_item_size {
            score += (next_item_size - post_residual) as f64 * 0.6;
        } else {
            // Gap reusable by next item: reward.
            score -= 8.0;
        }
    }

    // New-bin candidate: only attractive when open bins are crowded or fit is terrible.
    if bin_residual == bin_capacity {
        let crowded = mean_residual / bin_capacity as f64;
        score += 20.0 - crowded * 25.0;
        if open_bins_count == 0 {
            score -= 50.0;
        }
    }

    // Slight late-stream conservatism: consolidate more as stream progresses.
    score += (step_index as f64 / (total_items as f64).max(1.0)) * 5.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer tight fits (low post_residual already favored).
    // Normalize post_residual against capacity for nonlinear shaping.
    let pr_norm = post_residual as f64 / bin_capacity as f64;
    score += 40.0 * pr_norm * pr_norm;

    // Aggressive 2-step lookahead: reward if next item fits exactly in post_residual.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            // Perfect chaining: this bin will be exactly filled by the next item.
            score -= 60.0;
        } else if next_item_size <= post_residual {
            // Next item fits: good, but not perfect. Reward proportional to fill.
            let fill = next_item_size as f64 / post_residual as f64;
            score -= 40.0 * fill;
        } else {
            // Next item does NOT fit in the leftover: dead space risk.
            let gap = (next_item_size - post_residual) as f64;
            let gap_norm = gap / bin_capacity as f64;
            // Penalize more when gap is small (wasted near-miss) and when
            // post_residual is small enough that nothing else will fit either.
            let unusable = if post_residual < 10 { 1.0 } else { 0.0 };
            score += 25.0 * gap_norm + 20.0 * unusable * pr_norm;
        }
    } else {
        // Last item: any placement is fine; slight preference for fullest bin.
        score -= 10.0;
    }

    // Compare post_residual against mean residual across open bins:
    // leaving a residual below mean concentrates waste, which is good if
    // it consolidates space elsewhere.
    if mean_residual > 0.0 {
        let rel = post_residual as f64 / mean_residual;
        if rel < 1.0 {
            score -= 15.0 * (1.0 - rel);
        } else {
            score += 10.0 * (rel - 1.0).min(2.0);
        }
    }

    // Last-chance bin: if this is the only bin that can fit the item,
    // strongly prefer using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 45.0;
    }

    // New-bin candidate handling: opening a new bin is only attractive when
    // the item fits badly everywhere else. Make the empty bin moderately
    // expensive so it only wins when open bins leave very poor fits.
    if bin_residual == bin_capacity {
        // Empty bin: post_residual = capacity - item_size, already high.
        // Add a fixed opening cost, discounted slightly as the stream ends
        // (fewer future items to fill leftover space with) and when many
        // bins are already open (consolidation preferred).
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 30.0 - 10.0 * progress + 2.0 * (open_bins_count as f64).min(20.0);
        // But if next item would perfectly fill the new bin's residual too,
        // opening is actually great.
        if next_item_size > 0 && post_residual == next_item_size {
            score -= 70.0;
        }
    }

    // Small tie-breaker toward bins whose residual is close to item size.
    let tightness = (bin_residual - item_size) as f64 / bin_capacity as f64;
    score -= 5.0 * (1.0 - tightness);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tightness reward: strongly favor bins where the item nearly fills the residual.
    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 40.0 * fit_ratio * fit_ratio;

    // Dead-space penalty: leftover space that is too small for typical items is worthless.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Lookahead: penalize leftovers that cannot host the next item (stranding risk).
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            // Reward leaving room exactly usable by the next item.
            let next_fit = next_item_size as f64 / post_residual as f64;
            score -= 15.0 * next_fit;
        } else {
            score += 0.35 * (next_item_size - post_residual) as f64;
        }
    }

    // Last-chance bonus: if this is the only bin that fits, avoid opening a new bin
    // unless the fit is truly terrible.
    if fitting_bins_count == 1 {
        score -= 20.0 + 0.25 * item_size as f64;
    }

    // New-bin candidate handling: an empty bin is a fresh resource. Prefer it only
    // for large items or when existing bins are heavily fragmented.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let fragmentation = (mean_residual - post_residual as f64).max(0.0);
        // Cost of a new bin decreases with many open bins already, increases early on.
        let new_bin_cost = 60.0 - 25.0 * progress + 0.05 * open_bins_count as f64;
        score = new_bin_cost + post_residual as f64 * 0.5 - fragmentation * 0.1;
        // Big items deserve fresh bins more than small ones.
        score -= 0.3 * item_size as f64;
    }

    // Mild global pressure: when the mean residual is small, conserve tight bins.
    score += 0.05 * (mean_residual - post_residual as f64).max(0.0);

    // Small noise-free coupling with stream position: later in the stream,
    // consolidation matters more, so penalize wasteful placements.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += 5.0 * progress * (post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let residual = bin_residual as f64;

    // Base: prefer small post-residual (tight fit), smoothed non-linearly.
    let norm_post = post / cap; // 0..1
    let mut score = norm_post * norm_post * (1.0 + 2.0 * (1.0 - progress));

    // Non-linear coupling: post-residual penalized more strongly late in stream
    // and when it becomes unusable dead space relative to future item needs.
    let dead = if next_item_size > 0 {
        (next_item_size as f64 - post).max(0.0) / cap
    } else {
        0.0
    };
    score += dead * dead * (0.5 + 3.0 * progress);

    // Reward tight fits (post_residual near zero) with a smooth term.
    score -= (1.0 - norm_post).powi(3) * 2.0;

    // Last-chance bonus: if this is the only bin that fits, strongly favor it
    // to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 4.0 * (1.0 - progress + 0.3);
    }

    // Compare against mean residual: filling a bin below mean residual is good
    // (reduces fragmentation); smooth interaction term.
    score += 0.5 * (mean_residual - residual) / cap * (0.5 + progress);

    // New-bin candidate handling: empty bin has residual == capacity.
    // Penalize opening a new bin smoothly, more when other bins fit well and
    // early in the stream; relax late or when open bins are very full.
    if bin_residual == bin_capacity {
        let avg_fullness = 1.0 - mean_residual / cap;
        let new_bin_penalty = 3.0
            + 6.0 * (1.0 - progress)
            + 2.0 * avg_fullness * avg_fullness;
        // If the item is large, a fresh bin may be genuinely better.
        let size_relief = (item_size as f64 / cap).powi(2) * 5.0;
        score += new_bin_penalty - size_relief;
    }

    // Mild non-linear preference for bins that remain versatile afterwards.
    if post > 0.0 {
        score += 0.3 * (cap / post).ln().max(0.0) * 0.1;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class: post_residual bucketed by integer division (waste classes)
    let post_class = post_residual / 10;
    score += (post_class as f64).powi(2) * 2.0;

    // Reward near-perfect fits (post_residual in {0..=5} is nearly dead space but good)
    if post_residual <= 5 {
        score -= 12.0;
    }
    // Penalize awkward mid-range residuals (11..19 hard to fill)
    if post_residual >= 11 && post_residual <= 19 {
        score += 8.0;
    }

    // Modulo arithmetic on capacity fractions: residual mod 25 as harmonic phase
    let phase = post_residual % 25;
    score += phase as f64 * 0.3;

    // Lookahead coupling: if next item fits exactly into post_residual, big reward
    if next_item_size > 0 && next_item_size <= post_residual {
        score -= 6.0;
        if post_residual - next_item_size <= 5 {
            score -= 6.0;
        }
    } else if next_item_size > 0 {
        // next item cannot use leftover: leftover likely wasted
        score += (post_residual as f64) * 0.15;
    }

    // Last-chance bin: strongly prefer using it over opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate: penalize opening a new bin unless current bins are very full
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score += 25.0 - 20.0 * progress;
        if mean_residual < 30.0 && fitting_bins_count > 0 {
            score += 10.0;
        }
    }

    // Prefer tighter bins overall (deviation from mean residual)
    score += ((bin_residual as f64) - mean_residual).abs() * 0.2;

    // Slight preference for bins with small residual (best-fit bias)
    score += (bin_residual as f64) * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap_f = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Dead-space avoidance: strong tiered bonuses (borrowed from best-known)
    if post_residual == 0 {
        score -= 1180.0;
    } else if post_residual <= 3 {
        score -= 500.0;
    } else if post_residual <= 12 {
        score -= 98.0;
    } else if post_residual < 20 {
        score += 18.0;
    } else if post_residual < 30 {
        score += 18.0 + (30 - post_residual) as f64 * 0.6;
    }

    // Lookahead for the next item
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 900.0;
        } else if next_item_size <= post_residual {
            let post2 = post_residual - next_item_size;
            score -= 135.0 - (post2 as f64) * 2.0;
            if post2 == 0 { score -= 110.0; }
            if post2 > 0 && post2 < 5 { score -= 28.0; }
            if post2 > 0 && post2 <= 2 { score -= 14.0; }
            if post2 % 10 == 0 && post2 > 0 { score -= 28.0; }
            if post2 >= 20 && post2 % 5 == 0 { score -= 12.0; }
            if post_residual % next_item_size == 0 { score -= 18.0; }
            if post_residual >= next_item_size * 2 && post_residual - next_item_size * 2 <= 4 { score -= 20.0; }
            let chain = post_residual / next_item_size;
            if chain >= 2 { score -= (chain.min(4)) as f64 * 6.0; }
            if post2 > 0 && post2 <= next_item_size / 4 { score -= 10.0; }
        } else {
            let gap = next_item_size - post_residual;
            if post_residual > 0 {
                if gap <= 3 { score += 35.0; }
                if gap <= 5 { score += (6 - gap) as f64 * 4.0; }
                else if gap <= 8 { score += 12.0; }
                if (gap as f64) > mean_residual * 0.5 { score += 14.0; }
                if post_residual < 15 { score += 45.0; }
                if post_residual as f64 > mean_residual * 1.4 { score -= 12.0; }
            }
            if post_residual % 10 == 0 && post_residual > 0 { score -= 15.0; }
        }
    }

    // Compaction pressure
    score += open_bins_count as f64 * 0.8;

    // Last-chance bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 45.0;
    }

    // NEW-BIN CANDIDATE handling
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let avg_fill = 1.0 - (mean_residual / cap_f);
        let newbin_waste = (bin_capacity - item_size) as f64;
        score += 250.0 - avg_fill * 330.0 - progress * 65.0;
        if item_size as f64 > mean_residual { score -= 45.0; }
        if item_size as f64 / cap_f > 0.85 && mean_residual > cap_f * 0.35 { score -= 40.0; }
        if item_size >= bin_capacity * 3 / 4 { score -= 55.0; }
        if bin_capacity - item_size <= 4 { score -= 70.0; }
        if next_item_size > 0 && next_item_size <= bin_capacity - item_size {
            let leftover = bin_capacity - item_size;
            let tail = leftover % next_item_size;
            if tail == 0 { score -= 30.0; }
            else if tail <= 4 { score -= 16.0; }
            if leftover - next_item_size <= 6 { score -= 38.0; }
        }
        if next_item_size > 0 && newbin_waste > 0.0 && (newbin_waste as u32) < next_item_size && newbin_waste < cap_f * 0.12 { score += 26.0; }
        if newbin_waste > 0.0 && newbin_waste < mean_residual * 0.6 { score -= 30.0; }
        if fitting_bins_count > 0 {
            score += (fitting_bins_count.min(5) as f64) * 9.0 + 20.0;
            let best_alt = if item_size <= mean_residual as u32 { mean_residual - item_size as f64 } else { mean_residual };
            if newbin_waste > best_alt + cap_f * 0.08 { score += 22.0; }
            if newbin_waste > best_alt + cap_f * 0.2 { score += 14.0; }
        }
        if progress > 0.6 {
            let waste_tol = (1.0 - progress) * cap_f * 0.35;
            if newbin_waste > waste_tol && fitting_bins_count > 0 { score += 10.0 + progress * 22.0; }
        }
    } else {
        // Open-bin refinement: dead-space ratio and tightness
        let tightness = 1.0 - (item_size as f64 / bin_residual.max(1) as f64);
        score += tightness * 85.0;
        score += (mean_residual - bin_residual as f64) * 1.5;
        let dead_ratio = post_residual as f64 / cap_f;
        if dead_ratio < 0.03 { score -= 38.0; }
        else if dead_ratio < 0.08 { score -= 14.0; }
        else if dead_ratio > 0.35 { score += 24.0; }
        else if dead_ratio > 0.25 { score += 10.0; }
        score += dead_ratio * 30.0;
        if item_size == bin_residual { score -= 45.0; }
        if next_item_size > 0 && post_residual > 0 {
            let unusable = post_residual < next_item_size && (next_item_size - post_residual) > 12;
            if unusable {
                score += dead_ratio * 90.0;
            } else {
                let reuse = (post_residual / next_item_size) as f64 * (next_item_size as f64 / cap_f);
                score -= reuse * 22.0;
            }
            let gap = (next_item_size as f64 - post_residual as f64) / next_item_size.max(1) as f64;
            if gap > 0.0 && gap < 0.12 { score -= 10.0; }
        }
        if post_residual > 0 && post_residual < 6 { score -= 22.0; }
        if post_residual > 0 && (post_residual as f64) < mean_residual * 0.25 { score -= 15.0; }
        if fitting_bins_count <= 2 && post_residual > 0 { score -= 8.0; }
        if post_residual > 0 && (post_residual as f64) < cap_f * 0.015 { score -= 18.0; }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residual gaps below the minimum item size
    // (assumed small threshold) are pure waste; penalize them quadratically.
    if post_residual < 10 {
        score += (10 - post_residual) as f64 * 40.0;
    } else if post_residual < 20 {
        // Small unusable-ish gaps get a mild penalty.
        score += (20 - post_residual) as f64 * 2.0;
    }

    // Reward tight fits (post_residual near zero but usable).
    if post_residual > 0 && post_residual <= 30 {
        score -= 15.0 * (1.0 - post_residual as f64 / 30.0);
    }

    // Last-chance bonus: if this is the only fitting bin, strongly prefer it
    // to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // Open-bin pressure: when many bins are open, discourage spreading into
    // fresh bins; when few bins are open, slightly favor consolidation.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += open_bins_count as f64 * 0.5 * (0.5 + 0.5 * progress);

    // Compare against mean residual: bins with much less residual than the
    // mean are already tight; prefer filling them further.
    score -= (mean_residual - bin_residual as f64) * 0.3;

    // Lookahead: if the next item fits exactly into the post_residual,
    // reward this placement strongly.
    if next_item_size > 0 && post_residual >= next_item_size {
        let slack = post_residual - next_item_size;
        if slack <= 10 {
            score -= 20.0;
        } else {
            score -= 6.0;
        }
    }

    // New-bin candidate: make it moderately expensive so it is only chosen
    // when no open bin offers a decent fit (post_residual would be too small).
    if bin_residual == bin_capacity {
        score += 55.0 + open_bins_count as f64 * 2.0;
        // If the item is huge relative to capacity, a fresh bin is natural.
        if item_size >= bin_capacity / 2 {
            score -= 20.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong reward for exact or near-exact fits (minimize dead space).
    if post_residual == 0 {
        score -= 500.0;
    } else if post_residual <= 5 {
        score -= 200.0;
    } else if post_residual <= 15 {
        score -= 60.0;
    }

    // 2-step lookahead: reward bins whose post_residual can host the next item.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 300.0;
        } else if post_residual >= next_item_size {
            let slack = (post_residual - next_item_size) as f64;
            score -= 80.0 - slack.min(80.0);
        } else {
            // Next item cannot fit here; penalize proportionally to wasted potential.
            let miss = (next_item_size - post_residual) as f64;
            score += miss.min(60.0);
        }
    }

    // Relative-to-mean coupling: prefer bins with less residual than average
    // (concentrate filling), but avoid over-penalizing already-tight bins.
    let res = post_residual as f64;
    let dev = res - mean_residual;
    score += 0.35 * dev.max(-40.0);

    // Last-chance bonus: if this is the only fitting bin, strongly prefer using it
    // over opening a new bin (unless the fit is terrible).
    if fitting_bins_count == 1 {
        score -= 45.0;
        if post_residual > 40 {
            score += 25.0; // very poor fit: soften the bonus
        }
    }

    // New-bin candidate handling: an empty bin has large post_residual;
    // penalize opening a new bin unless few bins are open or fit is bad everywhere.
    if bin_residual == bin_capacity {
        score += 30.0;
        if open_bins_count == 0 {
            score -= 1000.0; // must open the first bin
        }
        if fitting_bins_count == 0 {
            score -= 60.0; // no open bin fits: opening is fine
        }
        // Late in the stream, be more willing to open fresh bins for clean fits.
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score -= 20.0 * progress;
    }

    // Mild preference to spread across bins early, concentrate later.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += (1.0 - progress) * 5.0 * (open_bins_count as f64).ln().max(0.0);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit bonus
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Penalize wasted space relative to capacity
    let waste_ratio = post_residual as f64 / bin_capacity as f64;
    score += waste_ratio * 30.0;

    // Lookahead: penalize post_residual that cannot fit the next item (dead space)
    if next_item_size > 0 {
        if post_residual > 0 && post_residual < next_item_size {
            score += 25.0;
        }
        // Reward residual that exactly accommodates next item
        if next_item_size > 0 && post_residual == next_item_size {
            score -= 60.0;
        }
        // Reward residual that can still fit the next item snugly
        if post_residual >= next_item_size {
            let slack = (post_residual - next_item_size) as f64;
            score += slack * 0.15;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 80.0;
    }

    // Opening a new bin should be costly when many bins are open
    if bin_residual == bin_capacity {
        score += 40.0 + 5.0 * open_bins_count as f64;
        // But attractive if existing bins fit poorly
        score += (mean_residual - item_size as f64).abs() * 0.5;
    }

    // Encourage tight packing as the stream progresses
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= (1.0 - waste_ratio) * progress * 20.0;

    // Mild preference for bins with residuals close to item size (best-fit flavor)
    let fit_gap = (bin_residual - item_size) as f64;
    score += fit_gap * 0.3;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let post = post_residual as f64;

    let mut score = post;

    // Reward tight fits: squared normalized fill ratio, scaled by stream progress
    let fill = (bin_residual - post_residual) as f64 / cap;
    score -= 2.5 * fill * fill * (0.5 + progress);

    // Penalize dead space: small post_residual that is hard to reuse
    let dead = post / cap;
    if post > 0.0 {
        score += 3.0 * dead * (1.0 - dead) * (1.0 - progress);
    }

    // Last chance bin: strong bonus to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 8.0 + 4.0 * progress;
    }

    // Lookahead: reward bins whose post_residual can host the next item
    if next_item_size > 0 && post_residual >= next_item_size {
        let nx = next_item_size as f64 / cap;
        score -= 2.0 * nx * (0.5 + 0.5 * progress);
    } else if next_item_size > 0 {
        score += 1.5 * (1.0 - progress);
    }

    // Smooth coupling: prefer bins below mean residual early, above mean later
    let dev = (post - mean_residual) / cap;
    score += (1.0 - 2.0 * progress) * dev * 2.0;

    // Mild penalty for proliferating open bins late in stream
    score += (open_bins_count as f64).ln().max(0.0) * (1.0 - progress) * 0.5;

    // New-bin candidate: keep it attractive only for large items / poor fits
    if bin_residual == bin_capacity {
        score += 4.0 - 3.0 * progress;
        if fitting_bins_count <= 1 {
            score -= 6.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap_f = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Perfect / near-perfect fit: strongly reward.
    if post_residual == 0 {
        score -= 900.0;
    } else if post_residual <= 3 {
        score -= 400.0;
    } else if post_residual <= 12 {
        score -= 80.0;
    } else if post_residual < 20 {
        score += 14.0;
    } else if post_residual < 30 {
        score += 14.0 + (30 - post_residual) as f64 * 0.5;
    }

    // Lookahead: reward placements whose residual can host the next item.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 700.0;
        } else if next_item_size <= post_residual {
            let post2 = post_residual - next_item_size;
            score -= 100.0 - post2 as f64 * 1.8;
            if post2 == 0 { score -= 90.0; }
            if post2 > 0 && post2 < 5 { score -= 25.0; }
            if post2 >= 20 && post2 % 5 == 0 { score -= 10.0; }
            if post_residual % next_item_size == 0 { score -= 15.0; }
            if post2 > 0 && post2 <= next_item_size / 4 { score -= 10.0; }
            // chain potential: residual can host next item multiple times
            let chain = post_residual / next_item_size;
            if chain >= 2 { score -= (chain.min(4)) as f64 * 6.0; }
        } else {
            // next item won't fit here: penalize blocking residuals
            let gap = next_item_size as f64 - post_residual as f64;
            score += 18.0;
            if post_residual > 0 && gap <= 3.0 { score += 30.0; }
            if post_residual > 0 && gap <= 8.0 { score += 10.0; }
            if post_residual > 0 && post_residual < 15 { score += 40.0; }
            if post_residual as f64 > mean_residual * 1.4 { score -= 10.0; }
        }
    }

    // Dead-space penalties relative to capacity.
    if post_residual > 0 {
        let dead = post_residual as f64 / cap_f;
        if dead < 0.03 { score -= 30.0; }
        else if dead < 0.08 { score -= 12.0; }
        else if dead > 0.35 { score += 20.0; }
        else if dead > 0.25 { score += 8.0; }
        score += dead * 25.0;
    }

    // Last-chance bin: strongly favor using it.
    if fitting_bins_count == 1 {
        score -= 30.0;
    } else if fitting_bins_count > 1 {
        score += 2.0 * (fitting_bins_count.min(6) as f64 - 1.0);
    }

    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    // Global state: discourage spreading when many open bins hold slack.
    if open_bins_count > 3 && mean_residual > item_size as f64 {
        score += 0.05 * open_bins_count as f64;
    }

    // New-bin candidate logic.
    if bin_residual == bin_capacity {
        let avg_fill = 1.0 - mean_residual / cap_f;
        score += 220.0 - avg_fill * 300.0 - progress * 60.0;
        let newbin_waste = (bin_capacity - item_size) as f64;
        if item_size as f64 > mean_residual { score -= 40.0; }
        if fitting_bins_count > 0 {
            score += (fitting_bins_count.min(5) as f64) * 8.0 + 18.0;
            let snug = item_size as f64 / bin_residual.max(1) as f64;
            if snug > 0.9 { score += 35.0; }
            if snug > 0.95 { score += 25.0; }
        }
        if item_size >= bin_capacity * 3 / 4 { score -= 50.0; }
        if next_item_size > 0 && next_item_size <= bin_capacity - item_size {
            let leftover = bin_capacity - item_size;
            let tail = leftover % next_item_size;
            if tail == 0 { score -= 18.0; }
            else if tail <= 4 { score -= 12.0; }
        }
        if newbin_waste > 0.0 && (newbin_waste as u32) < next_item_size && newbin_waste < cap_f * 0.12 {
            score += 24.0;
        }
        // awkward fresh bin may pair better with next item
        if next_item_size > 0 && post_residual > 0 && next_item_size > post_residual {
            score -= 18.0;
        }
    } else {
        // Existing bin: prefer bins close to full.
        let tightness = 1.0 - item_size as f64 / bin_residual.max(1) as f64;
        score += tightness * 70.0;
        score += (mean_residual - bin_residual as f64) * 1.2;
        if item_size == bin_residual { score -= 40.0; }
        if post_residual > 0 && post_residual % 10 == 0 { score -= 8.0; }
        if post_residual > 0 && (post_residual as f64) < mean_residual * 0.25 { score -= 12.0; }
        if bin_residual as f64 > cap_f * 0.6 { score -= 10.0; }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: residues near multiples of common item
    // sizes (mod 10 classes) are more reusable than odd dead space.
    let pr = post_residual;
    if pr > 0 {
        let mod10 = (pr % 10) as f64;
        score += mod10 * 1.5; // ragged residue penalized
        // post_residual divisible by small classes (10/20/25) is reusable
        if pr % 10 == 0 { score -= 12.0; }
        if pr % 20 == 0 { score -= 6.0; }
        if pr % 25 == 0 { score -= 8.0; }
        // tiny dead space (< 10, nothing can fit later) is worst
        if pr < 10 { score += 25.0; }
        // exact-fill reward
        if pr == 0 { score -= 40.0; }
    }

    // Lookahead coupling: if next item fits exactly into post_residual, big reward
    if next_item_size > 0 {
        if next_item_size == pr {
            score -= 35.0;
        } else if next_item_size < pr {
            let slack = (pr - next_item_size) as f64;
            score += slack * 0.3;
            if (pr - next_item_size) % 10 == 0 { score -= 5.0; }
        } else {
            // next item won't fit here; mild penalty for wasting the slot
            score += 4.0;
        }
    }

    // Last-chance bin: strongly prefer using the only fitting bin
    if fitting_bins_count == 1 {
        score -= 30.0;
    }

    // Fullness fraction: favor tighter fills nonlinearly
    let fill = (bin_residual - post_residual) as f64 / cap;
    score -= fill * fill * 20.0;

    // New-bin candidate logic: opening a new bin is only attractive when open
    // bins have poor residuals relative to the item.
    if bin_residual == bin_capacity {
        // prefer new bin when mean residual can't hold item comfortably
        let mean_gap = mean_residual - item_size as f64;
        if mean_gap < 0.0 {
            score -= 15.0; // no open bin really fits well -> open new
        } else {
            score += mean_gap * 0.5; // decent fits exist -> discourage new bin
        }
        // late in stream, avoid proliferating bins
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += progress * 10.0;
        score += open_bins_count as f64 * 0.5;
    } else {
        // existing bins: slight preference for fuller ones via mean comparison
        if (bin_residual as f64) < mean_residual {
            score -= 3.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: tiny unusable gaps are the worst outcome.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    } else if post_residual >= 10 && post_residual < 20 {
        score += 25.0;
    } else if post_residual == 0 {
        // Perfect fit: strong reward.
        score -= 80.0;
    } else {
        // Larger usable leftovers are mildly good, scaled by usefulness.
        score -= (post_residual as f64).ln() * 6.0;
    }

    // Reward bins whose leftover can still host the lookahead item (k=2).
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 12.0;
    } else if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        // Leftover too small for the next item: dead space risk.
        score += 10.0;
    }

    // Last-chance bin: strongly favor using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 30.0;
    }

    // Open-bin pressure: with many open bins, discourage spreading to new bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += (open_bins_count as f64).powf(1.3) * 0.5 * (1.0 - progress);

    // Prefer bins tighter than average (consolidation of residuals).
    score += (mean_residual - bin_residual as f64) * 0.4;

    // New-bin candidate: only attractive if item is huge and no good fit exists.
    if bin_residual == bin_capacity {
        if item_size >= 70 && fitting_bins_count == 0 {
            score -= 20.0;
        } else {
            score += 15.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap_f = bin_capacity as f64;
    let mut score = post_residual as f64;
    let progress = step_index as f64 / total_items.max(1) as f64;

    // Perfect / near-perfect fits strongly rewarded.
    if post_residual == 0 {
        score -= 1200.0;
    } else if post_residual <= 3 {
        score -= 520.0;
    } else if post_residual <= 12 {
        score -= 100.0;
    } else if post_residual < 20 {
        score += 18.0;
    } else if post_residual < 30 {
        score += 18.0 + (30 - post_residual) as f64 * 0.6;
    }

    // Lookahead coupling with next item.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 950.0;
        } else if next_item_size <= post_residual {
            let post2 = post_residual - next_item_size;
            score -= 135.0 - post2 as f64 * 2.0;
            if post2 == 0 { score -= 110.0; }
            if post2 > 0 && post2 % 10 == 0 { score -= 28.0; }
            if post2 > 0 && post2 < 5 { score -= 28.0; }
            if post2 >= 20 && post2 % 5 == 0 { score -= 12.0; }
            if post_residual >= next_item_size * 2 && post_residual - next_item_size * 2 <= 4 { score -= 20.0; }
            if post_residual % next_item_size == 0 { score -= 18.0; }
            let chain = post_residual / next_item_size;
            if chain >= 2 { score -= chain.min(4) as f64 * 6.0; }
        } else {
            score += 20.0;
            let gap = next_item_size as f64 - post_residual as f64;
            if post_residual > 0 && post_residual < 15 { score += 45.0; }
            if gap <= 3.0 { score += 35.0; }
            else if gap <= 8.0 { score += 12.0; }
            if post_residual as f64 > mean_residual * 1.4 { score -= 12.0; }
            if post_residual > 0 && post_residual < next_item_size {
                score += (next_item_size as f64 - post_residual as f64) * 0.6;
                score += (1.0 - progress) * 14.0;
            }
        }
        if post_residual > 0 && post_residual >= next_item_size && post_residual % next_item_size <= 2 { score -= 8.0; }
    }

    // Dead-space ratio shaping.
    let dead_ratio = post_residual as f64 / cap_f;
    if post_residual > 0 {
        if dead_ratio < 0.03 { score -= 38.0; }
        else if dead_ratio < 0.08 { score -= 14.0; }
        else if dead_ratio > 0.35 { score += 24.0; }
        else if dead_ratio > 0.25 { score += 10.0; }
        score += dead_ratio * 30.0;
        if post_residual < 6 { score -= 22.0; }
        if post_residual % 10 == 0 { score -= 10.0; }
        if post_residual % 5 == 0 && post_residual <= 30 { score -= 8.0; }
        if (post_residual as f64) < cap_f * 0.015 { score -= 18.0; }
        if next_item_size > 0 && post_residual < next_item_size && post_residual < bin_capacity / 10 {
            score += (25u32.min(post_residual)).max(1) as f64 * 1.2;
        }
    }

    // Last-chance bonus.
    if fitting_bins_count == 1 && post_residual > 0 { score -= 25.0; }
    if fitting_bins_count <= 2 && post_residual > 0 { score -= 8.0; }

    // New-bin candidate evaluation.
    if bin_residual == bin_capacity {
        let avg_fill = 1.0 - (mean_residual / cap_f);
        score += 250.0 - avg_fill * 330.0 - progress * 65.0;
        let leftover = bin_capacity - item_size;
        if item_size as f64 > mean_residual { score -= 45.0; }
        if leftover <= 4 { score -= 70.0; }
        if item_size >= bin_capacity * 3 / 4 { score -= 55.0; }
        if next_item_size > 0 && next_item_size >= bin_capacity / 2 { score -= 32.0; }
        if next_item_size > 0 && next_item_size <= leftover { score -= 25.0; }
        if fitting_bins_count > 0 {
            score += fitting_bins_count.min(5) as f64 * 9.0 + 20.0;
            let snug = item_size as f64 / bin_residual.max(1) as f64;
            if snug > 0.9 { score += 40.0; }
            if snug > 0.95 { score += 28.0; }
            if snug > 0.98 { score += 18.0; }
        }
        if next_item_size > 0 {
            if leftover >= next_item_size {
                let tail = leftover % next_item_size;
                if tail <= 4 { score -= 16.0; }
                if tail == 0 { score -= 10.0; }
            } else if leftover < 10 {
                score += 18.0;
            }
        }
        let newbin_waste = leftover as f64;
        if newbin_waste > 0.0 && newbin_waste < mean_residual * 0.6 { score -= 30.0; }
        if fitting_bins_count > 0 {
            let best_alt = if item_size as f64 <= mean_residual { mean_residual - item_size as f64 } else { mean_residual };
            if newbin_waste > best_alt + cap_f * 0.08 { score += 22.0; }
            if newbin_waste > best_alt + cap_f * 0.2 { score += 14.0; }
        }
        if progress > 0.6 {
            let waste_tol = (1.0 - progress) * cap_f * 0.35;
            if newbin_waste > waste_tol && fitting_bins_count > 0 { score += 10.0 + progress * 22.0; }
        }
        if newbin_waste > 0.0 && leftover < next_item_size && newbin_waste < cap_f * 0.12 { score += 26.0; }
    } else {
        // Open-bin fit quality.
        let tightness = 1.0 - (item_size as f64 / bin_residual.max(1) as f64);
        score += tightness * 85.0;
        score += (mean_residual - bin_residual as f64) * 1.5;
        if item_size == bin_residual { score -= 45.0; }
        if bin_residual as f64 > cap_f * 0.6 { score -= 12.0; }
        if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
            let gap = next_item_size as f64 - post_residual as f64;
            if gap < 0.12 * next_item_size as f64 { score -= 10.0; }
            if gap > mean_residual * 0.6 && fitting_bins_count > 2 { score += gap * 0.8; }
        }
        if next_item_size > 0 && post_residual > 0 && post_residual >= next_item_size && (post_residual as f64) < mean_residual * 0.7 {
            score -= 6.0;
        }
        if post_residual > 0 && (post_residual as f64) < mean_residual * 0.25 { score -= 15.0; }
        if next_item_size > 0 && post_residual > 0 && post_residual + next_item_size <= bin_capacity && (post_residual as f64) < mean_residual * 0.5 {
            score -= 9.0;
        }
    }

    // Mild penalty for many open bins with poor mean residual.
    if mean_residual > cap_f * 0.6 && open_bins_count > 3 { score += 3.0; }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: small post_residual is already favored by the base term.

    // 2-step lookahead: if the next item fits into the post-residual, reward this bin.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 12.0 + 0.35 * next_item_size as f64;
    } else if next_item_size > 0 {
        // Penalize leaving dead space the next item can't use.
        score += 0.25 * post_residual as f64;
    }

    // Perfect match: post_residual exactly equals next item size.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 15.0;
    }

    // Relative-to-mean coupling: bins with residual far below mean are tighter fits;
    // reward placing into them (they are the scarce space), penalize loose bins.
    let dev = mean_residual - post_residual as f64;
    score += 0.15 * dev;

    // Last-chance bin: if this is the only bin that fits, strongly favor using it.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 20.0;
    }

    // New-bin candidate handling: penalize opening a new bin unless the item is large
    // relative to capacity or existing bins are crowded.
    if bin_residual == bin_capacity {
        let crowded = mean_residual < 0.5 * bin_capacity as f64;
        if !crowded {
            score += 30.0;
        } else {
            score += 5.0;
        }
        if next_item_size > 0 && post_residual >= next_item_size {
            score -= 8.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
