    let mut score = post_residual as f64;
    let progress = step_index as f64 / total_items.max(1) as f64;
    let post = post_residual;
    let quarter = bin_capacity / 4;
    let half = bin_capacity / 2;

    // Perfect fit: dominate all scores.
    if post == 0 {
        score -= 1200.0;
        return score;
    }

    // Dead-space class penalties, sharpened near zero.
    if post <= 3 {
        score -= 500.0;
    } else if post <= 12 {
        score -= 98.0;
    } else if post < quarter {
        score += 30.0;
        if next_item_size > post {
            score += 20.0;
        }
    } else if post < half {
        score += 5.0;
    } else {
        score -= 10.0;
    }

    // Divisibility bonuses.
    if post % 10 == 0 {
        score -= 8.0;
    }
    if post % 20 == 0 {
        score -= 4.0;
    }

    // Lookahead coupling with exact-match reward.
    if next_item_size > 0 {
        if next_item_size == post {
            score -= 900.0;
        } else if next_item_size <= post {
            let slack = post - next_item_size;
            if slack < quarter {
                score -= 15.0;
            } else {
                score -= 3.0;
            }
            if post % next_item_size == 0 {
                score -= 18.0;
            }
            if slack > 0 && slack <= 2 {
                score -= 14.0;
            }
        } else {
            score += 10.0;
            let gap = (next_item_size - post) as f64;
            if gap <= 3.0 {
                score += 35.0;
            } else if gap <= 8.0 {
                score += 12.0;
            }
            if post < 15 {
                score += 45.0;
            }
            if post as f64 > mean_residual * 1.4 {
                score -= 12.0;
            }
        }
    }

    // Last-chance bonus.
    if fitting_bins_count == 1 {
        score -= 25.0;
    }

    // New-bin candidate handling.
    if bin_residual == bin_capacity {
        let avg_fill = 1.0 - (mean_residual / cap_f);
        score += 250.0 - avg_fill * 330.0 - progress * 65.0;
        let newbin_waste = (bin_capacity - item_size) as f64;

