            let chain = post_residual / next;
            if chain >= 2 { score -= (chain.min(4)) as f64 * 5.0; }
        }
        if post_residual > 0 && (post_residual as f64) < mean_residual * 0.25 { score -= 12.0; }
        if post_residual > 0 && (post_residual as f64) < cap_f * 0.015 { score -= 15.0; }
        if post_residual > 0 && post_residual % 5 == 0 && post_residual <= 30 { score -= 6.0; }
        if fitting_bins_count <= 2 && post_residual > 0 { score -= 6.0; }
        if next > 0 && post_residual > 0 && post_residual >= next && (post_residual % next) <= 2 { score -= 6.0; }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Normalize post-residual as fraction of capacity
    let frac = post_residual as f64 / bin_capacity as f64;

    // Penalize dead space non-linearly: small residuals are precious
    if post_residual > 0 {
        score += 40.0 * frac.powf(2.5);
    } else {
        // Perfect fill reward
        score -= 60.0;
    }

    // Last-chance bonus: if this is the only fitting bin, strongly prefer using it
    if fitting_bins_count == 1 {
        score -= 35.0;
    }

    // Lookahead: reward if the next item fits in the post-residual
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 25.0 * (next_item_size as f64 / bin_capacity as f64);
        } else {
            // Penalize creating residual that can't serve the next item,
            // scaled by how much is wasted
            let waste = (post_residual as f64).min(next_item_size as f64);
            score += 15.0 * (waste / bin_capacity as f64);
        }
    }

    // Prefer bins whose residual is close to the item (tight fit)
    let tightness = (bin_residual as f64 - item_size as f64).abs() / bin_capacity as f64;
    score -= 20.0 * (1.0 - tightness);

    // Global state: when many bins are open, prefer filling existing ones
    // over opening new ones; when few bins are open, opening is cheaper.
    let openness = open_bins_count as f64 / (total_items.max(1) as f64).sqrt().max(1.0);
    if bin_residual == bin_capacity {
        // New-bin candidate: penalize more when many bins already open
        score += 30.0 + 10.0 * openness;
        // But if mean residual is small (open bins nearly full), new bin is fine
        score -= 20.0 * (mean_residual / bin_capacity as f64).min(1.0);
    } else {
        // Reward using existing bins slightly more as stream progresses
        let progress = step_index as f64 / total_items.max(1) as f64;
        score -= 8.0 * progress;
    }

    // Coupling: avoid leaving residuals just below common small-item sizes
    for s in [10u32, 20, 30, 40, 50] {
        if post_residual >= s && post_residual < s + 5 {
            score -= 6.0; // residual still useful for typical small items
        }
    }
    if post_residual > 0 && post_residual < 10 {
        score += 25.0; // tiny unusable sliver
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;

    // Non-linear polynomial coupling of post_residual with stream progress
    let mut score = pr * (1.0 + 0.8 * progress * progress);

    // Penalize large residuals more as stream advances (dead space becomes costlier)
    score += 60.0 * norm_pr * norm_pr * (0.5 + progress);

    // Reward tight fits (small post_residual), stronger late in stream
    score -= 25.0 * (1.0 - norm_pr) * (1.0 - norm_pr) * (0.4 + 0.6 * progress);

    // Exact fit bonus
    if post_residual == 0 {
        score -= 50.0;
    }

    // Last-chance bin bonus: avoid opening a new bin when this is the only fitting one
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0 * (1.0 - progress);
    }

    // Lookahead: reward if next item fits into post_residual
    if next_item_size > 0 && post_residual >= next_item_size {
        let slack = (post_residual - next_item_size) as f64;
        score -= 20.0 * (1.0 - slack / cap) * (1.0 + progress);
    } else if next_item_size > 0 {
        score += 10.0 * progress;
    }

    // Penalty for scattering across many open bins with high mean residual
    score += 0.5 * open_bins_count as f64 * (mean_residual / cap).max(0.0) * (1.0 - progress);

    // New-bin candidate: mildly discourage unless residual is small (poor fits elsewhere)
    if bin_residual == bin_capacity {
        score += 15.0 * (1.0 - progress) - 20.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: modulo-10 class structure
    let pr = post_residual;
    let class = pr % 10;
    // Dead-space classes: residuals 1..9 are nearly useless for items >=10;
    // residual class 0 is perfect (exact fit or clean multiple).
    if pr == 0 {
        score -= 60.0; // perfect closure
    } else if pr < 10 {
        score += 25.0; // tiny dead space, unusable
    } else {
        // reward residuals that are "clean" fractions of capacity
        if pr % 20 == 0 { score -= 12.0; }
        else if pr % 10 == 0 { score -= 6.0; }
        else if class >= 5 { score += 4.0; }
    }

    // Lookahead coupling: does post_residual still admit next_item_size?
    if next_item_size > 0 {
        if pr >= next_item_size {
            // slack left for the next item: reward proportionally
            let slack = (pr - next_item_size) as f64;
            score -= 8.0 + 4.0 * (1.0 - slack / bin_capacity as f64);
            // harmonic bonus if post_residual is exactly next_item_size class
            if pr == next_item_size { score -= 10.0; }
        } else {
            // this placement strands the next item's fit here
            score += 15.0;
        }
    }

    // Last-chance bin: strongly favor using the only bin that fits
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate: penalize mildly so it's chosen only when
    // open bins create bad dead space; scale with stream progress.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score = bin_capacity as f64 - 20.0 - 15.0 * progress;
        if next_item_size > 0 && next_item_size >= bin_capacity {
            score -= 40.0; // next item needs a fresh bin anyway
        }
    }

    // Mild pressure to prefer fuller bins as open bin count grows
    score += (open_bins_count as f64).ln() * 1.5;

    // Tie-break: prefer bins whose residual is far from mean (compact set)
    score += 0.05 * (bin_residual as f64 - mean_residual).abs();

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: tiny gaps are unusable (min item is 1..100 here,
    // but gaps far below the mean item size are hard to fill).
    if post_residual > 0 {
        // Penalize very small post residuals heavily (dead space).
        if post_residual <= 5 {
            score += 60.0;
        } else if post_residual <= 10 {
            score += 30.0;
        } else if post_residual <= 20 {
            score += 12.0;
        }
        // Reward large usable residuals mildly (they stay flexible).
        if post_residual >= 50 {
            score -= 8.0;
        }
    } else {
        // Perfect fit: strongly favored.
        score -= 100.0;
    }

    // Reward tight fits relative to bin residual.
    let fill_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 25.0 * fill_ratio;

    // Last-chance bin: if this is the only bin that fits, strongly prefer using it.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 45.0;
    }

    // Open-bin pressure: many open bins -> discourage spreading, prefer new bin only when needed.
    score += (open_bins_count as f64).sqrt() * 2.0;

    // New-bin candidate handling: empty bin has residual == capacity.
    if bin_residual == bin_capacity {
        // Default mild penalty so we prefer reusing bins with good fits.
        score += 15.0;
        // But if no open bin fits well (this call means it's an option), and item is large,
        // opening a fresh bin is attractive for large items.
        if item_size >= 70 {
            score -= 40.0;
        } else if item_size >= 51 {
            score -= 15.0;
        }
        // Early in the stream, opening bins is cheaper.
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score -= 10.0 * (1.0 - progress);
    }

    // Lookahead: if next item fits exactly into the post residual, reward this placement.
    if next_item_size > 0 && post_residual >= next_item_size {
        if post_residual == next_item_size {
            score -= 50.0;
        } else if post_residual - next_item_size <= 10 {
            score -= 25.0;
        }
    }
    // Penalize if post residual is smaller than next item but nonzero (dead space for lookahead).
    if next_item_size > post_residual && post_residual > 0 {
        score += 10.0;
    }

    // Mean residual coupling: prefer bins whose residual is below mean (tighter bins fill first).
    let bin_res_f = bin_residual as f64;
    if mean_residual > 0.0 && bin_residual != bin_capacity {
        score += (bin_res_f - mean_residual) * 0.15;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Aggressive 2-step lookahead: reward exact/near match of post_residual to next item.
    if next_item_size > 0 {
        let gap = (post_residual as i64 - next_item_size as i64).abs() as f64;
        // Exact match is highly rewarded (item+next fill the bin perfectly).
        if post_residual == next_item_size {
            score -= 60.0;
        } else if post_residual > next_item_size {
            // Next item fits: reward closeness, penalize leftover slack quadratically.
            score -= 25.0 * (1.0 - gap / bin_capacity as f64);
            score += (gap * gap) / 50.0;
        } else {
            // Next item won't fit in the slack; mildly penalize large dead space.
            score += gap * 0.15;
        }
    }

    // Prefer tight fits relative to mean residual across open bins.
    score -= 0.5 * (mean_residual - post_residual as f64);

    // Last-chance bin: strong bonus to avoid opening a new bin needlessly.
    if fitting_bins_count == 1 {
        score -= 15.0;
    }

    // New-bin candidate: only attractive when current fit is terrible (huge dead space)
    // or late in stream with few open bins; otherwise penalize opening bins.
    if bin_residual == bin_capacity {
        let waste = post_residual as f64;
        let poor_fit = (waste > 40.0) as i32 as f64;
        score += 20.0; // base penalty for opening a new bin
        score -= poor_fit * 25.0;
        if next_item_size > 0 && waste <= next_item_size as f64 {
            score -= 10.0; // fresh bin guarantees lookahead fit
        }
    }

    // Small progression coupling: slightly prefer reusing bins later in the stream.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    if bin_residual != bin_capacity {
        score -= 2.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Progress through the stream: early on, be more exploratory (favor filling
    // existing bins less aggressively); late, squeeze hard.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    // Exact fit is always perfect.
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Tightness: fraction of bin used by this placement.
    let tightness = item_size as f64 / bin_capacity as f64;
    score -= 40.0 * tightness;

    // Penalize dead space non-linearly: small residuals that can't fit typical
    // future items (>=10) are wasted.
    if post_residual > 0 {
        let dead = (post_residual as f64).powf(1.5);
        score += 0.8 * dead;
        if post_residual < 10 {
            score += 30.0; // unusable sliver
        }
    }

    // Lookahead: reward if next item fits exactly in post_residual.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 250.0;
        } else if post_residual >= next_item_size {
            score -= 30.0 * (next_item_size as f64 / bin_capacity as f64);
        } else {
            // Next item won't fit here; penalize proportionally to leftover gap.
            score += 0.5 * (next_item_size as f64 - post_residual as f64).max(0.0);
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 120.0;
    }

    // New-bin candidate: usually worse than reusing an existing bin, unless the
    // item is large and mean residual across open bins is small.
    if bin_residual == bin_capacity {
        score += 150.0;
        // Exploration early: allow opening bins when few are open.
        score -= 60.0 * (1.0 - progress);
        // If existing bins are nearly full anyway, new bin is fine.
        score -= 1.5 * (bin_capacity as f64 - mean_residual).max(0.0);
        // Large items prefer fresh bins.
        score -= 0.5 * item_size as f64;
    }

    // Crowding: with many open bins, prefer consolidating into existing ones.
    score += 2.0 * open_bins_count as f64 * progress;

    // Mean residual coupling: bins with residual far below mean are "odd";
    // prefer keeping residual distribution compact.
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += 0.3 * dev;

    // Late-stream urgency: minimize residual aggressively at the end.
    score += 20.0 * progress * (post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
