pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = (step_index as f64 / total_items.max(1) as f64).clamp(0.0, 1.0);
    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;

    // Base: post residual, slightly discounted as stream progresses
    let mut score = pr * (1.0 - 0.35 * progress);

    // Reward tight fits (low post residual relative to capacity) smoothly
    score -= (1.0 - pr / cap).powi(3) * 18.0;

    // Penalize large dead space non-linearly, stronger late in stream
    let dead = (pr / cap).powi(2);
    score += dead * 25.0 * (0.5 + 0.5 * progress);

    // Last-chance bonus: strongly prefer the only fitting bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // Lookahead coupling: if next item fits the post residual, reward
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if nxt <= pr {
            score -= 12.0 * (1.0 - (pr - nxt) / cap);
        } else {
            score += 8.0 * ((nxt - pr) / cap).powi(2);
        }
    }

    // Mild penalty when bin residual deviates from mean residual (keep balance)
    score += ((bin_residual as f64 - mean_residual) / cap).abs() * 5.0;

    // Slight preference for using existing bins over opening new ones
    if bin_residual == bin_capacity {
        score += 6.0 + 4.0 * (1.0 - progress);
    }

    // Smooth polynomial coupling of fit ratio and progress
    score += fit_ratio.powi(2) * 10.0 * (1.0 - progress);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: capacity divided into fifths.
    let fifth = bin_capacity / 5;
    let class = post_residual / fifth;
    match class {
        0 => score -= 12.0,                    // near-perfect fit
        1 => score -= 4.0,                     // good fit
        2 => {}                                // neutral
        3 => score += 6.0,                     // poor
        _ => score += 12.0,                    // wasteful
    }

    // Penalize dead space that no plausible item (>=10) can ever use.
    if post_residual < 10 && post_residual > 0 {
        score += 25.0;
    }
    if post_residual == 0 {
        score -= 30.0;
    }

    // Lookahead coupling: does post_residual still serve the next item?
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 8.0;
            // harmonic bonus if next item lands in same class boundary
            if (post_residual - next_item_size) / fifth == 0 {
                score -= 6.0;
            }
        } else {
            score += 5.0;
        }
    }

    // Last-chance bin: strongly prefer using it before opening a new one.
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // New-bin candidate: only attractive when open bins are fragmented.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let fragmentation = mean_residual / bin_capacity as f64;
        let threshold = 0.35 - 0.15 * progress;
        if fragmentation < threshold && open_bins_count > 0 {
            score -= 18.0;
        } else {
            score += 15.0;
        }
    }

    // Mild pressure against hoarding many open bins.
    score += open_bins_count as f64 * 0.3;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Exact fit: overwhelmingly favored.
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Dead-space avoidance: small leftover gaps are unusable for typical items.
    if post_residual > 0 && post_residual < 10 {
        score += (10 - post_residual) as f64 * 15.0; // tight-but-wasted gap penalty
    }

    // Penalize large residual waste relative to capacity (poor density).
    let fill_ratio = item_size as f64 / bin_capacity as f64;
    score -= fill_ratio * 20.0; // reward placing into bins where item fills a big chunk

    // If the leftover gap could still fit the next item, mild reward.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 8.0;
        // Extra reward if next item would then fit almost exactly (chained fit).
        let chain_gap = post_residual - next_item_size;
        if chain_gap < 10 {
            score -= 12.0;
        }
    } else if next_item_size > 0 {
        // leftover cannot host next item: penalize proportionally to gap smallness
        if post_residual > 0 && post_residual < next_item_size as f64 * 0.5 {
            score += 10.0;
        }
    }

    // Last-chance bin: if this is the only bin that fits, strongly prefer using it.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate handling: opening a new bin is only attractive when
    // open-bin pressure is high or the fit into existing bins is poor.
    if bin_residual == bin_capacity {
        // Base hesitation: prefer existing bins slightly.
        score += 5.0;
        // More open bins -> more willing to open a fresh one (spread load).
        score -= (open_bins_count as f64).ln().max(0.0) * 4.0;
        // Late in the stream, opening new bins is safer than fragmenting.
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score -= progress * 10.0;
        // If mean residual across open bins is small (all bins tight), new bin is good.
        if mean_residual < item_size as f64 {
            score -= 20.0;
        }
    } else {
        // Existing bin: penalize if its residual deviates badly from mean (fragmentation).
        let dev = (bin_residual as f64 - mean_residual).abs();
        score += dev * 0.3;
        // Prefer bins with tighter residuals (best-fit flavor) beyond raw post_residual.
        score += (bin_residual as f64) * 0.1;
    }

    // Mild pressure: many open bins -> prefer consolidation into existing bins.
    score += open_bins_count as f64 * 0.5;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong reward for exact-ish fits (small dead space)
    if post_residual == 0 {
        score -= 1000.0;
    } else if post_residual <= 5 {
        score -= 200.0;
    } else if post_residual <= 15 {
        score -= 50.0;
    }

    // 2-step lookahead: reward if next item fits perfectly in the post residual
    if next_item_size > 0 {
        let nr = next_item_size as f64;
        let pr = post_residual as f64;
        if post_residual == next_item_size {
            score -= 500.0; // perfect chain
        } else if post_residual > next_item_size {
            let slack = pr - nr;
            if slack <= 10.0 {
                score -= 250.0 - slack * 10.0; // near-perfect chain
            } else {
                score -= 30.0; // next item fits, mild bonus
            }
        } else {
            // next item cannot fit here; penalize proportionally to waste
            score += (nr - pr) * 0.5;
        }
    }

    // Relative to mean residual: prefer bins that are already tight (below mean)
    let pr = post_residual as f64;
    if mean_residual > 0.0 {
        score += (pr - mean_residual) * 0.3;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 120.0;
    }

    // Penalize opening a new bin when decent alternatives exist,
    // but allow it when this bin would be a perfect fit anyway.
    if bin_residual == bin_capacity {
        if next_item_size > 0 && post_residual >= next_item_size && post_residual <= next_item_size + 10 {
            score -= 50.0; // fresh bin sets up a good chain
        } else {
            score += 150.0 + (open_bins_count as f64) * 5.0;
        }
    }

    // Late-stream consolidation: prefer filling existing bins tighter as stream ends
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= progress * 20.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
