        }
        if progress > 0.6 {
            let waste_tol = (1.0 - progress) * cap_f * 0.35;
            if newbin_waste > waste_tol && fitting_bins_count > 0 {
                score += 10.0 + progress * 20.0;
            }
        }
        if progress < 0.1 { score -= 5.0; }
    }

    // Mild progress-based diversity nudge for open bins
    if progress < 0.1 { score += 3.0; }

    // Prefer bins whose residual is below average (consolidating slack)
    if bin_residual < bin_capacity {
        score += (mean_residual - bin_residual as f64) * 1.2;
        let dead_ratio = post_residual as f64 / cap_f;
        if dead_ratio < 0.03 { score -= 30.0; }
        else if dead_ratio > 0.35 { score += 20.0; }
        else if dead_ratio > 0.25 { score += 10.0; }
        if item_size == bin_residual { score -= 40.0; }
        if post_residual > 0 && next_item_size > 0 && post_residual < next_item_size {
            let wasted = (next_item_size - post_residual) as f64;
            score += wasted * 0.6;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tight fits are excellent: reward low post residual non-linearly.
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 12.0 * tightness * tightness;

    // Penalize dead space that no plausible future item can use.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0; // small unusable slivers are wasted capacity
    }

    // Lookahead: if the next item fits exactly into post_residual, strong reward.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 30.0;
        } else if next_item_size < post_residual {
            let slack = (post_residual - next_item_size) as f64;
            score -= 8.0 * (1.0 - slack / bin_capacity as f64);
        } else {
            // next item cannot follow here; slight penalty proportional to gap
            score += 0.05 * ((next_item_size - post_residual) as f64);
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 20.0;
    }

    // Crowding: when many bins are open, prefer filling existing ones.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 0.3 * open_bins_count as f64 * (0.5 + 0.5 * progress);

    // Prefer bins whose residual is already below average (consolidation).
    if mean_residual > 0.0 {
        let diff = (post_residual as f64 - mean_residual) / mean_residual;
        score += 5.0 * diff;
    }

    // New-bin candidate handling: make an empty bin attractive only when
    // no open bin offers a decent fit (item nearly fills a fresh bin, or
    // the item would leave an awkward gap everywhere).
    if bin_residual == bin_capacity {
        let fill_ratio = item_size as f64 / bin_capacity as f64;
        if fill_ratio > 0.85 || (fitting_bins_count == 0) {
            score -= 15.0;
        } else {
            score += 10.0 + 20.0 * (1.0 - fill_ratio);
        }
    }

    // Mild time pressure: later in the stream, be greedier about tight fits.
    score -= 4.0 * progress * tightness;

    score
}

