pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let r = post_residual as f64;
    let cap = bin_capacity as f64;
    let rn = r / cap;

    // Base: prefer small post residual, with smooth non-linear shaping
    let mut score = r
        + 20.0 * rn * rn
        + 8.0 * rn * rn * rn;

    // Polynomial coupling of residual with stream progress:
    // early on tolerate larger residuals slightly; late in stream penalize dead space harder
    let prog_coupling = 1.0 + 2.0 * progress * (1.0 - progress) * 0.5 + 1.5 * progress * progress;
    score *= prog_coupling;

    // Reward tight fits (post residual near zero) with smooth quadratic bonus
    let tightness = (cap - r) / cap; // fill fraction
    score -= 15.0 * tightness * tightness * (0.5 + progress);

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 {
        score -= 25.0;
    }

    // Lookahead: penalize leaving residual that cannot fit next item
    if next_item_size > 0 {
        let fits_next = if r >= next_item_size as f64 { 1.0 } else { 0.0 };
        score += (1.0 - fits_next) * (5.0 + 10.0 * progress);
        // smooth bonus if post residual still fits next item
        let post_fits = if post_residual as f64 >= next_item_size as f64 { 1.0 } else { 0.0 };
        score -= post_fits * 6.0 * (1.0 - progress);
    }

    // Slight penalty when many bins already open (discourage bin proliferation)
    score += (open_bins_count as f64).ln() * (1.0 + progress);

    // Distance of residual from mean residual: prefer bins making residual typical
    let dev = (r - mean_residual).abs() / cap;
    score += 3.0 * dev * dev;

    score
}

