pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: dead space in (0..10) is nearly unusable
    // for future items (min item size 10), while multiples of 10 are "harmonic".
    let dead = post_residual.min(9) as f64;
    score += dead * 6.0;

    // Exact fill is perfect.
    if post_residual == 0 {
        score -= 200.0;
    }

    // Harmonic classes: post_residual divisible by 10 leaves clean reusable space.
    if post_residual % 10 == 0 && post_residual > 0 {
        score -= 12.0;
    }
    // Penalize awkward classes (residuals mod 10 in 1..9 already handled by dead bonus,
    // but add mild penalty for residuals just above a harmonic gap).
    let r = post_residual % 10;
    if r >= 1 && r <= 5 {
        score += 4.0;
    }

    // Lookahead: reward if next item fits exactly in the post residual.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 90.0;
        } else if next_item_size <= post_residual {
            score -= 25.0;
            // harmonic match: next item leaves a multiple-of-10 residual again
            if (post_residual - next_item_size) % 10 == 0 {
                score -= 15.0;
            }
        } else {
            // next item cannot use this bin's leftover: penalize large leftovers
            score += (post_residual as f64) * 0.15;
        }
    }

    // Last chance: if this is the only fitting bin, strongly prefer using it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 60.0;
