    score -= 0.5 * (item_size as f64 / bin_capacity as f64);

    // Open-bin pressure: discourage spreading across many bins unless fit is tight.
    score += 0.8 * open_bins_count as f64;

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // Lookahead: if the next item fits exactly in the post residual, reward this placement.
    if next_item_size > 0 && post_residual >= next_item_size {
        let slack = post_residual - next_item_size;
        if slack < 10 {
            score -= 20.0;
        } else {
            score -= 5.0;
        }
    } else if next_item_size > post_residual && post_residual > 0 {
        // Next item cannot use the leftover: penalize creating stranded space.
        score += 8.0;
    }

    // Mean residual coupling: prefer bins below mean residual (tighter bins first).
    score += 0.3 * (mean_residual - post_residual as f64);

    // New-bin candidate handling: only attractive when no open bin fits well
    // or the stream is early and consolidation pressure is high.
    if bin_residual == bin_capacity {
        if fitting_bins_count == 0 {
            score -= 100.0; // no alternative: new bin is correct
        } else {
            // make new bin unattractive unless open bins are very fragmented
            score += 15.0 + 1.5 * open_bins_count as f64;
            if mean_residual < 15.0 {
                score -= 20.0; // open bins nearly full, better to open fresh
            }
        }
    }

    // Mild stream-position adaptation: later in stream, be slightly more conservative.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += 3.0 * progress;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Aggressive 2-step lookahead: reward exact/near match of post_residual with next item.
    if next_item_size > 0 {
        let diff = (post_residual as i64 - next_item_size as i64).abs() as f64;
        // Exact match: strong reward.
        if post_residual == next_item_size {
            score -= 25.0;
        } else if post_residual >= next_item_size {
            // Next item fits in the leftover: scale reward by closeness.
            score -= 15.0 * (1.0 - diff / bin_capacity as f64);
        } else {
            // Leftover too small for next item: penalize dead space proportionally.
            score += 5.0 + 10.0 * (next_item_size as f64 - post_residual as f64) / bin_capacity as f64;
        }
    }

    // Compare post_residual to mean residual across open bins:
    // leaving a residual near the mean keeps flexibility; extremes are penalized.
    let dev = (post_residual as f64 - mean_residual).abs();
    score += 0.3 * dev;

    // Penalize very large post_residual (wasteful use of a big bin for a small item),
    // unless it sets up an exact match with the next item.
    if post_residual as f64 > mean_residual * 1.5 && next_item_size == 0 {
        score += 8.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 12.0;
    }

    // Early in the stream, slightly prefer consolidating into fewer bins.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    if open_bins_count > 4 && progress < 0.5 {
        score += 2.0 * (open_bins_count as f64 / 10.0);
    }

    // Perfect fill reward.
    if post_residual == 0 {
        score -= 20.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap_f = bin_capacity as f64;
    let progress = step_index as f64 / total_items.max(1) as f64;
    let mut score = post_residual as f64;

    // Tiered dead-space avoidance (strengthened, borrowed from best)
    if post_residual == 0 {
        score -= 900.0;
    } else if post_residual <= 3 {
        score -= 420.0;
    } else if post_residual <= 12 {
        score -= 90.0;
    } else if post_residual < 20 {
        score += 18.0;
    } else if post_residual < 30 {
        score += 18.0 + (30 - post_residual) as f64 * 0.6;
    }

    // Lookahead: exact and near-exact fits for the next item
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 750.0;
        } else if next_item_size <= post_residual {
            let post2 = post_residual - next_item_size;
            score -= 120.0 - (post2 as f64) * 2.0;
            if post2 == 0 { score -= 100.0; }
            if post2 > 0 && post2 < 5 { score -= 26.0; }
            if post2 % 10 == 0 && post2 > 0 { score -= 24.0; }
            if post2 > 0 && post2 % 5 == 0 && post2 >= 20 { score -= 10.0; }
            if post2 > 0 && post2 <= 2 { score -= 12.0; }
            if post2 > 0 && post2 <= next_item_size / 4 { score -= 9.0; }
            if post_residual % next_item_size == 0 { score -= 15.0; }
            if post_residual >= next_item_size * 2 && post_residual - next_item_size * 2 <= 4 {
                score -= 18.0;
            }
            let chain = post_residual / next_item_size;
            if chain >= 2 { score -= (chain.min(4)) as f64 * 6.0; }
        } else {
            // next item won't fit here: penalize leaving a nearly-fitting gap
            let gap = next_item_size - post_residual;
            if post_residual > 0 {
                if gap <= 3 { score += 35.0; }
                else if gap <= 8 { score += 12.0; }
                if (gap as f64) > mean_residual * 0.5 { score += 12.0; }
                if gap <= 5 { score += (6 - gap) as f64 * 4.0; }
                if post_residual < 15 { score += 30.0 * (1.0 - progress); }
                if post_residual as f64 > mean_residual * 1.4 { score -= 10.0; }
            }
        }
    }

    // Compaction pressure scaled by open bins
    score += open_bins_count as f64 * 0.8;

    // Last-chance bin: strongly favor using it
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 50.0;
    }

    // Tightness via relative fill
    score -= (item_size as f64 / bin_residual.max(1) as f64) * 30.0;

    // NEW-BIN CANDIDATE handling
    if bin_residual == bin_capacity {
        let avg_fill = 1.0 - (mean_residual / cap_f);
        score += 240.0 - avg_fill * 300.0 - progress * 60.0;
        let newbin_waste = (bin_capacity - item_size) as f64;
        // big items deserve a fresh bin
        if item_size as f64 / cap_f > 0.75 { score -= 55.0; }
        if item_size >= bin_capacity * 3 / 4 { score -= 45.0; }
        if bin_capacity - item_size <= 4 { score -= 70.0; }
        if item_size as f64 > mean_residual { score -= 25.0; }
        if newbin_waste < mean_residual * 0.5 { score -= 30.0; }
        if fitting_bins_count > 0 {
            score += (fitting_bins_count.min(5) as f64) * 8.0;
            let snug = item_size as f64 / bin_residual.max(1) as f64;
            if snug > 0.95 { score += 30.0; }
        }
        // fresh bin pairs perfectly with next item
        if next_item_size > 0 {
            let leftover = bin_capacity - item_size;
            if leftover >= next_item_size && leftover - next_item_size <= 6 {
                score -= 38.0;
            }
            if leftover >= next_item_size {
                let tail = leftover % next_item_size;
                if tail == 0 { score -= 14.0; }
                else if tail <= 4 { score -= 8.0; }
            } else if leftover < 10 {
                score += 18.0;
            }
            if (newbin_waste as u32) < next_item_size && newbin_waste < cap_f * 0.12 {
                score += 24.0;
            }
            if (newbin_waste as u32) % next_item_size == 0 && newbin_waste >= next_item_size as f64 {
                score -= 18.0;
            }
        }
        if progress > 0.6 {
            let waste_tol = (1.0 - progress) * cap_f * 0.35;
            if newbin_waste > waste_tol && fitting_bins_count > 0 {
                score += 10.0 + progress * 20.0;
            }
        }
        if progress < 0.1 { score -= 5.0; }
    } else {
        // Consolidate slack: prefer bins whose residual is below average
        score += (mean_residual - bin_residual as f64) * 1.2;

        let dead_ratio = post_residual as f64 / cap_f;
        if dead_ratio < 0.03 { score -= 35.0; }
        else if dead_ratio < 0.08 { score -= 12.0; }
        else if dead_ratio > 0.35 { score += 22.0; }
        else if dead_ratio > 0.25 { score += 10.0; }
        score += dead_ratio * 30.0;

        if item_size == bin_residual { score -= 40.0; }

        if post_residual > 0 && next_item_size > 0 {
            let unusable = post_residual < next_item_size && (next_item_size - post_residual) > 12;
            if unusable {
                score += dead_ratio * 80.0;
            } else {
                let reuse = (post_residual / next_item_size) as f64 * (next_item_size as f64 / cap_f);
                score -= reuse * 22.0;
            }
        }

        if post_residual > 0 && (post_residual as f64) < mean_residual * 0.25 { score -= 12.0; }
        if post_residual > 0 && (post_residual as f64) < cap_f * 0.015 { score -= 16.0; }
        if post_residual > 0 && post_residual % 10 == 0 { score -= 8.0; }
        if post_residual > 0 && post_residual % 5 == 0 && post_residual <= 30 { score -= 6.0; }
        if bin_residual as f64 > cap_f * 0.6 { score -= 10.0; }
        if fitting_bins_count <= 2 && post_residual > 0 { score -= 6.0; }
        if post_residual > 0 && (post_residual as f64) > mean_residual * 1.6 && fitting_bins_count > 2 { score += 9.0; }
        if post_residual > 0 && next_item_size > 0 && post_residual >= next_item_size as u32 && (post_residual as f64) < mean_residual * 0.7 { score -= 6.0; }
        if post_residual > 0 && next_item_size > 0 && post_residual < next_item_size as u32 {
            score += (1.0 - progress) * 12.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tight fit reward: quadratic penalty on wasted space.
    let waste = post_residual as f64;
    score += 0.35 * waste * waste / bin_capacity as f64;

    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 60.0;
    } else if post_residual < 10 {
        score -= 25.0;
    }

    // Lookahead: if next item fits in post_residual, reward this placement.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 18.0 + 0.5 * next_item_size as f64;
    } else if next_item_size > 0 && next_item_size > post_residual {
        // Next item won't fit here anyway; slight penalty if we leave awkward gap.
        score += 4.0;
    }

    // Last-chance bin: strongly favor using the only fitting bin.
    if fitting_bins_count == 1 {
        score -= 30.0;
    } else {
        score += 2.0 * (fitting_bins_count as f64 - 1.0);
    }

    // Prefer bins with smaller current residual (best-fit flavor) modulated by mean.
    score += 0.25 * (bin_residual as f64 - mean_residual);

    // Time horizon: early in stream, be conservative with new bins; late, pack tight.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    // New-bin candidate handling: empty bin has bin_residual == bin_capacity.
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin, reduced when few fitting bins or many open bins.
        let mut new_bin_cost = 55.0;
        if fitting_bins_count == 0 {
            new_bin_cost -= 40.0;
        }
        if open_bins_count == 0 {
            new_bin_cost -= 30.0;
        }
        // If item is large relative to capacity, opening a fresh bin is fine.
        new_bin_cost -= 0.2 * item_size as f64;
        // Late in stream, prefer squeezing into existing bins.
        new_bin_cost += 25.0 * progress;
        score += new_bin_cost;
    }

    // Slight global load balancing: avoid leaving one bin with huge residual while others tiny.
    if mean_residual > 0.0 {
        let ratio = bin_residual as f64 / mean_residual;
        score += 6.0 * (ratio - 1.0).abs();
    }

    // Small jitter-free exploration term coupling progress and open bins.
    score -= 3.0 * progress * (post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let score = (post_residual as f64) * 0.83;
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;

    // Base: prefer tight fits (small post_residual), with mild non-linear shaping.
    let mut score = pr * (1.0 + 0.5 * pr / cap);

    // Penalize dead space: residual too small to ever be useful for typical items.
    let useless = ((30.0 - pr) / 30.0).max(0.0);
    score += useless * useless * 12.0;

    // Reward if lookahead item fits exactly in the post residual.
    if next_item_size > 0 && (next_item_size as f64) == pr {
        score -= 15.0;
    } else if next_item_size > 0 && (next_item_size as u32) <= post_residual {
        score -= 6.0 * (1.0 - progress);
    }

    // Last-chance bonus: if this is the only fitting bin, strongly prefer using it.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // New-bin candidate: make it attractive only when current bin fits are poor.
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        score += 8.0 + 4.0 * (mean_residual / cap) - 10.0 * progress;
    }

    // Smooth stream-progress coupling: tighten preference for small residuals later.
    score *= 1.0 - 0.3 * progress * (pr / cap);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic classes: classify post_residual into capacity-fraction classes (1/4, 1/2, 3/4)
    let quarter = bin_capacity / 4;
    let half = bin_capacity / 2;
    let three_quarter = 3 * quarter;

    // Reward perfect harmonic fits (post_residual exactly on class boundaries)
    if post_residual == 0 {
        score -= 60.0; // perfect closure
    } else if post_residual <= quarter {
        score -= 30.0;
    } else if post_residual <= half {
        score -= 12.0;
    } else if post_residual <= three_quarter {
        score += 8.0;
    } else {
        score += 20.0; // large dead space
    }

    // Modulo arithmetic on post_residual: divisibility classes
    let pr = post_residual as i64;
    if pr % 10 == 0 {
        score -= 6.0; // aligns with common item granularity
    } else if pr % 5 == 0 {
        score -= 3.0;
    }

    // Integer-division thresholds: how many "typical" items (size ~ item_size) still fit
    let fits_more = if item_size > 0 { post_residual / item_size } else { 0 };
    if fits_more == 0 {
        score += 4.0; // bin becomes dead space
    } else {
        score -= 4.0 * fits_more as f64;
    }

    // Lookahead: does next item fit exactly into post_residual?
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 45.0; // perfect chain
        } else if next_item_size < post_residual {
            score -= 10.0;
            let gap = post_residual - next_item_size;
            if gap <= quarter {
                score -= 10.0;
            }
        } else {
            score += 15.0; // next item won't fit here
        }
    }

    // Last-chance bin: strongly prefer using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate handling: only attractive when open bins are congested
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let congestion = (open_bins_count as f64) / (1.0 + mean_residual / 10.0);
        score = 70.0 + congestion * 5.0 - progress * 10.0;
        if next_item_size > 0 && next_item_size > mean_residual as u32 {
            score -= 15.0; // open bins can't host the next item well
        }
    }

    // Mild tie-breaking: tighter bins preferred when many bins are open
    score += (bin_residual as f64) * 0.05 + open_bins_count as f64 * 0.1;

    // Small phase-dependent nudge using harmonic class of step
    let phase = (step_index % 4) as f64;
    score += phase * 0.25;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: penalize small unusable gaps hard.
    if post_residual > 0 {
        // A gap is "unusable" if it's smaller than the smallest plausible item (~1..15).
        // Penalize gaps in [1, 15] quadratically; they are almost certainly wasted.
        if post_residual < 15 {
            score += (16.0 - post_residual as f64) * (16.0 - post_residual as f64) * 4.0;
        }
        // Penalize gaps that can't fit the known next item (lookahead-aware dead space).
        if next_item_size > 0 && post_residual < next_item_size {
            score += (next_item_size - post_residual) as f64 * 3.0;
        }
    } else {
        // Perfect fit: strong reward.
        score -= 50.0;
    }

    // Reward tight fits: how well the item fills the bin relative to residual.
    let fill_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= fill_ratio * 20.0;

    // Open bins pressure: more open bins -> prefer filling existing bins over opening new ones.
    score += open_bins_count as f64 * 2.0;

    // Last-chance bonus: if this is the only bin that can fit the item, strongly prefer it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate handling: only attractive when no open bin fits well.
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin, modulated by stream progression.
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score += 35.0 + 20.0 * (1.0 - progress);
        // If open bins have plenty of slack on average, discourage a new bin less mildly.
        if mean_residual > item_size as f64 * 1.5 {
            score += 15.0;
        }
        // If the next item is large and this item is small, a fresh bin preserves flexibility.
        if next_item_size > 60 && item_size < 40 {
            score -= 10.0;
        }
    }

    // Slight preference for bins whose residual deviates from the mean
    // (consolidate slack into fewer bins).
    score += (bin_residual as f64 - mean_residual).abs() * 0.3;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit reward
    if post_residual == 0 {
        score -= 1000.0;
    }

    // 2-step lookahead: reward if next item fits exactly in post_residual
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 400.0;
        } else if post_residual >= next_item_size {
            // good chain: next item fits, penalize leftover after two placements
            let two_step_left = post_residual - next_item_size;
            score -= 150.0 - 0.5 * two_step_left as f64;
        } else {
            // next item does not fit here; penalize dead space proportional to gap
            let gap = (next_item_size - post_residual) as f64;
            score += 0.6 * gap;
        }
    }

    // Penalize residuals that are small but useless (below typical min item size)
    if post_residual > 0 && post_residual < 10 {
        score += 50.0;
    }

    // Prefer bins with residuals near mean (keep bin population homogeneous)
    let dev = (post_residual as f64 - mean_residual).abs();
    score += 0.3 * dev;

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 200.0;
    }

    // New-bin candidate: only attractive late in the stream or when few bins fit
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 80.0 + 100.0 * (1.0 - progress) - 50.0 * (fitting_bins_count as f64).min(3.0);
    }

    // Mild preference for tighter bins early on
    let fill_ratio = (bin_capacity - bin_residual) as f64 / bin_capacity as f64;
    score -= 20.0 * fill_ratio;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits (small post_residual) strongly, non-linearly.
    let tight = 1.0 - (post_residual as f64) / (bin_capacity as f64);
    score -= 30.0 * tight * tight;

    // Perfect fit: overwhelming reward.
    if post_residual == 0 {
        score -= 500.0;
    }

    // Penalize dead space below the minimum plausible item size (1..100 interface).
    // Residuals smaller than next item waste space for lookahead.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            // This bin can also host the next item: reward chaining.
            score -= 25.0;
            let chain_tight = 1.0 - ((post_residual - next_item_size) as f64) / (bin_capacity as f64);
            score -= 15.0 * chain_tight;
        } else if post_residual > 0 {
            // Dead space relative to lookahead item.
            score += 0.8 * (next_item_size - post_residual) as f64;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 120.0;
    }

    // New-bin candidate: only attractive when it beats a poor fit.
    if bin_residual == bin_capacity {
        // Base penalty for fragmenting into a fresh bin.
        score += 90.0;
        // Early in the stream, opening bins is cheaper (more future items to fill them).
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score -= 60.0 * (1.0 - progress);
        // Many open bins with slack: prefer filling them, penalize new bin.
        score += 4.0 * open_bins_count as f64;
        // If mean residual can't fit the item anyway, new bin is more acceptable.
        if mean_residual < item_size as f64 {
            score -= 70.0;
        }
    } else {
        // Reward using existing bins, more so when many are open (consolidation).
        score -= 2.0 * open_bins_count as f64;
    }

    // Prefer bins whose residual deviates favorably from the mean (use slack-heavy bins).
    let dev = bin_residual as f64 - mean_residual;
    score -= 0.3 * dev;

    // Late-stream urgency: fill existing bins tightly, avoid leaving many slivers.
    if progress_late(step_index, total_items) {
        score -= 20.0 * tight;
    }

    score
}

#[inline]
fn progress_late(step_index: usize, total_items: usize) -> bool {
    total_items > 0 && (step_index as f64 / total_items as f64) > 0.75
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let score = 0.0;
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;
    let norm_item = item_size as f64 / cap;
    let norm_next = next_item_size as f64 / cap;

    let mut score = pr;

    // Non-linear polynomial coupling of post_residual with stream progress.
    // Early on, prefer moderate residuals; late, strongly prefer tight fits.
    let tight = norm_pr * norm_pr; // quadratic dead-space term
    score += tight * cap * (0.5 + 1.5 * progress);

    // Smooth reward for small post_residual (cubic decay of waste).
    score -= cap * (norm_pr - norm_pr * norm_pr * norm_pr) * 0.6;

    // Lookahead coupling: reward residuals that still fit the next item,
    // penalize residuals just barely too small (near-miss dead space).
    if next_item_size > 0 {
        let fits_next = (post_residual as f64 >= next_item_size as f64) as f64;
        let gap = ((next_item_size as f64 - pr).abs()) / cap;
        score -= fits_next * (1.0 - gap) * 8.0 * (0.3 + 0.7 * progress);
        score += (1.0 - fits_next) * gap * gap * cap * 0.4;
    }

    // Perfect-fit / near-perfect-fit bonus (smooth via normalized residual).
    let perfect = 1.0 - (pr / cap).min(1.0);
    score -= perfect * perfect * perfect * cap * 0.5;

    // Last-chance bin: strongly favor using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate: penalize mildly so it's chosen only when fits are bad,
    // with penalty decaying as the stream progresses (late items prefer packing).
    if bin_residual == bin_capacity {
        score += 10.0 * (1.0 - 0.5 * progress) + open_bins_count as f64 * 0.3;
    }

    // Coupling with mean residual: avoid bins far from the mean (fragmentation).
    let dev = (pr - mean_residual).abs() / cap;
    score += dev * dev * cap * 0.3;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap_f = bin_capacity as f64;
    let mut score = post_residual as f64;
    let progress = step_index as f64 / total_items.max(1) as f64;

    // Dead-space tiers: reward near-perfect fits, penalize unusable slivers.
    if post_residual == 0 {
        score -= 900.0;
    } else if post_residual <= 3 {
        score -= 420.0;
    } else if post_residual <= 12 {
        score -= 90.0;
    } else if post_residual < 20 {
        score += 16.0;
    } else if post_residual < 30 {
        score += 16.0 + (30 - post_residual) as f64 * 0.6;
    }

    // Lookahead: does the next item fit into the resulting gap?
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 750.0;
        } else if next_item_size <= post_residual {
            let post2 = post_residual - next_item_size;
            score -= 120.0 - (post2 as f64) * 2.0;
            if post2 == 0 { score -= 95.0; }
            if post2 > 0 && post2 < 5 { score -= 26.0; }
            if post2 > 0 && post2 <= next_item_size / 4 { score -= 10.0; }
            if post_residual % next_item_size == 0 { score -= 16.0; }
            if post_residual >= next_item_size * 2 && post_residual - next_item_size * 2 <= 4 { score -= 18.0; }
            // chain potential: gap can hold several next items
            let chain = post_residual / next_item_size;
            if chain >= 2 { score -= (chain.min(4)) as f64 * 6.0; }
        } else {
            score += 18.0;
            let gap = next_item_size - post_residual;
            if gap <= 3 { score += 32.0; }
            if gap <= 8 { score += 10.0; }
            if post_residual < 15 { score += 40.0; }
            if post_residual as f64 > mean_residual * 1.4 { score -= 12.0; }
        }
    }

    // Tight fit reward.
    let fill_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= fill_ratio * 20.0;
    if item_size == bin_residual { score -= 40.0; }

    // Last-chance: only fitting bin -> strong preference over a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }
    if fitting_bins_count > 0 && bin_residual == bin_capacity {
        score += (fitting_bins_count as f64).min(5.0) * 9.0 + 20.0;
    }

    // New-bin candidate handling.
    if bin_residual == bin_capacity {
        let avg_fill = 1.0 - (mean_residual / cap_f);
        score += 250.0 - avg_fill * 330.0 - progress * 65.0;
        let leftover = bin_capacity - item_size;
        if item_size as f64 > mean_residual { score -= 45.0; }
        if item_size >= bin_capacity * 3 / 4 { score -= 55.0; }
        if bin_capacity - item_size <= 4 { score -= 70.0; }
        if next_item_size > 0 && next_item_size >= bin_capacity / 2 { score -= 32.0; }
        if next_item_size > 0 && next_item_size <= leftover {
            let tail = leftover % next_item_size;
            if tail == 0 { score -= 12.0; }
            if tail <= 4 { score -= 16.0; }
            if leftover >= next_item_size * 2 { score -= 14.0; }
        }
        if leftover < next_item_size && leftover < 10 { score += 18.0; }
        if leftover > 0 && (leftover as u32) < next_item_size && leftover < cap_f as u32 * 12 / 100 { score += 26.0; }
        if fitting_bins_count > 3 && item_size as f64 / cap_f < 0.5 { score += 30.0; }
        if progress > 0.6 {
            let waste_tol = (1.0 - progress) * cap_f * 0.35;
            if (leftover as f64) > waste_tol { score += 10.0 + progress * 22.0; }
        }
    }

    // Consolidate slack: prefer bins whose residual deviates from the mean.
    score += (bin_residual as f64 - mean_residual).abs() * 0.3;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post-residual: classify leftover space into capacity fractions
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;

    // Penalize leftover space that falls into "awkward" harmonic classes.
    // Classes by integer division of post_residual into quarters of capacity.
    let quarter = (bin_capacity / 4) as u32;
    let class = post_residual / quarter;
    match class {
        0 => { score += 6.0; }                 // tiny dead space (<25%) is nearly unusable
        1 => { score -= 2.0; }                 // 25-50% residual is useful
        2 => { score -= 4.0; }                 // 50-75% residual is very useful
        _ => { score -= 6.0; }                 // >75% residual is excellent
    }

    // Modulo-10 harmonic class: residuals that are multiples of common item sizes
    // (item sizes 10..80) tend to be fillable later; reward them.
    let pr_u = post_residual;
    if pr_u > 0 && (pr_u % 10 == 0 || pr_u % 20 == 0 || pr_u % 25 == 0) {
        score -= 3.0;
    } else if pr_u > 0 && pr_u < 10 {
        score += 8.0; // sub-10 dead space is pure waste
    }

    // Lookahead coupling: if the next item fits exactly into post_residual,
    // strongly favor this bin (perfect pair).
    if next_item_size > 0 {
        if next_item_size == pr_u {
            score -= 20.0;
        } else if next_item_size < pr_u {
            let next_left = pr_u - next_item_size;
            if next_left < 10 {
                score -= 6.0; // near-perfect pair
            } else {
                score -= (next_left as f64) / cap * 4.0;
            }
        } else {
            // next item won't fit here; mild penalty proportional to tightness
            score += (next_item_size - pr_u) as f64 / cap * 5.0;
        }
    }

    // Last-chance logic: if this is the only bin that fits, opening a new bin
    // costs one bin, so strongly prefer using it.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate handling: empty bin gets a baseline score so it wins
    // only when no open bin offers a decent fit.
    if bin_residual == bin_capacity {
        score += 12.0; // discourage opening new bins by default
        if next_item_size > 0 && next_item_size <= bin_capacity {
            // opening a fresh bin is fine if item is large (will leave usable residual)
            if item_size >= bin_capacity / 2 {
                score -= 4.0;
            }
        }
        if open_bins_count == 0 {
            score -= 100.0; // must open the first bin
        }
    }

    // Tight fit reward: small post_residual relative to item size means dense packing
    let tightness = item_size as f64 / bin_residual.max(1) as f64;
    score -= tightness * 5.0;

    // Mean residual alignment: prefer bins whose residual is close to the mean
    // (keeps the pool homogeneous, easier to fill with future items)
    let dev = ((pr - mean_residual) / cap).abs();
    score += dev * 3.0;

    // Stream progression: later in the stream, be greedier (minimize residual hard)
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += pr * (0.5 + progress * 0.5) * 0.3;

    // Many open bins: prefer consolidating into existing ones over opening new
    if open_bins_count > 4 && bin_residual != bin_capacity {
        score -= 2.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    let empty_candidate = bin_residual == bin_capacity;
    let progress = step_index as f64 / (total_items.max(1) as f64);
    let cap = bin_capacity as f64;

    // Dead-space threshold driven by the lookahead item (k=2).
    // If the leftover gap cannot host the next item, it risks becoming unusable dead space.
    let thr = if next_item_size > 0 { next_item_size as f64 } else { 6.0 };

    if !empty_candidate {
        if post_residual == 0 {
            // Perfect fit: strongly reward, slightly more valuable early in the stream.
            score -= 40.0 + 10.0 * (1.0 - progress);
        } else {
            let gap = post_residual as f64;
            if gap < thr {
                // Unusable-for-lookahead gap: strict dead-space penalty,
                // scaled by how far below the threshold the gap is.
                let deadness = (thr - gap) / thr.max(1.0); // in (0, 1]
                score += 18.0 * deadness + 6.0 * deadness * (1.0 - progress);
            } else {
                // Gap remains usable by the next item: reward aliveness,
                // mildly proportional to how roomy the gap is.
                score -= 8.0 + 4.0 * (gap / cap).min(1.0);
            }

            // Last-chance bin: if this is the only open bin that fits,
            // rejecting it forces a new bin — place here unless catastrophic.
            if fitting_bins_count == 1 {
                score -= 25.0;
            }
        }

        // Coupling with mean residual: a leftover far below the average
        // residual across open bins is likely isolated dead space.
        if post_residual > 0 && mean_residual > 0.0 && (post_residual as f64) < 0.15 * mean_residual {
            score += 4.0;
        }
    } else {
        // Brand-new bin candidate: base post_residual is already large
        // (deprioritizing it naturally). Add explicit consolidation
        // pressure that grows with the number of open bins, plus a
        // late-stream surcharge (opening bins late wastes more capacity).
        score += 6.0 + 3.5 * open_bins_count as f64;
        score += 8.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap_f = bin_capacity as f64;
    let mut score = post_residual as f64;
    let progress = step_index as f64 / total_items.max(1) as f64;

    // Dead-space tiers (borrowed strength from best-known).
    if post_residual == 0 {
        score -= 900.0;
    } else if post_residual <= 3 {
        score -= 350.0;
    } else if post_residual < 10 {
        score += 55.0;
    } else if post_residual < 20 {
        score += 18.0;
    } else if post_residual < 30 {
        score += (30 - post_residual) as f64 * 0.5;
    } else {
        score -= (post_residual as f64).ln() * 5.0;
    }

    // Lookahead coupling: exact and chained fits.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 700.0;
        } else if next_item_size <= post_residual {
            let post2 = post_residual - next_item_size;
            score -= 110.0 - post2 as f64 * 1.8;
            if post2 == 0 { score -= 90.0; }
            if post2 % 10 == 0 && post2 > 0 { score -= 22.0; }
            if post2 > 0 && post2 < 5 { score -= 24.0; }
            if post_residual % next_item_size == 0 { score -= 14.0; }
            let chain = post_residual / next_item_size;
            if chain >= 2 { score -= (chain.min(4)) as f64 * 5.0; }
        } else {
            let gap = next_item_size as f64 - post_residual as f64;
            score += 18.0;
            if post_residual > 0 && post_residual < 15 { score += 40.0; }
            if gap <= 5.0 { score += (6.0 - gap) * 4.0; }
            if post_residual as f64 > mean_residual * 1.4 { score -= 10.0 + progress * 6.0; }
        }
        if post_residual > 0 && post_residual < next_item_size {
            score += (next_item_size - post_residual) as f64 * 0.6 * (1.0 - progress);
        }
    }

    // Last-chance bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 28.0;
    }

    // Open-bin pressure.
    score += (open_bins_count as f64).powf(1.3) * 0.45 * (1.0 - progress);

    // Consolidation preference.
    score += (mean_residual - bin_residual as f64) * 0.9;

    // New-bin candidate decision.
    if bin_residual == bin_capacity {
        let newbin_waste = (bin_capacity - item_size) as f64;
        score += 200.0 - progress * 60.0;
        if fitting_bins_count > 0 {
            let snug = item_size as f64 / bin_residual.max(1) as f64;
            score += (fitting_bins_count.min(5) as f64) * 8.0 + 18.0;
            if snug > 0.9 { score += 35.0; }
            if snug > 0.97 { score += 20.0; }
        }
        if item_size >= bin_capacity * 3 / 4 { score -= 50.0; }
        if bin_capacity - item_size <= 4 { score -= 60.0; }
        if next_item_size > 0 && next_item_size >= bin_capacity / 2 { score -= 28.0; }
        if next_item_size > 0 && (bin_capacity - item_size) >= next_item_size {
            let tail = (bin_capacity - item_size) % next_item_size;
            if tail == 0 { score -= 16.0; } else if tail <= 4 { score -= 12.0; }
        }
        if newbin_waste > 0.0 && (newbin_waste as u32) < next_item_size && newbin_waste < cap_f * 0.12 {
            score += 22.0;
        }
        if progress > 0.6 {
            let waste_tol = (1.0 - progress) * cap_f * 0.35;
            if newbin_waste > waste_tol && fitting_bins_count > 0 {
                score += 10.0 + progress * 20.0;
            }
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward perfect or near-perfect fits.
    if post_residual == 0 {
        score -= 1000.0;
    } else if post_residual < 10 {
        score -= 200.0;
    }

    // Aggressive 2-step lookahead: reward when next item exactly fills post_residual.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 900.0;
        } else if next_item_size < post_residual {
            // Next item fits: penalize leftover after hypothetical placement.
            let second_residual = post_residual - next_item_size;
            score -= 150.0 * (1.0 - second_residual as f64 / bin_capacity as f64);
            if second_residual == 0 {
                score -= 800.0;
            }
        } else {
            // Next item won't fit here: penalize proportionally to wasted lookahead.
            let gap = (next_item_size - post_residual) as f64;
            score += gap * 0.5;
        }
    }

    // Relative to mean residual: bins tighter than average are better targets.
    score -= (mean_residual - post_residual as f64) * 0.3;

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 300.0;
    }

    // Penalize leaving awkward dead space (small but nonzero residuals).
    if post_residual > 0 && post_residual < next_item_size.max(1) {
        score += 20.0;
    }

    // New-bin candidate: only attractive when open bins would waste a lot.
    if bin_residual == bin_capacity {
        let waste_threshold = 30.0;
        if post_residual as f64 > waste_threshold && fitting_bins_count > 0 {
            let min_open_waste = if next_item_size > 0 && next_item_size < bin_residual {
                (bin_residual - next_item_size) as f64
            } else {
                bin_residual as f64
            };
            if min_open_waste > waste_threshold {
                score -= 100.0;
            } else {
                score += 250.0;
            }
        } else {
            score += 250.0;
        }
    }

    // Late in the stream, consolidate more aggressively.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= progress * 30.0 * (1.0 - post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong preference for tight fits: reward low post-residual non-linearly.
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 8.0 * tightness * tightness;

    // Penalize dead space that cannot fit the next item (lookahead k=2).
    if next_item_size > 0 {
        if post_residual < next_item_size {
            score += 0.6 * (next_item_size - post_residual) as f64;
        } else if post_residual >= next_item_size {
            // Reward bins that can also host the next item (chaining fits).
            score -= 2.0;
        }
        // Perfect pairing: item + next item exactly fills the bin.
        if post_residual == next_item_size {
            score -= 10.0;
        }
    }

    // Last-chance bonus: if this is the only bin that fits, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate handling: penalize opening a fresh bin unless residuals
    // across open bins are mostly unusable for the item.
    if bin_residual == bin_capacity {
        let base_penalty = 25.0;
        let scarcity = if fitting_bins_count == 0 { 30.0 } else { 0.0 };
        // Late in the stream, prefer consolidation into open bins.
        let horizon = step_index as f64 / (total_items.max(1) as f64);
        score += base_penalty + scarcity + 10.0 * horizon;
        // If open bins are too fragmented (high mean residual mismatch), allow new bin.
        if mean_residual > 0.0 && mean_residual < item_size as f64 * 0.9 {
            score -= 18.0;
        }
    }

    // Mild penalty for leaving residuals in the awkward 1..10 dead zone.
    if post_residual > 0 && post_residual < 10 {
        score += 3.0;
    }

    // Slight preference for using bins with larger residuals when many bins are open,
    // to consolidate fragmented capacity.
    score -= 0.05 * (bin_residual as f64 - mean_residual);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let norm_pr = pr / cap;
    let fit = item_size as f64 / cap;

    // Base: penalize remaining residual, but non-linearly (dead space matters more as it shrinks)
    let mut score = norm_pr * (1.0 + 0.8 * norm_pr * norm_pr);

    // Smooth coupling: residual squared vs progress — late in stream, compact bins harder
    score += 0.5 * norm_pr * norm_pr * (progress - 0.5);

    // Reward tight fits: interaction of fill ratio with progress
    let fill = 1.0 - norm_pr;
    score -= 0.6 * fill * fill * (1.0 - progress);

    // Lookahead: bonus if post_residual exactly fits next item
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        let diff = (pr - nxt).abs() / cap;
        score -= 0.9 * (1.0 - diff.min(1.0)) * (1.0 - progress);
        // penalize leaving residual just below next item (unusable wedge)
        if pr < nxt && pr > 0.0 {
            score += 0.4 * (nxt - pr) / cap;
        }
    }

    // Last-chance bin: strongly favor using it
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 1.2;
    }

    // Many open bins: prefer filling existing ones over opening new
    if bin_residual < bin_capacity {
        score -= 0.15 * (open_bins_count as f64).ln().max(0.0);
    } else {
        // New bin candidate: mild penalty unless residuals elsewhere are large
        score += 0.3 + 0.02 * mean_residual;
    }

    // Mean residual deviation: prefer bins close to mean (balanced packing)
    score += 0.1 * ((pr - mean_residual) / cap).abs();

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: reward near-perfect fits via capacity-fraction bands.
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;

    // Exact-fit harmonic reward (post_residual == 0 or small residue classes)
    if post_residual == 0 {
        score -= 40.0;
    } else {
        // Modulo-style dead-space penalty: residuals in "awkward" classes get penalized
        let r = post_residual;
        if r < 10 {
            score -= 15.0; // tiny residue is fine
        } else if r < 20 {
            score += 2.0;
        } else if r < 30 {
            score += 5.0;
        } else {
            score += (r as f64) * 0.05; // large dead space penalized extra
        }
        // Integer-division threshold: residuals that can't host common medium items are dead
        if r < 10 {
            score += 20.0; // truly dead space
        }
    }

    // Lookahead coupling: if next item fits the post residual, reward strongly.
    if next_item_size > 0 && post_residual >= next_item_size {
        let tight = (next_item_size as f64) / (pr + 1.0);
        score -= 10.0 + 12.0 * tight; // next item fills this bin well
    }
    // If next item exactly fills post_residual, huge reward (harmonic pair)
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 25.0;
    }
    // If next item would leave this bin awkward, slight penalty
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 3.0;
    }

    // Last-chance bonus: if this is the only fitting bin, strongly prefer it.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate handling: empty bin gets baseline score.
    if bin_residual == bin_capacity {
        // Prefer new bin only when existing fits are poor: give it a mediocre score
        score = cap * 0.5 + 0.35 * mean_residual;
        // Early in stream, opening bins is cheap; late, prefer filling existing
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score += 15.0 * progress;
        // If many open bins already, discourage opening more
        score += 2.0 * (open_bins_count as f64).sqrt();
        // If next item is large and this fresh bin could host a big pair, mild bonus
        if next_item_size >= item_size && item_size + next_item_size as u32 <= bin_capacity {
            score -= 8.0;
        }
    }

    // Mild preference for tighter bins overall (best-fit flavor)
    score += 0.02 * (bin_residual as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap_f = bin_capacity as f64;
    let mut score = post_residual as f64;
    let progress = step_index as f64 / total_items.max(1) as f64;
    let nis = next_item_size as u32;

    // Dead-space tiers (combined strength).
    if post_residual == 0 {
        score -= 1050.0;
    } else if post_residual <= 3 {
        score -= 420.0;
    } else if post_residual <= 12 {
        score -= 90.0;
    } else if post_residual < 20 {
        score += 18.0;
    } else if post_residual < 30 {
        score += 18.0 + (30 - post_residual) as f64 * 0.6;
    } else {
        score -= (post_residual as f64).ln() * 5.0;
    }

    // Lookahead coupling: exact and chained fits.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 820.0;
        } else if next_item_size <= post_residual {
            let post2 = post_residual - next_item_size;
            score -= 125.0 - post2 as f64 * 2.0;
            if post2 == 0 { score -= 100.0; }
            if post2 % 10 == 0 && post2 > 0 { score -= 25.0; }
            if post2 > 0 && post2 < 5 { score -= 26.0; }
            if post2 > 0 && post2 <= 2 { score -= 14.0; }
            if post_residual % next_item_size == 0 { score -= 16.0; }
            if post_residual >= next_item_size * 2 && post_residual - next_item_size * 2 <= 4 { score -= 20.0; }
            if post2 > 0 && post2 <= next_item_size / 4 { score -= 10.0; }
            let chain = post_residual / next_item_size;
            if chain >= 2 { score -= (chain.min(4)) as f64 * 6.0; }
        } else {
            let gap = next_item_size as f64 - post_residual as f64;
            score += 20.0;
            if post_residual > 0 && post_residual < 15 { score += 45.0; }
            if post_residual > 0 && gap <= 3.0 { score += 35.0; }
            if gap > 0.0 && gap <= 8.0 { score += 12.0; }
            if post_residual > 0 && gap > mean_residual * 0.5 { score += 14.0; }
            if post_residual > 0 && post_residual % 10 == 0 { score -= 15.0; }
            if post_residual as f64 > mean_residual * 1.4 { score -= 12.0 + progress * 6.0; }
        }
        if post_residual > 0 && post_residual < next_item_size {
            score += (next_item_size - post_residual) as f64 * 0.6 * (1.0 - progress);
            let gap = (next_item_size as f64 - post_residual as f64) / next_item_size as f64;
            if gap < 0.12 { score -= 10.0; }
            let unusable = (next_item_size - post_residual) > 12;
            if unusable { score += (post_residual as f64 / cap_f) * 90.0; }
        }
        if post_residual > 0 && post_residual >= next_item_size && (post_residual as f64) < mean_residual * 0.7 {
            score -= 6.0;
        }
    }

    // Last-chance bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 30.0;
    }

    // Open-bin pressure.
    score += (open_bins_count as f64).powf(1.3) * 0.45 * (1.0 - progress);

    // Consolidation preference.
    score += (mean_residual - bin_residual as f64) * 1.1;

    // New-bin candidate decision.
    if bin_residual == bin_capacity {
        let newbin_waste = (bin_capacity - item_size) as f64;
        score += 220.0 - progress * 65.0;
        if item_size as f64 > mean_residual { score -= 45.0; }
        if fitting_bins_count > 0 {
            let snug = item_size as f64 / bin_residual.max(1) as f64;
            score += (fitting_bins_count.min(5) as f64) * 9.0 + 20.0;
            if snug > 0.9 { score += 40.0; }
            if snug > 0.95 { score += 28.0; }
            if snug > 0.98 { score += 18.0; }
        }
        if item_size >= bin_capacity * 3 / 4 { score -= 55.0; }
        if bin_capacity - item_size <= 4 { score -= 70.0; }
        if next_item_size > 0 && next_item_size >= bin_capacity / 2 { score -= 30.0; }
        if next_item_size > 0 && (bin_capacity - item_size) >= next_item_size {
            let tail = (bin_capacity - item_size) % next_item_size;
            if tail == 0 { score -= 20.0; } else if tail <= 4 { score -= 16.0; }
            if (bin_capacity - item_size) - next_item_size <= 6 { score -= 38.0; }
        }
        if newbin_waste > 0.0 && (newbin_waste as u32) < nis && newbin_waste < cap_f * 0.12 {
            score += 24.0;
        }
        if newbin_waste > 0.0 && nis > 0 && newbin_waste >= nis as f64 && (newbin_waste as u32) % nis == 0 {
            score -= 20.0;
        }
        if progress > 0.6 {
            let waste_tol = (1.0 - progress) * cap_f * 0.35;
            if newbin_waste > waste_tol && fitting_bins_count > 0 {
                score += 10.0 + progress * 22.0;
            }
        }
        if progress > 0.85 && newbin_waste > cap_f * 0.3 { score += 8.0; }
        if fitting_bins_count > 3 && (item_size as f64) / cap_f < 0.5 { score += 30.0; }
    } else {
        // Fine-grained residual fitting for open bins.
        let tightness = 1.0 - (item_size as f64 / bin_residual.max(1) as f64);
        score += tightness * 85.0;
        let dead_ratio = post_residual as f64 / cap_f;
        if dead_ratio < 0.03 { score -= 38.0; }
        else if dead_ratio < 0.08 { score -= 14.0; }
        else if dead_ratio > 0.35 { score += 24.0; }
        else if dead_ratio > 0.25 { score += 10.0; }
        score += dead_ratio * 30.0;
        if item_size == bin_residual { score -= 45.0; }
        if post_residual > 0 && post_residual < 6 { score -= 22.0; }
        if post_residual > 0 && (post_residual as f64) < mean_residual * 0.25 { score -= 15.0; }
        if post_residual > 0 && post_residual % 10 == 0 { score -= 10.0; }
        if post_residual > 0 && post_residual % 5 == 0 && post_residual <= 30 { score -= 8.0; }
        if post_residual > 0 && (post_residual as f64) > mean_residual * 1.6 && fitting_bins_count > 2 { score += 10.0; }
        if next_item_size > 0 && post_residual > 0 {
            let reuse = (post_residual / nis) as f64 * (next_item_size as f64 / cap_f);
            score -= reuse * 22.0;
        }
        if post_residual > 0 && next_item_size > 0 && post_residual >= nis && (post_residual % nis) <= 2 {
            score -= 8.0;
        }
        if next_item_size > 0 && post_residual > 0 && post_residual < nis && (nis - post_residual) <= 2 {
            score += 10.0 * (1.0 - progress);
        }
        if fitting_bins_count <= 2 && post_residual > 0 { score -= 8.0; }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: gaps that no plausible item can fill are heavily penalized.
    // A residual gap is "dead" if it's smaller than the smallest possible item (1) — never —
    // but practically dead if it's tiny relative to capacity and below the lookahead item size.
    let progress = step_index as f64 / total_items.max(1) as f64;
    let min_gap = 1.0;
    if post_residual > 0 && (post_residual as f64) < min_gap.max(next_item_size as f64) {
        // gap too small for the known next item: likely dead space
        score += (bin_capacity as f64) * 0.5 * (1.0 - (post_residual as f64) / (bin_capacity as f64));
    }

    // Perfect fit reward
    if post_residual == 0 {
        score -= 60.0;
    }

    // Reward tight fits: small post_residual relative to bin
    let tightness = 1.0 - (post_residual as f64) / (bin_capacity as f64);
    score -= 20.0 * tightness * tightness;

    // Penalize leaving a gap that the next item would exactly fill (waste of good bin)
    if next_item_size > 0 && post_residual > 0 {
        let diff = (post_residual as i64 - next_item_size as i64).unsigned_abs();
        if diff <= 2 {
            score -= 15.0;
        }
    }

    // Open bins pressure: discourage spreading across many bins unless fit is great
    score += 0.6 * open_bins_count as f64 * (1.0 - tightness);

    // Last-chance bin: strongly favor using the only fitting bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate: only attractive when current fit is poor and mean residual is low
    if bin_residual == bin_capacity {
        let poor_fit = (post_residual as f64) / (bin_capacity as f64);
        score = 55.0 + 40.0 * poor_fit + 0.8 * open_bins_count as f64 - 20.0 * progress;
        if next_item_size > 0 && post_residual >= next_item_size {
            score -= 10.0;
        }
    }

    // Slight nudge toward bins with larger residual among similar fits
    score -= 0.05 * (bin_residual as f64 - mean_residual);

    score
}

