            let tail = (bin_capacity - item_size) % next_item_size;
            if tail == 0 { score -= 18.0; } else if tail <= 4 { score -= 14.0; }
            if (bin_capacity - item_size) - next_item_size <= 6 { score -= 30.0; }
        }
        if newbin_waste > 0.0 && (newbin_waste as u32) < next_item_size && newbin_waste < cap_f * 0.12 {
            score += 24.0;
        }
        if newbin_waste > 0.0 && newbin_waste < mean_residual * 0.6 { score -= 28.0; }
        if fitting_bins_count > 3 && item_size as f64 / cap_f < 0.5 { score += 28.0; }
        if progress > 0.6 {
            let waste_tol = (1.0 - progress) * cap_f * 0.35;
            if newbin_waste > waste_tol && fitting_bins_count > 0 {
                score += 10.0 + progress * 22.0;
            }
        }
        if progress > 0.85 && newbin_waste > cap_f * 0.3 { score += 8.0; }
    } else {
        let tightness = 1.0 - (item_size as f64 / bin_residual.max(1) as f64);
        score += tightness * 70.0;
        let dead_ratio = post_residual as f64 / cap_f;
        if dead_ratio < 0.03 { score -= 35.0; }
        else if dead_ratio < 0.08 { score -= 14.0; }
        else if dead_ratio > 0.35 { score += 22.0; }
        else if dead_ratio > 0.25 { score += 10.0; }
        score += dead_ratio * 30.0;
        if post_residual > 0 && post_residual < 6 { score -= 20.0; }
        if post_residual > 0 && (post_residual as f64) < mean_residual * 0.25 { score -= 14.0; }
        if item_size == bin_residual { score -= 45.0; }
        if post_residual > 0 && (post_residual as f64) < cap_f * 0.015 { score -= 18.0; }
        if post_residual > 0 && next_item_size > 0 && post_residual >= next_item_size && (post_residual % next_item_size) <= 2 {
            score -= 8.0;
        }
        if post_residual > 0 && (post_residual as f64) > mean_residual * 1.6 && fitting_bins_count > 2 { score += 10.0; }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: small post_residual relative to capacity.
    let tightness = 1.0 - (post_residual as f64) / (bin_capacity as f64);
    score -= 18.0 * tightness * tightness;

    // Penalize dead space that cannot fit the lookahead item (wasted gap).
    if next_item_size > 0 {
        if post_residual < next_item_size {
            score += 0.35 * (next_item_size - post_residual) as f64;
        } else {
            // Reward leaving a gap that exactly/nearly fits the next item.
            let gap_diff = (post_residual - next_item_size) as f64;
            score -= 6.0 * (-gap_diff / 12.0).exp();
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 25.0;
    }

    // New-bin candidate handling: penalize opening a new bin unless current
    // bin fits are all poor (large post_residual) or many bins already open.
    if bin_residual == bin_capacity {
        score += 22.0;
        score -= 2.0 * (open_bins_count as f64).ln().max(0.0);
        // Late in the stream, prefer closing out existing bins.
        let progress = step_index as f64 / (total_items as f64).max(1.0);
        score += 30.0 * progress;
    }

    // Penalize bins whose residual is far below the mean (fragmented bins);
    // prefer placing into bins with above-average residual.
    let res_diff = bin_residual as f64 - mean_residual;
    score -= 0.15 * res_diff;

    // Mild penalty for very fragmented bins (residual < 10 unusable).
    if post_residual < 10 && post_residual > 0 {
        score += 8.0;
    }

    // Slight preference to fill nearly-full bins earlier in the stream.
    let fill_ratio = 1.0 - (bin_residual as f64) / (bin_capacity as f64);
    score -= 5.0 * fill_ratio * (1.0 - step_index as f64 / (total_items as f64).max(1.0));

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let pr_norm = pr / cap;

    // Base: post-residual, mildly convex so small residuals are favored
    let mut score = pr + 20.0 * pr_norm * pr_norm;

    // Smooth polynomial coupling of residual quality with stream progress
    let coupling = 1.0 + 0.8 * progress * (1.0 - progress) * 4.0; // peaks mid-stream
    score *= coupling;

    // Reward tight fits (small post_residual) more strongly as stream advances
    let tightness = 1.0 - pr_norm;
    score -= 30.0 * progress * tightness * tightness * tightness;

    // Penalize dead space unusable by the next item (smooth interaction)
    if next_item_size > 0 {
        let gap = (pr - next_item_size as f64).max(0.0);
        score += 0.15 * gap * (1.0 + progress);
    }

    // Last-chance bonus: strongly favor the only bin that fits
    if fitting_bins_count == 1 {
        score -= 25.0 * (1.0 + progress);
    }

    // Discard overly empty placements when many bins are open (encourage consolidation)
    score += 0.5 * pr_norm * open_bins_count as f64;

    // Pull toward mean residual to balance loads smoothly
    score += 0.1 * (pr - mean_residual).abs();

    // New-bin candidate: smooth sigmoid gate on desirability of opening fresh bin
    let new_bin = (bin_residual == bin_capacity) as i32 as f64;
    let gate = 1.0 / (1.0 + (-6.0 * (pr_norm - 0.5)).exp());
    score += new_bin * 10.0 * (1.0 - gate);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Base: prefer tight fits (low post residual), scaled nonlinearly.
    let fit_ratio = post_residual as f64 / cap;
    score = fit_ratio * cap * 0.8 + (fit_ratio * fit_ratio) * 40.0;

    // Harmonic class of post_residual: residual mod 10 classes.
    let r_mod = post_residual % 10;
    let class_bonus = match r_mod {
        0 => 18.0,           // perfectly divisible residual — highly reusable
        1 | 9 => 10.0,       // near-decade residuals still useful
        5 => 8.0,            // half-decade
        2 | 4 | 6 | 8 => 3.0,
        _ => 0.0,            // odd awkward residuals penalized implicitly
    };
    score -= class_bonus;

    // Integer-division thresholds on post_residual: usable chunks for common item bands.
    let chunks = post_residual / 10;
    score -= (chunks as f64) * 1.5;

    // Coupling with next item (lookahead k=2): if next item fits exactly into post_residual, big reward.
    if next_item_size > 0 && next_item_size <= post_residual {
        score -= 12.0;
        let slack = post_residual - next_item_size;
        if slack % 10 == 0 {
            score -= 8.0; // next item leaves a clean harmonic residual
        }
        if slack < 10 && slack > 0 {
            score += 6.0; // next item would nearly fill, leaving dead space after
        }
    } else if next_item_size > post_residual {
        // residual too small for next item: penalize proportionally to wasted lookahead
        score += 5.0 + (next_item_size as f64 - post_residual as f64).min(30.0) * 0.2;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 25.0;
    }

    // Many open bins: discourage fragmenting further; prefer consolidating into fuller bins.
    if open_bins_count > 3 {
        let fullness = 1.0 - (bin_residual as f64 / cap);
        score -= fullness * (open_bins_count.min(20) as f64) * 1.2;
    }

    // Mean-residual coupling: bins with residual near mean are "typical" targets.
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += dev * 0.15;

    // Early stream: be greedy with new bins later; late stream: pack tightly.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score -= progress * 10.0;

    // New-bin candidate handling: empty bin gets a moderate baseline so it wins only
    // when no open bin offers a decent harmonic fit.
    if bin_residual == bin_capacity {
        score = 45.0 - progress * 8.0 + (open_bins_count as f64) * 0.5;
        if next_item_size > 0 && next_item_size >= 50 {
            score -= 6.0; // big upcoming item: fresh bin attractive
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap_f = bin_capacity as f64;
    let progress = step_index as f64 / total_items.max(1) as f64;
    let mut score = post_residual as f64;

    if post_residual == 0 {
        // Perfect fit: very strong reward.
        score -= 900.0;
    } else if post_residual < 15 {
        // Small unusable gaps: quadratic penalty.
        score += (16.0 - post_residual as f64) * (16.0 - post_residual as f64) * 3.0;
        if post_residual <= 3 {
            score -= 60.0; // tiny gaps are often still usable by small items
        }
    } else if post_residual < 30 {
        score += (30 - post_residual) as f64 * 0.8;
    }

    // Lookahead: reward residuals that can host the next item exactly or cleanly.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 400.0;
        } else if post_residual >= next_item_size {
            let post2 = post_residual - next_item_size;
            score -= 60.0;
            if post2 == 0 { score -= 80.0; }
            if post2 % next_item_size == 0 { score -= 25.0; }
            if post2 < 5 { score -= 20.0; }
            if post2 <= next_item_size / 4 { score -= 10.0; }
        } else {
            // Dead space relative to next item.
            let gap = (next_item_size - post_residual) as f64;
            score += gap * 2.5;
            if gap <= 3.0 { score += 20.0; }
        }
    }

    // Tight-fit reward.
    let fill_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= fill_ratio * 25.0;
    if item_size == bin_residual {
        score -= 40.0;
    }

    // Consolidate slack: prefer bins with residual below the mean.
    score += (bin_residual as f64 - mean_residual) * 0.8;
    if bin_residual as f64 > mean_residual * 1.5 {
        score += 8.0;
    }

    // Last-chance bonus for the only fitting open bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 45.0;
    }

    // New-bin candidate handling.
    if bin_residual == bin_capacity {
        let newbin_waste = (bin_capacity - item_size) as f64;
        score += 220.0 - progress * 60.0;

        if fitting_bins_count > 0 {
            score += (fitting_bins_count.min(6) as f64) * 10.0;
            // Snug fit in a fresh bin is fine.
            if fill_ratio > 0.9 { score += 30.0; }
            if fill_ratio > 0.97 { score += 25.0; }
        }
        // Large items deserve fresh bins.
        if item_size >= bin_capacity * 3 / 4 { score -= 60.0; }
        if bin_capacity - item_size <= 4 { score -= 70.0; }
        if next_item_size > 0 && next_item_size >= bin_capacity / 2 { score -= 35.0; }
        if next_item_size > 0 && (bin_capacity - item_size) >= next_item_size {
            let tail = (bin_capacity - item_size) % next_item_size;
            if tail == 0 { score -= 20.0; }
            else if tail <= 4 { score -= 12.0; }
        }
        // Waste tolerance shrinks as stream progresses.
        let waste_tol = (1.0 - progress) * cap_f * 0.35 + 8.0;
        if fitting_bins_count > 0 && newbin_waste > waste_tol {
            score += 15.0 + progress * 25.0;
        }
        if newbin_waste > 0.0 && (newbin_waste as u32) < next_item_size && newbin_waste < cap_f * 0.12 {
            score += 25.0;
        }
        if next_item_size > 0 && newbin_waste >= next_item_size as f64 && (newbin_waste as u32) % next_item_size == 0 {
            score -= 22.0;
        }
    }

    // Open-bin pressure scaled by progress.
    score += open_bins_count as f64 * (1.5 + progress * 1.5);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals that no future item can use are poison.
    // Dead space = post_residual smaller than the smallest plausible item (1) is impossible,
    // but gaps smaller than the next item (and smaller than a conservative min item size)
    // are likely wasted. Penalize quadratically.
    let min_item = 1u32;
    if post_residual > 0 && post_residual < next_item_size.max(min_item) {
        score += 12.0 + 0.25 * post_residual as f64;
    }
    // Very small gaps (< 10) are almost certainly dead space in typical streams.
    if post_residual < 10 && post_residual > 0 {
        score += 20.0;
    }
    // Perfect fit: post_residual 0 is ideal.
    if post_residual == 0 {
        score -= 25.0;
    }

    // Reward tight fits relative to bin capacity (waste ratio penalty).
    let waste_ratio = post_residual as f64 / bin_capacity as f64;
    score += 15.0 * waste_ratio * waste_ratio;

    // Lookahead: if next item fits exactly in the post residual, strongly favor this bin.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 18.0;
    }
    // If next item does NOT fit the post residual, mild penalty (chain break),
    // stronger when this bin would be nearly full anyway.
    if next_item_size > 0 && post_residual > 0 && next_item_size > post_residual {
        score += 6.0 * (1.0 - post_residual as f64 / bin_capacity as f64);
    }

    // Last-chance bonus: if this is the only bin that fits, avoid opening a new bin
    // unless the fit is terrible.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 14.0;
    }

    // Open-bin pressure: when many bins are open, prefer consolidating into existing bins
    // (penalize opening new ones); when few are open, new bins are cheap.
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pressure = (open_bins_count as f64).ln().max(0.0) * (0.5 + 0.5 * progress);
    if bin_residual == bin_capacity {
        // New-bin candidate: base cost plus pressure; allow it when fit elsewhere is bad.
        score += 30.0 + 8.0 * pressure;
        // Early in the stream, opening bins is more acceptable.
        score -= 20.0 * (1.0 - progress);
    } else {
        // Existing bins get a mild baseline advantage over new bins.
        score -= 4.0;
        // Prefer bins whose residual is close to the mean (balanced packing).
        score += 0.15 * ((bin_residual as f64 - mean_residual).abs());
    }

    // Prefer filling bins that are already mostly full (small residual) to close them out.
    score += 0.1 * bin_residual as f64 * (bin_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward perfect fits heavily.
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Aggressive 2-step lookahead: if the next item exactly matches post_residual, strong reward.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 400.0;
        } else if post_residual > next_item_size {
            // next item can still fit here afterwards: mild reward proportional to tightness
            score -= 60.0 * (next_item_size as f64 / post_residual as f64);
        } else {
            // next item cannot fit into post_residual: penalize wasted space relative to next item
            score += 0.8 * (next_item_size as f64 - post_residual as f64);
        }
    }

    // Compare post_residual against mean residual across open bins.
    // Creating a residual far below mean wastes bin potential; far above mean means a loose bin.
    let pr = post_residual as f64;
    let diff = pr - mean_residual;
    score += 0.3 * diff;

    // Penalize large dead space that nothing (items >= 1..=100) can usefully fill relative to capacity.
    let frac = pr / bin_capacity as f64;
    if frac > 0.5 {
        score += 50.0 * (frac - 0.5);
    }

    // Last-chance bin: strongly prefer using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 300.0;
    }

    // New-bin candidate: only attractive when no good fit exists among open bins.
    if bin_residual == bin_capacity {
        // Base cost of opening a bin, softened if many bins already open or stream is late.
        score = 60.0
            + 2.0 * open_bins_count as f64
            + 30.0 * (step_index as f64 / total_items.max(1) as f64);
        if next_item_size > 0 && next_item_size <= bin_capacity {
            score -= 0.2 * next_item_size as f64; // a fresh bin is a great host for the next item
        }
    }

    // Progression: tighten packing as the stream advances.
    score *= 1.0 + 0.2 * (step_index as f64 / total_items.max(1) as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tightness reward: quadratic bonus for small post-residuals.
    let tight = (post_residual as f64) / (bin_capacity as f64);
    score -= (1.0 - tight) * (1.0 - tight) * 12.0;

    // Exact fit jackpot.
    if post_residual == 0 {
        score -= 40.0;
    }

    // Dead-space penalty: residuals too small for the smallest plausible item.
    if post_residual > 0 && post_residual < 10 {
        score += 8.0;
    }

    // Lookahead: penalize placements that leave a residual that can't host the next item,
    // reward residuals that can.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 6.0 + 0.05 * next_item_size as f64;
        } else {
            score += 5.0;
        }
        // Perfect pairing: this fill plus next item nearly fills the bin.
        if next_item_size as i64 - post_residual as i64 >= -2
            && next_item_size as i64 - post_residual as i64 <= 2
            && post_residual >= next_item_size
        {
            score -= 15.0;
        }
    }

    // Last-chance bin: strongly favor using the only fitting bin to avoid a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate: only attractive when no open bin fits well.
    let is_new = bin_residual == bin_capacity;
    if is_new {
        // Baseline cost of opening a new bin, softened late in the stream
        // or when open bins are already fragmented.
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let frag = (mean_residual - post_residual as f64).abs() / (bin_capacity as f64);
        score += 20.0 - 10.0 * progress + 5.0 * frag;
        // Never open a new bin for a small item early on.
        if item_size < bin_capacity / 3 {
            score += 10.0;
        }
    } else {
        // Mild preference for bins already below mean residual (consolidation).
        if (bin_residual as f64) < mean_residual {
            score -= 3.0;
        }
        // Prefer fullest bins when many bins are open (reduce fragmentation).
        score -= 0.05 * (bin_capacity - bin_residual) as f64 / open_bins_count.max(1) as f64;
    }

    // Time-horizon modulation: early stream, be conservative (waste less);
    // late stream, prioritize finishing bins tightly.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score *= 1.0 + 0.15 * (1.0 - progress);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / (total_items as f64).max(1.0);
    let post = post_residual as f64;
    let cap = bin_capacity as f64;
    let mut score = post;

    // Non-linear polynomial coupling of post_residual with stream progress:
    // early on, tolerate slack; late in stream, punish residual waste harder.
    let progress_weight = 0.5 + 1.5 * progress * progress;
    score *= progress_weight;

    // Reward tight fits: normalized fill ratio, cubic smoothness.
    let fill = (cap - post) / cap;
    score -= 30.0 * fill * fill * fill;

    // Lookahead (k=2): penalize if next item could have used this post_residual.
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        if nx <= post {
            let waste = (post - nx) / cap;
            score += 25.0 * (1.0 - waste) * (1.0 - waste);
        } else {
            // next item won't fit here: mild reward for consuming this bin's slack now
            score -= 8.0 * (nx - post) / cap;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 40.0 * (1.0 - progress);
    }

    // Penalize scattering across many open bins when this bin is far below mean residual.
    let dev = (mean_residual - post) / cap;
    score += 5.0 * dev * dev * (open_bins_count as f64).sqrt();

    // Smooth taper: keep scores comparable across stream phases.
    score += 10.0 * progress * (1.0 - progress);

    score
}

