pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post-residual: quantize dead space into capacity fractions.
    let cap = bin_capacity as f64;
    let post_frac = post_residual as f64 / cap;

    // Integer-division thresholds on post_residual: bins whose residual falls into
    // "harmonic" classes (multiples of capacity/8) are more reusable.
    let class = post_residual / (bin_capacity / 8);
    let class_alignment = (post_residual % (bin_capacity / 8)) as f64;
    score += class_alignment * 0.25; // penalize off-class residuals slightly

    // Reward residuals that can still host common item classes (10..80 grid).
    if post_residual >= 80 { score -= 12.0; }
    else if post_residual >= 40 { score -= 6.0; }
    else if post_residual >= 20 { score -= 2.0; }

    // Lookahead coupling: if next item fits into post_residual, strongly reward.
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            score -= 15.0;
            // extra harmonic bonus if next item leaves another well-classed residual
            let npost = post_residual - next_item_size;
            if npost % 10 == 0 { score -= 4.0; }
        } else {
            // next item cannot follow here; penalize proportionally to wasted potential
            score += 5.0 + (next_item_size - post_residual) as f64 * 0.15;
        }
    }

    // Perfect fit: zero post-residual is ideal.
    if post_residual == 0 { score -= 25.0; }

    // Last-chance bin: if this is the only fitting bin, avoid opening a new bin
    // unless the fit is terrible.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 10.0 + (post_frac * 5.0);
    }

    // New-bin candidate: neutral-ish baseline, slightly penalized so we prefer
    // reusing open bins unless the fit is poor; becomes attractive when the
    // best existing fit would leave a bad harmonic class.
    if bin_residual == bin_capacity {
        score += 18.0;
        // early in the stream, opening bins is cheap; later, discourage it
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += progress * 10.0;
        // if mean residual across open bins is small (all bins tight), a new bin is fine
        score -= (mean_residual / cap).min(1.0) * 8.0;
    }

    // Slight preference for tighter existing fits overall.
    score += (bin_residual as f64 - item_size as f64) * 0.05;

    // Modulo coupling: reward when item_size and residual share harmonic structure.
    if bin_residual % item_size.max(1) == 0 { score -= 3.0; }

    // Mild pressure to consolidate when many bins are open.
    score += open_bins_count as f64 * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals too small to hold any realistic
    // future item (below the smallest plausible item) are pure waste.
    let dead_threshold = 12.0;
    if post_residual > 0 && (post_residual as f64) < dead_threshold {
        score += (dead_threshold - post_residual as f64) * 6.0;
    }

    // Non-linear penalty on mid-size unusable gaps (can't fit next item).
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += (next_item_size - post_residual) as f64 * 3.0;
    }

    // Reward perfect / near-perfect fits strongly.
    if post_residual == 0 {
        score -= 40.0;
    } else {
        let tightness = 1.0 - (post_residual as f64) / (bin_capacity as f64);
        score -= tightness * tightness * 15.0;
    }

    // Reward leaving room for the lookahead item (chained fit).
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 8.0 + (post_residual - next_item_size) as f64 * 0.1;
    }

    // Last-chance bonus: only fitting bin -> avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // Open-bin pressure: prefer reusing bins when many are open.
    score += open_bins_count as f64 * 0.5;

    // New-bin candidate: only attractive when existing residuals are poor
    // (mean residual large relative to item) or stream is early.
    if bin_residual == bin_capacity {
        let poor_fits = if mean_residual > item_size as f64 * 1.5 { 10.0 } else { 0.0 };
        score += 55.0 - poor_fits - (1.0 - step_index as f64 / total_items.max(1) as f64) * 5.0;
    }

    // Mild alignment with mean residual: avoid making bin outlier-residuals.
    score += ((post_residual as f64) - mean_residual).abs() * 0.15;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap_f = bin_capacity as f64;
    let mut score = post_residual as f64;
