        } else if post_residual > next_item_size {
            let slack = (post_residual - next_item_size) as f64;
            // Prefer leftovers the next item can nearly fill.
            score -= 25.0 * (-slack / 10.0).exp();
        } else {
            // Next item cannot fit here; penalize proportionally to the gap.
            let gap = (next_item_size - post_residual) as f64;
            score += 10.0 * (1.0 - (-gap / 15.0).exp());
        }
    } else {
        // Last item: prefer filling as tightly as possible.
        score -= 20.0 * (-fit_ratio * 15.0).exp();
    }

    // Relative-to-mean-residual term: prefer bins that are emptier than average
    // when the fit is loose, but prefer fuller-than-average bins for tight fits.
    let dev = post_residual as f64 - mean_residual;
    if fit_ratio > 0.2 {
        score += 0.08 * dev; // loose fit: drain emptier bins
    } else {
        score -= 0.05 * dev; // tight fit: prefer the fullest usable bin
    }

    // Last-chance bonus: if this is the only bin that can fit the item,
    // strongly favor using it over opening a new bin.
    if fitting_bins_count == 1 {
        score -= 35.0;
    }

    // Discourage opening a new bin when a decent fit already exists.
    if bin_residual == bin_capacity {
        // New-bin candidate: baseline attractiveness with lookahead discount.
        let new_bin_lookahead = if next_item_size > 0 {
            let slack = (bin_capacity as f64 - item_size as f64 - next_item_size as f64).abs();
            20.0 * (-slack / 12.0).exp()
        } else {
            0.0
        };
        score += 15.0 - new_bin_lookahead;
    }

    // Mild stream-progress pressure: as the stream advances, prefer
    // consolidating into existing bins rather than spreading out.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += 5.0 * progress * fit_ratio;

    // Slight penalty when many bins are already open (encourage consolidation).
    score += 0.5 * open_bins_count as f64 * fit_ratio;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits (low post residual) nonlinearly.
    let fit_ratio = post_residual as f64 / bin_capacity as f64;
    score += fit_ratio * fit_ratio * 40.0;

    // Penalize leaving dead space that is too small for the smallest item (1).
    if post_residual > 0 && post_residual < 1 {
        score += 100.0;
    }

    // Reward leaving space exactly usable by the next item (lookahead).
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 25.0;
        } else if post_residual >= next_item_size {
            score -= 8.0 * (next_item_size as f64 / (post_residual as f64 + 1.0));
        } else {
            // next item cannot fit here; slight penalty scaled by how much is wasted
            score += 6.0 * (1.0 - post_residual as f64 / (next_item_size as f64 + 1.0));
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 30.0;
    }

    // Many fitting bins: prefer the tightest one; add mild competition pressure.
    if fitting_bins_count > 1 {
        score += (fitting_bins_count as f64).ln() * 2.0;
    }

    // Global residual balance: prefer bins whose residual is near the mean
    // (keeps residuals homogeneous, easing future packing).
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += dev * 0.15;

    // Time horizon: early in stream, be conservative (favor new bins less);
    // late in stream, squeeze into existing bins harder.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score -= progress * 12.0;

    // Many open bins: discourage opening new bins, encourage filling existing ones.
    score += (open_bins_count as f64) * 0.8;

    // New-bin candidate adjustment: only attractive when item is large relative
    // to capacity or no good fit exists.
    if bin_residual == bin_capacity {
        let large_item = item_size as f64 / bin_capacity as f64;
        score += 18.0 - large_item * 14.0;
        if next_item_size > 0 && next_item_size <= post_residual {
            score += 5.0; // fresh bin can also host next item
        }
    }

    // Slight preference for filling bins with low residual first (best-fit bias).
    score += (bin_residual as f64 / bin_capacity as f64) * 5.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Normalized stream progress, smooth in [0,1]
    let t = if total_items > 1 {
        step_index as f64 / (total_items as f64 - 1.0)
    } else {
        0.0
    };

    // Normalized post-residual
    let pr = post_residual as f64 / bin_capacity as f64;
    let nr = next_item_size as f64 / bin_capacity as f64;

    // Smooth polynomial coupling: post_residual penalized more as stream progresses
    // (dead space matters more later when fewer chances remain to fill bins)
    let progress_weight = 1.0 + 1.5 * t * t;
    score += progress_weight * (pr * pr) * bin_capacity as f64;

    // Reward good fits: small post_residual relative to item size
    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 8.0 * fit_ratio * fit_ratio;

    // Lookahead coupling: if next item fits into the post-residual, reward this bin
    if next_item_size > 0 && post_residual >= next_item_size {
        let snug = 1.0 - (post_residual as f64 - next_item_size as f64) / bin_capacity as f64;
        score -= 6.0 * snug * (1.0 - t);
    } else if next_item_size > 0 {
        // Next item cannot use the leftover; penalize proportionally to wasted space
        score += 3.0 * pr * (0.5 + 0.5 * t);
    }

    // Last-chance bonus: if this is the only fitting bin, strongly favor using it
    if fitting_bins_count == 1 {
        score -= 12.0 * (1.0 - pr * pr);
    }

    // Deter opening new bins when many bins are open and mean residual is low
    let mean_pr = mean_residual / bin_capacity as f64;
    score += 0.4 * (open_bins_count as f64).ln().max(0.0) * (1.0 - mean_pr);

    // Mild preference for fuller bins (lower residual before placement)
    score += 0.05 * (bin_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of post-residual: classify leftover space into capacity-fraction buckets.
    // Residuals in (0,10] are "dead space" classes -> heavy penalty; larger residuals are reusable.
    let pr = post_residual;
    if pr == 0 {
        // Perfect fit: strongly reward.
        score -= 60.0;
    } else if pr <= 10 {
        // Dead-space class (smaller than the minimum item): unusable forever.
        score += 40.0;
    } else {
        // Harmonic class index via integer division on capacity fractions.
        // Classes: (0,25], (25,50], (50,75], (75,100] with quadratic preference for larger classes.
        let class = pr / 25; // 0..3
        score -= (class as f64) * (class as f64) * 4.0;
        // Extra reward for residuals in the most "useful" band (25..60): fits typical items.
        if pr >= 25 && pr <= 60 {
            score -= 12.0;
        }
    }

    // Lookahead coupling: reward if next item fits exactly or well into post_residual.
    if next_item_size > 0 && next_item_size <= pr {
        let slack = (pr - next_item_size) as f64;
        if slack == 0.0 {
            score -= 45.0; // chain perfect fit
        } else if slack <= 10 {
            score -= 20.0; // next item nearly fills bin
        } else {
            score -= 8.0 + 10.0 * (slack / cap); // mild reward for reusable leftover
        }
    } else if next_item_size > pr && next_item_size > 0 {
        // Next item won't fit here: penalize proportionally to how "wasted" this placement is.
        score += 6.0;
    }

    // Last-chance logic: if this is the only bin that fits, prefer using it over opening a new bin
    // unless the fit is terrible (large dead space).
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        if pr > 10 {
            score -= 25.0;
        } else {
            score -= 5.0;
        }
    }

    // New-bin candidate handling: a fresh bin has full residual. Only prefer it when current
    // open bins are mostly full and the fit here would create dead space.
    if bin_residual == bin_capacity {
        // Baseline for a new bin: slightly worse than a good fit, better than a dead-space fit.
        score = 0.35 * cap + 10.0;
        // As stream progresses and many bins are open, discourage excessive bin proliferation.
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score += 15.0 * progress;
        // If mean residual is large, prefer reusing existing bins.
        score += 0.25 * mean_residual;
    } else {
        // Tightness reward: filling a mostly-full bin is good (best-fit behavior sharpened).
        let fill_ratio = (bin_capacity - bin_residual) as f64 / cap;
        score -= 10.0 * fill_ratio;
    }

    // Mean-residual harmonic coupling: penalize placements that push bin far below mean residual
    // class (creating outliers), mildly.
    let pr_class = (pr / 25) as f64;
    let mean_class = (mean_residual / 25.0).floor();
    if pr_class < mean_class {
        score += 5.0 * (mean_class - pr_class);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Penalize unusable small dead space: gaps below the minimum item size are pure waste.
    if post_residual > 0 && post_residual < 10 {
        score += (10 - post_residual) as f64 * 6.0;
    }
    // Perfect fit reward.
    if post_residual == 0 {
        score -= 25.0;
    }

    // Tight-but-usable residual reward: small gap that still fits smallest items is fine.
    if post_residual >= 10 && post_residual <= 20 {
        score -= 4.0;
    }

    // Dead-space pressure grows with stream progression.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += (post_residual as f64 / bin_capacity as f64) * 20.0 * progress;

    // Open-bin pressure: discourage spreading across too many bins late in the stream.
    score += open_bins_count as f64 * 0.6;

    // Last-chance bonus: if this is the only fitting bin, strongly prefer it.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate: penalize opening a new bin unless current fit is terrible.
    if bin_residual == bin_capacity {
        score += 35.0;
        if post_residual as f64 > item_size as f64 * 0.5 {
            score += 10.0;
        }
    }

    // Lookahead: favor bins whose post-residual can still host the next item.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 8.0;
        } else if post_residual > 0 {
            score += 5.0;
        }
    }

    // Prefer bins tighter than the mean residual (waste consolidation).
    if (post_residual as f64) < mean_residual {
        score -= 3.0;
    } else {
        score += 3.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
