pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Penalize relative wasted space (tight fits preferred)
    let fill_ratio = item_size as f64 / bin_capacity as f64;
    score -= fill_ratio * 25.0;

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 35.0;
    }

    // Lookahead (k=2): reward if the next item can still fit in the post residual
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 15.0;
        } else {
            // Penalize dead space the next item cannot use
            score += (next_item_size as f64 - post_residual as f64).max(0.0) * 0.4;
        }
    }

    // New-bin candidate: penalize unless it is genuinely attractive
    if bin_residual == bin_capacity {
        score += 55.0;
        // Late in the stream, new bins are less costly (fewer future items to fill them)
        let t = step_index as f64 / (total_items.max(1) as f64);
        score -= t * 30.0;
    }

    // Global state: many open bins with high mean residual -> prefer reusing fuller bins
    if open_bins_count > 2 {
        score += mean_residual * 0.08;
    }

    // Time horizon: early on, keep residuals flexible; late, just pack tightly
    let t = step_index as f64 / (total_items.max(1) as f64);
    score += (1.0 - t) * post_residual as f64 * 0.15;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Normalized stream progress
    let progress = step_index as f64 / total_items.max(1) as f64;
    let prog01 = progress.clamp(0.0, 1.0);

    // Non-linear polynomial coupling of post_residual with progress
    let pr = post_residual as f64;
    let pr_norm = pr / cap;
    let poly = pr_norm * pr_norm * (1.0 - prog01) + pr_norm * prog01 * (1.0 - pr_norm);
    score += 12.0 * poly;

    // Penalize large dead space more than proportionally (quadratic dead-space term)
    if post_residual > 0 {
        score += 0.02 * pr * pr / cap;
    }

    // Perfect fit reward
    if post_residual == 0 {
        score -= 25.0;
    }

    // Lookahead coupling: reward residual that exactly fits next item
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if (pr - nxt).abs() < 0.5 {
            score -= 15.0;
        } else if pr >= nxt {
            score -= 3.0 * (1.0 - ((pr - nxt) / cap).abs());
        } else {
            score += 4.0 * (nxt - pr) / cap;
        }
    }

    // Last-chance bin bonus: strongly favor using the only fitting bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 20.0;
    }

    // Mean residual alignment: prefer bins whose residual is close to the mean
    let dev = (pr - mean_residual).abs();
    score += 0.5 * dev;

    // Mild pressure to reuse open bins as stream progresses
    score -= 2.0 * prog01 * (1.0 - pr_norm);

    // Slight penalty for opening new bins when many bins are open
    if bin_residual == bin_capacity {
        score += 3.0 + 0.1 * open_bins_count as f64;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap_f = bin_capacity as f64;
    let mut score = post_residual as f64;
    let progress = step_index as f64 / total_items.max(1) as f64;

    // Dead-space avoidance: tiny unusable gaps are the worst outcome.
    if post_residual == 0 {
        // Perfect fit: dominant reward.
        score -= 900.0;
    } else if post_residual <= 3 {
        score -= 350.0;
    } else if post_residual < 10 {
        score += 60.0;
    } else if post_residual < 20 {
        score += 25.0;
    } else if post_residual < 30 {
        score += 18.0 + (30 - post_residual) as f64 * 0.6;
    } else {
        score -= (post_residual as f64).ln() * 6.0;
    }

    // Lookahead (k=2): favor leftovers that host or exactly match the next item.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 700.0;
        } else if post_residual >= next_item_size {
            let post2 = post_residual - next_item_size;
            score -= 100.0 - post2 as f64 * 2.0;
            if post2 == 0 {
                score -= 80.0;
            }
            if post2 > 0 && post2 < 5 {
                score -= 25.0;
            }
            if post_residual % next_item_size == 0 {
                score -= 15.0;
            }
        } else {
            // Leftover too small for the next item: dead space risk.
            let gap = next_item_size as f64 - post_residual as f64;
            score += 20.0 + gap * 0.6;
            if gap <= 3.0 {
                score += 30.0;
            }
            if post_residual as f64 > mean_residual * 1.4 {
                score -= 12.0;
            }
        }
    }

    // Last-chance bin: strongly favor using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 35.0;
    }

    // Open-bin pressure: discourage spreading while many bins are open.
    score += (open_bins_count as f64).powf(1.3) * 0.5 * (1.0 - progress);

    // Prefer bins tighter than average (consolidation of residuals).
    score += (mean_residual - bin_residual as f64) * 0.9;

    // New-bin candidate logic: open only when item is huge or fits would be terrible.
    if bin_residual == bin_capacity {
        let newbin_waste = (bin_capacity - item_size) as f64;
        let avg_fill = 1.0 - (mean_residual / cap_f);
        score += 250.0 - avg_fill * 330.0 - progress * 65.0;
        if item_size >= 70 && fitting_bins_count == 0 {
            score -= 25.0;
        }
        if item_size as f64 / cap_f > 0.85 {
            score -= 45.0;
        }
        if bin_capacity - item_size <= 4 {
            score -= 70.0;
        }
        if fitting_bins_count > 0 {
            score += (fitting_bins_count.min(5) as f64) * 9.0 + 20.0;
            let snug = item_size as f64 / (bin_residual.max(1) as f64);
            if snug > 0.9 {
                score += 40.0;
            }
            if snug > 0.95 {
                score += 28.0;
            }
        }
        if next_item_size > 0 && next_item_size <= bin_capacity - item_size {
            score -= 25.0;
        }
        if newbin_waste > 0.0 && (newbin_waste as u32) < next_item_size && newbin_waste < cap_f * 0.12 {
            score += 26.0;
        }
        if progress > 0.6 {
            let waste_tol = (1.0 - progress) * cap_f * 0.35;
            if newbin_waste > waste_tol && fitting_bins_count > 0 {
                score += 10.0 + progress * 22.0;
            }
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit reward
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Harmonic class of the residual: residuals in the "small sliver" band are dead space
    let cls = post_residual / 10; // 0..=10 harmonic classes
    match cls {
        0 => score -= 50.0,                       // 0..9: nearly perfect
        1 => score -= 20.0,                       // 10..19: usable for small items
        2 | 3 => score -= 5.0,                    // 20..39: moderately useful
        4 | 5 => score += 0.0,                    // 40..59: neutral
        6 | 7 => score += 10.0,                   // 60..79: large gap
        _ => score += 25.0,                       // 80..99: huge dead space
    }

    // Lookahead coupling: if next item fits exactly in post_residual, big reward
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 300.0;
        } else if next_item_size <= post_residual {
            // reward proportional to how well next item packs into the leftover
            let waste_after_next = post_residual - next_item_size;
            let waste_cls = waste_after_next / 10;
            score -= 40.0 - (waste_cls as f64) * 4.0;
        } else {
            // next item won't fit here; penalize large residuals slightly more
            score += (post_residual as f64) * 0.15;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 {
        score -= 60.0;
    }

    // Modulo threshold on post_residual: residuals that are multiples of 10
    // are "harmonic" with typical item sizes; slight reward.
    if post_residual % 10 == 0 && post_residual > 0 {
        score -= 8.0;
    }

    // Integer-division threshold: bins whose residual is in [50,100) after placement
    // are half-empty; mild penalty scaled by stream progress.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    if post_residual >= 50 {
        score += 12.0 * (1.0 - progress);
    }

    // Prefer tighter bins relative to the mean residual of open bins
    score += (post_residual as f64 - mean_residual) * 0.3;

    // When many bins are open, discourage spreading (favor filling existing bins)
    if open_bins_count > 4 {
        score += 5.0;
    }

    // New-bin candidate: penalize opening a fresh bin unless current bin would
    // leave an awkward residual and next item is large.
    if bin_residual == bin_capacity {
        let awkward = post_residual >= 40 && post_residual <= 70;
        if next_item_size > 0 && next_item_size > post_residual && awkward {
            score -= 30.0; // opening a new bin is justified
        } else {
            score += 80.0; // generally prefer existing bins
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
