pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals too small for the minimum item (1)
    // are fine (perfect fit), but small non-zero gaps that no realistic future
    // item (sizes 1..100, unknown distribution) can use are heavily penalized.
    if post_residual > 0 {
        // gap smaller than next item AND smaller than a typical small item:
        // dead space risk rises steeply as gap shrinks.
        let gap = post_residual as f64;
        let next = next_item_size as f64;
        if next > 0.0 && gap < next {
            score += (next - gap) * 3.0; // gap unusable by the known lookahead
        }
        // absolute tiny-gap penalty (unusable sliver)
        if gap < 10.0 {
            score += (10.0 - gap) * 4.0;
        }
    } else {
        // perfect fit: strong reward
        score -= 25.0;
    }

    // Reward placements that still allow the lookahead item to fit here later
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 2.0 + (post_residual - next_item_size) as f64 * 0.05;
    }

    // Last-chance bin: if this is the only bin that fits, strongly prefer it
    // over opening a new bin (avoid bin proliferation).
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 15.0;
    }

    // Open-bin pressure: with many open bins, discourage new bins / encourage
    // consolidation into existing bins.
    let pressure = (open_bins_count as f64).ln().max(0.0);
    if bin_residual == bin_capacity {
        // new-bin candidate: base cost plus pressure; cheap only when few bins open
        score += 30.0 + pressure * 8.0;
        // opening a new bin is more attractive late in the stream when residuals
        // elsewhere are large and fragmented
        if mean_residual > item_size as f64 * 1.5 {
            score -= 5.0;
        }
    } else {
        // existing bin: mild reward to consolidate, scaled by pressure
        score -= pressure * 2.0;
    }

    // Slight preference for bins with residuals close to the item (tight fit)
    let tightness = (bin_residual - item_size) as f64;
    score += tightness * 0.1;

    // Early-stream tie-break: keep scores comparable across phases
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += progress * 0.5;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer tight fit (small post_residual)
    let tightness = (post_residual as f64) / bin_capacity as f64;
    score += 40.0 * tightness * tightness;

    // Aggressive 2-step lookahead: reward exact match of post_residual to next item
    if next_item_size > 0 {
        let diff = (post_residual as i64 - next_item_size as i64).abs() as f64;
        let perfect = (post_residual == next_item_size) as f64;
        score -= 30.0 * perfect;
        score += 0.6 * diff;
        // If next item fits exactly into remaining space, strongly favor this bin
        if post_residual >= next_item_size {
            score -= 8.0 * (next_item_size as f64 / 100.0);
        } else {
            // next item won't fit here; penalize proportionally to wasted residual
            score += 0.3 * (post_residual as f64);
        }
    } else {
        // Last item: minimize residual entirely
        score += 0.5 * (post_residual as f64);
    }

    // Relative-to-mean coupling: bins with residual far below mean are "tight" -> prefer filling them
    score -= 0.4 * (mean_residual - post_residual as f64);

    // Last-chance bin: strongly prefer using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate handling: penalize opening a new bin unless current bins are bad fits
    if bin_residual == bin_capacity {
        let mut penalty = 55.0;
        if next_item_size > 0 && post_residual >= next_item_size {
            // new bin can host both current and next item: attractive for large pairs
            penalty -= 20.0 + 0.2 * (item_size + next_item_size) as f64;
        }
        if fitting_bins_count == 0 {
            penalty = -5.0;
        }
        score += penalty;
    }

    // Early in stream: be slightly conservative, keep bins flexible
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += 5.0 * (1.0 - progress) * tightness;

    // Many open bins: prefer consolidating into existing ones
    score += 0.05 * open_bins_count as f64 * tightness;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let score = post_residual as f64 / bin_capacity.max(1) as f64;
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tight-fit reward: strongly favor bins where the item fills most of the residual.
    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 30.0 * fit_ratio * fit_ratio;

    // Penalize creating dead space that no typical item can use.
    if post_residual > 0 && post_residual < 10 {
        score += 12.0; // tiny unusable sliver
    }

    // Lookahead coupling: if post_residual exactly or nearly fits the next item, reward heavily.
    if next_item_size > 0 {
        let gap = post_residual as i64 - next_item_size as i64;
        if gap == 0 {
            score -= 40.0; // perfect two-item chain
        } else if gap > 0 && gap < 10 {
            score -= 15.0;
        } else if gap < 0 && (-gap) < 10 {
            score += 8.0; // next item just barely won't fit: mild penalty
        }
        // Bonus if post_residual can still hold next item comfortably
        if post_residual >= next_item_size {
            score -= 5.0 * (post_residual as f64 - next_item_size as f64) / bin_capacity as f64;
        }
    }

    // Last-chance bonus: if this is the only fitting bin, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate handling: opening a new bin wastes current residual space.
    if bin_residual == bin_capacity {
        // Cost proportional to residual space being abandoned elsewhere.
        score += 0.6 * mean_residual;
        // Early in the stream, or when few bins are open, new bins are cheaper.
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score -= 20.0 * (1.0 - progress);
        score -= 2.0 / (open_bins_count as f64 + 1.0);
        // If the item is large relative to capacity, a fresh bin is attractive.
        score -= 0.15 * item_size as f64;
        // But if an existing bin fits perfectly, never open a new one.
        if post_residual == 0 && bin_residual < bin_capacity {
            score -= 100.0;
        }
    } else {
        // Reward using existing bins, scaled by how much residual we consume.
        score -= 10.0 * (1.0 - post_residual as f64 / bin_capacity as f64);
        // Prefer spreading load when many bins are open and mean residual is high.
        if bin_residual as f64 > mean_residual {
            score -= 3.0; // pick a roomier-than-average bin for big leftovers
        }
    }

    // Late-stream consolidation: as we approach the end, avoid leaving many fragmented bins.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += 5.0 * progress * (post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap_f = bin_capacity as f64;
    let progress = step_index as f64 / total_items.max(1) as f64;
    let mut score = post_residual as f64;

    // Perfect fit: dominant reward.
    if post_residual == 0 {
        score -= 900.0;
    } else if post_residual <= 3 {
        score -= 320.0;
    } else if post_residual <= 12 {
        score -= 60.0;
    } else if post_residual < 20 {
        score += 12.0;
    } else if post_residual < 30 {
        score += 12.0 + (30 - post_residual) as f64 * 0.5;
    }

    // Lookahead chaining: reward leaving exactly room for next item.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 600.0;
        } else if next_item_size < post_residual {
            let post2 = post_residual - next_item_size;
            score -= 90.0 - post2 as f64 * 1.5;
            if post2 == 0 { score -= 80.0; }
            if post2 > 0 && post2 < 5 { score -= 20.0; }
            if post2 > 0 && post2 <= next_item_size / 2 { score -= 8.0; }
            if post_residual % next_item_size == 0 { score -= 12.0; }
        } else {
            // Next item cannot fit here: penalize dead space proportionally.
            let gap = (next_item_size - post_residual) as f64;
            score += gap * 0.8;
            if post_residual > 0 && gap <= 5.0 { score += 18.0; }
            if post_residual > 0 && post_residual < 15 { score += 25.0; }
        }
    }

    // Dead-space avoidance: residuals too small for plausible future items.
    if post_residual > 0 && (post_residual as f64) < 12.0 {
        score += (12.0 - post_residual as f64) * 5.0;
    }
    if post_residual > 0 && (post_residual as f64) < mean_residual * 0.25 {
        score -= 10.0;
    }

    // Tightness reward for near-full bins.
    if post_residual > 0 {
        let tightness = 1.0 - (post_residual as f64) / cap_f;
        score -= tightness * tightness * 12.0;
        let dead_ratio = post_residual as f64 / cap_f;
        if dead_ratio < 0.03 { score -= 25.0; }
        else if dead_ratio < 0.08 { score -= 10.0; }
        else if dead_ratio > 0.30 { score += 18.0; }
        if item_size == bin_residual { score -= 30.0; }
    }

    // Last-chance bonus: only fitting open bin.
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 22.0;
    }

    // Open-bin pressure: mild reuse preference.
    score += open_bins_count as f64 * 0.4;

    // ---- New-bin candidate logic ----
    if bin_residual == bin_capacity {
        let leftover = bin_capacity - item_size;
        let newbin_waste = leftover as f64;
        let avg_fill = 1.0 - mean_residual / cap_f;
        score += 200.0 - avg_fill * 260.0 - progress * 55.0;

        if fitting_bins_count > 0 {
            score += (fitting_bins_count as f64).min(5.0) * 8.0;
            let snug = item_size as f64 / bin_residual.max(1) as f64;
            if snug > 0.9 { score += 30.0; }
            if snug > 0.95 { score += 20.0; }
            // Compare new-bin waste vs best alternative waste.
            let best_alt = if item_size as f64 <= mean_residual { mean_residual - item_size as f64 } else { mean_residual };
            if newbin_waste > best_alt + cap_f * 0.08 { score += 18.0; }
            if newbin_waste > best_alt + cap_f * 0.2 { score += 12.0; }
        } else {
            // No open bin fits: opening a new bin is necessary, make it cheap.
            score -= 60.0;
        }

        // Large items pair well in fresh bins.
        if item_size >= bin_capacity * 3 / 4 { score -= 40.0; }
        if bin_capacity - item_size <= 4 { score -= 50.0; }
        if next_item_size > 0 && next_item_size >= bin_capacity / 2 { score -= 22.0; }

        // New-bin leftover compatible with next item chain.
        if next_item_size > 0 {
            if leftover >= next_item_size {
                let tail = leftover % next_item_size;
                if tail == 0 { score -= 14.0; }
                else if tail <= 4 { score -= 8.0; }
            } else if leftover < 10 {
                score += 12.0;
            }
        }
        // Fresh-bin waste small relative to mean residual: keep it closed.
        if newbin_waste < mean_residual * 0.5 { score += 20.0; }
        // Late stream: be conservative, prefer reusing.
        if progress > 0.7 && newbin_waste > cap_f * 0.4 { score += 10.0; }
    } else {
        // Residual alignment: avoid outlier residuals.
        score += ((post_residual as f64) - mean_residual).abs() * 0.12;
    }

    score
}

