            if post_residual > 0 && gap <= 3.0 { score += 30.0; }
        }
        // Chain reward: leave room for the lookahead item.
        if post_residual >= next_item_size {
            score -= 6.0 + (post_residual - next_item_size) as f64 * 0.08;
        }
    }

    // Last-chance bonus: only fitting open bin.
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
