    // Global state: many open bins with large mean residual -> discourage spreading.
    if open_bins_count > 3 && mean_residual > item_size as f64 {
        score += 0.05 * open_bins_count as f64;
    }

    // New-bin candidate handling.
    if bin_residual == bin_capacity {
        let newbin_waste = (bin_capacity - item_size) as f64;
        let avg_fill = 1.0 - (mean_residual / cap_f);
        // Base aversion to opening a new bin, modulated by fill level and progress.
        score += 250.0 - avg_fill * 330.0 - progress * 65.0;

        // A new bin is attractive when the item fits snugly (little waste).
        let snug = item_size as f64 / bin_residual.max(1) as f64;
        if snug > 0.9 {
            score -= 40.0;
        }
        if snug > 0.95 {
            score -= 25.0;
        }
        if item_size >= bin_capacity * 3 / 4 {
            score -= 45.0;
        }
        if bin_capacity - item_size <= 4 {
            score -= 60.0;
        }
        // Next item pairs with the fresh bin's leftover.
        if next_item_size > 0 {
            let leftover = bin_capacity - item_size;
            if leftover >= next_item_size {
                let tail = leftover % next_item_size;
                if tail == 0 {
                    score -= 20.0;
                } else if tail <= 4 {
                    score -= 12.0;
                }
                if leftover >= next_item_size * 2 {
                    score -= 10.0;
                }
            }
            if leftover < next_item_size && leftover < 10 {
                score += 15.0;
            }
            if leftover >= next_item_size && leftover - next_item_size <= 6 {
                score -= 30.0;
            }
        }
        // Avoid opening a bin when existing bins already hold lots of room.
        if fitting_bins_count > 0 && newbin_waste > mean_residual + cap_f * 0.1 {
            score += 20.0;
        }
        // Small awkward leftover for next item -> prefer fresh bin.
        if next_item_size > 0 && newbin_waste > 0.0 && (newbin_waste as u32) < next_item_size && newbin_waste < cap_f * 0.12 {
            score += 20.0;
        }
    } else {
        // Existing bin: reward tightness relative to what it held.
        let tightness = 1.0 - (item_size as f64 / bin_residual.max(1) as f64);
        score += tightness * 60.0;
        score += (mean_residual - bin_residual as f64) * 1.2;
        let dead_ratio = post_residual as f64 / cap_f;
        if dead_ratio < 0.03 {
            score -= 30.0;
        } else if dead_ratio > 0.30 {
            score += 20.0;
        }
        // Unusable dead space relative to next item.
        if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size && (next_item_size - post_residual) > 12 {
            score += dead_ratio * 70.0;
        }
        // Chain potential: residual can hold several copies of next item.
        if next_item_size > 0 && post_residual >= next_item_size {
            let chain = post_residual / next_item_size;
            if chain >= 2 {
                score -= (chain.min(4)) as f64 * 5.0;
            }
        }
        if item_size == bin_residual {
            score -= 35.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap_f = bin_capacity as f64;
    let mut score = post_residual as f64;
    let progress = step_index as f64 / total_items.max(1) as f64;

    // Strong exact / near-exact fit rewards (borrowed from best heuristic).
    if post_residual == 0 {
        score -= 1180.0;
    } else if post_residual <= 3 {
        score -= 500.0;
    } else if post_residual <= 12 {
        score -= 98.0;
    } else if post_residual < 20 {
        score += 18.0;
    } else if post_residual < 30 {
        score += 18.0 + (30 - post_residual) as f64 * 0.6;
    }

    // Lookahead: reward placements whose residual can host the next item.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 900.0;
        } else if next_item_size <= post_residual {
            let post2 = post_residual - next_item_size;
            score -= 135.0 - post2 as f64 * 2.0;
            if post2 == 0 {
                score -= 110.0;
            }
            if post2 > 0 && post2 < 5 {
                score -= 28.0;
            }
            if post2 >= 20 && post2 % 5 == 0 {
                score -= 12.0;
            }
            if post_residual % next_item_size == 0 {
                score -= 18.0;
            }
            if post2 > 0 && post2 <= next_item_size / 4 {
                score -= 10.0;
            }
        } else {
            // Next item won't fit here: penalize blocking residuals.
            score += 20.0;
            let gap = next_item_size as f64 - post_residual as f64;
            if gap <= 3.0 {
                score += 35.0;
            }
            if post_residual > 0 && post_residual < 15 {
                score += 45.0;
            }
            if post_residual as f64 > mean_residual * 1.4 {
                score -= 12.0;
                if progress > 0.7 {
                    score -= 8.0;
                }
            }
        }
    }

    // Last-chance bin: favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 25.0;
    }
    if fitting_bins_count > 1 {
        score += 2.0 * (fitting_bins_count as f64 - 1.0);
    }

    // Dead-space characterization relative to capacity.
    let dead_ratio = post_residual as f64 / cap_f;
    if post_residual > 0 {
        if dead_ratio < 0.03 {
            score -= 38.0;
        } else if dead_ratio < 0.08 {
            score -= 14.0;
        } else if dead_ratio > 0.35 {
            score += 24.0;
        } else if dead_ratio > 0.25 {
            score += 10.0;
        }
    }

    // New-bin candidate logic.
    if bin_residual == bin_capacity {
        let newbin_waste = (bin_capacity - item_size) as f64;
        let avg_fill = 1.0 - (mean_residual / cap_f);
        score += 250.0 - avg_fill * 330.0 - progress * 65.0;
        if fitting_bins_count > 0 {
            score += fitting_bins_count.min(5) as f64 * 9.0 + 20.0;
            let snug = item_size as f64 / bin_residual.max(1) as f64;
            if snug > 0.9 { score += 40.0; }
            if snug > 0.95 { score += 28.0; }
            if snug > 0.98 { score += 18.0; }
        }
        if item_size as f64 > mean_residual {
            score -= 45.0;
        }
        if item_size >= bin_capacity * 3 / 4 {
            score -= 55.0;
        }
        if bin_capacity - item_size <= 4 {
            score -= 70.0;
        }
        if next_item_size > 0 {
            let leftover = bin_capacity - item_size;
            if leftover >= next_item_size {
                let tail = leftover % next_item_size;
                if tail == 0 { score -= 26.0; }
                else if tail <= 4 { score -= 16.0; }
            }
            if leftover < next_item_size && leftover < 10 {
                score += 18.0;
            }
        }
        if newbin_waste > 0.0 && newbin_waste < mean_residual * 0.6 {
            score -= 30.0;
        }
        if fitting_bins_count > 0 {
            let best_alt = if item_size as f64 <= mean_residual { mean_residual - item_size as f64 } else { mean_residual };
            if newbin_waste > best_alt + cap_f * 0.08 { score += 22.0; }
            if newbin_waste > best_alt + cap_f * 0.2 { score += 14.0; }
        }
        if progress > 0.6 {
            let waste_tol = (1.0 - progress) * cap_f * 0.35;
            if newbin_waste > waste_tol && fitting_bins_count > 0 {
                score += 10.0 + progress * 22.0;
            }
        }
        if newbin_waste > 0.0 && (newbin_waste as u32) < next_item_size && newbin_waste < cap_f * 0.12 {
            score += 26.0;
        }
    } else {
        // Existing-bin tightness shaping.
        let tightness = 1.0 - (item_size as f64 / bin_residual.max(1) as f64);
        score += tightness * 85.0;
        score += (mean_residual - bin_residual as f64) * 1.5;
        if item_size == bin_residual {
            score -= 45.0;
        }
        if next_item_size > 0 && post_residual > 0 {
            let unusable = post_residual < next_item_size && (next_item_size - post_residual) > 12;
            if unusable {
                score += dead_ratio * 90.0;
            } else {
                let reuse = (post_residual / next_item_size) as f64 * (next_item_size as f64 / cap_f);
                score -= reuse * 22.0;
            }
        }
        if post_residual > 0 && next_item_size > 0 && post_residual < next_item_size {
            let gap = next_item_size as f64 - post_residual as f64;
            if gap > mean_residual * 0.6 && fitting_bins_count > 2 {
                score += gap * 0.8;
            }
            score += (1.0 - progress) * 14.0;
        }
        if post_residual > 0 && next_item_size > 0 && post_residual >= next_item_size {
            let chain = post_residual / next_item_size;
            if chain >= 2 {
                score -= chain.min(4) as f64 * 6.0;
            }
        }
        if post_residual > 0 && (post_residual as f64) < mean_residual * 0.25 {
            score -= 15.0;
        }
        if post_residual > 0 && post_residual < 6 {
            score -= 22.0;
        }
        if post_residual > 0 && (post_residual as f64) > mean_residual * 1.6 && fitting_bins_count > 2 {
            score += 10.0;
        }
    }

    // Global state: discourage spreading when many open bins hold large residual.
    if open_bins_count > 3 && mean_residual > item_size as f64 {
        score += 0.05 * open_bins_count as f64;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let score = post_residual as f64 / bin_capacity.max(1) as f64;
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let mut score = pr;

    // Non-linear polynomial coupling of post_residual with stream progress.
    let norm_pr = pr / cap; // in [0,1]
    let p2 = progress * progress;
    let p3 = p2 * progress;
    // As stream progresses, waste becomes more costly (amplified weight on residual).
    let progress_weight = 0.5 + 2.0 * (p2 + 0.5 * p3);
    score += progress_weight * norm_pr * norm_pr * cap * 0.5;

    // Penalize large dead space relative to mean residual (fragmentation signal).
    let frag = (pr - mean_residual) / cap;
    score += 3.0 * frag * frag * cap * (1.0 - progress);

    // Perfect fit reward: strongly subtract for near-zero post residual.
    if pr == 0 {
        score -= 50.0 + 50.0 * progress;
    } else {
        let tightness = 1.0 - norm_pr;
        score -= 10.0 * tightness * tightness * tightness;
    }

    // Lookahead coupling: reward if next item fits the post residual.
    if next_item_size > 0 && (next_item_size as f64) <= pr {
        score -= 8.0 * (next_item_size as f64 / cap) * (1.0 + progress);
    } else if next_item_size > 0 {
        // Next item won't fit here: penalize leaving medium residual that becomes dead space.
        score += 4.0 * norm_pr * (1.0 - norm_pr) * (1.0 + progress);
    }

    // Last-chance bin: strong reward to use it instead of opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // Penalize opening a brand-new bin, more so early when open bins exist.
    if bin_residual == bin_capacity {
        score += 30.0 + 20.0 * (1.0 - progress) + open_bins_count as f64;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the leftover space: items of size dividing capacity nicely
    // leave "perfect" residuals. Reward residuals that are multiples of common
    // small sizes (harmonic classes 10, 20, 25, 50).
    let pr = post_residual;
    if pr == 0 {
        score -= 60.0; // perfect closure
    } else if pr % 50 == 0 {
        score -= 25.0;
    } else if pr % 25 == 0 {
        score -= 15.0;
    } else if pr % 20 == 0 {
        score -= 12.0;
    } else if pr % 10 == 0 {
        score -= 8.0;
    } else {
        // dead space penalty grows for awkward remainders
        score += ((pr % 10) as f64) * 1.5;
    }

    // Penalize residuals in the "unfillable" band: too small for the smallest
    // plausible item (assume >=10), i.e. 1..10 is guaranteed dead space.
    if pr > 0 && pr < 10 {
        score += 40.0;
    }

    // Lookahead coupling: does the next item fit into the post residual?
    if next_item_size > 0 {
        if next_item_size <= pr {
            // next item fits exactly or leaves a harmonic remainder
            let nxt = next_item_size;
            if pr - nxt == 0 {
                score -= 30.0;
            } else if (pr - nxt) % 10 == 0 {
                score -= 10.0;
            }
            // small bonus for a tight next-fit
            score -= 5.0;
        } else {
            // next item will not fit here: this bin becomes dead-ended
            score += 8.0 + ((next_item_size - pr) as f64) * 0.3;
        }
    }

    // Last-chance bin: if this is the only bin that fits, strongly favor using it
    // to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 20.0;
    }

    // New-bin candidate handling: opening a new bin is only attractive when the
    // current item is large relative to capacity or open-bin pressure is low.
    if bin_residual == bin_capacity {
        // base handicap so we prefer existing bins with good fits
        score += 25.0;
        // but if the item is huge, packing it alone may be wise
        if item_size >= 50 {
            score -= (item_size - 50) as f64 * 0.8;
        }
        // early in the stream, opening bins is cheaper
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score -= (1.0 - progress) * 10.0;
        // fewer open bins -> opening one is less costly
        score -= (open_bins_count as f64).min(10.0) * 0.5;
    } else {
        // Prefer tighter fits among open bins: reward small post_residual.
        score -= (bin_capacity - bin_residual) as f64 * 0.05;

        // Prefer bins whose residual is below the mean (more "full" bins),
        // encouraging consolidation.
        let res_f = bin_residual as f64;
        if res_f < mean_residual {
            score -= 4.0;
        } else {
            score += 2.0;
        }
    }

    // Mid-stream consolidation pressure: as the stream progresses, discourage
    // spreading items across many partially-filled bins.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    if bin_residual < bin_capacity {
        score += progress * ((post_residual % 5) as f64) * 2.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals in [1, 9] are nearly unusable
    // (items are >= 1, but typical streams have few tiny items) -> hard penalty.
    if post_residual >= 1 && post_residual <= 9 {
        score += 60.0;
    }
    // Medium dead space (10..=19) is only usable by small items; moderate penalty.
    else if post_residual <= 19 {
        score += 18.0;
    }
    // Perfect or near-perfect fit: strong reward.
    if post_residual == 0 {
        score -= 40.0;
    } else if post_residual <= 5 {
        score -= 12.0;
    }

    // If the next item fits exactly into the post residual, reward heavily (chaining).
    if next_item_size > 0 && post_residual >= next_item_size {
        let slack = (post_residual - next_item_size) as f64;
        if slack <= 9.0 {
            score -= 25.0 - slack * 1.5;
        } else {
            score -= 8.0;
        }
    }
    // If next item does NOT fit in post residual, penalize slightly when post residual
    // is a stranded small gap.
    if next_item_size > 0 && post_residual < next_item_size && post_residual > 0 && post_residual < 10 {
        score += 15.0;
    }

    // Last-chance bin: if this is the only bin that fits, strongly prefer using it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // Open-bin pressure: with many open bins, prefer filling existing ones;
    // with few open bins, tolerate opening new bins less aggressively.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    let pressure = (open_bins_count as f64).ln().max(0.0) * (6.0 + 10.0 * progress);
    score += pressure;

    // Deviation from mean residual: bins far below mean residual are "smaller"
    // and should be filled first to consolidate space.
    let dev = mean_residual - bin_residual as f64;
    score += dev * 0.35;

    // New-bin candidate: empty bin gets a mild penalty so it only wins when
    // all open bins have bad fits (their penalties dominate).
    if bin_residual == bin_capacity {
        score += 45.0 + 8.0 * (open_bins_count as f64).ln().max(0.0);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong lookahead match: if next item fits exactly into post_residual, big reward.
    if next_item_size > 0 {
        let next = next_item_size as f64;
        let post = post_residual as f64;
        if next <= post {
            // Reward proportional to tightness of the 2-step fit.
            score -= 60.0 * (1.0 - (post - next) / bin_capacity as f64);
        } else {
            // Penalize post_residuals that cannot host the next item (dead space risk).
            score += 20.0 * ((post - next) / bin_capacity as f64).abs();
        }
    }

    // Prefer bins tighter than the mean (better space utilization).
    score += 0.5 * (mean_residual - bin_residual as f64).max(0.0);
    score -= 0.3 * (bin_residual as f64 - mean_residual).max(0.0);

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 40.0;
    }

    // New-bin candidate: penalize opening a new bin unless the item is large
    // relative to capacity (large items benefit from fresh space).
    if bin_residual == bin_capacity {
        let frac = item_size as f64 / bin_capacity as f64;
        score += 55.0 - 40.0 * frac;
        // Early in the stream, fresh bins are more valuable.
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score -= 15.0 * (1.0 - progress);
    }

    // Mild penalty for very small post-residuals that waste capacity.
    if post_residual > 0 && post_residual < 10 {
        score += 10.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: penalize post_residual relative to bin capacity (relative waste).
    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 8.0 * fit_ratio;

    // Penalize dead space that is too small to be useful for typical items.
    if post_residual > 0 && post_residual < 10 {
        score += 12.0;
    } else if post_residual >= 10 && post_residual < 20 {
        score += 4.0;
    }

    // Last-chance bonus: if this is the only fitting bin, strongly prefer it.
    if fitting_bins_count == 1 {
        score -= 15.0;
    }

    // Lookahead: if next item fits into post_residual, reward this placement.
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            score -= 10.0;
        } else {
            score += 2.0;
        }
    }

    // Time horizon: early in the stream, be conservative (favor filling existing bins);
    // late in the stream, allow opening new bins more freely since waste matters less.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    if bin_residual == bin_capacity {
        // New-bin candidate: penalize early, reward late.
        score += 20.0 * (1.0 - progress) - 5.0 * progress;
    } else {
        score -= 3.0 * progress;
    }

    // Global state coupling: many open bins with high mean residual -> prefer existing bins.
    let mean_res_ratio = mean_residual / bin_capacity as f64;
    if bin_residual != bin_capacity {
        score -= 5.0 * mean_res_ratio * (open_bins_count as f64).sqrt();
    }

    // Prefer bins whose residual is close to item size (minimize fragmentation).
    let gap = (bin_residual as f64 - item_size as f64).abs();
    score += 0.05 * gap;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap_f = bin_capacity as f64;
    let progress = step_index as f64 / total_items.max(1) as f64;
    let mut score = post_residual as f64;

    // Perfect fit: dominant reward.
    if post_residual == 0 {
        score -= 1100.0;
    } else if post_residual <= 3 {
        score -= 420.0;
    } else if post_residual <= 12 {
        score -= 80.0;
    } else if post_residual < 20 {
        score += 14.0;
    } else if post_residual < 30 {
        score += 14.0 + (30 - post_residual) as f64 * 0.55;
    }

    // Lookahead chaining: reward leaving exactly room for next item.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 750.0;
        } else if next_item_size < post_residual {
            let post2 = post_residual - next_item_size;
            score -= 110.0 - post2 as f64 * 1.8;
            if post2 == 0 { score -= 95.0; }
            if post2 > 0 && post2 < 5 { score -= 24.0; }
            if post2 > 0 && post2 <= next_item_size / 4 { score -= 10.0; }
            if post2 > 0 && post2 <= next_item_size / 2 { score -= 6.0; }
            if post_residual % next_item_size == 0 { score -= 15.0; }
            if post_residual >= next_item_size * 2 && post_residual - next_item_size * 2 <= 4 { score -= 18.0; }
        } else {
            // Next item cannot fit here: penalize dead space proportionally.
            let gap = (next_item_size - post_residual) as f64;
            score += gap * 0.7;
            if post_residual > 0 && gap <= 5.0 { score += 22.0; }
            if post_residual > 0 && post_residual < 15 { score += 30.0; }
            if post_residual > 0 && gap > mean_residual * 0.6 && fitting_bins_count > 2 { score += gap * 0.4; }
        }
    }

    // Dead-space avoidance: residuals too small for plausible future items.
    if post_residual > 0 && (post_residual as f64) < 12.0 {
        score += (12.0 - post_residual as f64) * 5.0;
    }
    if post_residual > 0 && (post_residual as f64) < mean_residual * 0.25 {
