        let dead_ratio = post_residual as f64 / cap_f;
        if dead_ratio < 0.03 { score -= 30.0; }
        else if dead_ratio < 0.08 { score -= 12.0; }
        else if dead_ratio > 0.30 { score += 20.0; }
        if item_size == bin_residual { score -= 40.0; }
        // Unusable dead space relative to next item.
        if next_item_size > 0 && post_residual < next_item_size && (next_item_size - post_residual) > 12 {
            score += dead_ratio * 70.0;
        }
        // Chain potential: residual can host multiple next items.
        if next_item_size > 0 && post_residual >= next_item_size {
            let chain = post_residual / next_item_size;
            if chain >= 2 { score -= (chain.min(4)) as f64 * 7.0; }
        }
    }

    // Last-chance bonus: only fitting open bin.
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 26.0;
    }

    // Open-bin pressure: mild reuse preference.
    score += open_bins_count as f64 * 0.4;

    // ---- New-bin candidate logic ----
    if bin_residual == bin_capacity {
        let leftover = bin_capacity - item_size;
        let newbin_waste = leftover as f64;
        let avg_fill = 1.0 - mean_residual / cap_f;
