            if item_size as f64 > mean_residual { score -= 35.0; }
        } else {
            // No open bin fits: opening a new bin is necessary, make it cheap.
            score -= 70.0;
        }

        // Large items pair well in fresh bins.
        if item_size >= bin_capacity * 3 / 4 { score -= 48.0; }
        if bin_capacity - item_size <= 4 { score -= 60.0; }
        if next_item_size > 0 && next_item_size >= bin_capacity / 2 { score -= 26.0; }
        if next_item_size > 0 && next_item_size <= leftover && leftover - next_item_size <= 6 { score -= 30.0; }

        // New-bin leftover compatible with next item chain.
        if next_item_size > 0 {
            if leftover >= next_item_size {
                let tail = leftover % next_item_size;
                if tail == 0 { score -= 16.0; }
                else if tail <= 4 { score -= 9.0; }
                if leftover >= next_item_size * 2 { score -= 12.0; }
            } else if leftover < 10 {
                score += 14.0;
            }
            let ldiff = (leftover as f64 - mean_residual).abs();
            if ldiff < cap_f * 0.05 { score -= 10.0; }
        }
        // Fresh-bin waste small relative to mean residual: keep it closed.
        if newbin_waste < mean_residual * 0.5 { score += 22.0; }
        // Late stream: be conservative, prefer reusing.
        if progress > 0.7 && newbin_waste > cap_f * 0.4 { score += 12.0; }
