            let snug = item_size as f64 / (bin_residual.max(1) as f64);
            if snug > 0.9 { score += 40.0; }
            if snug > 0.95 { score += 28.0; }
            if snug > 0.98 { score += 18.0; }
        }
        if next_item_size > 0 && next_item_size >= bin_capacity / 2 { score -= 32.0; }
        if item_size >= bin_capacity * 3 / 4 { score -= 55.0; }
        if bin_capacity - item_size <= 4 { score -= 70.0; }
        if next_item_size > 0 && next_item_size <= bin_capacity - item_size { score -= 25.0; }
        if next_item_size > 0 {
            let leftover = bin_capacity - item_size;
            if leftover >= next_item_size {
                let tail = leftover % next_item_size;
                if tail <= 4 { score -= 16.0; }
                if tail == 0 { score -= 10.0; }
            }
            if leftover >= next_item_size * 2 { score -= 14.0; }
            if leftover < next_item_size && leftover < 10 { score += 18.0; }
        }
        let newbin_waste = (bin_capacity - item_size) as f64;
        if newbin_waste > 0.0 && newbin_waste < mean_residual * 0.6 { score -= 30.0; }
        if fitting_bins_count > 0 {
            let best_alt = if item_size as f64 <= mean_residual { mean_residual - item_size as f64 } else { mean_residual };
            if newbin_waste > best_alt + cap_f * 0.08 { score += 22.0; }
            if newbin_waste > best_alt + cap_f * 0.2 { score += 14.0; }
        }
        if progress > 0.6 {
            let waste_tol = (1.0 - progress) * cap_f * 0.35;
            if newbin_waste > waste_tol && fitting_bins_count > 0 { score += 10.0 + progress * 22.0; }
        }
        if newbin_waste > 0.0 && (newbin_waste as u32) < next_item_size && newbin_waste < cap_f * 0.12 { score += 26.0; }
        if next_item_size > 0 && newbin_waste > 0.0 && (newbin_waste as u32) % next_item_size == 0 && newbin_waste >= next_item_size as f64 { score -= 20.0; }
    }

    // Consolidation preference: deviate-from-mean residual slight penalty.
    score += (bin_residual as f64 - mean_residual).abs() * 0.3;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits (low post residual) more aggressively when many bins compete.
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= tightness * 20.0;

    // Penalize bins whose residual becomes awkwardly small but nonzero (dead space).
    if post_residual > 0 && post_residual < 10 {
        score += 15.0;
    }

    // Last-chance bonus: if this is the only bin that fits, strongly prefer using it.
    if fitting_bins_count == 1 {
        score -= 30.0;
    }

    // Lookahead: if next item fits exactly in the post residual, reward heavily.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 25.0;
        } else if next_item_size <= post_residual {
            score -= 5.0;
        } else {
            // Next item won't fit here; slight penalty if we waste a large residual.
            score += (next_item_size as f64 - post_residual as f64).min(20.0) * 0.3;
        }
    }

    // Time horizon: later in the stream, consolidate more (prefer filling existing bins).
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += progress * (post_residual as f64 * 0.4);

    // Global state: many open bins with high mean residual -> favor using existing bins.
    if open_bins_count > 2 && mean_residual > item_size as f64 {
        score -= 4.0;
    }

    // New-bin candidate handling: empty bin should only win when no open bin fits well.
    if bin_residual == bin_capacity {
        score += 12.0 + progress * 10.0;
        if fitting_bins_count == 0 {
            score -= 50.0; // nothing else fits, new bin is fine
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    let progress = step_index as f64 / total_items.max(1) as f64;
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;

    // Smooth polynomial coupling: post_residual penalized more as stream progresses
    let norm_pr = pr / cap;
    score += 40.0 * norm_pr * norm_pr * (0.5 + progress);

    // Tight fit reward (quadratic dip near small post_residual)
    let tight = 1.0 - norm_pr;
    score -= 12.0 * tight * tight * tight;

    // Dead-space penalty: post_residual too small to fit plausible items
    if pr > 0.0 && pr < 10.0 {
        score += 25.0 * (10.0 - pr as f64) / 10.0;
    }

    // Lookahead coupling: reward if next item fits post_residual (smooth)
    if next_item_size > 0 {
        let fits = (pr - next_item_size as f64).max(0.0) / cap;
        score += 8.0 * fits * fits;
        let next_fit = if pr >= next_item_size as f64 { 1.0 } else { 0.0 };
        score -= 10.0 * next_fit * (1.0 - progress);
    }

    // Last-chance bonus: strongly favor using the only fitting bin
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 30.0 * (1.0 - progress);
    }

    // Prefer fuller bins relative to mean residual (smooth)
    score -= 5.0 * ((mean_residual - pr) / cap).tanh();

    // New-bin candidate: penalize mildly, less when open bins are crowded
    if bin_residual == bin_capacity {
        score += 15.0 + 3.0 * open_bins_count as f64;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: residual mod capacity-fraction classes
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let quarter = (bin_capacity / 4) as u32;
    let eighth = (bin_capacity / 8) as u32;

    // Integer-division thresholds on post_residual: penalize "dead" residual classes
    if post_residual > 0 {
        let class = post_residual / eighth; // 0..8 harmonic class
        match class {
            0 => score -= 30.0,             // near-perfect fill
            1 => score -= 12.0,
            2 => score += 6.0,              // awkward small leftover
            3 => score += 10.0,
            4 => score += 4.0,              // half-full leftover is reusable
            5 => score -= 2.0,
            6 => score -= 6.0,
            _ => score -= 10.0,             // large residual = flexible bin
        }
    } else {
        score -= 40.0; // perfect closure
    }

    // Modulo coupling: does next_item_size fit into post_residual's harmonic slot?
    if next_item_size > 0 && post_residual >= next_item_size {
        // next item fits exactly or leaves a good class again
        let next_post = post_residual - next_item_size;
        if next_post == 0 {
            score -= 25.0;
        } else if next_post % quarter == 0 {
            score -= 15.0;
        } else if next_post <= quarter {
            score -= 5.0;
        } else {
            score += 3.0;
        }
    } else if next_item_size > 0 {
        // next item cannot use this bin's leftover: dead space risk
        score += pr * 0.15;
        if post_residual < (bin_capacity / 10) {
            score += 12.0; // tiny unusable sliver
        }
    }

    // Capacity-fraction preference: filling to exact fractions is valuable
    let filled = cap - pr;
    for frac in [1.0, 0.75, 0.5, 0.25] {
        if (filled - frac * cap).abs() < 0.5 {
            score -= 18.0;
        }
    }

    // Last-chance bin: strongly favor using it before opening a new one
    if fitting_bins_count == 1 {
        score -= 20.0;
    }

    // New-bin candidate handling: only open a new bin when current fit is poor
    if bin_residual == bin_capacity {
        // brand-new empty bin: baseline cost, adjusted by stream position and load
        let progress = step_index as f64 / total_items.max(1) as f64;
        score = 55.0 - 10.0 * progress;
        if next_item_size > 0 && next_item_size >= item_size {
            score -= 8.0; // big next item benefits from fresh bin
        }
        if fitting_bins_count == 0 {
            score -= 60.0; // forced open
        }
    } else if post_residual >= 20 {
        score -= 8.0; // existing bins with usable residual preferred
    }

    // Slight tie-break toward tighter bins when many are open
    score += (bin_residual as f64 - mean_residual) * 0.05;
    score += open_bins_count as f64 * 0.02;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap_f = bin_capacity as f64;
    let mut score = post_residual as f64;
    let progress = step_index as f64 / total_items.max(1) as f64;

    // Perfect / near-perfect fit rewards (borrowed from best).
    if post_residual == 0 {
        score -= 900.0;
    } else if post_residual <= 3 {
        score -= 350.0;
    } else if post_residual <= 12 {
        score -= 70.0;
    } else if post_residual < 20 {
        score += 14.0;
    } else if post_residual < 30 {
        score += 14.0 + (30 - post_residual) as f64 * 0.5;
    }

    // Lookahead: chain fits with next item.
    if next_item_size > 0 {
        if next_item_size as u32 == post_residual {
            score -= 700.0;
        } else if next_item_size <= post_residual {
            let post2 = post_residual - next_item_size;
            score -= 100.0 - (post2 as f64) * 2.0;
            if post2 == 0 { score -= 90.0; }
            if post2 > 0 && post2 < 5 { score -= 24.0; }
            if post2 > 0 && post2 <= next_item_size / 4 { score -= 10.0; }
            if post_residual % next_item_size == 0 { score -= 16.0; }
        } else {
            // post_residual can't hold next item: penalize small dead gaps.
            score += 18.0;
            let gap = next_item_size as f64 - post_residual as f64;
            if post_residual > 0 && gap <= 3.0 { score += 30.0; }
            if post_residual > 0 && post_residual < 15 { score += 40.0; }
            if post_residual as f64 > mean_residual * 1.4 { score -= 10.0 + progress * 8.0; }
        }
    }

    // Last-chance bonus: sole fitting bin.
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 22.0;
    }

    // Open-bin pressure: mild preference for reuse.
    score += open_bins_count as f64 * 0.4;

    // New-bin candidate logic.
    if bin_residual == bin_capacity {
        let newbin_waste = (bin_capacity - item_size) as f64;
        let avg_fill = 1.0 - (mean_residual / cap_f);
        score += 220.0 - avg_fill * 300.0 - progress * 60.0;
        if fitting_bins_count > 0 {
            score += (fitting_bins_count as f64).min(5.0) * 8.0;
            let snug = item_size as f64 / (bin_residual.max(1) as f64);
            if snug > 0.9 { score += 35.0; }
            if snug > 0.95 { score += 25.0; }
            if bin_capacity - item_size <= 4 { score -= 60.0; }
            if item_size >= bin_capacity * 3 / 4 { score -= 50.0; }
        }
        if next_item_size > 0 && next_item_size <= bin_capacity - item_size {
            let leftover = bin_capacity - item_size;
            let tail = leftover % next_item_size;
            if tail == 0 { score -= 14.0; }
            else if tail <= 4 { score -= 10.0; }
            if leftover >= next_item_size * 2 { score -= 12.0; }
        }
        if newbin_waste > 0.0 && (newbin_waste as u32) < next_item_size && newbin_waste < cap_f * 0.12 {
            score += 22.0;
        }
        if progress > 0.7 {
            let waste_tol = (1.0 - progress) * cap_f * 0.35;
            if newbin_waste > waste_tol && fitting_bins_count > 0 {
                score += 10.0 + progress * 20.0;
            }
        }
    } else {
        // Existing bin: tightness and residual shaping.
        let tightness = 1.0 - (item_size as f64 / bin_residual.max(1) as f64);
        score += tightness * 70.0;
        score += (mean_residual - bin_residual as f64) * 1.2;
        let dead_ratio = post_residual as f64 / cap_f;
        if dead_ratio < 0.03 { score -= 30.0; }
        else if dead_ratio > 0.3 { score += 20.0; }
        if post_residual > 0 && post_residual < next_item_size {
            let wasted = (next_item_size - post_residual) as f64;
            score += wasted * 0.6;
            if wasted > mean_residual * 0.6 && fitting_bins_count > 2 { score += wasted * 0.7; }
        }
        if item_size == bin_residual { score -= 40.0; }
        if post_residual > 0 && next_item_size > 0 && post_residual >= next_item_size {
            let chain = post_residual / next_item_size;
            if chain >= 2 { score -= (chain.min(4)) as f64 * 5.0; }
        }
        if fitting_bins_count <= 2 && post_residual > 0 { score -= 7.0; }
        score += dead_ratio * 25.0;
    }

    // Mild alignment with mean residual.
    score += ((post_residual as f64) - mean_residual).abs() * 0.12;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals too small for any item (1..10)
    // are pure waste; penalize them heavily, scaled by how dead they are.
    if post_residual > 0 && post_residual < 10 {
        score += (10.0 - post_residual as f64) * 12.0;
    }
    if post_residual == 0 {
        // Perfect fit: strongly reward closing the bin.
        score -= 80.0;
    }

    // Reward tight fits: small post_residual relative to item size.
    let tightness = post_residual as f64 / (item_size.max(1) as f64);
    score += tightness * 15.0;

    // Last chance bin: if this is the only bin that fits, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // Lookahead: if next item fits exactly in the post residual, reward.
    if next_item_size > 0 && post_residual >= next_item_size && post_residual - next_item_size < 10 {
        score -= 30.0;
    }
    // Penalize if next item cannot fit into post residual but would fit a fresh bin.
    if next_item_size > post_residual {
        score += 8.0;
    }

    // Open-bin pressure: with many open bins, prefer consolidating into existing bins
    // rather than opening new ones; the new-bin candidate gets penalized here.
    if bin_residual == bin_capacity {
        // New-bin candidate: only attractive when current bins are fragmented
        // (high mean residual spread / many open bins with poor fit potential).
        score = 60.0 + open_bins_count as f64 * 4.0 - mean_residual * 0.5;
        if fitting_bins_count == 0 {
            score -= 100.0; // must open a new bin
        }
        if next_item_size > 0 && next_item_size <= item_size {
            score -= 10.0; // fresh bin can host the follow-up item too
        }
    } else {
        // Existing bin: slight reward for reducing overall open-bin pressure.
        score -= open_bins_count as f64 * 0.5;
    }

    // Stream progression: late in the stream, be greedier about tight fits.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score -= progress * 10.0 * (1.0 - tightness.min(1.0));

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap_f = bin_capacity as f64;
    let progress = step_index as f64 / total_items.max(1) as f64;
    let mut score = post_residual as f64;

    // Perfect fit: dominant reward.
    if post_residual == 0 {
        score -= 1180.0;
    } else if post_residual <= 3 {
        score -= 500.0;
    } else if post_residual <= 12 {
        score -= 98.0;
    } else if post_residual < 20 {
        score += 18.0;
    } else if post_residual < 30 {
        score += 18.0 + (30 - post_residual) as f64 * 0.6;
    }

    // Lookahead chaining: reward leaving exactly room for next item.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 900.0;
        } else if next_item_size < post_residual {
            let post2 = post_residual - next_item_size;
            score -= 135.0 - post2 as f64 * 2.0;
            if post2 == 0 { score -= 110.0; }
            if post2 > 0 && post2 < 5 { score -= 28.0; }
            if post2 > 0 && post2 <= 2 { score -= 14.0; }
            if post2 > 0 && post2 <= next_item_size / 2 { score -= 8.0; }
            if post_residual % next_item_size == 0 { score -= 18.0; }
            if post_residual >= next_item_size * 2 && post_residual - next_item_size * 2 <= 4 {
                score -= 20.0;
            }
            let chain = post_residual / next_item_size;
            if chain >= 2 { score -= (chain.min(4)) as f64 * 6.0; }
        } else {
            // Next item cannot fit here: penalize dead space proportionally.
            let gap = (next_item_size - post_residual) as f64;
            score += gap * 0.8;
            if post_residual > 0 && gap <= 5.0 { score += 18.0; }
            if post_residual > 0 && post_residual < 15 { score += 45.0; }
            if post_residual > 0 && gap > mean_residual * 0.5 { score += 14.0; }
            if post_residual as f64 > mean_residual * 1.4 { score -= 12.0; }
        }
        if post_residual > 0 && post_residual < next_item_size {
            score += (1.0 - progress) * 14.0;
            let gap = next_item_size as f64 - post_residual as f64;
            if gap > 12.0 { score += gap * 0.6; }
        }
    }

    // Dead-space avoidance: residuals too small for plausible future items.
    if post_residual > 0 && (post_residual as f64) < 12.0 {
        score += (12.0 - post_residual as f64) * 5.0;
    }
    if post_residual > 0 && (post_residual as f64) < mean_residual * 0.25 {
        score -= 15.0;
    }

    // Tightness reward for near-full bins.
    if post_residual > 0 && bin_residual != bin_capacity {
        let tightness = 1.0 - (post_residual as f64) / cap_f;
        score -= tightness * tightness * 12.0;
        let dead_ratio = post_residual as f64 / cap_f;
        if dead_ratio < 0.03 { score -= 38.0; }
        else if dead_ratio < 0.08 { score -= 14.0; }
        else if dead_ratio > 0.30 { score += 18.0; }
        if item_size == bin_residual { score -= 45.0; }
        let snug = item_size as f64 / bin_residual.max(1) as f64;
        if snug > 0.97 && post_residual >= next_item_size { score -= 16.0; }
        if post_residual % 5 == 0 && post_residual <= 30 { score -= 8.0; }
        score += ((post_residual as f64) - mean_residual).abs() * 0.12;
    }

    // Last-chance bonus: only fitting open bin.
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 22.0;
    }

    // Open-bin pressure: mild reuse preference.
    score += open_bins_count as f64 * 0.4;

    // ---- New-bin candidate logic ----
    if bin_residual == bin_capacity {
        let leftover = bin_capacity - item_size;
        let newbin_waste = leftover as f64;
        let avg_fill = 1.0 - mean_residual / cap_f;
        score += 250.0 - avg_fill * 330.0 - progress * 65.0;

        if fitting_bins_count > 0 {
            score += (fitting_bins_count as f64).min(5.0) * 9.0;
            let snug = item_size as f64 / bin_residual.max(1) as f64;
            if snug > 0.9 { score += 40.0; }
            if snug > 0.95 { score += 28.0; }
            if snug > 0.98 { score += 18.0; }
            let best_alt = if item_size as f64 <= mean_residual { mean_residual - item_size as f64 } else { mean_residual };
            if newbin_waste > best_alt + cap_f * 0.08 { score += 22.0; }
            if newbin_waste > best_alt + cap_f * 0.2 { score += 14.0; }
        } else {
            // No open bin fits: opening a new bin is necessary, make it cheap.
            score -= 60.0;
        }

        // Large items pair well in fresh bins.
        if item_size >= bin_capacity * 3 / 4 { score -= 55.0; }
        if bin_capacity - item_size <= 4 { score -= 70.0; }
        if item_size as f64 / cap_f > 0.85 && mean_residual > cap_f * 0.35 { score -= 40.0; }
        if next_item_size > 0 && next_item_size >= bin_capacity / 2 { score -= 32.0; }
        if next_item_size > 0 && next_item_size <= leftover && leftover - next_item_size <= 6 { score -= 38.0; }

        // New-bin leftover compatible with next item chain.
        if next_item_size > 0 {
            if leftover >= next_item_size {
                let tail = leftover % next_item_size;
                if tail == 0 { score -= 20.0; }
                else if tail <= 4 { score -= 16.0; }
            } else if leftover < 10 {
                score += 18.0;
            }
            if leftover >= next_item_size * 2 { score -= 14.0; }
            if newbin_waste > 0.0 && (newbin_waste as u32) % next_item_size == 0 { score -= 20.0; }
        }
        // Fresh-bin waste small relative to mean residual: keep it closed.
        if newbin_waste < mean_residual * 0.5 { score -= 20.0; }
        // Late stream: be conservative, prefer reusing.
        if progress > 0.6 && newbin_waste > (1.0 - progress) * cap_f * 0.35 && fitting_bins_count > 0 {
            score += 10.0 + progress * 22.0;
        }
        if progress > 0.85 && newbin_waste > cap_f * 0.3 { score += 8.0; }
        if newbin_waste > 0.0 && next_item_size > 0 && newbin_waste < next_item_size as f64 && newbin_waste < mean_residual * 0.4 {
            score += 14.0 * (1.0 - progress);
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit reward
    if post_residual == 0 {
        score -= 200.0;
    }

    // 2-step lookahead: reward if next item fits exactly into post_residual
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 120.0;
        } else if post_residual >= next_item_size {
            // next item fits, but penalize leftover after that
            let chain_residual = post_residual - next_item_size;
            score -= 40.0 - (chain_residual as f64) * 0.5;
        } else {
            // next item won't fit here; penalize dead space that can't serve next item
            score += (next_item_size - post_residual) as f64 * 0.3;
        }
    }

    // Relative to mean residual: prefer bins tighter than average
    score += (mean_residual - bin_residual as f64) * 0.4;

    // Last-chance bonus: if this is the only fitting bin, strongly favor using it
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 150.0;
    }

    // New-bin candidate: penalize opening a new bin unless residuals are tight
    if bin_residual == bin_capacity {
        score += 30.0 + mean_residual * 0.5;
    }

    // Slight preference early in stream to keep bins open for future items
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += post_residual as f64 * progress * 0.1;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: small post_residual is good, but penalize tiny useless slivers
    if post_residual > 0 {
        let sliver = (post_residual as f64) / bin_capacity as f64;
        if sliver < 0.05 {
            score += 12.0 * (0.05 - sliver) / 0.05; // dead space penalty
        }
    } else {
        score -= 8.0; // perfect fit bonus
    }

    // Fit ratio: how well item fills the bin
    let fill = item_size as f64 / bin_residual as f64;
    score -= 20.0 * fill * fill;

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 {
        score -= 15.0;
    } else {
        // More competing bins -> slight penalty to spread usage wisely
        score += 0.5 * (fitting_bins_count as f64).min(10.0);
    }

    // Lookahead: if next item fits in post_residual, reward this placement
    if next_item_size > 0 {
        if (next_item_size as u32) <= post_residual {
            score -= 10.0;
            // extra reward if next item nearly fills what remains
            let next_fill = next_item_size as f64 / post_residual as f64;
            score -= 6.0 * next_fill;
        } else if next_item_size as u32 > post_residual + 5 {
            // next item won't fit here anyway; neutral-ish, slight penalty for wasting space
            score += 3.0 * (1.0 - post_residual as f64 / bin_capacity as f64);
        }
    } else {
        // Last item: just minimize leftover
        score += 0.0;
    }

    // Time horizon: early in stream, be more willing to open new bins (favor good fits),
    // late in stream, consolidate into existing bins
    let progress = step_index as f64 / (total_items.max(1) as f64);
    if bin_residual == bin_capacity {
        // New-bin candidate: accept early, penalize late unless existing fits are bad
        score += 10.0 * progress;
        if mean_residual > item_size as f64 * 1.5 {
            score += 8.0; // there's room elsewhere; opening new bin is wasteful
        }
    } else {
        score -= 4.0 * progress; // consolidation pressure over time
    }

    // Global state: many open bins with large mean residual -> prefer filling existing bins
    if open_bins_count > 3 {
        let pressure = (open_bins_count as f64).ln();
        score -= pressure * (mean_residual / bin_capacity as f64) * 5.0;
    }

    // Prefer bins whose residual is close to item size (efficient pairing)
    let gap = (bin_residual as f64 - item_size as f64) / bin_capacity as f64;
    score += 15.0 * gap * gap;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let score = post_residual as f64 / bin_capacity.max(1) as f64;
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let t = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let prn = pr / cap;
    let is_new_bin = (bin_residual as f64 - cap).abs() < 0.5;

    // Smooth non-linear coupling of post_residual with stream progress
    score += 6.0 * prn * prn * (1.0 - t) * (1.0 - t);
    score -= 10.0 * prn * (1.0 - prn) * t * (1.0 - t);
    score += 4.0 * prn.powi(3) * t;

    // Reward tight fits, stronger late in the stream
    let tightness = 1.0 - prn;
    score -= 12.0 * tightness * tightness * (0.5 + t);

    // Penalize dead space relative to mean residual (smooth interaction)
    score += 3.0 * (pr - mean_residual).abs() / cap * (1.0 + t);

    // Last-chance bonus: strongly favor using the only fitting bin
    if fitting_bins_count == 1 && !is_new_bin {
        score -= 25.0 * (1.0 - prn);
    }

    // New-bin candidate: prefer it only when post-residual is large and stream is early
    if is_new_bin {
        score += 8.0 * (1.0 - t) - 15.0 * prn * t;
        // discourage new bin if next item could share residual space
        let ns = next_item_size as f64;
        if ns > 0.0 && pr >= ns {
            score += 6.0 * (1.0 - ns / cap) * (0.5 + t);
        }
    }

    // Lookahead: reward bins whose leftover can host the next item
    if next_item_size > 0 && !is_new_bin {
        let ns = next_item_size as f64;
        if pr >= ns {
            let fit_quality = 1.0 - (pr - ns) / cap;
            score -= 8.0 * fit_quality * fit_quality;
        } else {
            score += 2.0 * (ns - pr) / cap;
        }
    }

    // Mild penalty for proliferating bins early
    score += 0.15 * open_bins_count as f64 * (1.0 - t);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: bins whose post-residual falls into
    // "small" residue classes (<= 10) are nearly perfect fits -> reward heavily.
    let dead = post_residual as f64;
    if post_residual == 0 {
        score -= 1000.0; // perfect fill
    } else if post_residual <= 10 {
        score -= 60.0 + (10 - post_residual) as f64 * 8.0;
    } else if post_residual <= 20 {
        score -= 15.0;
    } else {
        // penalize large dead space, quadratically in the tail
        score += (dead - 20.0) * 0.35 + (dead * dead) / (bin_capacity as f64 * 4.0);
    }

    // Modulo coupling: post_residual that is a multiple of a likely small-item
    // size (10, 20, 25, 50) leaves re-usable space -> reward.
    let pr = post_residual;
    if pr > 0 && (pr % 10 == 0 || pr % 25 == 0 || pr % 50 == 0) {
        score -= 12.0;
    }

    // Lookahead: if next item fits exactly in post_residual, big reward.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 500.0;
        } else if next_item_size < post_residual {
            // reward proportional to how snugly the next item fits
            let slack = (post_residual - next_item_size) as f64;
            score -= 40.0 * (1.0 - slack / bin_capacity as f64);
            // harmonic bonus if next item also leaves a multiple-of-10 residue
            let nr = post_residual - next_item_size;
            if nr > 0 && nr % 10 == 0 {
                score -= 20.0;
            }
        } else {
            // next item cannot use this bin's residue: mild penalty if residue small
            if post_residual < 10 {
                score += 10.0;
            }
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 80.0;
    }

    // Tightness reward: prefer bins where item fills a large fraction.
    let fill_frac = item_size as f64 / bin_residual.max(1) as f64;
    score -= 30.0 * fill_frac;

    // Prefer fuller bins over emptier ones beyond post_residual itself.
    score -= (bin_capacity as f64 - bin_residual as f64) * 0.05;

    // New-bin candidate: only attractive when no open bin fits well.
    if bin_residual == bin_capacity {
        // base cost of opening a new bin
        score += 90.0;
        // cheaper to open a new bin early in the stream or when open bins are crowded
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score -= 25.0 * (1.0 - progress);
        if open_bins_count == 0 {
            score -= 500.0;
        }
        if fitting_bins_count == 0 {
            score -= 300.0;
        }
        // if next item is large, having a fresh bin helps
        if next_item_size >= 60 {
            score -= 15.0;
        }
    }

    // Mild preference for bins below mean residual (keeps spread balanced)
    score += (bin_residual as f64 - mean_residual) * 0.03;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals too small for any item (min size 1,
    // but treat gaps < 12 as likely unusable) are heavily penalized.
    if post_residual > 0 && post_residual < 12 {
        score += 60.0;
    }
    // Perfect fits are strongly rewarded.
    if post_residual == 0 {
        score -= 40.0;
    }

    // Reward tight fits relative to bin capacity.
    score -= (item_size as f64 / bin_capacity as f64) * 15.0;

    // Lookahead coupling: if the next item fits exactly in the post residual,
    // strongly favor this bin; penalize if post residual just barely misses it.
    if next_item_size > 0 {
        if post_residual >= next_item_size && post_residual - next_item_size < 12 {
            score -= 25.0;
        } else if post_residual < next_item_size && post_residual > 0 {
            score += 8.0;
        }
    }

    // Last-chance pressure: if this is the only bin that fits, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // Open-bin pressure: many open bins -> prefer filling existing ones.
    score += (open_bins_count as f64) * 2.0;

    // Mean residual coupling: penalize bins with residual far below the mean
    // when mean residual is large (they hoard scarce large space).
    if mean_residual > 30.0 && (bin_residual as f64) < mean_residual * 0.5 {
        score += 10.0;
    }

    // New-bin candidate: opening a fresh bin should be a last resort.
    if bin_residual == bin_capacity {
        score += 45.0 + (open_bins_count as f64) * 0.5;
        // But allow a new bin for very large items that would leave bad gaps anywhere.
        if item_size > 70 {
            score -= 20.0;
        }
    }

    score
}
